package com.clockwork;

import com.clockwork.core.AlertStyle;
import com.clockwork.core.Overridable;
import com.clockwork.core.Routine;
import com.clockwork.diag.Diagnostics;
import com.clockwork.overlay.OverlayCoordinator;
import com.clockwork.overlay.RoutineOverlay;
import com.clockwork.overlay.ScreenFlashOverlay;
import java.awt.Color;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.Notifier;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.Notification;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * What happens at the moment a clock finishes or a countdown reaches zero.
 *
 * <h2>Three questions, and why it is three rather than one</h2>
 *
 * <p>What it draws, which is one answer out of three, whether it chimes, and
 * whether it asks RuneLite to notify. The drawn answer is a flash on the
 * clock's own timer box, a flash across the whole screen, or nothing, and it is
 * a single answer because a user choosing between two flashes is choosing one
 * of them. The other two are each a yes or a no of their own, because a user
 * who wants a flash and a sound wants both, and a user who wants a flash and a
 * notification wants both as well. Folding either of them into the drawn answer
 * would be a setting that cannot say what a user is allowed to want.
 *
 * <p>The chime is played directly rather than through the notification system,
 * which is what lets it be heard while the client has focus.
 *
 * <p>The notification is the alt tabbed path and nothing more, and it is the
 * reason the two flashes exist. {@code Notifier} takes the notification,
 * posts the event, and then returns without doing anything else when the client
 * has focus and the notification does not say to send anyway. Whether it says
 * so is read off the notification itself, so a user who ticks Override on this
 * plugin's own notification item and turns Send when focused on does get one
 * while playing, and a user who leaves it alone gets RuneLite's default, which
 * is not to. A plugin whose only alert was the notification would therefore
 * look broken to the ordinary user at the one moment the alert is for. So the
 * flash and the chime carry it, the flash is what a new user gets, and every
 * place that offers the notification says this out loud.
 *
 * <p>All three questions are per clock. A clock carries its own
 * {@link com.clockwork.core.AlertOverride} for the drawn half and a
 * {@link com.clockwork.core.Toggle} each for the chime and the notification,
 * and all three are read separately, so any clock can draw nothing and still
 * chime, flash and be announced as well, or do none of it. Each per clock
 * setting starts on use global and falls back to the plugin wide one there,
 * which means the globals are the default rather than a gate, and a clock that
 * says on is heard while the global says off.
 *
 * <p>The global the notification falls back to is the enabled tick on this
 * plugin's own notification item. How that notification then behaves stays
 * plugin wide, because it is a single channel shared by the whole client and
 * RuneLite already gives the user its own override on it. See
 * {@link #notifyIfAsked} for the one wrinkle that comes of a global that is an
 * object rather than a boolean.
 *
 * <p>A countdown does one thing more, which is to count the last three seconds
 * in. Three beats of a shorter clip on the way to the chime the moment above
 * plays, read off the same per clock chime setting and the same volume, so it
 * is the chime arriving early rather than a channel with an answer of its
 * own. A clock that is silent is counted in silently, which is to say not at
 * all. The controller decides when a beat is due and this plays it, which is
 * why there is no timing in here.
 *
 * <p>It owns the flash window, because a flash is bounded in time and somebody
 * has to end it. The refresh loop asks {@link #expire(long)} to do that, and
 * reads {@link #getFlashingRoutineId()} and {@link #getFlashUntilMillis()} so
 * the box that is mid alert keeps drawing even though the clock behind it has
 * stopped.
 */
@Slf4j
public class Alerts
{
	/**
	 * The chime, as it sits in the plugin jar beside the icon. Read through
	 * {@code AudioPlayer}, which opens it with {@code getResourceAsStream}, so
	 * it is a classpath resource rather than a file and works from inside the
	 * packed jar the hub ships.
	 */
	private static final String SOUND_RESOURCE = "complete.wav";

	/**
	 * The shorter clip the last three seconds of a countdown are counted in
	 * with, read the same way and from beside it in the same jar.
	 */
	private static final String COUNT_IN_RESOURCE = "beep.wav";

	/**
	 * A hundred percent, in the units the volume setting is written in.
	 */
	private static final double FULL_VOLUME = 100d;

	private final Plugin plugin;
	private final Client client;
	private final ClockworkConfig config;
	private final OverlayManager overlayManager;
	private final OverlayCoordinator overlays;
	private final Notifier notifier;
	private final ClientThread clientThread;
	private final AudioPlayer audioPlayer;
	private final Diagnostics diagnostics;

	/**
	 * Puts the refresh back on its fast period, because a flash that blinks
	 * more than twice a second is not visible on a slow one.
	 */
	private final Runnable wake;

	private ScreenFlashOverlay screenFlashOverlay;

	private long flashUntilMillis;
	private String flashingRoutineId;

	public Alerts(Plugin plugin, Client client, ClockworkConfig config, OverlayManager overlayManager,
		OverlayCoordinator overlays, Notifier notifier, ClientThread clientThread, AudioPlayer audioPlayer,
		Diagnostics diagnostics, Runnable wake)
	{
		this.plugin = plugin;
		this.client = client;
		this.config = config;
		this.overlayManager = overlayManager;
		this.overlays = overlays;
		this.notifier = notifier;
		this.clientThread = clientThread;
		this.audioPlayer = audioPlayer;
		this.diagnostics = diagnostics == null ? Diagnostics.none() : diagnostics;
		this.wake = wake;
	}

	/**
	 * Puts the screen flash on the overlay manager. One instance for the whole
	 * plugin, because it is not tied to a clock and it draws nothing until an
	 * alert asks it to.
	 */
	public void startUp()
	{
		screenFlashOverlay = new ScreenFlashOverlay(plugin, client, diagnostics);
		overlayManager.add(screenFlashOverlay);
	}

	/**
	 * Takes it back off. Stopping a plugin never touches the overlay manager,
	 * so one left behind would keep drawing over the game with the plugin
	 * showing as off.
	 */
	public void shutDown()
	{
		if (screenFlashOverlay != null)
		{
			overlayManager.remove(screenFlashOverlay);
			screenFlashOverlay = null;
		}
		flashUntilMillis = 0;
		flashingRoutineId = null;
	}

	/**
	 * Draws the alert, plays the chime, and, separately from both, asks
	 * RuneLite to notify. See the note on this class for why it is all three.
	 *
	 * <p>Called on the event dispatch thread, from the listener callbacks the
	 * controller fires.
	 *
	 * <p>The drawn half is one of three answers and the other two are each a
	 * yes or a no, resolved one after another, and none of them reads another's
	 * answer. That is what makes every combination of the three reachable on
	 * any clock.
	 */
	public void alert(Routine routine, String message)
	{
		// The clock's own setting wins, and falls back to the plugin wide one
		// when it is left on use global, which is where every clock starts.
		final AlertStyle style = Overridable.resolve(routine.getAlert(), config.alertStyle());
		final long until = System.currentTimeMillis() + config.alertSeconds() * 1000L;
		final Color color = config.alertColor();

		clearFlash();

		if (style == AlertStyle.TIMER_BOX)
		{
			// Null when this clock has no box on screen, which is what the
			// timer box setting turned to never looks like from here. The
			// user asked for no box and does not get one conjured for an
			// alert, so the chime and the notification are what is left.
			final RoutineOverlay overlay = overlays.overlay(routine.getId());
			if (overlay != null)
			{
				overlay.flash(until, color);
				flashUntilMillis = until;
				flashingRoutineId = routine.getId();
			}
		}
		else if (style == AlertStyle.SCREEN && screenFlashOverlay != null)
		{
			screenFlashOverlay.flash(until, color);
			flashUntilMillis = until;
			flashingRoutineId = routine.getId();
		}

		if (flashUntilMillis > 0)
		{
			wake.run();
		}

		// Independently of the flash above. The clock's own setting wins here
		// too, so a clock that draws nothing can still chime and a clock that
		// flashes can stay silent, whichever way the plugin wide settings are
		// left. The global is the fallback rather than a gate over it.
		if (Overridable.resolve(routine.getSound(), config.playSound()))
		{
			playSound(SOUND_RESOURCE);
		}

		notifyIfAsked(routine, message);
	}

	/**
	 * Hands the finished run to RuneLite, for the clocks that asked for that.
	 *
	 * <p>Read the same way the flash and the chime are and after both of them,
	 * so it is a third answer beside them rather than one of the drawn ones.
	 * The clock's own setting wins, and a clock left on use global falls back
	 * to the plugin wide one.
	 *
	 * <p>That plugin wide one is an object rather than a boolean, which is the
	 * whole of what is unusual here. The enabled tick on the item is the half
	 * of it that means yes or no, so that is the half the fallback reads.
	 *
	 * <p>{@code Notifier} returns straight back out on a notification that is
	 * not enabled, so a clock that said on while the tick is off would be
	 * asking for something and quietly getting nothing. The copy that goes out
	 * therefore carries the tick turned on. It is a copy, the user's own item is
	 * untouched, and every other field on it travels exactly as it was left,
	 * including Override and Send when focused. What the tick then means is what
	 * the plugin wide chime setting already means, which is the default for the
	 * clocks that have not answered for themselves.
	 */
	private void notifyIfAsked(Routine routine, String message)
	{
		final Notification notification = config.notification();
		if (!Overridable.resolve(routine.getNotify(), notification.isEnabled()))
		{
			return;
		}

		// The notifier reads whether the client has focus, so it is called from
		// the client thread rather than from Swing.
		clientThread.invoke(() -> notifier.notify(notification.withEnabled(true), message));
	}

	/**
	 * Ends whatever is on screen now. Called when a run starts or is cancelled,
	 * so the alert for the last run is not still blinking over the next one.
	 */
	public void clearFlash()
	{
		flashUntilMillis = 0;
		flashingRoutineId = null;
		overlays.clearFlashes();
		if (screenFlashOverlay != null)
		{
			screenFlashOverlay.clearFlash();
		}
	}

	/**
	 * Ends a flash that has run its course. Called from the refresh.
	 */
	public void expire(long now)
	{
		if (flashUntilMillis > 0 && now >= flashUntilMillis)
		{
			clearFlash();
		}
	}

	/**
	 * Whether an alert is still on screen. The refresh stays on its fast period
	 * while this is true, because the flash blinks.
	 */
	public boolean isFlashing()
	{
		return flashUntilMillis > 0;
	}

	public long getFlashUntilMillis()
	{
		return flashUntilMillis;
	}

	/**
	 * The clock whose box is mid alert, or null. The overlays read it so that a
	 * box kept only while its clock runs stays on screen long enough to finish
	 * blinking.
	 */
	public String getFlashingRoutineId()
	{
		return flashingRoutineId;
	}

	/**
	 * One beat of the count in, at three, two, and one second left on a
	 * countdown.
	 *
	 * <p>Called on the event dispatch thread from the same listener block the
	 * alert above arrives on, once per beat, so it is three plays on the way
	 * into a chime rather than anything on the refresh tick itself.
	 *
	 * <p>It reads the clock's own chime setting through the same resolve the
	 * alert uses, so a clock that is silent stays silent and a clock that
	 * chimes on a plugin wide setting that is off is counted in as well. The
	 * count in is part of the chime rather than a channel beside it, which is
	 * why there is nothing else here to decide.
	 */
	public void countIn(Routine routine)
	{
		if (routine == null)
		{
			return;
		}

		if (Overridable.resolve(routine.getSound(), config.playSound()))
		{
			playSound(COUNT_IN_RESOURCE);
		}
	}

	/**
	 * Plays one of the bundled clips. This deliberately does not go through the
	 * notification system, which is what lets it be heard while the client has
	 * focus. Each clip is a few kilobytes read out of the plugin jar, so it is
	 * cheap enough to open where it is asked for.
	 *
	 * <p>Whether to play at all was settled by the caller. The volume read here
	 * is how loud rather than whether, and it stays plugin wide, so a user who
	 * has dragged it to zero has asked for silence on every clock and for every
	 * clip.
	 *
	 * @param resource the clip to play, as it sits in the jar
	 */
	private void playSound(String resource)
	{
		final int volume = config.soundVolume();
		if (volume <= 0)
		{
			return;
		}

		// The player takes a gain in decibels, so a percentage has to be bent
		// into one. A hundred percent is unchanged, and quieter settings fall
		// away on a curve that sounds even.
		final float gain = (float) (20d * Math.log10(Math.min(FULL_VOLUME, volume) / FULL_VOLUME));

		try
		{
			audioPlayer.play(ClockworkPlugin.class, resource, gain);
		}
		catch (Exception ex)
		{
			// A headless machine, a busy sound card, or a user with no audio
			// device at all. None of them is worth more than a debug line, and
			// none of them may take the run that just finished with it.
			log.debug("could not play the clockwork clip {}", resource, ex);
			diagnostics.record("alerts.playSound", ex);
		}
	}
}

package com.clockwork;

import com.clockwork.core.AlertStyle;
import com.clockwork.core.OverlayMode;
import com.clockwork.core.RunHistory;
import com.clockwork.core.SubSecond;
import java.awt.Color;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(ClockworkConfig.GROUP)
public interface ClockworkConfig extends Config
{
	String GROUP = "clockwork";

	@ConfigSection(
		name = "Display",
		description = "How the timer reads on screen",
		position = 0
	)
	String displaySection = "display";

	@ConfigSection(
		name = "Alerts",
		description = "What happens when a clock finishes or a countdown reaches zero",
		position = 1
	)
	String alertSection = "alert";

	@ConfigSection(
		name = "Hotkeys",
		description = "Keys that start, stop, and lap a clock without the side panel. Designate which clock they act on from the ... menu on its card.",
		position = 2
	)
	String hotkeySection = "hotkeys";

	@ConfigSection(
		name = "Triggers",
		description = "Help for setting up a clock that starts or stops itself",
		position = 3,
		closedByDefault = true
	)
	String triggerSection = "triggers";

	@ConfigItem(
		keyName = "showHours",
		name = "Hours",
		description = "Show an hours field. It only appears once a run passes one hour, and it never wraps.",
		section = displaySection,
		position = 0
	)
	default boolean showHours()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showMinutes",
		name = "Minutes",
		description = "Show a minutes field. With this off the seconds field carries the whole run.",
		section = displaySection,
		position = 1
	)
	default boolean showMinutes()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showSeconds",
		name = "Seconds",
		description = "Show a seconds field",
		section = displaySection,
		position = 2
	)
	default boolean showSeconds()
	{
		return true;
	}

	@ConfigItem(
		keyName = "precision",
		name = "Sub-second precision",
		description = "How many fractional digits the timer shows",
		section = displaySection,
		position = 3
	)
	default SubSecond precision()
	{
		return SubSecond.TENTHS;
	}

	@ConfigItem(
		keyName = "fontSize",
		name = "Timer size",
		description = "How big the timer is drawn in the in-game box. The clock's"
			+ " name above it stays the same size.",
		section = displaySection,
		position = 4
	)
	@Range(min = 8, max = 72)
	@Units(" pt")
	default int fontSize()
	{
		return 24;
	}

	@ConfigItem(
		keyName = "showPbDelta",
		name = "Show best time delta",
		description = "Show how far ahead or behind the personal best the run is. A clock can override this in its own settings.",
		section = displaySection,
		position = 4
	)
	default boolean showPbDelta()
	{
		return true;
	}

	@ConfigItem(
		keyName = "averageWindow",
		name = "Average over",
		description = "How many of your most recent runs the average is taken from. Abandoned runs among them are left out. A clock keeps its newest ten runs, so ten is as far back as this can reach, and the all time average on the card answers for everything before that.",
		section = displaySection,
		position = 5
	)
	// The maximum is the number of recent runs a clock keeps, rather than a
	// number of its own, because a window past that has nothing behind it. It
	// used to go to fifty, which was the old flat cap, and a stored value above
	// the new maximum is brought down at start up so the panel never shows a
	// figure the plugin will not honour.
	@Range(min = 1, max = RunHistory.RECENT_KEPT)
	@Units(" runs")
	default int averageWindow()
	{
		return RunHistory.RECENT_KEPT;
	}

	@ConfigItem(
		keyName = "overlayVisibility",
		name = "Timer boxes",
		description = "When a clock's timer box is on screen in the game window, so a run can be read without opening the side panel. Always show keeps an idle box there, reading the last run that clock recorded. Drag a box where you want it and it stays there. A clock can override this in its own settings.",
		section = displaySection,
		position = 6
	)
	default OverlayMode overlayVisibility()
	{
		return OverlayMode.WHILE_RUNNING;
	}

	@ConfigItem(
		keyName = "alertStyle",
		name = "Alert style",
		description = "What is drawn when a clock finishes or a countdown reaches zero. Flash the timer needs that clock to have a timer box, so it does nothing for a clock whose boxes are turned off. Flash the screen does not. The chime and the notification below are separate settings, so a clock set to None here can still do either. A clock can override this in its own settings.",
		section = alertSection,
		position = 0
	)
	default AlertStyle alertStyle()
	{
		return AlertStyle.TIMER_BOX;
	}

	@ConfigItem(
		keyName = "alertSeconds",
		name = "Alert length",
		description = "How long the flash stays on screen",
		section = alertSection,
		position = 1
	)
	@Range(min = 1, max = 30)
	@Units(Units.SECONDS)
	default int alertSeconds()
	{
		return 5;
	}

	@Alpha
	@ConfigItem(
		keyName = "alertColor",
		name = "Alert colour",
		description = "Colour of the flash. Leave some transparency in it if you flash the screen.",
		section = alertSection,
		position = 2
	)
	default Color alertColor()
	{
		return new Color(255, 0, 0, 90);
	}

	@ConfigItem(
		keyName = "playSound",
		name = "Play a sound",
		description = "Play a short bundled chime. It is played straight rather than through the notification system, so it is heard whether or not the client has focus. A clock can override this in its own settings, separately from the alert style above, so a clock can chime while the rest are silent or draw nothing and still chime.",
		section = alertSection,
		position = 3
	)
	default boolean playSound()
	{
		return false;
	}

	@ConfigItem(
		keyName = "soundVolume",
		name = "Sound volume",
		description = "Volume of the bundled chime",
		section = alertSection,
		position = 4
	)
	@Range(min = 0, max = 100)
	@Units(Units.PERCENT)
	default int soundVolume()
	{
		return 60;
	}

	@ConfigItem(
		keyName = "countIn",
		name = "Count the last seconds in",
		description = "Beep at three, two, and one second left on a countdown, before the chime at zero. It follows the chime setting above and the same volume, so a clock that does not chime is not counted in either, and it never fires on a clock that counts up.",
		section = alertSection,
		position = 5
	)
	default boolean countIn()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notification",
		name = "Notification",
		description = "Fire a RuneLite notification when a clock finishes, as well as whatever the alert style draws. It is a setting of its own rather than one of the alert styles, so a clock can flash and be notified. A clock can override it in its own settings, on or off, and that answer wins over the tick here. RuneLite holds a notification back while the client has focus, so on its own this one says nothing at the moment you are watching the game. Tick Override on it and turn Send when focused on if you want it either way.",
		section = alertSection,
		position = 6
	)
	default Notification notification()
	{
		return Notification.ON;
	}

	@ConfigItem(
		keyName = "startHotkey",
		name = "Start",
		description = "Starts a clock. It acts on the clock you designate, otherwise on the running clock when exactly one is running, otherwise on the clock selected in the side panel, otherwise on the built in Quick clock. Designate one from the ... menu on its card, and it sticks across restarts.",
		section = hotkeySection,
		position = 0
	)
	default Keybind startHotkey()
	{
		return new Keybind(KeyEvent.VK_S, InputEvent.CTRL_DOWN_MASK | InputEvent.ALT_DOWN_MASK);
	}

	@ConfigItem(
		keyName = "stopHotkey",
		name = "Stop",
		description = "Stops a clock and files the run. Same target as the start key.",
		section = hotkeySection,
		position = 1
	)
	default Keybind stopHotkey()
	{
		return new Keybind(KeyEvent.VK_P, InputEvent.CTRL_DOWN_MASK | InputEvent.ALT_DOWN_MASK);
	}

	@ConfigItem(
		keyName = "lapHotkey",
		name = "Lap",
		description = "Takes a split on a clock that has splits switched on. Same target as the start key.",
		section = hotkeySection,
		position = 2
	)
	default Keybind lapHotkey()
	{
		return new Keybind(KeyEvent.VK_L, InputEvent.CTRL_DOWN_MASK | InputEvent.ALT_DOWN_MASK);
	}

	@ConfigItem(
		keyName = "logMenuClicks",
		name = "Show me what I click",
		description = "Prints the option and the target of every menu entry you click into the chat box, worded exactly as Clockwork reads them, so you can copy the wording straight into a click trigger. This is a setup aid rather than a feature. It prints on every single click, so turn it back off once you have what you need.",
		section = triggerSection,
		position = 0
	)
	default boolean logMenuClicks()
	{
		return false;
	}
}

package com.clockwork;

import com.clockwork.core.Routine;
import com.clockwork.core.RoutineMigration;
import com.clockwork.core.SavedTrigger;
import com.clockwork.core.Trigger;
import com.clockwork.core.TriggerLibrary;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.UUID;

/**
 * Clocks as a document somebody can read, share, edit, and hand back.
 *
 * <p>The document is the saved state. Same {@code version}, {@code routines},
 * and {@code triggers}, same Gson, same shape, so there is no second format to
 * keep in step. What an export leaves out it leaves out by not being there,
 * rather than by a rule written twice.
 *
 * <h2>What is deliberately not in it</h2>
 *
 * <ul>
 *   <li>The recorded runs. They live under a config key of their own and the
 *   field is transient, so Gson never writes them. Somebody's personal bests
 *   are not part of a clock's settings and should not travel with them</li>
 *   <li>The clock id. It is kept in storage, because the in game timer box
 *   remembers where it was dragged to by id and dropping it would move every
 *   box back to the middle of the screen. In a shared document it is a string
 *   that means nothing to the reader, so the export copies each clock and nulls
 *   it, and Gson omits nulls. An import gives every clock a fresh one</li>
 *   <li>Trigger library entries nothing in the document waits for. A document
 *   carries the triggers its clocks name and no others, so importing one clock
 *   does not import somebody's whole library</li>
 * </ul>
 *
 * <h2>The two ways a document comes back in</h2>
 *
 * <p>An import adds. Every clock in the document becomes a new clock with a
 * fresh id, and nothing the user already had is touched.
 *
 * <p>An applied edit replaces. It is for the user editing their own clocks as
 * text, so clocks are matched by name, a name that is not there is added, and
 * an existing clock the document does not mention is removed. Both are worked
 * out first and handed back as a plan, so the panel can say what is about to
 * happen before any of it happens.
 *
 * <p>Matching by name is what makes an applied edit useful and it is also its
 * one sharp edge. Renaming a clock inside the document reads as "delete that
 * one, add this one", so the renamed clock arrives with no runs. Renaming
 * through the panel is not affected, because that keeps the id.
 *
 * <h2>Why this reads the document itself</h2>
 *
 * <p>{@link ClockworkStorage} takes a damaged blob apart the same way and says
 * what it lost in the log. That is right for the config it loads at start up,
 * where the user is not present and the alternative is a plugin with no clocks.
 * It is the wrong answer for a document somebody just pasted, where a clock
 * that quietly did not arrive is a clock they will look for later and not find.
 * Same shape of work, different jobs, so the reading here reports every loss as
 * a {@link DocumentProblem} and the salvage over there stays a matter for the
 * log alone.
 */
public final class ClockworkDocument
{
	/**
	 * Where the clocks sit in the document, which is the key the saved state
	 * uses because the document is the saved state.
	 */
	private static final String ROUTINES = "routines";

	private static final String TRIGGERS = "triggers";

	/**
	 * What to say about something that is valid JSON, or not even that, and is
	 * in any case nothing to do with clocks. It names the shape rather than the
	 * fault, because somebody who pasted the wrong thing entirely does not need
	 * a parser's opinion, they need to know what should have been there.
	 */
	private static final String NOT_A_DOCUMENT =
		"That is not a Clockwork document. A Clockwork document is a JSON object"
			+ " with a version and a list of clocks in it.";

	private ClockworkDocument()
	{
	}

	// Writing

	/**
	 * Every clock the user has, as a document.
	 */
	public static String exportAll(Gson gson, List<Routine> routines, TriggerLibrary library)
	{
		return write(gson, routines, library);
	}

	/**
	 * One clock, carrying only the saved triggers that clock actually waits
	 * for.
	 */
	public static String exportOne(Gson gson, Routine routine, TriggerLibrary library)
	{
		return write(gson, routine == null
			? Collections.emptyList()
			: Collections.singletonList(routine), library);
	}

	private static String write(Gson gson, List<Routine> routines, TriggerLibrary library)
	{
		final TriggerLibrary held = library == null ? TriggerLibrary.empty() : library;
		final List<Routine> copies = new ArrayList<>();

		// Kept by the library's own spelling of the name, in the order the
		// clocks name them, so the document reads in a stable order.
		final Map<String, SavedTrigger> wanted = new LinkedHashMap<>();

		if (routines != null)
		{
			for (Routine routine : routines)
			{
				if (routine == null)
				{
					continue;
				}

				final Routine copy = routine.copy();
				copy.setId(null);
				copy.setStartTrigger(exportable(held, routine.getStartTrigger(), wanted));
				copy.setLapTrigger(exportable(held, routine.getLapTrigger(), wanted));
				copy.setStopTrigger(exportable(held, routine.getStopTrigger(), wanted));
				copies.add(copy);
			}
		}

		final ClockworkStorage.SavedState state = new ClockworkStorage.SavedState();
		state.version = RoutineMigration.CURRENT_VERSION;
		state.minVersion = RoutineMigration.MINIMUM_READER_VERSION;
		state.routines = copies;
		state.triggers = new ArrayList<>(wanted.values());

		return gson.newBuilder().setPrettyPrinting().create().toJson(state);
	}

	/**
	 * The trigger as the document should carry it, noting the library entry it
	 * needs along the way.
	 *
	 * <p>A reference naming an entry that is not in the library is written out
	 * as Nothing, because Nothing is what that clock already does. Carrying the
	 * dangling name instead would produce a document that this plugin's own
	 * import refuses, which is a strange thing to hand somebody.
	 */
	private static Trigger exportable(TriggerLibrary library, Trigger trigger, Map<String, SavedTrigger> wanted)
	{
		final Trigger held = Trigger.orNothing(trigger);
		final String ref = held.getRef();
		if (ref == null)
		{
			return held;
		}

		final SavedTrigger entry = library.byName(ref);
		if (entry == null)
		{
			return Trigger.nothing();
		}

		wanted.put(entry.key(), entry);
		return Trigger.saved(entry.getName());
	}

	// Reading

	/**
	 * What importing this document would do. Nothing is changed by asking.
	 *
	 * <p>The user's own clocks are not a parameter because an import never
	 * looks at them. It adds, and every clock it adds gets a fresh id, so there
	 * is nothing to collide with.
	 *
	 * @param library the trigger library the user already has, which an import
	 * adds to and never overwrites
	 */
	public static Imported read(Gson gson, String json, TriggerLibrary library)
	{
		final Parsed parsed = parse(gson, json);
		if (parsed.refused)
		{
			return new Imported(true, parsed.problems, null, null, null);
		}

		final Merge merge = merge(parsed, library);
		final List<Routine> added = new ArrayList<>();
		for (Routine routine : parsed.routines)
		{
			final Routine copy = routine.copy();
			copy.setId(newId());
			added.add(copy);
		}

		return new Imported(false, parsed.problems, added, merge.library, merge.notes);
	}

	/**
	 * What applying this document as the user's own clock list would do.
	 * Nothing is changed by asking, which is the point, because this one can
	 * remove clocks and the user should see which before it happens.
	 */
	public static Applied readEdited(Gson gson, String json, List<Routine> existing, TriggerLibrary library)
	{
		final Parsed parsed = parse(gson, json);
		if (parsed.refused)
		{
			return new Applied(true, parsed.problems, null, null, null, null, null);
		}

		final Merge merge = merge(parsed, library);
		final List<String> notes = merge.notes;

		final Map<String, Routine> byName = new LinkedHashMap<>();
		if (existing != null)
		{
			for (Routine routine : existing)
			{
				if (routine != null)
				{
					byName.putIfAbsent(key(routine.getName()), routine);
				}
			}
		}

		final List<Routine> result = new ArrayList<>();
		final List<String> added = new ArrayList<>();
		final Set<String> matched = new HashSet<>();

		for (Routine incoming : parsed.routines)
		{
			final String name = key(incoming.getName());
			final Routine existingClock = byName.get(name);
			final Routine copy = incoming.copy();

			if (existingClock != null && matched.add(name))
			{
				// The id is kept, so the runs stay attached and the timer box
				// stays where it was dragged to. That is the whole reason this
				// is a different operation from an import.
				copy.setId(existingClock.getId());
				copy.setHistory(existingClock.getHistory());

				// And the lifetime count, which is the one part of a clock that
				// cannot be rebuilt from the runs. Carrying the runs and not
				// this would leave the clock counted again from the handful
				// that survived the cap, so a user who edited their clocks as
				// text would find an all time average over twenty runs where
				// they had one over hundreds, with nothing said about it.
				copy.setTotals(existingClock.getTotals());
				if (existingClock.isBuiltIn())
				{
					copy.setName(Routine.QUICK_NAME);
				}
			}
			else
			{
				if (existingClock != null)
				{
					notes.add("The document has more than one clock called " + incoming.getName()
						+ ". The first one keeps the existing clock's runs, the rest arrive as new clocks.");
				}
				copy.setId(newId());
				added.add(copy.getName());
			}
			result.add(copy);
		}

		final List<String> removed = new ArrayList<>();
		for (Map.Entry<String, Routine> entry : byName.entrySet())
		{
			if (matched.contains(entry.getKey()))
			{
				continue;
			}

			final Routine going = entry.getValue();
			if (going.isBuiltIn())
			{
				// The built in clock is always there and cannot be deleted, so
				// saying it would be removed would be a lie. It is put back at
				// the front, which is where it lives anyway.
				result.add(0, going);
				notes.add("The document does not mention " + Routine.QUICK_NAME
					+ ", which is the built in clock and cannot be removed, so it is left as it is.");
				continue;
			}
			removed.add(going.getName());
		}

		return new Applied(false, parsed.problems, result, merge.library, removed, added, notes);
	}

	/**
	 * Folds the document's trigger library into the user's, and repoints the
	 * document's clocks at wherever each entry landed.
	 *
	 * <p>Two rules, and they are the two an import has to get right. A name
	 * already in the user's library, asking for the same click, is the same
	 * idea arriving twice, so the entry already there is reused and nothing is
	 * added. A name already there asking for a different click is two ideas
	 * with one name, so the incoming one lands under a numbered name and the
	 * incoming clocks follow it. Neither case overwrites what the user had,
	 * because that would change what their existing clocks wait for without
	 * anybody asking.
	 */
	private static Merge merge(Parsed parsed, TriggerLibrary library)
	{
		final TriggerLibrary merged = TriggerLibrary.of(
			library == null ? Collections.emptyList() : new ArrayList<>(library.asStored()));
		final List<String> notes = new ArrayList<>();

		for (SavedTrigger entry : parsed.library.asStored())
		{
			final SavedTrigger landed = merged.absorb(entry.getName(), entry.getOption(), entry.getTarget());
			if (landed.getName().equals(entry.getName()))
			{
				continue;
			}

			TriggerLibrary.repoint(parsed.routines, entry.getName(), landed.getName());
			notes.add("You already have a custom trigger called " + entry.getName()
				+ " that waits for something else, so the one in this document arrived as "
				+ landed.getName() + ".");
		}

		return new Merge(merged, notes);
	}

	/**
	 * Reads a document, collecting everything wrong with it.
	 *
	 * <p>One pass, every problem, and only then a verdict. A document somebody
	 * is editing by hand is the worst possible thing to report one problem at a
	 * time about, because each round trip costs them a paste, an apply, and a
	 * read, and the second problem was there the whole time.
	 *
	 * <p>Two kinds of finding come out of here and they are not the same kind.
	 * Some are refusals, which are the things that leave no document at all
	 * behind them, and some are reports, which are the things the reading
	 * worked around and the user still has a right to know about. Both are in
	 * the same list, in the order somebody reads the document, and the flag says
	 * which way it went.
	 */
	private static Parsed parse(Gson gson, String json)
	{
		final List<DocumentProblem> problems = new ArrayList<>();

		if (json == null || json.trim().isEmpty())
		{
			problems.add(DocumentProblem.inDocument(
				"There is nothing to read. Paste a Clockwork document first."));
			return Parsed.refused(problems);
		}

		JsonObject root;
		try
		{
			root = gson.fromJson(json, JsonObject.class);
		}
		catch (RuntimeException ex)
		{
			problems.add(syntax(ex));
			return Parsed.refused(problems);
		}

		if (root == null)
		{
			problems.add(DocumentProblem.inDocument(NOT_A_DOCUMENT));
			return Parsed.refused(problems);
		}

		// The stamp is read by the storage layer's own reader rather than by a
		// second copy of it here. The two have to agree about what an absent or
		// damaged version means, and this class already writes that layer's
		// SavedState, so it is a dependency that exists rather than a new one.
		// Two numbers, and the second one is the one that decides. A document
		// from a newer build is refused only when that build says an older
		// reader would get it wrong, rather than whenever it is newer at all.
		//
		// Refusing on the version alone would break sharing between two users
		// every time an update rolled out, for the ordinary case of a document
		// that an older build reads perfectly well. Refusing on nothing at all
		// would be worse: a field that changed its meaning or its units binds
		// clean on an older build, so the review below sees nothing wrong and
		// the user ends up with a clock that looks right and times the wrong
		// thing. That failure is silent, and this is the only thing that
		// catches it.
		final int version = ClockworkStorage.version(root);
		final int minimum = ClockworkStorage.minimumReader(root);
		if (minimum > RoutineMigration.CURRENT_VERSION)
		{
			problems.add(DocumentProblem.inDocument(
				"This document was written for a newer Clockwork than this one. It needs version "
				+ minimum + " and this build is version " + RoutineMigration.CURRENT_VERSION
				+ ". Update the plugin and try again."));
		}

		final JsonElement routines = root.get(ROUTINES);
		if (routines == null || !routines.isJsonArray())
		{
			problems.add(DocumentProblem.inDocument(
				"That is not a Clockwork document. There is no list of clocks in it."));
		}

		// Both of the above are refusals, and both are collected before the
		// verdict, so a document that is wrong twice is told so twice.
		if (!problems.isEmpty())
		{
			return Parsed.refused(problems);
		}

		final Read read;
		try
		{
			read = bind(gson, root, problems);
		}
		catch (RuntimeException ex)
		{
			// The reading takes a damaged document apart rather than throwing,
			// so getting here at all means something nothing else accounted
			// for. It is still reported as a place in the text where there is
			// one to report.
			problems.add(syntax(ex));
			return Parsed.refused(problems);
		}

		// What the reading had to skip is already in the list. This adds what
		// it was perfectly happy with and should not have been.
		DocumentReview.check(gson, root, problems);

		final boolean dangling = missingTriggers(read.routines, read.library, problems);
		final List<DocumentProblem> ordered = DocumentProblem.inReadingOrder(problems);
		return dangling
			? Parsed.refused(ordered)
			: new Parsed(read.routines, read.library, ordered);
	}

	/**
	 * The clocks and the library the document holds, with everything that could
	 * not be read written down as it goes.
	 *
	 * <p>The whole document is tried in one bind first, because that is what a
	 * document with nothing wrong in it costs. One value of the wrong JSON type
	 * anywhere fails that bind, and refusing on it would mean one unreadable
	 * clock costing the user the other nine, so a failure drops through to
	 * reading the document a clock at a time instead.
	 *
	 * <p>Whichever way it went, what comes back holds no nulls. A document that
	 * writes a literal null where a clock should be binds perfectly happily to
	 * one, and everything downstream of here copies a clock rather than
	 * checking whether it is there, so the null is taken out and counted as a
	 * clock that did not arrive.
	 */
	private static Read bind(Gson gson, JsonObject root, List<DocumentProblem> problems)
	{
		ClockworkStorage.SavedState state;
		try
		{
			state = gson.fromJson(root, ClockworkStorage.SavedState.class);
		}
		catch (RuntimeException ignored)
		{
			// Said to the user rather than to the log, one finding at a time,
			// by the reading below.
			state = piecemeal(gson, root, problems);
		}

		if (state == null)
		{
			return new Read(new ArrayList<>(), TriggerLibrary.empty());
		}

		final TriggerLibrary library = TriggerLibrary.of(state.triggers);
		final List<Routine> routines = withoutNulls(state.routines, problems);
		RoutineMigration.migrate(routines);
		return new Read(routines, library);
	}

	/**
	 * The clocks that are actually there, with a null in the list reported as
	 * the clock it was standing in for.
	 *
	 * <p>Counted by position rather than by how many survived, because the
	 * position is what the user is told and the entries either side of a null
	 * keep the numbers they have in the text.
	 *
	 * <p>Nothing to do on the piecemeal path, which drops a null while it is
	 * still a piece of JSON and reports it there. This is for the bind that
	 * succeeded, where a JSON null is a Java null and no exception was thrown
	 * about it.
	 */
	private static List<Routine> withoutNulls(List<Routine> bound, List<DocumentProblem> problems)
	{
		final List<Routine> kept = new ArrayList<>();
		if (bound == null)
		{
			return kept;
		}

		int number = 0;
		for (Routine routine : bound)
		{
			number++;
			if (routine == null)
			{
				problems.add(DocumentProblem.skippedClock(number, null, null,
					"this is not a clock, it is nothing, so it was skipped"));
				continue;
			}
			kept.add(routine);
		}
		return kept;
	}

	/**
	 * What can still be read out of a document Gson would not bind in one go.
	 *
	 * <p>The library is read on its own, and then every clock is read on its
	 * own, so a clock nobody can read costs the user that clock rather than all
	 * of them. Never throws, because a caller that reaches this has already
	 * been told the ordinary bind failed and a second failure here would put it
	 * back where it started.
	 *
	 * <p>The array is walked by position, because the position is what the user
	 * is told, and a report that says the fifth clock went is only true if the
	 * count includes the entries that were not clocks at all.
	 */
	private static ClockworkStorage.SavedState piecemeal(Gson gson, JsonObject root,
		List<DocumentProblem> problems)
	{
		final ClockworkStorage.SavedState state = new ClockworkStorage.SavedState();
		state.version = ClockworkStorage.version(root);
		state.triggers = storedTriggers(gson, root, problems);
		state.routines = new ArrayList<>();

		final JsonElement array = root.get(ROUTINES);
		if (array == null || !array.isJsonArray())
		{
			return state;
		}

		int number = 0;
		for (JsonElement element : array.getAsJsonArray())
		{
			number++;
			if (element == null || !element.isJsonObject())
			{
				problems.add(DocumentProblem.skippedClock(number, null, null,
					"this is not a clock, it is " + DocumentProblem.found(element) + ", so it was skipped"));
				continue;
			}

			final Routine routine = oneClock(gson, element.getAsJsonObject(), number, problems);
			if (routine != null)
			{
				state.routines.add(routine);
			}
		}
		return state;
	}

	/**
	 * One clock out of a document that would not bind, or null when there is
	 * nothing left of it worth keeping.
	 *
	 * <p>The clock is tried as it stands first, because most clocks in a
	 * damaged document are fine and it was a neighbour that failed the bind.
	 *
	 * <p>If that fails, it is tried again without each trigger in turn, and
	 * then without any of the three. A trigger is an object where every other
	 * field on a clock is a string, a number, or a boolean, so it is much the
	 * likeliest thing to have failed. Dropping one at a time rather than all at
	 * once means a clock with one unreadable trigger keeps the other two. A
	 * clock that comes back waiting for nothing still has its name, its
	 * direction, and its target, which is a far smaller loss than the clock
	 * itself.
	 *
	 * <p>Only if all five fail is the clock dropped. Either way the user is
	 * told, naming the field that would not read and what it holds.
	 */
	private static Routine oneClock(Gson gson, JsonObject stored, int number, List<DocumentProblem> problems)
	{
		final String name = text(stored, "name");
		RuntimeException trouble;
		try
		{
			return gson.fromJson(stored, Routine.class);
		}
		catch (RuntimeException ex)
		{
			trouble = ex;
		}

		String lost = "the trigger it started on";
		Routine salvaged = boundWithout(gson, stored, "startTrigger");
		if (salvaged == null)
		{
			lost = "the trigger it stopped on";
			salvaged = boundWithout(gson, stored, "stopTrigger");
		}
		if (salvaged == null)
		{
			lost = "the trigger it lapped on";
			salvaged = boundWithout(gson, stored, "lapTrigger");
		}
		if (salvaged == null)
		{
			lost = "any of its triggers";
			salvaged = boundWithout(gson, stored, "startTrigger", "stopTrigger", "lapTrigger");
		}

		final String field = culprit(gson, stored);
		final String why = why(trouble, stored, field);

		if (salvaged == null)
		{
			problems.add(DocumentProblem.skippedClock(number, name, field, why + ", so this clock was skipped"));
			return null;
		}

		problems.add(DocumentProblem.inField(number, name, field,
			why + ", so this clock arrives without " + lost));
		return salvaged;
	}

	/**
	 * The one key on this clock that is stopping it from binding, or null when
	 * no single key is to blame.
	 *
	 * <p>Found by taking each key off in turn and seeing which removal lets the
	 * clock bind, which is the same trick {@link #boundWithout} already plays
	 * for the triggers, widened to every key. It is worth the handful of extra
	 * binds because Gson's own message names the field only sometimes. A value
	 * of the wrong JSON type comes with a path on it, and a number that will
	 * not parse comes with nothing but the text that would not parse, so
	 * without this a user editing by hand would be told a clock is broken and
	 * not told where.
	 *
	 * <p>Only reached for a clock that has already failed to bind, so the cost
	 * is paid on damaged documents alone.
	 */
	private static String culprit(Gson gson, JsonObject stored)
	{
		for (Map.Entry<String, JsonElement> entry : stored.entrySet())
		{
			if (boundWithout(gson, stored, entry.getKey()) != null)
			{
				return entry.getKey();
			}
		}
		return null;
	}

	/**
	 * Why a clock would not bind, in the user's words rather than the parser's.
	 *
	 * <p>Two halves, and each comes from a different place. What was wanted is
	 * the only thing the exception knows, since nothing else here can say what
	 * type a field is without asking the class, and what was found is read
	 * straight out of the document, so the user is shown the value they typed
	 * rather than the name of a token.
	 */
	private static String why(RuntimeException ex, JsonObject stored, String field)
	{
		final String wanted = DocumentProblem.expected(ex);
		if (wanted == null || field == null)
		{
			return "this could not be read";
		}
		return "expected " + wanted + ", found " + DocumentProblem.found(stored.get(field));
	}

	/**
	 * The clock as it binds once the named keys are taken off it, or null when
	 * it still will not bind. The copy is what keeps the caller free to try
	 * another combination against the original.
	 */
	private static Routine boundWithout(Gson gson, JsonObject stored, String... keys)
	{
		final JsonObject trimmed = stored.deepCopy();
		for (String key : keys)
		{
			trimmed.remove(key);
		}

		try
		{
			return gson.fromJson(trimmed, Routine.class);
		}
		catch (RuntimeException ignored)
		{
			// Nothing to say. This is one of five attempts at the same clock
			// and the caller reports whichever of them was the last to fail.
			return null;
		}
	}

	/**
	 * What the document holds in its library, read on its own rather than as
	 * part of the whole document.
	 *
	 * <p>A damaged library is not a reason to lose the clocks. The clocks then
	 * come back pointing at names nothing accounts for, and the check for
	 * dangling references below is what turns that into a refusal rather than
	 * into a clock that looks configured and never starts.
	 */
	private static List<SavedTrigger> storedTriggers(Gson gson, JsonObject root, List<DocumentProblem> problems)
	{
		final JsonElement stored = root.get(TRIGGERS);
		if (stored == null || !stored.isJsonArray())
		{
			return new ArrayList<>();
		}

		try
		{
			final SavedTrigger[] entries = gson.fromJson(stored, SavedTrigger[].class);
			return entries == null ? new ArrayList<>() : new ArrayList<>(Arrays.asList(entries));
		}
		catch (RuntimeException ignored)
		{
			problems.add(DocumentProblem.inDocument("The custom triggers in this document could not be read,"
				+ " so none of them arrived and the clocks that waited for one now wait for nothing."));
			return new ArrayList<>();
		}
	}

	/**
	 * A string field, or null when it is absent, is not a string, or is blank.
	 */
	private static String text(JsonObject object, String key)
	{
		final JsonElement stored = object.get(key);
		if (stored == null || !stored.isJsonPrimitive() || !stored.getAsJsonPrimitive().isString())
		{
			return null;
		}

		final String value = stored.getAsString().trim();
		return value.isEmpty() ? null : value;
	}

	/**
	 * A parser failure as somewhere in the text plus something a person can act
	 * on.
	 *
	 * <p>The line and the column are the whole point of this method. They are
	 * the only location any of this can offer that points at a character rather
	 * than at a clock.
	 *
	 * <p>A failure with no position in it is not a place in the document at
	 * all, it is Gson saying the whole thing is the wrong sort of value, so
	 * that one is reported as the document not being a document.
	 */
	private static DocumentProblem syntax(RuntimeException ex)
	{
		final String message = ex.getMessage();
		final int[] at = DocumentProblem.position(message);
		if (at == null)
		{
			return DocumentProblem.inDocument(NOT_A_DOCUMENT);
		}
		return DocumentProblem.at(at[0], at[1], said(DocumentProblem.phrase(message)));
	}

	/**
	 * The parser's complaint in the user's words.
	 *
	 * <p>Gson's own wording is kept where it is something somebody can act on,
	 * and replaced where it is not. The four below are the ones a hand edited
	 * document actually produces, and each is worded as what to go and look
	 * for rather than as what the reader wanted next.
	 */
	private static String said(String phrase)
	{
		if (DocumentProblem.mentionsInternals(phrase) || phrase.isEmpty())
		{
			return "the reader could not make sense of this";
		}

		if (phrase.startsWith("End of input"))
		{
			return "the document stops here, which usually means a bracket or a brace is missing";
		}

		if (phrase.startsWith("Unterminated "))
		{
			return "the " + phrase.substring("Unterminated ".length()) + " that starts here is never closed";
		}

		if (phrase.startsWith("Expected name"))
		{
			return "a name was expected here, which usually means a stray comma or a missing quote";
		}

		if (phrase.startsWith("Expected value"))
		{
			return "a value was expected here";
		}

		return Character.toLowerCase(phrase.charAt(0)) + phrase.substring(1);
	}

	/**
	 * Every clock in the document that waits for a custom trigger the document
	 * does not define, worded for the user. All three of a clock's triggers are
	 * asked about, because all three can name a library entry.
	 *
	 * <p>This is a refusal rather than something quietly resolved to Nothing.
	 * A clock whose trigger silently vanished looks configured, sits in the
	 * panel saying it starts on something, and never starts. Refusing the
	 * import is the only outcome the user can act on.
	 *
	 * <p>Every one of them is reported rather than the first, because a
	 * document that arrived missing one trigger has usually arrived missing
	 * several, and hearing about them one at a time is the thing this whole
	 * file was written to stop doing.
	 *
	 * @return whether anything at all was missing
	 */
	private static boolean missingTriggers(List<Routine> routines, TriggerLibrary library,
		List<DocumentProblem> problems)
	{
		// A clock that was skipped is not in this list and is still in the
		// document, so counting the survivors would number every clock after it
		// one too low. The skipped positions are already written down, so they
		// are counted past rather than guessed at, and every message about one
		// document agrees about which clock is which.
		final Set<Integer> gone = new HashSet<>();
		for (DocumentProblem problem : problems)
		{
			if (problem.isSkipped())
			{
				gone.add(problem.getNumber());
			}
		}

		boolean missing = false;
		int number = 0;

		for (Routine routine : routines)
		{
			number++;
			while (gone.contains(number))
			{
				number++;
			}

			if (routine == null)
			{
				continue;
			}

			missing |= dangling(problems, number, routine, "starts", routine.getStartTrigger(), library);
			missing |= dangling(problems, number, routine, "takes a split", routine.getLapTrigger(), library);
			missing |= dangling(problems, number, routine, "stops", routine.getStopTrigger(), library);
		}
		return missing;
	}

	private static boolean dangling(List<DocumentProblem> problems, int number, Routine routine,
		String end, Trigger trigger, TriggerLibrary library)
	{
		final String ref = missingRef(library, trigger);
		if (ref == null)
		{
			return false;
		}

		problems.add(DocumentProblem.inClock(number, routine.getName(),
			end + " on a custom trigger called " + ref + ", which this document does not define"));
		return true;
	}

	private static String missingRef(TriggerLibrary library, Trigger trigger)
	{
		final String ref = Trigger.orNothing(trigger).getRef();
		if (ref == null || library.byName(ref) != null)
		{
			return null;
		}
		return ref;
	}

	private static String key(String text)
	{
		return text == null ? "" : text.trim().toLowerCase(Locale.ROOT);
	}

	private static String newId()
	{
		return UUID.randomUUID().toString();
	}

	/**
	 * The clocks and the library one reading produced, before anything has been
	 * decided about whether the document is acceptable.
	 */
	private static final class Read
	{
		private final List<Routine> routines;
		private final TriggerLibrary library;

		private Read(List<Routine> routines, TriggerLibrary library)
		{
			this.routines = routines;
			this.library = library;
		}
	}

	/**
	 * A document that has been read and checked, and everything found wrong
	 * with it either way. A refused one has no clocks in it, and a document
	 * that was not refused can still have plenty to say.
	 */
	private static final class Parsed
	{
		private final boolean refused;
		private final List<DocumentProblem> problems;
		private final List<Routine> routines;
		private final TriggerLibrary library;

		private Parsed(List<Routine> routines, TriggerLibrary library, List<DocumentProblem> problems)
		{
			this.refused = false;
			this.problems = problems;
			this.routines = routines;
			this.library = library;
		}

		private Parsed(List<DocumentProblem> problems)
		{
			this.refused = true;
			this.problems = problems;
			this.routines = Collections.emptyList();
			this.library = TriggerLibrary.empty();
		}

		private static Parsed refused(List<DocumentProblem> problems)
		{
			return new Parsed(problems);
		}
	}

	/**
	 * The user's library with the document's triggers folded into it, and
	 * anything worth telling them about how that went.
	 */
	private static final class Merge
	{
		private final TriggerLibrary library;
		private final List<String> notes;

		private Merge(TriggerLibrary library, List<String> notes)
		{
			this.library = library;
			this.notes = notes;
		}
	}

	/**
	 * What an import would do. Ask {@link #isOk()} first, because everything
	 * else is empty when it is not.
	 */
	public static final class Imported
	{
		private final boolean refused;
		private final List<DocumentProblem> problems;
		private final List<Routine> added;
		private final TriggerLibrary library;
		private final List<String> notes;

		private Imported(boolean refused, List<DocumentProblem> problems, List<Routine> added,
			TriggerLibrary library, List<String> notes)
		{
			this.refused = refused;
			this.problems = problems == null
				? Collections.emptyList() : Collections.unmodifiableList(problems);
			this.added = added == null ? Collections.emptyList() : Collections.unmodifiableList(added);
			this.library = library == null ? TriggerLibrary.empty() : library;
			this.notes = notes == null ? Collections.emptyList() : Collections.unmodifiableList(notes);
		}

		public boolean isOk()
		{
			return !refused;
		}

		/**
		 * Why the document was refused, worded for the user, or null when it
		 * was not refused. Every problem found, one to a line, because a
		 * document refused for one reason usually has more than one.
		 */
		public String getProblem()
		{
			return refused ? DocumentProblem.lines(problems) : null;
		}

		/**
		 * Everything wrong with the document, whether or not it was refused.
		 *
		 * <p>Not empty on a document that imports. A clock the reading could not
		 * read is skipped rather than taking its neighbours with it, and this is
		 * where the user is told that happened, before they press the button.
		 */
		public List<DocumentProblem> getProblems()
		{
			return problems;
		}

		/**
		 * The clocks to add, each with a fresh id and no runs. Nothing the user
		 * already had is in here, because an import never replaces anything.
		 */
		public List<Routine> getAdded()
		{
			return added;
		}

		/**
		 * The user's trigger library with the document's triggers folded in.
		 */
		public TriggerLibrary getLibrary()
		{
			return library;
		}

		/**
		 * Things worth telling the user, such as a trigger that had to arrive
		 * under a numbered name. Empty when the import is uneventful.
		 */
		public List<String> getNotes()
		{
			return notes;
		}
	}

	/**
	 * What applying an edited document would do. A plan rather than an act, so
	 * the panel can confirm the removals before anything happens.
	 */
	public static final class Applied
	{
		private final boolean refused;
		private final List<DocumentProblem> problems;
		private final List<Routine> routines;
		private final TriggerLibrary library;
		private final List<String> removed;
		private final List<String> added;
		private final List<String> notes;

		private Applied(boolean refused, List<DocumentProblem> problems, List<Routine> routines,
			TriggerLibrary library, List<String> removed, List<String> added, List<String> notes)
		{
			this.refused = refused;
			this.problems = problems == null
				? Collections.emptyList() : Collections.unmodifiableList(problems);
			this.routines = routines == null ? Collections.emptyList() : Collections.unmodifiableList(routines);
			this.library = library == null ? TriggerLibrary.empty() : library;
			this.removed = removed == null ? Collections.emptyList() : Collections.unmodifiableList(removed);
			this.added = added == null ? Collections.emptyList() : Collections.unmodifiableList(added);
			this.notes = notes == null ? Collections.emptyList() : Collections.unmodifiableList(notes);
		}

		public boolean isOk()
		{
			return !refused;
		}

		public String getProblem()
		{
			return refused ? DocumentProblem.lines(problems) : null;
		}

		/**
		 * Everything wrong with the document, whether or not it was refused, so
		 * the editor can show all of it at once and leave the text alone.
		 */
		public List<DocumentProblem> getProblems()
		{
			return problems;
		}

		/**
		 * The whole clock list as it would stand, in the order the document
		 * lists them. A clock matched by name keeps its id, and therefore its
		 * runs and its timer box position.
		 */
		public List<Routine> getRoutines()
		{
			return routines;
		}

		public TriggerLibrary getLibrary()
		{
			return library;
		}

		/**
		 * The names of the clocks that would go, because the document does not
		 * mention them. Show these to the user before applying anything.
		 */
		public List<String> getRemoved()
		{
			return removed;
		}

		/**
		 * The names of the clocks that would be new.
		 */
		public List<String> getAdded()
		{
			return added;
		}

		public List<String> getNotes()
		{
			return notes;
		}
	}
}

