@Slf4j
@PluginDescriptor(
	name = "Clockwork",
	description = "Time the things you repeat, keep the runs, and see whether you are getting quicker",
	// The same eight, in the same order, as the tags line in
	// runelite-plugin.properties. That one drives the hub listing and this one
	// drives search inside the client, and two lists that drift are two
	// different answers to the same question.
	tags = {"timer", "stopwatch", "speedrun", "splits", "clock", "countdown", "farming", "herb run"}
)
public class ClockworkPlugin extends Plugin
{
	/**
	 * How often the panel is refreshed while something is moving. Fast enough
	 * for a hundredths display to look alive, and the work behind it is a
	 * handful of subtractions and a string per running routine.
	 */
	private static final int REFRESH_MILLIS = 50;

	/**
	 * How often it is refreshed while nothing is. With no clock running and the
	 * side panel shut, there is nothing on screen that changes between one tick
	 * and the next, so twenty a second was twenty wasted. Every path that
	 * starts something moving calls {@link #wake()}, and this period is also
	 * short enough that a path nobody thought of costs half a second rather
	 * than a stuck clock.
	 */
	private static final int IDLE_REFRESH_MILLIS = 500;

	/**
	 * The build this is. It tracks the version in build.gradle and the one in
	 * runelite-plugin.properties, and a test fails if they drift apart.
	 */
	public static final String VERSION = "00.01.010";

	@Inject
	private Client client;

	@Inject
	private ClockworkConfig config;

	@Inject
	private ClockworkStorage storage;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	/**
	 * Only used by the click log, which is off unless the user switches it on
	 * while setting a click trigger up.
	 */
	@Inject
	private ChatMessageManager chatMessageManager;

	/**
	 * The three the alerts need. The notifier reads whether the client has
	 * focus, so it is called from the client thread rather than from Swing, and
	 * the audio player is what reads the bundled chime out of the plugin jar.
	 */
	@Inject
	private Notifier notifier;

	@Inject
	private ClientThread clientThread;

	@Inject
	private AudioPlayer audioPlayer;

	/**
	 * Where the three hotkey listeners are registered and, at shut down, given
	 * back. Stopping a plugin never unregisters a key listener for it.
	 */
	@Inject
	private KeyManager keyManager;

	/**
	 * RuneLite's shared single threaded background executor, used for the one
	 * small disk append per finished run so the event dispatch thread never
	 * writes to disk. It is shared, so nothing here may block it, and a single
	 * bounded append does not.
	 */
	@Inject
	private ScheduledExecutorService executor;

	private RoutineController controller;

	/**
	 * The permanent run log on disk. Built at start up and re-pointed on a
	 * profile switch, since the path it follows is a per profile config key.
	 */
	private HistoryFile historyFile;

	/**
	 * The guard every entry point below is wrapped in. Never null, because a
	 * failure has to have somewhere to go from the first line of
	 * {@link #startUp()} onwards.
	 */
	private final Diagnostics diagnostics = new Diagnostics();

	private ClockworkPanel panel;
	private NavigationButton navButton;
	private Timer refreshTimer;

	/**
	 * The three collaborators. Each has its own {@code startUp} and
	 * {@code shutDown}, which this class calls and reverses, so the teardown
	 * that gives back every timer box, the screen flash, and the three key
	 * listeners sits next to the code that registered them.
	 */
	private OverlayCoordinator overlays;
	private Alerts alerts;
	private Hotkeys hotkeys;

	/**
	 * Wakes the refresh when the side panel is opened.
	 *
	 * <p>There is no event for that, and a panel that has just been opened is
	 * showing a clock the user expects to be live. Held so it can be taken off
	 * the panel again, since a listener left on a component keeps the thing
	 * that made it alive.
	 */
	private HierarchyListener panelShown;

	/**
	 * Whether any clock is waiting for an event of each kind.
	 *
	 * <p>These exist so the handlers below can leave immediately, before they
	 * touch anything or allocate anything, on a client where nobody has set a
	 * trigger. An animation fires for every actor near the player, so in a busy
	 * place that handler runs constantly and has to be free when it has nothing
	 * to do.
	 *
	 * <p>Written on the event dispatch thread whenever the clock list changes
	 * and read on the client thread, hence volatile. A read that is one event
	 * out of date costs at most one missed or one wasted trigger, which is why
	 * a plain field is enough and no lock is taken on the client thread.
	 */
	private volatile boolean watchingAnimations;
	private volatile boolean watchingMenu;
	private volatile boolean watchingChat;

	/**
	 * Every callback is guarded. The controller runs its listeners in a loop,
	 * so one that throws would otherwise take the rest of them with it and
	 * leave a run half recorded.
	 */
	private final RoutineListener listener = new RoutineListener()
	{
		@Override
		public void onRoutinesChanged()
		{
			diagnostics.guard("listener.routinesChanged", () ->
			{
				if (controller == null)
				{
					return;
				}
				// Every path that can change a history ends here, so this is
				// the one place derived statistics have to be dropped.
				RoutineStats.invalidateAll();
				storage.save(controller.getRoutines(), controller.getLibrary());
				refreshTriggerInterest();
				refreshPanel();
				wake();
			});
		}

		/**
		 * One clock's runs changed and nothing else did, which is a finished run
		 * or a cleared clock.
		 *
		 * <p>The narrow twin of the rebuild above. It writes that clock's runs
		 * rather than the whole saved state, which is the point of storing the
		 * runs under a key per clock, and it drops the statistics of that clock
		 * rather than of every clock, because no other clock's runs moved.
		 *
		 * <p>The clocks and the trigger library are untouched by a run ending,
		 * so nothing here has to look at what the triggers are waiting for.
		 */
		@Override
		public void onHistoryChanged(Routine routine)
		{
			diagnostics.guard("listener.historyChanged", () ->
			{
				RoutineStats.invalidate(routine);
				storage.saveHistory(routine);
				refreshPanel();
				wake();
			});
		}

		@Override
		public void onRunStarted(Routine routine)
		{
			diagnostics.guard("listener.runStarted", () ->
			{
				// The alert for the last run must not still be blinking over
				// the next one.
				clearAlert();
				refreshPanel();
				wake();
			});
		}

		@Override
		public void onRunCancelled(Routine routine)
		{
			diagnostics.guard("listener.runCancelled", () ->
			{
				clearAlert();
				refreshPanel();
				wake();
			});
		}

		@Override
		public void onLapTaken(Routine routine, Lap lap)
		{
			diagnostics.guard("listener.lapTaken", () ->
			{
				refreshPanel();
				wake();
			});
		}

		@Override
		public void onRunFinished(Routine routine, Run run)
		{
			diagnostics.guard("listener.runFinished", () ->
			{
				// Before anything reads a personal best, and belt and braces
				// beside the routines changed callback that follows this one.
				RoutineStats.invalidate(routine);

				// Every finished run is written to the permanent log, whether it
				// completed or was abandoned. The status column is what tells the
				// two apart, so this is not gated on the outcome.
				appendToHistoryFile(routine, run);

				// A run that was abandoned is not something to congratulate,
				// so only a completed one is announced.
				if (run.getStatus() == Status.COMPLETED && alerts != null)
				{
					alerts.alert(routine, routine.getName() + " finished in "
						+ DurationFormatter.format(run.getDurationMillis(), Formats.of(config)));
				}
			});
		}

		/**
		 * The last three seconds of a countdown, one callback per second.
		 *
		 * <p>The setting is read here rather than in the controller, which knows
		 * nothing about the config and simply says when a second went by. A user
		 * who has turned the count in off still has the moment announced to a
		 * plugin that then does nothing with it, which costs three comparisons on
		 * three ticks of a countdown and keeps the timing in one place.
		 */
		@Override
		public void onCountInSecond(Routine routine, int secondsLeft)
		{
			diagnostics.guard("listener.countInSecond", () ->
			{
				if (alerts != null && config.countIn())
				{
					alerts.countIn(routine);
				}
			});
		}

		/**
		 * The other end of a countdown. A clock told to stop at zero never
		 * reaches this, because its run ends there and arrives above as a
		 * finished run instead, so a run raises exactly one alert whichever way
		 * the clock is set.
		 */
		@Override
		public void onCountdownExpired(Routine routine)
		{
			diagnostics.guard("listener.countdownExpired", () ->
			{
				if (alerts != null)
				{
					alerts.alert(routine, routine.getName() + " reached zero");
				}
			});
		}
	};

	/**
	 * Starting up is the one entry point whose failure is not swallowed. It is
	 * recorded and then thrown on, because RuneLite needs to know the plugin
	 * did not come up rather than run a half built one.
	 *
	 * <p>The teardown before the rethrow is not belt and braces.
	 * {@code PluginManager} does not call {@code shutDown} on a plugin whose
	 * {@code startUp} threw, and {@link #doStartUp()} puts the navigation
	 * button on the toolbar before it is finished, so a throw after that point
	 * would otherwise leave a button behind for the rest of the session,
	 * opening a panel nothing refreshes, with the plugin showing as off.
	 * {@link #doShutDown()} is null safe at every step, so it is safe to run
	 * against a start up that got half way.
	 */
	@Override
	protected void startUp()
	{
		try
		{
			doStartUp();
		}
		catch (RuntimeException | Error thrown)
		{
			diagnostics.record("plugin.startUp", thrown);
			diagnostics.guard("plugin.startUp.undo", this::doShutDown);
			throw thrown;
		}
	}

	private void doStartUp()
	{
		storage.setDiagnostics(diagnostics);

		// First, and before anything reads a setting. A config key carries no
		// version of its own, so the one key that has been renamed since the
		// published build has to be carried across by hand or every user who
		// had turned the timer boxes off silently gets them back.
		storage.migrateOverlayVisibility();

		// Beside it, and for the same reason. The average window used to reach
		// past what a clock now keeps, so a stored value above the new maximum
		// is brought down rather than left reading one thing and doing another.
		storage.clampAverageWindow();

		controller = new RoutineController(System::currentTimeMillis);
		final ClockworkStorage.Saved saved = storage.load();
		RoutineStats.invalidateAll();
		controller.load(saved.getRoutines(), saved.getLibrary());
		controller.setLoggedIn(isInGame(client.getGameState()));
		refreshTriggerInterest();

		// Before the panel, because the panel is handed the designation and the
		// hotkeys own it. The panel is read back the other way, for the
		// selection, which is why that side is a supplier rather than a field.
		hotkeys = new Hotkeys(keyManager, config, storage, () -> controller,
			() -> panel == null ? null : panel.getSelectedRoutineId(), this::onEdt,
			this::onDesignationChanged);
		hotkeys.startUp();

		// Before the panel, because the panel is handed the file and offers to
		// move or delete it. The stored path is per profile, so an absent one
		// means this profile has never moved the log and the default place is
		// used.
		final File chosen = storage.loadHistoryFile();
		historyFile = new HistoryFile(chosen == null ? defaultHistoryFile() : chosen);

		panel = new ClockworkPanel(controller, config, historyFile, diagnostics, this::onHistoryFileMoved,
			hotkeys.handle(), storage);
		panelShown = event ->
		{
			if ((event.getChangeFlags() & HierarchyEvent.SHOWING_CHANGED) != 0 && panel != null
				&& panel.isShowing())
			{
				wake();
			}
		};
		panel.addHierarchyListener(panelShown);

		navButton = NavigationButton.builder()
			.tooltip("Clockwork")
			.icon(icon())
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		controller.addListener(listener);

		// After the listener is attached, so a first run writes the built in
		// clock straight back to config rather than waiting for another change.
		controller.ensureQuick();

		overlays = new OverlayCoordinator(this, overlayManager, config, diagnostics, () -> controller);
		overlays.startUp();

		// After the overlays, because an alert flashes a box the coordinator
		// owns and has to be able to ask it for one.
		alerts = new Alerts(this, client, config, overlayManager, overlays, notifier, clientThread,
			audioPlayer, diagnostics, this::wake);
		alerts.startUp();

		// Hoisted so the tick does not build a fresh one twenty times a
		// second.
		final Runnable tick = this::onRefresh;
		refreshTimer = new Timer(REFRESH_MILLIS, e -> diagnostics.guard("refresh.tick", tick));
		refreshTimer.start();
	}

	@Override
	protected void shutDown()
	{
		diagnostics.guard("plugin.shutDown", this::doShutDown);
	}

	/**
	 * Reverses {@link #doStartUp()}, in the order that undoes it. Everything
	 * registered on the way up is given back here, because stopping a plugin
	 * does not undo its registrations for it.
	 */
	private void doShutDown()
	{
		// First, and unconditionally. A key listener left registered outlives
		// the plugin that made it, which is the exact class of bug this plugin
		// is careful about everywhere else.
		if (hotkeys != null)
		{
			hotkeys.shutDown();
			hotkeys = null;
		}

		if (refreshTimer != null)
		{
			refreshTimer.stop();
			refreshTimer = null;
		}

		// Before the overlays, in the reverse of the order they came up in.
		if (alerts != null)
		{
			alerts.shutDown();
			alerts = null;
		}

		if (overlays != null)
		{
			overlays.shutDown();
			overlays = null;
		}

		if (controller != null)
		{
			controller.removeListener(listener);
		}

		if (panel != null && panelShown != null)
		{
			panel.removeHierarchyListener(panelShown);
		}
		panelShown = null;

		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}

		watchingAnimations = false;
		watchingMenu = false;
		watchingChat = false;

		panel = null;
		controller = null;

		// The executor is injected and shared, not ours, so it is left running.
		// Each append opens and closes its own stream, so there is nothing on
		// the file to close either.
		historyFile = null;

		RoutineStats.invalidateAll();
	}

	@Provides
	ClockworkConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ClockworkConfig.class);
	}

	/**
	 * The live controller.
	 *
	 * <p>Package private and read only in spirit. It exists for the test
	 * harness, which used to read the field reflectively, and reflection in a
	 * hub plugin's own source is worth removing even from a file that never
	 * ships.
	 */
	RoutineController getController()
	{
		return controller;
	}

	/**
	 * How long the refresh waits between ticks, which is one of two values and
	 * therefore says whether the plugin currently thinks anything is moving.
	 *
	 * <p>Package private for the wiring test. The wake up is the one part of
	 * the refresh a user notices immediately when it is wrong, a clock that
	 * starts and then sits still, and the alternative to reading this is a test
	 * that watches a real clock and hopes.
	 */
	int refreshDelayMillis()
	{
		final Timer timer = refreshTimer;
		return timer == null ? 0 : timer.getDelay();
	}

	/**
	 * Logging in and out. It exists so a clock set to count logged in time only
	 * stops counting the time spent at the login screen.
	 *
	 * <p>This used to be the only game event the plugin listened to. The three
	 * below it are the triggers, and they are the only others.
	 */
	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final boolean inGame = isInGame(event.getGameState());
		SwingUtilities.invokeLater(() ->
		{
			if (controller != null)
			{
				controller.setLoggedIn(inGame);
			}
		});
	}

	/**
	 * A setting changed.
	 *
	 * <p>This replaces a poll. The refresh used to read the display settings
	 * twenty times a second and compare them against the values it saw last
	 * time, purely to notice a change a user makes about once a month. Now the
	 * panel is redrawn on the event that says one of them moved, and the
	 * settings are read where they are drawn with.
	 *
	 * <p>Both halves of the panel need it. {@link #wake()} alone puts the
	 * refresh back on its fast period, which redraws the running clock, and
	 * leaves the Best, Average and Last lines and any open history rows in the
	 * format they were last drawn in. Those are only ever written by a rebuild,
	 * so the rebuild has to be asked for here.
	 *
	 * <p>A rebuild is affordable on this path. It happens once per settings
	 * change, which is user driven and rare, and it reads config rather than
	 * writing it, so it cannot bring another {@code ConfigChanged} back round.
	 *
	 * <p>Filtered to this plugin's own group. Every other plugin's settings
	 * come through the same event and none of them mean anything here.
	 */
	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!ClockworkConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		onEdt("plugin.configChanged", () ->
		{
			// Captured, because this arrives on a queue and the collaborator
			// underneath it goes away when the plugin is switched off.
			final OverlayCoordinator currentOverlays = overlays;
			if (currentOverlays != null)
			{
				currentOverlays.configChanged();
			}
			refreshPanel();
			wake();
		});
	}

	/**
	 * The user switched RuneLite config profile.
	 *
	 * <p>Thin on purpose. Every config profile keeps its own settings file, so
	 * the clock list is per profile, and Clockwork used to read it once at
	 * start up and never again. After a switch the plugin still held the
	 * previous profile's clocks and the next save wrote them over the newly
	 * selected profile's. See {@link ProfileSwitch} for what the reload has to
	 * be careful about and why.
	 */
	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		// Logged on arrival, before the hop, so the client log distinguishes
		// "the event never reached us" from "the reload ran and went wrong".
		// Without this the two look identical from the outside. Infrequent
		// enough for info, this fires only when a profile is switched.
		log.info("Clockwork saw a profile change, reloading");
		onEdt("plugin.profileChanged", () ->
		{
			reloadProfile();
			log.info("Clockwork reloaded {} clocks for the new profile",
				controller == null ? 0 : controller.getRoutines().size());
		});
	}

	/**
	 * Throws away everything the old profile owned and reads the new one.
	 *
	 * <p>Nothing is saved on the way out. By the time this runs the config
	 * manager has already moved, so a save now would write the old profile's
	 * clocks into the new profile, which is the exact damage being fixed. The
	 * old state is dropped unwritten instead, which is safe because it was
	 * written the last time it changed.
	 *
	 * <p>A run in progress cannot survive that. It belongs to a profile that
	 * can no longer be written to, so it is cancelled and recorded nowhere,
	 * and the log says so.
	 */
	private void reloadProfile()
	{
		final RoutineController current = controller;
		if (current == null)
		{
			return;
		}

		// Read, then decide, then act. Both decisions are pure and tested.
		// The trigger library comes out of the same blob and is per profile for
		// the same reason the clocks are, so it is reloaded here beside them.
		final ClockworkStorage.Saved saved = storage.load();
		final List<Routine> loaded = saved.getRoutines();

		final List<String> dropped = ProfileSwitch.droppedRuns(current.runningIds());

		if (!dropped.isEmpty())
		{
			diagnostics.record("plugin.profileChanged", "config profile switched, dropping "
				+ dropped.size() + " run in progress"
				+ ", because it belongs to the profile being left and cannot be written to it any more");
		}

		// Cancelled one at a time rather than left for the load to clear, so
		// the listeners see each run end and nothing is left half recorded.
		for (String id : dropped)
		{
			current.cancel(id);
		}

		carryDesignation(loaded);

		// Every clock the statistics were derived from is about to be replaced
		// by a different profile's.
		RoutineStats.invalidateAll();

		// This fires the routines changed listener, which saves. That save
		// goes to the newly selected profile and writes back exactly what was
		// just read out of it, so it costs nothing and loses nothing.
		current.load(loaded, saved.getLibrary());
		current.ensureQuick();

		refreshTriggerInterest();

		// The history file path is a per profile config key, so it follows the
		// profile the same way the clocks and the designation do. Re-pointed
		// here, or the log would keep appending to the previous profile's file.
		final File chosenHistory = storage.loadHistoryFile();
		if (historyFile != null)
		{
			historyFile.setTarget(chosenHistory == null ? defaultHistoryFile() : chosenHistory);
		}
		if (panel != null)
		{
			panel.refreshHistoryFile();
		}

		refreshPanel();
		wake();
	}

	/**
	 * Carries the designated hotkey clock across a profile switch, or clears it
	 * when the profile being entered has no such clock.
	 *
	 * <p>The designation is a config key, so it is per profile like everything
	 * else here, and one read before the switch can name a clock the new
	 * profile has never heard of. Leaving it in place would point the keys at
	 * nothing, so it is unset rather than left there, which is also what stops
	 * it coming back on the next restart.
	 *
	 * <p>The decision is {@link HotkeyTarget#surviving}, which is pure and
	 * tested. What is left here is which of the two answers to write, and that
	 * is covered end to end by the wiring test.
	 */
	private void carryDesignation(List<Routine> loaded)
	{
		final Hotkeys current = hotkeys;
		if (current == null)
		{
			return;
		}

		final String designated = current.getTargetId();
		if (designated == null || designated.isEmpty())
		{
			return;
		}

		final List<String> loadedIds = new ArrayList<>();
		for (Routine routine : loaded)
		{
			if (routine != null)
			{
				loadedIds.add(routine.getId());
			}
		}

		final String kept = HotkeyTarget.surviving(designated, loadedIds);
		current.setTargetId(kept);
		if (kept == null)
		{
			storage.saveHotkeyTarget(null);
			diagnostics.record("plugin.profileChanged", "config profile switched, clearing the"
				+ " designated hotkey clock, because the profile being entered does not have it");
		}
	}

	/**
	 * Run after the hotkeys are pointed at a different clock. The cards carry
	 * the marker and the wording of the menu entry, so they are rebuilt.
	 */
	private void onDesignationChanged()
	{
		refreshPanel();
		wake();
	}

	/**
	 * Writes one finished run to the permanent log, off the draw thread.
	 *
	 * <p>Called for every finished run, completed or abandoned, so the log is a
	 * full record rather than a record of the good ones. The status column is
	 * what separates them.
	 */
	private void appendToHistoryFile(Routine routine, Run run)
	{
		final HistoryFile file = historyFile;
		if (file == null)
		{
			return;
		}

		// Built here, on the thread that just finished the run, because it is
		// a handful of string joins and it has to read the clock's name as it
		// stands right now. Only the write is handed to the background, since
		// disk work has no place on the thread that draws the client.
		final String row = HistoryCsv.row(routine.getName(), run, ZoneId.systemDefault());
		try
		{
			executor.execute(() -> file.append(row));
		}
		catch (RejectedExecutionException ex)
		{
			// The shared executor only rejects once the client is shutting
			// down, and one last row is not worth writing on the draw thread
			// to save. It is dropped, and the file's own notice covers a
			// failure the user can still act on.
			log.debug("could not queue the history append, dropping one row", ex);
		}
	}

	/**
	 * The default place the log lives, inside the RuneLite directory, used when
	 * the user has never moved it.
	 */
	private static File defaultHistoryFile()
	{
		return new File(new File(RuneLite.RUNELITE_DIR, HistoryFile.DIRECTORY), HistoryFile.FILE_NAME);
	}

	/**
	 * Persists a moved log file. The panel sets the target on the file itself,
	 * this only remembers the choice for the next start up.
	 */
	private void onHistoryFileMoved(File file)
	{
		storage.saveHistoryFile(file);
	}

	// Triggers

	/**
	 * The player played an animation.
	 *
	 * <p>This is the hot one. It fires for every actor in the scene, so the
	 * cheap checks come first and in order, whether anybody is listening at all,
	 * then whether it was the local player. Nothing is allocated until both
	 * have passed.
	 *
	 * <p>Only the local player is ever read. See {@link com.clockwork.core.TriggerType}
	 * for why that is a hard rule rather than a preference.
	 */
	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (!watchingAnimations)
		{
			return;
		}

		final Actor actor = event.getActor();
		if (actor == null || actor != client.getLocalPlayer())
		{
			return;
		}

		final int animation = actor.getAnimation();
		diagnostics.guard("trigger.animation", () -> fireTrigger(TriggerEvent.animation(animation)));
	}

	/**
	 * The player clicked a menu entry.
	 *
	 * <p>Read and nothing else. The entry is not changed, no entry is added or
	 * removed, and the click is not consumed, so what the client does with it is
	 * exactly what it would have done without this plugin.
	 *
	 * <p>This fires on every click, so the two cheap boolean checks come first
	 * and nothing is allocated until one of them has passed. The clocks are
	 * asked about the click when any of them is waiting for one, and the click
	 * is written to the chat box when the user has asked to see it. Neither
	 * depends on the other, because the whole point of the log is to be usable
	 * before a trigger has been set up.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		final boolean logging = config.logMenuClicks();
		if (!logging && !watchingMenu)
		{
			return;
		}

		diagnostics.guard("trigger.menu", () ->
		{
			// Stripped once, and both halves are used from here, so what is
			// written to the chat box is exactly the pair a rule is given.
			final TriggerEvent click = GameTriggers.menuClick(event.getMenuOption(), event.getMenuTarget());
			if (logging)
			{
				logMenuClick(click);
			}
			if (watchingMenu)
			{
				fireTrigger(click);
			}
		});
	}

	/**
	 * Writes one click to the chat box, as the setup aid for click triggers.
	 *
	 * <p>Without this a user has to guess the exact wording of a menu target,
	 * and a trigger that never fires looks the same as a plugin that is broken.
	 * Both halves are printed in brackets so an empty one is visible rather
	 * than invisible, and both are printed after the colour tags come off,
	 * because those are the strings the rule is actually given.
	 *
	 * <p>Runs on the client thread, which is where the chat message manager
	 * wants to be called from and where this handler already is.
	 *
	 * <p>For a reviewer scanning this, the two rules nearest to it and what
	 * this does instead. "No autotyping", plugins must not programmatically
	 * insert text into the chatbox input. Nothing here touches the chatbox
	 * input. A {@code GAMEMESSAGE} is a line the client draws in the chat
	 * window on this player's screen, the same way dozens of core plugins
	 * report what they did, and nothing is sent to the server. "No modifying
	 * outgoing chat messages after the user sends them". Nothing here reads or
	 * alters a message the user typed. The only strings involved are the option
	 * and target of the menu entry the user just clicked.
	 */
	private void logMenuClick(TriggerEvent click)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.value("Clockwork saw a click. Option [" + click.getMenuOption()
				+ "] Target [" + click.getMenuTarget() + "]")
			.build());
	}

	/**
	 * A message arrived in the chat box. Only the game's own messages to this
	 * player are looked at, and the line is dropped before any rule sees it if
	 * it is anything else.
	 */
	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!watchingChat || !GameTriggers.isTriggerChat(event.getType()))
		{
			return;
		}

		diagnostics.guard("trigger.chat", () -> fireTrigger(GameTriggers.chatMessage(event.getMessage())));
	}

	/**
	 * Hands a normalised event to the clocks.
	 *
	 * <p>Every handler above runs on the client thread and the controller is
	 * confined to the event dispatch thread, so this hops before it touches
	 * anything. Triggers call
	 * {@link com.clockwork.core.RoutineController#start},
	 * {@link com.clockwork.core.RoutineController#lap}, and
	 * {@link com.clockwork.core.RoutineController#stop}, the same three methods
	 * the buttons call, so a repeated start is armed away exactly as it always
	 * was.
	 */
	private void fireTrigger(TriggerEvent event)
	{
		onEdt("trigger.dispatch", () -> TriggerEngine.dispatch(controller, event));
	}

	/**
	 * Works out which handlers have anything to do, and caches the answer.
	 *
	 * <p>Called on the event dispatch thread, from start up and from every
	 * change to the clock list, which is the only thing that can change the
	 * answer.
	 */
	private void refreshTriggerInterest()
	{
		final RoutineController current = controller;
		final List<Routine> routines = current == null ? Collections.emptyList() : current.getRoutines();
		final TriggerLibrary library = current == null ? TriggerLibrary.empty() : current.getLibrary();
		watchingAnimations = TriggerEngine.wants(routines, library, TriggerEvent.Kind.ANIMATION);
		watchingMenu = TriggerEngine.wants(routines, library, TriggerEvent.Kind.MENU_CLICK);
		watchingChat = TriggerEngine.wants(routines, library, TriggerEvent.Kind.CHAT_MESSAGE);
	}

	private void refreshPanel()
	{
		final ClockworkPanel current = panel;
		if (current != null)
		{
			current.rebuild();
		}
	}

	/**
	 * Menu callbacks arrive on the client thread and the controller lives on
	 * the event dispatch thread, so everything hops here.
	 */
	private void onEdt(String context, Runnable runnable)
	{
		SwingUtilities.invokeLater(() -> diagnostics.guard(context, () ->
		{
			if (controller != null)
			{
				runnable.run();
			}
		}));
	}

	private static boolean isInGame(GameState state)
	{
		return state == GameState.LOGGED_IN || state == GameState.LOADING || state == GameState.HOPPING;
	}

	// Refresh

	/**
	 * Runs on the Swing event dispatch thread, because that is where the timer
	 * fires and where every mutation of the controller happens.
	 */
	private void onRefresh()
	{
		// Captured up front. A tick can already be queued on the event thread
		// when the plugin is switched off, and shut down runs on the client
		// thread, so the fields underneath can go away mid method.
		final RoutineController current = controller;
		final ClockworkPanel currentPanel = panel;
		final OverlayCoordinator currentOverlays = overlays;
		final Alerts currentAlerts = alerts;
		if (current == null)
		{
			return;
		}

		final long now = System.currentTimeMillis();
		current.tick(now);

		// Ended before the boxes are drawn, so the tick that finds an alert
		// over is also the tick that gives back the box it was keeping open.
		if (currentAlerts != null)
		{
			currentAlerts.expire(now);
		}

		if (currentOverlays != null)
		{
			currentOverlays.update(now,
				currentAlerts == null ? null : currentAlerts.getFlashingRoutineId(),
				currentAlerts == null ? 0 : currentAlerts.getFlashUntilMillis());
		}

		final boolean showing = currentPanel != null && currentPanel.isShowing();
		if (showing)
		{
			currentPanel.refreshLive(now);
		}

		// Last, so the decision is made about the state this tick just drew. A
		// flash blinks, so it counts as something moving even with every clock
		// stopped.
		setRefreshRate(!current.runningIds().isEmpty() || showing
			|| (currentAlerts != null && currentAlerts.isFlashing()));
	}

	/**
	 * Ends whatever alert is on screen, if there is one and the plugin is still
	 * up.
	 */
	private void clearAlert()
	{
		final Alerts current = alerts;
		if (current != null)
		{
			current.clearFlash();
		}
	}

	/**
	 * Picks the period for the next tick.
	 *
	 * <p>Slowing down takes effect after the tick that decides it, because a
	 * Swing timer reschedules itself from its delay each time it fires. That is
	 * exactly what is wanted here, since the tick that finds nothing moving is
	 * also the tick that drew the last frame of whatever stopped.
	 */
	private void setRefreshRate(boolean busy)
	{
		final Timer timer = refreshTimer;
		final int wanted = busy ? REFRESH_MILLIS : IDLE_REFRESH_MILLIS;
		if (timer != null && timer.getDelay() != wanted)
		{
			timer.setDelay(wanted);
		}
	}

	/**
	 * Puts the refresh back on its fast period now rather than at the end of a
	 * slow tick.
	 *
	 * <p>Called from every path that starts something moving. A clock that
	 * starts and does not visibly move until half a second later is the failure
	 * this exists to prevent, so the restart is what makes the next tick land
	 * within a frame instead of at the end of the idle wait already under way.
	 *
	 * <p>Safe from any thread. A Swing timer is one of the few Swing objects
	 * documented as safe to touch from outside the event dispatch thread.
	 */
	private void wake()
	{
		final Timer timer = refreshTimer;
		if (timer == null || timer.getDelay() == REFRESH_MILLIS)
		{
			return;
		}

		timer.setDelay(REFRESH_MILLIS);
		// The initial delay is the fast period too, so this is a tick within a
		// frame rather than an immediate one, which is all the eye needs.
		timer.restart();
	}

	private BufferedImage icon()
	{
		return ImageUtil.loadImageResource(ClockworkPlugin.class, "icon.png");
	}
}

package com.clockwork;

import com.clockwork.core.OverlayMode;
import com.clockwork.core.Routine;
import com.clockwork.core.RoutineMigration;
import com.clockwork.core.Run;
import com.clockwork.core.RunHistory;
import com.clockwork.core.SavedTrigger;
import com.clockwork.core.Totals;
import com.clockwork.core.TriggerLibrary;
import com.clockwork.diag.Diagnostics;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.File;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Reads and writes the clocks, the trigger library, and the recorded runs.
 *
 * <p>The settings and the runs sit under different keys, and the split between
 * them is the point. {@code routines} holds the settings, which is exactly the
 * document a user can hand to somebody else, and the runs sit under a key per
 * clock, which is nobody else's business. Keeping them apart is what lets an
 * export be the same shape as the saved state rather than a second format with
 * a second parser behind it.
 *
 * <p>A key per clock rather than one key holding every clock's runs, because a
 * config value is written whole and every key that has changed is uploaded
 * whole. One key meant that finishing a single run re-encoded every clock's
 * entire history and put all of it in the next sync, which at the fifty run cap
 * came to a quarter of a megabyte for a user with ten clocks, for one finished
 * herb run. A key per logical entity, enumerated afterwards by scanning for the
 * prefix, is the layout RuneLite's own plugins use for anything machine
 * generated.
 *
 * <p>A second key per clock holds that clock's lifetime totals, which is a
 * count of completed runs and their summed duration and nothing else. The runs
 * are capped, so once one has been let go there is nowhere an all time average
 * could be read from, and two numbers is the smallest thing that can answer for
 * runs that are gone. It is a fixed size forever, whatever the user does.
 *
 * <p>Decoding is deliberately forgiving, and forgiving in a particular
 * direction. A blob that is missing or empty leaves the user with no routines
 * and a line in the log, never with a plugin that refuses to start. A blob that
 * is damaged is taken apart rather than thrown away, so that one clock nobody
 * can read costs the user that clock and not the rest of them, and a clock
 * whose trigger cannot be read comes back waiting for nothing rather than not
 * coming back at all. The runs follow the same rule one level further down,
 * where a run nobody can read costs the user that run and not the clock.
 */
@Slf4j
public class ClockworkStorage
{
	private static final String KEY = "routines";

	/**
	 * Where the named custom triggers sit inside that same blob.
	 */
	private static final String TRIGGERS_KEY = "triggers";

	/**
	 * What every key holding a clock's recorded runs starts with. The rest of
	 * the key is the clock's id, so one clock's runs are one key and a finished
	 * run rewrites one key.
	 *
	 * <p>Keys of their own rather than a field on a clock, so that the clocks
	 * blob is shareable as it stands. Keyed by id rather than by name, because
	 * a clock can be renamed and its history should follow it.
	 *
	 * <p>Every id is either generated or the built in clock's, which is a plain
	 * word, so nothing here has to be escaped to stand as a config key.
	 */
	private static final String HISTORY_PREFIX = "history_";

	/**
	 * What every key holding a clock's lifetime totals starts with, named the
	 * same way as the runs and holding the rest of what a clock remembers.
	 *
	 * <p>Two numbers, a count of completed runs and their summed duration. The
	 * key exists because the runs are capped and the totals are not, so once a
	 * run has been let go there is nowhere else an all time average could be
	 * read from. It is a fixed forty odd bytes however long the user plays,
	 * which is the shape core's Loot Tracker uses for the same problem.
	 *
	 * <p>Additive. A build that has never heard of this key never looks for it,
	 * and the runs it does look for are exactly where they always were, so the
	 * stored format has not moved and neither of its version stamps changes.
	 */
	private static final String TOTALS_PREFIX = "totals_";

	/**
	 * The single key every clock's runs shared, as a map from clock id to that
	 * clock's runs, in every build up to and including the fifth one published.
	 * Read by {@link #migrateHistory()} on every load, brought together with the
	 * keys above, and then unset.
	 *
	 * <p>Unset is not the end of it. A config profile is synced, and a build that
	 * predates the split writes this key while a build that follows it writes the
	 * keys above, so the same profile can hold both at once and this one can come
	 * back after it has been let go. That is why it is read every time rather
	 * than once.
	 */
	private static final String LEGACY_HISTORY_KEY = "history";

	/**
	 * Where the average window setting lives. Named here rather than left to
	 * the config annotation alone because {@link #clampAverageWindow()} has to
	 * rewrite a stored value that is now out of range, and a config item cannot
	 * do that for itself.
	 */
	private static final String AVERAGE_WINDOW_KEY = "averageWindow";

	/**
	 * Where the plugin wide timer box setting lives now, as one of three
	 * answers rather than as a yes or a no.
	 */
	private static final String OVERLAY_VISIBILITY_KEY = "overlayVisibility";

	/**
	 * The key that setting used to live under, as a boolean, in every build up
	 * to and including the first one published. Read once, moved onto the key
	 * above, and then unset.
	 */
	private static final String LEGACY_TIMER_BOX_KEY = "showTimerBox";

	/**
	 * Where the permanent history file lives. Written only after the user has
	 * picked a place through a file chooser, never typed in, which is why it is
	 * kept here rather than offered as a config item.
	 *
	 * <p>The name must not begin with the {@code history_} or {@code totals_}
	 * prefixes that {@link #keysWith(String)} scans for. A key under either of
	 * those reads to the reconcile as a clock whose id is the rest of the key,
	 * and {@link #forgetRunsExcept(Set)} unsets every such key whose id is not a
	 * live clock, so a path key named that way would be swept on the next wide
	 * save and the user would lose their chosen location. The character after
	 * {@code history} here is an F, not an underscore, so it is clear of both.
	 */
	private static final String HISTORY_PATH_KEY = "historyFilePath";

	/**
	 * The clock the hotkeys act on, as an id.
	 *
	 * <p>Kept here rather than offered as a config item because it is an id
	 * rather than something a user would type, and because it has to be
	 * persistent. It used to be the panel's selection, which is transient, so
	 * with the sidebar shut or straight after a restart there was nothing
	 * selected and the keys could only ever reach the built in clock.
	 *
	 * <p>Being a config key makes it per profile, which is what we want. A
	 * profile with different clocks in it gets its own designation, and the one
	 * that does not survive a switch is cleared.
	 *
	 * <p>A key of its own rather than a field on a clock, so nothing about the
	 * stored clocks moves. It is not part of the versioned blob and carries no
	 * stamp, which is affordable only because it has never existed before, so
	 * there is no old value anywhere to carry across.
	 */
	private static final String HOTKEY_TARGET_KEY = "hotkeyTargetId";

	private final ConfigManager configManager;
	private final Gson gson;

	/**
	 * Handed the real one as the plugin starts. Until then it writes nowhere,
	 * which saves a null check on every path below.
	 */
	private Diagnostics diagnostics = Diagnostics.none();

	@Inject
	public ClockworkStorage(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	public void setDiagnostics(Diagnostics diagnostics)
	{
		this.diagnostics = diagnostics == null ? Diagnostics.none() : diagnostics;
	}

	public Saved load()
	{
		// Before anything reads a key per clock, and here rather than beside
		// the plugin's other start up call because a config profile switch
		// comes back through this method and a profile that has never been
		// opened under this build has its runs on the old key. Every load, since
		// the old key can be written again after it has been read.
		migrateHistory();

		try
		{
			final Saved saved = decodeAll(gson, configManager.getConfiguration(ClockworkConfig.GROUP, KEY));

			// The runs come out of a key per clock and are put back on the
			// clocks they belong to, and the lifetime totals come off a second
			// key the same way. A clock with no stored totals is left at
			// nothing, and the controller counts it a set from the runs above
			// before it trims them.
			attachHistory(saved.getRoutines(), readHistory(saved.getRoutines()));
			attachTotals(saved.getRoutines(), readTotals(saved.getRoutines()));
			return saved;
		}
		catch (RuntimeException ex)
		{
			log.debug("could not read saved routines, starting empty", ex);
			diagnostics.record("storage.load", ex);
			return new Saved(new ArrayList<>(), TriggerLibrary.empty());
		}
	}

	/**
	 * The runs of every clock on the list, read a key at a time.
	 *
	 * <p>The keys are enumerated rather than worked out from the clock list, so
	 * that runs stored against a clock which is not on the list are noticed
	 * rather than invisible. They are left exactly where they are. A load is not
	 * the place to destroy the only copy of anything, and the wide save that
	 * every load is followed by is what reconciles the keys with the clock list.
	 */
	private Map<String, List<Run>> readHistory(List<Routine> routines)
	{
		final Map<String, List<Run>> history = new LinkedHashMap<>();
		final Set<String> known = idsOf(routines);

		int strays = 0;
		for (String key : keysWith(HISTORY_PREFIX))
		{
			final String routineId = key.substring(HISTORY_PREFIX.length());
			if (!known.contains(routineId))
			{
				strays++;
				continue;
			}

			history.put(routineId,
				decodeRuns(gson, configManager.getConfiguration(ClockworkConfig.GROUP, key)));
		}

		if (strays > 0)
		{
			log.debug("{} stored histories belong to a clock that is not on the list", strays);
		}
		return history;
	}

	/**
	 * The lifetime totals of every clock on the list, read a key at a time and
	 * on exactly the terms the runs above are read on.
	 *
	 * <p>A clock with no readable key is left out of the map, and the clock
	 * then keeps the nothing it arrived with. Nothing is written for a clock
	 * that has counted nothing, so an absent key and a stored zero are the same
	 * answer to everything downstream, and both leave the controller to count a
	 * set from whatever runs are stored.
	 */
	private Map<String, Totals> readTotals(List<Routine> routines)
	{
		final Map<String, Totals> totals = new LinkedHashMap<>();
		final Set<String> known = idsOf(routines);

		for (String key : keysWith(TOTALS_PREFIX))
		{
			final String routineId = key.substring(TOTALS_PREFIX.length());
			if (!known.contains(routineId))
			{
				continue;
			}

			final Totals stored = decodeTotals(gson,
				configManager.getConfiguration(ClockworkConfig.GROUP, key));
			if (stored != null)
			{
				totals.put(routineId, stored);
			}
		}
		return totals;
	}

	/**
	 * The ids of the clocks on the list, which is what says whether a stored
	 * key still belongs to anything.
	 */
	private static Set<String> idsOf(List<Routine> routines)
	{
		final Set<String> ids = new LinkedHashSet<>();
		if (routines == null)
		{
			return ids;
		}

		for (Routine routine : routines)
		{
			if (routine != null && routine.getId() != null && !routine.getId().trim().isEmpty())
			{
				ids.add(routine.getId());
			}
		}
		return ids;
	}

	/**
	 * Every key starting with the given prefix, as this plugin's own keys rather
	 * than as the whole keys the scan hands back.
	 *
	 * <p>A prefix scan is how RuneLite's own plugins enumerate a key per entity.
	 * It answers with the group and the key joined by a dot, so the group is
	 * taken off here and every caller sees a key it could pass straight back in.
	 *
	 * <p>The old single runs key is not one of these. It is {@code history} with
	 * nothing after it, and the prefix ends in an underscore, so a scan cannot
	 * mistake it for a clock whose id is empty.
	 */
	private List<String> keysWith(String prefix)
	{
		final String group = ClockworkConfig.GROUP + ".";
		final List<String> keys = new ArrayList<>();
		for (String whole : configManager.getConfigurationKeys(group + prefix))
		{
			if (whole != null && whole.length() > group.length() + prefix.length())
			{
				keys.add(whole.substring(group.length()));
			}
		}
		return keys;
	}

	/**
	 * The key one clock's runs live under, or null when the clock has no id to
	 * put them against.
	 *
	 * <p>A clock with no usable id has nowhere to store runs and its runs are
	 * lost on the next save, which is worth knowing about even though nothing in
	 * the plugin makes such a clock.
	 */
	static String historyKey(String routineId)
	{
		return routineId == null || routineId.trim().isEmpty() ? null : HISTORY_PREFIX + routineId;
	}

	/**
	 * The key one clock's lifetime totals live under, on the same terms.
	 */
	static String totalsKey(String routineId)
	{
		return routineId == null || routineId.trim().isEmpty() ? null : TOTALS_PREFIX + routineId;
	}

	/**
	 * Turns a stored blob back into routines.
	 *
	 * <p>Separate from {@link #load()} and free of the config manager so the
	 * decode can be tested against a real stored blob.
	 *
	 * <p>Nothing is refused for being damaged. A blob that will not bind in one
	 * go is read a clock at a time instead.
	 */
	static List<Routine> decode(Gson gson, String json)
	{
		return decodeAll(gson, json).getRoutines();
	}

	/**
	 * The clocks and the trigger library they point at, which come out of one
	 * blob and have to be read together.
	 *
	 * <p>Throws only when the text is not a JSON object at all, which is the
	 * one failure with nothing left to salvage. A blob that is an object but
	 * will not bind is taken apart by {@link #salvage} instead, so the caller
	 * gets the clocks that could be read rather than an exception and no
	 * clocks.
	 */
	static Saved decodeAll(Gson gson, String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return empty();
		}

		JsonObject root = gson.fromJson(json, JsonObject.class);
		if (root == null)
		{
			return empty();
		}

		// Branch on the stored version rather than on how a field looks. That
		// is the whole lesson of the last format change in this plugin, and it
		// is what the stamp is written for.
		final int version = version(root);
		if (version > RoutineMigration.CURRENT_VERSION)
		{
			// A blob written by a later build than this one, which is what a
			// downgrade looks like from here. Refusing it would cost the user
			// every clock they have, and a shape this build has not seen is
			// still mostly a shape it can read, so it is said out loud and
			// then bound as far as it will go.
			log.warn("stored clocks are stamped version {}, newer than the version this build writes ({}),"
				+ " so they are read as far as they will go", version, RoutineMigration.CURRENT_VERSION);
		}

		SavedState state;
		try
		{
			state = gson.fromJson(root, SavedState.class);
		}
		catch (RuntimeException ex)
		{
			// A bind failure is a value of the wrong JSON type, and there is
			// nothing this file can do to the tree that would change that.
			//
			// Refusing the whole blob would mean one clock nobody can read
			// costing the user every clock they have, which is the worst thing
			// this file could do. So it is said out loud and then taken apart
			// piece by piece instead.
			log.warn("stored clocks stamped version {} are not a shape this build can bind in one go,"
				+ " reading them one clock at a time instead", version);
			log.debug("could not bind the stored clocks", ex);
			state = salvage(gson, root);
		}

		if (state == null || state.routines == null)
		{
			return new Saved(new ArrayList<>(), TriggerLibrary.of(state == null ? null : state.triggers));
		}

		List<Routine> routines = new ArrayList<>(state.routines);
		TriggerLibrary library = TriggerLibrary.of(state.triggers);
		RoutineMigration.migrate(routines);
		return new Saved(routines, library);
	}

	/**
	 * What the old single key holds, as a map from clock id to that clock's
	 * runs. Never null, and never throws, because a damaged history is not a
	 * reason to lose the clocks it belongs to.
	 *
	 * <p>Read by {@link #migrateHistory()} alone. No build from the sixth one on
	 * writes this shape, but a profile can still gain one, either from a sync
	 * that carries an older value back or from an older build of the plugin
	 * running against the same profile, so this is read on every load rather
	 * than on the first one.
	 */
	static Map<String, List<Run>> decodeHistory(Gson gson, String json)
	{
		final Map<String, List<Run>> history = new LinkedHashMap<>();
		if (json == null || json.trim().isEmpty())
		{
			return history;
		}

		JsonObject root;
		try
		{
			root = gson.fromJson(json, JsonObject.class);
		}
		catch (RuntimeException ex)
		{
			log.debug("could not read the stored history", ex);
			return history;
		}

		if (root == null)
		{
			return history;
		}

		// Read a clock at a time rather than as one bound map, so a single
		// damaged entry costs that clock rather than costing every clock, and
		// then a run at a time below, so it costs that one run. It also keeps a
		// parameterised type out of this file, which a plugin reviewer should
		// not have to think about.
		for (Map.Entry<String, JsonElement> entry : root.entrySet())
		{
			try
			{
				history.put(entry.getKey(), runsIn(gson, entry.getValue()));
			}
			catch (RuntimeException ex)
			{
				log.debug("could not read the stored runs of clock {}", entry.getKey(), ex);
			}
		}
		return history;
	}

	/**
	 * What one clock's key holds, as that clock's runs. Never null, and never
	 * throws, for the same reason as above, one level further down.
	 */
	static List<Run> decodeRuns(Gson gson, String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return new ArrayList<>();
		}

		try
		{
			return runsIn(gson, gson.fromJson(json, JsonElement.class));
		}
		catch (RuntimeException ex)
		{
			log.debug("could not read a stored clock's runs", ex);
			return new ArrayList<>();
		}
	}

	/**
	 * What one clock's totals key holds, or null when there is nothing readable
	 * under it.
	 *
	 * <p>Null rather than a zeroed set, so a clock the key says nothing about
	 * is left exactly as it arrived rather than having a fresh object put on
	 * it. The two amount to the same figures either way, since a clock arrives
	 * counting nothing.
	 *
	 * <p>A damaged value, and a stored count or sum below zero, both read as
	 * nothing readable. That costs the user an exact lifetime count and gives
	 * them one taken from the runs still stored, which is the safe direction to
	 * be wrong in, and it keeps a negative out of the division behind the
	 * average.
	 */
	static Totals decodeTotals(Gson gson, String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return null;
		}

		try
		{
			final Totals totals = gson.fromJson(json, Totals.class);
			if (totals == null || totals.getCompletedRuns() < 0 || totals.getCompletedMillis() < 0)
			{
				return null;
			}
			return totals;
		}
		catch (RuntimeException ex)
		{
			log.debug("could not read a stored clock's totals", ex);
			return null;
		}
	}

	/**
	 * One clock's runs, from the array stored against its id.
	 *
	 * <p>Read a run at a time rather than as one bound array, for the same
	 * reason the clocks are read one at a time above. This key is the only copy
	 * of a user's runs there is, so one run of a shape this build cannot bind
	 * costs the user that one run and leaves the runs either side of it where
	 * they were.
	 *
	 * <p>Nulls inside are dropped, because a null run is nothing anybody can
	 * read, and what is left comes back in the order it was stored in, which is
	 * the order every statistic reads off.
	 */
	private static List<Run> runsIn(Gson gson, JsonElement stored)
	{
		final List<Run> kept = new ArrayList<>();
		if (stored == null || !stored.isJsonArray())
		{
			return kept;
		}

		for (JsonElement element : stored.getAsJsonArray())
		{
			try
			{
				final Run run = gson.fromJson(element, Run.class);
				if (run != null)
				{
					kept.add(run);
				}
			}
			catch (RuntimeException ex)
			{
				log.debug("could not read the stored run {}, it was dropped and the rest were kept",
					element, ex);
			}
		}
		return kept;
	}

	/**
	 * Puts each clock's runs back on it.
	 *
	 * <p>A clock the map says nothing about keeps whatever it already has,
	 * which is what a clock with no runs recorded yet looks like from here.
	 */
	static void attachHistory(List<Routine> routines, Map<String, List<Run>> history)
	{
		if (routines == null || history == null || history.isEmpty())
		{
			return;
		}

		for (Routine routine : routines)
		{
			if (routine == null || routine.getId() == null)
			{
				continue;
			}

			final List<Run> runs = history.get(routine.getId());
			if (runs == null)
			{
				continue;
			}

			final List<Run> kept = new ArrayList<>();
			for (Run run : runs)
			{
				if (run != null)
				{
					kept.add(run);
				}
			}
			routine.setHistory(kept);
		}
	}

	/**
	 * Puts each clock's lifetime totals back on it.
	 *
	 * <p>A clock the map says nothing about is left exactly as it arrived,
	 * which is at nothing, and the controller is what counts it a set from the
	 * runs it also arrived with.
	 */
	static void attachTotals(List<Routine> routines, Map<String, Totals> totals)
	{
		if (routines == null || totals == null || totals.isEmpty())
		{
			return;
		}

		for (Routine routine : routines)
		{
			if (routine == null || routine.getId() == null)
			{
				continue;
			}

			final Totals stored = totals.get(routine.getId());
			if (stored != null)
			{
				routine.setTotals(stored);
			}
		}
	}

	private static Saved empty()
	{
		return new Saved(new ArrayList<>(), TriggerLibrary.empty());
	}

	/**
	 * The version the blob says it is, or 0 when it does not say.
	 *
	 * <p>Read in three places, by the decode to notice a blob from a newer
	 * build than this one, by the salvage to carry the stamp onto what it
	 * manages to rescue, and by {@link ClockworkDocument}, which reads the same
	 * stamp off the same shape of blob. Two readers that could disagree about a
	 * missing or damaged version is exactly the kind of quiet split this file
	 * exists to avoid, so it is package private rather than copied.
	 */
	/**
	 * The oldest build the document says can read it, or its own version when
	 * it does not say.
	 *
	 * <p>Falling back to the version rather than to zero is the conservative
	 * way round. A document written before this stamp existed, or one with the
	 * key stripped out, is then judged exactly as strictly as it would have
	 * been before, rather than claiming every build can read it.
	 */
	static int minimumReader(JsonObject root)
	{
		try
		{
			JsonElement stored = root.get("minVersion");
			if (stored == null || !stored.isJsonPrimitive())
			{
				return version(root);
			}
			return stored.getAsInt();
		}
		catch (RuntimeException ex)
		{
			return version(root);
		}
	}

	static int version(JsonObject root)
	{
		try
		{
			JsonElement stored = root.get("version");
			if (stored == null || !stored.isJsonPrimitive())
			{
				return 0;
			}
			return stored.getAsInt();
		}
		catch (RuntimeException ex)
		{
			return 0;
		}
	}

	/**
	 * What can still be read out of a blob Gson would not bind in one go.
	 *
	 * <p>The rule is to lose the unreadable part rather than the document. One
	 * value of the wrong JSON type anywhere in the blob fails the whole bind,
	 * so the blob is taken apart instead. The library is read on its own, and
	 * then every clock is read on its own, so a clock nobody can read costs the
	 * user that clock rather than all of them.
	 *
	 * <p>Never throws. A caller that reaches this has already been told the
	 * ordinary bind failed, and a second failure here would put it back where
	 * it started.
	 */
	private static SavedState salvage(Gson gson, JsonObject root)
	{
		final SavedState state = new SavedState();
		state.version = version(root);
		state.triggers = storedTriggers(gson, root);
		state.routines = new ArrayList<>();

		final JsonElement array = root.get(KEY);
		if (array == null || !array.isJsonArray())
		{
			return state;
		}

		for (JsonElement element : array.getAsJsonArray())
		{
			if (element == null || !element.isJsonObject())
			{
				continue;
			}

			final Routine routine = salvageRoutine(gson, element.getAsJsonObject());
			if (routine != null)
			{
				state.routines.add(routine);
			}
		}
		return state;
	}

	/**
	 * One clock out of a blob that would not bind, or null when there is
	 * nothing left of it worth keeping.
	 *
	 * <p>The clock is tried as it stands first, because most clocks in a
	 * damaged blob are fine and it was a neighbour that failed the bind.
	 *
	 * <p>If that fails, it is tried again without each trigger in turn, and
	 * then without any of the three. A trigger is an object where every other
	 * field on a clock is a string, a number, or a boolean, so it is much the
	 * likeliest thing to have failed. Dropping one at a time rather than all at
	 * once means a clock with one unreadable trigger keeps the other two. A
	 * clock that comes back waiting for nothing still has its name, its
	 * direction, its target, and its recorded runs, which is a far smaller loss
	 * than the clock itself.
	 *
	 * <p>Only if all five fail is the clock dropped, and the log says which
	 * clock went and what it cost either way.
	 */
	private static Routine salvageRoutine(Gson gson, JsonObject stored)
	{
		final String name = text(stored, "name");
		try
		{
			return gson.fromJson(stored, Routine.class);
		}
		catch (RuntimeException ex)
		{
			log.debug("could not read clock {} as it stands", name, ex);
		}

		String lost = "the trigger it started on";
		Routine salvaged = boundWithout(gson, stored, "startTrigger");
		if (salvaged == null)
		{
			lost = "the trigger it stopped on";
			salvaged = boundWithout(gson, stored, "stopTrigger");
		}
		if (salvaged == null)
		{
			lost = "the trigger it lapped on";
			salvaged = boundWithout(gson, stored, "lapTrigger");
		}
		if (salvaged == null)
		{
			lost = "any of its triggers";
			salvaged = boundWithout(gson, stored, "startTrigger", "stopTrigger", "lapTrigger");
		}

		if (salvaged == null)
		{
			log.warn("the clock named {} could not be read at all and was dropped,"
				+ " the rest of the clocks were kept", name);
			return null;
		}

		log.warn("the clock named {} came back without {}, because what it stored there is not a"
			+ " shape this build can read", name, lost);
		return salvaged;
	}

	/**
	 * The clock as it binds once the named keys are taken off it, or null when
	 * it still will not bind. The copy is what keeps the caller free to try
	 * another combination against the original.
	 */
	private static Routine boundWithout(Gson gson, JsonObject stored, String... keys)
	{
		final JsonObject trimmed = stored.deepCopy();
		for (String key : keys)
		{
			trimmed.remove(key);
		}

		try
		{
			return gson.fromJson(trimmed, Routine.class);
		}
		catch (RuntimeException ex)
		{
			log.debug("could not read clock {} without {}", text(stored, "name"), Arrays.toString(keys), ex);
			return null;
		}
	}

	/**
	 * What the blob holds in its library, read on its own rather than as part
	 * of the whole blob.
	 *
	 * <p>Used only by the salvage below, which is reached when binding the blob
	 * in one go has already failed. Reading the library separately means a
	 * clock nobody can read does not also cost the user every saved trigger
	 * those clocks pointed at.
	 */
	private static List<SavedTrigger> storedTriggers(Gson gson, JsonObject root)
	{
		JsonElement stored = root.get(TRIGGERS_KEY);
		if (stored == null || !stored.isJsonArray())
		{
			return new ArrayList<>();
		}

		try
		{
			SavedTrigger[] entries = gson.fromJson(stored, SavedTrigger[].class);
			return entries == null ? new ArrayList<>() : new ArrayList<>(Arrays.asList(entries));
		}
		catch (RuntimeException ex)
		{
			// A damaged library is not a reason to lose the clocks. The clocks
			// then come back pointing at names nothing accounts for, which
			// resolves to Nothing, and that is the safe direction to be wrong
			// in.
			log.warn("the stored trigger library could not be read, so every saved trigger in it is lost");
			log.debug("could not read the stored trigger library", ex);
			return new ArrayList<>();
		}
	}

	/**
	 * A string field, or null when it is absent, is not a string, or is blank.
	 */
	private static String text(JsonObject object, String key)
	{
		JsonElement stored = object.get(key);
		if (stored == null || !stored.isJsonPrimitive() || !stored.getAsJsonPrimitive().isString())
		{
			return null;
		}

		final String value = stored.getAsString().trim();
		return value.isEmpty() ? null : value;
	}

	/**
	 * Moves the plugin wide timer box setting off the old boolean and onto the
	 * three way one, once, for a user upgrading from a build that had the
	 * boolean.
	 *
	 * <p>A config key is not the versioned blob and carries no version of its
	 * own, so renaming one with nothing to carry the old value across is a
	 * silent reset of everybody's setting. This is what carries it.
	 *
	 * <p>Nothing happens for a user who has already been migrated, and nothing
	 * happens for a user who never touched the old setting, who gets the new
	 * default instead. Runs before anything reads the setting, so the first
	 * frame after an update is already drawn from the moved value.
	 */
	public void migrateOverlayVisibility()
	{
		try
		{
			if (isSet(configManager.getConfiguration(ClockworkConfig.GROUP, OVERLAY_VISIBILITY_KEY)))
			{
				return;
			}

			final String legacy = configManager.getConfiguration(ClockworkConfig.GROUP, LEGACY_TIMER_BOX_KEY);
			if (!isSet(legacy))
			{
				return;
			}

			configManager.setConfiguration(ClockworkConfig.GROUP, OVERLAY_VISIBILITY_KEY, movedVisibility(legacy));
			configManager.unsetConfiguration(ClockworkConfig.GROUP, LEGACY_TIMER_BOX_KEY);
		}
		catch (RuntimeException ex)
		{
			log.debug("could not migrate the timer box setting", ex);
			diagnostics.record("storage.migrateOverlayVisibility", ex);
		}
	}

	/**
	 * What the old boolean means under the new setting.
	 *
	 * <p>The old one answered "show a timer box for every clock that is
	 * running", so on is today's only while running and off is never. Nobody's
	 * setting changes meaning across the update, which is the whole point of
	 * the move.
	 *
	 * <p>Anything that is neither reads as on, because on is what the old
	 * setting defaulted to and a value nobody can parse is not evidence that
	 * the user asked for the boxes to go away.
	 *
	 * <p>Pure and package private, so the mapping can be tested without a
	 * config manager behind it.
	 */
	static OverlayMode movedVisibility(String legacy)
	{
		return legacy != null && "false".equalsIgnoreCase(legacy.trim())
			? OverlayMode.NEVER
			: OverlayMode.WHILE_RUNNING;
	}

	/**
	 * Brings a stored average window down to the most this build can honour.
	 *
	 * <p>The setting used to go up to fifty, because a clock used to keep its
	 * newest fifty runs. It keeps its newest ten now, so a window above ten has
	 * nothing behind it, and a user who had set thirty would have had it quietly
	 * answered as ten from here on with the config panel still reading thirty.
	 * A setting that says one thing and does another is worse than a setting
	 * that changed, so this changes it.
	 *
	 * <p>What a user sees is the number in the config panel moved to ten the
	 * first time they start this build, and an average that is over ten runs and
	 * says so. Anybody at ten or below, which is everybody who never touched it,
	 * sees nothing at all.
	 *
	 * <p>Only the top is brought in. The old range started at one as well, so
	 * there is no stored value below the new minimum anywhere to carry.
	 *
	 * <p>A value that is not a number is left exactly where it is. RuneLite
	 * answers the default for one of those, so it is already being read as ten,
	 * and rewriting it would be this method inventing a setting rather than
	 * carrying one.
	 */
	public void clampAverageWindow()
	{
		try
		{
			final String stored = configManager.getConfiguration(ClockworkConfig.GROUP, AVERAGE_WINDOW_KEY);
			if (!isSet(stored) || Integer.parseInt(stored.trim()) <= RunHistory.RECENT_KEPT)
			{
				return;
			}

			log.debug("the average window was set past what a clock now keeps, bringing it down to {}",
				RunHistory.RECENT_KEPT);
			configManager.setConfiguration(ClockworkConfig.GROUP, AVERAGE_WINDOW_KEY,
				String.valueOf(RunHistory.RECENT_KEPT));
		}
		catch (RuntimeException ex)
		{
			log.debug("could not bring the average window into range", ex);
			diagnostics.record("storage.clampAverageWindow", ex);
		}
	}

	/**
	 * Whether a config key holds anything. Absent and blank are the same
	 * answer, since a blank is what a key that has been unset reads as.
	 */
	private static boolean isSet(String value)
	{
		return value != null && !value.trim().isEmpty();
	}

	/**
	 * Brings the recorded runs on the one key every clock's runs used to share
	 * together with the key per clock they live on now, so that a user holding
	 * runs under both layouts keeps every one of them.
	 *
	 * <p>A config key is not the versioned blob and carries no version of its
	 * own, so splitting one with nothing to carry the old value across is a
	 * silent loss of everybody's runs. This is what carries them. The shape of a
	 * stored run does not move, only which key it sits under, so the blob's
	 * version stamp has nothing to say about this and does not change.
	 *
	 * <p><b>Every load, not once.</b> A move from one key to many is not
	 * something that either has or has not happened, since part of it happening
	 * is an ordinary state, and the old key can be written again after the move
	 * has run. A config profile is synced, so a value unset here comes back from
	 * the server on a later login, and a build that predates the split writes the
	 * old key while a build that follows it writes the new ones, which is one
	 * downgrade away and is a second client on the same profile away. A guard
	 * that stopped as soon as any clock had a key of its own left whatever was
	 * under the old key unread for good, and that reads to a user as runs they
	 * can see in their config and cannot see in the panel.
	 *
	 * <p><b>Together, not one over the other.</b> Each key can hold runs the
	 * other does not, in either direction, so a clock ends up with the runs of
	 * both and a run found under both is kept once. See
	 * {@link #merge(List, List)} for what makes two stored runs the same run and
	 * for the order they come back in.
	 *
	 * <p>Every clock is written on its own, so one clock nobody can write costs
	 * that clock rather than all of them, and the old key is let go only when
	 * every one of them landed. A user whose move was part refused keeps the old
	 * key and has the rest of it brought across on the next load. A clock whose
	 * own key already holds everything the old key holds for it is not written at
	 * all, so a load with nothing to carry across writes nothing.
	 */
	public void migrateHistory()
	{
		try
		{
			final String legacy = configManager.getConfiguration(ClockworkConfig.GROUP, LEGACY_HISTORY_KEY);
			if (!isSet(legacy))
			{
				return;
			}

			boolean everyClockLanded = true;
			for (Map.Entry<String, List<Run>> entry : decodeHistory(gson, legacy).entrySet())
			{
				final String key = historyKey(entry.getKey());
				if (key == null || entry.getValue() == null || entry.getValue().isEmpty())
				{
					// A clock the old key records nothing for has nothing to
					// bring across, and one with no usable id has nowhere to
					// bring it to.
					continue;
				}

				try
				{
					final List<Run> stored = decodeRuns(gson,
						configManager.getConfiguration(ClockworkConfig.GROUP, key));
					final List<Run> merged = merge(stored, entry.getValue());

					// Untouched when the clock's own key already holds all of it,
					// which is what the old key coming back unchanged looks like.
					// A write here would be a whole history in the next sync for
					// every clock, on every load, for nothing.
					if (!merged.equals(stored))
					{
						configManager.setConfiguration(ClockworkConfig.GROUP, key, gson.toJson(merged));
					}
				}
				catch (RuntimeException ex)
				{
					everyClockLanded = false;
					log.debug("could not bring the recorded runs of clock {} together", entry.getKey(), ex);
				}
			}

			if (everyClockLanded)
			{
				configManager.unsetConfiguration(ClockworkConfig.GROUP, LEGACY_HISTORY_KEY);
			}
		}
		catch (RuntimeException ex)
		{
			log.debug("could not bring the recorded runs onto a key per clock", ex);
			diagnostics.record("storage.migrateHistory", ex);
		}
	}

	/**
	 * One clock's runs from both layouts as one list, oldest first, with a run
	 * that is under both of them in it once.
	 *
	 * <h2>What makes two stored runs the same run</h2>
	 *
	 * <p>The three times a run carries, which are when it started, when it
	 * ended, and how long it took. One clock has one run at a time, so two
	 * attempts cannot agree on all three, and a match is therefore the same
	 * attempt written to both keys rather than two attempts that look alike.
	 *
	 * <p>The start on its own would answer for anything this plugin has ever
	 * recorded, since a run always carries the moment it began. It is not enough
	 * for a stored blob that carries no times at all, which is what a hand
	 * written config reads as, because every run in one of those began at zero
	 * and they would fold into a single run. Reading all three keeps them apart.
	 *
	 * <p>Only the old key's runs are held against that. Whatever the clock's own
	 * key holds is kept exactly as it stands, since neither key was ever written
	 * with one run in it twice, and two runs inside one key that look alike are
	 * two runs the user did.
	 *
	 * <h2>The order they come back in</h2>
	 *
	 * <p>By when each run started, so the newest is at the end wherever it was
	 * found. Everything that reads a clock's runs reads that order, the newest
	 * ten and the last completed run included, so appending a key's worth of
	 * older runs after a newer one would quietly change which run the panel
	 * calls the latest. The sort is stable, so runs carrying the same start time
	 * stay in the order they were found in, which is the clock's own key first.
	 *
	 * @param stored what the clock's own key holds, which may be nothing
	 * @param legacy what the old shared key holds for that clock
	 * @return the runs of both, oldest first
	 */
	static List<Run> merge(List<Run> stored, List<Run> legacy)
	{
		final List<Run> merged = new ArrayList<>();
		final Set<String> alreadyOnItsOwnKey = new LinkedHashSet<>();

		if (stored != null)
		{
			for (Run run : stored)
			{
				if (run != null)
				{
					merged.add(run);
					alreadyOnItsOwnKey.add(theSameRunAs(run));
				}
			}
		}

		if (legacy != null)
		{
			for (Run run : legacy)
			{
				if (run != null && !alreadyOnItsOwnKey.contains(theSameRunAs(run)))
				{
					merged.add(run);
				}
			}
		}

		merged.sort(Comparator.comparingLong(Run::getStartedAtEpochMillis));
		return merged;
	}

	/**
	 * What two stored runs have to agree on to be one run. See
	 * {@link #merge(List, List)} for why it is these three.
	 */
	private static String theSameRunAs(Run run)
	{
		return run.getStartedAtEpochMillis() + ":" + run.getFinishedAtEpochMillis()
			+ ":" + run.getDurationMillis();
	}

	/**
	 * Writes the settings and every clock's runs, and takes away the runs of
	 * clocks that are not on the list any more.
	 *
	 * <p>The settings and the runs are guarded separately, so a failure to write
	 * one does not throw the other away with it, and each clock's runs are
	 * guarded again on their own, so one clock nobody can write costs the user
	 * that clock rather than all of them.
	 *
	 * <p>This is the wide write, for the changes that can move any part of it,
	 * which are a clock arriving, leaving, being renamed, or being reconfigured.
	 * All of those are a user clicking something, so there are a handful of them
	 * in a session. A finished run goes through {@link #saveHistory(Routine)}
	 * instead, which touches one key.
	 */
	public void save(List<Routine> routines, TriggerLibrary library)
	{
		try
		{
			configManager.setConfiguration(ClockworkConfig.GROUP, KEY,
				encodeRoutines(gson, routines, library));
		}
		catch (RuntimeException ex)
		{
			log.debug("could not write routines", ex);
			diagnostics.record("storage.save", ex);
		}

		final Set<String> live = idsOf(routines);
		if (routines != null)
		{
			for (Routine routine : routines)
			{
				saveHistory(routine);
			}
		}
		forgetRunsExcept(live);
	}

	/**
	 * Writes one clock's runs and its lifetime totals, and touches nothing
	 * else.
	 *
	 * <p>This is the write a finished run goes through, and it is the whole
	 * reason the runs sit under a key per clock. A run recorded through the wide
	 * write above re-encoded every clock's runs rather than the runs of the one
	 * clock that gained one, and under the old single key it put all of them in
	 * the next sync as well.
	 *
	 * <p>Both keys, because a clock's runs and its lifetime count change on the
	 * same events and are announced as one. Ending a run moves the list and
	 * usually the count as well, an abandoned one moves only the list, and
	 * clearing a clock empties both. Writing them from one place is what stops
	 * a caller having to know which of those it just did.
	 *
	 * <p>A clock with no runs left has its key taken away rather than written as
	 * an empty list, so clearing a clock leaves nothing behind and a clock
	 * nobody has run yet costs nothing at all. Its totals go the same way, since
	 * a count of nothing is what an absent key already means.
	 */
	public void saveHistory(Routine routine)
	{
		final String key = historyKey(routine == null ? null : routine.getId());
		if (key == null)
		{
			return;
		}

		try
		{
			if (routine.historyOrEmpty().isEmpty())
			{
				configManager.unsetConfiguration(ClockworkConfig.GROUP, key);
			}
			else
			{
				configManager.setConfiguration(ClockworkConfig.GROUP, key, encodeRuns(gson, routine));
			}
		}
		catch (RuntimeException ex)
		{
			log.debug("could not write the recorded runs of clock {}", routine.getId(), ex);
			diagnostics.record("storage.saveHistory", ex);
		}

		// Guarded on its own, because a clock whose runs could not be written
		// has no reason to lose its lifetime count as well.
		try
		{
			if (routine.totalsOrZero().isEmpty())
			{
				configManager.unsetConfiguration(ClockworkConfig.GROUP, totalsKey(routine.getId()));
			}
			else
			{
				configManager.setConfiguration(ClockworkConfig.GROUP, totalsKey(routine.getId()),
					encodeTotals(gson, routine));
			}
		}
		catch (RuntimeException ex)
		{
			log.debug("could not write the lifetime totals of clock {}", routine.getId(), ex);
			diagnostics.record("storage.saveTotals", ex);
		}
	}

	/**
	 * Takes away everything stored against a clock that is not on the list any
	 * more, which means its runs and its lifetime totals both.
	 *
	 * <p>Reconciled against the clock list rather than hung off a delete, so
	 * that every way a clock can leave is covered by one rule. Deleting one is
	 * not the only way. Applying an edited document replaces the whole list, and
	 * the clocks it drops leave the same way. It is also exactly what the single
	 * key did, since that key was rebuilt from the clock list on every save, so
	 * nothing about which runs survive a change has moved.
	 *
	 * <p>Both prefixes are scanned rather than only the runs. A reconcile that
	 * knew about one of them would leave a totals key behind for every clock the
	 * user ever deleted, and nothing would ever come back for it.
	 *
	 * @param liveIds the ids of the clocks that are still on the list
	 */
	private void forgetRunsExcept(Set<String> liveIds)
	{
		try
		{
			forgetExcept(HISTORY_PREFIX, liveIds);
			forgetExcept(TOTALS_PREFIX, liveIds);
		}
		catch (RuntimeException ex)
		{
			log.debug("could not take away what is stored against clocks that are gone", ex);
			diagnostics.record("storage.forgetHistory", ex);
		}
	}

	private void forgetExcept(String prefix, Set<String> liveIds)
	{
		for (String key : keysWith(prefix))
		{
			if (!liveIds.contains(key.substring(prefix.length())))
			{
				configManager.unsetConfiguration(ClockworkConfig.GROUP, key);
			}
		}
	}

	/**
	 * The settings blob exactly as a save writes it. Separate from the write
	 * itself, and free of the config manager, so a round trip can be tested
	 * against the real encoder rather than against a hand written blob.
	 */
	static String encodeRoutines(Gson gson, List<Routine> routines, TriggerLibrary library)
	{
		SavedState state = new SavedState();
		state.version = RoutineMigration.CURRENT_VERSION;
		state.minVersion = RoutineMigration.MINIMUM_READER_VERSION;
		state.routines = routines == null ? Collections.emptyList() : routines;
		state.triggers = library == null ? Collections.emptyList() : library.asStored();
		return gson.toJson(state);
	}

	/**
	 * One clock's runs exactly as a save writes them, for the same reason.
	 */
	static String encodeRuns(Gson gson, Routine routine)
	{
		return gson.toJson(routine == null ? Collections.emptyList() : routine.historyOrEmpty());
	}

	/**
	 * One clock's lifetime totals exactly as a save writes them.
	 */
	static String encodeTotals(Gson gson, Routine routine)
	{
		return gson.toJson(routine == null ? new Totals() : routine.totalsOrZero());
	}

