	/**
	 * Wrapper around the routine list. The version field is what a format
	 * change branches on, and {@link RoutineMigration} owns what it is worth
	 * now.
	 */
	static class SavedState
	{
		int version;

		/**
		 * The oldest build that can read this correctly. Absent on anything
		 * written before it existed, which readers treat as equal to
		 * {@link #version} so an unstamped document is judged the strict way.
		 */
		int minVersion;

		List<Routine> routines;

		/**
		 * The named custom triggers clocks point at. Absent when the user has
		 * never made one, which the decode reads as an empty library.
		 */
		List<SavedTrigger> triggers;
	}

	/**
	 * What one read of the blob produced. The two halves are handed over
	 * together because a clock that points at a library entry is only readable
	 * beside the library it points into.
	 */
	static final class Saved
	{
		private final List<Routine> routines;
		private final TriggerLibrary library;

		Saved(List<Routine> routines, TriggerLibrary library)
		{
			this.routines = routines == null ? new ArrayList<>() : routines;
			this.library = library == null ? TriggerLibrary.empty() : library;
		}

		List<Routine> getRoutines()
		{
			return routines;
		}

		TriggerLibrary getLibrary()
		{
			return library;
		}
	}
}

package com.clockwork;

import com.google.gson.JsonElement;
import com.google.gson.JsonPrimitive;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * One thing wrong with a document, and enough about where it is that somebody
 * can go and fix it.
 *
 * <p>Refusing a document with one sentence is a bad handler. Somebody hand
 * editing a page of JSON wants every problem in it at once, each one with a
 * place attached, so they can make one pass over the text rather than one pass
 * per mistake. So every path that reads a document collects these rather than
 * stopping at the first thing it does not like.
 *
 * <h2>How much of a location there is</h2>
 *
 * <p>Three kinds of problem, and each knows a different amount about where it
 * lives. That is not a design choice, it is what the parser hands over.
 *
 * <ul>
 *   <li><b>Syntax.</b> Gson throws before anything is bound and its message
 *   carries a line and a column, which is the most useful location of the
 *   three because it points straight at a character in the box</li>
 *   <li><b>Binding.</b> The blob parsed but a value is the wrong sort of
 *   thing. Gson's message carries a JSON path such as
 *   {@code $.routines[2].mode} and no line, because by then it is reading a
 *   tree rather than text. The path is turned into a clock number and a field
 *   name, since {@code routines[2]} is not something a user should have to
 *   decode</li>
 *   <li><b>Semantic.</b> Everything this plugin works out for itself, such as
 *   a trigger reference nothing defines. We generate these, so they can say
 *   exactly what they mean</li>
 * </ul>
 *
 * <p>Pure, and deliberately so. No Swing and no client, so the wording is
 * testable, and the panel renders a list it is handed rather than writing
 * sentences of its own.
 *
 * <h2>Wording</h2>
 *
 * <p>A problem with a location reads as "location: detail", so the detail is
 * written as a lower case fragment that follows a colon. A problem with no
 * location has the detail as the whole line, so those are written as ordinary
 * sentences. That is the only reason the two are punctuated differently.
 */
public final class DocumentProblem
{
	private final int line;
	private final int column;
	private final int number;
	private final String name;
	private final String field;
	private final String detail;
	private final boolean skipped;

	private DocumentProblem(int line, int column, int number, String name, String field,
		String detail, boolean skipped)
	{
		this.line = Math.max(line, 0);
		this.column = Math.max(column, 0);
		this.number = Math.max(number, 0);
		this.name = blank(name) ? null : name.trim();
		this.field = blank(field) ? null : field.trim();
		this.detail = detail == null ? "" : detail.trim();
		this.skipped = skipped;
	}

	/**
	 * Something wrong with the document as a whole, with nowhere in particular
	 * to point at. Worded as a full sentence, because it is the whole line.
	 */
	public static DocumentProblem inDocument(String detail)
	{
		return new DocumentProblem(0, 0, 0, null, null, detail, false);
	}

	/**
	 * Something wrong at a place in the text. Only the parser knows this much,
	 * and only before anything is bound.
	 */
	public static DocumentProblem at(int line, int column, String detail)
	{
		return new DocumentProblem(line, column, 0, null, null, detail, false);
	}

	/**
	 * Something wrong with one clock.
	 *
	 * @param number the clock's position in the document, counting from one,
	 * because the user counts from one and nobody outside a debugger reads
	 * {@code routines[2]}
	 * @param name the clock's own name where the document gives one, which is
	 * what the user actually recognises it by, or null
	 */
	public static DocumentProblem inClock(int number, String name, String detail)
	{
		return new DocumentProblem(0, 0, number, name, null, detail, false);
	}

	/**
	 * Something wrong with one field of one clock. The field is the key as the
	 * document spells it, so the user can search the text for it.
	 */
	public static DocumentProblem inField(int number, String name, String field, String detail)
	{
		return new DocumentProblem(0, 0, number, name, field, detail, false);
	}

	/**
	 * A clock that could not be read at all, and therefore is not going to
	 * arrive.
	 *
	 * <p>Marked rather than merely worded, so a count of the clocks that will
	 * not arrive is a count of something true rather than of lines that happen
	 * to mention it. Skipping is not new behaviour and is not changed by any of
	 * this. Losing one clock is far better than losing the document it was in.
	 * What is new is that the user is told.
	 */
	public static DocumentProblem skippedClock(int number, String name, String field, String detail)
	{
		return new DocumentProblem(0, 0, number, name, field, detail, true);
	}

	/**
	 * Whether this problem means a clock in the document does not arrive at
	 * all.
	 */
	public boolean isSkipped()
	{
		return skipped;
	}

	/**
	 * How many of these mean a clock does not arrive.
	 */
	public static int skippedCount(List<DocumentProblem> problems)
	{
		int count = 0;
		if (problems == null)
		{
			return count;
		}

		for (DocumentProblem problem : problems)
		{
			if (problem != null && problem.isSkipped())
			{
				count++;
			}
		}
		return count;
	}

	/**
	 * The line in the text, counting from one, or zero when this problem is
	 * not something the parser found at a place in the text.
	 */
	public int getLine()
	{
		return line;
	}

	public int getColumn()
	{
		return column;
	}

	/**
	 * Which clock, counting from one, or zero when the problem is not about
	 * one clock.
	 */
	public int getNumber()
	{
		return number;
	}

	/**
	 * The clock's name as the document gives it, or null when it does not give
	 * one.
	 */
	public String getName()
	{
		return name;
	}

	public String getField()
	{
		return field;
	}

	public String getDetail()
	{
		return detail;
	}

	/**
	 * Where this problem is, in the user's terms, or an empty string when
	 * there is nowhere to point at.
	 */
	public String location()
	{
		final StringBuilder where = new StringBuilder();
		if (line > 0)
		{
			where.append("Line ").append(line);
			if (column > 0)
			{
				where.append(", column ").append(column);
			}
			return where.toString();
		}

		if (number > 0)
		{
			where.append("Clock ").append(number);
			if (name != null)
			{
				where.append(" \"").append(name).append('"');
			}
		}

		if (field != null)
		{
			where.append(where.length() == 0 ? "Field " : ", field ").append(field);
		}
		return where.toString();
	}

	/**
	 * The whole thing as one line, location first, because a list of these is
	 * read down the left hand edge.
	 */
	public String describe()
	{
		final String where = location();
		if (where.isEmpty())
		{
			return detail;
		}
		return detail.isEmpty() ? where : where + ": " + detail;
	}

	@Override
	public String toString()
	{
		return describe();
	}

	// Reading a list of them

	/**
	 * Every problem as its own line, in the order given. The one place the
	 * lines are joined, so the dialog, the editor, and the refusal all read the
	 * same.
	 */
	public static String lines(List<DocumentProblem> problems)
	{
		final StringBuilder text = new StringBuilder();
		if (problems == null)
		{
			return "";
		}

		for (DocumentProblem problem : problems)
		{
			if (problem == null)
			{
				continue;
			}

			if (text.length() > 0)
			{
				text.append('\n');
			}
			text.append(problem.describe());
		}
		return text.toString();
	}

	/**
	 * The first line number anything in the list carries, or zero when none of
	 * them is a place in the text. The editor uses it to put the caret where
	 * the trouble is.
	 */
	public static int firstLine(List<DocumentProblem> problems)
	{
		if (problems == null)
		{
			return 0;
		}

		for (DocumentProblem problem : problems)
		{
			if (problem != null && problem.getLine() > 0)
			{
				return problem.getLine();
			}
		}
		return 0;
	}

	/**
	 * The list in the order somebody reads the document, which is the clocks in
	 * turn with anything about the document as a whole in front of them.
	 *
	 * <p>Sorted rather than appended in order because the problems come from
	 * two passes over the same document, one that binds and one that checks
	 * what bound, and a user should not have to know that. The sort is stable,
	 * so two problems with the same clock stay in the order they were found.
	 */
	public static List<DocumentProblem> inReadingOrder(List<DocumentProblem> problems)
	{
		final List<DocumentProblem> ordered = new ArrayList<>();
		if (problems == null)
		{
			return ordered;
		}

		for (DocumentProblem problem : problems)
		{
			if (problem != null)
			{
				ordered.add(problem);
			}
		}

		ordered.sort((left, right) -> Integer.compare(left.getNumber(), right.getNumber()));
		return ordered;
	}

	// The vocabulary the parser's own messages are translated into

	/**
	 * What a value in the document is, said as a person would say it. Used for
	 * the "found" half of a message, and it reads the value itself rather than
	 * a token name, so a wrong number comes back as the number the user typed.
	 */
	public static String found(JsonElement value)
	{
		if (value == null || value.isJsonNull())
		{
			return "nothing";
		}

		if (value.isJsonObject())
		{
			return "an object";
		}

		if (value.isJsonArray())
		{
			return "a list";
		}

		final JsonPrimitive primitive = value.getAsJsonPrimitive();
		if (primitive.isString())
		{
			return '"' + primitive.getAsString() + '"';
		}
		return primitive.getAsString();
	}

	/**
	 * What the reader wanted at the point it gave up, said as a person would
	 * say it, or null when its complaint does not say.
	 *
	 * <p>Gson words this two ways depending on which reader threw, token names
	 * such as {@code BEGIN_OBJECT} from one and English such as
	 * {@code a long} from the other, so both are read here. A number that will
	 * not parse arrives as a {@code NumberFormatException} with no "expected"
	 * half at all, and that one is the only case where the wanted type can be
	 * known from the exception's class alone.
	 */
	public static String expected(Throwable ex)
	{
		for (Throwable cause = ex; cause != null; cause = cause.getCause())
		{
			if (cause instanceof NumberFormatException)
			{
				return "a number";
			}
		}

		for (Throwable cause = ex; cause != null; cause = cause.getCause())
		{
			final String wanted = wanted(cause.getMessage());
			if (wanted != null)
			{
				return wanted;
			}
		}
		return null;
	}

	private static String wanted(String message)
	{
		if (message == null)
		{
			return null;
		}

		final int start = message.indexOf("Expected ");
		final int end = message.indexOf(" but was ");
		if (start < 0 || end <= start)
		{
			return null;
		}

		final String token = message.substring(start + "Expected ".length(), end).toUpperCase(Locale.ROOT);
		if (token.contains("OBJECT"))
		{
			return "an object";
		}
		if (token.contains("ARRAY"))
		{
			return "a list";
		}
		if (token.contains("STRING"))
		{
			return "text";
		}
		if (token.contains("NUMBER") || token.contains("LONG") || token.contains("INT")
			|| token.contains("DOUBLE") || token.contains("FLOAT"))
		{
			return "a number";
		}
		if (token.contains("BOOLEAN"))
		{
			return "true or false";
		}
		if (token.contains("NULL"))
		{
			return "nothing";
		}
		return null;
	}

	/**
	 * The line and column out of a parser message, as a two element array, or
	 * null when it does not carry one.
	 *
	 * <p>Gson writes "at line 3 column 12 path $.routines" on anything it
	 * throws while reading text. That position is the single most useful thing
	 * in the whole message for somebody editing by hand, and this file exists
	 * largely to stop it being thrown away.
	 */
	public static int[] position(String message)
	{
		if (message == null)
		{
			return null;
		}

		final int line = number(message, "at line ");
		if (line <= 0)
		{
			return null;
		}
		return new int[]{line, Math.max(number(message, " column "), 0)};
	}

	/**
	 * The whole number that follows this word in the text, or zero.
	 */
	private static int number(String message, String after)
	{
		final int at = message.indexOf(after);
		if (at < 0)
		{
			return 0;
		}

		int index = at + after.length();
		int value = 0;
		int digits = 0;
		while (index < message.length() && message.charAt(index) >= '0' && message.charAt(index) <= '9')
		{
			value = value * 10 + (message.charAt(index) - '0');
			index++;
			digits++;
		}
		return digits == 0 ? 0 : value;
	}

	/**
	 * The part of a parser message worth reading, with the class names and the
	 * position taken off the front and the back.
	 *
	 * <p>An exception message arrives as one or more class names stacked in
	 * front of a phrase, then the phrase, then the position, then a JSON path.
	 * Only the phrase is anybody's business outside this file.
	 */
	public static String phrase(String message)
	{
		if (message == null)
		{
			return "";
		}

		String cleaned = message.trim();
		while (true)
		{
			final int colon = cleaned.indexOf(": ");
			if (colon <= 0)
			{
				break;
			}

			final String head = cleaned.substring(0, colon);
			if (head.indexOf(' ') >= 0 || head.indexOf('.') < 0)
			{
				break;
			}
			cleaned = cleaned.substring(colon + 2).trim();
		}

		final int at = cleaned.indexOf(" at line ");
		if (at > 0)
		{
			cleaned = cleaned.substring(0, at).trim();
		}

		final int path = cleaned.indexOf(" path $");
		if (path > 0)
		{
			cleaned = cleaned.substring(0, path).trim();
		}
		return cleaned;
	}

	/**
	 * Whether what is left still reads as something out of a library rather
	 * than something out of the document. Nothing that answers true is ever
	 * put in front of a user.
	 */
	public static boolean mentionsInternals(String text)
	{
		return text == null || text.contains("com.google") || text.contains("java.")
			|| text.contains("JsonReader") || text.contains("setLenient");
	}

	private static boolean blank(String text)
	{
		return text == null || text.trim().isEmpty();
	}
}

package com.clockwork;

import com.clockwork.core.AlertOverride;
import com.clockwork.core.ClockMode;
import com.clockwork.core.Mode;
import com.clockwork.core.OverlayOverride;
import com.clockwork.core.Toggle;
import com.clockwork.core.TriggerType;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

/**
 * Everything wrong with a document that the parser is perfectly happy with.
 *
 * <p>This is the half of the diagnostics nobody gets for free. Gson complains
 * loudly about a value of the wrong JSON type and says nothing at all about a
 * value of the right type that means nothing, so a clock whose direction is
 * written {@code countup!} binds to a null and reads as a working clock right
 * up until somebody presses start. Those are the ones found here, by looking at
 * the document rather than at what it bound to.
 *
 * <p>Every check reads the tree and reports. Nothing here changes a document,
 * repairs a value, or decides whether an import goes ahead. That decision
 * belongs to {@link ClockworkDocument}, which is also where the checks that can
 * refuse a document live.
 *
 * <h2>Where the list of acceptable spellings comes from</h2>
 *
 * <p>A message that says "expected countdown or countup" is only worth printing
 * if those are the two spellings that actually bind. So they are not written
 * down here. Each enum is asked what Gson writes for every one of its
 * constants, which is the same question Gson asks itself when it reads the
 * document, so the sentence and the binding cannot drift apart. A constant
 * added to one of these enums appears in the message on the next build with
 * nothing to remember.
 *
 * <p>The one thing written down is which JSON key holds which enum, and that is
 * the shape of the document rather than a fact about any build of it.
 *
 * <p>No Swing, no client, and no reflection here, only the tree and Gson, so
 * every sentence below can be tested against a string of JSON.
 */
final class DocumentReview
{
	/**
	 * The JSON key a trigger's type lives under, inside the start, lap, and
	 * stop trigger objects.
	 */
	private static final String TRIGGER_TYPE = "type";

	/**
	 * The keys on a clock that hold an enum, and therefore the keys where a
	 * plausible looking value can bind to nothing at all, each with the enum it
	 * has to be one of.
	 */
	private static final Map<String, Enum<?>[]> CLOCK_ENUMS;

	/**
	 * The keys on a clock that hold a trigger, each of which has an enum of its
	 * own inside it.
	 */
	private static final String[] TRIGGERS =
	{
		"startTrigger",
		"stopTrigger",
		"lapTrigger",
	};

	static
	{
		final Map<String, Enum<?>[]> fields = new LinkedHashMap<>();
		fields.put("mode", Mode.values());
		fields.put("clock", ClockMode.values());
		fields.put("overlay", OverlayOverride.values());
		fields.put("showDelta", Toggle.values());
		fields.put("alert", AlertOverride.values());
		fields.put("sound", Toggle.values());
		fields.put("notify", Toggle.values());
		CLOCK_ENUMS = Collections.unmodifiableMap(fields);
	}

	private DocumentReview()
	{
	}

	/**
	 * Everything worth telling the user about the clocks in this document,
	 * added to the list in document order.
	 *
	 * @param gson the reader the document is bound with, asked here for the
	 * spellings it accepts
	 * @param root the document as a tree, exactly as it was written
	 * @param problems where the findings go, which is a list rather than a
	 * return value because two different passes over the same document both add
	 * to it
	 */
	static void check(Gson gson, JsonObject root, List<DocumentProblem> problems)
	{
		if (gson == null || root == null || problems == null)
		{
			return;
		}

		final JsonElement routines = root.get("routines");
		if (routines == null || !routines.isJsonArray())
		{
			return;
		}

		// Worked out once for the whole document rather than once per clock,
		// because it is the same answer every time and a pasted document can
		// hold a great many clocks.
		final Map<String, Set<String>> accepted = accepted(gson);

		final JsonArray array = routines.getAsJsonArray();
		final Set<String> seen = new HashSet<>();

		for (int index = 0; index < array.size(); index++)
		{
			final JsonElement element = array.get(index);
			if (element == null || !element.isJsonObject())
			{
				// Not a clock at all, which fails the bind and is reported by
				// the reading with the reason it failed. Saying it twice would
				// be worse than saying it once.
				continue;
			}

			checkClock(element.getAsJsonObject(), index + 1, seen, accepted, problems);
		}
	}

	/**
	 * Every enum valued key in a document, with the spellings Gson accepts for
	 * it. Derived, so it says what this build actually reads.
	 */
	private static Map<String, Set<String>> accepted(Gson gson)
	{
		final Map<String, Set<String>> spellings = new LinkedHashMap<>();
		for (Map.Entry<String, Enum<?>[]> field : CLOCK_ENUMS.entrySet())
		{
			spellings.put(field.getKey(), stored(gson, field.getValue()));
		}
		spellings.put(TRIGGER_TYPE, stored(gson, TriggerType.values()));
		return spellings;
	}

	/**
	 * What Gson writes for every constant of one enum, sorted, so the sentence
	 * built from it reads the same every time.
	 */
	private static Set<String> stored(Gson gson, Enum<?>[] values)
	{
		final Set<String> names = new TreeSet<>();
		for (Enum<?> value : values)
		{
			names.add(written(gson, value));
		}
		return names;
	}

	/**
	 * One constant as the document should spell it, which is what Gson writes
	 * for it with the quotes taken off.
	 */
	private static String written(Gson gson, Enum<?> value)
	{
		final String json = gson.toJson(value);
		if (json != null && json.length() >= 2 && json.charAt(0) == '"'
			&& json.charAt(json.length() - 1) == '"')
		{
			return json.substring(1, json.length() - 1);
		}
		return json == null ? "" : json;
	}

	private static void checkClock(JsonObject clock, int number, Set<String> seen,
		Map<String, Set<String>> accepted, List<DocumentProblem> problems)
	{
		final String name = text(clock, "name");

		if (name == null)
		{
			problems.add(DocumentProblem.inClock(number, null,
				"this clock has no name, so it arrives called Clock"));
		}
		else if (!seen.add(name.toLowerCase(Locale.ROOT)))
		{
			problems.add(DocumentProblem.inClock(number, name,
				"another clock in this document is called this too, and clocks are matched by name"));
		}

		for (String field : CLOCK_ENUMS.keySet())
		{
			checkEnum(clock, field, field, number, name, accepted, problems);
		}

		for (String key : TRIGGERS)
		{
			final JsonElement trigger = clock.get(key);
			if (trigger != null && trigger.isJsonObject())
			{
				checkEnum(trigger.getAsJsonObject(), TRIGGER_TYPE, key + "." + TRIGGER_TYPE,
					number, name, accepted, problems);
			}
		}
	}

	/**
	 * One enum valued key, checked against the spellings this build actually
	 * binds.
	 *
	 * <p>A value of the wrong JSON type is left alone here, because that one
	 * fails the bind and is reported with the reason it failed. This is only
	 * about a string that is spelled wrong.
	 *
	 * @param field the key inside the object being read
	 * @param shown the key as the user should be told it, which for a trigger
	 * is the path from the clock rather than the bare word type
	 */
	private static void checkEnum(JsonObject holder, String field, String shown, int number,
		String name, Map<String, Set<String>> accepted, List<DocumentProblem> problems)
	{
		final JsonElement value = holder.get(field);
		if (value == null || value.isJsonNull() || !value.isJsonPrimitive()
			|| !value.getAsJsonPrimitive().isString())
		{
			return;
		}

		final Set<String> spellings = accepted.get(field);
		if (spellings == null || spellings.contains(value.getAsString().trim()))
		{
			return;
		}

		problems.add(DocumentProblem.inField(number, name, shown,
			"expected " + choices(spellings) + ", found " + DocumentProblem.found(value)));
	}

	/**
	 * The values a key will accept, with an "or" before the last one so it
	 * reads as a sentence rather than as a dump.
	 */
	private static String choices(Collection<String> values)
	{
		final List<String> sorted = new ArrayList<>(values);
		if (sorted.isEmpty())
		{
			return "something else";
		}

		if (sorted.size() == 1)
		{
			return sorted.get(0);
		}

		return String.join(", ", sorted.subList(0, sorted.size() - 1)) + " or " + sorted.get(sorted.size() - 1);
	}

	/**
	 * A key's value as trimmed text, or null when it is missing, blank, or not
	 * text at all.
	 */
	private static String text(JsonObject object, String key)
	{
		final JsonElement value = object.get(key);
		if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isString())
		{
			return null;
		}

		final String written = value.getAsString().trim();
		return written.isEmpty() ? null : written;
	}
}

package com.clockwork;

import com.clockwork.core.DurationFormat;

/**
 * Builds the format spec the whole plugin renders with.
 *
 * <p>This deliberately does not live on {@link ClockworkConfig}. RuneLite
 * proxies every method on a config interface, so a method without a
 * {@code @ConfigItem} never runs its default body and hands the caller a null
 * instead. A composed helper therefore has to sit outside the interface.
 *
 * <p>It does not live in {@code com.clockwork.core} either, because that
 * package is kept free of anything RuneLite.
 */
public final class Formats
{
	private Formats()
	{
	}

	/**
	 * The format spec assembled from config, so no two labels in the panel can
	 * disagree about it.
	 *
	 * <p>Callers on a refresh path should work this out once and pass it down
	 * rather than asking for it per label, since every call reads four config
	 * values back through the proxy.
	 */
	public static DurationFormat of(ClockworkConfig config)
	{
		if (config == null)
		{
			return DurationFormat.CLOCK_TENTHS;
		}
		return new DurationFormat(config.showHours(), config.showMinutes(), config.showSeconds(), config.precision());
	}
}

package com.clockwork;

import com.clockwork.core.TriggerEvent;
import net.runelite.api.ChatMessageType;
import net.runelite.client.util.Text;

/**
 * The client side half of a trigger, and the only place RuneLite types meet
 * them.
 *
 * <p>A raw event from the client is not in a shape a rule can read. A menu
 * target arrives wrapped in colour tags, so it reads as
 * {@code <col=ff9040>Bank chest</col>} rather than as {@code Bank chest}, and
 * comparing that against a plain string silently never matches. Chat lines can
 * carry tags of their own for the same reason.
 *
 * <p>So everything is stripped here, once, and handed on as a
 * {@link TriggerEvent}. Past this class the rules are plain string and integer
 * work in {@code com.clockwork.core}, which is what lets them be tested without
 * a client.
 */
final class GameTriggers
{
	private GameTriggers()
	{
	}

	/**
	 * Whether a chat line is one worth looking at.
	 *
	 * <p>Both types are taken because skilling messages land in either
	 * depending on the player's chat filter, and RuneLite's own item charge
	 * plugin reads the mining messages out of both for exactly that reason.
	 * Everything else, public chat included, is dropped here and never reaches
	 * a rule.
	 */
	static boolean isTriggerChat(ChatMessageType type)
	{
		return type == ChatMessageType.GAMEMESSAGE || type == ChatMessageType.SPAM;
	}

	/**
	 * A menu entry the player clicked, with the tags taken off both halves.
	 * Nothing about the entry is changed and the click is not consumed.
	 */
	static TriggerEvent menuClick(String option, String target)
	{
		return TriggerEvent.menuClick(strip(option), strip(target));
	}

	/**
	 * A game message, with the tags taken off.
	 */
	static TriggerEvent chatMessage(String message)
	{
		return TriggerEvent.chatMessage(strip(message));
	}

	private static String strip(String text)
	{
		return text == null ? "" : Text.removeTags(text);
	}
}

package com.clockwork;

import com.clockwork.core.HotkeyTarget;
import com.clockwork.core.Routine;
import com.clockwork.core.RoutineController;
import com.clockwork.ui.HotkeyTargetHandle;
import java.util.ArrayList;
import java.util.List;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.input.KeyManager;
import net.runelite.client.util.HotkeyListener;

/**
 * The three keys that start, stop, and lap a clock without the side panel, and
 * the designation that says which clock they act on.
 *
 * <p>Listening for a key is all that happens here. Each listener is asked
 * whether a key event the client already delivered matches a keybind, and if it
 * does the clock is driven through the same controller methods a button press
 * goes through. Nothing is ever built and handed back to the client, so no
 * input is put into the game and nothing is typed anywhere.
 *
 * <p>The three listeners are separate objects rather than one listener with a
 * switch because {@link HotkeyListener} matches one keybind each, and because
 * registering and unregistering them one at a time is what makes
 * {@link #shutDown()} obviously complete.
 */
@Slf4j
public class Hotkeys
{
	private final KeyManager keyManager;
	private final ClockworkStorage storage;

	/**
	 * The live controller, asked for rather than held, because the plugin drops
	 * it on shutdown.
	 */
	private final Supplier<RoutineController> controller;

	/**
	 * Whatever card the user last clicked in the side panel, which is the last
	 * rule the resolution falls back on before the built in clock. Null when
	 * the panel is shut or nothing is selected.
	 */
	private final Supplier<String> selectedRoutineId;

	/**
	 * Hops a key press from the client's input thread to the event dispatch
	 * thread, where the controller lives.
	 */
	private final BiConsumer<String, Runnable> onEdt;

	/**
	 * Redraws the cards, which are what show the designation. Run after every
	 * change the user makes to it.
	 */
	private final Runnable onDesignationChanged;

	/**
	 * The clock the hotkeys act on, or null when the user has not designated
	 * one.
	 *
	 * <p>Persisted, because the thing it replaced was the panel's selection and
	 * that is transient. With the sidebar shut, or on the first press after a
	 * restart, there was nothing selected and the keys could only ever reach the
	 * built in clock.
	 *
	 * <p>Written on the event dispatch thread, where every card callback and
	 * every hotkey hops to, and read on the same thread by the panel. It is
	 * volatile only because start up writes it from the client thread.
	 */
	private volatile String targetId;

	/**
	 * Built in the constructor rather than beside their declarations, because
	 * each one reads a keybind back off the config every time it is pressed and
	 * the field it reads is not assigned until the constructor runs.
	 */
	private final HotkeyListener startHotkey;
	private final HotkeyListener stopHotkey;
	private final HotkeyListener lapHotkey;

	/**
	 * What the side panel is given so its cards can show and change the
	 * designation without keeping a second copy of it.
	 */
	private final HotkeyTargetHandle handle = new HotkeyTargetHandle()
	{
		@Override
		public String getHotkeyTargetId()
		{
			return targetId;
		}

		@Override
		public void setHotkeyTargetId(String routineId)
		{
			designate(routineId);
		}
	};

	public Hotkeys(KeyManager keyManager, ClockworkConfig config, ClockworkStorage storage,
		Supplier<RoutineController> controller, Supplier<String> selectedRoutineId,
		BiConsumer<String, Runnable> onEdt, Runnable onDesignationChanged)
	{
		this.keyManager = keyManager;
		this.storage = storage;
		this.controller = controller;
		this.selectedRoutineId = selectedRoutineId;
		this.onEdt = onEdt;
		this.onDesignationChanged = onDesignationChanged;

		this.startHotkey = new HotkeyListener(config::startHotkey)
		{
			@Override
			public void hotkeyPressed()
			{
				onHotkey("hotkey.start", id -> controller.get().start(id));
			}
		};

		this.stopHotkey = new HotkeyListener(config::stopHotkey)
		{
			@Override
			public void hotkeyPressed()
			{
				onHotkey("hotkey.stop", id -> controller.get().stop(id));
			}
		};

		this.lapHotkey = new HotkeyListener(config::lapHotkey)
		{
			@Override
			public void hotkeyPressed()
			{
				onHotkey("hotkey.lap", id -> controller.get().lap(id));
			}
		};
	}

	public void startUp()
	{
		targetId = storage.loadHotkeyTarget();
		keyManager.registerKeyListener(startHotkey);
		keyManager.registerKeyListener(stopHotkey);
		keyManager.registerKeyListener(lapHotkey);
	}

	/**
	 * A key listener left registered outlives the plugin that made it, which is
	 * the exact class of bug this plugin is careful about everywhere else, so
	 * this is called first and unconditionally.
	 */
	public void shutDown()
	{
		keyManager.unregisterKeyListener(startHotkey);
		keyManager.unregisterKeyListener(stopHotkey);
		keyManager.unregisterKeyListener(lapHotkey);
		targetId = null;
	}

	public HotkeyTargetHandle handle()
	{
		return handle;
	}

	public String getTargetId()
	{
		return targetId;
	}

	/**
	 * Sets the designation without writing it through to config or redrawing.
	 * Only the profile switch uses it, because that path has already decided
	 * what to persist and rebuilds everything afterwards.
	 */
	public void setTargetId(String routineId)
	{
		targetId = routineId;
	}

	/**
	 * Points the hotkeys at a clock, or at nothing when given null.
	 *
	 * <p>Called from the clock's card, on the event dispatch thread. It writes
	 * the choice through to config, so it survives a restart and does not depend
	 * on the side panel being open, and then redraws what shows it.
	 */
	public void designate(String routineId)
	{
		targetId = routineId == null || routineId.isEmpty() ? null : routineId;
		storage.saveHotkeyTarget(targetId);
		onDesignationChanged.run();
	}

	/**
	 * Works out which clock a hotkey means and acts on it.
	 *
	 * <p>Key events arrive on the client's input thread, so this hops to the
	 * event dispatch thread first. The panel's selection and the controller are
	 * both read over there.
	 */
	private void onHotkey(String context, Consumer<String> action)
	{
		onEdt.accept(context, () ->
		{
			final String id = target();
			if (id == null)
			{
				log.debug("clockwork hotkey ignored, more than one clock is running, none is designated,"
					+ " and none is selected");
				return;
			}
			action.accept(id);
		});
	}

	/**
	 * The clock a hotkey acts on. See {@link HotkeyTarget} for the rule, which
	 * lives in core so it can be tested without a client.
	 */
	private String target()
	{
		final RoutineController current = controller.get();
		if (current == null)
		{
			return null;
		}

		return HotkeyTarget.resolve(current.runningIds(), surviving(current),
			selectedRoutineId.get(), Routine.QUICK_ID);
	}

	/**
	 * The designation as it still stands, having cleared it if the clock it
	 * named has since been deleted.
	 *
	 * <p>A dead designation falls through to the next rule rather than stopping
	 * the key from doing anything, and it is unset rather than left in config
	 * pointing at nothing.
	 */
	private String surviving(RoutineController current)
	{
		final String stored = targetId;
		if (stored == null)
		{
			return null;
		}

		final List<String> ids = new ArrayList<>();
		for (Routine routine : current.getRoutines())
		{
			ids.add(routine.getId());
		}

		final String live = HotkeyTarget.surviving(stored, ids);
		if (live == null)
		{
			targetId = null;
			storage.saveHotkeyTarget(null);
		}
		return live;
	}
}

package com.clockwork.core;

import com.google.gson.annotations.SerializedName;

/**
 * One clock's answer to what it draws when it finishes, which is either
 * "whatever the plugin config says" or a decision of its own.
 *
 * <p>Some clocks want an alert and some do not, and there was no way to say so
 * while the style was global only. This is the same shape
 * {@link OverlayOverride} already has, so the fallback rule is the one written
 * down in {@link Overridable} rather than a second copy of it.
 *
 * <p>This one is persisted, on {@link Routine#getAlert()}, so the serialized
 * names below are the contract. See {@link Overridable} for how a member that
 * carries null resolves.
 *
 * <p>This is the drawn half of an alert and nothing else. The chime and the
 * RuneLite notification each have a per clock answer of their own, a
 * {@link Toggle} on {@link Routine#getSound()} and a {@link Toggle} on
 * {@link Routine#getNotify()}, and all three are read separately so that a
 * clock can draw nothing and still chime, or flash and be announced as well.
 * The notification is deliberately not one of the answers here. A single
 * select cannot say "flash and notify", and that is a thing a user is allowed
 * to want.
 */
public enum AlertOverride implements Overridable<AlertStyle>
{
	@SerializedName("useglobal")
	USE_GLOBAL("Use global", null),
	@SerializedName("none")
	NONE("None", AlertStyle.NONE),
	@SerializedName("timerbox")
	TIMER_BOX("Flash the timer", AlertStyle.TIMER_BOX),
	@SerializedName("screen")
	SCREEN("Flash the screen", AlertStyle.SCREEN);

	private final String label;
	private final AlertStyle value;

	AlertOverride(String label, AlertStyle value)
	{
		this.label = label;
		this.value = value;
	}

	@Override
	public AlertStyle override()
	{
		return value;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.clockwork.core;

/**
 * How a finished clock announces itself on screen.
 *
 * <p>Three answers, two of them drawn and one of them nothing, and it is one
 * setting rather than a row of switches because a user choosing between two
 * flashes is choosing one of them. The two things that are genuinely beside
 * this rather than inside it, the chime and the RuneLite notification, each
 * have a setting of their own and are read without looking at this one.
 *
 * <p>This is the resolved answer, the one the plugin acts on. It is also the
 * type of the plugin wide default, which a clock can override through
 * {@link AlertOverride}.
 *
 * <p>The plugin wide default is a config item, and RuneLite's config manager
 * writes an enum as {@code name()} and reads it back with {@code Enum.valueOf},
 * so the stored form of the global setting is the constant name and renaming a
 * constant here is what would orphan a user's saved choice.
 * {@code StoredEnumNamesTest} pins those names for that reason. Nothing
 * persists this type through Gson, because the per clock answer is carried by
 * {@link AlertOverride} and that enum has serialized names of its own.
 *
 * <p>Nothing here re-rolls colours per frame. A blink alternates between two
 * fixed colours on a fixed period and stops after a bounded number of seconds,
 * which keeps it useful without turning into a strobe.
 */
public enum AlertStyle
{
	NONE("None"),

	/**
	 * The clock's own timer box blinks.
	 *
	 * <p>It needs that clock to have a box, so a user who has the timer boxes
	 * turned off has nothing here to flash and is left with the chime and the
	 * notification. Neither of those depends on a box, and neither of them is
	 * decided here.
	 */
	TIMER_BOX("Flash the timer"),

	/**
	 * A translucent wash over the whole game canvas.
	 */
	SCREEN("Flash the screen");

	private final String label;

	AlertStyle(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

