package com.clockwork.core;

import java.util.Objects;

/**
 * Which fields a formatted duration is built from.
 *
 * <p>A disabled field is absent from the output rather than blanked out, and
 * the largest field that is still enabled absorbs everything above it, so a
 * duration can never wrap around and read as a smaller one.
 */
public final class DurationFormat
{
	public static final DurationFormat CLOCK = new DurationFormat(true, true, true, SubSecond.NONE);
	public static final DurationFormat CLOCK_TENTHS = new DurationFormat(true, true, true, SubSecond.TENTHS);
	public static final DurationFormat CLOCK_HUNDREDTHS = new DurationFormat(true, true, true, SubSecond.HUNDREDTHS);

	private final boolean hours;
	private final boolean minutes;
	private final boolean seconds;
	private final SubSecond subSecond;

	public DurationFormat(boolean hours, boolean minutes, boolean seconds, SubSecond subSecond)
	{
		this.hours = hours;
		this.minutes = minutes;
		this.seconds = seconds;
		this.subSecond = subSecond == null ? SubSecond.NONE : subSecond;
	}

	public boolean isHours()
	{
		return hours;
	}

	public boolean isMinutes()
	{
		return minutes;
	}

	public boolean isSeconds()
	{
		return seconds;
	}

	public SubSecond getSubSecond()
	{
		return subSecond;
	}

	/**
	 * This format with sub-second digits removed, used for history rows where
	 * fractions are noise.
	 */
	public DurationFormat withoutSubSecond()
	{
		return subSecond == SubSecond.NONE ? this : new DurationFormat(hours, minutes, seconds, SubSecond.NONE);
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof DurationFormat))
		{
			return false;
		}
		DurationFormat other = (DurationFormat) o;
		return hours == other.hours
			&& minutes == other.minutes
			&& seconds == other.seconds
			&& subSecond == other.subSecond;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(hours, minutes, seconds, subSecond);
	}

	@Override
	public String toString()
	{
		return "DurationFormat(hours=" + hours + ", minutes=" + minutes
			+ ", seconds=" + seconds + ", subSecond=" + subSecond + ")";
	}
}

package com.clockwork.core;

/**
 * Turns a duration in milliseconds into a string, using only the fields the
 * caller asked for.
 *
 * <p>Two rules drive the whole class.
 *
 * <ol>
 *     <li>A disabled field is genuinely absent. Nothing is emitted in its
 *     place, no placeholder digits and no filler characters.</li>
 *     <li>The largest enabled field is unbounded. Hours never wrap, and when
 *     hours are switched off the minutes field carries them, so sixty one
 *     minutes reads as 61:00 and can never be mistaken for one minute.</li>
 * </ol>
 *
 * <p>Hours are the one field that appears on their own. They are skipped below
 * the one hour mark even when enabled, because a five minute run should not
 * read as 0:05:00.
 */
public final class DurationFormatter
{
	private static final long HOUR = 3_600_000L;
	private static final long MINUTE = 60_000L;
	private static final long SECOND = 1_000L;

	private DurationFormatter()
	{
	}

	/**
	 * Formats a duration. Negative values get a leading minus, which is how
	 * countdown overtime is shown.
	 */
	public static String format(long millis, DurationFormat spec)
	{
		return build(millis, spec, millis < 0 ? "-" : "");
	}

	/**
	 * Formats a delta with an explicit sign, so a value ahead of the personal
	 * best reads as -0:04.2 and one behind reads as +0:04.2.
	 */
	public static String formatSigned(long millis, DurationFormat spec)
	{
		return build(millis, spec, millis < 0 ? "-" : "+");
	}

	private static String build(long millis, DurationFormat spec, String sign)
	{
		long remaining = Math.abs(millis);
		final long subSecondPart = remaining % SECOND;

		StringBuilder out = new StringBuilder();
		boolean first = true;

		if (spec.isHours())
		{
			long h = remaining / HOUR;
			if (h > 0)
			{
				out.append(h);
				remaining -= h * HOUR;
				first = false;
			}
		}

		if (spec.isMinutes())
		{
			long m = remaining / MINUTE;
			append(out, m, first);
			remaining -= m * MINUTE;
			first = false;
		}

		if (spec.isSeconds())
		{
			long s = remaining / SECOND;
			append(out, s, first);
			first = false;
		}

		int digits = spec.getSubSecond().getDigits();
		if (digits > 0)
		{
			if (!first)
			{
				out.append('.');
			}
			long divisor = digits == 1 ? 100L : 10L;
			appendPadded(out, subSecondPart / divisor, digits);
			first = false;
		}

		if (first)
		{
			// Nothing at all was enabled, so there is nothing to sign either.
			return "";
		}

		return sign + out;
	}

	private static void append(StringBuilder out, long value, boolean first)
	{
		if (first)
		{
			out.append(value);
			return;
		}
		out.append(':');
		appendPadded(out, value, 2);
	}

	private static void appendPadded(StringBuilder out, long value, int width)
	{
		String s = Long.toString(value);
		for (int i = s.length(); i < width; i++)
		{
			out.append('0');
		}
		out.append(s);
	}
}

package com.clockwork.core;

import java.util.Collection;

/**
 * Which clock a hotkey acts on.
 *
 * <p>A hotkey has one key and the user has any number of clocks, so the
 * mapping has to be a rule rather than a guess. The rule is, in order,
 *
 * <ol>
 * <li>the designated clock, when one is set and still exists</li>
 * <li>the clock that is running, when exactly one is</li>
 * <li>the clock selected in the side panel</li>
 * <li>the built in Quick clock</li>
 * </ol>
 *
 * <h2>Why the designation is first</h2>
 *
 * <p>It used to be third, below the single running clock and below the panel
 * selection, and there was no designation at all. That failed in the ordinary
 * case. Selection is transient panel state, so playing with the sidebar shut,
 * or on the first press after a restart, there is nothing selected and the
 * keys can only ever reach Quick. A user with a clock pinned on screen pressed
 * start and got Quick instead.
 *
 * <p>So the designation is explicit, it is persisted, and it beats everything.
 * Putting it below the running rule would have the same surprise in reverse,
 * designate a clock, leave Quick running, and the start key still lands on
 * Quick. An explicit choice the user made and can see has to win over one the
 * plugin inferred.
 *
 * <p>With more than one clock running, nothing designated and nothing selected
 * there is no answer, so nothing happens. Acting on all of them, or on
 * whichever one happened to be first, would be worse than doing nothing,
 * because a stop hotkey that hits the wrong clock destroys a run that cannot
 * be got back.
 *
 * <p>Pure on purpose. The panel and the plugin supply the inputs and this
 * decides, so the rule can be tested without a client.
 */
public final class HotkeyTarget
{
	private HotkeyTarget()
	{
	}

	/**
	 * The designation as it still stands, or null when it does not.
	 *
	 * <p>A designated clock can be deleted, and a config profile can be
	 * switched to one that never had it, so the stored id is checked against
	 * the clocks that actually exist before it is used. The caller is expected
	 * to clear the stored id when this returns null, so a dead designation
	 * does not sit in config forever.
	 *
	 * @param designatedId the stored id, which may be null, empty, or stale
	 * @param existingIds ids of the clocks that exist right now
	 * @return the id when it is live, otherwise null
	 */
	public static String surviving(String designatedId, Collection<String> existingIds)
	{
		if (designatedId == null || designatedId.isEmpty() || existingIds == null)
		{
			return null;
		}
		return existingIds.contains(designatedId) ? designatedId : null;
	}

	/**
	 * @param runningIds ids of the clocks running right now
	 * @param designatedId the designated clock, already checked against
	 * {@link #surviving(String, Collection)}, or null for none
	 * @param selectedId id selected in the side panel, or null
	 * @param fallbackId id of the built in clock
	 * @return the clock to act on, or null when the situation is ambiguous and
	 * the caller should do nothing
	 */
	public static String resolve(Collection<String> runningIds, String designatedId, String selectedId,
		String fallbackId)
	{
		if (designatedId != null && !designatedId.isEmpty())
		{
			return designatedId;
		}

		final int running = runningIds == null ? 0 : runningIds.size();

		if (running == 1)
		{
			return runningIds.iterator().next();
		}

		if (selectedId != null && !selectedId.isEmpty())
		{
			return selectedId;
		}

		if (running == 0)
		{
			return fallbackId;
		}

		return null;
	}
}

package com.clockwork.core;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * One split inside a run.
 *
 * <p>{@code splitMillis} is the total elapsed time at the moment the lap was
 * taken. {@code lapMillis} is the time since the previous lap, so the first
 * lap's two values are equal and the last lap's split equals the run duration.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class Lap
{
	/**
	 * Free text describing the segment, for example a patch name. May be null.
	 */
	private String label;

	private long splitMillis;

	private long lapMillis;
}

package com.clockwork.core;

import com.google.gson.annotations.SerializedName;

/**
 * Direction a routine's clock runs in.
 */
public enum Mode
{
	/**
	 * Counts upward from zero. The routine ends when the user stops it.
	 */
	@SerializedName("countup")
	COUNT_UP("Count up"),

	/**
	 * Counts down from a target. What happens at zero is up to the routine.
	 * By default the clock keeps going and reports overtime as a negative
	 * remaining value, and with {@link Routine#isStopAtZero()} set the run ends
	 * there instead.
	 */
	@SerializedName("countdown")
	COUNT_DOWN("Count down");

	private final String label;

	Mode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.clockwork.core;

import com.google.gson.annotations.SerializedName;

/**
 * When a clock's timer box is on screen.
 *
 * <p>This is the resolved answer, the one the plugin acts on. It is also the
 * type of the plugin wide default, which a clock can override through
 * {@link OverlayOverride}.
 *
 * <h2>Two names per constant, and which one is the contract</h2>
 *
 * <p>The plugin wide default is a config item, and RuneLite's config manager
 * writes an enum as {@code name()} and reads it back with
 * {@code Enum.valueOf}. So the stored form of the global setting is the
 * constant name, {@code WHILE_RUNNING}, and renaming a constant here is what
 * would orphan a user's saved choice. {@code StoredEnumNamesTest} pins those
 * names for that reason.
 *
 * <p>The serialized names below are not what the config manager reads. They
 * are here so that this type is already written down in the blob's own
 * vocabulary the day anything persists it through Gson, which is how
 * {@link OverlayOverride} carries the same three answers today.
 */
public enum OverlayMode
{
	/**
	 * On screen even when the clock is idle, showing the last run it recorded
	 * or zero when it has never run.
	 */
	@SerializedName("always")
	ALWAYS("Always show"),

	/**
	 * On screen only while the clock is running.
	 */
	@SerializedName("whilerunning")
	WHILE_RUNNING("Only while running"),

	/**
	 * No timer box at all.
	 */
	@SerializedName("never")
	NEVER("Never");

	private final String label;

	OverlayMode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.clockwork.core;

import com.google.gson.annotations.SerializedName;

/**
 * One clock's answer to where its timer box lives, which is either "whatever
 * the plugin config says" or a decision of its own.
 *
 * <p>This one is persisted, on {@link Routine#getOverlay()}, so the serialized
 * names below are the contract. See {@link Overridable} for how a member that
 * carries null resolves.
 */
public enum OverlayOverride implements Overridable<OverlayMode>
{
	@SerializedName("useglobal")
	USE_GLOBAL("Use global", null),
	@SerializedName("always")
	ALWAYS("Always show", OverlayMode.ALWAYS),
	@SerializedName("whilerunning")
	WHILE_RUNNING("Only while running", OverlayMode.WHILE_RUNNING),
	@SerializedName("never")
	NEVER("Never", OverlayMode.NEVER);

	private final String label;
	private final OverlayMode value;

	OverlayOverride(String label, OverlayMode value)
	{
		this.label = label;
		this.value = value;
	}

	@Override
	public OverlayMode override()
	{
		return value;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.clockwork.core;

/**
 * A per-clock setting that can either defer to the plugin wide setting or
 * override it.
 *
 * <p>Four settings have this shape, the in-game timer box, the best time delta,
 * what a finished clock draws, and whether it chimes, and there will be more.
 * The rule is written once here rather than once per setting, because two
 * copies of a fallback rule is two chances to disagree about what "use global"
 * means.
 *
 * <p>An implementation is an enum whose members each carry the value they
 * stand for, and whose "use global" member carries null.
 *
 * @param <T> what the setting resolves to, a value of the global setting's own
 * type
 */
public interface Overridable<T>
{
	/**
	 * The value this member insists on, or null when it defers to the global
	 * setting.
	 */
	T override();

	/**
	 * Works out what a clock actually does.
	 *
	 * <p>A null per-clock setting reads as "use global" too, so a blob decoded
	 * from an older version resolves rather than throwing.
	 */
	static <T> T resolve(Overridable<T> perClock, T global)
	{
		if (perClock == null)
		{
			return global;
		}
		T value = perClock.override();
		return value == null ? global : value;
	}
}

package com.clockwork.core;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;

/**
 * What has to happen when the user switches RuneLite config profile.
 *
 * <h2>Why this is not simply a reload</h2>
 *
 * <p>Every config profile has its own settings file, so the clock list is per
 * profile too. Clockwork used to read it once at start up and never again,
 * which meant that after a switch the plugin still held the previous profile's
 * clocks, and the next save wrote them into the newly selected profile on top
 * of whatever lived there. Clocks disappeared and nothing said so.
 *
 * <p>The awkward part is the order. By the time the plugin hears about the
 * switch the config manager has already moved, so a save now writes to the new
 * profile, which is exactly the damage being avoided. So nothing is saved on
 * the way out. The old profile's state is dropped unwritten, which is safe
 * because it was already written the last time it changed.
 *
 * <p>That leaves a run in progress with nowhere to go. It belongs to the old
 * profile and cannot be filed there any more, so it is cancelled rather than
 * left ticking against a clock list it is no longer part of. Cancelling
 * records nothing, which is the honest outcome, and the plugin writes a
 * diagnostics line naming the clocks it dropped.
 *
 * <p>Pure on purpose. The plugin hands over what was running and this says
 * what the switch costs, so the one part of a profile switch that has a
 * decision in it can be tested without a client and without a config manager.
 */
public final class ProfileSwitch
{
	private ProfileSwitch()
	{
	}

	/**
	 * Works out what the switch costs.
	 *
	 * <p>The clocks that were running and whose runs are about to be thrown
	 * away. Empty when the switch costs nothing, which is the caller's cue that
	 * there is nothing worth a diagnostics line.
	 *
	 * @param runningIds ids running in the profile being left
	 */
	public static List<String> droppedRuns(Collection<String> runningIds)
	{
		final List<String> dropped = new ArrayList<>();
		if (runningIds != null)
		{
			for (String id : runningIds)
			{
				if (id != null && !id.isEmpty())
				{
					dropped.add(id);
				}
			}
		}

		return dropped;
	}
}

package com.clockwork.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * A repeatable thing the user times, such as a ten patch herb run.
 *
 * <p>Everything the user reads calls this a clock. The class is called
 * {@code Routine} on purpose and stays that way. {@link ClockMode} already
 * exists and means something else entirely, whether a run counts wall clock
 * time or only logged in time, so a {@code Clock} domain class beside it would
 * read as the same idea while being a different one. Internal vocabulary is
 * routine, user facing vocabulary is clock.
 *
 * <p>This is plain data. It holds no live timing state, which lives in the
 * controller, so the whole object can be handed to Gson as is.
 */
@Data
@NoArgsConstructor
public class Routine
{
	/**
	 * Id of the built in clock, the one that is always there for something the
	 * user wants to time right now. Well known rather than generated, so it is
	 * the same id after a restart and the controller can find it again, or put
	 * it back, without looking anything up.
	 */
	public static final String QUICK_ID = "clockwork-quick";

	/**
	 * Name of the built in clock. Fixed, because that clock cannot be renamed.
	 */
	public static final String QUICK_NAME = "Quick";

	/**
	 * Stable generated id. Used as the persistence key, so it must never change
	 * once a routine exists.
	 */
	private String id;

	private String name = "Clock";

	private Mode mode = Mode.COUNT_UP;

	/**
	 * Only meaningful in {@link Mode#COUNT_DOWN}.
	 */
	private long targetMillis;

	/**
	 * Only meaningful in {@link Mode#COUNT_DOWN}. When false the countdown
	 * passes zero and carries on into overtime, which is what you want when the
	 * target is a pace to hold rather than a limit. When true the run ends at
	 * zero and is recorded exactly as a stop would have recorded it.
	 *
	 * <p>On by default, because a countdown that reaches zero has done what it
	 * was asked to do and running into overtime is the special case rather than
	 * the ordinary one. Only a clock made after this changed picks the new
	 * default up. Gson writes a primitive boolean whether it is true or false,
	 * so every clock already saved carries its own answer in the blob and keeps
	 * it, which is what an existing clock should do.
	 */
	private boolean stopAtZero = true;

	private ClockMode clock = ClockMode.WALL_CLOCK;

	private boolean lapsEnabled;

	/**
	 * A run longer than this is closed automatically and marked
	 * {@link Status#ABANDONED}. Null means never auto-abandon.
	 */
	private Long abandonAfterMillis;

	/**
	 * When false, a start request against an already running routine is
	 * ignored. When true it discards the run in progress and starts over.
	 */
	private boolean restartOnStart;

	/**
	 * Whether this routine gets its own draggable in-game timer box, and
	 * whether an idle one stays on screen. {@link OverlayOverride#USE_GLOBAL}
	 * defers to the plugin config, anything else wins over it.
	 *
	 * <p>Initialised rather than left null, so a clock saved by a build that
	 * had never heard of this field decodes as "use global" and behaves the
	 * way it did before the field existed. Gson runs field initialisers, so
	 * that costs the blob nothing and needs no rewrite.
	 */
	private OverlayOverride overlay = OverlayOverride.USE_GLOBAL;

	/**
	 * Whether the live gap against the personal best is shown for this
	 * routine. {@link Toggle#USE_GLOBAL} defers to the plugin config.
	 */
	private Toggle showDelta = Toggle.USE_GLOBAL;

	/**
	 * What this clock draws when it finishes, or when its countdown reaches
	 * zero. {@link AlertOverride#USE_GLOBAL} defers to the plugin config,
	 * anything else wins over it.
	 *
	 * <p>Initialised rather than left null for the same reason
	 * {@link #overlay} is, so a clock saved by a build that had never heard of
	 * this field decodes as "use global" and alerts exactly the way it did
	 * before the field existed.
	 *
	 * <p>The three parts of an alert each answer for themselves. This one is
	 * the drawn half, {@link #sound} is the chime, and {@link #notify} is the
	 * RuneLite notification. None of them reads either of the others.
	 */
	private AlertOverride alert = AlertOverride.USE_GLOBAL;

	/**
	 * Whether this clock chimes when it finishes, or when its countdown reaches
	 * zero. {@link Toggle#USE_GLOBAL} defers to the plugin config, on and off
	 * both win over it.
	 *
	 * <p>Beside {@link #alert} rather than folded into it, because the two are
	 * independent. A clock can draw nothing and still chime, chime and draw
	 * nothing, do both, or do neither, whichever way the plugin wide settings
	 * are left.
	 *
	 * <p>Initialised rather than left null for the same reason {@link #overlay}
	 * is, so a clock saved by a build that had never heard of this field
	 * decodes as "use global" and chimes exactly the way it did before the
	 * field existed.
	 */
	private Toggle sound = Toggle.USE_GLOBAL;

	/**
	 * Whether this clock asks RuneLite to notify when it finishes, or when its
	 * countdown reaches zero. {@link Toggle#USE_GLOBAL} defers to the plugin
	 * config, on and off both win over it.
	 *
	 * <p>Beside {@link #alert} rather than one of its answers, and beside
	 * {@link #sound} rather than folded into it, for the same reason both of
	 * those are beside each other. A user who wants a flash and a notification
	 * for the same clock wants both, and a single select cannot say that.
	 *
	 * <p>The global it falls back to is the enabled tick on the plugin's own
	 * notification item, which makes that tick the default for the clocks that
	 * are left on use global rather than a gate over the ones that are not.
	 * That is exactly what the chime's global already is.
	 *
	 * <p>Initialised rather than left null for the same reason {@link #overlay}
	 * is, so a clock saved by a build that had never heard of this field
	 * decodes as "use global" and is announced exactly the way it was before
	 * the field existed.
	 */
	private Toggle notify = Toggle.USE_GLOBAL;

	/**
	 * What starts this clock on its own, or null for nothing.
	 *
	 * <p>A {@link Trigger} rather than a bare {@link TriggerType}, because a
	 * click trigger is only a setting once the user has said which click, and
	 * the type alone has nowhere to keep that.
	 *
	 * <p>Left uninitialised rather than defaulted, so a clock saved before
	 * triggers existed decodes as null instead of quietly picking up a value it
	 * never had. Read it through {@link Trigger#orNothing}, which treats null
	 * and Nothing the same.
	 *
	 * <p>The trigger belongs to this clock and acts on this clock. Two clocks
	 * that both wait for the same thing each start themselves.
	 */
	private Trigger startTrigger;

	/**
	 * What stops this clock on its own, or null for nothing. A stop trigger on
	 * a clock that is not running does nothing at all, so it can never file a
	 * run of no length.
	 */
	private Trigger stopTrigger;

	/**
	 * What takes a split on this clock on its own, or null for nothing.
	 *
	 * <p>The third of the three, and the one that turns a total into a set of
	 * splits. A ten patch herb run that starts on the first teleport and stops
	 * at the bank gives one number without this, and one number per patch with
	 * it, which is what the splits were for.
	 *
	 * <p>Only acts on a running clock, and only when {@link #lapsEnabled} is
	 * on, so it can no more open a run than a stop trigger can. When one event
	 * is both this clock's lap trigger and its stop trigger, the stop wins,
	 * because ending the run is the more final intent and the closing lap
	 * already covers the split on the way out.
	 */
	private Trigger lapTrigger;

	/**
	 * The runs this clock has recorded.
	 *
	 * <p>Transient, and that is the point. History is the one part of a clock
	 * that is nobody else's business, so it does not belong in the same
	 * document as the settings. Gson skips it in both directions and the
	 * storage layer keeps it under a config key of its own, one per clock and
	 * named after the clock's id, which means a clock's settings can be handed
	 * to somebody else without handing them your personal bests.
	 *
	 * <p>It is also cheaper. Every lap used to rewrite the whole blob,
	 * including every clock's settings, because history lived inside it, and
	 * every finished run used to rewrite every clock's runs, because they all
	 * shared one key.
	 *
	 * <p>Nothing about the in memory API changes. This is still the list the
	 * controller appends to and {@link RoutineStats} reads.
	 */
	private transient List<Run> history = new ArrayList<>();

	/**
	 * Every completed run this clock has ever recorded, as a count and a sum.
	 *
	 * <p>Transient and stored under a key of its own, exactly as the runs are
	 * and for exactly the same two reasons. It is nobody else's business, so it
	 * has no place in a document a user hands to somebody, and it changes on a
	 * different beat from the settings, so it does not belong in the same key
	 * as them.
	 *
	 * <p>This is the only part of a clock that outlives the runs it was
	 * computed from. {@link #history} is capped, so the runs behind an all time
	 * average are mostly gone, and two numbers is the whole of what is left of
	 * them. Nothing else derived is stored, because everything else can be
	 * worked out from the runs that are still there.
	 */
	private transient Totals totals = new Totals();

	public Routine(String id, String name)
	{
		this.id = id;
		this.name = name;
	}

	/**
	 * Whether this is the built in clock, which is always present and can be
	 * neither renamed nor deleted.
	 */
	public boolean isBuiltIn()
	{
		return QUICK_ID.equals(id);
	}

	/**
	 * History of this routine, never null even after a decode of damaged data.
	 */
	public List<Run> historyOrEmpty()
	{
		return history == null ? Collections.emptyList() : history;
	}

	/**
	 * Lifetime totals of this clock, never null even after a decode of damaged
	 * data.
	 *
	 * <p>Readers use this. Anything that has to add to the totals fills the
	 * field in first, because a fresh object handed back here would be written
	 * to and thrown away.
	 */
	public Totals totalsOrZero()
	{
		return totals == null ? new Totals() : totals;
	}

	/**
	 * Every persisted setting of this clock, on a new object, with no history
	 * and no runs.
	 *
	 * <p>Export and import both need this. Export copies so it can null the id
	 * without touching the clock the user is still using, and import copies so
	 * an applied document cannot hand the controller the same object twice.
	 *
	 * <p>Every persisted field has to be listed here. {@code RoutineCopyTest}
	 * holds it to that by comparing what Gson writes for the copy against what
	 * Gson writes for the original, so a field added to this class and not
	 * added here fails rather than going quietly missing from every export.
	 */
	public Routine copy()
	{
		final Routine copy = new Routine();
		copy.id = id;
		copy.name = name;
		copy.mode = mode;
		copy.targetMillis = targetMillis;
		copy.stopAtZero = stopAtZero;
		copy.clock = clock;
		copy.lapsEnabled = lapsEnabled;
		copy.abandonAfterMillis = abandonAfterMillis;
		copy.restartOnStart = restartOnStart;
		copy.overlay = overlay;
		copy.showDelta = showDelta;
		copy.alert = alert;
		copy.sound = sound;
		copy.notify = notify;
		copy.startTrigger = startTrigger;
		copy.stopTrigger = stopTrigger;
		copy.lapTrigger = lapTrigger;
		copy.history = new ArrayList<>();

		// A copy is what an export and an import are made of, so it starts with
		// no runs behind it and no record of any. Somebody else's lifetime
		// average is not part of a clock's settings any more than their
		// personal best is.
		copy.totals = new Totals();
		return copy;
	}
}

package com.clockwork.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Consumer;
import java.util.function.LongSupplier;

/**
 * The single entry point for starting, splitting, and stopping routines.
 *
 * <p>Buttons in the side panel, the hotkeys, and every automatic trigger go
 * through these five methods. Nothing else is allowed to touch a run, which is
 * what keeps the arm semantics below in one place instead of scattered across
 * callers.
 *
 * <p>Time never accumulates. Every elapsed value is the difference between two
 * readings of the injected clock, so a slow frame, a paused JVM, or a busy
 * client cannot make a run drift, and a countdown holds an absolute deadline
 * rather than a counter someone has to remember to decrement.
 *
 * <p>The class is not thread safe by design. Callers keep it on one thread,
 * which for this plugin is the Swing event dispatch thread.
 */
public class RoutineController
{
	/**
	 * How many seconds of a countdown are counted in before it reaches zero.
	 *
	 * <p>Three because that is what a count in is. It is also the most a run can
	 * be given without the beats reaching back into the part of a countdown a
	 * user is not watching.
	 */
	private static final int COUNT_IN_FROM = 3;

	private final LongSupplier clock;
	private final Map<String, Routine> routines = new LinkedHashMap<>();
	private final Map<String, ActiveRun> active = new HashMap<>();
	private final List<RoutineListener> listeners = new CopyOnWriteArrayList<>();

	/**
	 * The named custom triggers, which clocks point at by name.
	 *
	 * <p>Held beside the clocks rather than inside them, because that is what
	 * it is. It is saved in the same blob and reloaded on a config profile
	 * switch by the same path, so a profile with its own clocks has its own
	 * triggers too.
	 */
	private TriggerLibrary library = TriggerLibrary.empty();

	/**
	 * Whether the player is in the game world. Only routines on the logged in
	 * only clock care.
	 */
	private boolean loggedIn = true;

	public RoutineController(LongSupplier clock)
	{
		this.clock = clock;
	}

	public long now()
	{
		return clock.getAsLong();
	}

	public void addListener(RoutineListener listener)
	{
		listeners.add(listener);
	}

	public void removeListener(RoutineListener listener)
	{
		listeners.remove(listener);
	}

	// Routine book keeping

	public List<Routine> getRoutines()
	{
		return Collections.unmodifiableList(new ArrayList<>(routines.values()));
	}

	public Routine get(String routineId)
	{
		return routineId == null ? null : routines.get(routineId);
	}

	/**
	 * Replaces every routine and the triggers they point at, used once at start
	 * up when the saved state comes back from config. Any run in progress is
	 * dropped.
	 *
	 * <p>The two go in together and are announced once. They come out of one
	 * blob and they have to go in as one thing, or a clock would spend a moment
	 * pointing at an entry that is not there yet.
	 *
	 * <p>{@link #addAll} is the other way clocks arrive, and it adds rather than
	 * replaces, which is what an import wants.
	 */
	public void load(List<Routine> loaded, TriggerLibrary loadedLibrary)
	{
		library = loadedLibrary == null ? TriggerLibrary.empty() : loadedLibrary;
		active.clear();
		routines.clear();
		adoptAll(loaded);
		fire(RoutineListener::onRoutinesChanged);
	}

	/**
	 * The named custom triggers, live. Read it freely. Change it through
	 * {@link #editLibrary}, so nothing slips past the listeners and leaves the
	 * panel or the saved state stale.
	 */
	public TriggerLibrary getLibrary()
	{
		return library;
	}

	/**
	 * Applies an edit to the library and tells everyone about it, exactly as
	 * {@link #update} does for one clock.
	 */
	public void editLibrary(Consumer<TriggerLibrary> edit)
	{
		if (edit == null)
		{
			return;
		}

		edit.accept(library);
		fire(RoutineListener::onRoutinesChanged);
	}

	/**
	 * Changes a saved trigger, and follows a rename through onto every clock
	 * waiting for it.
	 *
	 * <p>A clock stores the trigger's name, so a rename that stopped at the
	 * library would leave those clocks waiting for something that no longer
	 * exists. They would still look configured and would quietly never fire
	 * again, which is the worst shape a bug like this can take. So the two
	 * halves happen together, here, where both the library and the clocks are
	 * to hand.
	 *
	 * @param currentName the entry to change, by the name it has now
	 * @return the entry as it now stands, or null when there is no such entry
	 */
	public SavedTrigger editTrigger(String currentName, String name, String option, String target)
	{
		final SavedTrigger edited = library.edit(currentName, name, option, target);
		if (edited == null)
		{
			return null;
		}

		TriggerLibrary.repoint(new ArrayList<>(routines.values()), currentName, edited.getName());
		fire(RoutineListener::onRoutinesChanged);
		return edited;
	}

	/**
	 * Adds clocks that arrived from somewhere else, and the library they point
	 * into, without disturbing anything the user already has.
	 *
	 * <p>This is what an import applies. It is not {@link #load}, because load
	 * replaces the whole list and drops every run in progress with it, and
	 * adding somebody else's clocks is no reason to throw away the run the user
	 * is timing right now.
	 *
	 * <p>A clock arriving without an id gets one, exactly as load does, so a
	 * document that left its ids out still lands as real clocks.
	 */
	public void addAll(List<Routine> added, TriggerLibrary loadedLibrary)
	{
		if (loadedLibrary != null)
		{
			library = loadedLibrary;
		}

		adoptAll(added);
		fire(RoutineListener::onRoutinesChanged);
	}

	/**
	 * What it takes for a plain object to become a live clock, in one place.
	 *
	 * <p>{@link #load} and {@link #addAll} are the two ways clocks arrive from
	 * outside, one replacing the list and one adding to it, and the terms of
	 * arrival are the same either way. A null in the list is dropped, a clock
	 * with no id is given one so a document that left its ids out still lands,
	 * a null history becomes an empty one so nothing downstream has to check,
	 * and an over long history is trimmed on the way in rather than on the way
	 * out.
	 *
	 * <p>Written twice, this was a rule that could be updated on one path and
	 * not the other with nothing to notice. Neither caller announces the change
	 * here, because load and addAll each have their own reasons to fire once at
	 * the end.
	 *
	 * <p>The reconcile runs before the trim, and that order is the whole of it.
	 * See {@link #reconcileTotals(Routine)}.
	 */
	private void adoptAll(List<Routine> arriving)
	{
		if (arriving == null)
		{
			return;
		}

		for (Routine routine : arriving)
		{
			if (routine == null)
			{
				continue;
			}
			if (routine.getId() == null || routine.getId().isEmpty())
			{
				routine.setId(newId());
			}
			if (routine.getHistory() == null)
			{
				routine.setHistory(new ArrayList<>());
			}
			if (routine.getTotals() == null)
			{
				routine.setTotals(new Totals());
			}
			reconcileTotals(routine);
			trimHistory(routine);
			routines.put(routine.getId(), routine);
		}
	}

	/**
	 * Brings a clock's lifetime totals up to at least what its stored runs
	 * prove, counted from the runs it arrived with and before
	 * {@link #trimHistory} drops any of them.
	 *
	 * <p>This is what carries a user across the update that added the totals.
	 * Their stored runs are the only evidence of their history that exists, so
	 * a clock that has counted nothing is counted from them, and a user who
	 * arrives with fifty stored runs is credited with fifty rather than with
	 * the ten or twenty that survive the trim.
	 *
	 * <p>It cannot recover what they actually did. A user who has run a clock
	 * two hundred times has fifty runs stored, because that was the cap, so
	 * fifty is what they are credited with and their all time average starts
	 * as the average of those fifty. There is nowhere else to read the other
	 * hundred and fifty from. From this point on the count is exact.
	 *
	 * <h2>Why it is a floor rather than a seed</h2>
	 *
	 * <p>It used to fire only for a clock that had counted nothing at all, and
	 * that left a real profile reading "Average 16:00 over 8" beside "All time
	 * 16:01 over 7". The lifetime count was smaller than the number of runs
	 * sitting in the clock's own history, which cannot be true of anything.
	 * What happened is that the totals were counted first and the runs on the
	 * one key every clock used to share were brought in afterwards, so a run
	 * recovered by that move landed in the history and was counted by nothing.
	 * A guard that only ever seeded had no way back from it.
	 *
	 * <p>So the rule is stated as a floor instead. <b>The lifetime figures can
	 * never be below what the stored runs already account for.</b> Each number
	 * is held to its own floor, the count to how many stored runs are
	 * completed and the sum to how long those runs took, and a figure below its
	 * floor is raised to meet it.
	 *
	 * <p>Both floors are proofs rather than estimates. If the totals honestly
	 * count every stored completed run and however many more have since been
	 * let go, then they are at least the stored count and at least the stored
	 * sum. Being under either one is therefore proof that some stored run was
	 * never counted, and the stored figure is the smallest correction that can
	 * be justified from the evidence to hand.
	 *
	 * <h2>Why it may only ever raise</h2>
	 *
	 * <p>Recounting a clock whose totals are <em>above</em> its stored runs
	 * would destroy the thing the totals exist for. The runs are deliberately
	 * capped at between ten and twenty and the totals count everything ever, so
	 * a clock with two hundred runs behind it and twenty stored is the ordinary
	 * shape rather than a fault, and rewriting it from the twenty would throw
	 * away a hundred and eighty runs the user really did, with no backup and no
	 * export to get them back from. Raising is recoverable in a way lowering is
	 * not.
	 *
	 * <p>Neither is anything ever added on. Two lists that overlap by an
	 * unknown amount cannot be summed, and adding the stored runs to a figure
	 * that already includes them is exactly the double count the old guard was
	 * written to avoid. Taking the larger of the two is the only answer that is
	 * right when the runs are already counted and no worse than the truth when
	 * they are not.
	 *
	 * <p>Being a floor rather than a one shot also makes it idempotent by
	 * construction rather than by a guard, so it runs on every load and a
	 * restart changes nothing. A clock whose runs the user cleared stays at
	 * nothing, since clearing takes the totals and the runs together and there
	 * is nothing left to raise it to.
	 */
	private static void reconcileTotals(Routine routine)
	{
		final Totals totals = routine.getTotals();
		if (totals == null)
		{
			return;
		}

		long storedRuns = 0;
		long storedMillis = 0;
		for (Run run : routine.historyOrEmpty())
		{
			if (RunHistory.counts(run))
			{
				storedRuns++;
				storedMillis += run.getDurationMillis();
			}
		}

		totals.raiseTo(storedRuns, storedMillis);
	}

	public Routine create(String name)
	{
		Routine routine = new Routine(newId(), name == null || name.trim().isEmpty() ? "Clock" : name.trim());
		routines.put(routine.getId(), routine);
		fire(RoutineListener::onRoutinesChanged);
		return routine;
	}

	/**
	 * Makes sure the built in clock exists and is the first one in the list.
	 *
	 * <p>Called once at start up, after the saved state has been loaded. It is
	 * idempotent, so a user who already has it keeps the one they have, with
	 * its history and its settings, and never ends up with a second.
	 *
	 * <p>It announces exactly when it changed something, which means when it
	 * created the clock and when it moved an existing one back to the front.
	 * A clock that is already there and already first leaves it silent.
	 *
	 * <p>It is an ordinary clock in every other way. It records runs, it has
	 * personal bests, and it honours the alert settings, because making it a
	 * special case would mean a second set of rules to keep in step with the
	 * first.
	 */
	public Routine ensureQuick()
	{
		Routine quick = routines.get(Routine.QUICK_ID);
		final boolean created = quick == null;

		if (created)
		{
			quick = new Routine(Routine.QUICK_ID, Routine.QUICK_NAME);
			// A scratch timer is started again because the user wants to time
			// something else, so a second start means start over rather than
			// the ignore that suits a clock with a repeating trigger. Splits
			// are on so a split can be taken on it.
			quick.setRestartOnStart(true);
			quick.setLapsEnabled(true);
		}
		else
		{
			// Heals a name changed by hand in an older blob.
			quick.setName(Routine.QUICK_NAME);
		}

		// Read before the reorder, because afterwards the built in clock is
		// first either way. A clock that is already first stays exactly where
		// it is, so that case changes nothing and announces nothing. The map
		// is never empty here unless the clock was just created, which created
		// already covers.
		final boolean moved = !created && !Routine.QUICK_ID.equals(routines.keySet().iterator().next());

		// Rebuilt rather than sorted, because the map's iteration order is the
		// order the panel draws in and the built in clock is pinned to the top.
		final Map<String, Routine> reordered = new LinkedHashMap<>();
		reordered.put(Routine.QUICK_ID, quick);
		for (Map.Entry<String, Routine> entry : routines.entrySet())
		{
			if (!Routine.QUICK_ID.equals(entry.getKey()))
			{
				reordered.put(entry.getKey(), entry.getValue());
			}
		}
		routines.clear();
		routines.putAll(reordered);

		// Announced whenever something actually changed, whether that was the
		// clock arriving or the clock moving back to the front. A move is a
		// change to the order the panel draws in and the order the state saves
		// in, so a silent one would leave both stale.
		if (created || moved)
		{
			fire(RoutineListener::onRoutinesChanged);
		}
		return quick;
	}

	/**
	 * Applies an edit to a routine and tells everyone about it. Edits go
	 * through here rather than through the object itself so no change can slip
	 * past the listeners and leave the panel or the saved state stale.
	 */
	public void update(String routineId, Consumer<Routine> edit)
	{
		Routine routine = get(routineId);
		if (routine == null)
		{
			return;
		}

		edit.accept(routine);
		if (routine.isBuiltIn())
		{
			// The built in clock keeps its name whatever an edit tried to do
			// with it. Everything else about it is the user's to change.
			routine.setName(Routine.QUICK_NAME);
		}

		fire(RoutineListener::onRoutinesChanged);
	}

	public void delete(String routineId)
	{
		Routine routine = get(routineId);
		if (routine == null || routine.isBuiltIn())
		{
			// The built in clock is always there. Its runs can be cleared like
			// anything else, but it cannot be removed.
			return;
		}

		routines.remove(routineId);
		active.remove(routineId);
		fire(RoutineListener::onRoutinesChanged);
	}

	// The five verbs

	/**
	 * Starts a run.
	 *
	 * <p>A start against a routine that is already running is ignored. That
	 * default exists for the case this plugin was built around, where the
	 * signal that begins a routine repeats many times inside it, a herb run
	 * being ten teleports rather than one. Set
	 * {@link Routine#isRestartOnStart()} on routines where a repeat really
	 * should start over, and the run in progress is discarded.
	 */
	public void start(String routineId)
	{
		Routine routine = get(routineId);
		if (routine == null)
		{
			return;
		}

		if (active.containsKey(routineId))
		{
			if (!routine.isRestartOnStart())
			{
				return;
			}
			active.remove(routineId);
			fire(l -> l.onRunCancelled(routine));
		}

		long now = clock.getAsLong();
		ActiveRun run = new ActiveRun(now, now + routine.getTargetMillis());
		if (routine.getClock() == ClockMode.LOGGED_IN_ONLY && !loggedIn)
		{
			run.pausedSince = now;
		}
		active.put(routineId, run);
		fire(l -> l.onRunStarted(routine));
	}

	public void lap(String routineId)
	{
		lap(routineId, null);
	}

	/**
	 * Takes a split. Ignored when the routine has laps switched off or is not
	 * running.
	 */
	public void lap(String routineId, String label)
	{
		Routine routine = get(routineId);
		ActiveRun run = active.get(routineId);
		if (routine == null || run == null || !routine.isLapsEnabled())
		{
			return;
		}

		long split = elapsedOf(run, clock.getAsLong());
		long previous = run.laps.isEmpty() ? 0 : run.laps.get(run.laps.size() - 1).getSplitMillis();
		Lap lap = new Lap(label, split, split - previous);
		run.laps.add(lap);
		fire(l -> l.onLapTaken(routine, lap));
	}

	/**
	 * Ends the run and writes it to history as completed.
	 */
	public void stop(String routineId)
	{
		Routine routine = get(routineId);
		ActiveRun run = active.remove(routineId);
		if (routine == null || run == null)
		{
			return;
		}
		finish(routine, run, clock.getAsLong(), Status.COMPLETED);
	}

	/**
	 * Throws the run away. Nothing is recorded, so a run spoiled by something
	 * outside the routine does not have to be lived with.
	 */
	public void cancel(String routineId)
	{
		Routine routine = get(routineId);
		ActiveRun run = active.remove(routineId);
		if (routine == null || run == null)
		{
			return;
		}
		fire(l -> l.onRunCancelled(routine));
	}

	/**
	 * Clears the routine back to nothing, dropping any run in progress and the
	 * whole history with it. Personal bests go too, which is the point, and so
	 * does the lifetime count, since a clock that kept its all time average
	 * would be answering from runs the user has just thrown away.
	 */
	public void reset(String routineId)
	{
		Routine routine = get(routineId);
		if (routine == null)
		{
			return;
		}
		boolean wasRunning = active.remove(routineId) != null;
		if (routine.getHistory() != null)
		{
			routine.getHistory().clear();
		}
		if (routine.getTotals() != null)
		{
			routine.getTotals().clear();
		}
		if (wasRunning)
		{
			fire(l -> l.onRunCancelled(routine));
		}

		// One clock's runs went, which is the same narrow change a finished run
		// is, seen from the other direction.
		fire(l -> l.onHistoryChanged(routine));
	}

	/**
	 * Clears the recorded runs of every routine at once, which resets every
	 * personal best and average with them.
	 *
	 * <p>Unlike {@link #reset(String)} this leaves runs in progress alone, so
	 * emptying the working set while something is being timed does not throw
	 * that run away.
	 */
	public void clearAllHistory()
	{
		for (Routine routine : routines.values())
		{
			if (routine.getHistory() != null)
			{
				routine.getHistory().clear();
			}
			if (routine.getTotals() != null)
			{
				routine.getTotals().clear();
			}
		}
		fire(RoutineListener::onRoutinesChanged);
	}

	// Live state

	public boolean isRunning(String routineId)
	{
		return active.containsKey(routineId);
	}

	/**
	 * Ids of the runs in progress, in the order the routines are listed.
	 *
	 * <p>The plugin reads this to work out what a profile switch is about to
	 * throw away, and to decide whether anything is moving and the refresh
	 * needs its fast period. It is a copy, so the caller cannot reach the live
	 * run map through it.
	 */
	public List<String> runningIds()
	{
		final List<String> out = new ArrayList<>();
		for (String routineId : routines.keySet())
		{
			if (active.containsKey(routineId))
			{
				out.add(routineId);
			}
		}
		return out;
	}

	public boolean isPaused(String routineId)
	{
		ActiveRun run = active.get(routineId);
		return run != null && run.pausedSince != null;
	}

	public long elapsedMillis(String routineId)
	{
		return elapsedMillis(routineId, clock.getAsLong());
	}

	public long elapsedMillis(String routineId, long now)
	{
		ActiveRun run = active.get(routineId);
		return run == null ? 0 : elapsedOf(run, now);
	}

	/**
	 * Time left on a countdown, negative once it has gone past zero. Null for
	 * a routine that is counting up or is not running.
	 */
	public Long remainingMillis(String routineId, long now)
	{
		Routine routine = get(routineId);
		ActiveRun run = active.get(routineId);
		if (routine == null || run == null || routine.getMode() != Mode.COUNT_DOWN)
		{
			return null;
		}
		long reference = run.pausedSince != null ? run.pausedSince : now;
		return run.deadline - reference;
	}

	/**
	 * Splits taken so far in the run in progress.
	 */
	public List<Lap> currentLaps(String routineId)
	{
		ActiveRun run = active.get(routineId);
		return run == null ? Collections.emptyList() : Collections.unmodifiableList(run.laps);
	}

	/**
	 * Called when the player enters or leaves the game world. Routines on the
	 * logged in only clock pause and resume, and their deadline moves with
	 * them so a countdown does not eat the time spent at the login screen.
	 */
	public void setLoggedIn(boolean value)
	{
		if (loggedIn == value)
		{
			return;
		}
		loggedIn = value;

		long now = clock.getAsLong();
		for (Map.Entry<String, ActiveRun> entry : active.entrySet())
		{
			Routine routine = routines.get(entry.getKey());
			if (routine == null || routine.getClock() != ClockMode.LOGGED_IN_ONLY)
			{
				continue;
			}

			ActiveRun run = entry.getValue();
			if (!value)
			{
				if (run.pausedSince == null)
				{
					run.pausedSince = now;
				}
			}
			else if (run.pausedSince != null)
			{
				long paused = Math.max(0, now - run.pausedSince);
				run.pausedTotal += paused;
				run.deadline += paused;
				run.pausedSince = null;
			}
		}
	}

	/**
	 * Advances housekeeping that is driven by time rather than by the user,
	 * namely auto-abandon, the count in, and countdown expiry.
	 *
	 * <p>This is called from the plugin's refresh timer. It is deliberately
	 * separate from drawing, so that no frame the panel paints ever has to
	 * decide whether a run is still alive.
	 */
	public void tick(long now)
	{
		if (active.isEmpty())
		{
			return;
		}

		for (String routineId : new ArrayList<>(active.keySet()))
		{
			Routine routine = routines.get(routineId);
			ActiveRun run = active.get(routineId);
			if (routine == null || run == null)
			{
				continue;
			}

			Long abandonAfter = routine.getAbandonAfterMillis();
			if (abandonAfter != null && abandonAfter > 0 && elapsedOf(run, now) >= abandonAfter)
			{
				active.remove(routineId);
				finish(routine, run, now, Status.ABANDONED);
				continue;
			}

			if (routine.getMode() == Mode.COUNT_DOWN && run.pausedSince == null)
			{
				countIn(routine, run, now);
			}

			if (routine.getMode() == Mode.COUNT_DOWN
				&& !run.expiryFired
				&& run.pausedSince == null
				&& now >= run.deadline)
			{
				// Latched before either branch, so neither the alert nor the
				// automatic stop can happen twice for one run however many
				// ticks arrive after the deadline. A run that carries on into
				// overtime passes through here once and is left alone from
				// then on.
				run.expiryFired = true;

				if (routine.isStopAtZero())
				{
					// Recorded through the same path a stop goes through, at
					// the measured time rather than at the target. A tick that
					// arrives late records the time that really passed, because
					// inventing an exact target figure would put a run in the
					// history that nobody ran.
					active.remove(routineId);
					finish(routine, run, now, Status.COMPLETED);
				}
				else
				{
					fire(l -> l.onCountdownExpired(routine));
				}
			}
		}
	}

	// Internals

	/**
	 * Announces the last seconds of a countdown as it crosses them.
	 *
	 * <p>The latch is the second still owed rather than a flag per beat, which
	 * is what makes a late tick announce one second instead of three. Whatever
	 * the gap between ticks, the beat that fires is the one the countdown is in
	 * right now and everything above it is written off, so a client that stalls
	 * for two seconds inside a count in beeps once on the way out rather than
	 * emptying the whole count in at the same moment.
	 *
	 * <p>Only called for a countdown that is not paused. A paused run has its
	 * remaining time held still, so it crosses nothing and is owed exactly what
	 * it was owed when it stopped.
	 */
	private void countIn(Routine routine, ActiveRun run, long now)
	{
		if (run.countInSecond < 1)
		{
			return;
		}

		final long remaining = run.deadline - now;
		if (remaining <= 0)
		{
			// Past zero, where there is nothing left to count in to. The run may
			// carry on into overtime from here, and none of it is a count in.
			run.countInSecond = 0;
			return;
		}

		// The second the countdown is in, rounded up, so that a run with 2400ms
		// left is in its third second and one with exactly 2000ms left is in its
		// second.
		final int second = (int) ((remaining + 999L) / 1000L);
		if (second > run.countInSecond)
		{
			return;
		}

		run.countInSecond = second - 1;
		fire(l -> l.onCountInSecond(routine, second));
	}

	private void finish(Routine routine, ActiveRun run, long now, Status status)
	{
		long duration = elapsedOf(run, now);

		List<Lap> laps = new ArrayList<>(run.laps);
		if (routine.isLapsEnabled() && status == Status.COMPLETED)
		{
			// Close the segment the user was in when they stopped, so a lapped
			// run always has as many splits as it had segments and the last
			// split equals the run duration.
			long previous = laps.isEmpty() ? 0 : laps.get(laps.size() - 1).getSplitMillis();
			laps.add(new Lap(null, duration, duration - previous));
		}

		Run record = new Run(run.startedAt, now, duration, laps, status);
		if (routine.getHistory() == null)
		{
			routine.setHistory(new ArrayList<>());
		}
		routine.getHistory().add(record);

		// Counted before the trim, and counted whether or not the run survives
		// it, because the lifetime figure is about what the user did rather
		// than about what there was room to keep.
		if (RunHistory.counts(record))
		{
			if (routine.getTotals() == null)
			{
				routine.setTotals(new Totals());
			}
			routine.getTotals().record(duration);
		}

		trimHistory(routine);

		fire(l -> l.onRunFinished(routine, record));

		// The clock gained a run and nothing else about it moved, so this says
		// so, and the one clock's runs are all that has to be written.
		fire(l -> l.onHistoryChanged(routine));
	}

	/**
	 * Brings one clock's stored runs down to the ones worth keeping.
	 *
	 * <p>{@link RunHistory#kept(List)} decides which those are, and the same
	 * method is what the panel lists, so a run shown as one of the best is a
	 * run that is still there.
	 *
	 * <p>The list is emptied and refilled rather than replaced, because the
	 * caller holds it and the derived statistics fingerprint it. Handing back a
	 * different list would be a second thing for every holder to notice.
	 */
	private static void trimHistory(Routine routine)
	{
		final List<Run> history = routine.getHistory();
		if (history == null)
		{
			return;
		}

		final List<Run> kept = RunHistory.kept(history);
		if (kept.size() == history.size())
		{
			return;
		}

		history.clear();
		history.addAll(kept);
	}

	private static long elapsedOf(ActiveRun run, long now)
	{
		long paused = run.pausedTotal;
		if (run.pausedSince != null)
		{
			paused += Math.max(0, now - run.pausedSince);
		}
		long elapsed = now - run.startedAt - paused;
		return Math.max(0, elapsed);
	}

	private static String newId()
	{
		return UUID.randomUUID().toString();
	}

	private void fire(Consumer<RoutineListener> event)
	{
		for (RoutineListener listener : listeners)
		{
			event.accept(listener);
		}
	}

	/**
	 * Live state of a run in progress. Never persisted.
	 */
	private static final class ActiveRun
	{
		private final long startedAt;
		private final List<Lap> laps = new ArrayList<>();

		/**
		 * Absolute moment a countdown hits zero. Held as a deadline rather
		 * than a remaining counter, and pushed forward by any time the run
		 * spends paused.
		 */
		private long deadline;

		private long pausedTotal;
		private Long pausedSince;
		private boolean expiryFired;

		/**
		 * The next second of the count in this run still owes, or zero once it
		 * owes none.
		 *
		 * <p>Set from how long the countdown was when it began, so a run only
		 * ever owes beats it really has. A countdown of three seconds or more
		 * owes all three, one of two and a half seconds owes the two and the
		 * one, and one of under a second owes nothing and simply ends.
		 *
		 * <p>It lives on the run rather than beside the alerts, so starting,
		 * restarting, or cancelling a run resets it by construction. There is no
		 * second place that has to be told a run began.
		 */
		private int countInSecond;

		private ActiveRun(long startedAt, long deadline)
		{
			this.startedAt = startedAt;
			this.deadline = deadline;
			this.countInSecond = (int) Math.max(0, Math.min(COUNT_IN_FROM,
				(deadline - startedAt) / 1000L));
		}
	}
}

package com.clockwork.core;

import java.util.List;

/**
 * Brings a decoded blob up to the shape the rest of the code expects.
 *
 * <p>Every step here is a normalisation, filling in a field that a damaged or
 * hand edited blob can arrive without. None of them is allowed to reach the
 * refresh path or the dispatch path as a null, and a clock that came back at
 * its defaults would be the worst thing a persistence layer can do quietly.
 *
 * <p>Pure, so it can be tested against a real blob rather than reasoned about,
 * and it takes no version, because a step that a current blob does not need and
 * cannot be harmed by has nothing to branch on.
 *
 * <p>{@link #CURRENT_VERSION} is stamped on everything this build writes, and
 * the storage layer reads it back. That is the branch point for the first real
 * format change, and the rule it exists to serve is worth stating now rather
 * than working out later. Branch on the stored version, never on a field
 * looking empty. Gson runs the field initialisers, so a blob written before a
 * field existed comes back carrying that field's default rather than a null to
 * spot.
 */
public final class RoutineMigration
{
	/**
	 * Shape of the blob this code writes.
	 */
	public static final int CURRENT_VERSION = 1;

	/**
	 * The oldest build that can still read correctly what this one writes.
	 *
	 * <p>{@link #CURRENT_VERSION} looks backwards, saying which rewrites a
	 * newer reader has to run over older data. This looks forwards, saying
	 * whether an older reader is safe to go ahead. They are different questions
	 * and one number cannot answer both.
	 *
	 * <p>Raise this only for a change an older build would read wrongly rather
	 * than not at all, which means a field that changed meaning, or units, or
	 * spelling. Adding a field never counts, because an older build ignores a
	 * key it does not know and fills a missing one from its initialiser, which
	 * is pinned by a test.
	 *
	 * <p>Leaving it down is what keeps two users on different builds able to
	 * swap documents while an update rolls out.
	 */
	public static final int MINIMUM_READER_VERSION = 1;

	private RoutineMigration()
	{
	}

	public static void migrate(List<Routine> routines)
	{
		if (routines == null)
		{
			return;
		}

		for (Routine routine : routines)
		{
			if (routine == null)
			{
				continue;
			}

			// Damaged or hand edited data can still arrive with any of these
			// missing, and none of them is allowed to reach the refresh path
			// or the dispatch path as a null. All of them read as "use global"
			// when they are absent, which is what the field initialiser says too,
			// so this only ever fires for a blob that names the key and puts
			// something unreadable under it.
			if (routine.getOverlay() == null)
			{
				routine.setOverlay(OverlayOverride.USE_GLOBAL);
			}

			if (routine.getShowDelta() == null)
			{
				routine.setShowDelta(Toggle.USE_GLOBAL);
			}

			if (routine.getAlert() == null)
			{
				routine.setAlert(AlertOverride.USE_GLOBAL);
			}

			if (routine.getSound() == null)
			{
				routine.setSound(Toggle.USE_GLOBAL);
			}

			if (routine.getNotify() == null)
			{
				routine.setNotify(Toggle.USE_GLOBAL);
			}

			// A clock saved before triggers existed has none of these fields,
			// a clock saved before the lap trigger existed has the first two
			// and not the third, and a hand edited one can name a type this
			// build has never heard of, which decodes as an empty object. All
			// of them come out as Nothing rather than as a null the rest of the
			// plugin would have to keep checking for, which is the whole of
			// what a missing lap trigger costs. There is no rewrite for it,
			// because absent already means what it should mean.
			routine.setStartTrigger(Trigger.orNothing(routine.getStartTrigger()));
			routine.setStopTrigger(Trigger.orNothing(routine.getStopTrigger()));
			routine.setLapTrigger(Trigger.orNothing(routine.getLapTrigger()));
		}
	}
}

package com.clockwork.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Everything derived from a routine's history.
 *
 * <p>Almost none of this is persisted. Personal bests and windowed averages are
 * values of the run list, so they cannot drift away from the runs they claim to
 * summarise. Abandoned runs are kept in the history but never feed a statistic,
 * which is the point of auto-abandon in the first place, and
 * {@link RunHistory#counts(Run)} is the one place that is decided.
 *
 * <p>The exception is the all time average, and it has to be. The stored runs
 * are capped, so the runs an all time figure would need are mostly gone, and it
 * is read from the count and sum in {@link Totals} instead. That is still not a
 * stored average. It is a stored count and a stored sum, divided here, so the
 * answer is exact and cannot drift the way a rounded running average would.
 *
 * <p>Three of the answers here are about the run in progress rather than about
 * the history, {@link #liveDelta}, {@link #currentLapLabel} and
 * {@link #currentLapMillis}. They are here because the timer box and the side
 * panel both show them at the same moment, and two derivations of the same
 * split would be two chances for the two of them to say different things about
 * one run.
 *
 * <h2>The memo</h2>
 *
 * <p>Every answer here used to be recomputed from scratch on every call, and
 * the callers are the refresh loop and the side panel, both of which run twenty
 * times a second. Ten clocks with the panel open came to roughly eight hundred
 * fresh lists a second, each one a walk of a whole history, for numbers that
 * only change when a run finishes. The history is smaller now and the walk
 * carries a sort, so the reason to do it once has not changed.
 *
 * <p>So the walk is done once per routine and kept. The memo is invisible from
 * the outside because every entry carries a fingerprint of the history it was
 * computed from, the list instance, its length, and the identity of its newest
 * run. Anything that can change a statistic changes at least one of the three,
 * so a stale entry is thrown away on the next read rather than answered from.
 * {@link #invalidate(Routine)} and {@link #invalidateAll()} exist so the plugin
 * can drop entries as soon as it hears about a change, but correctness does not
 * rest on either being called.
 *
 * <p>The memo is keyed on the routine id rather than the routine, because
 * {@link Routine} is a data class whose {@code hashCode} is computed over its
 * fields, history included. Hashing one would mean walking the very list this
 * exists to avoid walking, and would change under the map as runs are recorded.
 * The entry holds the routine it was computed for as well, so two clocks that
 * ever shared an id could not read each other's numbers.
 */
public final class RoutineStats
{
	/**
	 * How many routines may be remembered before the memo is emptied and
	 * refilled. A user with more clocks than this is not a real user, and the
	 * bound means a caller that never invalidates cannot grow the map without
	 * limit.
	 */
	private static final int MAX_ENTRIES = 256;

	/**
	 * Guarded rather than concurrent. Every caller in the plugin is on the
	 * event dispatch thread, so the lock is never contended, and a plain
	 * {@code HashMap} behind one is easier to reason about than the illusion of
	 * lock free reads over a value that has to be checked against a fingerprint
	 * anyway.
	 */
	private static final Map<String, Derived> MEMO = new HashMap<>();

	private RoutineStats()
	{
	}

	/**
	 * Completed runs, oldest first.
	 *
	 * <p>The list is unmodifiable, because it is shared with the next caller
	 * that asks the same question.
	 */
	public static List<Run> completed(Routine routine)
	{
		return derived(routine).completed;
	}

	/**
	 * The most recently recorded runs, newest first, at most
	 * {@link RunHistory#RECENT_KEPT} of them. Abandoned runs are in it, because
	 * this is a record of what happened rather than a leaderboard.
	 *
	 * <p>The list is unmodifiable, because it is shared with the next caller
	 * that asks the same question.
	 */
	public static List<Run> recent(Routine routine)
	{
		return derived(routine).recent;
	}

	/**
	 * The fastest completed runs, fastest first, at most
	 * {@link RunHistory#FASTEST_KEPT} of them. Unmodifiable, for the same
	 * reason as above.
	 */
	public static List<Run> fastest(Routine routine)
	{
		return derived(routine).fastest;
	}

	/**
	 * Fastest completed run, or null when there is not one yet.
	 *
	 * <p>The first of {@link #fastest(Routine)} and nothing else. The record is
	 * not held anywhere separately, so there is one copy of it and no way for
	 * the number on the card to disagree with the run the history lists as the
	 * best one.
	 */
	public static Run personalBest(Routine routine)
	{
		final List<Run> fastest = derived(routine).fastest;
		return fastest.isEmpty() ? null : fastest.get(0);
	}

	/**
	 * Most recent completed run still stored, or null when there is not one.
	 *
	 * <p>Still stored is the exact claim, and it is worth being exact about.
	 * The newest {@link RunHistory#RECENT_KEPT} runs are always kept, so in
	 * every ordinary case this is the run the user just finished. A clock that
	 * abandoned every one of its last ten runs is the case where it is not,
	 * because the completed run before those ten is only kept if it is also one
	 * of the fastest, and then this answers with the most recent completed run
	 * there is rather than with one that is gone.
	 */
	public static Run lastCompleted(Routine routine)
	{
		return derived(routine).last;
	}

	/**
	 * Forgets what was derived for one routine. Cheap, and never required for
	 * correctness. See the note on this class.
	 */
	public static void invalidate(Routine routine)
	{
		if (routine == null)
		{
			return;
		}
		synchronized (MEMO)
		{
			MEMO.remove(routine.getId());
		}
	}

	/**
	 * Forgets everything. Called when the whole clock list has been replaced,
	 * such as after a config profile switch.
	 */
	public static void invalidateAll()
	{
		synchronized (MEMO)
		{
			MEMO.clear();
		}
	}

	/**
	 * Mean duration of the completed runs among the last {@code window} runs
	 * recorded. Returns null when none of them completed. With fewer runs than
	 * the window it averages what is there rather than refusing to answer.
	 *
	 * <p>The window is over runs recorded, not over completed runs, and that
	 * distinction became load bearing when the history stopped being a flat
	 * list of the newest fifty. The stored runs are now the newest ten and the
	 * fastest ten, so reaching past the newest ten to make a window up to
	 * length would reach into a user's record runs and quietly pull a recent
	 * average down towards their best ever form. Three abandoned runs in the
	 * last ten would have been filled in with three personal bests from months
	 * ago. So the window is the newest runs, and the abandoned ones among them
	 * are left out rather than replaced.
	 *
	 * <p>For the same reason the window cannot usefully be longer than
	 * {@link RunHistory#RECENT_KEPT} and is capped at it here. The config item
	 * behind it is ranged to the same number, so the two agree, and this cap is
	 * what holds if a stored setting ever gets past the range.
	 */
	public static Long averageOfLast(Routine routine, int window)
	{
		final long[] sum = sumOfLast(routine, window);
		return sum[1] == 0 ? null : sum[0] / sum[1];
	}

	/**
	 * How many runs {@link #averageOfLast} actually averaged, which is what the
	 * panel says the average is over. Zero when there is nothing to average.
	 */
	public static int completedInLast(Routine routine, int window)
	{
		return (int) sumOfLast(routine, window)[1];
	}

	/**
	 * The total and the count behind the windowed average, as one walk.
	 *
	 * <p>One method rather than two loops, because the caller wants both
	 * numbers and two loops would be two chances for the window rule to drift
	 * apart from itself.
	 *
	 * @return the summed duration and the number of runs it came from
	 */
	private static long[] sumOfLast(Routine routine, int window)
	{
		if (routine == null || window < 1)
		{
			return new long[]{0, 0};
		}

		final List<Run> runs = routine.historyOrEmpty();
		final int from = Math.max(0, runs.size() - Math.min(window, RunHistory.RECENT_KEPT));

		long total = 0;
		long count = 0;
		for (int i = from; i < runs.size(); i++)
		{
			final Run run = runs.get(i);
			if (!RunHistory.counts(run))
			{
				continue;
			}
			total += run.getDurationMillis();
			count++;
		}
		return new long[]{total, count};
	}

	/**
	 * Mean duration of every completed run this clock has ever recorded, or
	 * null when there has not been one.
	 *
	 * <p>Every run, not every stored run. The stored runs are capped and the
	 * count and the sum behind this are not, so this keeps answering for runs
	 * that were dropped years ago and stays the same size doing it.
	 *
	 * <p>Not memoised, because it is a division of two numbers that are already
	 * to hand. Memoising it would mean a second thing that could go stale.
	 */
	public static Long allTimeAverage(Routine routine)
	{
		return routine == null ? null : routine.totalsOrZero().average();
	}

	/**
	 * How many completed runs the all time average is over, which is what the
	 * panel says beside it.
	 */
	public static long completedAllTime(Routine routine)
	{
		return routine == null ? 0 : routine.totalsOrZero().getCompletedRuns();
	}

	/**
	 * The name of the split now being timed, which is one past however many
	 * have been taken.
	 *
	 * <p>Worded once, here, because the timer box and the side panel both say
	 * it and a run cannot be on lap three in one place and lap four in the
	 * other.
	 *
	 * @param currentLaps the splits taken on this run so far, which is what
	 * {@code RoutineController.currentLaps} hands back, and may be null or
	 * empty on a run that has not been split yet
	 */
	public static String currentLapLabel(List<Lap> currentLaps)
	{
		return "Lap " + ((currentLaps == null ? 0 : currentLaps.size()) + 1);
	}

	/**
	 * How long the split now being timed has been going, which is the elapsed
	 * time less the total at the last split.
	 *
	 * <p>Before the first split is taken that is the elapsed time itself, so a
	 * run reads as being on lap one from the moment it starts rather than
	 * showing nothing until the user presses Lap. That was the bug, on screen a
	 * clock looked as though the button had done nothing.
	 */
	public static long currentLapMillis(List<Lap> currentLaps, long elapsedMillis)
	{
		if (currentLaps == null || currentLaps.isEmpty())
		{
			return elapsedMillis;
		}
		return elapsedMillis - currentLaps.get(currentLaps.size() - 1).getSplitMillis();
	}

	/**
	 * Live delta against the personal best, negative when ahead of it.
	 *
	 * <p>Without laps this is simply the elapsed time measured against the
	 * personal best's total, which counts down through the run and crosses
	 * zero at the moment the record is lost.
	 *
	 * <p>With laps it behaves like a split timer. The delta freezes at the
	 * value it had when the last lap was taken, and only starts moving again
	 * once the elapsed time passes the personal best's next split, so the
	 * number on screen answers "how am I doing" rather than flickering.
	 *
	 * @return the delta in millis, or null when there is no personal best to
	 * compare against
	 */
	public static Long liveDelta(Routine routine, long elapsedMillis, List<Lap> currentLaps)
	{
		Run best = personalBest(routine);
		if (best == null)
		{
			return null;
		}

		List<Lap> bestLaps = routine != null && routine.isLapsEnabled()
			? best.lapsOrEmpty()
			: Collections.emptyList();

		int taken = currentLaps == null ? 0 : currentLaps.size();

		Long committed = null;
		if (taken > 0 && taken <= bestLaps.size())
		{
			long mine = currentLaps.get(taken - 1).getSplitMillis();
			long theirs = bestLaps.get(taken - 1).getSplitMillis();
			committed = mine - theirs;
		}

		long nextTarget = taken < bestLaps.size()
			? bestLaps.get(taken).getSplitMillis()
			: best.getDurationMillis();

		long live = elapsedMillis - nextTarget;
		if (live > 0 || committed == null)
		{
			return live;
		}
		return committed;
	}

	/**
	 * The derived values for one routine, from the memo when they are still
	 * good for the history in front of us and freshly computed when they are
	 * not.
	 */
	private static Derived derived(Routine routine)
	{
		if (routine == null)
		{
			return Derived.EMPTY;
		}

		final List<Run> history = routine.historyOrEmpty();
		final int size = history.size();
		final Run newest = size == 0 ? null : history.get(size - 1);

		synchronized (MEMO)
		{
			final Derived cached = MEMO.get(routine.getId());
			if (cached != null && cached.matches(routine, history, size, newest))
			{
				return cached;
			}

			final Derived fresh = compute(routine, history, size, newest);
			if (MEMO.size() >= MAX_ENTRIES)
			{
				MEMO.clear();
			}
			MEMO.put(routine.getId(), fresh);
			return fresh;
		}
	}

	private static Derived compute(Routine routine, List<Run> history, int size, Run newest)
	{
		final List<Run> completed = new ArrayList<>();
		for (Run run : history)
		{
			if (RunHistory.counts(run))
			{
				completed.add(run);
			}
		}

		// The two sets the store keeps, worked out by the same code that
		// decides what the store keeps, so the panel cannot list a run that has
		// already been let go.
		return new Derived(routine, history, size, newest,
			Collections.unmodifiableList(completed),
			Collections.unmodifiableList(RunHistory.recent(history)),
			Collections.unmodifiableList(RunHistory.fastest(history)),
			completed.isEmpty() ? null : completed.get(completed.size() - 1));
	}

	/**
	 * One routine's statistics, beside the fingerprint of the history they were
	 * read from.
	 */
	private static final class Derived
	{
		private static final Derived EMPTY = new Derived(null, Collections.emptyList(), 0, null,
			Collections.emptyList(), Collections.emptyList(), Collections.emptyList(), null);

		private final Routine routine;
		private final List<Run> history;
		private final int size;
		private final Run newest;

		private final List<Run> completed;
		private final List<Run> recent;
		private final List<Run> fastest;
		private final Run last;

		private Derived(Routine routine, List<Run> history, int size, Run newest,
			List<Run> completed, List<Run> recent, List<Run> fastest, Run last)
		{
			this.routine = routine;
			this.history = history;
			this.size = size;
			this.newest = newest;
			this.completed = completed;
			this.recent = recent;
			this.fastest = fastest;
			this.last = last;
		}

		/**
		 * Whether these values still describe the history in front of us.
		 *
		 * <p>Identity throughout, never equality. Two runs of the same length
		 * are equal and are not the same run, and the question here is whether
		 * the list changed rather than whether it looks similar.
		 */
		private boolean matches(Routine routine, List<Run> history, int size, Run newest)
		{
			return this.routine == routine
				&& this.history == history
				&& this.size == size
				&& this.newest == newest;
		}
	}
}

package com.clockwork.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * One finished attempt at a routine.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class Run
{
	private long startedAtEpochMillis;

	private long finishedAtEpochMillis;

	/**
	 * Measured duration of the run. For a routine on the logged in only clock
	 * this is smaller than the wall-clock span between the two timestamps,
	 * because logged out time is not counted.
	 */
	private long durationMillis;

	private List<Lap> laps = new ArrayList<>();

	private Status status = Status.COMPLETED;

	public boolean isCompleted()
	{
		return status == Status.COMPLETED;
	}

	/**
	 * Laps of this run, never null even after a decode of older or damaged data.
	 */
	public List<Lap> lapsOrEmpty()
	{
		return laps == null ? Collections.emptyList() : laps;
	}
}

package com.clockwork.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Which runs a clock keeps, and which it lets go.
 *
 * <p>The newest ten and the fastest ten, deduplicated. Between ten and twenty
 * distinct runs, because a run can be in both sets and then it is stored once.
 *
 * <p>This replaced a flat newest fifty. The flat rule bounded the stored data
 * and did something else nobody asked for, which is that a user's best ever run
 * aged off the front and was gone. The plugin writes no file and keeps no
 * backup, so at that moment their record was not archived or summarised, it was
 * deleted, and from then on the best time on screen quietly meant "best of the
 * last fifty" while still being labelled Best. Keeping the fastest runs on
 * purpose is what makes the label true again, and it is also why the personal
 * best is not stored anywhere separately. It is simply the first of the fastest
 * set, so there is one copy of it and it cannot disagree with the runs.
 *
 * <p>Pure, static, and free of everything else in the plugin, because two
 * callers depend on it agreeing with itself. {@link RoutineController} trims
 * with it, and {@link RoutineStats} shows the same two sets in the panel. If
 * those ever diverged, the panel would list runs the store had already dropped.
 *
 * <h2>The two rules that had to be decided</h2>
 *
 * <p><b>Only a completed run can be one of the fastest.</b> An abandoned run is
 * a run that ran away, not an achievement, and a clock with auto-abandon set
 * would otherwise fill its fastest set with runs it cut short. That is the same
 * rule every other statistic uses and it is written once, in
 * {@link #counts(Run)}, so there is no second answer to keep in step.
 *
 * <p><b>A tie goes to the older run.</b> Two runs of exactly equal duration are
 * ordered oldest first, so the first of the fastest set is the earliest run
 * that ever reached that time. That is deliberately the same answer
 * {@code RoutineStats} has always given, since it took a new best only on a
 * strictly faster run, and it means the run shown as Best does not change
 * identity the moment somebody matches it.
 */
public final class RunHistory
{
	/**
	 * How many of the most recently recorded runs are kept, whatever they are
	 * worth. This is the window every "how am I running now" answer is taken
	 * from, and it is why the average window setting cannot be set above it.
	 *
	 * <p>Abandoned runs count against it, because the recent list is a record
	 * of what happened rather than a leaderboard, and a run that ran away is
	 * worth seeing in it.
	 */
	public static final int RECENT_KEPT = 10;

	/**
	 * How many of the fastest completed runs are kept. Ten rather than one,
	 * because a personal best on its own is a number with no context, and ten
	 * is enough to see whether a record was a fluke or a plateau.
	 */
	public static final int FASTEST_KEPT = 10;

	/**
	 * The most distinct runs a clock can ever hold, which is both sets with no
	 * overlap at all. The least is {@link #RECENT_KEPT}, which is what a user
	 * whose ten newest runs are also their ten fastest holds, and that is the
	 * ordinary shape for somebody who is still improving.
	 */
	public static final int MAX_KEPT = RECENT_KEPT + FASTEST_KEPT;

	private RunHistory()
	{
	}

	/**
	 * Whether a run is one a statistic is allowed to read.
	 *
	 * <p>The single rule. A null is nothing anybody can read and an abandoned
	 * run is deliberately left out of every derived number, which is the whole
	 * point of the auto-abandon setting. Everything that picks a best, sums a
	 * total, or averages anything asks this rather than testing the status
	 * itself, so there is one place to change and no chance of two answers.
	 */
	public static boolean counts(Run run)
	{
		return run != null && run.isCompleted();
	}

	/**
	 * The most recently recorded runs, newest first, at most
	 * {@link #RECENT_KEPT} of them.
	 *
	 * <p>Newest first because that is the order the panel lists them in, which
	 * is the reverse of the order they are stored in.
	 */
	public static List<Run> recent(List<Run> history)
	{
		if (history == null)
		{
			return Collections.emptyList();
		}

		final List<Run> recent = new ArrayList<>();
		for (int i = history.size() - 1; i >= 0 && recent.size() < RECENT_KEPT; i--)
		{
			final Run run = history.get(i);
			if (run != null)
			{
				recent.add(run);
			}
		}
		return recent;
	}

	/**
	 * The fastest completed runs, fastest first, at most
	 * {@link #FASTEST_KEPT} of them. The first of them is the personal best.
	 *
	 * <p>Ties are ordered oldest first. See the note on this class for why.
	 */
	public static List<Run> fastest(List<Run> history)
	{
		final List<Run> fastest = new ArrayList<>();
		for (int index : fastestIndices(history))
		{
			fastest.add(history.get(index));
		}
		return fastest;
	}

	/**
	 * The runs worth keeping, in the order they were recorded.
	 *
	 * <p>Recorded order rather than either of the two orders above, because
	 * that is the order the stored list has always been in and every reader of
	 * it, the last completed run included, depends on it.
	 *
	 * <p>The order of operations is the part that matters. Every run that is
	 * going to be kept is chosen while the whole list is still in front of us,
	 * and only then is anything dropped. Trimming to the newest ten first and
	 * looking for the fastest afterwards would find the fastest of the ten that
	 * survived, which for a user upgrading with fifty stored runs would throw
	 * away the record they have been holding for months.
	 *
	 * <p>Nulls are dropped. A null carries nothing and no reader can do
	 * anything with one.
	 */
	public static List<Run> kept(List<Run> history)
	{
		if (history == null)
		{
			return new ArrayList<>();
		}

		final int size = history.size();
		final boolean[] keep = new boolean[size];

		int taken = 0;
		for (int i = size - 1; i >= 0 && taken < RECENT_KEPT; i--)
		{
			if (history.get(i) != null)
			{
				keep[i] = true;
				taken++;
			}
		}

		for (int index : fastestIndices(history))
		{
			// A run that is both recent and fast is already marked, so it is
			// kept once and the two sets overlap rather than doubling up.
			keep[index] = true;
		}

		final List<Run> kept = new ArrayList<>();
		for (int i = 0; i < size; i++)
		{
			if (keep[i])
			{
				kept.add(history.get(i));
			}
		}
		return kept;
	}

	/**
	 * Where the fastest completed runs sit in the list, fastest first, ties
	 * oldest first.
	 *
	 * <p>Positions rather than runs, so that {@link #kept} can mark them
	 * without having to work out whether two equal looking runs are the same
	 * object. Two runs of identical duration, laps, and timestamps are equal to
	 * one another and are still two separate runs the user did.
	 */
	private static List<Integer> fastestIndices(List<Run> history)
	{
		if (history == null || history.isEmpty())
		{
			return Collections.emptyList();
		}

		final List<Integer> completed = new ArrayList<>();
		for (int i = 0; i < history.size(); i++)
		{
			if (counts(history.get(i)))
			{
				completed.add(i);
			}
		}

		completed.sort((left, right) ->
		{
			final int byDuration = Long.compare(history.get(left).getDurationMillis(),
				history.get(right).getDurationMillis());
			return byDuration != 0 ? byDuration : Integer.compare(left, right);
		});

		return completed.subList(0, Math.min(FASTEST_KEPT, completed.size()));
	}
}

package com.clockwork.core;

import java.util.Objects;

/**
 * One custom click trigger the user named and kept.
 *
 * <p>A click trigger is the only trigger whose rule is the user's own two
 * strings, and those strings are worth reusing. Somebody who times a herb run
 * off "Use: Tool Leprechaun" wants the same wording on the clock that times a
 * flax run, and wants both to follow when they correct it. So the wording lives
 * here, once, under a name, and a clock points at it by {@link #getName()}
 * rather than copying it.
 *
 * <p>The name is the identity. An entry used to carry a generated id as well,
 * and a clock stored that, which meant a shared document was full of strings
 * that mean nothing to anybody. A name is already unique within a library, so
 * it does the same job and reads as something. The cost is that a rename has to
 * be followed through onto every clock pointing at the old name, which
 * {@link TriggerLibrary#repoint} does and the controller drives.
 *
 * <p>Immutable in use. The fields are not final only because Gson writes them
 * in place after building the object, which is also why the private no argument
 * constructor is here.
 *
 * <p>Pure, like everything else in this package. No client, no Swing.
 */
public final class SavedTrigger
{
	/**
	 * What the user calls it, such as "Note herbs". Trimmed, never empty, and
	 * unique within a library. This is also what a clock stores, so changing it
	 * changes what every clock has to point at.
	 */
	private String name;

	/**
	 * The menu option to insist on, or null for any option. Same meaning as on
	 * {@link Trigger}, because this turns into one.
	 */
	private String option;

	/**
	 * Text the menu target has to contain, or null for any target.
	 */
	private String target;

	/**
	 * For Gson, which builds the object before it fills anything in.
	 */
	private SavedTrigger()
	{
	}

	private SavedTrigger(String name, String option, String target)
	{
		this.name = Text.clean(name);
		this.option = Text.clean(option);
		this.target = Text.clean(target);
	}

	/**
	 * A new entry, under this name.
	 */
	public static SavedTrigger of(String name, String option, String target)
	{
		return new SavedTrigger(name, option, target);
	}

	/**
	 * Never null, even after a decode of damaged data, because a nameless row
	 * in the panel would be a row nobody can point at.
	 */
	public String getName()
	{
		final String cleaned = Text.clean(name);
		return cleaned == null ? "Custom trigger" : cleaned;
	}

	/**
	 * The name as a library compares it, which ignores case and surrounding
	 * space so "note herbs" and "Note herbs" are one entry rather than two.
	 */
	public String key()
	{
		return Text.lower(getName());
	}

	public String getOption()
	{
		return Text.clean(option);
	}

	public String getTarget()
	{
		return Text.clean(target);
	}

	/**
	 * The same entry under a different name, or with different strings. Used by
	 * an edit. A changed name is a changed identity, so the caller has to
	 * repoint the clocks that were waiting for the old one.
	 */
	public SavedTrigger with(String newName, String newOption, String newTarget)
	{
		return new SavedTrigger(newName, newOption, newTarget);
	}

	/**
	 * What this entry means as a rule, which is a plain click trigger.
	 */
	public Trigger toTrigger()
	{
		return Trigger.click(getOption(), getTarget());
	}

	/**
	 * Whether this entry asks for the same click as those two strings, compared
	 * the way {@link Trigger} compares them, so an import can tell that two
	 * entries are asking for one thing.
	 */
	public boolean asks(String otherOption, String otherTarget)
	{
		return Objects.equals(getOption(), Text.clean(otherOption))
			&& Objects.equals(getTarget(), Text.clean(otherTarget));
	}

	/**
	 * The two strings as one line, for the panel row under the name, as in
	 * "Use: Tool Leprechaun".
	 */
	public String describe()
	{
		final String wantedOption = getOption();
		final String wantedTarget = getTarget();

		if (wantedOption == null && wantedTarget == null)
		{
			return "nothing filled in yet";
		}
		if (wantedTarget == null)
		{
			return wantedOption;
		}
		if (wantedOption == null)
		{
			return "anything: " + wantedTarget;
		}
		return wantedOption + ": " + wantedTarget;
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof SavedTrigger))
		{
			return false;
		}
		final SavedTrigger that = (SavedTrigger) other;
		return Objects.equals(getName(), that.getName())
			&& Objects.equals(getOption(), that.getOption())
			&& Objects.equals(getTarget(), that.getTarget());
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(getName(), getOption(), getTarget());
	}

	@Override
	public String toString()
	{
		return getName();
	}
}

