package com.clockwork.core;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

/**
 * The animations that mean the player teleported.
 *
 * <p>These are cache animation ids, and the plugin's own rule is that ids come
 * from {@code net.runelite.api.gameval.AnimationID} rather than being typed in
 * as numbers. This package is not allowed to import anything from RuneLite,
 * though, because staying free of the client is what lets every rule in here be
 * tested without one.
 *
 * <p>So the ids are mirrored, each one named after the gameval constant it
 * copies, and {@code GamevalAnimationTest} asserts field by field that the
 * mirror still agrees with {@code AnimationID}. The test lives in the test
 * source set, where the client is on the classpath. If Jagex ever renumbers one
 * of these, the build fails rather than the trigger quietly going dead.
 *
 * <p>The list is short on purpose. Every id here is an animation the player
 * themselves plays, which is the whole reason this trigger is allowed to exist.
 * See {@link TriggerType} for that constraint written out in full.
 */
public final class TeleportAnimations
{
	/**
	 * The standard spellbook teleport. Also the animation played by jewellery
	 * teleports, so one id covers the glory, the ring of dueling, the games
	 * necklace, and the rest of them.
	 */
	public static final int HUMAN_CASTTELEPORT = 714;

	/**
	 * Breaking a teleport tablet. Named for the construction spell that makes
	 * them, which is where the cache name comes from.
	 */
	public static final int POH_SMASH_MAGIC_TABLET = 4069;

	/**
	 * The Arceuus spellbook teleports, which use an animation of their own
	 * rather than the standard one.
	 */
	public static final int HUMAN_SPELLCAST_ARCEUUS_TELEPORT = 6575;

	private static final Set<Integer> IDS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		HUMAN_CASTTELEPORT,
		POH_SMASH_MAGIC_TABLET,
		HUMAN_SPELLCAST_ARCEUUS_TELEPORT)));

	private TeleportAnimations()
	{
	}

	/**
	 * Every teleport animation this plugin knows about, as an unmodifiable
	 * set.
	 */
	public static Set<Integer> ids()
	{
		return IDS;
	}

	public static boolean contains(int animationId)
	{
		return IDS.contains(animationId);
	}
}

package com.clockwork.core;

import java.util.Locale;

/**
 * The two string rules the trigger classes have to agree about.
 *
 * <p>Not a utility drawer. These are here because {@link Trigger},
 * {@link SavedTrigger} and {@link TriggerLibrary} each depend on the other two
 * giving the same answer, and each of them used to carry its own copy.
 *
 * <p>{@link #clean} is the one that matters. A blank string is not a value, and
 * that single decision reaches further than it looks. It decides whether two
 * triggers are equal, whether a library entry counts as already asking for the
 * same click, and whether a click trigger has been configured at all. Three
 * copies of it could have drifted apart with nothing to notice, and a drift
 * would have shown up as a saved trigger that quietly stopped matching itself.
 *
 * <p>{@link #lower} is the matching rule for a menu click, which is compared
 * without case. It answers with an empty string rather than null, because every
 * caller goes straight on to compare it.
 */
final class Text
{
	private Text()
	{
	}

	/**
	 * The text with its surrounding space removed, or null when there was
	 * nothing but space in it.
	 */
	static String clean(String text)
	{
		if (text == null)
		{
			return null;
		}
		final String trimmed = text.trim();
		return trimmed.isEmpty() ? null : trimmed;
	}

	/**
	 * The text in lower case, or an empty string when there is none.
	 *
	 * <p>{@link Locale#ROOT} rather than the default locale, so a player whose
	 * machine is set to Turkish gets the same match as everybody else. The
	 * strings being compared are the game's own English menu text.
	 */
	static String lower(String text)
	{
		return text == null ? "" : text.toLowerCase(Locale.ROOT);
	}
}

