package com.clockwork.core;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Every completed run a clock has ever recorded, as two numbers.
 *
 * <p>A count and a sum, and nothing else. The all time average is the quotient
 * of the two, which is exact, cannot drift away from the runs it came from, and
 * takes the same room after fifty thousand runs as it does after one. That is
 * the only way to keep an all time figure honest once the stored runs are
 * capped, because a capped list can no longer answer for the runs that fell out
 * of it.
 *
 * <p>The alternative, a stored average updated in place, was rejected. It has
 * to be rounded on every write, so it walks away from the truth by a little on
 * every run, and there is no way to check it against anything afterwards.
 *
 * <p>The sum is milliseconds in a long, so it holds runs adding up to a couple
 * of hundred million years before it has anything to worry about.
 *
 * <p>Abandoned runs are not in here, for the same reason they are in no other
 * statistic. {@link RunHistory#counts(Run)} is the one rule that decides, and
 * everything that adds to these numbers asks it.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class Totals
{
	private long completedRuns;

	private long completedMillis;

	/**
	 * Counts one completed run. The caller has already decided the run counts.
	 */
	public void record(long durationMillis)
	{
		completedRuns++;
		completedMillis += durationMillis;
	}

	/**
	 * Raises either figure that is below the one it is given, and lowers
	 * neither.
	 *
	 * <p>The one repair these two numbers have. They are a lifetime record with
	 * no backup behind them, so the only safe correction is upward, and every
	 * caller wanting to hold them to a floor comes through here rather than
	 * writing the comparison again with the other one the wrong way round.
	 *
	 * <p>Each figure is judged on its own, because each is evidence on its own.
	 * A count that is short says a run was never counted, and a sum that is
	 * short says the same thing, and neither is a reason to move the other in
	 * the direction it was not asked to move.
	 *
	 * <p>Nothing is ever added. A floor is right when the runs behind it are
	 * already counted and no worse than the truth when they are not, whereas
	 * adding would double every run that is in both.
	 *
	 * <p>{@link RoutineController} says what the floor is and why the stored
	 * runs are the thing that sets it.
	 *
	 * @param runs the fewest completed runs this clock can honestly have run
	 * @param millis the least time those runs can honestly have taken
	 */
	public void raiseTo(long runs, long millis)
	{
		if (runs > completedRuns)
		{
			completedRuns = runs;
		}

		if (millis > completedMillis)
		{
			completedMillis = millis;
		}
	}

	/**
	 * Forgets everything, which is what clearing a clock's runs has to do here
	 * too. A cleared clock that kept its all time average would be showing a
	 * number from runs the user just threw away.
	 */
	public void clear()
	{
		completedRuns = 0;
		completedMillis = 0;
	}

	/**
	 * Whether nothing has been counted yet. Also what says a stored figure is
	 * absent rather than zero, since a clock with no completed runs and a clock
	 * with no stored totals are the same thing to every reader.
	 */
	public boolean isEmpty()
	{
		return completedRuns <= 0;
	}

	/**
	 * Mean duration of every completed run ever recorded, or null when there
	 * has not been one.
	 */
	public Long average()
	{
		return isEmpty() ? null : completedMillis / completedRuns;
	}
}

package com.clockwork.core;

import java.util.Objects;

/**
 * A trigger as a clock actually holds it, which is a {@link TriggerType} plus
 * whatever that type needs the user to fill in.
 *
 * <p>Every trigger up to now was answerable by its name alone. Teleporting is
 * teleporting, and the rule for it is written once in {@link TriggerType}. A
 * click trigger is not like that. It only means something once the user has
 * said which click, so the type on its own is no longer enough to carry a
 * setting and this small value type carries it instead.
 *
 * <p>Two optional strings, both of which may be left empty.
 *
 * <ul>
 *   <li>The menu option, the left hand side of the entry, such as Rub</li>
 *   <li>The menu target, the right hand side, such as Ardougne cloak 4</li>
 * </ul>
 *
 * <p>Blank means anything, on either side, but not on both at once. A trigger
 * with nothing filled in matches no click at all, because a clock that starts
 * on every click in the game is a broken clock rather than a configured one.
 *
 * <p>A click trigger no longer keeps those two strings itself. It keeps the
 * name of a {@link SavedTrigger} in the library instead, and the strings live
 * there under that name. Correcting the wording once corrects every clock
 * waiting for it. The two string fields stay because that is what a reference
 * resolves into, and because a hand edited config can still hold one written
 * out in full.
 *
 * <p>Immutable in use. The fields are not declared final only because Gson
 * writes them in place after building the object, and the private no argument
 * constructor exists for the same reason. Nothing outside this class changes
 * one, so the two static instances handed out below are safe to share.
 *
 * <p>Pure, like everything else in this package. No client, no Swing, and no
 * game needed to test any rule below.
 */
public final class Trigger
{
	/**
	 * The default, and what every clock has until the user picks something.
	 * Shared, because it carries nothing that could differ between clocks.
	 */
	private static final Trigger NOTHING = new Trigger(TriggerType.NONE, null, null, null);

	private TriggerType type;

	/**
	 * The menu option to insist on, or null for any option. Stored already
	 * trimmed, with an empty string kept as a null so there is one way to say
	 * "anything" rather than two.
	 */
	private String option;

	/**
	 * Text the menu target has to contain, or null for any target. A substring
	 * on purpose, because a target reads "Ardougne cloak 4" today and the user
	 * should be able to write "Ardougne cloak" and keep the clock working when
	 * they finish the diary.
	 */
	private String target;

	/**
	 * The name of the {@link SavedTrigger} this trigger points at, or null when
	 * it carries its own rule.
	 *
	 * <p>A reference rather than a copy, so that editing the saved trigger
	 * changes every clock that waits for it. A name that names nothing resolves
	 * to Nothing rather than throwing, which {@link TriggerLibrary#resolve}
	 * owns.
	 *
	 * <p>It used to be a generated id. A name does the same job, because names
	 * are already unique within a library, and it means a shared document reads
	 * as words rather than as a page of hex. The cost is that a rename has to be
	 * followed through onto every clock, which
	 * {@link TriggerLibrary#repoint} does.
	 */
	private String ref;

	/**
	 * For Gson, which builds the object before it fills anything in. It leaves
	 * a value that reads as {@link #nothing()} if the stored object turns out
	 * to be empty.
	 */
	private Trigger()
	{
		this(TriggerType.NONE, null, null, null);
	}

	private Trigger(TriggerType type, String option, String target, String ref)
	{
		this.type = type == null ? TriggerType.NONE : type;
		this.option = Text.clean(option);
		this.target = Text.clean(target);
		this.ref = Text.clean(ref);
	}

	/**
	 * Nothing at all, the manual only clock.
	 */
	public static Trigger nothing()
	{
		return NOTHING;
	}

	/**
	 * A trigger of a type that needs nothing filled in.
	 */
	public static Trigger of(TriggerType type)
	{
		if (type == null || type == TriggerType.NONE)
		{
			return NOTHING;
		}
		return new Trigger(type, null, null, null);
	}

	/**
	 * A click trigger. Either side may be null or blank, meaning anything, and
	 * both blank means nothing at all.
	 */
	public static Trigger click(String option, String target)
	{
		return new Trigger(TriggerType.CUSTOM_CLICK, option, target, null);
	}

	/**
	 * A click trigger that points at a named entry in the library.
	 *
	 * <p>This is what a clock actually holds once the user has picked a custom
	 * trigger, and it is not answerable on its own. Ask
	 * {@link TriggerLibrary#resolve} for the rule behind it, or
	 * {@link TriggerLibrary#matches} for the answer.
	 */
	public static Trigger saved(String savedTriggerName)
	{
		final String name = Text.clean(savedTriggerName);
		if (name == null)
		{
			return NOTHING;
		}
		return new Trigger(TriggerType.CUSTOM_CLICK, null, null, name);
	}

	/**
	 * Reads a possibly missing trigger.
	 *
	 * <p>A clock saved before triggers existed has no trigger fields, damaged
	 * data can arrive with either missing, and a hand edited blob can name a
	 * type this build has never heard of, which Gson decodes as a null type.
	 * All three mean the same thing the user means by Nothing, so all three
	 * come back as the same shared value.
	 */
	public static Trigger orNothing(Trigger trigger)
	{
		if (trigger == null || trigger.getType() == TriggerType.NONE)
		{
			return NOTHING;
		}
		return trigger;
	}

	/**
	 * Never null, even after a decode that put a null in the field.
	 */
	public TriggerType getType()
	{
		return TriggerType.orNone(type);
	}

	/**
	 * The menu option the user asked for, or null when they left it blank and
	 * any option will do.
	 */
	public String getOption()
	{
		return Text.clean(option);
	}

	/**
	 * The text the menu target has to contain, or null when they left it blank
	 * and any target will do.
	 */
	public String getTarget()
	{
		return Text.clean(target);
	}

	/**
	 * The name of the library entry this trigger points at, or null when it
	 * carries its own rule and needs no library to be judged.
	 */
	public String getRef()
	{
		return Text.clean(ref);
	}

	/**
	 * The kind of event this trigger can possibly match, or null when it can
	 * match none.
	 *
	 * <p>A click trigger with neither side filled in reports null rather than
	 * a click, so the plugin does not switch its menu handler on for a setting
	 * that could never fire.
	 */
	public TriggerEvent.Kind kind()
	{
		if (getType() == TriggerType.CUSTOM_CLICK
			&& getRef() == null
			&& getOption() == null
			&& getTarget() == null)
		{
			return null;
		}
		return getType().kind();
	}

	/**
	 * Whether this event is the thing this trigger waits for.
	 *
	 * <p>The fixed triggers hand the question straight to their type, which is
	 * where those rules have always been written. Only the click trigger has a
	 * rule that depends on what the user typed, so only that one is answered
	 * here.
	 */
	public boolean matches(TriggerEvent event)
	{
		if (getType() == TriggerType.CUSTOM_CLICK)
		{
			return matchesClick(event);
		}
		return getType().matches(event);
	}

	/**
	 * The user's own rule.
	 *
	 * <p>Everything is compared with the tags already off, because the plugin
	 * strips them before a rule ever sees a click, and case is ignored on both
	 * sides because nobody should have to know whether the game writes Rub or
	 * rub.
	 *
	 * <p>Reading the player's own menu clicks is a safe and precedented thing
	 * for a plugin to do. A hub plugin ran this same matcher, free text option
	 * and target against the entry the player clicked, for two years. It was
	 * eventually pulled at Jagex's request, and not for the matcher. It was
	 * pulled for what it did next, which was to minimise the client window.
	 * The risk in a plugin lives in what it does with an event rather than in
	 * how it observes one, and what this one does is start a timer.
	 */
	private boolean matchesClick(TriggerEvent event)
	{
		if (event == null || event.getKind() != TriggerEvent.Kind.MENU_CLICK)
		{
			return false;
		}

		// A reference has no rule of its own. Only the library can say what it
		// waits for, so an unresolved one answers no rather than guessing, and
		// a guess of yes would fire on every click in the game.
		if (getRef() != null)
		{
			return false;
		}

		final String wantedOption = getOption();
		final String wantedTarget = getTarget();

		// Nothing filled in. Firing on every click in the game would be worse
		// than not firing at all, so this is the one case that matches nothing.
		if (wantedOption == null && wantedTarget == null)
		{
			return false;
		}

		if (wantedOption != null && !Text.lower(wantedOption).equals(Text.lower(event.getMenuOption()).trim()))
		{
			return false;
		}

		return wantedTarget == null || Text.lower(event.getMenuTarget()).contains(Text.lower(wantedTarget));
	}

	/**
	 * The phrase used on a clock card, as in "Starts on teleporting" or
	 * "Starts on click, Rub: Ardougne cloak 4".
	 */
	public String hint()
	{
		if (getType() != TriggerType.CUSTOM_CLICK)
		{
			return getType().hint();
		}

		// A reference is worded by the name the user gave it, which only the
		// library knows. TriggerLibrary.hint does that, and this stands in for
		// the case where there is no library to hand.
		if (getRef() != null)
		{
			return getType().hint() + ", a saved trigger";
		}

		final String wantedOption = getOption();
		final String wantedTarget = getTarget();

		if (wantedOption == null && wantedTarget == null)
		{
			return getType().hint() + ", nothing filled in yet";
		}
		if (wantedTarget == null)
		{
			return getType().hint() + ", " + wantedOption;
		}
		if (wantedOption == null)
		{
			return getType().hint() + ", anything: " + wantedTarget;
		}
		return getType().hint() + ", " + wantedOption + ": " + wantedTarget;
	}

	/**
	 * Trimmed, with an empty string read as nothing asked for.
	 */
	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof Trigger))
		{
			return false;
		}
		final Trigger that = (Trigger) other;
		return getType() == that.getType()
			&& Objects.equals(getOption(), that.getOption())
			&& Objects.equals(getTarget(), that.getTarget())
			&& Objects.equals(getRef(), that.getRef());
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(getType(), getOption(), getTarget(), getRef());
	}

	@Override
	public String toString()
	{
		return hint();
	}
}

package com.clockwork.core;

import java.util.List;

/**
 * Turns one thing that happened into the calls it should make on the
 * controller.
 *
 * <p>Triggers go through {@link RoutineController#start(String)},
 * {@link RoutineController#stop(String)}, and
 * {@link RoutineController#lap(String)}, exactly as the buttons and the hotkeys
 * do. There is no second path into a run, which is what keeps the arm semantics
 * in one place. In particular a start against a clock
 * that is already running is still ignored unless that clock has
 * {@link Routine#isRestartOnStart()}, so a herb run that is ten teleports long
 * is still one run.
 *
 * <p>Pure. It touches no client and no Swing, so the whole dispatch rule can be
 * exercised against a real controller and a fake clock.
 */
public final class TriggerEngine
{
	/**
	 * What one event means for one clock.
	 */
	public enum Action
	{
		NONE,
		START,
		STOP,
		LAP
	}

	private TriggerEngine()
	{
	}

	/**
	 * Whether any clock is waiting for this kind of event.
	 *
	 * <p>The plugin asks this whenever the clock list changes and remembers the
	 * answer, so a handler on a hot event such as an animation can return
	 * immediately, before it allocates anything, when nothing is configured.
	 *
	 * <p>The library is wanted rather than optional, so a clock pointing at a
	 * saved trigger that has since gone does not keep a handler switched on for
	 * an event nothing can act on.
	 */
	public static boolean wants(List<Routine> routines, TriggerLibrary library, TriggerEvent.Kind kind)
	{
		if (routines == null || kind == null)
		{
			return false;
		}

		final TriggerLibrary known = library == null ? TriggerLibrary.empty() : library;
		for (Routine routine : routines)
		{
			if (routine == null)
			{
				continue;
			}
			if (known.kind(routine.getStartTrigger()) == kind
				|| known.kind(routine.getStopTrigger()) == kind
				|| known.kind(routine.getLapTrigger()) == kind)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * What this event does to this clock.
	 *
	 * <p>Four rules, and the last two are the interesting half.
	 *
	 * <ol>
	 *   <li>A stop trigger on a clock that is not running does nothing. It does
	 *   not start one and it does not record a run of no length. A lap trigger
	 *   on one does nothing either, for the same reason, and neither does a lap
	 *   trigger on a clock with its splits switched off.</li>
	 *   <li>When a clock has the same trigger set for both start and stop, one
	 *   event toggles it. Start wins while it is idle and stop wins while it is
	 *   running, which is what makes "the bank chest" a sensible answer to both
	 *   questions at once.</li>
	 *   <li>When one event is both the lap trigger and the stop trigger, the
	 *   stop wins. Ending the run is the more final intent, and the closing lap
	 *   the controller writes at the end already gives the split on the way
	 *   out, so nothing is lost by it.</li>
	 *   <li>When one event is both the start trigger and the lap trigger, the
	 *   start wins on an idle clock, since a lap has no run to split. On a
	 *   running clock the start is the one that does nothing, because the arm
	 *   semantics ignore it, so the lap is what the event means and the lap is
	 *   what comes back. A clock that asks to be started over is the exception,
	 *   because there the start is not ignored and starting over is the more
	 *   final of the two.</li>
	 * </ol>
	 *
	 * <p>Starting a clock that is already running is still passed on rather
	 * than swallowed here, because whether that restarts the run is the
	 * controller's decision to make and it already knows how to make it.
	 */
	public static Action decide(Routine routine, TriggerLibrary library, boolean running, TriggerEvent event)
	{
		if (routine == null || event == null)
		{
			return Action.NONE;
		}

		final TriggerLibrary known = library == null ? TriggerLibrary.empty() : library;
		final boolean starts = known.matches(routine.getStartTrigger(), event);
		final boolean stops = known.matches(routine.getStopTrigger(), event);

		// A clock with its splits switched off has nowhere to put a lap, so its
		// lap trigger is not a setting that can do anything and is read as
		// though it were not there.
		final boolean laps = routine.isLapsEnabled() && known.matches(routine.getLapTrigger(), event);

		if (running)
		{
			if (stops)
			{
				return Action.STOP;
			}

			// The one case where a start against a running clock is not
			// ignored. It is the more final of the two, so it wins over a lap
			// the same event would otherwise have taken.
			if (starts && routine.isRestartOnStart())
			{
				return Action.START;
			}
			if (laps)
			{
				return Action.LAP;
			}
			return starts ? Action.START : Action.NONE;
		}

		// Idle. Neither a stop trigger nor a lap trigger has a run to act on,
		// so both are ignored outright.
		return starts ? Action.START : Action.NONE;
	}

	/**
	 * Applies the event to every clock.
	 *
	 * <p>Called on the thread the controller lives on, which for this plugin is
	 * the Swing event dispatch thread. The handlers hop before they get here.
	 */
	public static void dispatch(RoutineController controller, TriggerEvent event)
	{
		if (controller == null || event == null)
		{
			return;
		}

		// A copy, because starting or stopping fires listeners and a listener
		// is allowed to add or remove a clock.
		for (Routine routine : controller.getRoutines())
		{
			if (routine == null)
			{
				continue;
			}

			final String id = routine.getId();
			switch (decide(routine, controller.getLibrary(), controller.isRunning(id), event))
			{
				case START:
					controller.start(id);
					break;
				case STOP:
					controller.stop(id);
					break;
				case LAP:
					controller.lap(id);
					break;
				default:
					break;
			}
		}
	}
}

package com.clockwork.core;

/**
 * Something that happened in the game, flattened into the smallest shape a
 * trigger rule needs in order to judge it.
 *
 * <p>This is the boundary between the client and the rules. The plugin's event
 * handlers do the RuneLite specific work, filtering an animation down to the
 * local player and stripping the colour tags off a menu target, and then hand
 * one of these over. Everything past this point is plain data, which is why
 * {@link TriggerType#matches(TriggerEvent)} can be tested without a client,
 * without Swing, and without a game running.
 *
 * <p>Three kinds cover the whole seed vocabulary. A fourth trigger built on one
 * of the same kinds costs a line in {@link TriggerType} and nothing here.
 */
public final class TriggerEvent
{
	/**
	 * What sort of thing happened. Also what decides which handler in the
	 * plugin has to be listening at all, so a clock with no trigger of a given
	 * kind means the plugin never builds one.
	 */
	public enum Kind
	{
		/**
		 * The local player played an animation. Never another actor.
		 */
		ANIMATION,

		/**
		 * The player clicked a menu entry. Read only, the entry is neither
		 * changed nor consumed.
		 */
		MENU_CLICK,

		/**
		 * A game message addressed to the player arrived in the chat box.
		 */
		CHAT_MESSAGE
	}

	private final Kind kind;
	private final int animationId;
	private final String menuOption;
	private final String menuTarget;
	private final String message;

	private TriggerEvent(Kind kind, int animationId, String menuOption, String menuTarget, String message)
	{
		this.kind = kind;
		this.animationId = animationId;
		this.menuOption = menuOption == null ? "" : menuOption;
		this.menuTarget = menuTarget == null ? "" : menuTarget;
		this.message = message == null ? "" : message;
	}

	/**
	 * An animation the local player played. The caller has already checked
	 * that it was the local player.
	 */
	public static TriggerEvent animation(int animationId)
	{
		return new TriggerEvent(Kind.ANIMATION, animationId, null, null, null);
	}

	/**
	 * A menu entry the player clicked. Both strings are expected to have had
	 * their colour tags taken off already, because a raw target arrives
	 * wrapped in them and an unstripped comparison quietly never matches.
	 */
	public static TriggerEvent menuClick(String option, String target)
	{
		return new TriggerEvent(Kind.MENU_CLICK, -1, option, target, null);
	}

	/**
	 * A game message. Tags off, same reason as above.
	 */
	public static TriggerEvent chatMessage(String message)
	{
		return new TriggerEvent(Kind.CHAT_MESSAGE, -1, null, null, message);
	}

	public Kind getKind()
	{
		return kind;
	}

	/**
	 * The animation played, or -1 when this is not an animation event.
	 */
	public int getAnimationId()
	{
		return animationId;
	}

	/**
	 * Left hand side of the menu entry, such as "Use". Never null.
	 */
	public String getMenuOption()
	{
		return menuOption;
	}

	/**
	 * Right hand side of the menu entry, such as "Bank chest". Never null.
	 */
	public String getMenuTarget()
	{
		return menuTarget;
	}

	/**
	 * The chat line. Never null.
	 */
	public String getMessage()
	{
		return message;
	}

	@Override
	public String toString()
	{
		switch (kind)
		{
			case ANIMATION:
				return "animation " + animationId;
			case MENU_CLICK:
				return "click " + menuOption + " " + menuTarget;
			default:
				return "message " + message;
		}
	}
}

package com.clockwork.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.UUID;

/**
 * Every custom click trigger the user has named, and the rules for keeping
 * them.
 *
 * <p>A clock stores the name of an entry rather than a copy of its two
 * strings. That is the whole point of the library. Correcting the wording of
 * "Note herbs" once corrects every clock that waits for it, where copy on
 * select would have left the user with four slightly different versions of one
 * idea and no way to tell which clock had which.
 *
 * <p>The name is the identity, so a rename is the one edit that has to be
 * followed through onto the clocks. {@link #repoint} does that, and the
 * controller drives it, because the library does not hold clocks.
 *
 * <p>The rules the panel and the editor both need are here rather than in
 * either of them.
 *
 * <ul>
 *   <li>A name is trimmed, is not empty, and is not already taken</li>
 *   <li>An entry with neither string filled in is refused, because it would
 *   match every click in the game</li>
 *   <li>An entry that a clock points at cannot be deleted, and the clocks that
 *   point at it can be named so the user knows what to detach</li>
 *   <li>A name that no longer names an entry resolves to Nothing, so a hand
 *   edited config leaves a manual clock rather than a crash</li>
 * </ul>
 *
 * <p>Mutable, because it is a list the user edits, and owned by the controller
 * exactly as the clock list is. Pure all the same, so every rule above is
 * testable without Swing and without a client.
 */
public final class TriggerLibrary
{
	/**
	 * Kept in insertion order and sorted only when read, so an edit never
	 * shuffles the rows under the user's hand.
	 */
	private final List<SavedTrigger> entries = new ArrayList<>();

	private TriggerLibrary()
	{
	}

	public static TriggerLibrary empty()
	{
		return new TriggerLibrary();
	}

	/**
	 * A library from what came out of storage. Nulls and second copies of a
	 * name are dropped, because neither is something a clock could point at
	 * meaningfully. The first entry under a name wins, so a hand edited
	 * document that names one thing twice reads as the first of them rather
	 * than as neither.
	 */
	public static TriggerLibrary of(List<SavedTrigger> loaded)
	{
		final TriggerLibrary library = new TriggerLibrary();
		if (loaded == null)
		{
			return library;
		}

		for (SavedTrigger entry : loaded)
		{
			if (entry == null)
			{
				continue;
			}
			if (library.byName(entry.getName()) != null)
			{
				continue;
			}
			library.entries.add(entry);
		}
		return library;
	}

	/**
	 * Everything in it, by name, which is the order the dropdown and the panel
	 * both show. Case is ignored so "note herbs" does not sort away from "Note
	 * herbs".
	 */
	public List<SavedTrigger> all()
	{
		final List<SavedTrigger> sorted = new ArrayList<>(entries);
		sorted.sort(Comparator.comparing(entry -> Text.lower(entry.getName())));
		return Collections.unmodifiableList(sorted);
	}

	/**
	 * As stored, which is insertion order. Handed to the saver.
	 */
	public List<SavedTrigger> asStored()
	{
		return Collections.unmodifiableList(new ArrayList<>(entries));
	}

	/**
	 * The entry with this name, ignoring case and space, or null.
	 */
	public SavedTrigger byName(String name)
	{
		final String wanted = key(name);
		if (wanted == null)
		{
			return null;
		}
		for (SavedTrigger entry : entries)
		{
			if (wanted.equals(entry.key()))
			{
				return entry;
			}
		}
		return null;
	}

	/**
	 * Turns what a clock stores into what the rules can judge.
	 *
	 * <p>Three cases, and the third is the one worth writing a test for.
	 *
	 * <ol>
	 *   <li>A trigger that carries its own rule, which is anything that is not
	 *   a reference, comes back as it stands</li>
	 *   <li>A reference naming an entry that is here comes back as that entry's
	 *   click rule</li>
	 *   <li>A reference naming an entry that is not here comes back as Nothing.
	 *   A hand edited config, an imported document, or a clock copied between
	 *   profiles, must leave a manual clock rather than throw or fire on
	 *   everything</li>
	 * </ol>
	 */
	public Trigger resolve(Trigger trigger)
	{
		final Trigger held = Trigger.orNothing(trigger);
		final String ref = held.getRef();
		if (ref == null)
		{
			return held;
		}

		final SavedTrigger entry = byName(ref);
		return entry == null ? Trigger.nothing() : entry.toTrigger();
	}

	/**
	 * Whether this event is what that clock's trigger waits for, references
	 * resolved. The one question the dispatch path asks.
	 */
	public boolean matches(Trigger trigger, TriggerEvent event)
	{
		return resolve(trigger).matches(event);
	}

	/**
	 * The kind of event a trigger can possibly match, references resolved, or
	 * null when it can match none.
	 */
	public TriggerEvent.Kind kind(Trigger trigger)
	{
		return resolve(trigger).kind();
	}

	/**
	 * The phrase a clock card reads, as in "Starts on click, Note herbs".
	 *
	 * <p>A reference is worded by its name rather than by its two strings, so
	 * the card says the thing the user named. A reference to an entry that has
	 * gone reads as Nothing, matching what it actually does.
	 */
	public String hint(Trigger trigger)
	{
		final Trigger held = Trigger.orNothing(trigger);
		final String ref = held.getRef();
		if (ref == null)
		{
			return held.hint();
		}

		final SavedTrigger entry = byName(ref);
		if (entry == null)
		{
			return Trigger.nothing().hint();
		}
		return held.getType().hint() + ", " + entry.getName();
	}

	// Editing

	/**
	 * Why this cannot be saved, or null when it can.
	 *
	 * <p>{@code exceptName} is the entry being edited, which is allowed to keep
	 * its own name. Pass null when adding.
	 */
	public String problemWith(String name, String option, String target, String exceptName)
	{
		final String trimmed = name == null ? "" : name.trim();
		if (trimmed.isEmpty())
		{
			return "A custom trigger needs a name, so you can pick it out of the list later.";
		}

		final SavedTrigger clash = byName(trimmed);
		if (clash != null && !clash.key().equals(key(exceptName)))
		{
			return "There is already a custom trigger called " + clash.getName()
				+ ". Pick another name, or edit that one instead.";
		}

		final String cleanOption = Text.clean(option);
		final String cleanTarget = Text.clean(target);
		if (cleanOption == null && cleanTarget == null)
		{
			return "A custom trigger needs a menu option, a menu target, or both."
				+ " Left empty it would fire on every click in the game."
				+ " Turn on \"Show me what I click\" in the plugin settings to see the wording of a click.";
		}

		return null;
	}

	/**
	 * Adds an entry and hands it back. The caller is expected to have asked
	 * {@link #problemWith} first, and the check is repeated here because a
	 * library that can be talked into holding a name twice is not a library.
	 */
	public SavedTrigger add(String name, String option, String target)
	{
		final String problem = problemWith(name, option, target, null);
		if (problem != null)
		{
			throw new IllegalArgumentException(problem);
		}

		final SavedTrigger entry = SavedTrigger.of(name, option, target);
		entries.add(entry);
		return entry;
	}

	/**
	 * Renames an entry, or changes what it waits for, in place.
	 *
	 * <p>Changing what it waits for reaches every clock pointing at it for
	 * free, which is the entire reason the library exists. Changing its name
	 * does not, because the name is what a clock stores, so the caller has to
	 * follow it through with {@link #repoint}. The controller does that, since
	 * it is the one holding both the library and the clocks.
	 *
	 * @param currentName the entry to change, by the name it has now
	 * @return the entry as it now stands, or null when there is no such entry
	 */
	public SavedTrigger edit(String currentName, String name, String option, String target)
	{
		final SavedTrigger existing = byName(currentName);
		if (existing == null)
		{
			return null;
		}

		final String problem = problemWith(name, option, target, existing.getName());
		if (problem != null)
		{
			throw new IllegalArgumentException(problem);
		}

		final SavedTrigger edited = existing.with(name, option, target);
		entries.set(entries.indexOf(existing), edited);
		return edited;
	}

	/**
	 * Removes an entry. Whether anything still points at it is the caller's
	 * question to ask, through {@link #usedBy}, because the clock list is not
	 * this class's to hold.
	 *
	 * @return whether there was one to remove
	 */
	public boolean remove(String name)
	{
		final SavedTrigger existing = byName(name);
		return existing != null && entries.remove(existing);
	}

	/**
	 * Takes in an entry from a document somebody else wrote, and hands back the
	 * entry the importing clocks should point at.
	 *
	 * <p>Two cases, and they are the two an import has to get right.
	 *
	 * <ol>
	 *   <li>A name already here, asking for the same click, is the same idea
	 *   arriving twice. The one already here is handed back and nothing is
	 *   added, so importing a document twice does not double the library</li>
	 *   <li>A name already here, asking for a different click, is two ideas
	 *   with one name. The incoming one lands under a numbered name, and the
	 *   caller repoints the incoming clocks onto it. Refusing it would lose a
	 *   setting, and letting it overwrite would change what the user's existing
	 *   clocks wait for without being asked</li>
	 * </ol>
	 *
	 * <p>Unlike {@link #add} this does not refuse an entry with neither string
	 * filled in. Such an entry cannot fire, which is what
	 * {@link Trigger#matches} already says about it, and dropping it here would
	 * leave the clocks that named it pointing at nothing at all.
	 */
	public SavedTrigger absorb(String name, String option, String target)
	{
		final SavedTrigger existing = byName(name);
		if (existing != null && existing.asks(option, target))
		{
			return existing;
		}

		final SavedTrigger entry = SavedTrigger.of(uniqueName(name), option, target);
		entries.add(entry);
		return entry;
	}

	/**
	 * That name, or the first numbered variant of it that is free.
	 *
	 * <p>Only {@link #absorb} needs this, because it is the only thing in the
	 * plugin that has to land an entry whose name may already be taken. Every
	 * other way of adding one goes through {@link #problemWith} and refuses.
	 */
	private String uniqueName(String base)
	{
		final String wanted = base == null || base.trim().isEmpty() ? "Custom trigger" : base.trim();
		if (byName(wanted) == null)
		{
			return wanted;
		}

		for (int suffix = 2; suffix < 1000; suffix++)
		{
			final String candidate = wanted + " (" + suffix + ")";
			if (byName(candidate) == null)
			{
				return candidate;
			}
		}
		return wanted + " " + UUID.randomUUID();
	}

	/**
	 * The names of the clocks whose start, lap, or stop trigger points at this
	 * entry.
	 *
	 * <p>Static, and given the clock list, because the library does not hold
	 * clocks and should not start. The names rather than the ids, because this
	 * is read out to the user when a delete is refused and an id would tell
	 * them nothing.
	 */
	public static List<String> usedBy(List<Routine> routines, String name)
	{
		final List<String> used = new ArrayList<>();
		final String wanted = key(name);
		if (routines == null || wanted == null)
		{
			return used;
		}

		for (Routine routine : routines)
		{
			if (routine == null)
			{
				continue;
			}
			if (wanted.equals(key(Trigger.orNothing(routine.getStartTrigger()).getRef()))
				|| wanted.equals(key(Trigger.orNothing(routine.getLapTrigger()).getRef()))
				|| wanted.equals(key(Trigger.orNothing(routine.getStopTrigger()).getRef())))
			{
				used.add(routine.getName());
			}
		}
		return used;
	}

	/**
	 * Points every clock waiting for one name at another name instead.
	 *
	 * <p>This is what a rename costs now that a clock stores the name rather
	 * than a generated id. Without it, renaming "Note herbs" to "Leprechaun"
	 * would leave every clock waiting for a trigger that no longer exists, and
	 * those clocks would quietly stop firing while still looking configured.
	 *
	 * <p>Static, and given the clock list, for the same reason {@link #usedBy}
	 * is. The library does not hold clocks.
	 *
	 * @return how many clocks were changed
	 */
	public static int repoint(List<Routine> routines, String fromName, String toName)
	{
		final String wanted = key(fromName);
		final String replacement = Text.clean(toName);
		if (routines == null || wanted == null || replacement == null || wanted.equals(key(replacement)))
		{
			return 0;
		}

		int changed = 0;
		for (Routine routine : routines)
		{
			if (routine == null)
			{
				continue;
			}

			boolean touched = false;
			if (wanted.equals(key(Trigger.orNothing(routine.getStartTrigger()).getRef())))
			{
				routine.setStartTrigger(Trigger.saved(replacement));
				touched = true;
			}
			if (wanted.equals(key(Trigger.orNothing(routine.getLapTrigger()).getRef())))
			{
				routine.setLapTrigger(Trigger.saved(replacement));
				touched = true;
			}
			if (wanted.equals(key(Trigger.orNothing(routine.getStopTrigger()).getRef())))
			{
				routine.setStopTrigger(Trigger.saved(replacement));
				touched = true;
			}
			if (touched)
			{
				changed++;
			}
		}
		return changed;
	}

	private static String key(String text)
	{
		final String cleaned = Text.clean(text);
		return cleaned == null ? null : Text.lower(cleaned);
	}
}

package com.clockwork.core;

import com.google.gson.annotations.SerializedName;

/**
 * A thing that can start or stop a clock on its own.
 *
 * <p>Each clock owns its own start trigger and its own stop trigger, and a
 * trigger only ever acts on the clock it is set on. There is no broadcast and
 * no global list, so two clocks both set to start on teleporting each start
 * themselves and nothing else.
 *
 * <h2>Why this list is so short, and why it has to stay that way</h2>
 *
 * <p>Every member here is one of three things, and nothing else is allowed to
 * be added.
 *
 * <ol>
 *   <li>An animation the local player played</li>
 *   <li>A menu entry the player clicked</li>
 *   <li>A game message addressed to the player</li>
 * </ol>
 *
 * <p>All three are the player's own actions, reported back to the player. None
 * of them is information about anybody or anything else.
 *
 * <p>{@link #CUSTOM_CLICK} lets the user describe the click themselves rather
 * than pick one this file already knows about. That is still the second kind
 * and it is precedented. A hub plugin shipped the same matcher, free text
 * option and target compared against the entry the player clicked, and lived on
 * the hub with it for two years. It was eventually pulled at Jagex's request,
 * and not for the matcher. It was pulled for what it did with the click, which
 * was to minimise the client window. The risk in a plugin is in what it does
 * with an event rather than in how it observes one, and starting a timer is
 * about as little as a plugin can do.
 *
 * <p>RuneLite hub reviewers police what a plugin makes possible, not what it
 * was meant for. The sound-triggers plugin shipped a "Player Seen" trigger and
 * had it pulled the next day, because a trigger that fires on another actor is
 * a trigger somebody can point at a boss, a PvP opponent, or a crowd. That is
 * true no matter what the author intended it for.
 *
 * <p>So this plugin does not subscribe to {@code ProjectileMoved},
 * {@code HitsplatApplied}, {@code ActorDeath}, or {@code InteractingChanged},
 * and does not read animations or spawns of anything that is not the local
 * player. Adding a trigger built on any of those turns a timer into a combat
 * helper and gets the whole plugin rejected, so do not add one. If a future
 * trigger cannot be expressed as one of the three kinds above, it does not
 * belong here.
 *
 * <p>The matching itself is a pure function of a {@link TriggerEvent}, which is
 * what keeps it in this package and out of the client.
 */
public enum TriggerType
{
	/**
	 * The default, and what every clock had before triggers existed. Matches
	 * nothing at all, so the clock is driven by hand.
	 */
	@SerializedName("none")
	NONE("Nothing (manual only)", "nothing", null),

	/**
	 * The player teleported. See {@link TeleportAnimations} for which
	 * animations count.
	 */
	@SerializedName("teleport")
	TELEPORT("Teleporting", "teleporting", TriggerEvent.Kind.ANIMATION),

	/**
	 * The player used something called a bank chest. Only the options that do
	 * something to the chest count, so Examine does not fire it.
	 */
	@SerializedName("bankchest")
	BANK_CHEST("Using a bank chest", "using a bank chest", TriggerEvent.Kind.MENU_CLICK),

	/**
	 * The player got an iron ore out of a rock.
	 */
	@SerializedName("mineiron")
	MINE_IRON("Mining iron ore", "mining iron ore", TriggerEvent.Kind.CHAT_MESSAGE),

	/**
	 * The player clicked a menu entry they described themselves, by option, by
	 * target, or by both.
	 *
	 * <p>The only member whose rule is not written in this file, because it is
	 * the only one that cannot be. What counts as a match depends on what the
	 * user typed, so the rule lives in {@link Trigger} beside the two strings
	 * it needs and {@link #matches(TriggerEvent)} below answers false for this
	 * member on purpose.
	 *
	 * <p>It is still one of the three kinds above. A click is the player's own
	 * action, reported back to the player, and it is read rather than changed,
	 * added to, or consumed. Free text does not widen the event surface at all,
	 * it only widens which of the player's own clicks a clock can care about.
	 *
	 * <p>A clock set to this holds the name of a {@link SavedTrigger} rather
	 * than the strings themselves, since every custom trigger is named and kept
	 * in a {@link TriggerLibrary}. The label reads Custom, and the dropdown row that
	 * carries it is the one that defines a new saved trigger.
	 */
	@SerializedName("custom")
	CUSTOM_CLICK("Custom", "click", TriggerEvent.Kind.MENU_CLICK);

	/**
	 * The target text of a bank chest menu entry, lower cased. Tags are
	 * expected to be off by the time the rule sees the string.
	 */
	private static final String BANK_CHEST_TARGET = "bank chest";

	/**
	 * Menu options that mean the player actually used the chest, lower cased.
	 *
	 * <p>The rule used to look at the target alone, so every entry on a bank
	 * chest fired it, Examine included. Reading the description of a chest is
	 * not banking at it, and a clock that starts or stops because somebody
	 * looked at something is a clock the user cannot trust.
	 *
	 * <p>It is a small set rather than one string because chests differ.
	 * Most read "Use", some read "Bank", the deposit ones read "Deposit", and
	 * a few are opened rather than used. Anything outside the set, whether it
	 * is Examine, Walk here, or something added to the game later, does not
	 * count as using the chest.
	 */
	private static final String[] BANK_CHEST_OPTIONS = {"use", "bank", "open", "deposit"};

	/**
	 * Named so the exclusion is written down rather than merely implied by the
	 * list above. If that list is ever widened, this still holds.
	 */
	private static final String EXAMINE = "examine";

	/**
	 * Opening of the message the game sends when a rock gives up an ore. Taken
	 * from RuneLite's own item charge plugin, which matches "You manage to mine
	 * some clay." for the same reason.
	 */
	private static final String MINE_PREFIX = "you manage to mine some ";

	/**
	 * What has to appear after that opening for the ore to be an iron one.
	 * Matched as a substring rather than as an exact ending, so the rule holds
	 * whether the game says "iron" or "iron ore".
	 */
	private static final String IRON = "iron";

	private final String label;
	private final String hint;

	/**
	 * The kind of event this trigger can possibly match, or null for
	 * {@link #NONE}. The plugin reads this to work out which handlers have any
	 * work to do, so a client with no trigger configured anywhere does not pay
	 * for one.
	 */
	private final TriggerEvent.Kind kind;

	TriggerType(String label, String hint, TriggerEvent.Kind kind)
	{
		this.label = label;
		this.hint = hint;
		this.kind = kind;
	}

	/**
	 * Reads a possibly missing trigger. A clock saved before triggers existed
	 * has neither field, and null means the same thing {@link #NONE} does.
	 */
	public static TriggerType orNone(TriggerType type)
	{
		return type == null ? NONE : type;
	}

	public TriggerEvent.Kind kind()
	{
		return kind;
	}

	/**
	 * The phrase used on a clock card, as in "Starts on teleporting".
	 */
	public String hint()
	{
		return hint;
	}

	/**
	 * Whether this event is the thing this trigger waits for.
	 *
	 * <p>Pure, and the only place a trigger rule is written down. The plugin's
	 * handlers normalise an event and then ask this, so every rule can be
	 * tested against a value rather than against a running game.
	 */
	public boolean matches(TriggerEvent event)
	{
		if (event == null || kind == null || event.getKind() != kind)
		{
			return false;
		}

		switch (this)
		{
			case TELEPORT:
				return TeleportAnimations.contains(event.getAnimationId());

			case BANK_CHEST:
				return Text.lower(event.getMenuTarget()).contains(BANK_CHEST_TARGET)
					&& isChestUse(Text.lower(event.getMenuOption()).trim());

			case MINE_IRON:
			{
				final String message = Text.lower(event.getMessage()).trim();
				return message.startsWith(MINE_PREFIX)
					&& message.substring(MINE_PREFIX.length()).contains(IRON);
			}

			case CUSTOM_CLICK:
				// Not answerable here. The rule is the user's two strings, and
				// a clock holds those on its Trigger rather than on this enum,
				// so Trigger.matches is the only place that can decide. Anyone
				// asking a bare CUSTOM_CLICK gets a no rather than a yes,
				// because a wrong yes would fire on every click in the game.
				return false;

			default:
				return false;
		}
	}

	/**
	 * Whether a menu option is one of the ways a bank chest gets used. The
	 * option is expected to be lower cased and trimmed already.
	 */
	private static boolean isChestUse(String option)
	{
		if (option.isEmpty() || EXAMINE.equals(option))
		{
			return false;
		}

		for (String allowed : BANK_CHEST_OPTIONS)
		{
			if (allowed.equals(option))
			{
				return true;
			}
		}
		return false;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.clockwork.diag;

import lombok.extern.slf4j.Slf4j;

/**
 * The guard every entry point into the plugin is wrapped in.
 *
 * <p>A button, a listener, an event handler, or the refresh tick that throws
 * would otherwise surface as an uncaught exception somewhere the user cannot
 * act on, and in Swing it can leave a panel half built. {@link #guard} runs the
 * body, writes down anything it throws, and does not rethrow, so one broken
 * thing stays one broken thing.
 *
 * <p>Everything written here goes to the client's own log through slf4j. There
 * is no second log and no file.
 *
 * <p>It never throws. Not from a record, not from a guard. A reporting tool
 * that can take the client down with it is worse than no reporting tool.
 */
@Slf4j
public class Diagnostics
{
	private static final Diagnostics NONE = new Diagnostics(false);

	/**
	 * Whether anything is written down. False only on {@link #none()}, which
	 * stands in before the real one is handed over, and a half built component
	 * failing on its way to being wired is not news.
	 */
	private final boolean recording;

	public Diagnostics()
	{
		this(true);
	}

	private Diagnostics(boolean recording)
	{
		this.recording = recording;
	}

	/**
	 * An instance that writes nothing, for a holder that has not been handed
	 * the real one yet. It saves every caller a null check, and it still
	 * swallows, because the guard's job does not depend on the log.
	 */
	public static Diagnostics none()
	{
		return NONE;
	}

	/**
	 * Runs the body, records anything it throws, and does not rethrow.
	 *
	 * <p>This is the shape every entry point takes. A button that fails should
	 * leave a line in the log, not a stack trace on somebody's screen.
	 */
	public void guard(String context, Runnable body)
	{
		if (body == null)
		{
			return;
		}

		try
		{
			body.run();
		}
		catch (Throwable thrown)
		{
			record(context, thrown);
		}
	}

	/**
	 * A failure, at debug.
	 *
	 * <p>Debug rather than warn because of where this is called from. The
	 * refresh tick runs twenty times a second, so a failure that repeats is a
	 * failure that repeats every frame. Nothing on a hot path may log above
	 * debug.
	 */
	public void record(String context, Throwable thrown)
	{
		if (!recording)
		{
			return;
		}

		try
		{
			log.debug("failed in {}", name(context), thrown);
		}
		catch (Throwable ignored)
		{
			// Deliberately silent. This class is the place failures get said,
			// so there is nowhere left to say that saying one did not work.
		}
	}

	/**
	 * A notice the plugin means to make, at warn.
	 *
	 * <p>Higher than {@link #record(String, Throwable)} because this form is
	 * not reached from any repeating path. It is used where the plugin
	 * deliberately drops something the user would otherwise expect to keep, and
	 * it is the only trace of that decision.
	 */
	public void record(String context, String message)
	{
		if (!recording)
		{
			return;
		}

		try
		{
			log.warn("{}: {}", name(context), message == null ? "" : message);
		}
		catch (Throwable ignored)
		{
			// As above. Deliberately silent.
		}
	}

	private static String name(String context)
	{
		return context == null ? "clockwork" : context;
	}
}

package com.clockwork.history;

import com.clockwork.core.DurationFormat;
import com.clockwork.core.DurationFormatter;
import com.clockwork.core.Lap;
import com.clockwork.core.Run;
import com.clockwork.core.Status;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.List;

/**
 * Turns a finished run into one line of CSV.
 *
 * <p>Nothing here touches a disk. Building the text and putting the text
 * somewhere are kept apart so the shape of a row can be checked without a
 * temporary file, and so the formatting happens on the thread that finished
 * the run while only the write is handed off.
 *
 * <p>The file is a permanent log rather than a view of the plugin's state. It
 * is written once and never read back, which is what lets the file and the
 * plugin's own history be deleted independently of each other without either
 * one disagreeing with the other.
 */
public final class HistoryCsv
{
	public static final String HEADER = "routine,started_at,finished_at,duration_ms,duration,status,laps";

	/**
	 * Durations in the file are always rendered the same way, whatever the
	 * display settings happen to be at the time. A log written across months of
	 * changed settings still reads as one document.
	 */
	private static final DurationFormat FORMAT = DurationFormat.CLOCK_HUNDREDTHS;

	/**
	 * ISO-8601 local date and time, to the second. The fixed width matters more
	 * here than the fractions do, because the raw millis are in the row anyway.
	 */
	private static final DateTimeFormatter TIMESTAMP = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss");

	private static final char[] NEEDS_QUOTING = {',', '"', '\n', '\r'};

	private HistoryCsv()
	{
	}

	/**
	 * One row for one completed or abandoned run, without a line terminator.
	 *
	 * @param routineName the routine's name as it was at the moment the run
	 * ended, which is user supplied text and is escaped accordingly
	 * @param zone the zone the two timestamps are rendered in
	 */
	public static String row(String routineName, Run run, ZoneId zone)
	{
		StringBuilder out = new StringBuilder();
		out.append(escape(routineName)).append(',');
		out.append(timestamp(run.getStartedAtEpochMillis(), zone)).append(',');
		out.append(timestamp(run.getFinishedAtEpochMillis(), zone)).append(',');
		out.append(run.getDurationMillis()).append(',');
		out.append(DurationFormatter.format(run.getDurationMillis(), FORMAT)).append(',');
		out.append(status(run)).append(',');
		out.append(laps(run));
		return out.toString();
	}

	public static String timestamp(long epochMillis, ZoneId zone)
	{
		return TIMESTAMP.format(LocalDateTime.ofInstant(Instant.ofEpochMilli(epochMillis),
			zone == null ? ZoneId.systemDefault() : zone));
	}

	/**
	 * Splits as a pipe delimited list of total elapsed millis, empty for a run
	 * that took none. Pipes are used so the field never needs quoting.
	 */
	public static String laps(Run run)
	{
		List<Lap> laps = run.lapsOrEmpty();
		StringBuilder out = new StringBuilder();
		for (Lap lap : laps)
		{
			if (lap == null)
			{
				continue;
			}
			if (out.length() > 0)
			{
				out.append('|');
			}
			out.append(lap.getSplitMillis());
		}
		return out.toString();
	}

	/**
	 * Escapes one field the way RFC 4180 asks for. A field carrying a comma, a
	 * quote, or a line break is wrapped in quotes and its own quotes are
	 * doubled. Routine names are typed by the user, so this is not theoretical.
	 */
	public static String escape(String field)
	{
		if (field == null)
		{
			return "";
		}

		boolean quote = false;
		for (char c : NEEDS_QUOTING)
		{
			if (field.indexOf(c) >= 0)
			{
				quote = true;
				break;
			}
		}

		if (!quote)
		{
			return field;
		}

		StringBuilder out = new StringBuilder(field.length() + 2);
		out.append('"');
		for (int i = 0; i < field.length(); i++)
		{
			char c = field.charAt(i);
			if (c == '"')
			{
				out.append('"');
			}
			out.append(c);
		}
		out.append('"');
		return out.toString();
	}

	private static String status(Run run)
	{
		Status status = run.getStatus();
		return (status == null ? Status.COMPLETED : status).name();
	}
}

package com.clockwork.history;

import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.OutputStreamWriter;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import lombok.extern.slf4j.Slf4j;

/**
 * The permanent history file.
 *
 * <p>Every completed or abandoned run is appended here as one line, and the
 * file is never read back. The plugin's own history in the config cache stays
 * the source of truth for personal bests, averages, and everything else on
 * screen, so deleting this file changes no number anywhere, and clearing the
 * plugin's history leaves this file alone. That independence is the whole
 * point of writing it, and it is also why the fifty run cap on the cache does
 * not bound what ends up here.
 *
 * <p>Nothing in this class throws at its caller. A run happening is not the
 * moment to find out a disk is full, so a failed write is logged at debug,
 * remembered as a notice for the panel to show, and otherwise ignored.
 */
@Slf4j
public class HistoryFile
{
	/**
	 * Subdirectory of the RuneLite directory the file lives in by default.
	 */
	public static final String DIRECTORY = "clockwork";

	public static final String FILE_NAME = "history.csv";

	/**
	 * Written explicitly rather than taken from the platform, so a file moved
	 * between machines stays one consistent document.
	 */
	private static final String NEWLINE = "\n";

	/**
	 * Appends arrive from a background thread and the panel can change the
	 * target from the event dispatch thread, so the two are kept apart.
	 */
	private final Object lock = new Object();

	private volatile File target;

	/**
	 * Set when a write fails, cleared when one succeeds. The panel reads it to
	 * put a non-blocking line on screen.
	 */
	private volatile String notice;

	public HistoryFile(File target)
	{
		this.target = target;
	}

	public File getTarget()
	{
		return target;
	}

	/**
	 * Points the log at a different file. Only ever called with a path the user
	 * chose through a file chooser.
	 */
	public void setTarget(File file)
	{
		synchronized (lock)
		{
			this.target = file;
			this.notice = null;
		}
	}

	public String getNotice()
	{
		return notice;
	}

	public boolean exists()
	{
		File file = target;
		return file != null && file.isFile();
	}

	/**
	 * Appends one already formatted row, writing the header first if the file
	 * is being created. An existing file is only ever added to.
	 *
	 * @return true when the line reached the disk
	 */
	public boolean append(String row)
	{
		if (row == null)
		{
			return false;
		}

		synchronized (lock)
		{
			final File file = target;
			if (file == null)
			{
				return false;
			}

			try
			{
				final File directory = file.getParentFile();
				if (directory != null && !directory.isDirectory() && !directory.mkdirs())
				{
					return fail(file, "the folder could not be created");
				}

				final boolean fresh = !file.isFile() || file.length() == 0;
				try (Writer writer = new OutputStreamWriter(new FileOutputStream(file, true), StandardCharsets.UTF_8))
				{
					if (fresh)
					{
						writer.write(HistoryCsv.HEADER);
						writer.write(NEWLINE);
					}
					writer.write(row);
					writer.write(NEWLINE);
				}

				notice = null;
				return true;
			}
			catch (IOException | RuntimeException ex)
			{
				log.debug("could not append to the clockwork history file", ex);
				return fail(file, "it could not be written to");
			}
		}
	}

	/**
	 * Removes the file. The plugin's own history is untouched, so no statistic
	 * moves.
	 *
	 * @return true when there is no file left afterwards
	 */
	public boolean delete()
	{
		synchronized (lock)
		{
			final File file = target;
			if (file == null)
			{
				return false;
			}
			if (!file.exists())
			{
				notice = null;
				return true;
			}

			boolean gone;
			try
			{
				gone = file.delete();
			}
			catch (RuntimeException ex)
			{
				log.debug("could not delete the clockwork history file", ex);
				gone = false;
			}

			if (gone)
			{
				notice = null;
			}
			else
			{
				fail(file, "it could not be deleted");
			}
			return gone;
		}
	}

	private boolean fail(File file, String reason)
	{
		notice = "History file at " + file.getAbsolutePath() + " is not being written, " + reason
			+ ". Your runs are still being kept in the plugin.";
		log.debug("clockwork history file unusable, {}", notice);
		return false;
	}
}

package com.clockwork.overlay;

import com.clockwork.ClockworkConfig;
import com.clockwork.Formats;
import com.clockwork.core.DurationFormat;
import com.clockwork.core.DurationFormatter;
import com.clockwork.core.Lap;
import com.clockwork.core.Mode;
import com.clockwork.core.OverlayMode;
import com.clockwork.core.Overridable;
import com.clockwork.core.Routine;
import com.clockwork.core.RoutineController;
import com.clockwork.core.RoutineStats;
import com.clockwork.core.Run;
import com.clockwork.core.RunHistory;
import com.clockwork.diag.Diagnostics;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Supplier;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * The timer boxes, from the set of them down to what each one says.
 *
 * <p>Which clocks have a box is one question asked twice, once of the plugin
 * wide setting and once of the clock's own. {@link OverlayMode#NEVER} means no
 * box at all, {@link OverlayMode#WHILE_RUNNING} means a box that comes and goes
 * with the run, and {@link OverlayMode#ALWAYS} means a box that stays put while
 * the clock is idle, reading the last run it recorded. A clock answers for
 * itself through {@link com.clockwork.core.OverlayOverride}, and a clock that
 * defers gets whatever the config says. {@link Overridable} is the one place
 * that fallback is written down.
 *
 * <p>It has its own {@link #startUp()} and {@link #shutDown()}, which the
 * plugin calls, so the teardown that takes every box back off the overlay
 * manager sits next to the code that put them on. Stopping a plugin does not
 * remove its overlays for it.
 *
 * <h2>Config is read on change, not per tick</h2>
 *
 * <p>The settings this needs are cached in fields and refreshed from
 * {@link #configChanged()}. A RuneLite config interface is a Guice proxy and
 * every call on it is a lookup, so reading five of them twenty times a second
 * to notice a setting that changes once a month was work for nothing.
 */
public class OverlayCoordinator
{
	/**
	 * The narrowest a box is drawn, which is what an overlay panel asks for on
	 * its own.
	 */
	private static final int MINIMUM_WIDTH = 129;

	/**
	 * Roughly how wide one character of the overlay font is, and how much room
	 * the panel's border wants either side. Together they turn a character
	 * count into a width.
	 */
	private static final int WIDTH_PER_CHARACTER = 7;
	private static final int BORDER_WIDTH = 24;

	/**
	 * How many characters of clear air a two sided row wants between its left
	 * and its right, so a lap label and its time are not drawn touching.
	 */
	private static final int ROW_GAP = 2;

	/**
	 * How much of its point size one digit of the time takes up sideways.
	 * Measured off the face rather than reasoned about, and generous, since the
	 * cost of asking for too much is a little empty box and the cost of asking
	 * for too little is a timer drawn over its own border.
	 */
	private static final float TIME_WIDTH_RATIO = 0.7f;

	/**
	 * The size the timer is drawn at when nothing says otherwise, and the
	 * fallback when there is no config to ask.
	 */
	private static final int DEFAULT_FONT_SIZE = 24;

	private final Plugin plugin;
	private final OverlayManager overlayManager;
	private final ClockworkConfig config;
	private final Diagnostics diagnostics;

	/**
	 * The live controller, asked for rather than held, because the plugin drops
	 * it on shutdown and replaces it on a profile switch.
	 */
	private final Supplier<RoutineController> controller;

	/**
	 * Every box currently on the overlay manager, by clock id. Everything put
	 * in here was added to the manager and everything taken out of here was
	 * removed from it.
	 */
	private final Map<String, RoutineOverlay> overlays = new LinkedHashMap<>();

	/**
	 * Set by {@link #shutDown()}, so a refresh tick already queued on the event
	 * dispatch thread cannot put a box back after the teardown has run. Written
	 * on whichever thread stops the plugin and read on the event dispatch
	 * thread, hence volatile. Without it the last tick of a plugin being
	 * switched off can add a box that nothing will ever remove, which is the
	 * exact leak the teardown exists to prevent.
	 *
	 * <p>{@link OverlayMode#ALWAYS} makes that more likely rather than less. A
	 * box under that setting is wanted whether or not anything is running, so
	 * the queued tick's answer to "should this clock have a box" is yes even on
	 * a client where nothing has been started all session. {@link #update(long)}
	 * reads this before it reads anything else, and it is the only place a box
	 * is added, so there is one door and it is shut first.
	 */
	private volatile boolean tornDown;

	// Config, cached. See the note on this class.
	private DurationFormat format = DurationFormat.CLOCK_TENTHS;

	/**
	 * The same spec with the fractional part dropped, which is what a best time
	 * is written in on the footer row. Derived beside the other rather than
	 * where it is used, because deriving it there meant a fresh one per idle
	 * box per tick.
	 */
	private DurationFormat coarseFormat = DurationFormat.CLOCK_TENTHS.withoutSubSecond();

	private OverlayMode globalVisibility = OverlayMode.WHILE_RUNNING;
	private boolean globalDelta = true;
	private int fontSize = DEFAULT_FONT_SIZE;

	/**
	 * How far back the windowed average on an idle box reaches. Defaulted to
	 * the whole recent window, which is both the config default and the most
	 * the setting can be, so a box drawn before there is a config to ask says
	 * the same thing the config would have said.
	 */
	private int averageWindow = RunHistory.RECENT_KEPT;

	// The derived face and the size it was derived at, kept together so one
	// comparison says whether the other is still the right answer.
	private Font timeFont;
	private int timeFontSize;

	public OverlayCoordinator(Plugin plugin, OverlayManager overlayManager, ClockworkConfig config,
		Diagnostics diagnostics, Supplier<RoutineController> controller)
	{
		this.plugin = plugin;
		this.overlayManager = overlayManager;
		this.config = config;
		this.diagnostics = diagnostics == null ? Diagnostics.none() : diagnostics;
		this.controller = controller;
	}

	/**
	 * Reads the settings this draws with. No box is added here, because which
	 * ones exist is decided by the clock list and {@link #update(long)} is what
	 * asks.
	 */
	public void startUp()
	{
		readConfig();
	}

	/**
	 * Takes every box back off the overlay manager, mirroring the adds in
	 * {@link #update(long)}. This is the whole teardown.
	 */
	public void shutDown()
	{
		tornDown = true;
		removeAll();
	}

	/**
	 * Re-reads config after a setting changed. A setting that takes boxes away
	 * takes them away on the next tick, which the plugin wakes the refresh for.
	 */
	public void configChanged()
	{
		readConfig();
	}

	/**
	 * Brings the set of boxes in line with the set of clocks that want one, and
	 * publishes what each one says next frame.
	 *
	 * <p>Called from the refresh timer, on the event dispatch thread. Every
	 * string and every colour on a box is worked out here, so the render that
	 * follows does nothing but draw.
	 *
	 * <p>The alert window is passed in rather than held, because
	 * {@link com.clockwork.Alerts} owns it and one owner is what stops the two
	 * disagreeing about when a flash ends. Under the ordinary setting a box
	 * exists only while its clock runs, so without this the box of the clock
	 * that just finished would be taken away on the very tick that started its
	 * alert and the flash would never be seen.
	 *
	 * @param flashingRoutineId the clock whose box is mid alert, or null
	 * @param flashUntilMillis when that alert ends
	 */
	public void update(long now, String flashingRoutineId, long flashUntilMillis)
	{
		if (tornDown)
		{
			return;
		}

		final RoutineController current = controller.get();
		if (current == null)
		{
			removeAll();
			return;
		}

		// Off first, so a clock that stopped has given its box back before a
		// clock that started asks for one.
		for (Iterator<Map.Entry<String, RoutineOverlay>> boxes = overlays.entrySet().iterator();
			boxes.hasNext();)
		{
			final Map.Entry<String, RoutineOverlay> box = boxes.next();
			final Routine routine = current.get(box.getKey());
			final boolean flashing = box.getKey().equals(flashingRoutineId) && now < flashUntilMillis;
			if (routine == null || (!flashing && !wantsBox(current, routine)))
			{
				overlayManager.remove(box.getValue());
				boxes.remove();
			}
		}

		// Every clock rather than every running clock, because a clock set to
		// always show wants a box while it is idle. This is the same one list
		// per tick the refresh already asks the controller for, and the test
		// per clock is an enum comparison.
		for (Routine routine : current.getRoutines())
		{
			final String id = routine.getId();
			RoutineOverlay overlay = overlays.get(id);
			if (overlay == null)
			{
				// A box is only ever created because a setting asks for one. A
				// box kept alive for an alert is one that was already there,
				// since an alert can only flash a box it found, so nothing here
				// has to account for one.
				if (!wantsBox(current, routine))
				{
					continue;
				}

				overlay = new RoutineOverlay(plugin, id, diagnostics);
				overlays.put(id, overlay);
				// Adding is also what restores this clock's saved position.
				overlayManager.add(overlay);
			}

			// Whatever is on screen is kept current, including a box being held
			// open for an alert, which reads the run it just finished.
			overlay.setSnapshot(snapshot(current, routine, now));
		}
	}

	/**
	 * One clock's box, or null when that clock has not got one on screen.
	 *
	 * <p>Handed out so an alert can flash it. Null is a real answer rather than
	 * a defensive one, and it is what the timer box setting turned to never
	 * looks like from the alert path.
	 */
	public RoutineOverlay overlay(String routineId)
	{
		return overlays.get(routineId);
	}

	/**
	 * Ends any blink on any box. Called when an alert is cleared, which happens
	 * on its deadline and whenever a new run starts.
	 */
	public void clearFlashes()
	{
		for (RoutineOverlay overlay : overlays.values())
		{
			overlay.clearFlash();
		}
	}

	/**
	 * Whether this clock has a box on screen right now, which is its own
	 * setting when it has one and the config's when it does not.
	 */
	private boolean wantsBox(RoutineController current, Routine routine)
	{
		final OverlayMode visibility = Overridable.resolve(routine.getOverlay(), globalVisibility);
		if (visibility == OverlayMode.ALWAYS)
		{
			return true;
		}
		return visibility == OverlayMode.WHILE_RUNNING && current.isRunning(routine.getId());
	}

	private void readConfig()
	{
		format = Formats.of(config);
		coarseFormat = format.withoutSubSecond();
		globalVisibility = config == null ? OverlayMode.WHILE_RUNNING : orDefault(config.overlayVisibility());
		globalDelta = config == null || config.showPbDelta();
		fontSize = config == null ? DEFAULT_FONT_SIZE : config.fontSize();
		averageWindow = config == null ? RunHistory.RECENT_KEPT : config.averageWindow();
	}

	/**
	 * The config's answer, or the default when there is not one.
	 *
	 * <p>A RuneLite config proxy hands back null for an enum item whose stored
	 * value no longer names a constant, so this is a real case rather than a
	 * defensive one, and null here would take every box away rather than leave
	 * the setting where the user left it.
	 */
	private static OverlayMode orDefault(OverlayMode mode)
	{
		return mode == null ? OverlayMode.WHILE_RUNNING : mode;
	}

	/**
	 * The time face at the size asked for, derived once and kept.
	 *
	 * <p>Cached because this is asked for once per running clock per refresh
	 * and deriving a font is not free. The size only moves when somebody drags
	 * the setting, so the cache misses about as often as that happens.
	 */
	private Font timeFont(int size)
	{
		if (timeFont == null || timeFontSize != size)
		{
			timeFontSize = size;
			timeFont = FontManager.getRunescapeBoldFont().deriveFont((float) size);
		}
		return timeFont;
	}

	private void removeAll()
	{
		if (overlays.isEmpty())
		{
			return;
		}

		for (RoutineOverlay overlay : overlays.values())
		{
			overlayManager.remove(overlay);
		}
		overlays.clear();
	}

	/**
	 * One box's next frame, read the same way the side panel reads a clock, so
	 * the two can never disagree about the same run.
	 *
	 * <p>Every row below the time is left off when it has nothing to say. The
	 * split in progress is only a row on a clock that takes splits, the delta is
	 * only a row when this clock shows one and has a best to measure against,
	 * the footer carries the best time while the clock is idle or the reason it
	 * is not moving while it runs, and the two average rows are only on an idle
	 * box with completed runs behind it. A plain stopwatch that has never
	 * finished a run is still two lines tall.
	 *
	 * <p>Everything is worked out here, on the refresh tick, so the render that
	 * follows does nothing but draw. The laps are asked for once and used
	 * twice, because asking twice is a second list wrapper per box per tick for
	 * the same answer.
	 */
	private OverlaySnapshot snapshot(RoutineController current, Routine routine, long now)
	{
		final String id = routine.getId();
		final String title = routine.getName();

		final String time;
		final Color timeColor;
		String lapLabel = null;
		String lapTime = null;
		String deltaText = null;
		Color deltaColor = null;
		String statusText = null;
		String averageLabel = null;
		String averageText = null;
		String allTimeText = null;

		if (!current.isRunning(id))
		{
			// An idle box, which is what always show is for. It reads the last
			// run this clock finished, or zero when it has never finished one,
			// and it is grey because nothing on it is moving. The same number
			// the card in the side panel shows for an idle clock, from the same
			// derived statistics, so the two agree.
			final Run last = RoutineStats.lastCompleted(routine);
			time = DurationFormatter.format(last == null ? 0 : last.getDurationMillis(), format);
			timeColor = ColorScheme.LIGHT_GRAY_COLOR;

			final Run best = RoutineStats.personalBest(routine);
			statusText = best == null
				? "Not started"
				: "Best " + DurationFormatter.format(best.getDurationMillis(), coarseFormat);

			// Both averages, read from the same place the side panel reads
			// them, so an idle box and the card next to it cannot come to two
			// different answers about the same runs. The recent one says how
			// many runs it covers, because abandoned runs inside the window are
			// left out and the count is what makes that visible.
			final Long recent = RoutineStats.averageOfLast(routine, averageWindow);
			if (recent != null)
			{
				averageLabel = "last " + RoutineStats.completedInLast(routine, averageWindow);
				averageText = DurationFormatter.format(recent, coarseFormat);
			}

			final Long allTime = RoutineStats.allTimeAverage(routine);
			if (allTime != null)
			{
				allTimeText = DurationFormatter.format(allTime, coarseFormat);
			}
		}
		else
		{
			final long elapsed = current.elapsedMillis(id, now);
			final Long remaining = current.remainingMillis(id, now);
			final boolean countdown = routine.getMode() == Mode.COUNT_DOWN && remaining != null;

			time = DurationFormatter.format(countdown ? remaining : elapsed, format);

			if (current.isPaused(id))
			{
				timeColor = ColorScheme.LIGHT_GRAY_COLOR;
				statusText = "Paused, logged out";
			}
			else if (countdown && remaining < 0)
			{
				timeColor = ColorScheme.PROGRESS_ERROR_COLOR;
			}
			else
			{
				timeColor = Color.WHITE;
			}

			final boolean splits = routine.isLapsEnabled();
			// The clock's own setting wins, and falls back to the plugin wide
			// one when it is left on use global, exactly as the card resolves
			// it.
			final boolean delta = Overridable.resolve(routine.getShowDelta(), globalDelta);
			if (splits || delta)
			{
				final List<Lap> laps = current.currentLaps(id);

				if (splits)
				{
					lapLabel = RoutineStats.currentLapLabel(laps);
					lapTime = DurationFormatter.format(
						RoutineStats.currentLapMillis(laps, elapsed), format);
				}

				if (delta)
				{
					final Long gap = RoutineStats.liveDelta(routine, elapsed, laps);
					if (gap != null)
					{
						deltaText = DurationFormatter.formatSigned(gap, format);
						deltaColor = gap > 0
							? ColorScheme.PROGRESS_ERROR_COLOR
							: ColorScheme.PROGRESS_COMPLETE_COLOR;
					}
				}
			}
		}

		// Every row is measured, because any of them can be the wider one. The
		// rows below the time are drawn at the ordinary size so they count
		// characters at the ordinary rate, while the time scales with whatever
		// the setting says. A box that asks for too little does not wrap, it
		// draws over its own edge, and "Paused, logged out" is long enough to
		// do exactly that on a box left at its narrowest.
		int characters = title.length();
		if (lapTime != null)
		{
			characters = Math.max(characters, lapLabel.length() + lapTime.length() + ROW_GAP);
		}
		if (deltaText != null)
		{
			characters = Math.max(characters,
				RoutineOverlay.DELTA_LABEL.length() + deltaText.length() + ROW_GAP);
		}
		if (statusText != null)
		{
			characters = Math.max(characters, statusText.length());
		}
		if (averageText != null)
		{
			characters = Math.max(characters, averageLabel.length() + averageText.length() + ROW_GAP);
		}
		if (allTimeText != null)
		{
			characters = Math.max(characters,
				RoutineOverlay.ALL_TIME_LABEL.length() + allTimeText.length() + ROW_GAP);
		}

		final int width = Math.max(MINIMUM_WIDTH, Math.max(
			(int) (time.length() * fontSize * TIME_WIDTH_RATIO) + BORDER_WIDTH,
			characters * WIDTH_PER_CHARACTER + BORDER_WIDTH));

		return new OverlaySnapshot(title, time, timeColor, timeFont(fontSize),
			new Dimension(width, 0), lapLabel, lapTime, deltaText, deltaColor, statusText,
			averageLabel, averageText, allTimeText);
	}
}

package com.clockwork.overlay;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import lombok.Value;

/**
 * Everything one timer box needs for a frame, worked out in advance.
 *
 * <p>The refresh timer builds these, already formatted and already coloured,
 * and hands them to the overlay. The overlay's render method then does no
 * arithmetic and no string building of its own, which is the only way to keep
 * per frame work honest when the frame rate is whatever the client feels like.
 */
@Value
public class OverlaySnapshot
{
	String title;

	String time;
	Color timeColor;

	/**
	 * The face the time is drawn in, at whatever size the setting says.
	 *
	 * <p>Only the time carries it. The name above stays at the size every
	 * other overlay in the client uses, because the point of the setting is to
	 * read a running clock from across the room, and a name blown up to match
	 * would cost the box the width without earning any of it.
	 */
	Font timeFont;

	/**
	 * The width the box asks for, estimated from the text rather than measured,
	 * because measuring needs a font metrics and that only exists inside a
	 * frame. A box that asks for too little draws the name outside itself.
	 */
	Dimension preferredSize;

	/**
	 * Which split the run is on and how long that split has been going, or null
	 * on a clock that is not taking splits.
	 *
	 * <p>The two travel together and the time is the one the overlay tests, so
	 * a null there is what leaves the row off. Without this row a clock records
	 * its splits perfectly and shows none of them until the run is over, which
	 * reads on screen as a Lap button that does nothing.
	 */
	String lapLabel;
	String lapTime;

	/**
	 * The gap to this clock's best run, already signed and already formatted,
	 * or null when the clock is not showing one or has no best to compare
	 * against.
	 */
	String deltaText;
	Color deltaColor;

	/**
	 * The footer line, which is the best time on an idle box and the reason a
	 * running one is not moving. Null when there is nothing to say.
	 */
	String statusText;

	/**
	 * The average over the recent window, on an idle box, with the label saying
	 * how many runs it came from. Null on a running box and on a clock with no
	 * completed runs behind it.
	 *
	 * <p>The label travels rather than being written in the overlay, because the
	 * user chooses how far back the window goes and abandoned runs inside it are
	 * left out, so the number is not a constant. The two halves move together
	 * and the text is the one the overlay tests, which is what leaves the row
	 * off.
	 */
	String averageLabel;
	String averageText;

	/**
	 * The average over every completed run this clock has ever recorded, on the
	 * same terms. Null when there has not been one.
	 *
	 * <p>Beside the windowed one rather than instead of it. They answer
	 * different questions, how the user is running now and how they have run all
	 * along, and a box that showed only one of them would be the surface that
	 * disagreed with the side panel.
	 */
	String allTimeText;
}

package com.clockwork.overlay;

import com.clockwork.diag.Diagnostics;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * One draggable timer box, showing a clock's name, how long it has been
 * running, and, when there is anything to say about them, the split in
 * progress, the gap to the best run, and a footer line.
 *
 * <p>Every row below the time is optional and is left off rather than blanked,
 * so the box is only ever as tall as it has something to fill. An idle box, the
 * one the always show setting leaves on screen, is where the two averages
 * appear, since a box with a run going has rows of its own that are moving.
 *
 * <p>This is a panel overlay rather than an infobox on purpose. Infoboxes share
 * one tray at one user wide size, so two clocks running at once cannot be put
 * in two different corners.
 *
 * <p>Position and size are saved by RuneLite itself, and dragging is its work
 * too, so there is no drag code here. See {@link #getName()} for the one part
 * of that which does have to be handled.
 */
public class RoutineOverlay extends OverlayPanel
{
	/**
	 * How long the box spends on one colour before swapping to the other. Fixed
	 * rather than derived from anything, so a blink is the same speed whatever
	 * the frame rate happens to be and cannot turn into a strobe.
	 */
	private static final long BLINK_PERIOD_MILLIS = 400L;

	/**
	 * The left hand side of the delta row, which never changes, so it is set
	 * once at construction rather than per frame.
	 *
	 * <p>Package visible because the coordinator measures it when it works out
	 * how wide the box has to be, and a second copy of the wording there is a
	 * second thing to keep in step.
	 */
	static final String DELTA_LABEL = "vs best";

	/**
	 * The left hand side of the all time average row, which never changes, so
	 * it is treated exactly as the delta label above is. The windowed average
	 * beside it has no constant label, because how many runs it covers is the
	 * user's setting, so that one travels on the snapshot.
	 */
	static final String ALL_TIME_LABEL = "all time";

	/**
	 * The key RuneLite files this box's saved position under. Built once
	 * rather than per call, since {@link #getName()} is asked on every add,
	 * drag, and save.
	 */
	private final String name;

	private final Diagnostics diagnostics;

	// Rendered rows are built once and mutated in place. Re-adding the same
	// instances each frame keeps the panel's layout while allocating nothing.
	private final TitleComponent titleRow = TitleComponent.builder().text("").build();
	private final LineComponent timeRow = LineComponent.builder().left("").build();
	private final LineComponent lapRow = LineComponent.builder().left("").right("").build();
	private final LineComponent deltaRow = LineComponent.builder().left(DELTA_LABEL).right("").build();
	private final LineComponent statusRow = LineComponent.builder().left("").build();
	private final LineComponent averageRow = LineComponent.builder().left("").right("").build();
	private final LineComponent allTimeRow = LineComponent.builder().left(ALL_TIME_LABEL).right("").build();

	/**
	 * What to draw next frame. Written on the event dispatch thread by the
	 * coordinator and read on the client thread by {@link #render}, hence
	 * volatile.
	 */
	private volatile OverlaySnapshot snapshot;

	/**
	 * When the current blink ends, or zero when this box is not mid alert.
	 * Written on the event dispatch thread by the alerts and read on the client
	 * thread by {@link #render}, hence volatile, and read first so that a box
	 * which is not flashing does no clock arithmetic at all.
	 */
	private volatile long flashUntilMillis;
	private volatile Color flashColor = new Color(255, 0, 0, 90);

	public RoutineOverlay(Plugin plugin, String routineId, Diagnostics diagnostics)
	{
		super(plugin);
		this.name = "clockwork_" + routineId;
		this.diagnostics = diagnostics == null ? Diagnostics.none() : diagnostics;
		setPosition(OverlayPosition.DYNAMIC);
		setMovable(true);
		setSnappable(true);
		setResettable(true);
		setPriority(PRIORITY_HIGH);
	}

	/**
	 * Keyed per clock, so each box keeps its own saved position and size.
	 *
	 * <p>Without this override every instance answers {@code RoutineOverlay}
	 * and they all share one stored position, which reads as two boxes stacked
	 * on each other that will not stay where they are put.
	 */
	@Override
	public String getName()
	{
		return name;
	}

	/**
	 * Publishes the next frame's contents. Called from the refresh timer, and
	 * null hides the box entirely.
	 */
	public void setSnapshot(OverlaySnapshot snapshot)
	{
		this.snapshot = snapshot;
	}

	/**
	 * What this box will draw next frame, or null while it has nothing to draw.
	 *
	 * <p>The tests that pin what a box says read this. Rendering one needs a
	 * frame to draw in, so until there was a way to read the snapshot the only
	 * thing a test could check about a box was whether it existed.
	 */
	public OverlaySnapshot getSnapshot()
	{
		return snapshot;
	}

	/**
	 * Starts a bounded blink. Set once when a run ends, never per frame, so the
	 * deadline and the colour are both decided outside the render loop.
	 */
	public void flash(long untilMillis, Color color)
	{
		this.flashColor = color;
		this.flashUntilMillis = untilMillis;
	}

	public void clearFlash()
	{
		this.flashUntilMillis = 0;
	}

	/**
	 * Guarded with a plain try rather than a wrapper, because this runs every
	 * frame and the happy path must not allocate so much as a lambda.
	 */
	@Override
	public Dimension render(Graphics2D graphics)
	{
		try
		{
			return draw(graphics);
		}
		catch (Throwable thrown)
		{
			diagnostics.record("overlay.render", thrown);
			return null;
		}
	}

	private Dimension draw(Graphics2D graphics)
	{
		final OverlaySnapshot current = snapshot;
		if (current == null)
		{
			return null;
		}

		panelComponent.setBackgroundColor(lit() ? flashColor : ComponentConstants.STANDARD_BACKGROUND_COLOR);
		panelComponent.setPreferredSize(current.getPreferredSize());

		final List<LayoutableRenderableEntity> children = panelComponent.getChildren();

		titleRow.setText(current.getTitle());
		children.add(titleRow);

		timeRow.setLeft(current.getTime());
		timeRow.setLeftColor(current.getTimeColor());
		// The size setting reaches the box here. Only the time carries it, so
		// the name above stays the size every other overlay uses.
		timeRow.setLeftFont(current.getTimeFont());
		children.add(timeRow);

		// A row only appears when it has something to say. A clock with its
		// splits switched off has no lap row at all rather than an empty one,
		// which is what keeps a plain stopwatch's box two lines tall.
		if (current.getLapTime() != null)
		{
			lapRow.setLeft(current.getLapLabel());
			lapRow.setRight(current.getLapTime());
			children.add(lapRow);
		}

		if (current.getDeltaText() != null)
		{
			deltaRow.setRight(current.getDeltaText());
			deltaRow.setRightColor(current.getDeltaColor());
			children.add(deltaRow);
		}

		if (current.getStatusText() != null)
		{
			statusRow.setLeft(current.getStatusText());
			children.add(statusRow);
		}

		// The two averages, under the best time, so an idle box reads best,
		// then recent form, then all time. Both are left off on a running box,
		// where the rows above are the ones that are moving.
		if (current.getAverageText() != null)
		{
			averageRow.setLeft(current.getAverageLabel());
			averageRow.setRight(current.getAverageText());
			children.add(averageRow);
		}

		if (current.getAllTimeText() != null)
		{
			allTimeRow.setRight(current.getAllTimeText());
			children.add(allTimeRow);
		}

		return super.render(graphics);
	}

	/**
	 * Whether this frame is one of the lit ones.
	 *
	 * <p>The deadline is read before anything else, so the box that is not mid
	 * alert, which is every box on almost every frame, answers without reading
	 * a clock.
	 */
	private boolean lit()
	{
		final long until = flashUntilMillis;
		if (until == 0)
		{
			return false;
		}

		final long now = System.currentTimeMillis();
		return now < until && ((now / BLINK_PERIOD_MILLIS) & 1L) == 0L;
	}
}

package com.clockwork.overlay;

import com.clockwork.diag.Diagnostics;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import net.runelite.api.Client;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A translucent wash over the whole canvas, for the case where a timer box
 * blinking in the corner is not enough.
 *
 * <p>It is bounded in three ways on purpose. It stops at a deadline set once
 * when the run finished, it alternates on a fixed period rather than per
 * frame, and the colour comes from config and never changes on its own. A
 * timer is not worth giving anybody a headache over.
 *
 * <p>One instance, added once at start up and taken off once at shut down,
 * rather than one per clock. It is not tied to a clock, it draws nothing at all
 * until something asks it to flash, and a plugin that added and removed it
 * around every alert would be doing overlay manager work on the path where a
 * run ends.
 */
public class ScreenFlashOverlay extends Overlay
{
	private static final long BLINK_PERIOD_MILLIS = 400L;

	private final Client client;
	private final Diagnostics diagnostics;

	/**
	 * When the current flash ends, or zero when nothing is flashing. Written on
	 * the event dispatch thread by the alerts and read on the client thread by
	 * {@link #render}, hence volatile.
	 */
	private volatile long flashUntilMillis;
	private volatile Color color = new Color(255, 0, 0, 90);

	public ScreenFlashOverlay(Plugin plugin, Client client, Diagnostics diagnostics)
	{
		super(plugin);
		this.client = client;
		this.diagnostics = diagnostics == null ? Diagnostics.none() : diagnostics;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPriority(PRIORITY_HIGHEST);
		setMovable(false);
		setResizable(false);
		setSnappable(false);
	}

	public void flash(long untilMillis, Color color)
	{
		this.color = color;
		this.flashUntilMillis = untilMillis;
	}

	public void clearFlash()
	{
		this.flashUntilMillis = 0;
	}

	@Override
	public String getName()
	{
		return "clockwork_screenflash";
	}

	/**
	 * Guarded with a plain try rather than a wrapper, because this runs every
	 * frame and the happy path must not allocate so much as a lambda.
	 */
	@Override
	public Dimension render(Graphics2D graphics)
	{
		try
		{
			return draw(graphics);
		}
		catch (Throwable thrown)
		{
			diagnostics.record("overlay.screenFlash", thrown);
			return null;
		}
	}

	private Dimension draw(Graphics2D graphics)
	{
		final long until = flashUntilMillis;
		if (until == 0)
		{
			// The ordinary case, which is every frame of every session where
			// nothing has finished. Answered before the clock is read.
			return null;
		}

		final long now = System.currentTimeMillis();
		if (now >= until)
		{
			return null;
		}

		if (((now / BLINK_PERIOD_MILLIS) & 1L) != 0L)
		{
			return null;
		}

		final int width = client.getCanvasWidth();
		final int height = client.getCanvasHeight();
		graphics.setColor(color);
		graphics.fillRect(0, 0, width, height);
		return new Dimension(width, height);
	}
}

package com.clockwork.ui;

import java.awt.Toolkit;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.StringSelection;
import java.awt.datatransfer.Transferable;
import java.awt.datatransfer.UnsupportedFlavorException;
import java.io.IOException;

/**
 * The system clipboard, wrapped so a failure comes back as a sentence rather
 * than as an exception.
 *
 * <p>Reading the clipboard can fail for reasons that have nothing to do with
 * this plugin. Another program can hold it, the flavour on it can be an image,
 * and it can simply be empty. None of those are worth a stack trace and all of
 * them are worth telling the user about, so every path returns wording from
 * {@link PanelMessages} instead of throwing.
 *
 * <p>{@code java.awt.datatransfer} and nothing else. There is no file here, no
 * stream, and no path. The one thing in this file from {@code java.io} is the
 * checked exception the transfer method declares, which is caught and never
 * thrown, and it arrives with no filesystem behind it.
 *
 * <p>Called from Swing handlers, which are already on the event dispatch
 * thread. Nothing in here goes near the client thread and nothing in here
 * blocks.
 */
final class ClipboardText
{
	private ClipboardText()
	{
	}

	/**
	 * Puts text on the clipboard.
	 *
	 * @return null when it went on, or the wording to show when it did not
	 */
	static String write(String text)
	{
		try
		{
			Toolkit.getDefaultToolkit().getSystemClipboard()
				.setContents(new StringSelection(text == null ? "" : text), null);
			return null;
		}
		catch (RuntimeException ignored)
		{
			return PanelMessages.CLIPBOARD_UNWRITABLE;
		}
	}

	/**
	 * Takes text off the clipboard, or says why there is none to take.
	 */
	static Reading read()
	{
		final Transferable contents;
		try
		{
			contents = Toolkit.getDefaultToolkit().getSystemClipboard().getContents(null);
		}
		catch (RuntimeException ignored)
		{
			return Reading.problem(PanelMessages.CLIPBOARD_UNREADABLE);
		}

		if (contents == null || !contents.isDataFlavorSupported(DataFlavor.stringFlavor))
		{
			return Reading.problem(PanelMessages.NOTHING_TO_PASTE);
		}

		final Object held;
		try
		{
			held = contents.getTransferData(DataFlavor.stringFlavor);
		}
		catch (UnsupportedFlavorException | IOException | RuntimeException ignored)
		{
			return Reading.problem(PanelMessages.CLIPBOARD_UNREADABLE);
		}

		if (!(held instanceof String) || ((String) held).trim().isEmpty())
		{
			return Reading.problem(PanelMessages.NOTHING_TO_PASTE);
		}

		return Reading.of((String) held);
	}

	/**
	 * What came off the clipboard, or why nothing did. Ask
	 * {@link #getProblem()} first.
	 */
	static final class Reading
	{
		private final String text;
		private final String problem;

		private Reading(String text, String problem)
		{
			this.text = text;
			this.problem = problem;
		}

		private static Reading of(String text)
		{
			return new Reading(text, null);
		}

		private static Reading problem(String problem)
		{
			return new Reading(null, problem);
		}

		String getText()
		{
			return text;
		}

		/**
		 * The wording to show, or null when there is text to work with.
		 */
		String getProblem()
		{
			return problem;
		}
	}
}

package com.clockwork.ui;

import com.clockwork.ClockworkConfig;
import com.clockwork.ClockworkDocument;
import com.clockwork.ClockworkStorage;
