import com.clockwork.core.Routine;
import com.clockwork.core.RoutineController;
import com.clockwork.core.SavedTrigger;
import com.clockwork.core.TriggerLibrary;
import com.clockwork.diag.Diagnostics;
import com.clockwork.history.HistoryFile;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.GridLayout;
import java.io.File;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
