import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * The side panel.
 *
 * <p>It owns no timing state and no rules. It reads the controller, draws what
 * it finds, and sends every button press back to the controller.
 *
 * <p>Both public entry points hop to the event dispatch thread themselves, so
 * a caller coming off the client thread does not have to remember to.
 */
public class ClockworkPanel extends PluginPanel
{
	private final RoutineController controller;
	private final ClockworkConfig config;
	private final Diagnostics diagnostics;

	/**
	 * The permanent run log on disk. The panel shows where it is and offers to
	 * move or delete it. The plugin owns the file itself.
	 */
	private final HistoryFile historyFile;

	/**
	 * Persists a moved log file. The panel sets the new target on the file, and
	 * then hands the choice here so it survives a restart.
	 */
	private final Consumer<File> onHistoryFileMoved;

	/**
	 * Reads and writes the shared document. The panel holds it only for the
	 * share and edit section, because export, import, and applying an edit are
	 * all its work rather than the controller's.
	 */
	private final ClockworkStorage storage;

	/**
	 * The designated hotkey target, which the plugin owns. Cards read it to
	 * mark themselves and write it when the user picks one.
	 */
	private final HotkeyTargetHandle hotkeyTarget;

	private final JPanel list = new JPanel();
	private final Map<String, RoutineCard> cards = new LinkedHashMap<>();
	private final JLabel emptyLabel = new JLabel();

	/**
	 * The clock the user last clicked, drawn with a highlight so it is obvious
	 * which card the eye is on. It is also the last tiebreak a hotkey uses,
	 * below the designation and below a single running clock. Null when nothing
	 * is selected, and a second click on the selected card puts it back to
	 * null.
	 */
	private String selectedId;

	/**
	 * The rows of the saved trigger library, rebuilt whenever the library
	 * changes, which is whenever anything else about the clocks changes too.
	 */
	private final JPanel triggerList = new JPanel();

	/**
	 * The last thing the share and edit section did, kept on screen until it
	 * does something else. Every one of those buttons would otherwise end in
	 * silence, which is how somebody decides a button is broken.
	 */
	private final JLabel shareStatusLabel = new JLabel();

	/**
	 * Where the run log is kept, and any failed write to it. Held as fields
	 * because a profile switch and a failed background write both change what
	 * they say without a rebuild of the whole footer.
	 */
	private final JLabel filePathLabel = new JLabel();
	private final JLabel noticeLabel = new JLabel();

	/**
	 * The notice currently on screen, so a rebuild only touches the label when
	 * the file's own notice has actually changed.
	 */
	private String shownNotice;

	public ClockworkPanel(RoutineController controller, ClockworkConfig config,
		HistoryFile historyFile, Diagnostics diagnostics, Consumer<File> onHistoryFileMoved,
		HotkeyTargetHandle hotkeyTarget, ClockworkStorage storage)
	{
		this.controller = controller;
		this.config = config;
		this.historyFile = historyFile;
		this.diagnostics = diagnostics == null ? Diagnostics.none() : diagnostics;
		this.onHistoryFileMoved = onHistoryFileMoved;
		this.hotkeyTarget = hotkeyTarget;
		this.storage = storage;

		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JLabel title = new JLabel("Clockwork");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);

		JButton newClock = Controls.primary("New clock");
		newClock.setToolTipText("Make a clock for something you repeat");
		newClock.addActionListener(e -> diagnostics.guard("panel.newClock",
			() -> RoutineEditor.showCreate(this, controller, this.diagnostics)));

		JPanel header = new JPanel(new BorderLayout(0, 6));
		header.setBackground(getBackground());
		header.add(title, BorderLayout.NORTH);
		header.add(newClock, BorderLayout.CENTER);

		emptyLabel.setText("<html><div style='text-align:center'>No clocks yet."
			+ "<br><br>Make one for something you repeat, start it when you set off, and stop it when you are done."
			+ "<br><br>Clockwork remembers the runs so you can see whether you are getting quicker.</div></html>");
		emptyLabel.setFont(FontManager.getRunescapeSmallFont());
		emptyLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		emptyLabel.setHorizontalAlignment(SwingConstants.CENTER);

		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(getBackground());

		JPanel listHolder = new JPanel(new BorderLayout());
		listHolder.setBackground(getBackground());
		listHolder.add(list, BorderLayout.NORTH);

		add(header, BorderLayout.NORTH);
		add(listHolder, BorderLayout.CENTER);
		add(buildFooter(), BorderLayout.SOUTH);

		rebuild();
	}

	/**
	 * The history and trigger controls, kept at the bottom and away from the
	 * clock buttons because one of them destroys something.
	 *
	 * <p>Every section is a heading, a line saying what it is for, whatever it
	 * has to report, and a column of buttons. They are built through the helpers
	 * at the bottom of this class rather than by hand, so the three of them
	 * cannot end up with three different ideas of what a heading looks like.
	 */
	private JPanel buildFooter()
	{
		JPanel footer = new JPanel();
		footer.setLayout(new BoxLayout(footer, BoxLayout.Y_AXIS));
		footer.setBackground(getBackground());
		footer.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(1, 0, 0, 0, ColorScheme.DARKER_GRAY_COLOR),
			BorderFactory.createEmptyBorder(8, 0, 0, 0)));

		// Stored history
		footer.add(heading("Stored history", false));
		footer.add(explanation("<html>The recent runs of every clock, which is where best times "
			+ "and averages come from.</html>"));
		footer.add(buttonColumn(
			button("Clear stored history",
				"Empty the runs on every clock",
				"panel.clearStoredHistory", this::confirmClearStoredHistory)));

		// Run log
		styleSmall(filePathLabel, ColorScheme.LIGHT_GRAY_COLOR);
		styleSmall(noticeLabel, ColorScheme.PROGRESS_ERROR_COLOR);
		noticeLabel.setVisible(false);

		footer.add(heading("Run log", true));
		footer.add(explanation("<html>Every finished run is also written to a file on disk, so a "
			+ "permanent record survives past the runs a clock keeps. Moving or deleting it changes "
			+ "no time on screen.</html>"));
		footer.add(filePathLabel);
		footer.add(noticeLabel);
		footer.add(buttonColumn(
			button("Choose where it is kept",
				"Pick the file the run log is written to",
				"panel.moveHistoryFile", this::chooseHistoryFile),
			button("Delete the run log",
				"Remove the file. Your clocks, best times, and averages are not touched",
				"panel.deleteHistoryFile", this::confirmDeleteFile)));

		// Custom triggers
		triggerList.setLayout(new BoxLayout(triggerList, BoxLayout.Y_AXIS));
		triggerList.setBackground(getBackground());
		triggerList.setAlignmentX(Component.LEFT_ALIGNMENT);

		footer.add(heading("Custom triggers", true));
		footer.add(explanation("<html>Clicks you have named, which any clock can be set to "
			+ "start or stop on. Editing one here changes every clock that waits for it.</html>"));
		footer.add(triggerList);
		footer.add(buttonColumn(
			button("Add a custom trigger",
				"Name a click, so a clock can be set to start or stop on it",
				"panel.addTrigger", () -> SavedTriggerDialog.showCreate(this, controller))));

		// Share and edit
		styleSmall(shareStatusLabel, ColorScheme.LIGHT_GRAY_COLOR);
		shareStatusLabel.setVisible(false);

		footer.add(heading("Share and edit", true));
		footer.add(explanation("<html>Clocks travel as text. One clock on its own is in "
			+ "that clock's ... menu. Runs and best times never travel.</html>"));
		footer.add(shareStatusLabel);
		footer.add(buttonColumn(
			button("Copy all clocks",
				"Put every clock on the clipboard as text, ready to hand to somebody",
				"panel.copyAll", this::copyAll),
			button("Paste clocks in",
				"Read a document off the clipboard and add the clocks in it, leaving yours alone",
				"panel.pasteIn", this::pasteIn),
			button("Edit as text...",
				"Open your clocks as a document you can change, in a window big enough to read it in",
				"panel.editAsText", this::editAsText)));

		rebuildTriggers();
		refreshFilePath();
		return footer;
	}

	/**
	 * Rebuilds the clock list from the controller.
	 */
	public void rebuild()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::rebuild);
			return;
		}

		diagnostics.guard("panel.rebuild", this::doRebuild);
	}

	private void doRebuild()
	{
		// Before the shortcut below, because the library can change without the
		// clock list changing at all, which is what happens when a trigger is
		// renamed or a new one is added from down here.
		rebuildTriggers();

		List<Routine> routines = controller.getRoutines();
		List<String> ids = new ArrayList<>();
		for (Routine routine : routines)
		{
			ids.add(routine.getId());
		}

		// Worked out once for the whole pass. Every call reads four config
		// values back through the proxy, and there is a card and several
		// labels waiting on it.
		final DurationFormat format = Formats.of(config);

		// An empty list still has to fall through the first time, so the note
		// about what routines are for gets put on screen.
		boolean sameOrder = !ids.isEmpty() && ids.equals(new ArrayList<>(cards.keySet()));
		if (sameOrder)
		{
			for (RoutineCard card : cards.values())
			{
				card.refreshStatic(format);
			}
			refreshLive(controller.now(), format);
			refreshNotice();
			return;
		}

		list.removeAll();
		Map<String, RoutineCard> kept = new LinkedHashMap<>();
		for (Routine routine : routines)
		{
			RoutineCard card = cards.get(routine.getId());
			if (card == null)
			{
				card = new RoutineCard(controller, config, diagnostics, routine.getId(), this::select,
					hotkeyTarget, storage == null ? null : this::copyOne);
			}
			card.refreshStatic(format);
			kept.put(routine.getId(), card);
			list.add(card);
		}

		cards.clear();
		cards.putAll(kept);

		if (cards.isEmpty())
		{
			list.add(emptyLabel);
		}

		applySelection();
		refreshLive(controller.now(), format);
		refreshNotice();
		list.revalidate();
		list.repaint();
	}

	// Selection

	/**
	 * The clock a hotkey should act on when the panel is what decides, or null
	 * when nothing is selected or the selected clock has since gone.
	 *
	 * <p>This is a tiebreak and not the main mechanism. It only decides when no
	 * clock has been designated, because it is transient state that does not
	 * exist with the sidebar shut or after a restart.
	 *
	 * <p>Read from the event dispatch thread, which is where the hotkey
	 * handlers hop to before they ask.
	 */
	public String getSelectedRoutineId()
	{
		if (selectedId == null || controller.get(selectedId) == null)
		{
			return null;
		}
		return selectedId;
	}

	/**
	 * Selects a clock, or clears the selection when the selected one is
	 * clicked again.
	 */
	private void select(String routineId)
	{
		selectedId = routineId != null && routineId.equals(selectedId) ? null : routineId;
		applySelection();
	}

	private void applySelection()
	{
		for (Map.Entry<String, RoutineCard> entry : cards.entrySet())
		{
			entry.getValue().setSelected(entry.getKey().equals(selectedId));
		}
	}

	/**
	 * Updates the moving numbers. Called from the refresh timer.
	 */
	public void refreshLive(long now)
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(() -> refreshLive(now));
			return;
		}

		diagnostics.guard("panel.refreshLive", () -> refreshLive(now, Formats.of(config)));
	}

	private void refreshLive(long now, DurationFormat format)
	{
		for (RoutineCard card : cards.values())
		{
			card.refreshLive(now, format);
		}
	}

	// Stored history

	private void confirmClearStoredHistory()
	{
		final boolean go = Confirms.ask(this, "Clear stored history",
			"<b>Clear the stored runs of every clock.</b>"
				+ "<br><br>This empties every clock's runs, so every best time and every average goes "
				+ "back to nothing, all time averages included, and none of it can be got back."
				+ "<br><br>Runs in progress are not interrupted.");

		if (!go)
		{
			return;
		}

		controller.clearAllHistory();
	}

	// Run log

	/**
	 * Puts a failed write on screen without interrupting anything. A disk that
	 * will not take the log is not a reason to stop timing.
	 */
	private void refreshNotice()
	{
		final String notice = historyFile == null ? null : historyFile.getNotice();
		if (notice == null ? shownNotice == null : notice.equals(shownNotice))
		{
			return;
		}

		shownNotice = notice;
		noticeLabel.setText(notice == null ? "" : "<html>" + PanelMessages.escapeHtml(notice) + "</html>");
		noticeLabel.setVisible(notice != null);
		revalidate();
		repaint();
	}

	/**
	 * Re-reads the run log after something outside the panel moved it, which
	 * right now means a config profile switch. The path is a config key, so it
	 * follows the profile.
	 */
	public void refreshHistoryFile()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::refreshHistoryFile);
			return;
		}

		diagnostics.guard("panel.refreshHistoryFile", () ->
		{
			shownNotice = null;
			refreshFilePath();
			refreshNotice();
		});
	}

	private void refreshFilePath()
	{
		if (historyFile == null || historyFile.getTarget() == null)
		{
			filePathLabel.setText("");
			filePathLabel.setToolTipText(null);
			return;
		}

		final String path = historyFile.getTarget().getAbsolutePath();
		filePathLabel.setText("<html><span style='color:#a0a0a0'>"
			+ PanelMessages.escapeHtml(path) + "</span></html>");
		filePathLabel.setToolTipText(path);
	}

	/**
	 * The only way the file moves. A chooser is used rather than a typed in
	 * path, so the plugin never writes to a place the user did not point at.
	 */
	private void chooseHistoryFile()
	{
		if (historyFile == null)
		{
			return;
		}

		JFileChooser chooser = new JFileChooser();
		chooser.setDialogTitle("Where should Clockwork keep its run log");
		chooser.setFileSelectionMode(JFileChooser.FILES_ONLY);
		chooser.setSelectedFile(historyFile.getTarget());

		if (chooser.showSaveDialog(this) != JFileChooser.APPROVE_OPTION)
		{
			return;
		}

		File chosen = chooser.getSelectedFile();
		if (chosen == null)
		{
			return;
		}
		if (chosen.isDirectory())
		{
			chosen = new File(chosen, HistoryFile.FILE_NAME);
		}

		historyFile.setTarget(chosen);
		shownNotice = null;
		if (onHistoryFileMoved != null)
		{
			onHistoryFileMoved.accept(chosen);
		}
		refreshFilePath();
		refreshNotice();
	}

	private void confirmDeleteFile()
	{
		if (historyFile == null || historyFile.getTarget() == null)
		{
			return;
		}

		final String path = historyFile.getTarget().getAbsolutePath();
		final boolean go = Confirms.ask(this, "Delete the run log",
			"<b>Delete the run log on disk.</b>"
				+ "<br><br>This removes " + PanelMessages.escapeHtml(path) + " and every run written in it."
				+ "<br><br>Nothing on screen changes. Best times, averages, and the run lists in the panel "
				+ "come from the plugin's own stored history, which this leaves alone."
				+ "<br><br>A new file is started the next time a run ends.");

		if (!go)
		{
			return;
		}

		historyFile.delete();
		shownNotice = null;
		refreshFilePath();
		refreshNotice();
	}

	// Share and edit

	/**
	 * The one line the share section says about itself. Kept to a line, because
	 * the sidebar has no room for a paragraph and there are already two other
	 * footer sections competing for what it does have.
	 */
	private void setShareStatus(String text, boolean bad)
	{
		if (text == null || text.trim().isEmpty())
		{
			shareStatusLabel.setText("");
			shareStatusLabel.setToolTipText(null);
			shareStatusLabel.setVisible(false);
		}
		else
		{
			shareStatusLabel.setForeground(bad
				? ColorScheme.PROGRESS_ERROR_COLOR
				: ColorScheme.LIGHT_GRAY_COLOR);
			shareStatusLabel.setText("<html>" + PanelMessages.escapeHtml(text) + "</html>");
			shareStatusLabel.setToolTipText(text);
			shareStatusLabel.setVisible(true);
		}

		revalidate();
		repaint();
	}

	/**
	 * A refusal, which is always several sentences and always worth reading, so
	 * it gets a dialog as well as the status line.
	 *
	 * <p>The dialog carries every problem found, one to a line, and the status
	 * line carries the count, because the sidebar has room for a line and the
	 * problems are the point.
	 *
	 * <p>Shown through JOptionPane rather than through {@link Confirms}, because
	 * this body arrives as finished html from {@link PanelMessages} and the
	 * helper wraps a body of its own around what it is given.
	 */
	private void refuse(String title, List<DocumentProblem> problems)
	{
		JOptionPane.showMessageDialog(this, PanelMessages.refusalHtml(problems),
			title, JOptionPane.WARNING_MESSAGE);
		setShareStatus(PanelMessages.refusalLine(problems), true);
	}

	private void copyAll()
	{
		if (storage == null)
		{
			return;
		}

		final List<Routine> routines = controller.getRoutines();
		final String problem = ClipboardText.write(storage.exportAll(routines, controller.getLibrary()));
		setShareStatus(problem == null ? PanelMessages.copiedAll(routines.size()) : problem, problem != null);
	}

	/**
	 * One clock, from that clock's own menu. It lives on the card rather than
	 * down here because the card is where the user already goes to do something
	 * to one clock, and because a fourth button in a 225 pixel column is a
	 * button nobody reads.
	 */
	void copyOne(String routineId)
	{
		if (storage == null)
		{
			return;
		}

		final Routine routine = controller.get(routineId);
		if (routine == null)
		{
			return;
		}

		final String problem = ClipboardText.write(storage.exportOne(routine, controller.getLibrary()));
		setShareStatus(problem == null ? PanelMessages.copiedOne(routine.getName()) : problem, problem != null);
	}

	/**
	 * Adds the clocks on the clipboard. Additive and every clock gets a fresh
	 * id, so nothing here can lose anything, which is why the confirm is light
	 * and the reporting afterwards is not.
	 */
	private void pasteIn()
	{
		if (storage == null)
		{
			return;
		}

		final ClipboardText.Reading reading = ClipboardText.read();
		if (reading.getProblem() != null)
		{
			setShareStatus(reading.getProblem(), true);
			return;
		}

		final ClockworkDocument.Imported imported = storage.readImport(reading.getText(), controller.getLibrary());
		if (!imported.isOk())
		{
			refuse("Import clocks", imported.getProblems());
			return;
		}

		final int count = imported.getAdded().size();
		final List<DocumentProblem> problems = imported.getProblems();
		final PanelMessages.Confirm confirm = PanelMessages.importConfirm(count, problems);
		if (!confirm.isNeeded())
		{
			setShareStatus(PanelMessages.summariseImport(count, imported.getNotes(), problems), false);
			return;
		}

		final int answer = JOptionPane.showConfirmDialog(this, confirm.getMessage(), confirm.getTitle(),
			JOptionPane.OK_CANCEL_OPTION, JOptionPane.QUESTION_MESSAGE);
		if (answer != JOptionPane.OK_OPTION)
		{
			setShareStatus(PanelMessages.NOTHING_IMPORTED, false);
			return;
		}

		controller.addAll(imported.getAdded(), imported.getLibrary());
		setShareStatus(PanelMessages.summariseImport(count, imported.getNotes(), problems), false);
	}

	private void editAsText()
	{
		if (storage == null)
		{
			return;
		}

		DocumentDialog.show(this, diagnostics,
			storage.exportAll(controller.getRoutines(), controller.getLibrary()), this::applyEdited);
	}

	/**
	 * Reads what is in the editor, asks about anything it would remove, and
	 * only then changes anything.
	 *
	 * <p>The order is the point. Reading is a plan rather than an act, so a
	 * document that will not read never gets as far as the clocks, and a
	 * document that would remove something never gets past the user. There is
	 * no path through here that applies half of a document.
	 */
	private DocumentDialog.Outcome applyEdited(Component parent, String json)
	{
		if (storage == null)
		{
			return DocumentDialog.Outcome.problem(PanelMessages.APPLY_FAILED);
		}

		final ClockworkDocument.Applied applied =
			storage.readEdited(json, controller.getRoutines(), controller.getLibrary());
		if (!applied.isOk())
		{
			// The line number, where there is one, is what lets the box put the
			// caret on the character that is wrong rather than leaving the user
			// to count down the page.
			return DocumentDialog.Outcome.problem(PanelMessages.refusal(applied.getProblems()),
				DocumentProblem.firstLine(applied.getProblems()));
		}

		final PanelMessages.Confirm confirm = PanelMessages.editConfirm(applied.getRemoved(),
			applied.getAdded(), applied.getNotes(), applied.getProblems(), applied.getRoutines().size());
		if (confirm.isNeeded())
		{
			final int answer = JOptionPane.showConfirmDialog(parent == null ? this : parent,
				confirm.getMessage(), confirm.getTitle(),
				JOptionPane.OK_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE);
			if (answer != JOptionPane.OK_OPTION)
			{
				return DocumentDialog.Outcome.cancelled();
			}
		}

		controller.load(applied.getRoutines(), applied.getLibrary());
		controller.ensureQuick();

		setShareStatus(PanelMessages.summariseEdit(controller.getRoutines().size(),
			applied.getAdded().size(), applied.getRemoved().size(), applied.getNotes(),
			applied.getProblems()), false);
		return DocumentDialog.Outcome.applied();
	}

	// Custom triggers

	/**
	 * Redraws the library rows.
	 *
	 * <p>Each entry reads as its name, the click it waits for, and the two
	 * things that can be done to it. Kept down here with the other footer
	 * sections rather than up with the clocks, because it is a list of settings
	 * rather than a list of things that run, and because one of its buttons
	 * destroys something.
	 */
	private void rebuildTriggers()
	{
		triggerList.removeAll();

		final List<SavedTrigger> entries = controller.getLibrary().all();
		if (entries.isEmpty())
		{
			triggerList.add(explanation("<html>None yet. Add one here, or pick Custom "
				+ "in a clock's start or stop dropdown.</html>"));
		}
		else
		{
			for (SavedTrigger entry : entries)
			{
				triggerList.add(triggerRow(entry));
			}
		}

		triggerList.revalidate();
		triggerList.repaint();
	}

	private JPanel triggerRow(SavedTrigger entry)
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
		row.setBackground(getBackground());
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setBorder(BorderFactory.createEmptyBorder(4, 0, 4, 0));

		JLabel name = styleSmall(new JLabel("<html>" + PanelMessages.escapeHtml(entry.getName()) + "</html>"),
			Color.WHITE);

		JLabel what = explanation("<html>" + PanelMessages.escapeHtml(entry.describe()) + "</html>");
		what.setToolTipText(entry.describe());

		JButton edit = button("Edit",
			"Change the name or the click. Every clock waiting for this one follows the change.",
			"panel.editTrigger", () -> SavedTriggerDialog.showEdit(this, controller, entry));

		JButton delete = button("Delete",
			"Remove this trigger. A trigger a clock is still waiting for cannot be removed.",
			"panel.deleteTrigger", () -> confirmDeleteTrigger(entry));

		JPanel buttons = new JPanel(new GridLayout(1, 0, 2, 0));
		buttons.setBackground(getBackground());
		buttons.setAlignmentX(Component.LEFT_ALIGNMENT);
		buttons.add(edit);
		buttons.add(delete);

		row.add(name);
		row.add(what);
		row.add(buttons);
		return row;
	}

	/**
	 * Deleting a trigger a clock still points at is refused rather than allowed
	 * and tidied up afterwards.
	 *
	 * <p>Detaching the clocks silently would change what they do without being
	 * asked, and leaving the references behind would leave clocks pointing at
	 * nothing. So the clocks are named and the user decides. Naming them is the
	 * whole value of the message, since an id would tell them nothing.
	 */
	private void confirmDeleteTrigger(SavedTrigger entry)
	{
		final List<String> users = TriggerLibrary.usedBy(controller.getRoutines(), entry.getName());
		if (!users.isEmpty())
		{
			Confirms.warn(this, "Clockwork",
				"<b>" + PanelMessages.escapeHtml(entry.getName()) + " is still in use.</b>"
					+ "<br><br>These clocks start or stop on it, "
					+ PanelMessages.escapeHtml(String.join(", ", users)) + "."
					+ "<br><br>Point them at something else first, then delete it.");
			return;
		}

		final boolean go = Confirms.ask(this, "Delete a custom trigger",
			"<b>Delete " + PanelMessages.escapeHtml(entry.getName()) + ".</b>"
				+ "<br><br>It waits for " + PanelMessages.escapeHtml(entry.describe()) + "."
				+ "<br><br>No clock is waiting for it, so nothing else changes.");

		if (!go)
		{
			return;
		}

		controller.editLibrary(library -> library.remove(entry.getName()));
	}

	/**
	 * A footer section heading.
	 *
	 * <p>Every section but the first carries a gap above it. The first needs
	 * no gap, because the footer's own border already puts one between it and
	 * the clock list.
	 */
	private static JLabel heading(String text, boolean spaced)
	{
		JLabel heading = new JLabel(text);
		heading.setFont(FontManager.getRunescapeBoldFont());
		heading.setForeground(Color.WHITE);
		heading.setAlignmentX(Component.LEFT_ALIGNMENT);
		if (spaced)
		{
			heading.setBorder(BorderFactory.createEmptyBorder(8, 0, 0, 0));
		}
		return heading;
	}

	/**
	 * The line or two under a heading saying what the section is for. The text
	 * arrives already wrapped in html, which is what makes it wrap to the
	 * width of the sidebar rather than run off the side of it.
	 */
	private static JLabel explanation(String html)
	{
		return styleSmall(new JLabel(html), ColorScheme.LIGHT_GRAY_COLOR);
	}

	/**
	 * The shape every small footer label has. Applied to the labels held as
	 * fields as well as to the ones made here, so a path, a notice, and an
	 * explanation all sit on the same left edge.
	 */
	private static JLabel styleSmall(JLabel label, Color colour)
	{
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(colour);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/**
	 * The stack of buttons a footer section ends with, one to a row, two
	 * pixels apart.
	 */
	private JPanel buttonColumn(JButton... buttons)
	{
		JPanel column = new JPanel(new GridLayout(0, 1, 0, 2));
		column.setBackground(getBackground());
		column.setAlignmentX(Component.LEFT_ALIGNMENT);
		for (JButton button : buttons)
		{
			column.add(button);
		}
		return column;
	}

	/**
	 * A button whose press runs inside the diagnostics guard, which is every
	 * button in the panel. The guard key names the press in the log, so a
	 * failure says which button caused it.
	 */
	private JButton button(String text, String tooltip, String guardKey, Runnable action)
	{
		JButton button = Controls.small(text);
		button.setToolTipText(tooltip);
		button.addActionListener(e -> diagnostics.guard(guardKey, action));
		return button;
	}
}

package com.clockwork.ui;

import java.awt.Component;
import javax.swing.JOptionPane;

/**
 * The box that asks before something is destroyed, the box that says why
 * something was refused, and the box that says what happened anyway.
 *
 * <p>Only the shell moved here. Every question keeps its own wording at the
 * call site, next to the code that acts on the answer, because what a dialog
 * says is part of what the action means. What was worth taking away is the
 * html wrapper, the width, and the reading of the answer, which were being
 * written out by hand at every one of these and are the parts that drift.
 */
final class Confirms
{
	/**
	 * Wide enough for a sentence to read as a sentence. The dialogs are not
	 * resizable, so left to itself a paragraph goes out as one long line.
	 */
	private static final String OPEN = "<html><body style='width:280px'>";
	private static final String CLOSE = "</body></html>";

	private Confirms()
	{
	}

	/**
	 * Asks before doing something that cannot be undone.
	 *
	 * @param body html, with anything the user typed already escaped
	 * @return true when the user said to go ahead
	 */
	static boolean ask(Component parent, String title, String body)
	{
		return JOptionPane.showConfirmDialog(parent, OPEN + body + CLOSE, title,
			JOptionPane.OK_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE) == JOptionPane.OK_OPTION;
	}

	/**
	 * Says why something was refused. There is nothing to decide, so there is
	 * no answer to give back.
	 *
	 * @param body html, with anything the user typed already escaped
	 */
	static void warn(Component parent, String title, String body)
	{
		JOptionPane.showMessageDialog(parent, OPEN + body + CLOSE, title, JOptionPane.WARNING_MESSAGE);
	}

	/**
	 * Says what happened, when nothing went wrong and nothing was refused. The
	 * plainer icon matters, because a warning triangle over a piece of good
	 * news reads as a problem the user has to go and look for.
	 *
	 * @param body html, with anything the user typed already escaped
	 */
	static void note(Component parent, String title, String body)
	{
		JOptionPane.showMessageDialog(parent, OPEN + body + CLOSE, title, JOptionPane.INFORMATION_MESSAGE);
	}
}

package com.clockwork.ui;

import java.awt.Component;
import java.awt.Dimension;
import java.awt.Insets;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The small Swing pieces the panel and the dialogs are built out of.
 *
 * <p>Called Controls rather than Widgets because a widget in a RuneLite plugin
 * is a game interface component, and one word meaning two things inside one
 * codebase costs a reader something every time they meet it.
 *
 * <p>Nothing here knows what a clock is. It is the shape of a button and the
 * shape of a form row, in one place. The button was written out three times
 * and the row twice before this, and a change to either meant finding every
 * copy first.
 */
final class Controls
{
	private Controls()
	{
	}

	/**
	 * A button in the small font with no focus ring, which is what every
	 * button in this plugin is.
	 */
	static JButton small(String text)
	{
		JButton button = new JButton(text);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setFocusPainted(false);
		return button;
	}

	/**
	 * The one button that is not small. Making a clock is the thing somebody
	 * opens this panel to do the first time, and it sat in the same grey as
	 * every other control, so it read as one option among several rather than
	 * as the way in.
	 *
	 * <p>Twenty four point, which is the size the in-game timer is drawn at by
	 * default, so the two pieces of oversized text in the plugin agree with
	 * each other rather than each having been picked on its own. The panel is
	 * around two hundred pixels wide, which is what sets the ceiling.
	 *
	 * <p>The colour is the one the Quick clock already wears, so the two things
	 * that are always on screen look like they belong together.
	 */
	static JButton primary(String text)
	{
		JButton button = new JButton(text);
		button.setFont(FontManager.getRunescapeBoldFont().deriveFont(24f));
		button.setForeground(ColorScheme.BRAND_ORANGE);
		button.setFocusPainted(false);
		button.setMargin(new Insets(8, 10, 8, 10));
		return button;
	}

	/**
	 * The same button with its padding set, for rows that put several of them
	 * side by side and need the labels to still fit.
	 */
	static JButton small(String text, Insets margin)
	{
		JButton button = small(text);
		button.setMargin(margin);
		return button;
	}

	/**
	 * Adds one row to a form.
	 *
	 * <p>A vertical box is used rather than a grid, because the pickers are
	 * taller than a text field and a grid would stretch every other row to
	 * match them. Capping the height here is what stops the box doing the
	 * same thing in the other direction.
	 */
	static void row(JPanel form, JComponent component)
	{
		component.setAlignmentX(Component.LEFT_ALIGNMENT);
		component.setMaximumSize(new Dimension(Integer.MAX_VALUE, component.getPreferredSize().height));
		form.add(component);
	}
}

package com.clockwork.ui;

import com.clockwork.diag.Diagnostics;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.Window;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JDialog;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.text.BadLocationException;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The whole clock list as text, in a box big enough to read it in.
 *
 * <p>A dialog rather than something inline in the side panel, because the side
 * panel is about 225 pixels wide and a JSON document of several clocks in a
 * column that narrow is unusable. It is resizable for the same reason.
 *
 * <p>The dialog knows nothing about clocks. It hands the text to an
 * {@link Applier} and does what the answer tells it to, which keeps the reading,
 * the confirming, and the applying in the panel where the controller is, and
 * leaves this class as a box with four buttons.
 *
 * <h2>The rule this class exists to keep</h2>
 *
 * <p>A failed apply never closes the dialog and never loses what was typed. The
 * applier validates before it changes anything, so an answer of "here is what is
 * wrong" leaves the text exactly where it was, with the problem underneath it
 * and the caret still in the box.
 */
@Slf4j
class DocumentDialog extends JDialog
{
	/**
	 * Roomy enough for several clocks without scrolling sideways, and small
	 * enough to open on a modest screen.
	 */
	private static final Dimension DEFAULT_SIZE = new Dimension(620, 520);

	private static final Dimension SMALLEST = new Dimension(420, 320);

	private static final Font MONO = new Font(Font.MONOSPACED, Font.PLAIN, 12);

	private final Diagnostics diagnostics;
	private final Applier applier;

	private final JTextArea area = new JTextArea();
	private final JTextArea message = new JTextArea();

	/**
	 * The text as it was last put in the box by the plugin, so the box can tell
	 * whether there is typing in it worth asking about before it is replaced.
	 */
	private String lastLoaded;

	private DocumentDialog(Window owner, Diagnostics diagnostics, String text, Applier applier)
	{
		super(owner, "Clockwork, your clocks as text", ModalityType.APPLICATION_MODAL);

		this.diagnostics = diagnostics == null ? Diagnostics.none() : diagnostics;
		this.applier = applier;

		final JPanel root = new JPanel(new BorderLayout(0, 6));
		root.setBackground(ColorScheme.DARK_GRAY_COLOR);
		root.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		root.add(note("Your clocks as a document. Change it and press Apply, or paste somebody "
			+ "else's in first. Clocks are matched to yours by name, so renaming one in here loses "
			+ "that clock's runs. Rename from the clock's ... menu instead."), BorderLayout.NORTH);

		area.setFont(MONO);
		area.setTabSize(2);
		area.setLineWrap(false);
		area.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		area.setForeground(Color.WHITE);
		area.setCaretColor(Color.WHITE);
		area.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));

		final JScrollPane scroll = new JScrollPane(area,
			ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_AS_NEEDED);
		scroll.setBorder(BorderFactory.createLineBorder(ColorScheme.DARKER_GRAY_COLOR));
		root.add(scroll, BorderLayout.CENTER);

		final JPanel bottom = new JPanel();
		bottom.setLayout(new BoxLayout(bottom, BoxLayout.Y_AXIS));
		bottom.setBackground(root.getBackground());

		message.setFont(FontManager.getRunescapeSmallFont());
		message.setEditable(false);
		message.setLineWrap(true);
		message.setWrapStyleWord(true);
		message.setOpaque(false);
		message.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		message.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		message.setRows(3);
		bottom.add(message);
		bottom.add(buttons());

		root.add(bottom, BorderLayout.SOUTH);
		setContentPane(root);

		put(text);
		setSize(DEFAULT_SIZE);
		setMinimumSize(SMALLEST);
		setResizable(true);
	}

	private JPanel buttons()
	{
		final JButton copy = Controls.small("Copy to clipboard");
		copy.setToolTipText("Put what is in the box on the clipboard");
		copy.addActionListener(e -> diagnostics.guard("document.copy", this::onCopy));

		final JButton paste = Controls.small("Paste from clipboard");
		paste.setToolTipText("Replace what is in the box with the clipboard");
		paste.addActionListener(e -> diagnostics.guard("document.paste", this::onPaste));

		final JButton cancel = Controls.small("Cancel");
		cancel.setToolTipText("Shut this and change nothing");
		cancel.addActionListener(e -> diagnostics.guard("document.cancel", this::dispose));

		final JButton apply = Controls.small("Apply");
		apply.setToolTipText("Check the document, then make your clocks match it");
		apply.addActionListener(e -> diagnostics.guard("document.apply", this::onApply));

		final JPanel left = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		left.setBackground(ColorScheme.DARK_GRAY_COLOR);
		left.add(copy);
		left.add(paste);

		final JPanel right = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
		right.setBackground(ColorScheme.DARK_GRAY_COLOR);
		right.add(cancel);
		right.add(apply);

		final JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.add(left, BorderLayout.WEST);
		row.add(right, BorderLayout.EAST);
		return row;
	}

	// The four buttons

	private void onCopy()
	{
		final String problem = ClipboardText.write(area.getText());
		if (problem == null)
		{
			say(PanelMessages.COPIED_FROM_BOX, false);
		}
		else
		{
			say(problem, true);
		}
	}

	private void onPaste()
	{
		final ClipboardText.Reading reading = ClipboardText.read();
		if (reading.getProblem() != null)
		{
			say(reading.getProblem(), true);
			return;
		}

		final PanelMessages.Confirm confirm = PanelMessages.pasteOverwrite(isModified());
		if (confirm.isNeeded() && JOptionPane.showConfirmDialog(this, confirm.getMessage(),
			confirm.getTitle(), JOptionPane.OK_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE)
			!= JOptionPane.OK_OPTION)
		{
			return;
		}

		put(reading.getText());
		say(PanelMessages.PASTED_INTO_BOX, false);
	}

	/**
	 * Hands the text off, and shuts only on an answer that says it was applied.
	 */
	private void onApply()
	{
		if (applier == null)
		{
			return;
		}

		// The guard is what stops a failure part way through from taking the
		// dialog down with it, so the answer is collected out of it rather than
		// returned through it. Still null afterwards means the guard caught
		// something, which is a failure to report rather than a reason to shut.
		final Outcome[] answer = new Outcome[1];
		diagnostics.guard("document.applyDocument", () -> answer[0] = applier.apply(this, area.getText()));

		final Outcome outcome = answer[0];
		if (outcome == null)
		{
			say(PanelMessages.APPLY_FAILED, true);
			return;
		}

		if (outcome.isApplied())
		{
			dispose();
			return;
		}

		if (outcome.getProblem() != null)
		{
			say(outcome.getProblem(), true);
			goTo(outcome.getLine());
		}
	}

	/**
	 * Puts the caret on a line of the text and selects it, so a problem that
	 * knows where it is points at itself.
	 *
	 * <p>Only a syntax error knows a line, since by the time anything is being
	 * bound the reader is walking a tree and has forgotten the text it came
	 * from. That is the one kind of problem where somebody genuinely has to
	 * find a character, so it is the one worth scrolling to.
	 *
	 * <p>Nothing here can fail loudly. A line number past the end of the box
	 * means the user has edited the text since, which is their business, and
	 * the message underneath still says where the problem was.
	 *
	 * <p>The box is not asked for focus. Focus is the client window's business
	 * and {@code ClockworkWindowTest} guards the whole main source against
	 * touching it, deliberately widely, so the selection is made visible
	 * instead and the caret lands where it lands.
	 */
	private void goTo(int line)
	{
		if (line <= 0 || line > area.getLineCount())
		{
			return;
		}

		try
		{
			final int start = area.getLineStartOffset(line - 1);
			final int end = area.getLineEndOffset(line - 1);
			area.setCaretPosition(start);
			area.moveCaretPosition(Math.max(end - 1, start));
			area.getCaret().setSelectionVisible(true);
		}
		catch (BadLocationException ex)
		{
			// The box changed under us between reading it and pointing at it,
			// which costs the user a scroll and nothing else.
			log.debug("could not point at line {} of the document box", line, ex);
		}
	}

	// Odds and ends

	private void put(String text)
	{
		lastLoaded = text == null ? "" : text;
		area.setText(lastLoaded);
		area.setCaretPosition(0);
	}

	private boolean isModified()
	{
		return !area.getText().equals(lastLoaded == null ? "" : lastLoaded);
	}

	/**
	 * Puts a line under the box. Nothing in here ever clears the box, which is
	 * the whole point of showing the problem down here rather than in it.
	 */
	private void say(String text, boolean bad)
	{
		message.setForeground(bad ? ColorScheme.PROGRESS_ERROR_COLOR : ColorScheme.LIGHT_GRAY_COLOR);
		message.setText(text == null ? "" : text);
		message.setCaretPosition(0);
	}

	private static JTextArea note(String text)
	{
		final JTextArea note = new JTextArea(text);
		note.setFont(FontManager.getRunescapeSmallFont());
		note.setEditable(false);
		note.setLineWrap(true);
		note.setWrapStyleWord(true);
		note.setOpaque(false);
		note.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		note.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));
		return note;
	}

	/**
	 * Opens the box on the given text.
	 */
	static void show(Component parent, Diagnostics diagnostics, String text, Applier applier)
	{
		final DocumentDialog dialog = new DocumentDialog(
			SwingUtilities.getWindowAncestor(parent), diagnostics, text, applier);
		dialog.setLocationRelativeTo(parent);
		dialog.setVisible(true);
	}

	/**
	 * Whatever knows what a document means. Given the text, it validates,
	 * confirms if there is anything worth confirming, applies if the user
	 * agreed, and says which of those happened.
	 */
	interface Applier
	{
		/**
		 * @param parent the dialog, so a confirm of its own opens in front of
		 * it rather than behind it
		 * @param json what is in the box right now
		 * @return never null
		 */
		Outcome apply(Component parent, String json);
	}

	/**
	 * What came of an apply. Three answers, and only one of them shuts the box.
	 */
	static final class Outcome
	{
		private final boolean applied;
		private final String problem;
		private final int line;

		private Outcome(boolean applied, String problem, int line)
		{
			this.applied = applied;
			this.problem = problem;
			this.line = line;
		}

		/**
		 * It went through. The dialog shuts.
		 */
		static Outcome applied()
		{
			return new Outcome(true, null, 0);
		}

		/**
		 * The document was refused, with this to show. The dialog stays open
		 * and the text stays put.
		 */
		static Outcome problem(String problem)
		{
			return new Outcome(false, problem, 0);
		}

		/**
		 * The same, and this one knows which line of the text to point at.
		 */
		static Outcome problem(String problem, int line)
		{
			return new Outcome(false, problem, line);
		}

		/**
		 * The user was asked and said no. The dialog stays open with nothing
		 * new to say, because they already know what they just cancelled.
		 */
		static Outcome cancelled()
		{
			return new Outcome(false, null, 0);
		}

		boolean isApplied()
		{
			return applied;
		}

		String getProblem()
		{
			return problem;
		}

		/**
		 * The line of the text worth putting the caret on, counting from one,
		 * or zero when the problem is not somewhere in particular.
		 */
		int getLine()
		{
			return line;
		}
	}
}

package com.clockwork.ui;

import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JCheckBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Hours, minutes, and seconds as three digit pickers.
 *
 * <p>It replaces a text box that had to be parsed. A spinner cannot hold 1:90
 * or the word soon, so the only validation left is whether the total makes
 * sense for what it is being used for, which is the caller's business.
 *
 * <p>Given a label it grows a tick box that turns the whole thing off, for a
 * duration that is genuinely optional. An unticked picker reads as null rather
 * than as zero, because zero is a length of time and "never" is not.
 */
class DurationPicker extends JPanel
{
	private static final int SPINNER_MIN_WIDTH = 52;
	private static final int ROW_MAX_WIDTH = 220;
	private static final int SPINNER_HEIGHT = 22;

	private final JSpinner hours = spinner(99);
	private final JSpinner minutes = spinner(59);
	private final JSpinner seconds = spinner(59);

	/**
	 * Null when the duration is not optional and the spinners are always live.
	 */
	private final JCheckBox enable;

	/**
	 * @param optionalLabel text of the tick box that turns the picker on, or
	 * null for a duration that is always set
	 */
	DurationPicker(String optionalLabel)
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);

		// GridBag rather than FlowLayout. The sidebar is about 210px of usable
		// width and the popup is wider, so a fixed spinner width either clips
		// the digits in one place or wastes space in the other. Letting the
		// three spinners share whatever width there is fits both places.
		final JPanel row = new JPanel(new GridBagLayout());
		row.setOpaque(false);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(ROW_MAX_WIDTH, SPINNER_HEIGHT + 4));

		final GridBagConstraints field = new GridBagConstraints();
		field.fill = GridBagConstraints.HORIZONTAL;
		field.weightx = 1;
		field.gridy = 0;

		final GridBagConstraints label = new GridBagConstraints();
		label.weightx = 0;
		label.gridy = 0;
		label.insets = new Insets(0, 2, 0, 6);

		row.add(hours, field);
		row.add(unit("h"), label);
		row.add(minutes, field);
		row.add(unit("m"), label);
		row.add(seconds, field);
		row.add(unit("s"), label);

		if (optionalLabel == null)
		{
			enable = null;
		}
		else
		{
			enable = new JCheckBox(optionalLabel);
			enable.setFont(FontManager.getRunescapeSmallFont());
			enable.setOpaque(false);
			enable.setAlignmentX(Component.LEFT_ALIGNMENT);
			enable.addItemListener(e -> applyEnabled());
			add(enable);
		}

		add(row);
		applyEnabled();
	}

	/**
	 * @return the duration in millis, or null when the picker is optional and
	 * switched off
	 */
	Long getMillis()
	{
		if (enable != null && !enable.isSelected())
		{
			return null;
		}
		return value(hours) * 3_600_000L + value(minutes) * 60_000L + value(seconds) * 1_000L;
	}

	/**
	 * Fills the pickers in. Null switches an optional picker off, and anything
	 * past the top of the range is clamped rather than refused, since a value
	 * that got in some other way is not the user's mistake to fix.
	 */
	void setMillis(Long millis)
	{
		if (enable != null)
		{
			enable.setSelected(millis != null);
		}

		long total = millis == null ? 0 : Math.max(0, millis) / 1000L;
		long h = Math.min(99, total / 3600L);
		long m = (total % 3600L) / 60L;
		long s = total % 60L;

		hours.setValue((int) h);
		minutes.setValue((int) m);
		seconds.setValue((int) s);
		applyEnabled();
	}

	private void applyEnabled()
	{
		final boolean on = enable == null || enable.isSelected();
		hours.setEnabled(on);
		minutes.setEnabled(on);
		seconds.setEnabled(on);
	}

	private static int value(JSpinner spinner)
	{
		final Object value = spinner.getValue();
		return value instanceof Number ? ((Number) value).intValue() : 0;
	}

	private static JSpinner spinner(int max)
	{
		final JSpinner spinner = new JSpinner(new SpinnerNumberModel(0, 0, max, 1));
		final JSpinner.NumberEditor editor = new JSpinner.NumberEditor(spinner, "00");
		editor.getTextField().setColumns(2);
		spinner.setEditor(editor);

		// Pin the height only. The width comes from the GridBag share, with a
		// floor that still shows two digits plus the stepper arrows.
		spinner.setPreferredSize(new Dimension(SPINNER_MIN_WIDTH, SPINNER_HEIGHT));
		spinner.setMinimumSize(new Dimension(SPINNER_MIN_WIDTH, SPINNER_HEIGHT));
		spinner.setMaximumSize(new Dimension(Integer.MAX_VALUE, SPINNER_HEIGHT));
		return spinner;
	}

	private static JComponent unit(String text)
	{
		final JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 2));
		return label;
	}
}

package com.clockwork.ui;

import com.clockwork.DocumentProblem;
import java.util.ArrayList;
import java.util.List;

/**
 * Everything the panel says back to the user, every decision about whether to
 * stop and ask first, and the wording of both.
 *
 * <p>Plain Java on purpose. There is no Swing in here and there is no state, so
 * the wording and the decisions can be tested, which the widgets that show them
 * cannot be. A panel that builds its own sentences inline is a panel whose
 * sentences nobody ever checks.
 *
 * <p>Names come out of a box the user typed into, or out of a document somebody
 * else wrote, and they are shown inside html, so anything in a name that looks
 * like a tag is made to stop looking like one on the way in.
 */
public final class PanelMessages
{
	/**
	 * The clipboard held nothing, or held something that is not text. Not a
	 * failure, just an empty pocket, so it is worded as one.
	 */
	public static final String NOTHING_TO_PASTE =
		"There is nothing to paste. Copy a Clockwork document first, then try again.";

	/**
	 * The clipboard itself refused. Usually another program holding it for a
	 * moment, which is worth saying because the fix is to try again.
	 */
	public static final String CLIPBOARD_UNREADABLE =
		"The clipboard could not be read. Another program may be holding it, so try again in a moment.";

	public static final String CLIPBOARD_UNWRITABLE =
		"The clipboard could not be written to. Another program may be holding it, so try again in a moment.";

	public static final String NOTHING_TO_COPY =
		"There are no clocks to copy.";

	public static final String NOTHING_IMPORTED =
		"Nothing was imported. Your clocks are as they were.";

	/**
	 * Shown when applying threw rather than returned. The text stays in the box
	 * either way, which is the part the user cares about.
	 */
	public static final String APPLY_FAILED =
		"Something went wrong applying that. Your text is still here, and the client log has the detail.";

	/**
	 * The opening line of a refusal. It is followed by what is wrong and where,
	 * every time, because on its own it tells somebody who is editing by hand
	 * nothing they can act on.
	 */
	public static final String REFUSED = "That document could not be read.";

	public static final String COPIED_FROM_BOX =
		"Copied to the clipboard.";

	public static final String PASTED_INTO_BOX =
		"Pasted from the clipboard. Nothing happens to your clocks until you press Apply.";

	/**
	 * How many problems are listed before the list says how many more there
	 * are.
	 *
	 * <p>There is a cap because a document pasted from the wrong place can have
	 * a problem on every line of it, and the box under the editor is three rows
	 * tall. The count above the list is never capped, so nothing is hidden,
	 * only unlisted.
	 */
	private static final int SHOWN = 6;

	private PanelMessages()
	{
	}

	// Counting

	/**
	 * A count of clocks with the right noun on it, because "1 clocks" reads as
	 * a bug in the plugin rather than as a number.
	 */
	public static String clocks(int count)
	{
		return count == 1 ? "1 clock" : count + " clocks";
	}

	/**
	 * A count of problems with the right noun on it.
	 */
	public static String problems(int count)
	{
		return count == 1 ? "1 problem" : count + " problems";
	}

	// What is wrong with a document

	/**
	 * The headline over a list of problems, which is the answer to the only
	 * question the user actually has, which is how much of their document is
	 * going to arrive.
	 *
	 * <p>Skipped clocks are counted rather than inferred from the wording,
	 * because a clock that will not arrive and a field that is spelled wrong
	 * are not the same news and should not be added together.
	 */
	public static String importHeadline(int added, List<DocumentProblem> problems)
	{
		return headline(added <= 0
			? "No clocks will be added."
			: "Add " + clocks(added) + " from the clipboard.", problems);
	}

	/**
	 * The same, for the editor, where the count is the list as it would stand
	 * rather than the clocks arriving.
	 */
	public static String editHeadline(int total, List<DocumentProblem> problems)
	{
		return headline(clocks(Math.max(total, 0)) + " will be applied.", problems);
	}

	private static String headline(String opening, List<DocumentProblem> problems)
	{
		final int found = count(problems);
		if (found == 0)
		{
			return opening;
		}

		final int skipped = DocumentProblem.skippedCount(problems);
		if (skipped <= 0)
		{
			return opening + " " + problems(found) + (found == 1 ? " was found." : " were found.");
		}

		return opening + " " + skipped + (skipped == 1 ? " was skipped." : " were skipped.");
	}

	/**
	 * Every problem, one to a line, in plain text, for the box that shows plain
	 * text.
	 *
	 * <p>Capped, because the list under the editor is three rows tall and a
	 * document pasted from the wrong place can have a problem on every line of
	 * it. The count in the headline is never capped, so the user still knows
	 * how many there are.
	 */
	public static String problemLines(List<DocumentProblem> problems)
	{
		final List<DocumentProblem> shown = listed(problems);
		final StringBuilder text = new StringBuilder();

		for (int index = 0; index < shown.size() && index < SHOWN; index++)
		{
			if (text.length() > 0)
			{
				text.append('\n');
			}
			text.append(shown.get(index).describe());
		}

		if (shown.size() > SHOWN)
		{
			text.append("\nand ").append(shown.size() - SHOWN).append(" more.");
		}
		return text.toString();
	}

	/**
	 * The same list for a dialog, which is html, so the names out of the
	 * document are escaped on the way in.
	 */
	public static String problemHtml(List<DocumentProblem> problems)
	{
		final StringBuilder html = new StringBuilder();
		for (String line : problemLines(problems).split("\n"))
		{
			if (line.isEmpty())
			{
				continue;
			}

			if (html.length() > 0)
			{
				html.append("<br>");
			}
			html.append(escapeHtml(line));
		}
		return html.toString();
	}

	/**
	 * A refused document, said in full, as plain text.
	 *
	 * <p>A single problem with nowhere to point at is already a whole sentence
	 * about the whole document, so it is left to speak for itself. Anything
	 * else gets a line saying what happened and then the list, because a list
	 * of locations with no sentence over it reads as a wall of numbers.
	 */
	public static String refusal(List<DocumentProblem> problems)
	{
		final List<DocumentProblem> found = listed(problems);
		if (found.isEmpty())
		{
			return REFUSED;
		}

		if (found.size() == 1 && found.get(0).location().isEmpty())
		{
			return found.get(0).getDetail();
		}

		return refusedCount(found) + "\n\n" + problemLines(found);
	}

	/**
	 * A refused document as html, for a dialog.
	 */
	public static String refusalHtml(List<DocumentProblem> problems)
	{
		final List<DocumentProblem> found = listed(problems);
		if (found.isEmpty())
		{
			return open() + "<b>" + REFUSED + "</b>" + close();
		}

		if (found.size() == 1 && found.get(0).location().isEmpty())
		{
			return open() + "<b>" + escapeHtml(found.get(0).getDetail()) + "</b>" + close();
		}

		return open() + "<b>" + escapeHtml(refusedCount(found)) + "</b>"
			+ "<br><br>" + problemHtml(found) + close();
	}

	/**
	 * A refused document in one line, for the side panel, which has room for
	 * one line. The detail is in the dialog that opens beside it.
	 */
	public static String refusalLine(List<DocumentProblem> problems)
	{
		final List<DocumentProblem> found = listed(problems);
		if (found.isEmpty())
		{
			return REFUSED;
		}

		return found.size() == 1 ? found.get(0).describe() : refusedCount(found);
	}

	private static String refusedCount(List<DocumentProblem> found)
	{
		return REFUSED + " " + problems(found.size())
			+ (found.size() == 1 ? " was found." : " were found.");
	}

	// Copying out

	public static String copiedAll(int count)
	{
		return count <= 0 ? NOTHING_TO_COPY : clocks(count) + " copied to the clipboard.";
	}

	public static String copiedOne(String name)
	{
		final String clean = name == null ? "" : name.trim();
		return clean.isEmpty()
			? "That clock is copied to the clipboard."
			: clean + " is copied to the clipboard.";
	}

	// Importing

	/**
	 * Whether an import is worth stopping for, and what to say if it is.
	 *
	 * <p>An import adds and mints fresh ids, so nothing the user has can be
	 * lost by it. That makes this a light confirm rather than a warning, and it
	 * exists mostly so a stray press of the button does not silently grow
	 * somebody's clock list.
	 */
	public static Confirm importConfirm(int added)
	{
		return importConfirm(added, null);
	}

	/**
	 * The same question, with what is wrong with the document in front of the
	 * user before they answer it.
	 *
	 * <p>A document with something wrong in it is always worth stopping for,
	 * even when nothing would arrive, because the alternative is a button that
	 * quietly adds three of somebody's five clocks and says so afterwards. This
	 * is the whole reason the reading is a plan rather than an act.
	 */
	public static Confirm importConfirm(int added, List<DocumentProblem> problems)
	{
		final List<DocumentProblem> found = listed(problems);
		if (added <= 0 && found.isEmpty())
		{
			return Confirm.notNeeded();
		}

		final StringBuilder body = new StringBuilder();
		body.append(open());
		body.append("<b>").append(escapeHtml(importHeadline(added, found))).append("</b>");

		if (!found.isEmpty())
		{
			body.append("<br><br>").append(problemHtml(found));
		}

		body.append("<br><br>Nothing you already have is changed. Your clocks keep their names, "
			+ "their settings, and their runs, and the ones arriving come in beside them with no runs of their own.");
		body.append("<br><br>A custom trigger whose name clashes with one of yours arrives under a "
			+ "numbered name, and you are told which.");
		body.append(close());

		return Confirm.needed("Import clocks", body.toString());
	}

	/**
	 * What an import did, said afterwards, because a button that changes the
	 * list and says nothing reads as a button that did not work.
	 */
	public static String summariseImport(int added, List<String> notes)
	{
		return summariseImport(added, notes, null);
	}

	/**
	 * The same line, with a count of what did not arrive on the end of it.
	 */
	public static String summariseImport(int added, List<String> notes, List<DocumentProblem> problems)
	{
		final int skipped = DocumentProblem.skippedCount(listed(problems));
		final StringBuilder text = new StringBuilder();
		text.append(added <= 0 && skipped <= 0
			? "That document has no clocks in it, so nothing was added."
			: clocks(added) + " added.");

		if (skipped > 0)
		{
			text.append(' ').append(skipped).append(skipped == 1 ? " was skipped." : " were skipped.");
		}
		appendNotes(text, notes);
		return text.toString();
	}

	// Applying an edited document

	/**
	 * Whether applying an edited document is worth stopping for, and what to
	 * say if it is.
	 *
	 * <p>Removals are the whole reason this confirm exists. Applying a document
	 * that takes nothing away cannot lose anything, so it goes straight
	 * through, and applying one that does is stopped with the clocks named.
	 *
	 * <p>The rename trap is the reason the additions are named too. Clocks are
	 * matched by name, so a clock renamed in the text reads as one removal and
	 * one addition, and the two lists side by side are what makes that legible
	 * rather than cryptic.
	 */
	public static Confirm editConfirm(List<String> removed, List<String> added, List<String> notes)
	{
		return editConfirm(removed, added, notes, null, 0);
	}

	/**
	 * The same question, with what is wrong with the document in it.
	 *
	 * <p>Problems make this a confirm even when nothing would be removed.
	 * Applying a document that quietly drops a clock is exactly the silence
	 * this feature exists to end, and the box stays open behind the question
	 * with the text still in it either way.
	 *
	 * @param total how many clocks the user would have afterwards, which is
	 * what the headline counts when there is nothing being removed
	 */
	public static Confirm editConfirm(List<String> removed, List<String> added, List<String> notes,
		List<DocumentProblem> problems, int total)
	{
		final List<String> gone = clean(removed);
		final List<String> fresh = clean(added);
		final List<DocumentProblem> found = listed(problems);

		if (gone.isEmpty() && found.isEmpty())
		{
			return Confirm.notNeeded();
		}

		if (gone.isEmpty())
		{
			final StringBuilder said = new StringBuilder(open());
			said.append("<b>").append(escapeHtml(editHeadline(total, found))).append("</b>");
			said.append("<br><br>").append(problemHtml(found));
			said.append("<br><br>Nothing has happened to your clocks yet. Press Cancel to go back to "
				+ "the text and fix these, or OK to apply the document as it reads now.");
			said.append(close());
			return Confirm.needed("Apply the edited document", said.toString());
		}

		final StringBuilder body = new StringBuilder();
		body.append(open());
		body.append("<b>").append(clocks(gone.size())).append(" will be removed.</b>");

		if (!found.isEmpty())
		{
			body.append("<br><br>").append(problemHtml(found));
		}

		body.append("<br><br>").append(escapeHtml(join(gone))).append(".");
		body.append("<br><br>A removed clock takes its run history with it, along with its best time, "
			+ "its average, and where you dragged its timer box. None of that can be got back, because "
			+ "the plugin keeps no copy of it anywhere else.");

		if (!fresh.isEmpty())
		{
			body.append("<br><br>").append(clocks(fresh.size())).append(" will be added, ")
				.append(escapeHtml(join(fresh))).append(".");
			body.append("<br><br>Clocks are matched by name, so a clock you renamed in the text reads "
				+ "as one removal and one addition, and the renamed one would arrive with no history. "
				+ "If that is what happened here, press Cancel, put the old name back, and rename it "
				+ "from that clock's ... menu instead, which keeps everything attached to it.");
		}

		for (String note : clean(notes))
		{
			body.append("<br><br>").append(escapeHtml(note));
		}

		body.append(close());
		return Confirm.needed("Apply the edited document", body.toString());
	}

	/**
	 * What applying an edited document did.
	 */
	public static String summariseEdit(int total, int added, int removed, List<String> notes)
	{
		return summariseEditLine(total, added, removed, notes);
	}

	/**
	 * The same line, with a count of what did not arrive on the end of it.
	 */
	public static String summariseEdit(int total, int added, int removed, List<String> notes,
		List<DocumentProblem> problems)
	{
		final int skipped = DocumentProblem.skippedCount(listed(problems));
		final String said = summariseEditLine(total, added, removed, notes);
		return skipped <= 0
			? said
			: said + " " + skipped + (skipped == 1 ? " was skipped." : " were skipped.");
	}

	private static String summariseEditLine(int total, int added, int removed, List<String> notes)
	{
		final StringBuilder text = new StringBuilder("Applied. ");
		if (added <= 0 && removed <= 0)
		{
			text.append(clocks(total)).append(", nothing added or removed.");
		}
		else
		{
			text.append(clocks(total)).append(" now, ").append(Math.max(added, 0))
				.append(" added and ").append(Math.max(removed, 0)).append(" removed.");
		}
		appendNotes(text, notes);
		return text.toString();
	}

	// The clock editor

	/**
	 * What to say when a clock dialog is cancelled after saving custom
	 * triggers, or null when it saved none and there is nothing to say.
	 *
	 * <p>A custom trigger defined from inside the clock editor goes into the
	 * library as soon as it is defined, which is right, because a trigger is
	 * not part of the clock that happened to be open at the time and other
	 * clocks can point at the same one. It does mean that cancelling the clock
	 * leaves work behind that the user has no reason to expect survived, so
	 * this names what was saved and says where it went rather than letting them
	 * assume it went with the clock.
	 *
	 * @param names the entries defined during that dialog, in the order they
	 * were defined
	 * @return html, with the names already escaped, or null when there is
	 * nothing to say
	 */
	public static String keptCustomTriggers(List<String> names)
	{
		final List<String> kept = clean(names);
		if (kept.isEmpty())
		{
			return null;
		}

		final boolean one = kept.size() == 1;
		return "<b>" + escapeHtml(joinAnd(kept)) + (one ? " was saved." : " were saved.") + "</b>"
			+ "<br><br>Cancelling left the clock alone, and the custom "
			+ (one ? "trigger you defined is kept all the same. It lives" : "triggers you defined are kept all the same. They live")
			+ " under Custom triggers in the side panel, so you can point any clock at "
			+ (one ? "it." : "them.");
	}

	// The editor box

	/**
	 * Whether pasting over the box is worth stopping for. Only when there is
	 * typing in there to lose, because asking about an untouched box is asking
	 * for nothing.
	 */
	public static Confirm pasteOverwrite(boolean modified)
	{
		if (!modified)
		{
			return Confirm.notNeeded();
		}

		final StringBuilder body = new StringBuilder();
		body.append(open());
		body.append("<b>Replace what is in the box with the clipboard.</b>");
		body.append("<br><br>What you have typed is not saved anywhere, so it goes.");
		body.append("<br><br>Your clocks are not touched either way, because nothing in this box "
			+ "reaches them until you press Apply.");
		body.append(close());

		return Confirm.needed("Replace the text in the box", body.toString());
	}

	// Shared bits

	private static void appendNotes(StringBuilder text, List<String> notes)
	{
		for (String note : clean(notes))
		{
			text.append(' ').append(note);
		}
	}

	/**
	 * A problem list with the nulls taken out, so a count of it is a count of
	 * things that will actually be shown. Named apart from {@link #clean}
	 * because two methods taking a list cannot be told apart by the list's
	 * element type.
	 */
	private static List<DocumentProblem> listed(List<DocumentProblem> problems)
	{
		final List<DocumentProblem> kept = new ArrayList<>();
		if (problems == null)
		{
			return kept;
		}

		for (DocumentProblem problem : problems)
		{
			if (problem != null)
			{
				kept.add(problem);
			}
		}
		return kept;
	}

	private static int count(List<DocumentProblem> problems)
	{
		return listed(problems).size();
	}

	/**
	 * A list with the nulls and the blanks taken out, so a count of it is a
	 * count of things worth naming.
	 */
	private static List<String> clean(List<String> values)
	{
		final List<String> kept = new ArrayList<>();
		if (values == null)
		{
			return kept;
		}

		for (String value : values)
		{
			if (value != null && !value.trim().isEmpty())
			{
				kept.add(value.trim());
			}
		}
		return kept;
	}

	private static String join(List<String> values)
	{
		return String.join(", ", values);
	}

	/**
	 * The same list read out as a person would read it, with an "and" before
	 * the last one, because this one lands in the middle of a sentence rather
	 * than on a line of its own.
	 */
	private static String joinAnd(List<String> values)
	{
		final int size = values.size();
		if (size <= 1)
		{
			return join(values);
		}
		return join(values.subList(0, size - 1)) + " and " + values.get(size - 1);
	}

	private static String open()
	{
		return "<html><body style='width:320px'>";
	}

	private static String close()
	{
		return "</body></html>";
	}

	/**
	 * Clock names and trigger names are typed by the user, or by whoever wrote
	 * the document, and every message the panel shows is html, so anything in
	 * one that looks like a tag has to stop looking like one. A menu target
	 * really can carry an angle bracket, since "use X on Y" reads as an arrow.
	 *
	 * <p>The whole panel escapes through this one, dialogs and wrapping labels
	 * alike, because it is the only copy with a test behind it. Null comes back
	 * as an empty string rather than as an exception, since a missing name is a
	 * blank in a sentence and not a reason to lose the dialog.
	 */
	public static String escapeHtml(String text)
	{
		return text == null ? "" : text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/**
	 * A question to put in front of the user, or the decision that there is no
	 * question worth asking.
	 */
	public static final class Confirm
	{
		private final boolean needed;
		private final String title;
		private final String message;

		private Confirm(boolean needed, String title, String message)
		{
			this.needed = needed;
			this.title = title;
			this.message = message;
		}

		private static Confirm notNeeded()
		{
			return new Confirm(false, null, null);
		}

		private static Confirm needed(String title, String message)
		{
			return new Confirm(true, title, message);
		}

		/**
		 * Whether to stop and ask. False means go ahead, not that something
		 * went wrong.
		 */
		public boolean isNeeded()
		{
			return needed;
		}

		/**
		 * The dialog's title bar, or null when there is no dialog.
		 */
		public String getTitle()
		{
			return title;
		}

		/**
		 * The dialog's body as html, or null when there is no dialog.
		 */
		public String getMessage()
		{
			return message;
		}
	}
}

