/**
 * One clock in the side panel.
 *
 * <p>Strictly a view. Every button hands straight to the controller and every
 * number on it is read back out of the controller or derived from history, so
 * there is no second copy of the truth living in the panel.
 *
 * <p>The built in clock draws as a variant of this rather than as a card of
 * its own. It is an ordinary clock with two extra buttons and a duration
 * picker, so a second card class would be two places to fix every future
 * change.
 */
class RoutineCard extends JPanel
{
	private static final DateTimeFormatter WHEN = DateTimeFormatter.ofPattern("d MMM HH:mm");
	private static final Font TIME_FONT = new Font(Font.MONOSPACED, Font.BOLD, 18);
	private static final Color AHEAD = ColorScheme.PROGRESS_COMPLETE_COLOR;
	private static final Color BEHIND = ColorScheme.PROGRESS_ERROR_COLOR;

	/**
	 * The padding on this card's buttons. Named here because every one of them
	 * takes it.
	 */
	private static final Insets CARD_MARGIN = new Insets(2, 4, 2, 4);

	/**
	 * Which of the two lists a history row belongs to. Only ever used as the
	 * front of a key, so the two need to differ and nothing else.
	 */
	private static final String RECENT_SECTION = "recent:";
	private static final String BEST_SECTION = "best:";

	private final RoutineController controller;
	private final ClockworkConfig config;
	private final Diagnostics diagnostics;
	private final String routineId;

	/**
	 * Whether this is the built in clock, which gets the quick start buttons
	 * and loses the rename and delete entries.
	 */
	private final boolean builtIn;

	/**
	 * Told which clock the user clicked, so the panel can keep one card
	 * highlighted and one selected for the hotkeys to fall back on.
	 */
	private final Consumer<String> onSelect;

	/**
	 * The designated hotkey target, owned by the plugin. Read to mark this card
	 * and written when the user picks this clock.
	 */
	private final HotkeyTargetHandle hotkeyTarget;

	/**
	 * Told to put this clock on the clipboard, which the panel does because the
	 * panel is what holds the storage. Null when there is nowhere to copy to,
	 * and the menu entry is then left off rather than shown doing nothing.
	 */
	private final Consumer<String> onCopy;

	private boolean selected;

	/**
	 * Only on the built in clock. Sets what its countdown button counts from.
	 */
	private final DurationPicker quickTarget;

	private final JLabel nameLabel = new JLabel();
	private final JLabel timeLabel = new JLabel();

	/**
	 * The split in progress, on a running clock that takes them, and nothing at
	 * all otherwise.
	 *
	 * <p>The line is given back rather than held open as a blank one, because a
	 * card is small and there are several of them down the panel. A clock that
	 * takes no splits is exactly as tall as it was before this existed.
	 */
	private final JLabel splitLabel = new JLabel();

	private final JLabel deltaLabel = new JLabel();
	private final JLabel statsLabel = new JLabel();

	/**
	 * What starts and stops this clock on its own, shown only when there is
	 * something to say. A clock that starts itself would otherwise look like a
	 * clock somebody else was driving.
	 */
	private final JLabel triggerLabel = new JLabel();

	/**
	 * Says so when the hotkeys act on this clock, and is hidden otherwise.
	 * Without it the keys are a mystery, which is the bug this replaced.
	 */
	private final JLabel hotkeyLabel = new JLabel();

	private final JButton startButton = small("Start");
	private final JButton lapButton = small("Lap");
	private final JButton stopButton = small("Stop");
	private final JButton cancelButton = small("Cancel");
	private final JButton historyButton = small("History");

	private final JPanel historyPanel = new JPanel();

	/**
	 * Runs whose splits are showing, keyed on which section they were opened in
	 * and when the run started, so the expanded set survives older runs falling
	 * off the end of the history.
	 *
	 * <p>The section is part of the key because a run can be listed twice, once
	 * for being recent and once for being one of the best, and clicking one of
	 * those rows should open that row rather than both of them.
	 */
	private final Set<String> expandedRuns = new HashSet<>();
	private boolean historyVisible;

	RoutineCard(RoutineController controller, ClockworkConfig config, Diagnostics diagnostics, String routineId,
		Consumer<String> onSelect, HotkeyTargetHandle hotkeyTarget, Consumer<String> onCopy)
	{
		this.controller = controller;
		this.config = config;
		this.diagnostics = diagnostics == null ? Diagnostics.none() : diagnostics;
		this.routineId = routineId;
		this.onSelect = onSelect;
		this.hotkeyTarget = hotkeyTarget;
		this.onCopy = onCopy;
		this.builtIn = Routine.QUICK_ID.equals(routineId);
		this.quickTarget = builtIn ? new DurationPicker(null) : null;

		setLayout(new BorderLayout(0, 4));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		applyBorder();

		nameLabel.setFont(FontManager.getRunescapeBoldFont());
		nameLabel.setForeground(builtIn ? ColorScheme.BRAND_ORANGE : Color.WHITE);
		if (builtIn)
		{
			nameLabel.setToolTipText("Always here, for something you want to time right now. It cannot be renamed or deleted.");
		}

		// A click anywhere that is not a button selects this clock, which
		// highlights the card so it is obvious which one the eye is on.
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				RoutineCard.this.diagnostics.guard("card.select", () ->
				{
					if (RoutineCard.this.onSelect != null)
