		menuButton.addActionListener(e -> this.diagnostics.guard("card.menu", () -> showMenu(menuButton)));

		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(getBackground());
		header.add(nameLabel, BorderLayout.CENTER);
		header.add(menuButton, BorderLayout.EAST);

		timeLabel.setFont(TIME_FONT);
		timeLabel.setHorizontalAlignment(SwingConstants.CENTER);
		timeLabel.setAlignmentX(Component.CENTER_ALIGNMENT);

		splitLabel.setFont(FontManager.getRunescapeSmallFont());
		splitLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		splitLabel.setHorizontalAlignment(SwingConstants.CENTER);
		splitLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
		splitLabel.setVisible(false);
		splitLabel.setToolTipText("The split this run is on now, and how long it has been going. "
			+ "It is the same split the clock's timer box shows.");

		deltaLabel.setFont(FontManager.getRunescapeSmallFont());
		deltaLabel.setHorizontalAlignment(SwingConstants.CENTER);
		deltaLabel.setAlignmentX(Component.CENTER_ALIGNMENT);

		statsLabel.setFont(FontManager.getRunescapeSmallFont());
		statsLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		statsLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

		triggerLabel.setFont(FontManager.getRunescapeSmallFont());
		triggerLabel.setForeground(ColorScheme.BRAND_ORANGE);
		triggerLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		triggerLabel.setVisible(false);
		triggerLabel.setToolTipText("This clock starts or stops itself. Only this clock, and only on what its own settings name.");

		hotkeyLabel.setText("Hotkeys act on this clock");
		hotkeyLabel.setFont(FontManager.getRunescapeSmallFont());
		hotkeyLabel.setForeground(ColorScheme.BRAND_ORANGE);
		hotkeyLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		hotkeyLabel.setVisible(false);
		hotkeyLabel.setToolTipText("The start, stop, and lap keys act on this clock wherever you are, "
			+ "with the side panel open or shut. Change it from the ... menu here.");

		JPanel buttons = new JPanel(new GridLayout(1, builtIn ? 3 : 4, 2, 0));
		buttons.setBackground(getBackground());
		if (!builtIn)
		{
			buttons.add(startButton);
