		buttons.add(lapButton);
		buttons.add(stopButton);
		buttons.add(cancelButton);
		buttons.setAlignmentX(Component.LEFT_ALIGNMENT);

		startButton.addActionListener(e -> this.diagnostics.guard("card.start", () -> controller.start(routineId)));
		lapButton.addActionListener(e -> this.diagnostics.guard("card.lap", () -> controller.lap(routineId)));
		stopButton.addActionListener(e -> this.diagnostics.guard("card.stop", () -> controller.stop(routineId)));
		cancelButton.addActionListener(e -> this.diagnostics.guard("card.cancel", () -> controller.cancel(routineId)));
		cancelButton.setToolTipText("Throw this run away without recording it");

		historyButton.setAlignmentX(Component.LEFT_ALIGNMENT);
		// The number on the button is how many runs are stored, and the two
		// lists it opens can add up to more than that, because a run that is
		// both recent and one of the best is stored once and listed in both.
		historyButton.setToolTipText("The runs this clock has kept, its newest and its fastest."
			+ " A run that is both is stored once and shown in both lists.");
		historyButton.addActionListener(e -> this.diagnostics.guard("card.history", () ->
		{
			historyVisible = !historyVisible;
			historyPanel.setVisible(historyVisible);
			refreshStatic();
			revalidate();
			repaint();
		}));

		historyPanel.setLayout(new BoxLayout(historyPanel, BoxLayout.Y_AXIS));
		historyPanel.setBackground(getBackground());
		historyPanel.setVisible(false);
		historyPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

		JPanel body = new JPanel();
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(getBackground());
		body.add(timeLabel);
		body.add(splitLabel);
		body.add(deltaLabel);
		body.add(statsLabel);
		body.add(triggerLabel);
		body.add(hotkeyLabel);
		if (builtIn)
		{
			body.add(buildQuickControls());
		}
		body.add(buttons);
		body.add(historyButton);
