	/**
	 * The two one click starts on the built in clock, and the pickers the
	 * countdown one counts from.
	 */
	private JPanel buildQuickControls()
	{
		final Routine routine = controller.get(routineId);
		final long target = routine == null ? 0 : routine.getTargetMillis();
		// Five minutes when nothing has been set yet, so the countdown button
		// does something the first time it is pressed.
		quickTarget.setMillis(target > 0 ? target : 300_000L);
		quickTarget.setAlignmentX(Component.LEFT_ALIGNMENT);
		quickTarget.setToolTipText("What the countdown button counts down from");

		final JButton up = small("Count up");
		up.setToolTipText("Start timing right now, counting up from zero");
		up.addActionListener(e -> diagnostics.guard("card.quickUp", () ->
		{
			controller.update(routineId, r -> r.setMode(Mode.COUNT_UP));
			controller.start(routineId);
		}));

		final JButton down = small("Count down");
		down.setToolTipText("Start a countdown from the time set above");
		down.addActionListener(e -> diagnostics.guard("card.quickDown", () ->
		{
			final Long millis = quickTarget.getMillis();
			if (millis == null || millis <= 0)
			{
				JOptionPane.showMessageDialog(this, "Set a time to count down from first.",
					"Clockwork", JOptionPane.WARNING_MESSAGE);
				return;
			}
			controller.update(routineId, r ->
			{
				r.setMode(Mode.COUNT_DOWN);
				r.setTargetMillis(millis);
			});
			controller.start(routineId);
		}));

		final JPanel actions = new JPanel(new GridLayout(1, 2, 2, 0));
		actions.setBackground(getBackground());
		actions.setAlignmentX(Component.LEFT_ALIGNMENT);
		actions.add(up);
		actions.add(down);

		final JPanel holder = new JPanel();
		holder.setLayout(new BoxLayout(holder, BoxLayout.Y_AXIS));
		holder.setBackground(getBackground());
		holder.setAlignmentX(Component.LEFT_ALIGNMENT);
		holder.add(quickTarget);
		holder.add(actions);
		return holder;
	}

	/**
	 * Selection is drawn as the border rather than as a background, so it reads
	 * as a border on a card rather than as a highlighted row.
	 */
	private void applyBorder()
	{
		final Color line = selected
			? ColorScheme.BRAND_ORANGE
			: (builtIn ? ColorScheme.BRAND_ORANGE_TRANSPARENT : ColorScheme.DARK_GRAY_COLOR);
		final int thickness = selected ? 2 : 1;
		final int pad = selected ? 5 : 6;

		setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createEmptyBorder(0, 0, 8, 0),
			BorderFactory.createCompoundBorder(
				BorderFactory.createLineBorder(line, thickness),
				BorderFactory.createEmptyBorder(pad, pad, pad, pad))));
	}

	void setSelected(boolean value)
	{
		if (selected == value)
		{
			return;
		}
		selected = value;
		applyBorder();
		revalidate();
		repaint();
	}

	/**
	 * For the handful of callers inside this card that are not on the refresh
	 * path and have no format spec to hand.
	 */
	private void refreshStatic()
	{
		refreshStatic(Formats.of(config));
	}

	@Override
	public Dimension getMaximumSize()
	{
		// Without this the vertical box layout stretches one card over the
		// whole panel.
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}

	/**
	 * Redraws everything that only changes when the routine or its history
	 * changes.
	 */
	void refreshStatic(DurationFormat format)
	{
		Routine routine = controller.get(routineId);
		if (routine == null)
		{
			return;
		}

		nameLabel.setText(routine.getName());
		lapButton.setVisible(routine.isLapsEnabled());

		DurationFormat plain = format.withoutSubSecond();
		Run best = RoutineStats.personalBest(routine);
		Long average = RoutineStats.averageOfLast(routine, config.averageWindow());
		Long allTime = RoutineStats.allTimeAverage(routine);
		Run last = RoutineStats.lastCompleted(routine);

		StringBuilder stats = new StringBuilder("<html>");
		stats.append("Best ").append(best == null ? "none yet" : DurationFormatter.format(best.getDurationMillis(), plain));
		stats.append("<br>Average ").append(average == null ? "none yet"
			: DurationFormatter.format(average, plain)
			+ " over " + RoutineStats.completedInLast(routine, config.averageWindow()));
		// The two averages read the same way and say what each is over, because
		// the only thing that distinguishes them is how far back they reach.
		stats.append("<br>All time ").append(allTime == null ? "none yet"
			: DurationFormatter.format(allTime, plain)
			+ " over " + RoutineStats.completedAllTime(routine));
		stats.append("<br>Last ").append(last == null ? "none yet" : DurationFormatter.format(last.getDurationMillis(), plain));
		stats.append("</html>");
		statsLabel.setText(stats.toString());

		String triggers = triggerHint(routine);
		triggerLabel.setText(triggers == null ? " " : triggers);
		triggerLabel.setVisible(triggers != null);

		hotkeyLabel.setVisible(isHotkeyTarget());

		int runs = routine.historyOrEmpty().size();
		historyButton.setText((historyVisible ? "Hide history" : "History") + " (" + runs + ")");
		historyButton.setEnabled(runs > 0);

		if (historyVisible)
		{
			rebuildHistory(routine, plain);
		}
	}

	/**
	 * Redraws the parts that move while a run is going.
	 */
	void refreshLive(long now, DurationFormat format)
	{
		Routine routine = controller.get(routineId);
		if (routine == null)
		{
			return;
		}

		boolean running = controller.isRunning(routineId);
		startButton.setEnabled(!running || routine.isRestartOnStart());
		lapButton.setEnabled(running);
		stopButton.setEnabled(running);
		cancelButton.setEnabled(running);

		if (!running)
		{
			Run last = RoutineStats.lastCompleted(routine);
			timeLabel.setText(DurationFormatter.format(last == null ? 0 : last.getDurationMillis(), format));
			timeLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			showSplit(false, null, 0, format);
			deltaLabel.setText(" ");
			return;
		}

		long elapsed = controller.elapsedMillis(routineId, now);
		Long remaining = controller.remainingMillis(routineId, now);
		boolean countdown = routine.getMode() == Mode.COUNT_DOWN && remaining != null;

		timeLabel.setText(DurationFormatter.format(countdown ? remaining : elapsed, format));
		if (controller.isPaused(routineId))
		{
			timeLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		}
		else if (countdown && remaining < 0)
		{
			timeLabel.setForeground(BEHIND);
		}
		else
		{
			timeLabel.setForeground(Color.WHITE);
		}

		// The clock's own setting wins, and falls back to the plugin wide one
		// when it is left on use global.
		boolean showingDelta = Overridable.resolve(routine.getShowDelta(), config.showPbDelta());

		// Asked for once and read twice. A clock that shows neither the split
		// nor the delta does not ask at all, so a card that has nothing to do
		// with the laps allocates nothing for them.
		boolean showingSplit = routine.isLapsEnabled();
		List<Lap> laps = showingSplit || showingDelta ? controller.currentLaps(routineId) : null;

		showSplit(showingSplit, laps, elapsed, format);

		Long delta = showingDelta ? RoutineStats.liveDelta(routine, elapsed, laps) : null;

		if (delta == null)
		{
			deltaLabel.setText(controller.isPaused(routineId) ? "paused" : " ");
			deltaLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		}
		else
		{
			deltaLabel.setText(DurationFormatter.formatSigned(delta, format) + " vs best");
			deltaLabel.setForeground(delta > 0 ? BEHIND : AHEAD);
		}
	}

	/**
	 * Puts the split in progress on the card, or takes the line back when there
	 * is not one.
	 *
	 * <p>Both halves come out of {@link RoutineStats}, which is where the timer
	 * box reads them too, so the two cannot disagree about which split the run
	 * is on or how long it has been going. That is the same arrangement the
	 * idle card and the idle box already have through
	 * {@link RoutineStats#lastCompleted}.
	 *
	 * <p>The visibility is only touched when it actually changes, because this
	 * runs on the refresh tick for every card on screen and a needless
	 * {@code setVisible} costs the panel a layout.
	 */
	private void showSplit(boolean wanted, List<Lap> laps, long elapsed, DurationFormat format)
	{
		if (wanted)
		{
			splitLabel.setText(RoutineStats.currentLapLabel(laps) + "  "
				+ DurationFormatter.format(RoutineStats.currentLapMillis(laps, elapsed), format));
		}
		else
		{
			// Emptied rather than left holding the last split of the last run,
			// so a hidden line has nothing stale in it. Swing compares the text
			// before it lays anything out again, so setting the same empty
			// string every tick costs nothing.
			splitLabel.setText("");
		}

		if (splitLabel.isVisible() != wanted)
		{
			splitLabel.setVisible(wanted);
		}
	}

	/**
	 * The one, two, or three lines under the stats saying what drives this
	 * clock on its own, or null when nothing does.
	 *
	 * <p>Every phrase comes out of the trigger itself, so there is one place a
	 * trigger is worded and the dropdown and the card cannot drift apart.
	 *
	 * <p>They read in the order they happen, so a clock that starts on a
	 * teleport, splits at the leprechaun, and stops at the bank reads that way
	 * down the card. The lap line is left off a clock with its splits switched
	 * off, because such a clock does not lap on anything however its lap
	 * trigger is set, and a card that said otherwise would be telling the user
	 * something that is not so.
	 */
	private String triggerHint(Routine routine)
	{
		// Resolved through the library, so a clock that waits for a saved
		// trigger reads the name the user gave it, and a clock pointing at one
		// that has since gone reads as nothing, which is what it now does.
		final TriggerLibrary library = controller.getLibrary();
		final Trigger start = library.resolve(routine.getStartTrigger());
		final Trigger lap = library.resolve(routine.getLapTrigger());
		final Trigger stop = library.resolve(routine.getStopTrigger());
		final boolean lapping = routine.isLapsEnabled() && lap.getType() != TriggerType.NONE;
		if (start.getType() == TriggerType.NONE && stop.getType() == TriggerType.NONE && !lapping)
		{
			return null;
		}

		final StringBuilder hint = new StringBuilder("<html>");
		if (start.getType() != TriggerType.NONE)
		{
			hint.append("Starts on ").append(PanelMessages.escapeHtml(library.hint(routine.getStartTrigger())));
		}
		if (lapping)
		{
			if (hint.length() > "<html>".length())
			{
				hint.append("<br>");
			}
			hint.append("Splits on ").append(PanelMessages.escapeHtml(library.hint(routine.getLapTrigger())));
		}
		if (stop.getType() != TriggerType.NONE)
		{
			if (hint.length() > "<html>".length())
			{
				hint.append("<br>");
			}
			hint.append("Stops on ").append(PanelMessages.escapeHtml(library.hint(routine.getStopTrigger())));
		}
		return hint.append("</html>").toString();
	}

	/**
	 * The expanded history, as the two sets a clock actually keeps rather than
	 * as one undifferentiated list.
	 *
	 * <p>Recent and best, each labelled. They are the same two sets the store
	 * keeps, read from {@link RoutineStats}, so a run listed here is a run that
	 * is still there and the list cannot promise something the config has
	 * already let go. A run that is both recent and one of the best appears in
	 * both, because it is true in both, and it is stored once.
	 */
	private void rebuildHistory(Routine routine, DurationFormat format)
	{
		historyPanel.removeAll();
		addSection(RECENT_SECTION, "Recent", RoutineStats.recent(routine), format);
		addSection(BEST_SECTION, "Best", RoutineStats.fastest(routine), format);
	}

	/**
	 * One labelled run of rows, left out entirely when there is nothing in it.
	 *
	 * @param section which list this is, which keys the expanded splits so that
	 * clicking a run in one section does not open it in the other
	 */
	private void addSection(String section, String title, List<Run> runs, DurationFormat format)
	{
		if (runs.isEmpty())
		{
			return;
		}

		JLabel header = new JLabel(title);
		header.setFont(FontManager.getRunescapeSmallFont());
		header.setForeground(ColorScheme.BRAND_ORANGE);
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.setBorder(BorderFactory.createEmptyBorder(6, 0, 2, 0));
		historyPanel.add(header);

		for (Run run : runs)
		{
			final String key = section + run.getStartedAtEpochMillis();

			JPanel row = new JPanel(new BorderLayout());
			row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			row.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));

			JLabel when = new JLabel(WHEN.format(Instant.ofEpochMilli(run.getStartedAtEpochMillis())
				.atZone(ZoneId.systemDefault())));
			when.setFont(FontManager.getRunescapeSmallFont());
			when.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

			JLabel duration = new JLabel(DurationFormatter.format(run.getDurationMillis(), format));
			duration.setFont(FontManager.getRunescapeSmallFont());
			duration.setForeground(run.getStatus() == Status.ABANDONED ? BEHIND : Color.WHITE);
			if (run.getStatus() == Status.ABANDONED)
			{
				duration.setToolTipText("Abandoned, so it is left out of your best and average times");
			}

			row.add(when, BorderLayout.WEST);
			row.add(duration, BorderLayout.EAST);

			if (!run.lapsOrEmpty().isEmpty())
			{
				row.setToolTipText("Click to show splits");
				row.addMouseListener(new MouseAdapter()
				{
					@Override
					public void mouseClicked(MouseEvent e)
					{
						diagnostics.guard("card.splits", () ->
						{
							if (!expandedRuns.remove(key))
							{
								expandedRuns.add(key);
							}
							refreshStatic();
							revalidate();
							repaint();
						});
					}
				});
			}

			historyPanel.add(row);

			if (expandedRuns.contains(key))
			{
				List<Lap> laps = run.lapsOrEmpty();
				for (int l = 0; l < laps.size(); l++)
				{
					Lap lap = laps.get(l);
					String label = lap.getLabel() == null ? "Split " + (l + 1) : lap.getLabel();
					JLabel lapLabel = new JLabel("<html><span style='color:#a0a0a0'>&nbsp;&nbsp;" + label
						+ "</span> " + DurationFormatter.format(lap.getLapMillis(), format)
						+ " <span style='color:#a0a0a0'>at " + DurationFormatter.format(lap.getSplitMillis(), format)
						+ "</span></html>");
					lapLabel.setFont(FontManager.getRunescapeSmallFont());
					historyPanel.add(lapLabel);
				}
			}
		}
	}

	private void showMenu(Component anchor)
	{
		Routine routine = controller.get(routineId);
		if (routine == null)
		{
			return;
		}

		JPopupMenu menu = new JPopupMenu();

		if (!builtIn)
		{
			JMenuItem rename = new JMenuItem("Rename");
			rename.addActionListener(e -> diagnostics.guard("card.rename",
				() -> RoutineEditor.showRename(this, controller, diagnostics, routine)));
			menu.add(rename);
		}

		JMenuItem configure = new JMenuItem("Configure");
		configure.addActionListener(e -> diagnostics.guard("card.configure",
			() -> RoutineEditor.showEdit(this, controller, diagnostics, routine)));
		menu.add(configure);

		if (onCopy != null)
		{
			JMenuItem copy = new JMenuItem("Copy this clock as text");
			copy.setToolTipText("Put this clock on the clipboard, ready to hand to somebody. "
				+ "Its runs and its best time stay here.");
			copy.addActionListener(e -> diagnostics.guard("card.copyOne", () -> onCopy.accept(routineId)));
			menu.add(copy);
		}

		JMenuItem reset = new JMenuItem("Clear this clock's runs");
		reset.addActionListener(e -> diagnostics.guard("card.clearRuns", () ->
		{
			if (Confirms.ask(this, "Clear this clock's runs",
				"<b>Clear the stored runs of " + PanelMessages.escapeHtml(routine.getName()) + ".</b>"
					+ "<br><br>This clock's best time and both its averages go back to nothing, and a run it has "
					+ "in progress right now is thrown away."
					+ "<br><br>Other clocks are not touched. The runs cleared here cannot be got back, "
					+ "because the plugin keeps no copy of them anywhere else."))
			{
				expandedRuns.clear();
				controller.reset(routineId);
			}
		}));
		menu.add(reset);

		final boolean targeted = isHotkeyTarget();
		JMenuItem hotkeys = new JMenuItem(targeted
			? "Stop using hotkeys on this clock"
			: "Use hotkeys on this clock");
		hotkeys.setToolTipText(targeted
			? "Go back to no designated clock, so the keys fall back to whatever is running"
			: "Make the start, stop, and lap keys act on this clock, panel open or shut");
		hotkeys.addActionListener(e -> diagnostics.guard("card.hotkeyTarget", () ->
		{
			if (hotkeyTarget != null)
			{
				hotkeyTarget.setHotkeyTargetId(targeted ? null : routineId);
			}
		}));
		menu.add(hotkeys);

		if (!builtIn)
		{
			JMenuItem delete = new JMenuItem("Delete clock");
			delete.addActionListener(e -> diagnostics.guard("card.delete", () ->
			{
				if (Confirms.ask(this, "Delete clock",
					"<b>Delete the clock " + PanelMessages.escapeHtml(routine.getName()) + ".</b>"
						+ "<br><br>The clock goes, along with its stored runs and its best time."
						+ "<br><br>None of that can be got back, because the plugin keeps no copy of it "
						+ "anywhere else."))
				{
					controller.delete(routineId);
				}
			}));
			menu.add(delete);
		}

		menu.show(anchor, 0, anchor.getHeight());
	}

	/**
	 * Whether the hotkeys are pointed at this clock.
	 */
	private boolean isHotkeyTarget()
	{
		return hotkeyTarget != null && routineId != null
			&& routineId.equals(hotkeyTarget.getHotkeyTargetId());
	}

	/**
	 * The card packs up to four buttons across a 225 pixel sidebar, so they
	 * take a tighter margin than the full width buttons in the footer do.
	 */
	private static JButton small(String text)
	{
		return Controls.small(text, CARD_MARGIN);
	}
}

package com.clockwork.ui;

import com.clockwork.core.AlertOverride;
import com.clockwork.core.ClockMode;
import com.clockwork.core.Mode;
import com.clockwork.core.OverlayOverride;
import com.clockwork.core.Routine;
import com.clockwork.core.RoutineController;
import com.clockwork.core.Toggle;
import com.clockwork.core.Trigger;
import com.clockwork.diag.Diagnostics;
import java.awt.Component;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JTextField;

/**
 * The create and configure dialogs.
 *
 * <p>This class only gathers what the user picked and hands it to the
 * controller. Every change lands through {@link RoutineController#update}, so
 * the panel and the saved state both hear about it through the same path a
 * trigger would use.
 *
 * <p>Automatic start, split, and stop triggers are three more rows in the same
 * form. They are plain settings on a clock, so they are gathered and applied
 * exactly the way every other setting is. The three dropdowns are
 * {@link TriggerPicker}s, which know about the saved trigger library and can
 * define a new entry in it without leaving this dialog.
 *
 * <p>A new entry lands in the library as soon as it is defined, and it stays
 * there when this dialog is cancelled, because a saved trigger belongs to the
 * library rather than to whichever clock was open at the time. Cancelling then
 * says which entries were kept and where they are, so nobody has to guess
 * whether that work went with the clock.
 */
public final class RoutineEditor
{
	private RoutineEditor()
	{
	}

	public static void showCreate(Component parent, RoutineController controller, Diagnostics diagnostics)
	{
		String name = JOptionPane.showInputDialog(parent, "Name this clock", "New clock", JOptionPane.PLAIN_MESSAGE);
		if (name == null || name.trim().isEmpty())
		{
			return;
		}

		Routine created = controller.create(name);
		showEdit(parent, controller, diagnostics, created);
	}

	public static void showRename(Component parent, RoutineController controller, Diagnostics diagnostics,
		Routine routine)
	{
		if (routine.isBuiltIn())
		{
			return;
		}

		String name = JOptionPane.showInputDialog(parent, "Rename clock", routine.getName());
		if (name == null || name.trim().isEmpty())
		{
			return;
		}
		final String trimmed = name.trim();
		orNone(diagnostics).guard("editor.rename", () -> controller.update(routine.getId(), r -> r.setName(trimmed)));
	}

	public static void showEdit(Component parent, RoutineController controller, Diagnostics diagnostics,
		Routine routine)
	{
		final boolean builtIn = routine.isBuiltIn();

		final JTextField nameField = new JTextField(routine.getName());
		nameField.setEnabled(!builtIn);
		if (builtIn)
		{
			nameField.setToolTipText("The built in clock keeps its name, so the hotkeys always have something to fall back to.");
		}

		final JComboBox<Mode> modeField = new JComboBox<>(Mode.values());
		modeField.setSelectedItem(routine.getMode());

		final JComboBox<ClockMode> clockField = new JComboBox<>(ClockMode.values());
		clockField.setSelectedItem(routine.getClock());

		final DurationPicker targetField = new DurationPicker(null);
		targetField.setMillis(routine.getTargetMillis() > 0 ? routine.getTargetMillis() : null);

		final DurationPicker abandonField = new DurationPicker("Abandon a run after");
		abandonField.setMillis(routine.getAbandonAfterMillis());

		final JCheckBox stopAtZeroField = new JCheckBox("Stop the run at zero", routine.isStopAtZero());
		final JCheckBox lapsField = new JCheckBox("Take splits", routine.isLapsEnabled());
		final JCheckBox restartField = new JCheckBox("Start over if started again", routine.isRestartOnStart());

		final TriggerPicker startTriggerPicker =
			new TriggerPicker(controller, diagnostics, routine.getStartTrigger());
		final TriggerPicker lapTriggerPicker =
			new TriggerPicker(controller, diagnostics, routine.getLapTrigger());
		final TriggerPicker stopTriggerPicker =
			new TriggerPicker(controller, diagnostics, routine.getStopTrigger());
		final JComboBox<Object> startTriggerField = startTriggerPicker.getComponent();
		final JComboBox<Object> lapTriggerField = lapTriggerPicker.getComponent();
		final JComboBox<Object> stopTriggerField = stopTriggerPicker.getComponent();

		// The lap trigger is only a setting on a clock that takes splits, so it
		// is shown greyed rather than hidden while they are off. Hiding it
		// would move every row under it the moment the tick box was touched,
		// and greying it says the row exists and what it is waiting for.
		final JLabel lapTriggerLabel = new JLabel("Take a split on this clock when");
		lapsField.addActionListener(e ->
		{
			lapTriggerField.setEnabled(lapsField.isSelected());
			lapTriggerLabel.setEnabled(lapsField.isSelected());
		});
		lapTriggerField.setEnabled(lapsField.isSelected());
		lapTriggerLabel.setEnabled(lapsField.isSelected());

		final JComboBox<OverlayOverride> overlayField = new JComboBox<>(OverlayOverride.values());
		overlayField.setSelectedItem(
			routine.getOverlay() == null ? OverlayOverride.USE_GLOBAL : routine.getOverlay());

		final JComboBox<Toggle> deltaField = new JComboBox<>(Toggle.values());
		deltaField.setSelectedItem(routine.getShowDelta() == null ? Toggle.USE_GLOBAL : routine.getShowDelta());

		final JComboBox<AlertOverride> alertField = new JComboBox<>(AlertOverride.values());
		alertField.setSelectedItem(
			routine.getAlert() == null ? AlertOverride.USE_GLOBAL : routine.getAlert());

		final JComboBox<Toggle> soundField = new JComboBox<>(Toggle.values());
		soundField.setSelectedItem(routine.getSound() == null ? Toggle.USE_GLOBAL : routine.getSound());

		final JComboBox<Toggle> notifyField = new JComboBox<>(Toggle.values());
		notifyField.setSelectedItem(routine.getNotify() == null ? Toggle.USE_GLOBAL : routine.getNotify());

		targetField.setToolTipText("Only used when counting down");
		stopAtZeroField.setToolTipText("Only used when counting down. Off means the clock carries on past zero and shows the overtime in red, which is what you want when the target is a pace to hold. On means the run ends at zero and is recorded just as if you had stopped it yourself.");
		abandonField.setToolTipText("Leave this unticked to never abandon. A run past this length is filed as abandoned and left out of your best and average times.");
		restartField.setToolTipText("Off means a second start while the clock is already running is ignored, which is what you want when the thing that starts a clock happens several times inside it.");
		startTriggerField.setToolTipText("Starts this clock by itself when the chosen thing happens. It only ever acts on this clock, and while the clock is already running it is ignored unless start over is ticked above. Custom defines a new saved trigger of your own, and the saved ones you already have are listed above it.");
		lapTriggerField.setToolTipText("Takes a split on this clock by itself when the chosen thing happens, such as using your herbs on the tool leprechaun at each patch. It needs take splits ticked above, and it does nothing at all while the clock is not running. If one thing is set as both the split and the stop, the stop wins, and the closing split still covers the last stretch.");
		stopTriggerField.setToolTipText("Stops this clock by itself when the chosen thing happens, and does nothing at all while the clock is not running. Pick the same thing for both and one event toggles the clock, starting it when it is idle and stopping it when it is running.");
		overlayField.setToolTipText("When this clock's timer box is on screen in the game window. Always show keeps a box there while the clock is idle, reading its last run. Use global follows the plugin config, anything else wins over it.");
		deltaField.setToolTipText("Whether this clock shows how far ahead or behind its best it is. Use global follows the plugin config.");
		alertField.setToolTipText("What this clock draws when it finishes, or when its countdown reaches zero. Use global follows the plugin config, anything else wins over it, so one clock can flash while the rest stay quiet. Flash the timer needs this clock to have a timer box. The chime and the notification are the two rows below and are read separately, so None here still leaves both of them open to this clock.");
		soundField.setToolTipText("Whether this clock plays the bundled chime when it finishes, or when its countdown reaches zero. Use global follows the plugin config, on and off both win over it, so this clock can chime while the rest are silent or stay silent while the rest chime. It is read separately from the row above, so a clock can draw nothing and still chime. The chime is played directly rather than through the notification system, so it is heard whether or not the client has focus. The volume is plugin wide, and zero is silent everywhere.");
		notifyField.setToolTipText("Whether this clock asks RuneLite to notify when it finishes, or when its countdown reaches zero. Use global follows the tick on Notification in the plugin config, on and off both win over it, so this clock can be announced while the rest are not. It is read separately from the two rows above, so this clock can flash and be notified, or draw nothing and still be notified. RuneLite holds a notification back while the client has focus, so tick Override on Notification in the plugin config and turn Send when focused on inside it if you want one at the moment you are watching the game. How the notification behaves is plugin wide, this row is only whether this clock gets one.");

		final JPanel form = new JPanel();
		form.setLayout(new BoxLayout(form, BoxLayout.Y_AXIS));
		form.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));
		Controls.row(form, new JLabel("Name"));
		Controls.row(form, nameField);
		Controls.row(form, new JLabel("Direction"));
		Controls.row(form, modeField);
		Controls.row(form, new JLabel("Countdown from"));
		Controls.row(form, targetField);
		Controls.row(form, stopAtZeroField);
		Controls.row(form, new JLabel("Time counted"));
		Controls.row(form, clockField);
		Controls.row(form, abandonField);
		Controls.row(form, lapsField);
		Controls.row(form, restartField);
		Controls.row(form, new JLabel("Start this clock when"));
		Controls.row(form, startTriggerField);
		Controls.row(form, lapTriggerLabel);
		Controls.row(form, lapTriggerField);
		Controls.row(form, new JLabel("Stop this clock when"));
		Controls.row(form, stopTriggerField);
		Controls.row(form, new JLabel("Timer box in game"));
		Controls.row(form, overlayField);
		Controls.row(form, new JLabel("Best time delta"));
		Controls.row(form, deltaField);
		Controls.row(form, new JLabel("Alert when it finishes"));
		Controls.row(form, alertField);
		Controls.row(form, new JLabel("Chime when it finishes"));
		Controls.row(form, soundField);
		Controls.row(form, new JLabel("Notify when it finishes"));
		Controls.row(form, notifyField);

		while (true)
		{
			int result = JOptionPane.showConfirmDialog(parent, form, "Configure clock",
				JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
			if (result != JOptionPane.OK_OPTION)
			{
				sayWhatWasKept(parent, startTriggerPicker, lapTriggerPicker, stopTriggerPicker);
				return;
			}

			final String name = nameField.getText().trim();
			if (name.isEmpty())
			{
				JOptionPane.showMessageDialog(parent, "A clock needs a name.", "Clockwork", JOptionPane.WARNING_MESSAGE);
				continue;
			}

			final Mode mode = (Mode) modeField.getSelectedItem();
			final Long target = targetField.getMillis();
			if (mode == Mode.COUNT_DOWN && (target == null || target <= 0))
			{
				JOptionPane.showMessageDialog(parent, "A countdown needs a time to count from, such as 6 minutes.",
					"Clockwork", JOptionPane.WARNING_MESSAGE);
				continue;
			}

			final Long abandon = abandonField.getMillis();
			if (abandon != null && abandon <= 0)
			{
				JOptionPane.showMessageDialog(parent, "Abandon after needs a length of time, or untick it to never abandon.",
					"Clockwork", JOptionPane.WARNING_MESSAGE);
				continue;
			}

			// Nothing to check here any more. A saved trigger was checked when
			// it was defined, in the one place that can check it, so the picker
			// can only hand back something already valid.
			final Trigger startTrigger = startTriggerPicker.getTrigger();
			final Trigger stopTrigger = stopTriggerPicker.getTrigger();

			// Kept whether or not splits are on, so turning them off for an
			// evening and back on again does not cost the user the setting.
			// Nothing acts on it while they are off, which is the dispatch
			// rule's business rather than this dialog's.
			final Trigger lapTrigger = lapTriggerPicker.getTrigger();

			final ClockMode clock = (ClockMode) clockField.getSelectedItem();
			final OverlayOverride overlay = (OverlayOverride) overlayField.getSelectedItem();
			final Toggle delta = (Toggle) deltaField.getSelectedItem();
			final AlertOverride alert = (AlertOverride) alertField.getSelectedItem();
			final Toggle sound = (Toggle) soundField.getSelectedItem();
			final Toggle notify = (Toggle) notifyField.getSelectedItem();
			orNone(diagnostics).guard("editor.apply", () -> controller.update(routine.getId(), r ->
			{
				r.setName(name);
				r.setMode(mode);
				r.setTargetMillis(target == null ? 0 : target);
				r.setStopAtZero(stopAtZeroField.isSelected());
				r.setClock(clock);
				r.setAbandonAfterMillis(abandon);
				r.setLapsEnabled(lapsField.isSelected());
				r.setRestartOnStart(restartField.isSelected());
				r.setStartTrigger(startTrigger);
				r.setLapTrigger(lapTrigger);
				r.setStopTrigger(stopTrigger);
				r.setOverlay(overlay);
				r.setShowDelta(delta);
				r.setAlert(alert);
				r.setSound(sound);
				r.setNotify(notify);
			}));
			return;
		}
	}

	/**
	 * Tells the user which custom triggers were saved on the way through a
	 * dialog they then cancelled, and says nothing at all when none were.
	 *
	 * <p>Only on cancel. Saving a clock has nothing surprising in it, so
	 * saying this there would be a box in the way of the ordinary path.
	 */
	private static void sayWhatWasKept(Component parent, TriggerPicker... pickers)
	{
		final List<String> created = new ArrayList<>();
		for (TriggerPicker picker : pickers)
		{
			created.addAll(picker.getCreated());
		}

		final String kept = PanelMessages.keptCustomTriggers(created);
		if (kept != null)
		{
			Confirms.note(parent, "Clockwork", kept);
		}
	}

	/**
	 * Saves every call site a null check. The dialogs are also reachable from
	 * a test, where there is no plugin to have handed one over.
	 */
	private static Diagnostics orNone(Diagnostics diagnostics)
	{
		return diagnostics == null ? Diagnostics.none() : diagnostics;
	}
}

package com.clockwork.ui;

import com.clockwork.core.RoutineController;
import com.clockwork.core.SavedTrigger;
import com.clockwork.core.TriggerLibrary;
import java.awt.Component;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JTextField;

/**
 * The one form that makes and changes a saved custom trigger.
 *
 * <p>Shared by the clock editor, where picking Custom means "define a new one",
 * and by the side panel, where the library is managed on its own. One form, so
 * the rules a name and the two strings have to satisfy are asked for in one
 * wording rather than in two that drift.
 *
 * <p>Every rule it enforces lives in {@link TriggerLibrary}, which is pure and
 * tested. This class collects text and shows what came back.
 */
final class SavedTriggerDialog
{
	/**
	 * Width of the three boxes, in characters. Set rather than left to the
	 * text, because a new trigger starts with all three empty and a form of
	 * three empty boxes an inch wide is a form nobody can type in.
	 */
	private static final int COLUMNS = 18;

	private SavedTriggerDialog()
	{
	}

	/**
	 * Defines a new saved trigger and puts it in the library.
	 *
	 * @return the entry, or null when the user backed out
	 */
	static SavedTrigger showCreate(Component parent, RoutineController controller)
	{
		return show(parent, controller, null, "New custom trigger");
	}

	/**
	 * Changes an existing entry. A clock points at it by name, so a rename is
	 * followed through onto every clock waiting for it, which the controller
	 * does.
	 *
	 * @return the entry as it now stands, or null when the user backed out
	 */
	static SavedTrigger showEdit(Component parent, RoutineController controller, SavedTrigger entry)
	{
		if (entry == null)
		{
			return null;
		}
		return show(parent, controller, entry, "Edit custom trigger");
	}

	private static SavedTrigger show(Component parent, RoutineController controller, SavedTrigger entry,
		String title)
	{
		final JTextField nameField = new JTextField(entry == null ? "" : entry.getName(), COLUMNS);
		final JTextField optionField = new JTextField(entry == null ? "" : orEmpty(entry.getOption()), COLUMNS);
		final JTextField targetField = new JTextField(entry == null ? "" : orEmpty(entry.getTarget()), COLUMNS);

		nameField.setToolTipText("What you will call this trigger in the list, such as Note herbs.");
		optionField.setToolTipText("The left hand side of the menu entry, such as Rub, Use, Mine, or Bank. Leave it empty to match any option.");
		targetField.setToolTipText("The right hand side of the menu entry, such as Ardougne cloak 4, Bank chest, or Iron rocks. Part of it is enough, so Ardougne cloak matches Ardougne cloak 4. Leave it empty to match any target.");

		final JPanel form = new JPanel();
		form.setLayout(new BoxLayout(form, BoxLayout.Y_AXIS));
		form.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));
		Controls.row(form, new JLabel("Name"));
		Controls.row(form, nameField);
		Controls.row(form, new JLabel("Menu option"));
		Controls.row(form, optionField);
		Controls.row(form, new JLabel("Menu target"));
		Controls.row(form, targetField);

		final String currentName = entry == null ? null : entry.getName();

		while (true)
		{
			int result = JOptionPane.showConfirmDialog(parent, form, title,
				JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
			if (result != JOptionPane.OK_OPTION)
			{
				return null;
			}

			final String name = nameField.getText();
			final String option = optionField.getText();
			final String target = targetField.getText();

			final String problem = controller.getLibrary().problemWith(name, option, target, currentName);
			if (problem != null)
			{
				Confirms.warn(parent, "Clockwork", PanelMessages.escapeHtml(problem));
				continue;
			}

			if (currentName == null)
			{
				// One element so the lambda can hand the entry back out. The
				// add runs through the controller so the save and the panel
				// refresh happen on the same path every other change uses.
				final SavedTrigger[] saved = new SavedTrigger[1];
				controller.editLibrary(library -> saved[0] = library.add(name, option, target));
				return saved[0];
			}

			// An edit goes through its own controller method, because a rename
			// has to reach the clocks waiting for the old name as well as the
			// library.
			return controller.editTrigger(currentName, name, option, target);
		}
	}

	private static String orEmpty(String text)
	{
		return text == null ? "" : text;
	}
}

package com.clockwork.ui;

import com.clockwork.core.RoutineController;
import com.clockwork.core.SavedTrigger;
import com.clockwork.core.Trigger;
import com.clockwork.core.TriggerType;
import com.clockwork.diag.Diagnostics;
import java.awt.Component;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.DefaultComboBoxModel;
import javax.swing.DefaultListCellRenderer;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JSeparator;
import javax.swing.ListCellRenderer;

/**
 * The dropdown a clock's start or stop trigger is picked from.
 *
 * <p>Three groups, in this order.
 *
 * <ol>
 *   <li>The triggers this build knows about by name, Nothing first</li>
 *   <li>The user's own saved triggers, alphabetically</li>
 *   <li>Custom, which defines a new saved trigger and picks it</li>
 * </ol>
 *
 * <p>A clock holds the id of a saved trigger rather than a copy of its two
 * strings, so this hands back {@link Trigger#saved(String)} and never a copy.
 * That is what makes an edit to a saved trigger reach every clock waiting for
 * it.
 *
 * <p>The two rules dropped since the old form are worth naming. There is no
 * unnamed click trigger any more, so the pair of boxes that used to appear
 * under this row is gone and lives in {@link SavedTriggerDialog} instead, and a
 * clock pointing at a saved trigger that has since gone selects Nothing, which
 * is exactly what such a clock now does.
 */
final class TriggerPicker
{
	/**
	 * The rows between the groups. A sentinel rather than a value, so nothing
	 * can be confused for it, and it is drawn as a line and refused as a
	 * selection.
	 */
	private static final Object SEPARATOR = new Object();

	/**
	 * The fixed triggers, in the order they are offered. Written out rather
	 * than taken from {@code TriggerType.values()}, because the custom member
	 * belongs at the bottom under the saved ones rather than in this group.
	 */
	private static final TriggerType[] FIXED =
		{TriggerType.NONE, TriggerType.TELEPORT, TriggerType.BANK_CHEST, TriggerType.MINE_IRON};

	private final RoutineController controller;
	private final Diagnostics diagnostics;
	private final JComboBox<Object> combo = new JComboBox<>();

	/**
	 * The names of the entries defined through this dropdown while it has been
	 * on screen, in the order they were defined.
	 *
	 * <p>Kept because a new entry goes into the library the moment it is
	 * defined, whatever becomes of the clock dialog around it, and the dialog
	 * has to be able to say so when it is cancelled. Nothing is removed from
	 * this list, since nothing is removed from the library either.
	 */
	private final List<String> created = new ArrayList<>();

	/**
	 * The last thing the user actually chose, which a separator row or a
	 * cancelled Custom dialog is put back to.
	 */
	private Object chosen = TriggerType.NONE;

	/**
	 * True while this class is the one changing the selection, so its own
	 * changes do not come back round as another choice.
	 */
	private boolean adjusting;

	TriggerPicker(RoutineController controller, Diagnostics diagnostics, Trigger current)
	{
		this.controller = controller;
		this.diagnostics = diagnostics == null ? Diagnostics.none() : diagnostics;

		combo.setRenderer(renderer());
		rebuild(startingChoice(current));
		combo.addActionListener(e -> this.diagnostics.guard("editor.triggerPicker", this::onChoice));
	}

	JComboBox<Object> getComponent()
	{
		return combo;
	}

	/**
	 * The saved triggers this dropdown put in the library, in the order they
	 * were defined. Empty unless the user used the Custom row.
	 */
	List<String> getCreated()
	{
		return Collections.unmodifiableList(created);
	}

	/**
	 * What the clock should be set to, which is a reference when a saved
	 * trigger is picked.
	 */
	Trigger getTrigger()
	{
		final Object item = combo.getSelectedItem();
		if (item instanceof SavedTrigger)
		{
			return Trigger.saved(((SavedTrigger) item).getName());
		}
		if (item instanceof TriggerType && item != TriggerType.CUSTOM_CLICK)
		{
			return Trigger.of((TriggerType) item);
		}

		// Custom is a thing to do rather than a thing to be, so a dialog that
		// went nowhere leaves the clock manual rather than half configured.
		return Trigger.nothing();
	}

	/**
	 * What this clock is set to now, as a row in the list.
	 *
	 * <p>A reference to an entry that is no longer there comes back as Nothing,
	 * because that is what the clock does, and showing it as anything else
	 * would tell the user their clock still fires.
	 */
	private Object startingChoice(Trigger current)
	{
		final Trigger held = Trigger.orNothing(current);
		final String ref = held.getRef();
		if (ref != null)
		{
			final SavedTrigger entry = controller.getLibrary().byName(ref);
			return entry == null ? TriggerType.NONE : entry;
		}
		if (held.getType() == TriggerType.CUSTOM_CLICK)
		{
			// An inline click trigger, which only a hand edited config still
			// produces. There is no row for one, so it reads as Nothing and the
			// user can point the clock at a saved trigger instead.
			return TriggerType.NONE;
		}
		return held.getType();
	}

	/**
	 * Fills the list in and selects one row, without letting either look like a
	 * choice the user made.
	 */
	private void rebuild(Object select)
	{
		final List<Object> items = new ArrayList<>();
		for (TriggerType type : FIXED)
		{
			items.add(type);
		}

		final List<SavedTrigger> saved = controller.getLibrary().all();
		if (!saved.isEmpty())
		{
			items.add(SEPARATOR);
			items.addAll(saved);
		}
		items.add(SEPARATOR);
		items.add(TriggerType.CUSTOM_CLICK);

		adjusting = true;
		try
		{
			combo.setModel(new DefaultComboBoxModel<>(items.toArray()));
			combo.setSelectedItem(select);
			chosen = combo.getSelectedItem();
		}
		finally
		{
			adjusting = false;
		}
	}

	private void onChoice()
	{
		if (adjusting)
		{
			return;
		}

		final Object item = combo.getSelectedItem();
		if (item == SEPARATOR)
		{
			restore();
			return;
		}

		if (item == TriggerType.CUSTOM_CLICK)
		{
			final SavedTrigger made = SavedTriggerDialog.showCreate(combo, controller);
			if (made == null)
			{
				restore();
				return;
			}

			// It is in the library now, and it stays there even if the clock
			// dialog around this one is cancelled, so the dialog is given
			// something to say about it.
			created.add(made.getName());

			// The list is a row longer than it was, so it is built again rather
			// than have the new entry appended out of alphabetical order.
			rebuild(made);
			return;
		}

		chosen = item;
	}

	private void restore()
	{
		adjusting = true;
		try
		{
			combo.setSelectedItem(chosen);
		}
		finally
		{
			adjusting = false;
		}
	}

	/**
	 * Draws a saved trigger by its name, the Custom row with its trailing dots,
	 * and a separator as a line.
	 */
	private static ListCellRenderer<Object> renderer()
	{
		return new DefaultListCellRenderer()
		{
			private final JSeparator line = new JSeparator();

			@Override
			public Component getListCellRendererComponent(JList<?> list, Object value, int index,
				boolean selected, boolean focused)
			{
				if (value == SEPARATOR)
				{
					return line;
				}

				Component drawn = super.getListCellRendererComponent(list, value, index, selected, focused);
				if (value == TriggerType.CUSTOM_CLICK && drawn instanceof JLabel)
				{
					((JLabel) drawn).setText(TriggerType.CUSTOM_CLICK + "...");
				}
				return drawn;
			}
		};
	}
}

package com.clockwork;

import com.clockwork.core.AlertOverride;
import com.clockwork.core.AlertStyle;
import com.clockwork.core.Routine;
import com.clockwork.core.Toggle;
import com.clockwork.diag.Diagnostics;
import com.clockwork.overlay.OverlayCoordinator;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.client.Notifier;
import net.runelite.client.config.Notification;
import net.runelite.client.ui.overlay.OverlayManager;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.atLeastOnce;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.mockingDetails;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;

/**
 * The things a finished clock can do, which are every combination of a flash, a
 * notification and a chime, held against the plugin wide settings both ways
 * round.
 *
 * <p>The three parts of an alert are independent and each falls back to a
 * global of its own, so there is nothing clever to assert about any one of them
 * alone. What is worth asserting is the product. Nothing, any one of the three,
 * any two of them, and all three, all reachable on any clock whatever the
 * config panel says, which is the whole point of the per clock settings and is
 * the thing a fallback written as a gate would quietly break.
 *
 * <p>The direction that breaks first is a clock turning something <b>on</b>
 * while the global has it off. A resolve written as {@code global && perClock}
 * passes every off case and fails only that one, so both directions are here
 * rather than only the convenient one. The notification has a second way to
 * fail in that same direction, since {@code Notifier} returns straight back out
 * on a notification whose own tick is off, so a clock that says on while the
 * plugin wide tick is off has to be handed one with the tick turned on or it
 * asks for something and gets nothing.
 *
 * <p>The notification was briefly a fourth answer inside the drawn setting,
 * which made it exclusive with the two flashes. It is a setting of its own
 * again, because a user who wants a flash and a notification for the same clock
 * wants both and a single select cannot say that.
 *
 * <h2>How the three parts are read</h2>
 *
 * <p>The chime is counted by {@link SilentAudioPlayer}, since the build is
 * headless and the real player would throw where a test cannot see it.
 *
 * <p>The count in is here for the same reason. It is a fourth thing that can
 * make a noise and it reads the same per clock setting, so the question it has
 * to answer is not whether it beeps but whether a clock the user has silenced
 * stays silent, which is exactly the product above with one more row.
 *
 * <p>The flash is read as {@link Alerts#isFlashing()}, and the style used
 * throughout is {@link AlertStyle#SCREEN} on purpose. The screen flash needs no
 * timer box, so a clock can be asked to flash without standing the overlay
 * coordinator up around it, and the flash window is set by the same statement
 * that draws it. {@code ClockworkWiringTest} covers the timer box half of the
 * flash against real boxes, which is where a box is the thing in question.
 *
 * <p>The notification is counted off the mocked {@code Notifier}. What the real
 * one then does with it, and in particular that it says nothing while the
 * client has focus unless the item itself says to send anyway, is RuneLite's
 * behaviour rather than this plugin's and is not something a test here could
 * observe. It is written down where the user chooses the setting instead.
 */
public class AlertMatrixTest
{
	private final ClockworkPlugin plugin = new ClockworkPlugin();
	private final FakeClockworkConfig config = new FakeClockworkConfig();
	private final SilentAudioPlayer audioPlayer = new SilentAudioPlayer();
	private final BlockingClientThread clientThread = new BlockingClientThread();
	private final Client client = mock(Client.class);
	private final OverlayManager overlayManager = mock(OverlayManager.class);
	private final Notifier notifier = mock(Notifier.class);

	private Alerts alerts;

	@Before
	public void setUp()
	{
		final OverlayCoordinator overlays = new OverlayCoordinator(plugin, overlayManager, config,
			Diagnostics.none(), () -> null);
		alerts = new Alerts(plugin, client, config, overlayManager, overlays, notifier, clientThread,
			audioPlayer, Diagnostics.none(), () ->
		{
		});
		alerts.startUp();
	}

	/**
	 * How many notifications the plugin has asked RuneLite for so far. Every
	 * call this mock takes is a {@code notify}, so counting its invocations
	 * counts them without a captor and without resetting anything between rows.
	 */
	private int notified()
	{
		return mockingDetails(notifier).getInvocations().size();
	}

	/**
	 * The notification the plugin handed over last, which is what says whether
	 * the user's own item made the trip and what was changed on the way.
	 */
	private Notification handedOver()
	{
		final ArgumentCaptor<Notification> captor = ArgumentCaptor.forClass(Notification.class);
		verify(notifier, atLeastOnce()).notify(captor.capture(), anyString());
		return captor.getValue();
	}

	/**
	 * One clock, on its own settings, finished once.
	 *
	 * <p>All three parts are folded into the answer, in a fixed order, so a row
	 * that says "flash" is also saying that nothing was sent to RuneLite and
	 * nothing was played.
	 *
	 * @return what it did, as the words in the table this class is about
	 */
	private String whatHappens(AlertOverride alert, Toggle notify, Toggle sound)
	{
		final Routine routine = new Routine("herb", "Herb run");
		routine.setAlert(alert);
		routine.setNotify(notify);
		routine.setSound(sound);

		final int playsBefore = audioPlayer.playCount();
		final int notifiedBefore = notified();
		alerts.clearFlash();
		alerts.alert(routine, "Herb run finished");

		final List<String> did = new ArrayList<>();
		if (alerts.isFlashing())
		{
			did.add("flash");
		}
		if (notified() > notifiedBefore)
		{
			did.add("notification");
		}
		if (audioPlayer.playCount() > playsBefore)
		{
			did.add("chime");
		}

		return did.isEmpty() ? "nothing" : String.join(" and ", did);
	}

	/**
	 * One clock, on its own settings, counted in three times.
	 *
	 * @return how many of the three beats were heard
	 */
	private int countedIn(Routine routine)
	{
		final int before = audioPlayer.playCount();
		alerts.countIn(routine);
		alerts.countIn(routine);
		alerts.countIn(routine);
		return audioPlayer.playCount() - before;
	}

	/**
	 * Every global off, and each of the three still reachable on its own by a
	 * clock saying so. This is the direction worth having, since all three of
	 * these rows need a per clock setting to beat a global that is off.
	 */
	@Test
	public void eachOfTheThreeIsReachableAloneWhileEveryGlobalIsOff()
	{
		config.setAlertStyle(AlertStyle.NONE);
		config.setNotification(Notification.OFF);
		config.setPlaySound(false);

		assertEquals("a clock left alone under three globals that are off did something anyway",
			"nothing", whatHappens(AlertOverride.USE_GLOBAL, Toggle.USE_GLOBAL, Toggle.USE_GLOBAL));
		assertEquals("a clock asked to flash and nothing else did not flash",
			"flash", whatHappens(AlertOverride.SCREEN, Toggle.OFF, Toggle.OFF));
		assertEquals("a clock asked for the notification alone was not announced, so the notification"
				+ " override cannot beat a global that is off and the setting is a gate rather than"
				+ " a default",
			"notification", whatHappens(AlertOverride.NONE, Toggle.ON, Toggle.OFF));
		assertEquals("a clock asked for the chime alone stayed silent, so the chime override cannot"
				+ " beat a global that is off and the setting is a gate rather than a default",
			"chime", whatHappens(AlertOverride.NONE, Toggle.OFF, Toggle.ON));
	}

	/**
	 * And the other way. Every global on, and each of the three still reachable
	 * on its own, this time by a clock turning the other two off for itself.
	 */
	@Test
	public void eachOfTheThreeIsReachableAloneWhileEveryGlobalIsOn()
	{
		config.setAlertStyle(AlertStyle.SCREEN);
		config.setNotification(Notification.ON);
		config.setPlaySound(true);

		assertEquals("a clock that asked for none of the three got one of them anyway",
			"nothing", whatHappens(AlertOverride.NONE, Toggle.OFF, Toggle.OFF));
		assertEquals("a clock that turned the notification and the chime off for itself got one"
				+ " of them anyway",
			"flash", whatHappens(AlertOverride.USE_GLOBAL, Toggle.OFF, Toggle.OFF));
		assertEquals("a clock that turned the flash and the chime off for itself got one of them"
				+ " anyway",
			"notification", whatHappens(AlertOverride.NONE, Toggle.USE_GLOBAL, Toggle.OFF));
		assertEquals("a clock that turned the flash and the notification off for itself got one of"
				+ " them anyway",
			"chime", whatHappens(AlertOverride.NONE, Toggle.OFF, Toggle.USE_GLOBAL));
		assertEquals("a clock left alone under three globals that are on did less than all three",
			"flash and notification and chime",
			whatHappens(AlertOverride.USE_GLOBAL, Toggle.USE_GLOBAL, Toggle.USE_GLOBAL));
	}

	/**
	 * The four way table this change exists for, with the plugin wide
	 * notification off.
	 *
	 * <p>A flash and a notification are two settings rather than two answers to
	 * one, so all four corners are reachable on a single clock. The pair used to
	 * be a single select, which made the top left corner unreachable and was the
	 * whole of what was wrong with it.
	 */
	@Test
	public void allFourOfTheFlashAndTheNotificationAreReachableWhileTheGlobalNotificationIsOff()
	{
		config.setAlertStyle(AlertStyle.NONE);
		config.setNotification(Notification.OFF);
		config.setPlaySound(false);

		assertEquals("a clock asked for a flash and a notification got one of the two, so the pair"
				+ " is still a single select in everything but name",
			"flash and notification", whatHappens(AlertOverride.SCREEN, Toggle.ON, Toggle.OFF));
		assertEquals("flash only", "flash",
			whatHappens(AlertOverride.SCREEN, Toggle.OFF, Toggle.OFF));
		assertEquals("notification only", "notification",
			whatHappens(AlertOverride.NONE, Toggle.ON, Toggle.OFF));
		assertEquals("neither", "nothing",
			whatHappens(AlertOverride.NONE, Toggle.OFF, Toggle.OFF));
	}

	/**
	 * The same four corners with the plugin wide notification on, reached
	 * through the fallback rather than by saying so on the clock. The tick is
	 * the default for a clock left on use global and nothing more than that.
	 */
	@Test
	public void allFourOfTheFlashAndTheNotificationAreReachableWhileTheGlobalNotificationIsOn()
	{
		config.setAlertStyle(AlertStyle.NONE);
		config.setNotification(Notification.ON);
		config.setPlaySound(false);

		assertEquals("flash and notification",
			whatHappens(AlertOverride.SCREEN, Toggle.USE_GLOBAL, Toggle.OFF));
		assertEquals("a clock that turned the notification off for itself was announced anyway,"
				+ " so the plugin wide tick is a gate rather than a default",
			"flash", whatHappens(AlertOverride.SCREEN, Toggle.OFF, Toggle.OFF));
		assertEquals("notification", whatHappens(AlertOverride.NONE, Toggle.USE_GLOBAL, Toggle.OFF));
		assertEquals("nothing", whatHappens(AlertOverride.NONE, Toggle.OFF, Toggle.OFF));
	}

	/**
	 * The drawn setting no longer decides whether RuneLite hears about the run.
	 *
	 * <p>It briefly did, and undoing that is the change this file was reworked
	 * for. A clock that draws nothing is announced if it asked to be, and a
	 * clock that flashes is announced too, so no value of the drawn setting can
	 * take the notification away.
	 */
	@Test
	public void theDrawnSettingDoesNotDecideWhetherTheNotificationFires()
	{
		config.setNotification(Notification.OFF);
		config.setPlaySound(false);

		for (AlertOverride drawn : new AlertOverride[]{AlertOverride.NONE, AlertOverride.TIMER_BOX,
			AlertOverride.SCREEN})
		{
			assertTrue("a clock on " + drawn + " that asked to be announced was not, so the drawn"
					+ " setting is deciding the notification again",
				whatHappens(drawn, Toggle.ON, Toggle.OFF).contains("notification"));
			assertFalse("a clock on " + drawn + " that asked not to be announced was anyway",
				whatHappens(drawn, Toggle.OFF, Toggle.OFF).contains("notification"));
		}
	}

	/**
	 * The one that {@code Notifier} would swallow.
	 *
	 * <p>A clock that says on while the plugin wide tick is off has asked for a
	 * notification, and {@code Notifier} returns without doing anything at all
	 * when the notification it is handed is not enabled. So the plugin turns the
	 * tick on in the copy it sends. Counting the call is not enough to catch
	 * this, because the call is made either way and it is the argument that
	 * decides whether anything happens, so the argument is what is read here.
	 */
	@Test
	public void aClockThatSaysOnWhileTheGlobalTickIsOffIsHandedAnEnabledNotification()
	{
		config.setNotification(Notification.OFF);
		config.setPlaySound(false);

		assertEquals("notification", whatHappens(AlertOverride.NONE, Toggle.ON, Toggle.OFF));
		assertTrue("the plugin asked RuneLite to notify with a notification that is switched off,"
				+ " which Notifier drops on the floor, so the clock asked for something and got"
				+ " nothing",
			handedOver().isEnabled());
	}

	/**
	 * And everything else on that item is the user's and travels untouched.
	 *
	 * <p>This is the whole of the objection to turning the tick on, answered.
	 * The tick means "the clocks that have not answered for themselves", the way
	 * the plugin wide chime setting already does, and the parts of the item that
	 * say how a notification behaves are not the plugin's to change. In
	 * particular Override and Send when focused are what a user sets to get a
	 * notification while looking at the game, and they would be worth nothing if
	 * this rebuilt the item rather than copying it.
	 */
	@Test
	public void everythingElseOnTheUsersNotificationSurvivesTheTrip()
	{
		final Notification theirs = Notification.OFF
			.withOverride(true)
			.withInitialized(true)
			.withSendWhenFocused(true)
			.withTray(true)
			.withTimeout(9)
			.withGameMessage(true);

		config.setNotification(theirs);
		config.setPlaySound(false);

		assertEquals("notification", whatHappens(AlertOverride.NONE, Toggle.ON, Toggle.OFF));

		final Notification sent = handedOver();
		assertTrue(sent.isEnabled());
		assertTrue("Override was dropped, so RuneLite would throw the user's settings away and use"
				+ " its own defaults instead", sent.isOverride());
		assertTrue("Send when focused was dropped, which is the one setting that decides whether a"
				+ " notification is seen at all while the client has focus",
			sent.isSendWhenFocused());
		assertTrue(sent.isTray());
		assertTrue(sent.isGameMessage());
		assertEquals(9, sent.getTimeout());
		assertFalse("the plugin changed the user's own item rather than a copy of it",
			config.notification().isEnabled());
	}

	/**
	 * A clock that came out of a blob written before one of these fields
	 * existed, or out of a hand edited document that named the key and put
	 * something unreadable under it, decodes with a null and has to read as use
	 * global.
	 *
	 * <p>{@code RoutineMigration} fills them in on the way through storage, so
	 * this is the belt to that braces. {@code Overridable.resolve} answers for a
	 * null on its own, and the point here is that both paths go through it
	 * rather than dereferencing.
	 */
	@Test
	public void aClockWithNoAnswerAtAllFollowsTheGlobalBothWays()
	{
		config.setAlertStyle(AlertStyle.NONE);

		config.setNotification(Notification.ON);
		config.setPlaySound(true);
		assertEquals("a clock carrying neither setting did not follow the globals that are on",
			"notification and chime", whatHappens(AlertOverride.NONE, null, null));

		config.setNotification(Notification.OFF);
		config.setPlaySound(false);
		assertEquals("a clock carrying neither setting did not follow the globals that are off",
			"nothing", whatHappens(AlertOverride.NONE, null, null));
	}

	/**
	 * The count in reads the same setting the chime reads, both ways round. A
	 * clock that is silent is counted in silently, which is to say not at all,
	 * and a clock that chimes while the plugin wide setting is off is counted
	 * in as well.
	 *
	 * <p>This is the whole of the rule. The count in is the chime arriving
	 * early rather than a channel of its own, so there is no further setting and
	 * no way for one of the two to be heard while the other is not.
	 */
	@Test
	public void theCountInFollowsTheSameChimeSettingTheAlertDoes()
	{
		final Routine routine = new Routine("herb", "Herb run");

		config.setPlaySound(false);
		routine.setSound(Toggle.USE_GLOBAL);
		assertEquals("a clock that does not chime was counted in anyway", 0, countedIn(routine));

		routine.setSound(Toggle.OFF);
		assertEquals(0, countedIn(routine));

		routine.setSound(Toggle.ON);
		assertEquals("a clock that turned the chime on for itself was not counted in, so the count"
				+ " in reads the global as a gate rather than as a default",
			3, countedIn(routine));

		config.setPlaySound(true);
		routine.setSound(Toggle.USE_GLOBAL);
		assertEquals(3, countedIn(routine));

		routine.setSound(Toggle.OFF);
		assertEquals("a clock that turned the chime off for itself was counted in anyway, so"
				+ " silencing a clock does not silence it",
			0, countedIn(routine));

		routine.setSound(null);
		assertEquals("a clock carrying no chime setting at all did not follow the global", 3,
			countedIn(routine));
	}

	/**
	 * The count in is a different clip from the chime, and the run it counts in
	 * ends on the chime. Three beats and then the sound, in that order, which
	 * is the whole of what a user hears.
	 */
	@Test
	public void theCountInIsThreeBeatsAndThenTheChime()
	{
		config.setPlaySound(true);
		config.setAlertStyle(AlertStyle.NONE);

		final Routine routine = new Routine("herb", "Herb run");
		alerts.countIn(routine);
		alerts.countIn(routine);
		alerts.countIn(routine);
		alerts.alert(routine, "Herb run reached zero");

		assertEquals("the count in played the same clip the chime plays, so a user hears the alert"
				+ " four times rather than a count in and an alert",
			Arrays.asList("beep.wav", "beep.wav", "beep.wav", "complete.wav"),
			audioPlayer.played());
	}

	/**
	 * A volume dragged to zero is a user asking for silence on every clock, and
	 * the count in goes through the same volume as everything else rather than
	 * around it.
	 */
	@Test
	public void aVolumeOfZeroSilencesTheCountInAsWell()
	{
		config.setPlaySound(true);
		config.setSoundVolume(0);

		final Routine routine = new Routine("herb", "Herb run");
		alerts.countIn(routine);
		alerts.alert(routine, "Herb run reached zero");

		assertTrue("a user who asked for silence was counted in", audioPlayer.played().isEmpty());
	}

	/**
	 * One beat of the count in plays one clip and does nothing else. It draws
	 * no flash, opens no flash window, and sends no notification, because the
	 * moment worth announcing is zero and this is the approach to it.
	 */
	@Test
	public void aBeatOfTheCountInPlaysOneClipAndDrawsNothing()
	{
		config.setPlaySound(true);
		config.setAlertStyle(AlertStyle.SCREEN);

		final Routine routine = new Routine("herb", "Herb run");
		alerts.countIn(routine);

		assertEquals(1, audioPlayer.playCount());
		assertFalse("a beat of the count in opened a flash window, so a timer box would be held"
				+ " open three seconds before the run ends",
			alerts.isFlashing());
		assertNull(alerts.getFlashingRoutineId());
		verify(notifier, never()).notify(any(Notification.class), anyString());
	}

	/**
	 * The chime a clock asked for is played once per finish rather than once per
	 * anything else, and the flash it did not ask for leaves the flash window
	 * shut so the refresh has nothing to hold a box open for.
	 */
	@Test
	public void aChimeOnlyAlertPlaysOnceAndOpensNoFlashWindow()
	{
		config.setAlertStyle(AlertStyle.SCREEN);
		config.setPlaySound(false);

		final Routine routine = new Routine("herb", "Herb run");
		routine.setAlert(AlertOverride.NONE);
		routine.setNotify(Toggle.OFF);
		routine.setSound(Toggle.ON);

		alerts.alert(routine, "Herb run finished");

		assertEquals("one finished run played the chime a number of times that is not one",
			1, audioPlayer.playCount());
		assertFalse("a clock that draws nothing left a flash window open, so its timer box would be"
				+ " held on screen for an alert that is not on screen",
			alerts.isFlashing());
		assertNull("nothing at all is being flashed and the plugin still names a clock as the one"
				+ " mid alert",
			alerts.getFlashingRoutineId());
	}

	/**
	 * What RuneLite is handed, which is the plugin's own notification item and
	 * the message the run ended with.
	 *
	 * <p>The item stays plugin wide on purpose. It says how the notification
	 * behaves, which is RuneLite's own question about tray icons, sounds, and
	 * whether to send while focused, and the per clock setting is what says
	 * whether a clock uses it at all.
	 *
	 * <p>The very same object, not a copy of it. Turning the tick on in
	 * something that already has it on changes nothing, so nothing is rebuilt,
	 * and what a clock left on use global gets is the user's item exactly as
	 * they left it. What survives when the tick does have to be turned on is
	 * checked field by field in
	 * {@link #everythingElseOnTheUsersNotificationSurvivesTheTrip}.
	 */
	@Test
	public void theNotificationCarriesThePluginsOwnSettingAndTheMessage()
	{
		config.setAlertStyle(AlertStyle.NONE);

		final Routine routine = new Routine("herb", "Herb run");
		alerts.alert(routine, "Herb run finished in 16:00");

		verify(notifier, times(1).description("what went out was not the plugin's own notification"
			+ " item, or not the message the run ended with"))
			.notify(config.notification(), "Herb run finished in 16:00");
		assertFalse("an alert that draws nothing opened a flash window, so a timer box would be held"
				+ " on screen for an alert that is not on screen",
			alerts.isFlashing());
	}
}

package com.clockwork;

import java.util.function.BooleanSupplier;
import net.runelite.client.callback.ClientThread;

/**
 * A {@link ClientThread} that runs everything handed to it immediately, on the
 * caller's thread.
 *
 * <p>Without this, anything the plugin defers to the client thread simply never
 * runs in a test, because the queue behind the real one is drained by the game
 * engine and there is no game engine here. The alert path is the example that
 * matters, {@code notifier.notify} is reached through {@code invoke}, so with
 * the real class a test of it would assert on something that had not happened
 * yet and would pass or fail on timing.
 *
 * <p>Borrowed from DinkPlugin, which is where our engineering guide found the
 * idea. It is the one piece that makes the alert path testable in a single
 * threaded JUnit run.
 *
 * <p>Two deliberate simplifications, both of which flatter the code under test
 * and are worth knowing before writing a test that leans on them.
 *
 * <ul>
 * <li>The real {@code invoke(Runnable)} is synchronous only when the caller is
 * already on the client thread. Here it always is.</li>
 * <li>The real {@code invoke(BooleanSupplier)} re queues the supplier every
 * engine cycle until it returns true. Here it is called once and the answer is
 * thrown away, so a test cannot see a retry.</li>
 * </ul>
 *
 * <p>Subclassing works because {@code ClientThread} has a public no argument
 * constructor and none of these methods are final. Its own injected fields stay
 * null, which is safe only because every method that would read one is
 * overridden below.
 */
class BlockingClientThread extends ClientThread
{
	@Override
	public void invoke(Runnable runnable)
	{
		if (runnable != null)
		{
			runnable.run();
		}
	}

	@Override
	public void invoke(BooleanSupplier supplier)
	{
		if (supplier != null)
		{
			supplier.getAsBoolean();
		}
	}

	@Override
	public void invokeLater(Runnable runnable)
	{
		invoke(runnable);
	}

	@Override
	public void invokeLater(BooleanSupplier supplier)
	{
		invoke(supplier);
	}

	@Override
	public void invokeAtTickEnd(Runnable runnable)
	{
		invoke(runnable);
	}
}

package com.clockwork;

import java.awt.Color;
import java.awt.Dimension;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.FontType;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.ModifierlessKeybind;
import net.runelite.client.config.Notification;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Guards the other half of the config surface, that it can actually be drawn.
 *
 * <p>{@link ClockworkConfigTest} next door checks that every method carries a
 * {@code @ConfigItem}, which stops the proxy returning null to its callers.
 * That says nothing about whether RuneLite can build a control for what the
 * method returns.
 *
 * <p>It cannot build one for everything. RuneLite's {@code ConfigPanel} walks
 * the items and dispatches on the return type through a plain if/else chain
 * with no terminal else, so a type it does not know produces a label with an
 * empty space where the control should be. Nothing throws, nothing is logged,
 * and the setting simply cannot be changed. Adding a {@code long} or an
 * {@code Instant} getter to the interface would look perfectly reasonable in
 * review and ship a dead row in the config panel.
 *
 * <p>The set below mirrors that chain exactly, read from
 * {@code runelite-client/src/main/java/net/runelite/client/plugins/config/ConfigPanel.java}
 * at commit b9ea1f8, the {@code rebuild()} method, fetched from GitHub on
 * 2026-08-20. It reads,
 *
 * <pre>
 * if (cid.getType() == boolean.class)                                        createCheckbox
 * else if (cid.getType() == int.class)                                       createIntSpinner
 * else if (cid.getType() == double.class)                                    createDoubleSpinner
 * else if (cid.getType() == String.class)                                    createTextField
 * else if (cid.getType() == Color.class)                                     createColorPicker
 * else if (cid.getType() == Dimension.class)                                 createDimension
 * else if (cid.getType() instanceof Class &amp;&amp; ((Class) cid.getType()).isEnum()) createComboBox
 * else if (cid.getType() == Keybind.class || == ModifierlessKeybind.class)   createKeybind
 * else if (cid.getType() == Notification.class)                              createNotification
 * else if (cid.getType() == FontType.class)                                  createFont
 * else if (cid.getType() instanceof ParameterizedType)
 *     if (parameterizedType.getRawType() == Set.class)                       createList
 * </pre>
 *
 * <p>Note that RuneLite reads the type with {@code getGenericReturnType()}, in
 * {@code ConfigManager.getConfigDescriptor}, not {@code getReturnType()}. So
 * this does the same, otherwise a {@code Set} item would be judged against its
 * raw type and the answer would differ from the client's.
 *
 * <p>Note also that the boxed types are not on the list. {@code Boolean} and
 * {@code Integer} are stored and read back perfectly well by the config
 * manager, so nothing fails at runtime, and neither of them gets a control.
 * That is exactly the sort of near miss this test is for.
 *
 * <p>THIS TEST USES REFLECTION ON PURPOSE, AND IT IS ALLOWED TO. The plugin
 * rules forbid reflection in shipped code. This class lives in the test source
 * set, is never packaged into the plugin, and never runs inside the client. No
 * main source file uses reflection.
 */
public class ClockworkConfigRenderableTest
{
	@Test
	public void everyConfigItemReturnsSomethingRuneLiteCanDraw()
	{
		final List<String> undrawable = new ArrayList<>();
		int checked = 0;

		for (Method method : ClockworkConfig.class.getDeclaredMethods())
		{
			if (method.isSynthetic() || Modifier.isStatic(method.getModifiers())
				|| method.getAnnotation(ConfigItem.class) == null)
			{
				continue;
			}

			checked++;
			if (!renderable(method.getGenericReturnType()))
			{
				undrawable.add(method.getName() + " returns " + method.getGenericReturnType().getTypeName());
			}
		}

		assertTrue("no annotated config methods were found at all, so this test is not testing anything",
			checked > 5);
		assertTrue("RuneLite's config panel builds a control by switching on the return type, and its"
				+ " if/else chain has no terminal else. A type it does not know draws a label with"
				+ " nothing beside it, silently, so the setting cannot be changed. Use one of"
				+ " boolean, int, double, String, Color, Dimension, an enum, Keybind,"
				+ " ModifierlessKeybind, Notification, FontType, or Set of an enum. Offending"
				+ " methods, " + undrawable,
			undrawable.isEmpty());
	}

	/**
	 * The same decision RuneLite's {@code ConfigPanel.rebuild()} makes, in the
	 * same order, including the two branches that are not exact equality.
	 */
	private static boolean renderable(Type type)
	{
		return type == boolean.class
			|| type == int.class
			|| type == double.class
			|| type == String.class
			|| type == Color.class
			|| type == Dimension.class
			|| (type instanceof Class && ((Class<?>) type).isEnum())
			|| type == Keybind.class
			|| type == ModifierlessKeybind.class
			|| type == Notification.class
			|| type == FontType.class
			|| (type instanceof ParameterizedType && ((ParameterizedType) type).getRawType() == Set.class);
	}
}

package com.clockwork;

import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.util.ArrayList;
import java.util.List;
import net.runelite.client.config.ConfigItem;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Guards the whole class of bug that a composed default method on a config
 * interface causes.
 *
 * <p>RuneLite proxies every method on a {@code @ConfigGroup} interface. A
 * method without a {@code @ConfigItem} never runs the default body written
 * underneath it. The proxy logs one warning and returns null, and because the
 * warning comes from the client rather than from here it is easy to miss and
 * easy to reintroduce. That is exactly what happened once already, with a
 * {@code durationFormat()} helper that returned null to every caller and threw
 * a null pointer on the refresh path a few hundred times a minute.
 *
 * <p>Nothing in our own logic can catch that, because the failure is in
 * somebody else's proxy. Reading the annotations back is the only way.
 *
 * <p>THIS TEST USES REFLECTION ON PURPOSE, AND IT IS ALLOWED TO. The plugin
 * rules forbid reflection in shipped code. This class lives in the test source
 * set, is never packaged into the plugin, and never runs inside the client. No
 * main source file uses reflection.
 */
public class ClockworkConfigTest
{
	@Test
	public void everyConfigMethodIsAnnotated()
	{
		final List<String> bare = new ArrayList<>();
		int checked = 0;

		for (Method method : ClockworkConfig.class.getDeclaredMethods())
		{
			if (method.isSynthetic() || Modifier.isStatic(method.getModifiers()))
			{
				continue;
			}

			checked++;
			if (method.getAnnotation(ConfigItem.class) == null)
			{
				bare.add(method.getName());
			}
		}

		assertTrue("no config methods were found at all, so this test is not testing anything", checked > 5);
		assertTrue("every method on a config interface is proxied, and one without @ConfigItem returns null"
				+ " to its callers rather than running its body. Move it to a helper class outside the"
				+ " interface. Offending methods, " + bare,
			bare.isEmpty());
	}
}

package com.clockwork;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Stream;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Guards the one property the whole test suite rests on, that
 * {@code com.clockwork.core} has never heard of the client.
 *
 * <p>Our engineering guide puts it as a grep. Search the core package for
 * {@code net.runelite.api}, {@code javax.swing}, and {@code java.awt}, and if
 * anything comes back the core is not a core. It then says to make that a test
 * so it stays true, which is this file.
 *
 * <p>The payoff is not tidiness. A pure core is the only part of a plugin that
 * can be tested without a running game, and the hundreds of tests under
 * {@code src/test/java/com/clockwork/core} exist because it is pure. One import
 * of {@code Client} in there would compile, work, and quietly take the whole
 * level with it, because those tests would then need a client to construct the
 * thing they are testing. Nothing else in the build would notice.
 *
 * <p>{@code net.runelite.client} is on the list as well, which the guide does
 * not name. The rule is the same rule. A {@code Keybind} or a {@code ColorScheme}
 * in the core drags in the client just as surely as a {@code Client} does, and
 * the core is free of both today, so the wider list costs nothing and is worth
 * having written down.
 *
 * <h2>Comments do not count</h2>
 *
 * <p>{@code core/TeleportAnimations.java} names
 * {@code net.runelite.api.gameval.AnimationID} in prose, and it has to. It
 * mirrors ids out of that class by hand, precisely because it is not allowed to
 * import it, and a comment that could not say so would be a worse comment. So
 * the scan strips comments and string literals first and reads only code.
 *
 * <p>The stripper is a small state machine rather than a regular expression,
 * because the naive version of this treats the {@code //} in a URL inside a
 * javadoc block as the start of a line comment and gets the rest of the file
 * wrong.
 *
 * <p>The scan is over the source text rather than the compiled classes, the
 * same as {@link ClockworkWindowTest} and for the same reason. A constant
 * folded away or a class named only in an annotation leaves nothing in the
 * bytecode to find.
 */
public class ClockworkCoreTest
{
	/**
	 * The package that is not allowed to know the client exists, relative to
	 * the plugin directory the tests run in.
	 */
	private static final String CORE_SOURCE = "src/main/java/com/clockwork/core";

	/**
	 * How few files would mean the walk found the wrong directory. The core
	 * holds well over twice this.
	 */
	private static final int TOO_FEW = 12;

	/**
	 * Everything the core may not name. The first three are the guide's own
	 * list. The fourth is the rest of the client, held to the same rule.
	 *
	 * <p>Widening this is free. Narrowing it should be a decision somebody
	 * makes on purpose, in this file, next to the reasons above.
	 */
	private static final List<String> FORBIDDEN = Arrays.asList(
		"net.runelite.api",
		"net.runelite.client",
		"javax.swing",
		"java.awt");

	@Test
	public void theCoreHasNeverHeardOfTheClient() throws IOException
	{
		final List<Path> sources = coreSources();

		assertFalse("no source files were found under " + new File(CORE_SOURCE).getAbsolutePath()
				+ ", so this test would pass by scanning nothing. It expects to run with the plugin"
				+ " directory as the working directory.",
			sources.isEmpty());
		assertTrue("only " + sources.size() + " files were found under " + CORE_SOURCE + ", which is too"
				+ " few to be the whole core, so this test is not scanning what it thinks it is",
			sources.size() >= TOO_FEW);

		final List<String> offences = new ArrayList<>();
		for (Path source : sources)
		{
			final String code = withoutCommentsAndStrings(
				new String(Files.readAllBytes(source), StandardCharsets.UTF_8));

			for (String forbidden : FORBIDDEN)
			{
				if (code.contains(forbidden))
				{
					offences.add(source + " references " + forbidden);
				}
			}
		}

		assertTrue("com.clockwork.core is the part of this plugin that can be tested without a running"
				+ " game, and it can only stay that way while it imports nothing from the client, from"
				+ " Swing, or from AWT. Every test under src/test/java/com/clockwork/core depends on"
				+ " that. Move whatever needs the client up into the plugin package and hand the core"
				+ " plain values instead. Offending files, " + offences,
			offences.isEmpty());
	}

	/**
	 * The guard, checked against itself.
	 *
	 * <p>The test above passes trivially if the stripper ever eats the whole
	 * file, so the stripper is asked to keep code and drop prose on a sample
	 * that has both. Without this, a bug in the stripper reads as a clean core.
	 */
	@Test
	public void theStripperKeepsCodeAndDropsProse()
	{
		final String source = "package com.clockwork.core;\n"
			+ "// see net.runelite.api.gameval.AnimationID\n"
			+ "/* and javax.swing and net.runelite.client.ui too,\n"
			+ " * plus a http://example.com/x that a naive stripper reads as a line comment */\n"
			+ "import java.util.List;\n"
			+ "class Sample { String s = \"java.awt.Color\"; List<String> x; }\n";

		final String code = withoutCommentsAndStrings(source);

		assertTrue("the stripper dropped code as well as prose, so the scan above reads nothing",
			code.contains("import java.util.List;") && code.contains("class Sample"));
		for (String forbidden : FORBIDDEN)
		{
			assertFalse("the stripper left " + forbidden + " behind, and every mention of it in that"
					+ " sample is in a comment or a string literal",
				code.contains(forbidden));
		}
	}

	/**
	 * Everything outside a comment and outside a string or character literal.
	 *
	 * <p>Each dropped run is replaced by a single space rather than deleted, so
	 * two identifiers either side of a comment cannot be pushed together into a
	 * third thing that was never written.
	 */
	private static String withoutCommentsAndStrings(String source)
	{
		final StringBuilder code = new StringBuilder(source.length());
		final int length = source.length();
		int index = 0;

		while (index < length)
		{
			final char current = source.charAt(index);
			final char next = index + 1 < length ? source.charAt(index + 1) : '\0';

			if (current == '/' && next == '/')
			{
				while (index < length && source.charAt(index) != '\n')
				{
					index++;
				}
				code.append(' ');
			}
			else if (current == '/' && next == '*')
			{
				index += 2;
				while (index < length && !(source.charAt(index) == '*'
					&& index + 1 < length && source.charAt(index + 1) == '/'))
				{
					index++;
				}
				index = Math.min(length, index + 2);
				code.append(' ');
			}
			else if (current == '"' || current == '\'')
			{
				index = endOfLiteral(source, index, current);
				code.append(' ');
			}
			else
			{
				code.append(current);
				index++;
			}
		}

		return code.toString();
	}

	/**
	 * Where a string or character literal ends, counting escapes so that a
	 * quote written as {@code \"} does not close it early.
	 *
	 * @param start the index of the opening quote
	 * @return the index just past the closing quote
	 */
	private static int endOfLiteral(String source, int start, char quote)
	{
		int index = start + 1;
		while (index < source.length())
		{
			final char current = source.charAt(index);
			if (current == '\\')
			{
				index += 2;
				continue;
			}
			if (current == quote)
			{
				return index + 1;
			}
			index++;
		}
		return index;
	}

	private static List<Path> coreSources() throws IOException
	{
		final File root = new File(CORE_SOURCE);
		assertTrue("expected to run with the plugin directory as the working directory, looked for "
			+ root.getAbsolutePath(), root.isDirectory());

		try (Stream<Path> walk = Files.walk(root.toPath()))
		{
			final List<Path> sources = new ArrayList<>();
			walk.filter(Files::isRegularFile)
				.filter(path -> path.toString().endsWith(".java"))
				.forEach(sources::add);
			return sources;
		}
	}
}

package com.clockwork;

import com.clockwork.core.ClockMode;
import com.clockwork.core.Mode;
import com.clockwork.core.OverlayOverride;
import com.clockwork.core.Routine;
import com.clockwork.core.Run;
import com.clockwork.core.Status;
import com.clockwork.core.Totals;
import com.clockwork.core.Toggle;
import com.clockwork.core.Trigger;
import com.clockwork.core.TriggerEvent;
import com.clockwork.core.TriggerLibrary;
import com.clockwork.core.TriggerType;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Clocks as a document. What goes out, what may not go out, and what happens
 * when one comes back in.
 *
 * <p>The document is the same shape as the saved state, so every test here that
 * reads one reads it through the plugin's own decode. A second parser would be
 * a second thing to get wrong.
 */
public class ClockworkDocumentTest
{
	private static final Gson GSON = new Gson();

	private TriggerLibrary library = TriggerLibrary.empty();

	private Routine clock(String id, String name)
	{
		Routine routine = new Routine(id, name);
		routine.getHistory().add(new Run(1000, 61000, 60000, new ArrayList<>(), Status.COMPLETED));

		// More lifetime runs than there are stored runs, which is what every
		// clock that has been used for a while looks like, and is the only way
		// to tell a count that was carried across from one that was worked out
		// again from the runs that are left.
		routine.setTotals(new Totals(214, 214L * 300_000L));
		return routine;
	}

	// Writing

	@Test
	public void anExportCarriesTheSettingsAndNothingElse()
	{
		Routine herb = clock("a", "Herb run");
		herb.setMode(Mode.COUNT_DOWN);
		herb.setTargetMillis(360_000);
		herb.setClock(ClockMode.LOGGED_IN_ONLY);
		herb.setOverlay(OverlayOverride.WHILE_RUNNING);
		herb.setShowDelta(Toggle.ON);
		herb.setStopTrigger(Trigger.of(TriggerType.BANK_CHEST));

		String document = ClockworkDocument.exportAll(GSON, Collections.singletonList(herb), library);

		assertTrue(document, document.contains("\"name\": \"Herb run\""));
		assertTrue(document, document.contains("\"mode\": \"countdown\""));
		assertTrue(document, document.contains("\"clock\": \"loggedinonly\""));
		assertTrue("pretty printed, because a person is going to read it",
			document.contains("\n"));

		assertFalse("no clock id", document.contains("\"id\""));
		assertFalse("no runs", document.contains("durationMillis"));
		assertFalse(document.contains("\"history\""));
	}

	@Test
	public void anExportCarriesOnlyTheTriggersItsClocksWaitFor()
	{
		library.add("Note herbs", "Use", "Tool Leprechaun");
		library.add("Rub the cloak", "Rub", "Ardougne cloak");
		library.add("Bank it", "Bank", "Bank chest");

		Routine herb = clock("a", "Herb run");
		herb.setStartTrigger(Trigger.saved("Note herbs"));
		herb.setStopTrigger(Trigger.saved("Bank it"));

		String document = ClockworkDocument.exportAll(GSON, Collections.singletonList(herb), library);

		assertTrue(document, document.contains("Note herbs"));
		assertTrue(document, document.contains("Bank it"));
		assertFalse("a trigger nothing in the document waits for is not in it",
			document.contains("Rub the cloak"));
	}

	@Test
	public void exportingOneClockCarriesOnlyThatClocksTriggers()
	{
		library.add("Note herbs", "Use", "Tool Leprechaun");
		library.add("Rub the cloak", "Rub", "Ardougne cloak");

		Routine herb = clock("a", "Herb run");
		herb.setStartTrigger(Trigger.saved("Note herbs"));

		Routine cloak = clock("b", "Ardougne run");
		cloak.setStartTrigger(Trigger.saved("Rub the cloak"));

		String document = ClockworkDocument.exportOne(GSON, herb, library);

		assertTrue(document, document.contains("Herb run"));
		assertFalse("the other clock is not in it", document.contains("Ardougne run"));
		assertTrue(document, document.contains("Note herbs"));
		assertFalse("nor is the other clock's trigger", document.contains("Rub the cloak"));

		ClockworkStorage.Saved back = ClockworkStorage.decodeAll(GSON, document);
		assertEquals(1, back.getRoutines().size());
		assertEquals(1, back.getLibrary().all().size());
	}

	/**
	 * A clock pointing at a trigger that is not in the library already does
	 * nothing. Writing the dangling name out would produce a document this
	 * plugin's own import refuses, which is a strange thing to hand somebody.
	 */
	@Test
	public void anExportedClockPointingAtNothingIsWrittenAsManual()
	{
		Routine herb = clock("a", "Herb run");
		herb.setStartTrigger(Trigger.saved("gone"));

		String document = ClockworkDocument.exportAll(GSON, Collections.singletonList(herb), library);
		assertFalse(document, document.contains("gone"));

		ClockworkDocument.Imported imported = ClockworkDocument.read(GSON, document, TriggerLibrary.empty());
		assertTrue(imported.getProblem(), imported.isOk());
		assertSame(Trigger.nothing(), imported.getAdded().get(0).getStartTrigger());
	}

	/**
	 * The whole point of the third trigger, end to end. A herb run that starts
	 * on the teleport, splits at the leprechaun, and stops at the bank has to
	 * arrive on somebody else's client waiting for the same three things, with
	 * the two library entries it names arriving with it.
	 */
	@Test
	public void aClockWithAllThreeTriggersMakesTheRoundTrip()
	{
		library.add("Note herbs", "Use", "Tool Leprechaun");
		library.add("Bank it", "Bank", "Bank chest");
		library.add("Rub the cloak", "Rub", "Ardougne cloak");

		Routine herb = clock("a", "Herb run");
		herb.setLapsEnabled(true);
		herb.setStartTrigger(Trigger.of(TriggerType.TELEPORT));
		herb.setLapTrigger(Trigger.saved("Note herbs"));
		herb.setStopTrigger(Trigger.saved("Bank it"));

		String document = ClockworkDocument.exportAll(GSON, Collections.singletonList(herb), library);
		assertFalse("a trigger nothing in the document waits for is still left out",
			document.contains("Rub the cloak"));

		ClockworkDocument.Imported imported = ClockworkDocument.read(GSON, document, TriggerLibrary.empty());
		assertTrue(imported.getProblem(), imported.isOk());

		Routine arrived = imported.getAdded().get(0);
		assertTrue("the splits came with it", arrived.isLapsEnabled());
		assertEquals(Trigger.of(TriggerType.TELEPORT), arrived.getStartTrigger());
		assertEquals(Trigger.saved("Note herbs"), arrived.getLapTrigger());
		assertEquals(Trigger.saved("Bank it"), arrived.getStopTrigger());

		assertEquals("both entries the clock names arrived, and only those two",
			2, imported.getLibrary().all().size());
		assertTrue(imported.getLibrary().matches(arrived.getLapTrigger(),
			TriggerEvent.menuClick("Use", "Tool Leprechaun")));
		assertTrue(imported.getLibrary().matches(arrived.getStopTrigger(),
			TriggerEvent.menuClick("Bank", "Bank chest")));
	}

	@Test
	public void anExportIsSomethingThisPluginCanReadBack()
	{
		library.add("Note herbs", "Use", "Tool Leprechaun");

		Routine herb = clock("a", "Herb run");
		herb.setMode(Mode.COUNT_DOWN);
		herb.setTargetMillis(360_000);
		herb.setStartTrigger(Trigger.saved("Note herbs"));

		String document = ClockworkDocument.exportAll(GSON, Collections.singletonList(herb), library);
		ClockworkStorage.Saved back = ClockworkStorage.decodeAll(GSON, document);

		Routine decoded = back.getRoutines().get(0);
		assertEquals("Herb run", decoded.getName());
		assertSame(Mode.COUNT_DOWN, decoded.getMode());
		assertEquals(360_000, decoded.getTargetMillis());
		assertNull("the id was left out", decoded.getId());
		assertTrue(decoded.historyOrEmpty().isEmpty());
		assertTrue(back.getLibrary().matches(decoded.getStartTrigger(),
			TriggerEvent.menuClick("Use", "Tool Leprechaun")));
	}

	@Test
	public void exportingNothingIsStillADocument()
	{
		assertTrue(ClockworkDocument.exportAll(GSON, null, null).contains("\"version\""));
		assertTrue(ClockworkDocument.exportOne(GSON, null, library).contains("\"version\""));
	}

	// Importing

	private static String document(String routines, String triggers)
	{
		return "{\"version\":1,\"triggers\":[" + triggers + "],\"routines\":[" + routines + "]}";
	}

	@Test
	public void importedClocksArriveWithFreshIdsAndNoRuns()
	{
		String json = document("{\"id\":\"a\",\"name\":\"Herb run\",\"mode\":\"countdown\","
			+ "\"targetMillis\":360000},{\"id\":\"a\",\"name\":\"Wine run\"}", "");

		ClockworkDocument.Imported imported = ClockworkDocument.read(GSON, json, library);

		assertTrue(imported.getProblem(), imported.isOk());
		assertEquals(2, imported.getAdded().size());

		Routine herb = imported.getAdded().get(0);
		Routine wine = imported.getAdded().get(1);

		assertNotNull(herb.getId());
		assertNotEquals("an id from the document is not reused", "a", herb.getId());
		assertNotEquals("and two clocks do not share one", herb.getId(), wine.getId());
		assertEquals("Herb run", herb.getName());
		assertSame(Mode.COUNT_DOWN, herb.getMode());
		assertEquals(360_000, herb.getTargetMillis());
		assertTrue("nobody else's personal bests come with it", herb.historyOrEmpty().isEmpty());
	}

	@Test
	public void anImportAddsRatherThanReplaces()
	{
		Routine mine = clock("mine", "Herb run");
		String json = document("{\"name\":\"Herb run\"}", "");

		ClockworkDocument.Imported imported = ClockworkDocument.read(GSON, json, library);

		assertTrue(imported.isOk());
		assertEquals("only the incoming clock is listed", 1, imported.getAdded().size());
		assertNotEquals(mine.getId(), imported.getAdded().get(0).getId());
		assertEquals("and the user's own clock was not touched", 1, mine.historyOrEmpty().size());
		assertEquals("Herb run", mine.getName());
	}

	/**
	 * The same trigger arriving twice is one trigger. Importing a document a
	 * second time must not double the library.
	 */
	@Test
	public void anIncomingTriggerIdenticalToOneAlreadyThereIsReused()
	{
		library.add("Note herbs", "Use", "Tool Leprechaun");

		String json = document("{\"name\":\"Herb run\",\"startTrigger\":"
				+ "{\"type\":\"custom\",\"ref\":\"Note herbs\"}}",
			"{\"name\":\"Note herbs\",\"option\":\"Use\",\"target\":\"Tool Leprechaun\"}");

		ClockworkDocument.Imported imported = ClockworkDocument.read(GSON, json, library);

		assertTrue(imported.getProblem(), imported.isOk());
		assertEquals("one wording, one entry", 1, imported.getLibrary().all().size());
		assertEquals(Trigger.saved("Note herbs"), imported.getAdded().get(0).getStartTrigger());
		assertTrue("nothing worth telling the user about", imported.getNotes().isEmpty());
	}

	/**
	 * The other half. A name that means something else to the user must not be
	 * overwritten, because that would change what their existing clocks wait
	 * for without anybody asking.
	 */
	@Test
	public void anIncomingTriggerThatOnlySharesANameIsNumberedAndTheRefsFollow()
	{
		library.add("Note herbs", "Use", "Tool Leprechaun");

		String json = document("{\"name\":\"Herb run\",\"startTrigger\":"
				+ "{\"type\":\"custom\",\"ref\":\"Note herbs\"}}",
			"{\"name\":\"Note herbs\",\"option\":\"Rub\",\"target\":\"Ardougne cloak\"}");

		ClockworkDocument.Imported imported = ClockworkDocument.read(GSON, json, library);

		assertTrue(imported.getProblem(), imported.isOk());
		assertEquals("neither was dropped", 2, imported.getLibrary().all().size());
		assertEquals("what the user already had is untouched",
			"Use", imported.getLibrary().byName("Note herbs").getOption());
		assertEquals("Rub", imported.getLibrary().byName("Note herbs (2)").getOption());

		assertEquals("and the incoming clock points at the one that arrived",
			Trigger.saved("Note herbs (2)"), imported.getAdded().get(0).getStartTrigger());
		assertTrue(imported.getLibrary().matches(imported.getAdded().get(0).getStartTrigger(),
			TriggerEvent.menuClick("Rub", "Ardougne cloak 4")));

		assertEquals(1, imported.getNotes().size());
		assertTrue(imported.getNotes().get(0), imported.getNotes().get(0).contains("Note herbs (2)"));
	}

	/**
	 * A clock naming a trigger the document does not define is refused rather
	 * than quietly resolved to Nothing. Such a clock sits in the panel saying
	 * it starts on something and never starts, which is worse than a refusal.
	 */
	@Test
	public void aClockNamingATriggerTheDocumentDoesNotHaveIsAnError()
	{
		String json = document("{\"name\":\"Herb run\",\"startTrigger\":"
			+ "{\"type\":\"custom\",\"ref\":\"Note herbs\"}}", "");

		ClockworkDocument.Imported imported = ClockworkDocument.read(GSON, json, library);

		assertFalse(imported.isOk());
		assertTrue(imported.getProblem(), imported.getProblem().contains("Herb run"));
		assertTrue(imported.getProblem(), imported.getProblem().contains("Note herbs"));
		assertTrue(imported.getAdded().isEmpty());
	}

	@Test
	public void aStopTriggerNamingSomethingMissingIsAnErrorToo()
	{
		String json = document("{\"name\":\"Herb run\",\"stopTrigger\":"
			+ "{\"type\":\"custom\",\"ref\":\"Bank it\"}}", "");

		ClockworkDocument.Imported imported = ClockworkDocument.read(GSON, json, library);

		assertFalse(imported.isOk());
		assertTrue(imported.getProblem(), imported.getProblem().contains("stops"));
		assertTrue(imported.getProblem(), imported.getProblem().contains("Bank it"));
	}

	@Test
	public void aLapTriggerNamingSomethingMissingIsAnErrorToo()
	{
		String json = document("{\"name\":\"Herb run\",\"lapsEnabled\":true,\"lapTrigger\":"
			+ "{\"type\":\"custom\",\"ref\":\"Note herbs\"}}", "");

		ClockworkDocument.Imported imported = ClockworkDocument.read(GSON, json, library);

		assertFalse(imported.isOk());
		assertTrue(imported.getProblem(), imported.getProblem().contains("takes a split"));
		assertTrue(imported.getProblem(), imported.getProblem().contains("Note herbs"));
		assertTrue(imported.getAdded().isEmpty());
	}

	@Test
	public void malformedJsonIsRefusedWithSomethingReadable()
	{
		for (String bad : Arrays.asList("", "   ", "not json at all", "{\"version\":1,",
			"[1,2,3]", "null"))
		{
			ClockworkDocument.Imported imported = ClockworkDocument.read(GSON, bad, library);

			assertFalse("expected a refusal for " + bad, imported.isOk());
			assertNotNull(imported.getProblem());
			assertFalse("a stack trace is not a message",
				imported.getProblem().contains("com.google.gson"));
			assertFalse(imported.getProblem().contains("java.lang"));
			assertTrue("a refusal ends in a sentence", imported.getProblem().length() > 10);
		}
	}

	@Test
	public void aDocumentWithNoClockListIsRefused()
	{
		ClockworkDocument.Imported imported = ClockworkDocument.read(GSON,
			"{\"version\":1,\"triggers\":[]}", library);

		assertFalse(imported.isOk());
		assertTrue(imported.getProblem(), imported.getProblem().contains("clocks"));
	}

	@Test
	public void aDocumentFromANewerClockworkIsRefusedByName()
	{
		ClockworkDocument.Imported imported = ClockworkDocument.read(GSON,
			"{\"version\":99,\"routines\":[{\"name\":\"Herb run\"}]}", library);

		assertFalse(imported.isOk());
		assertTrue(imported.getProblem(), imported.getProblem().contains("99"));
		assertTrue(imported.getProblem(), imported.getProblem().contains("newer"));
	}

	/**
	 * A document that says it is version 0, which is what a hand written one
	 * with no stamp on it looks like, is read rather than refused. Only a
	 * version above the one this build writes is a refusal, because that is the
	 * only one that could hold a shape this build has never seen.
	 */
	@Test
	public void aDocumentWithNoVersionStampIsStillRead()
	{
		ClockworkDocument.Imported imported = ClockworkDocument.read(GSON,
			"{\"routines\":[{\"name\":\"Herb run\",\"mode\":\"countdown\"}]}", library);

		assertTrue(imported.getProblem(), imported.isOk());
		assertEquals(1, imported.getAdded().size());
		assertSame(Mode.COUNT_DOWN, imported.getAdded().get(0).getMode());
	}

	/**
	 * A run that somehow reached a document is still not imported. The field is
	 * transient so an export never writes one, but a hand written document can
	 * say anything, and somebody else's personal bests are not something to
	 * take on trust.
	 */
	@Test
	public void runsWrittenIntoADocumentByHandDoNotArrive()
	{
		String json = document("{\"name\":\"Herb run\","
			+ "\"history\":[{\"startedAtEpochMillis\":1,\"finishedAtEpochMillis\":2,"
			+ "\"durationMillis\":1,\"status\":\"completed\",\"laps\":[]}]}", "");

		ClockworkDocument.Imported imported = ClockworkDocument.read(GSON, json, library);

		assertTrue(imported.getProblem(), imported.isOk());
		assertTrue("the field is transient, so nothing binds into it",
			imported.getAdded().get(0).historyOrEmpty().isEmpty());
	}

	// Applying an edited document

	private List<Routine> mine()
	{
		Routine quick = clock(Routine.QUICK_ID, Routine.QUICK_NAME);
		Routine herb = clock("a", "Herb run");
		herb.setTargetMillis(1000);
		Routine wine = clock("b", "Wine run");
		return Arrays.asList(quick, herb, wine);
	}

	@Test
	public void anEditedDocumentMatchesByNameAndKeepsTheIdAndTheRuns()
	{
		List<Routine> existing = mine();
		String json = document("{\"name\":\"Quick\"},{\"name\":\"Herb run\",\"targetMillis\":360000,"
			+ "\"mode\":\"countdown\"},{\"name\":\"Wine run\"}", "");

		ClockworkDocument.Applied applied = ClockworkDocument.readEdited(GSON, json, existing, library);

		assertTrue(applied.getProblem(), applied.isOk());
		assertEquals(3, applied.getRoutines().size());
		assertTrue(applied.getRemoved().isEmpty());
		assertTrue(applied.getAdded().isEmpty());

		Routine herb = applied.getRoutines().get(1);
		assertEquals("the matched clock keeps its id, so its timer box stays put",
			"a", herb.getId());
		assertEquals("and its runs", 1, herb.historyOrEmpty().size());
		assertEquals("and the lifetime count behind its all time average, which is the one part of a"
				+ " clock that cannot be worked out again from the runs that are left",
			214, herb.totalsOrZero().getCompletedRuns());
		assertEquals(214L * 300_000L, herb.totalsOrZero().getCompletedMillis());
		assertEquals("while the settings come from the document", 360_000, herb.getTargetMillis());
		assertSame(Mode.COUNT_DOWN, herb.getMode());

		assertEquals("case does not stop a match", Routine.QUICK_ID, applied.getRoutines().get(0).getId());
	}

	@Test
	public void aNameNotAlreadyThereBecomesANewClock()
	{
		List<Routine> existing = mine();
		String json = document("{\"name\":\"Quick\"},{\"name\":\"Herb run\"},{\"name\":\"Wine run\"},"
			+ "{\"name\":\"Birdhouse run\"}", "");

		ClockworkDocument.Applied applied = ClockworkDocument.readEdited(GSON, json, existing, library);

		assertTrue(applied.isOk());
		assertEquals(4, applied.getRoutines().size());
		assertEquals(Collections.singletonList("Birdhouse run"), applied.getAdded());

		Routine added = applied.getRoutines().get(3);
		assertNotNull(added.getId());
		assertTrue(added.historyOrEmpty().isEmpty());
		assertTrue("a clock that is new here has run nothing and has counted nothing",
			added.totalsOrZero().isEmpty());
	}

	/**
	 * The removal, and the reason it is reported rather than done. A user who
	 * pastes a document that is missing a clock should be told which clock is
	 * about to go before it goes.
	 */
	@Test
	public void aClockTheDocumentDoesNotMentionIsReportedAsARemoval()
	{
		List<Routine> existing = mine();
		String json = document("{\"name\":\"Quick\"},{\"name\":\"Herb run\"}", "");

		ClockworkDocument.Applied applied = ClockworkDocument.readEdited(GSON, json, existing, library);

		assertTrue(applied.isOk());
		assertEquals(Collections.singletonList("Wine run"), applied.getRemoved());
		assertEquals("and the plan says what is left", 2, applied.getRoutines().size());
		assertEquals("nothing was actually removed by asking", 3, existing.size());
	}

	/**
	 * Renaming a clock inside the document reads as a delete and an add,
	 * because the match is by name. The renamed clock therefore arrives with no
	 * runs. This is the sharp edge of the operation and it is written down
	 * rather than discovered.
	 */
	@Test
	public void renamingAClockInTheDocumentOrphansItsRuns()
	{
		List<Routine> existing = mine();
		String json = document("{\"name\":\"Quick\"},{\"name\":\"Herbiboar run\"},{\"name\":\"Wine run\"}", "");

		ClockworkDocument.Applied applied = ClockworkDocument.readEdited(GSON, json, existing, library);

		assertTrue(applied.isOk());
		assertEquals(Collections.singletonList("Herb run"), applied.getRemoved());
		assertEquals(Collections.singletonList("Herbiboar run"), applied.getAdded());

		Routine renamed = applied.getRoutines().get(1);
		assertEquals("Herbiboar run", renamed.getName());
		assertNotEquals("a", renamed.getId());
		assertTrue("which is what orphaning the runs means", renamed.historyOrEmpty().isEmpty());
	}

	/**
	 * The built in clock is always there and cannot be deleted, so saying it
	 * would be removed would be a lie.
	 */
	@Test
	public void theBuiltInClockIsNeverReportedAsARemoval()
	{
		List<Routine> existing = mine();
		String json = document("{\"name\":\"Herb run\"},{\"name\":\"Wine run\"}", "");

		ClockworkDocument.Applied applied = ClockworkDocument.readEdited(GSON, json, existing, library);

		assertTrue(applied.isOk());
		assertEquals("only the ordinary clocks can go", Collections.emptyList(), applied.getRemoved());
		assertEquals(3, applied.getRoutines().size());
		assertEquals("and it is still at the front", Routine.QUICK_ID, applied.getRoutines().get(0).getId());
		assertEquals(1, applied.getNotes().size());
	}

	@Test
	public void anEditedDocumentIsCheckedTheSameWayAnImportIs()
	{
		ClockworkDocument.Applied applied = ClockworkDocument.readEdited(GSON, "not json", mine(), library);

		assertFalse(applied.isOk());
		assertNotNull(applied.getProblem());
		assertTrue(applied.getRoutines().isEmpty());
		assertTrue(applied.getRemoved().isEmpty());

		ClockworkDocument.Applied tooNew = ClockworkDocument.readEdited(GSON,
			"{\"version\":99,\"routines\":[]}", mine(), library);
		assertFalse(tooNew.isOk());
		assertTrue(tooNew.getProblem(), tooNew.getProblem().contains("newer"));
	}

	@Test
	public void anEditedDocumentFoldsInItsTriggersTheSameWayAnImportDoes()
	{
		library.add("Note herbs", "Use", "Tool Leprechaun");

		String json = document("{\"name\":\"Herb run\",\"startTrigger\":"
				+ "{\"type\":\"custom\",\"ref\":\"Note herbs\"}}",
			"{\"name\":\"Note herbs\",\"option\":\"Rub\",\"target\":\"Ardougne cloak\"}");

		ClockworkDocument.Applied applied = ClockworkDocument.readEdited(GSON, json,
			Collections.singletonList(clock("a", "Herb run")), library);

		assertTrue(applied.getProblem(), applied.isOk());
		assertEquals(2, applied.getLibrary().all().size());
		assertEquals(Trigger.saved("Note herbs (2)"), applied.getRoutines().get(0).getStartTrigger());
		assertEquals("the user's library object itself is not edited by asking", 1, library.all().size());
	}

	@Test
	public void anEmptyDocumentWouldRemoveEverythingAndSaysSo()
	{
		List<Routine> existing = mine();

		ClockworkDocument.Applied applied = ClockworkDocument.readEdited(GSON,
			document("", ""), existing, library);

		assertTrue(applied.isOk());
		assertEquals(Arrays.asList("Herb run", "Wine run"), applied.getRemoved());
		assertEquals("with the built in clock left standing", 1, applied.getRoutines().size());
	}
}

package com.clockwork;

import com.clockwork.core.Routine;
import com.clockwork.core.RoutineController;
import com.clockwork.overlay.RoutineOverlay;
import com.google.inject.AbstractModule;
import com.google.inject.Guice;
import com.google.inject.util.Providers;
import java.awt.event.KeyEvent;
import java.lang.reflect.InvocationTargetException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.client.Notifier;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.config.Keybind;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayManager;
import org.mockito.ArgumentCaptor;
import static org.mockito.Mockito.atLeast;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;

/**
 * Stands the whole plugin up with test doubles in place of the client, so the
 * wiring can be driven and read in an ordinary JUnit run.
 *
 * <p>Our engineering guide calls this level two, and calls it the level
 * everybody skips and the one where the bugs are. Everything else in
 * {@code src/test} tests {@code com.clockwork.core}, which is pure and easy.
 * Nothing tested the layer that turns a profile change into a reload, and that
 * is the layer every bug this plugin has shipped lived in.
 *
 * <h2>How to use it</h2>
 *
 * <pre>
 * harness = new ClockworkHarness();
 * harness.storage.setStored(routine("herb", "Herb run"));
 * harness.startUp();
 * harness.onEdt(() -&gt; harness.controller().start("herb"));
 * assertTrue(harness.controller().isRunning("herb"));
 * </pre>
 *
 * <p>Set the world up on {@link #storage} and {@link #config} before
 * {@link #startUp()}, because the plugin reads both once as it comes up. Drive
 * it afterwards through the real entry points, the {@code on...} event methods
 * and the controller on the thread it is confined to, rather than by reaching
 * inside. Read the result back off {@link #storage}, off the mocks, or off
 * {@link #controller()}.
 *
 * <h2>What is a mock and what is hand written, and why</h2>
 *
 * <p>Everything that could be written by hand was. {@link FakeClockworkConfig},
 * {@link FakeClockworkStorage}, {@link BlockingClientThread} and
 * {@link SilentAudioPlayer} are all plain classes with no library behind them,
 * and they read better for it. The last two work by subclassing, because
 * {@code ClientThread} and {@code AudioPlayer} each have a public no argument
 * constructor and no final method in the way.
 *
 * <p>The six below are mocked because they cannot be anything else.
 * {@code ClientToolbar}, {@code ChatMessageManager}, {@code OverlayManager},
 * {@code KeyManager} and {@code Notifier} are concrete classes with private
 * constructors, so they cannot be built, cannot be subclassed, and cannot be
 * proxied. The plugin injects each one as a class rather than an interface, so
 * there is no seam to use instead. {@code Client} is mocked as well, because it
 * is far too wide to write out for the handful of methods the plugin calls.
 *
 * <h2>The client thread</h2>
 *
 * <p>{@link BlockingClientThread} runs client thread work inline. Without it
 * anything the plugin defers there never runs at all in a test, since the queue
 * behind the real one is drained by a game engine that is not present. The
 * notification is reached that way, so it is the reason this exists.
 *
 * <h2>Threads</h2>
 *
 * <p>The plugin's work lands on the Swing event dispatch thread, and
 * {@link #flushEdt()} waits for that thread to empty, so a test can assert
 * immediately after acting instead of sleeping and hoping.
 *
 * <h2>No reflection</h2>
 *
 * <p>{@link #controller()} used to read a private field, because the agent that
 * wrote this harness was not allowed to touch the main source. The plugin now
 * carries a package private {@code getController()} and this reads that
 * instead, so nothing here reaches through a private wall.
 * {@code ClockworkConfigTest} and {@code ClockworkSubscriptionsTest} do still
 * use reflection, over the plugin's own declared methods rather than its state,
 * and each carries the note saying why that is allowed in a test source set.
 */
class ClockworkHarness
{
	final ClockworkPlugin plugin = new ClockworkPlugin();

	final FakeClockworkConfig config = new FakeClockworkConfig();
	final FakeClockworkStorage storage = new FakeClockworkStorage();
	final BlockingClientThread clientThread = new BlockingClientThread();
	final SilentAudioPlayer audioPlayer = new SilentAudioPlayer();

	final Client client = mock(Client.class);
	final ClientToolbar clientToolbar = mock(ClientToolbar.class);
	final ChatMessageManager chatMessageManager = mock(ChatMessageManager.class);
	final OverlayManager overlayManager = mock(OverlayManager.class);
	final Notifier notifier = mock(Notifier.class);
	final KeyManager keyManager = mock(KeyManager.class);

	/**
	 * Stands in for RuneLite's shared background executor. A plain mock swallows
	 * the one disk append the plugin hands it per finished run, so a harness test
	 * never writes to the real RuneLite directory. The append itself is covered
	 * directly in {@code HistoryFileTest}.
	 */
	final ScheduledExecutorService executor = mock(ScheduledExecutorService.class);

	/**
	 * A key event needs a component to have come from. Never shown, never given
	 * a peer, so it is safe on a headless build.
	 */
	private final JPanel keySource = new JPanel();

	/**
	 * Everything the plugin logs while this harness is up, read back by
	 * {@link #newDiagnosticsText()}.
	 */
	private final LogCapture logs = new LogCapture();

	private boolean started;

	ClockworkHarness()
	{
		// Bound through providers rather than toInstance, because toInstance
		// asks Guice to inject the instance's own members and these doubles
		// stand in for classes whose members we have no way of satisfying.
		Guice.createInjector(new AbstractModule()
		{
			@Override
			protected void configure()
			{
				bind(Client.class).toProvider(Providers.of(client));
				bind(ClockworkConfig.class).toProvider(Providers.of(config));
				bind(ClockworkStorage.class).toProvider(Providers.of(storage));
				bind(ClientToolbar.class).toProvider(Providers.of(clientToolbar));
				bind(ChatMessageManager.class).toProvider(Providers.of(chatMessageManager));
				bind(OverlayManager.class).toProvider(Providers.of(overlayManager));
				bind(ClientThread.class).toProvider(Providers.of(clientThread));
				bind(Notifier.class).toProvider(Providers.of(notifier));
				bind(AudioPlayer.class).toProvider(Providers.of(audioPlayer));
				bind(KeyManager.class).toProvider(Providers.of(keyManager));
				bind(ScheduledExecutorService.class).toProvider(Providers.of(executor));
			}
		}).injectMembers(plugin);
	}

	// Lifecycle

	void startUp()
	{
		plugin.startUp();
		started = true;
		flushEdt();
	}

	/**
	 * Reverses {@link #startUp()}, and is safe to call twice so a test can shut
	 * down explicitly and still leave the teardown in place.
	 *
	 * <p>What was logged stays readable afterwards, so a test can shut down and
	 * then read what the shutdown wrote.
	 */
	void shutDown()
	{
		if (started)
		{
			started = false;
			plugin.shutDown();
			flushEdt();
		}
		logs.close();
	}

	// Driving it

	/**
	 * Presses and releases a key, through the listeners the plugin really
	 * registered with the key manager.
	 *
	 * <p>The event goes to all three, and the two that do not match it ignore
	 * it, which is how the client behaves and is the point of going this way
	 * round rather than calling one listener directly. The release matters,
	 * because {@code HotkeyListener} latches on press and will not fire twice
	 * without one.
	 *
	 * <p>Note the direction. These are events the client already delivered,
	 * handed to listeners that read them. Nothing built here is ever given back
	 * to the client, which is the same thing the plugin itself does not do.
	 */
	void pressHotkey(Keybind keybind)
	{
		final long when = System.currentTimeMillis();
		final KeyEvent pressed = new TypedKeyEvent(keySource, KeyEvent.KEY_PRESSED, when,
			keybind.getKeyCode());
		final KeyEvent released = new TypedKeyEvent(keySource, KeyEvent.KEY_RELEASED, when + 1,
			keybind.getKeyCode());

		for (KeyListener listener : registeredKeyListeners())
		{
			listener.keyPressed(pressed);
			listener.keyReleased(released);
		}
		flushEdt();
	}

	/**
	 * Runs something on the event dispatch thread and waits for it, then waits
	 * for anything it queued behind itself. Use it for the setup a test does
	 * through the controller, so it happens on the thread the plugin confines
	 * the controller to.
	 */
	void onEdt(Runnable body)
	{
		try
		{
			SwingUtilities.invokeAndWait(body);
		}
		catch (InterruptedException ex)
		{
			Thread.currentThread().interrupt();
			throw new AssertionError("interrupted waiting for the event dispatch thread", ex);
		}
		catch (InvocationTargetException ex)
		{
			throw new AssertionError("the event dispatch thread threw", ex.getCause());
		}
		flushEdt();
	}

	/**
	 * Waits until the event dispatch thread has nothing left to do.
	 *
	 * <p>Everything the plugin defers goes through {@code invokeLater}, which
	 * is a queue, so an empty task that gets to the front is proof that
	 * everything queued before it has run. It is done more than once because a
	 * task is allowed to queue another one, and the plugin's refresh does.
	 */
	void flushEdt()
	{
		for (int round = 0; round < 4; round++)
		{
			try
			{
				SwingUtilities.invokeAndWait(() ->
				{
				});
			}
			catch (InterruptedException ex)
			{
				Thread.currentThread().interrupt();
				throw new AssertionError("interrupted waiting for the event dispatch thread", ex);
			}
			catch (InvocationTargetException ex)
			{
				throw new AssertionError("the event dispatch thread threw", ex.getCause());
			}
		}
	}

	// Reading it back

	/**
	 * The live controller, through the plugin's own package private accessor.
	 * Read from it rather than writing through it.
	 */
	RoutineController controller()
	{
		return plugin.getController();
	}

	/**
	 * Every side panel button the plugin has put on the toolbar, in order.
	 */
	List<NavigationButton> addedNavigation()
	{
		final ArgumentCaptor<NavigationButton> captor = ArgumentCaptor.forClass(NavigationButton.class);
		verify(clientToolbar, atLeast(0)).addNavigation(captor.capture());
		return captor.getAllValues();
	}

	/**
	 * Every side panel button the plugin has taken back off the toolbar. One
	 * left behind is a button that opens a panel nothing is refreshing.
	 */
	List<NavigationButton> removedNavigation()
	{
		final ArgumentCaptor<NavigationButton> captor = ArgumentCaptor.forClass(NavigationButton.class);
		verify(clientToolbar, atLeast(0)).removeNavigation(captor.capture());
		return captor.getAllValues();
	}

	/**
	 * Every overlay the plugin has put on the overlay manager, in order. One
	 * timer box per clock that is allowed one, plus the screen flash, which is
	 * added once at start up and is not tied to a clock.
	 */
	List<Overlay> addedOverlays()
	{
		final ArgumentCaptor<Overlay> captor = ArgumentCaptor.forClass(Overlay.class);
		verify(overlayManager, atLeast(0)).add(captor.capture());
		return captor.getAllValues();
	}

	/**
	 * Every overlay the plugin has taken back off the overlay manager. One left
	 * behind keeps drawing forever with the plugin switched off, because
	 * stopping a plugin never touches the overlay manager.
	 */
	List<Overlay> removedOverlays()
	{
		final ArgumentCaptor<Overlay> captor = ArgumentCaptor.forClass(Overlay.class);
		verify(overlayManager, atLeast(0)).remove(captor.capture());
		return captor.getAllValues();
	}

	/**
	 * The timer boxes alone, which is what a test about a clock having a box
	 * wants to count.
	 *
	 * <p>Separate from {@link #addedOverlays()} because the screen flash is
	 * added at start up whether or not anything is running, so counting every
	 * overlay would answer a question about the alert path in a test about the
	 * boxes. The teardown test still reads the whole set, since what has to
	 * come back off is everything that went on.
	 */
	List<Overlay> addedTimerBoxes()
	{
		return timerBoxesIn(addedOverlays());
	}

	List<Overlay> removedTimerBoxes()
	{
		return timerBoxesIn(removedOverlays());
	}

	/**
	 * Every key listener the plugin has registered, which should be the three
	 * hotkeys and nothing else.
	 */
	List<KeyListener> registeredKeyListeners()
	{
		final ArgumentCaptor<KeyListener> captor = ArgumentCaptor.forClass(KeyListener.class);
		verify(keyManager, atLeast(0)).registerKeyListener(captor.capture());
		return captor.getAllValues();
	}

	/**
	 * Every key listener the plugin has given back. One left registered outlives
	 * the plugin that made it and keeps acting on key presses with the plugin
	 * switched off.
	 */
	List<KeyListener> unregisteredKeyListeners()
	{
		final ArgumentCaptor<KeyListener> captor = ArgumentCaptor.forClass(KeyListener.class);
		verify(keyManager, atLeast(0)).unregisterKeyListener(captor.capture());
		return captor.getAllValues();
	}

	private static List<Overlay> timerBoxesIn(List<Overlay> overlays)
	{
		final List<Overlay> boxes = new ArrayList<>();
		for (Overlay overlay : overlays)
		{
			if (overlay instanceof RoutineOverlay)
			{
				boxes.add(overlay);
			}
		}
		return boxes;
	}

	/**
	 * Everything the plugin has logged since this harness was built.
	 *
	 * <p>Worth having because the plugin swallows on purpose. Every entry point
	 * is wrapped in {@code Diagnostics.guard}, which catches and records rather
	 * than throwing, so a wiring bug shows up as a test that fails for a reason
	 * that makes no sense until you read this. It is also where the profile
	 * switch says what the switch cost, which is the only outside evidence that
	 * a run in progress was dropped rather than carried across.
	 */
	String newDiagnosticsText()
	{
		return logs.text();
	}

	/**
	 * A clock, made the way the plugin's own storage would hand one over.
	 */
	static Routine routine(String id, String name)
	{
		return new Routine(id, name);
	}

	/**
	 * A key event that answers for its own extended key code.
	 *
	 * <p>{@code Keybind.matches} compares the extended key code, which the
	 * toolkit fills in through an internal accessor a test cannot reach, so on
	 * an event built here it stays zero and every keybind fails to match.
	 *
	 * <p>Overriding the getter is the honest version of what the toolkit does,
	 * and it keeps the test on the real matching path instead of skipping it.
	 * The alternative, reaching into the private field, needs the JDK's own
	 * module to be prised open and would break on a future release.
	 */
	private static final class TypedKeyEvent extends KeyEvent
	{
		private TypedKeyEvent(JPanel source, int id, long when, int keyCode)
		{
			super(source, id, when, 0, keyCode, KeyEvent.CHAR_UNDEFINED);
		}

		@Override
		public int getExtendedKeyCode()
		{
			return getKeyCode();
		}
	}
}

package com.clockwork;

import com.clockwork.core.Lap;
import com.clockwork.core.Routine;
import com.clockwork.core.Run;
import com.clockwork.core.Status;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The recorded runs going out to a key per clock and coming back.
 *
 * <p>This is the only copy of a user's runs there is. The plugin writes no
 * file, keeps no backup, and the settings blob holds none of this, so whatever
 * {@code encodeRuns} drops on the way out or {@code decodeRuns} drops on the
 * way back is gone for good and gone quietly. That is why these methods are
 * tested here at the encoder rather than only through the wiring test, which
 * can only say that a save and a load agreed with each other.
 *
 * <p>{@code decodeHistory} is tested here too. It reads the one key every
 * clock's runs used to share, which no current build writes, and it is what
 * carries a user's runs across the update that split them up.
 *
 * <p>{@code merge} is tested here for the same reason. It is what decides
 * whether a run that is under both keys is one run or two, and it is asked that
 * on every load, so an answer that is wrong in one direction loses runs and an
 * answer that is wrong in the other doubles a user's history every time they
 * start the client.
 *
 * <p>{@link HistoryKeysTest} is the other half, covering which keys are written
 * and taken away. This file is about what is inside one.
 *
 * <p>The damaged input cases below assert what the code actually does, not what
 * it ought to do. Where a kind of damage costs one clock its runs, that is
 * written down as the behaviour so that a later change cannot quietly make the
 * loss wider without a test going red.
 *
 * <p>A plain Gson is built here for the same reason as in
 * {@link ClockworkStorageTest}, because there is no injector in a test and the
 * plugin is handed a stock one.
 */
public class ClockworkHistoryStorageTest
{
	private static final Gson GSON = new Gson();

	/**
	 * The one that matters most. Three clocks, each with runs of its own, each
	 * run carrying every field a {@link Run} has, through a real encode, a real
	 * decode, and a real attach.
	 *
	 * <p>Every field is asserted rather than a count, because a decode that
	 * hands back the right number of runs with the wrong numbers in them is the
	 * failure that would never be noticed.
	 */
	@Test
	public void everyClockKeepsEveryRunAndEveryLapThroughARoundTrip()
	{
		Routine herb = new Routine("herb-id", "Herb run");
		herb.setHistory(new ArrayList<>(Arrays.asList(
			run(1000L, 4000L, 3000L, Status.COMPLETED,
				new Lap("Ardougne", 1200L, 1200L),
				new Lap("Catherby", 3000L, 1800L)),
			run(9000L, 12500L, 3500L, Status.ABANDONED,
				new Lap("Ardougne", 3500L, 3500L)))));

		Routine tree = new Routine("tree-id", "Tree run");
		tree.setHistory(new ArrayList<>(Arrays.asList(
			run(50L, 150L, 100L, Status.COMPLETED,
				new Lap(null, 40L, 40L),
				new Lap("Falador", 70L, 30L),
				new Lap("Taverley", 100L, 30L)))));

		Routine quick = new Routine(Routine.QUICK_ID, Routine.QUICK_NAME);
		quick.setHistory(new ArrayList<>(Arrays.asList(
			run(7L, 8L, 1L, Status.COMPLETED))));

		List<Routine> loaded = reload(Arrays.asList(herb, tree, quick));

		assertEquals(2, loaded.get(0).historyOrEmpty().size());
		assertEquals(1, loaded.get(1).historyOrEmpty().size());
		assertEquals(1, loaded.get(2).historyOrEmpty().size());

		// The order of the runs is the order they were recorded in, which is
		// what every statistic and every list in the panel reads off.
		Run first = loaded.get(0).historyOrEmpty().get(0);
		assertEquals(1000L, first.getStartedAtEpochMillis());
		assertEquals(4000L, first.getFinishedAtEpochMillis());
		assertEquals(3000L, first.getDurationMillis());
		assertSame(Status.COMPLETED, first.getStatus());
		assertTrue(first.isCompleted());
		assertEquals(2, first.lapsOrEmpty().size());
		assertEquals("Ardougne", first.lapsOrEmpty().get(0).getLabel());
		assertEquals(1200L, first.lapsOrEmpty().get(0).getSplitMillis());
		assertEquals(1200L, first.lapsOrEmpty().get(0).getLapMillis());
		assertEquals("Catherby", first.lapsOrEmpty().get(1).getLabel());
		assertEquals(3000L, first.lapsOrEmpty().get(1).getSplitMillis());
		assertEquals(1800L, first.lapsOrEmpty().get(1).getLapMillis());

		Run second = loaded.get(0).historyOrEmpty().get(1);
		assertEquals(9000L, second.getStartedAtEpochMillis());
		assertEquals(12500L, second.getFinishedAtEpochMillis());
		assertEquals(3500L, second.getDurationMillis());
		assertSame(Status.ABANDONED, second.getStatus());
		assertFalse(second.isCompleted());
		assertEquals(1, second.lapsOrEmpty().size());

		// A lap with no label had no label, and must not come back with one
		// invented, because the panel prints whatever is there.
		Run treeRun = loaded.get(1).historyOrEmpty().get(0);
		assertEquals(3, treeRun.lapsOrEmpty().size());
		assertNull(treeRun.lapsOrEmpty().get(0).getLabel());
		assertEquals(40L, treeRun.lapsOrEmpty().get(0).getSplitMillis());
		assertEquals("Taverley", treeRun.lapsOrEmpty().get(2).getLabel());
		assertEquals(100L, treeRun.lapsOrEmpty().get(2).getSplitMillis());
		assertEquals(30L, treeRun.lapsOrEmpty().get(2).getLapMillis());

		Run quickRun = loaded.get(2).historyOrEmpty().get(0);
		assertEquals(7L, quickRun.getStartedAtEpochMillis());
		assertEquals(8L, quickRun.getFinishedAtEpochMillis());
		assertEquals(1L, quickRun.getDurationMillis());
	}

