	/**
	 * One unreadable run in the middle of a real history. The rest of that
	 * clock's runs survive, they survive in the order they were recorded in,
	 * and the clocks either side of it are untouched.
	 *
	 * <p>This is the shape the loss actually takes on a user's config, where a
	 * clock holds fifty runs and one of them is damaged.
	 */
	@Test
	public void oneUnreadableRunCostsOneRunAndTheSurvivorsKeepTheirOrder()
	{
		String blob = "{\"tree-id\":[{\"durationMillis\":11}],"
			+ "\"bad-id\":[{\"durationMillis\":1},{\"durationMillis\":{}},"
			+ "{\"durationMillis\":3},{\"durationMillis\":4}],"
			+ "\"herb-id\":[{\"durationMillis\":7},{\"durationMillis\":8}]}";

		Map<String, List<Run>> decoded = ClockworkStorage.decodeHistory(GSON, blob);

		assertEquals(3, decoded.size());

		List<Run> salvaged = decoded.get("bad-id");
		assertEquals(3, salvaged.size());
		assertEquals(1L, salvaged.get(0).getDurationMillis());
		assertEquals(3L, salvaged.get(1).getDurationMillis());
		assertEquals(4L, salvaged.get(2).getDurationMillis());

		assertEquals(1, decoded.get("tree-id").size());
		assertEquals(11L, decoded.get("tree-id").get(0).getDurationMillis());
		assertEquals(2, decoded.get("herb-id").size());
		assertEquals(7L, decoded.get("herb-id").get(0).getDurationMillis());
		assertEquals(8L, decoded.get("herb-id").get(1).getDurationMillis());
	}

