	// Runs under both keys at once, brought together

	/**
	 * The plain case. Each key holds a run the other does not, and both
	 * survive, oldest first.
	 */
	@Test
	public void aRunUnderEitherKeyAloneIsKept()
	{
		List<Run> merged = ClockworkStorage.merge(
			Collections.singletonList(run(1000L, 2000L, 1000L, Status.COMPLETED)),
			Collections.singletonList(run(3000L, 3900L, 900L, Status.COMPLETED)));

		assertEquals(2, merged.size());
		assertEquals(1000L, merged.get(0).getStartedAtEpochMillis());
		assertEquals(3000L, merged.get(1).getStartedAtEpochMillis());
	}

	/**
	 * The other direction, and the one that matters more, because this is asked
	 * on every load. A run that is under both keys is one run the user did and
	 * has to come back once however many times the question is asked.
	 */
	@Test
	public void aRunUnderBothKeysIsKeptOnce()
	{
		List<Run> merged = ClockworkStorage.merge(
			Arrays.asList(run(1000L, 2000L, 1000L, Status.COMPLETED),
				run(3000L, 3900L, 900L, Status.COMPLETED)),
			Collections.singletonList(run(3000L, 3900L, 900L, Status.COMPLETED)));

		assertEquals("the same run under both keys came back twice, so a history grows by a copy of"
				+ " itself on every load", 2, merged.size());

		// And again, over its own answer, which is what the next load does.
		assertEquals(2, ClockworkStorage.merge(merged,
			Collections.singletonList(run(3000L, 3900L, 900L, Status.COMPLETED))).size());
	}

	/**
	 * What makes two runs the same run is when it started, when it ended, and
	 * how long it took, all three. Two runs of one clock cannot agree on all of
	 * them, so a match is one run written to both keys.
	 *
	 * <p>The start alone is not enough, which is what this pins. Every run in a
	 * blob that carries no times reads as having started at zero, and folding
	 * those into one run would take a user's whole history down to a single
	 * entry.
	 */
	@Test
	public void runsThatShareAStartTimeAndNothingElseAreStillTwoRuns()
	{
		List<Run> merged = ClockworkStorage.merge(Collections.emptyList(),
			Arrays.asList(run(0L, 0L, 1200L, Status.COMPLETED),
				run(0L, 0L, 1300L, Status.COMPLETED)));

		assertEquals("a stored blob carrying no times folded into one run", 2, merged.size());
		assertEquals(1200L, merged.get(0).getDurationMillis());
		assertEquals(1300L, merged.get(1).getDurationMillis());
	}

	/**
	 * The order is by when each run started, whichever key it came off, because
	 * everything that reads a clock's runs reads them in recorded order. The
	 * newest run is the one at the end, and appending a key's worth of older
	 * runs after a newer one would quietly move it.
	 */
	@Test
	public void theRunsComeBackOldestFirstWhicheverKeyTheyWereUnder()
	{
		List<Run> merged = ClockworkStorage.merge(
			Collections.singletonList(run(5000L, 5500L, 500L, Status.COMPLETED)),
			Arrays.asList(run(9000L, 9100L, 100L, Status.COMPLETED),
				run(1000L, 1400L, 400L, Status.COMPLETED)));

		assertEquals(Arrays.asList(1000L, 5000L, 9000L),
			Arrays.asList(merged.get(0).getStartedAtEpochMillis(),
				merged.get(1).getStartedAtEpochMillis(),
				merged.get(2).getStartedAtEpochMillis()));
	}

	/**
	 * A clock with nothing on its own key yet, which is every clock of a user
	 * upgrading for the first time. What the old key holds comes back in the
	 * order it was stored in.
	 */
	@Test
	public void aClockWithNothingOnItsOwnKeyGetsTheOldKeysRunsInOrder()
	{
		List<Run> merged = ClockworkStorage.merge(null,
			Arrays.asList(run(0L, 0L, 1200L, Status.COMPLETED),
				run(0L, 0L, 1300L, Status.COMPLETED)));

		assertEquals(2, merged.size());
		assertEquals(1200L, merged.get(0).getDurationMillis());
		assertEquals(1300L, merged.get(1).getDurationMillis());
	}

	/**
	 * Nothing under the old key for this clock, so the clock's own runs come
	 * back as they were and the caller has nothing to write.
	 */
	@Test
	public void aClockTheOldKeySaysNothingAboutIsHandedBackUnchanged()
	{
		List<Run> stored = Arrays.asList(run(1000L, 2000L, 1000L, Status.COMPLETED),
			run(3000L, 3900L, 900L, Status.ABANDONED));

		assertEquals(stored, ClockworkStorage.merge(stored, null));
		assertEquals(stored, ClockworkStorage.merge(stored, Collections.emptyList()));
	}

	/**
	 * A save and a load with nothing in between, which is what the plugin does
	 * across a restart.
	 */
	private static List<Routine> reload(List<Routine> routines)
	{
		final List<Routine> fresh = new ArrayList<>();
		for (Routine routine : routines)
		{
			if (routine != null)
			{
				fresh.add(new Routine(routine.getId(), routine.getName()));
			}
		}

		ClockworkStorage.attachHistory(fresh, stored(routines));
		return fresh;
	}

	/**
	 * What the config holds after a save, as the map a load builds out of it.
	 * One encode and one decode per clock, through the real pair, so a round
	 * trip here is the round trip a restart performs.
	 *
	 * <p>A clock with no usable id has no key to be written against and is not
	 * in the map, which is where its runs are lost.
	 */
	private static Map<String, List<Run>> stored(List<Routine> routines)
	{
		final Map<String, List<Run>> history = new LinkedHashMap<>();
		for (Routine routine : routines)
		{
			if (ClockworkStorage.historyKey(routine == null ? null : routine.getId()) == null)
			{
				continue;
			}
			history.put(routine.getId(),
				ClockworkStorage.decodeRuns(GSON, ClockworkStorage.encodeRuns(GSON, routine)));
		}
		return history;
	}

	private static Run run(long startedAt, long finishedAt, long duration, Status status, Lap... laps)
	{
		return new Run(startedAt, finishedAt, duration, new ArrayList<>(Arrays.asList(laps)), status);
	}
}

package com.clockwork;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

