package com.clockwork;

import com.clockwork.core.AlertOverride;
import com.clockwork.core.ClockMode;
import com.clockwork.core.Mode;
import com.clockwork.core.OverlayMode;
import com.clockwork.core.OverlayOverride;
import com.clockwork.core.Routine;
import com.clockwork.core.RoutineMigration;
import com.clockwork.core.SavedTrigger;
import com.clockwork.core.Toggle;
import com.clockwork.core.Trigger;
import com.clockwork.core.TriggerEvent;
import com.clockwork.core.TriggerLibrary;
import com.clockwork.core.TriggerType;
import com.google.gson.Gson;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Reading a stored blob back, and degrading rather than throwing when one
 * cannot be read.
 *
 * <p>There is one stored shape, and everything here is written in it. What
 * varies is how damaged the blob is, because a config file can be hand edited,
 * half written, or copied between profiles, and none of those is a reason to
 * hand the user back no clocks at all.
 *
 * <p>Losing settings quietly is the worst thing a persistence layer can do, and
 * losing every clock over one bad one is the second worst. Both are pinned
 * here, by decoding real blobs rather than reasoning about them.
 *
 * <p>A plain Gson is built here because there is no injector in a test. The
 * plugin itself always uses the injected one.
 */
public class ClockworkStorageTest
{
	private static final Gson GSON = new Gson();

	/**
	 * A clock with its stored enum settings filled in keeps them. Gson binds a
	 * stored enum by its serialized name, and a name that does not bind comes
	 * back null rather than throwing, so this is worth decoding for real rather
	 * than assuming.
	 */
	@Test
	public void aStoredBlobKeepsTheEnumSettingsItWasGiven()
	{
		String blob = "{\"version\":1,\"routines\":[{\"id\":\"a\",\"name\":\"Herb run\","
			+ "\"showDelta\":\"off\",\"clock\":\"wallclock\",\"alert\":\"screen\","
			+ "\"sound\":\"on\",\"notify\":\"off\"}]}";

		Routine herb = ClockworkStorage.decode(GSON, blob).get(0);

		assertSame(Toggle.OFF, herb.getShowDelta());
		assertSame(ClockMode.WALL_CLOCK, herb.getClock());
		assertSame(AlertOverride.SCREEN, herb.getAlert());
		assertSame("the chime setting and the drawn alert share a key or a binding, so a clock that"
				+ " asked for one of them got the other", Toggle.ON, herb.getSound());
		assertSame("the notification setting and the chime share a key or a binding, so a clock that"
				+ " asked for one of them got the other", Toggle.OFF, herb.getNotify());
	}

	/**
	 * A clock that had no triggers had none, and must come back with none
	 * rather than with something invented, because inventing a trigger would
	 * mean a clock that suddenly starts itself.
	 */
	@Test
	public void aClockWithNoTriggersDecodesWithNothing()
	{
		String blob = "{\"version\":1,\"routines\":[{\"id\":\"a\",\"name\":\"Herb run\","
			+ "\"showDelta\":\"off\"}]}";

		Routine herb = ClockworkStorage.decode(GSON, blob).get(0);

		assertSame(Trigger.nothing(), herb.getStartTrigger());
		assertSame(Trigger.nothing(), herb.getStopTrigger());
		assertSame(TriggerType.NONE, herb.getStartTrigger().getType());
		assertSame(TriggerType.NONE, herb.getStopTrigger().getType());
	}

	@Test
	public void aClockWithTriggersSurvivesTheRoundTrip()
	{
		Routine herb = new Routine("a", "Herb run");
		herb.setStartTrigger(Trigger.of(TriggerType.TELEPORT));
		herb.setStopTrigger(Trigger.of(TriggerType.BANK_CHEST));

		String blob = "{\"version\":1,\"routines\":[" + GSON.toJson(herb) + "]}";
		Routine decoded = ClockworkStorage.decode(GSON, blob).get(0);

		assertEquals(Trigger.of(TriggerType.TELEPORT), decoded.getStartTrigger());
		assertEquals(Trigger.of(TriggerType.BANK_CHEST), decoded.getStopTrigger());
		assertEquals("Herb run", decoded.getName());
	}

	/**
	 * The lap trigger arrived without a migration step of its own. A blob saved
	 * before it existed has no such key, Gson leaves the field null, and null
	 * already means Nothing everywhere the plugin reads a trigger. This is the
	 * test that says so rather than the assumption that says so.
	 */
	@Test
	public void aClockSavedBeforeLapTriggersExistedComesBackWithoutOne()
	{
		String blob = "{\"version\":1,\"routines\":[{\"id\":\"a\",\"name\":\"Herb run\","
			+ "\"lapsEnabled\":true,\"startTrigger\":{\"type\":\"teleport\"},"
			+ "\"stopTrigger\":{\"type\":\"bankchest\"}}]}";

		Routine herb = ClockworkStorage.decode(GSON, blob).get(0);

		assertSame("absent already means nothing", Trigger.nothing(), herb.getLapTrigger());
		assertSame(TriggerType.NONE, herb.getLapTrigger().getType());
		assertNull("and it can match no kind of event at all", herb.getLapTrigger().kind());

		assertEquals("the two it did have are untouched",
			Trigger.of(TriggerType.TELEPORT), herb.getStartTrigger());
		assertEquals(Trigger.of(TriggerType.BANK_CHEST), herb.getStopTrigger());
		assertTrue(herb.isLapsEnabled());
	}

	/**
	 * A lap trigger has to survive a save and a load like the other two, both
	 * as a fixed trigger and as a reference to a library entry, or the setting
	 * lasts until the next restart.
	 */
	@Test
	public void aLapTriggerSurvivesTheRoundTrip()
	{
		TriggerLibrary library = TriggerLibrary.empty();
		SavedTrigger entry = library.add("Note herbs", "Use", "Tool Leprechaun");

		Routine herb = new Routine("a", "Herb run");
		herb.setLapsEnabled(true);
		herb.setStartTrigger(Trigger.of(TriggerType.TELEPORT));
		herb.setLapTrigger(Trigger.saved(entry.getName()));
		herb.setStopTrigger(Trigger.of(TriggerType.BANK_CHEST));

		String blob = "{\"version\":1,\"triggers\":" + GSON.toJson(library.asStored())
			+ ",\"routines\":[" + GSON.toJson(herb) + "]}";
		ClockworkStorage.Saved saved = ClockworkStorage.decodeAll(GSON, blob);
		Routine decoded = saved.getRoutines().get(0);

		assertEquals("the reference came back as a reference",
			Trigger.saved("Note herbs"), decoded.getLapTrigger());
		assertEquals(Trigger.click("Use", "Tool Leprechaun"),
			saved.getLibrary().resolve(decoded.getLapTrigger()));
		assertTrue(saved.getLibrary().matches(decoded.getLapTrigger(),
			TriggerEvent.menuClick("Use", "Tool Leprechaun")));
		assertEquals("and the fixed triggers either side of it are untouched",
			Trigger.of(TriggerType.TELEPORT), decoded.getStartTrigger());
		assertEquals(Trigger.of(TriggerType.BANK_CHEST), decoded.getStopTrigger());

		String again = "{\"version\":1,\"routines\":[" + GSON.toJson(decoded) + "],\"triggers\":"
			+ GSON.toJson(saved.getLibrary().asStored()) + "}";
		ClockworkStorage.Saved back = ClockworkStorage.decodeAll(GSON, again);

		assertEquals("and it survives the next trip as a reference too",
			decoded.getLapTrigger(), back.getRoutines().get(0).getLapTrigger());
		assertTrue(back.getLibrary().matches(back.getRoutines().get(0).getLapTrigger(),
			TriggerEvent.menuClick("Use", "Tool Leprechaun")));
	}

	/**
	 * The same trigger on both ends is a real setting, not a mistake, so it has
	 * to come back the way it went in.
	 */
	@Test
	public void aClockThatTogglesItselfRoundTripsToo()
	{
		Routine laps = new Routine("b", "Agility lap");
		laps.setStartTrigger(Trigger.of(TriggerType.BANK_CHEST));
		laps.setStopTrigger(Trigger.of(TriggerType.BANK_CHEST));

		String blob = "{\"version\":1,\"routines\":[" + GSON.toJson(laps) + "]}";
		Routine decoded = ClockworkStorage.decode(GSON, blob).get(0);

		assertEquals(Trigger.of(TriggerType.BANK_CHEST), decoded.getStartTrigger());
		assertEquals(Trigger.of(TriggerType.BANK_CHEST), decoded.getStopTrigger());
	}

	/**
	 * A blob hand edited to name a trigger that no longer exists must not take
	 * the whole clock list down with it. It decodes as an empty object, which
	 * lands as Nothing, and the clock around it is kept.
	 */
	@Test
	public void anUnknownTriggerNameDecodesAsNothingRatherThanThrowing()
	{
		String blob = "{\"version\":1,\"routines\":[{\"id\":\"a\",\"name\":\"Herb run\","
			+ "\"startTrigger\":{\"type\":\"CHOPPING_A_TREE\"}}]}";

		Routine herb = ClockworkStorage.decode(GSON, blob).get(0);

		assertEquals("Herb run", herb.getName());
		assertSame(Trigger.nothing(), herb.getStartTrigger());
	}

	/**
	 * What the plugin writes today is what it can read tomorrow. The version
	 * stamped on a save has to be the one the migration treats as current, or
	 * every load would run a migration over data that never needed one.
	 */
	@Test
	public void whatIsWrittenNowIsStampedWithTheCurrentVersion()
	{
		assertEquals(1, RoutineMigration.CURRENT_VERSION);
		assertTrue("and the stamp is on what is written",
			ClockworkStorage.encodeRoutines(GSON, Collections.singletonList(new Routine("a", "Herb run")),
				TriggerLibrary.empty()).contains("\"version\":1"));
	}

	@Test
	public void nothingStoredMeansNoClocks()
	{
		assertTrue(ClockworkStorage.decode(GSON, null).isEmpty());
		assertTrue(ClockworkStorage.decode(GSON, "").isEmpty());
		assertTrue(ClockworkStorage.decode(GSON, "   ").isEmpty());
		assertTrue(ClockworkStorage.decode(GSON, "{}").isEmpty());
	}

	/**
	 * The referential integrity case. A hand edited config, or a clock copied
	 * between profiles, can point at an entry that is not there.
	 */
	@Test
	public void aReferenceToAnEntryThatIsNotThereResolvesToNothing()
	{
		String blob = "{\"version\":1,\"triggers\":[],"
			+ "\"routines\":[{\"id\":\"a\",\"name\":\"Herb run\","
			+ "\"startTrigger\":{\"type\":\"custom\",\"ref\":\"gone\"}}]}";

		ClockworkStorage.Saved saved = ClockworkStorage.decodeAll(GSON, blob);
		Routine herb = saved.getRoutines().get(0);

		assertEquals("the clock itself is not lost", "Herb run", herb.getName());
		assertSame("and it reads as manual rather than throwing",
			Trigger.nothing(), saved.getLibrary().resolve(herb.getStartTrigger()));
		assertFalse(saved.getLibrary().matches(herb.getStartTrigger(),
			TriggerEvent.menuClick("Use", "Tool Leprechaun")));
		assertEquals("nothing", saved.getLibrary().hint(herb.getStartTrigger()));
	}

	/**
	 * What is written now is what is read back, references included.
	 */
	@Test
	public void aLibraryAndTheClocksPointingAtItSurviveARoundTrip()
	{
		TriggerLibrary library = TriggerLibrary.empty();
		SavedTrigger entry = library.add("Note herbs", "Use", "Tool Leprechaun");

		Routine herb = new Routine("a", "Herb run");
		herb.setStartTrigger(Trigger.saved(entry.getName()));

		String blob = "{\"version\":1,\"triggers\":" + GSON.toJson(library.asStored())
			+ ",\"routines\":[" + GSON.toJson(herb) + "]}";

		ClockworkStorage.Saved saved = ClockworkStorage.decodeAll(GSON, blob);

		assertEquals(1, saved.getLibrary().all().size());
		assertEquals("Note herbs", saved.getLibrary().byName(entry.getName()).getName());
		assertEquals(Trigger.saved(entry.getName()), saved.getRoutines().get(0).getStartTrigger());
		assertTrue(saved.getLibrary().matches(saved.getRoutines().get(0).getStartTrigger(),
			TriggerEvent.menuClick("Use", "Tool Leprechaun")));
	}

	@Test
	public void nothingStoredMeansNoTriggersEither()
	{
		assertTrue(ClockworkStorage.decodeAll(GSON, null).getLibrary().all().isEmpty());
		assertTrue(ClockworkStorage.decodeAll(GSON, "{}").getLibrary().all().isEmpty());
		assertTrue(ClockworkStorage.decodeAll(GSON, "{\"version\":1}").getLibrary().all().isEmpty());
	}

	/**
	 * A trigger stored as a bare name where an object goes is a bind failure
	 * with nothing to repair it, and it used to take every clock in the blob
	 * down with it. A hand edit is the realistic way to arrive here.
	 *
	 * <p>It now costs the trigger and nothing else. The clock keeps its name,
	 * its direction and its target, and comes back waiting for nothing, which
	 * is a thing the user can see in the panel and fix.
	 */
	@Test
	public void aTriggerStoredAsABareNameCostsTheTriggerRatherThanTheClock()
	{
		String blob = "{\"version\":1,\"routines\":[{\"id\":\"a\",\"name\":\"Herb run\","
			+ "\"mode\":\"countdown\",\"targetMillis\":360000,"
			+ "\"startTrigger\":\"teleport\"}]}";

		List<Routine> decoded = ClockworkStorage.decode(GSON, blob);

		assertEquals("the clock is not lost", 1, decoded.size());
		Routine herb = decoded.get(0);
		assertEquals("Herb run", herb.getName());
		assertSame("nor is anything else it was set to", Mode.COUNT_DOWN, herb.getMode());
		assertEquals(360_000, herb.getTargetMillis());

		assertSame("only the trigger nobody can read", Trigger.nothing(), herb.getStartTrigger());
	}

	// Degrading rather than throwing

	/**
	 * The rule, stated as plainly as it can be. One clock nobody can read costs
	 * the user that clock, and not the two either side of it.
	 *
	 * <p>The middle clock stores a word where a number goes, which is a bind
	 * failure no rewrite can repair and nothing about a trigger, so there is
	 * nothing left to salvage of that clock and it is dropped.
	 */
	@Test
	public void oneUnreadableClockIsDroppedAndItsNeighboursAreKept()
	{
		String blob = "{\"version\":1,\"routines\":["
			+ "{\"id\":\"a\",\"name\":\"Herb run\",\"mode\":\"countup\","
			+ "\"startTrigger\":{\"type\":\"teleport\"}},"
			+ "{\"id\":\"b\",\"name\":\"Nonsense\",\"targetMillis\":\"soon\"},"
			+ "{\"id\":\"c\",\"name\":\"Flax run\",\"mode\":\"countdown\","
			+ "\"targetMillis\":360000}]}";

		List<Routine> decoded = ClockworkStorage.decode(GSON, blob);

		assertEquals("the two good clocks came back", 2, decoded.size());
		assertEquals("Herb run", decoded.get(0).getName());
		assertEquals("Flax run", decoded.get(1).getName());

		assertSame("and neither was disturbed on the way past", Mode.COUNT_UP, decoded.get(0).getMode());
		assertEquals(Trigger.of(TriggerType.TELEPORT), decoded.get(0).getStartTrigger());
		assertSame(Mode.COUNT_DOWN, decoded.get(1).getMode());
		assertEquals(360_000, decoded.get(1).getTargetMillis());
	}

	/**
	 * The other half. A blob whose clocks are otherwise fine keeps everything
	 * except the one trigger that cannot be read, including the other trigger
	 * on the very same clock.
	 *
	 * <p>Dropping both triggers would be the easy way to write the salvage and
	 * it would quietly cost a setting nothing was wrong with, so the two are
	 * dropped one at a time.
	 */
	@Test
	public void anUnreadableTriggerCostsThatTriggerAndNothingElseOnTheClock()
	{
		String blob = "{\"version\":1,\"triggers\":[{\"name\":\"Note herbs\",\"option\":\"Use\","
			+ "\"target\":\"Tool Leprechaun\"}],"
			+ "\"routines\":["
			+ "{\"id\":\"a\",\"name\":\"Herb run\",\"mode\":\"countup\","
			+ "\"startTrigger\":\"teleport\","
			+ "\"stopTrigger\":{\"type\":\"bankchest\"}},"
			+ "{\"id\":\"b\",\"name\":\"Ardougne run\","
			+ "\"startTrigger\":{\"type\":\"custom\",\"ref\":\"Note herbs\"}}]}";

		ClockworkStorage.Saved saved = ClockworkStorage.decodeAll(GSON, blob);
		List<Routine> decoded = saved.getRoutines();

		assertEquals("no clock was lost", 2, decoded.size());
		assertSame("the trigger nobody can read is the whole loss",
			Trigger.nothing(), decoded.get(0).getStartTrigger());
		assertEquals("the other trigger on that same clock is untouched",
			Trigger.of(TriggerType.BANK_CHEST), decoded.get(0).getStopTrigger());
		assertSame(Mode.COUNT_UP, decoded.get(0).getMode());

		assertEquals("and the clock beside it still points into the library",
			1, saved.getLibrary().all().size());
		assertEquals(Trigger.saved("Note herbs"), decoded.get(1).getStartTrigger());
		assertTrue(saved.getLibrary().matches(decoded.get(1).getStartTrigger(),
			TriggerEvent.menuClick("Use", "Tool Leprechaun")));
	}

	/**
	 * A clock nobody can read must not cost the user their saved triggers
	 * either. The library is read on its own, so it survives whatever the
	 * clocks do.
	 */
	@Test
	public void anUnreadableClockDoesNotCostTheUserTheirTriggerLibrary()
	{
		String blob = "{\"version\":1,"
			+ "\"triggers\":[{\"name\":\"Note herbs\",\"option\":\"Use\","
			+ "\"target\":\"Tool Leprechaun\"}],"
			+ "\"routines\":[{\"id\":\"a\",\"name\":\"Nonsense\",\"targetMillis\":\"soon\"},"
			+ "{\"id\":\"b\",\"name\":\"Herb run\","
			+ "\"startTrigger\":{\"type\":\"custom\",\"ref\":\"Note herbs\"}}]}";

		ClockworkStorage.Saved saved = ClockworkStorage.decodeAll(GSON, blob);

		assertEquals("the clock that could be read came back", 1, saved.getRoutines().size());
		assertEquals("Herb run", saved.getRoutines().get(0).getName());

		assertEquals("and the library came with it", 1, saved.getLibrary().all().size());
		assertEquals("Note herbs", saved.getLibrary().all().get(0).getName());
		assertEquals("reference and all",
			Trigger.saved("Note herbs"), saved.getRoutines().get(0).getStartTrigger());
		assertTrue(saved.getLibrary().matches(saved.getRoutines().get(0).getStartTrigger(),
			TriggerEvent.menuClick("Use", "Tool Leprechaun")));
	}

	/**
	 * The same rule, stated against a blob that says nothing is wrong with it.
	 * A hand edit or a half written config leaves the stamp alone, so the
	 * salvage cannot depend on the stamp. {@code load} catches and starts empty,
	 * which is the right last resort and the wrong first one, so it has to be
	 * reached as rarely as possible.
	 */
	@Test
	public void aDamagedBlobStampedCurrentDegradesTheSameWay()
	{
		String blob = "{\"version\":1,\"routines\":["
			+ "{\"id\":\"a\",\"name\":\"Nonsense\",\"targetMillis\":\"soon\"},"
			+ "{\"id\":\"b\",\"name\":\"Herb run\",\"mode\":\"countdown\","
			+ "\"targetMillis\":360000}]}";

		assertFalse("the good clock is not thrown away with the bad one",
			ClockworkStorage.decode(GSON, blob).isEmpty());
		assertEquals("Herb run", ClockworkStorage.decode(GSON, blob).get(0).getName());
		assertSame(Mode.COUNT_DOWN, ClockworkStorage.decode(GSON, blob).get(0).getMode());
	}

	/**
	 * The invariant every future update rests on, pinned so it stops being
	 * somebody's memory of an afternoon they checked it.
	 *
	 * <p>This tree binds the blob with a stock reflective Gson and no adapter
	 * of its own, so a key it has never heard of is skipped and the clock
	 * around it binds. That is what makes a stored shape safe to add a field to
	 * without a version bump, and it is what makes a user safe to run an older
	 * build after a newer one has written their config, which is an ordinary
	 * thing to do on the plugin hub when an update goes wrong.
	 *
	 * <p>Without it the direction of failure is the worst one this plugin has.
	 * A decode that threw on an unknown key would send the whole blob down the
	 * salvage path, and a salvage that could not read any clock hands the user
	 * back an empty list. Their clocks are the only copy of that data anywhere.
	 */
	@Test
	public void aBlobCarryingAKeyThisBuildDoesNotKnowStillGivesTheClockBackWhole()
	{
		final String blob = "{\"version\":1,\"routines\":[{\"id\":\"herb\",\"name\":\"Herb run\","
			+ "\"somethingFromTheFuture\":\"whatever\",\"mode\":\"countup\"}],\"triggers\":[]}";

		final List<Routine> routines = ClockworkStorage.decode(GSON, blob);

		assertEquals("a clock written by a build that knew one more field than this one came back as"
				+ " no clock at all, so every user who runs an older build after a newer one loses"
				+ " everything they had", 1, routines.size());

		final Routine herb = routines.get(0);
		assertEquals("herb", herb.getId());
		assertEquals("Herb run", herb.getName());
		assertSame(Mode.COUNT_UP, herb.getMode());
		assertSame("and the fields this build does know are still at their defaults rather than null",
			OverlayOverride.USE_GLOBAL, herb.getOverlay());
		assertSame(Toggle.USE_GLOBAL, herb.getShowDelta());
		assertSame(AlertOverride.USE_GLOBAL, herb.getAlert());
		assertSame(Toggle.USE_GLOBAL, herb.getSound());
		assertSame(Toggle.USE_GLOBAL, herb.getNotify());
	}

	/**
	 * The other half of the same rule, in the other direction. A clock saved
	 * before the timer box setting existed has no key for it, and Gson runs the
	 * field initialiser, so it comes back deferring to the plugin config, which
	 * is exactly how it behaved before the field was added.
	 */
	@Test
	public void aClockSavedWithoutATimerBoxSettingDefersToTheGlobalOne()
	{
		final String blob = "{\"version\":1,\"routines\":[{\"id\":\"a\",\"name\":\"Herb run\"}]}";

		assertSame(OverlayOverride.USE_GLOBAL, ClockworkStorage.decode(GSON, blob).get(0).getOverlay());
	}

	/**
	 * And a clock that does carry one keeps it, decoded from the stored
	 * spelling rather than from the constant name, because those differ and
	 * only one of them is what a config file holds.
	 */
	@Test
	public void aStoredTimerBoxSettingBindsFromItsStoredSpelling()
	{
		final String blob = "{\"version\":1,\"routines\":["
			+ "{\"id\":\"a\",\"name\":\"Herb run\",\"overlay\":\"always\"},"
			+ "{\"id\":\"b\",\"name\":\"Wine run\",\"overlay\":\"never\"}]}";

		final List<Routine> routines = ClockworkStorage.decode(GSON, blob);
		assertSame(OverlayOverride.ALWAYS, routines.get(0).getOverlay());
		assertSame(OverlayOverride.NEVER, routines.get(1).getOverlay());
	}

	/**
	 * A round trip through the real encoder, so the spelling that goes out is
	 * the spelling that comes back rather than two lists that happen to agree.
	 */
	@Test
	public void aTimerBoxSettingSurvivesBeingWrittenAndReadBack()
	{
		final Routine herb = new Routine("a", "Herb run");
		herb.setOverlay(OverlayOverride.WHILE_RUNNING);

		final String blob = ClockworkStorage.encodeRoutines(GSON,
			Collections.singletonList(herb), TriggerLibrary.empty());

		assertTrue("the stored spelling is what a config file holds and what an older build binds"
				+ " against, so it is the thing worth asserting. Blob was " + blob,
			blob.contains("\"overlay\":\"whilerunning\""));
		assertSame(OverlayOverride.WHILE_RUNNING, ClockworkStorage.decode(GSON, blob).get(0).getOverlay());
	}

	/**
	 * The config key move, which is the one thing in this update that is not
	 * the versioned blob and so has nothing to carry it across but this.
	 *
	 * <p>A user who had the timer boxes on must not find them off, and a user
	 * who had them off must not find them on. The old boolean answered "show a
	 * box for every clock that is running", so it maps onto exactly two of the
	 * three new answers and never onto always show, which nobody has ever asked
	 * for and nobody should be given.
	 */
	@Test
	public void theOldTimerBoxBooleanKeepsItsMeaning()
	{
		assertSame("a user who had the boxes on sees the same thing they saw yesterday",
			OverlayMode.WHILE_RUNNING, ClockworkStorage.movedVisibility("true"));
		assertSame("a user who turned the boxes off must not find them back",
			OverlayMode.NEVER, ClockworkStorage.movedVisibility("false"));
		assertSame("whitespace around a stored value is not a decision to change it",
			OverlayMode.NEVER, ClockworkStorage.movedVisibility(" FALSE "));
		assertSame("and anything nobody can read is the default the old setting shipped with,"
				+ " because an unreadable value is not evidence that the user asked for the boxes"
				+ " to go away",
			OverlayMode.WHILE_RUNNING, ClockworkStorage.movedVisibility("nonsense"));
	}
}

package com.clockwork;

import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Guards the event surface, which is the thing hub reviewers actually police.
 *
 * <p>{@link com.clockwork.core.TriggerType} explains at length why the trigger
 * vocabulary is only the player's own animations, the player's own clicks, and
 * game messages addressed to the player. The short version is that reviewers
 * judge what a plugin makes possible rather than what it was meant for. The
 * sound-triggers plugin shipped a "Player Seen" trigger and had it pulled the
 * next day, because a trigger that fires on another actor is a trigger
 * somebody can point at a boss, a PvP opponent, or a crowd.
 *
 * <p>That reasoning is written down in a class comment, and a class comment
 * does not fail a build. This does. Subscribing to a combat event would be a
 * one line change that compiles, works, and gets the whole plugin rejected,
 * and the person making it may never read the comment. Making it impossible to
 * add one without a red build is worth more than the comment is.
 *
 * <p>The allowlist below is deliberately explicit rather than a rule about
 * event packages or names. Widening it should be a decision somebody makes on
 * purpose, in this file, next to the reasons.
 *
 * <p>THIS TEST USES REFLECTION ON PURPOSE, AND IT IS ALLOWED TO. The plugin
 * rules forbid reflection in shipped code. This class lives in the test source
 * set, is never packaged into the plugin, and never runs inside the client. No
 * main source file uses reflection.
 */
public class ClockworkSubscriptionsTest
{
	/**
	 * Every event Clockwork is allowed to hear about. Each one is either the
	 * player's own action reported back to the player, or a change to the
	 * plugin's own surroundings.
	 *
	 * <ul>
	 * <li>{@code GameStateChanged}, so a clock counting logged in time only
	 * stops at the login screen</li>
	 * <li>{@code AnimationChanged}, filtered to the local player</li>
	 * <li>{@code MenuOptionClicked}, read only, nothing added or consumed</li>
	 * <li>{@code ChatMessage}, filtered to the game's messages to this
	 * player</li>
	 * <li>{@code ProfileChanged}, which is about RuneLite's own config and
	 * touches the game not at all</li>
	 * <li>{@code ConfigChanged}, added on purpose on 2026-08-24, and self
	 * directed for the same reason {@code ProfileChanged} is. It says that a
	 * setting moved, the handler drops every group but this plugin's own, and
	 * it reads nothing about the game or about any other actor. It replaced a
	 * poll that read the settings twenty times a second to notice a change a
	 * user makes about once a month</li>
	 * </ul>
	 */
	private static final Set<Class<?>> ALLOWED = new HashSet<>(Arrays.asList(
		GameStateChanged.class,
		AnimationChanged.class,
		MenuOptionClicked.class,
		ChatMessage.class,
		ProfileChanged.class,
		ConfigChanged.class));

	/**
	 * Named so the failure message can say what the test is really about. Any
	 * of these turns a timer into a combat helper, whatever it was added for.
	 *
	 * <p>Class literals are not used, because naming them would mean importing
	 * them, and an import of {@code HitsplatApplied} in this plugin is itself
	 * the wrong signal to leave lying around.
	 */
	private static final Set<String> FORBIDDEN = new HashSet<>(Arrays.asList(
		"ProjectileMoved",
		"HitsplatApplied",
		"ActorDeath",
		"InteractingChanged",
		"NpcSpawned",
		"NpcDespawned"));

	@Test
	public void everySubscribedEventIsOneWeAreAllowedToHear()
	{
		final List<String> offences = new ArrayList<>();
		final List<String> subscribed = new ArrayList<>();

		for (Method method : ClockworkPlugin.class.getDeclaredMethods())
		{
			if (method.isSynthetic() || method.getAnnotation(Subscribe.class) == null)
			{
				continue;
			}

			assertEquals("a @Subscribe method takes exactly one event, " + method.getName(),
				1, method.getParameterCount());

			final Class<?> event = method.getParameterTypes()[0];
			subscribed.add(event.getSimpleName());

			if (!ALLOWED.contains(event))
			{
				offences.add(method.getName() + " subscribes to " + event.getName()
					+ (FORBIDDEN.contains(event.getSimpleName())
						? ", which is a combat or other actor event and will get the plugin rejected"
						: ", which is not on the allowlist"));
			}
		}

		assertTrue("no @Subscribe methods were found at all, so this test is not testing anything",
			subscribed.size() >= 4);

		assertTrue("Clockwork listens only to the player's own actions and to RuneLite's own config."
				+ " Hub reviewers police the available surface rather than the intended usage, so a"
				+ " subscription to an event about another actor makes this a combat plugin whatever"
				+ " it was added for. See com.clockwork.core.TriggerType for the full reasoning. If a"
				+ " new event genuinely belongs here, add it to the allowlist in this test on purpose."
				+ " Offending subscriptions, " + offences,
			offences.isEmpty());
	}

	/**
	 * The other direction. The test above passes trivially if the allowlist is
	 * ever widened to include one of the events that must never be there, so
	 * the two sets are checked against each other as well.
	 */
	@Test
	public void theAllowlistNeverGrowsToIncludeACombatEvent()
	{
		for (Class<?> allowed : ALLOWED)
		{
			assertTrue("the allowlist has grown to include " + allowed.getSimpleName()
					+ ", which is exactly what it exists to keep out",
				!FORBIDDEN.contains(allowed.getSimpleName()));
		}
	}
}

package com.clockwork;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The build the plugin says it is. It is a constant rather than something read
 * out of a resource, because the build does not put the plugin properties on
 * the classpath and reading it back at runtime would mean reflection, which is
 * not allowed.
 *
 * <p>A constant can drift from the build, so this checks the two agree. Both
 * files are bumped together by the build script.
 */
public class ClockworkVersionTest
{
	private static String read(String name) throws IOException
	{
		File file = new File(name);
		assertTrue("expected to run with the plugin directory as the working directory, looked for "
			+ file.getAbsolutePath(), file.isFile());
		return new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);
	}

	@Test
	public void theConstantMatchesTheBuild() throws IOException
	{
		assertTrue("the version reads as MM.mm.rrr", ClockworkPlugin.VERSION.matches("\\d\\d\\.\\d\\d\\.\\d\\d\\d"));

		assertTrue("build.gradle should carry version '" + ClockworkPlugin.VERSION + "'",
			read("build.gradle").contains("version = '" + ClockworkPlugin.VERSION + "'"));

		String properties = read("runelite-plugin.properties");
		String declared = null;
		for (String line : properties.split("\\R"))
		{
			if (line.startsWith("version="))
			{
				declared = line.substring("version=".length()).trim();
			}
		}

		assertEquals("runelite-plugin.properties has drifted from ClockworkPlugin.VERSION",
			ClockworkPlugin.VERSION, declared);
	}
}

package com.clockwork;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Stream;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Guards the client's window, which Clockwork has no business touching.
 *
 * <p>RuneLite's rejected features list carries this, and our snapshot of the
 * plugin rules did not until the same day this test was written.
 *
 * <blockquote>Plugins that manipulate the client's window, including, but not
 * limited to, minimizing or changing which window is currently
 * focused.</blockquote>
 *
 * <p>The rule has a history worth knowing, because it is the reason the click
 * trigger in this plugin is written the way it is. A hub plugin called Click To
 * Minimize used the same matcher Clockwork's click trigger uses, free text
 * option and target compared against the menu entry the player clicked, and
 * lived on the hub with it from 2024 to 2026. It was pulled at Jagex's request,
 * and not for the matcher. It was pulled for what it did with the click, which
 * was to shrink the client window, and Jagex tied that to an enforcement action.
 * The rule above was added to the wiki twelve days later.
 *
 * <p>So reading the player's own menu clicks is precedented and safe. The risk
 * in a plugin lives in what it does with an event rather than in how it observes
 * one, and what Clockwork does with a click is start a timer. This test guards
 * the half that actually got somebody removed.
 *
 * <p>The second test here guards the other half of the same sentence in the
 * README, that Clockwork changes no menu entry, adds none, and swallows none.
 * That was true by reading and by nothing else until the tokens went in below.
 *
 * <blockquote>Plugins that add menu entries that send actions to the
 * server.</blockquote>
 *
 * <p>The scan is over the source text rather than over the compiled classes,
 * because these are call sites rather than signatures. Reflection would show
 * that this plugin declares no method called {@code toFront} and would say
 * nothing at all about whether it calls one.
 *
 * <p>This test reads files rather than using reflection, so it is not even the
 * sort of test that needs the usual note. No main source file uses reflection.
 */
public class ClockworkWindowTest
{
	/**
	 * Where the shipped code lives, relative to the plugin directory the tests
	 * run in.
	 */
	private static final String MAIN_SOURCE = "src/main/java";

	/**
	 * Every way a plugin reaches for the client's window that is worth naming.
	 * Matched as plain text against the source, comments included, because a
	 * comment planning one of these is worth catching too.
	 *
	 * <p>Widening this list is free. Narrowing it should be a decision somebody
	 * makes on purpose, in this file, next to the reasons above.
	 */
	private static final List<String> WINDOW = Arrays.asList(
		"javax.swing.JFrame",
		"JFrame",
		"java.awt.Frame",
		"setExtendedState",
		"toBack",
		"toFront",
		"setAlwaysOnTop",
		"requestFocus",
		"ICONIFIED");

	/**
	 * Every way a plugin writes to the client's menu, plus the one way it
	 * swallows a click.
	 *
	 * <p>Matched the same way, as plain text over the source with comments
	 * included, with one exception. The swallow is matched as
	 * {@code .consume()} rather than as {@code consume}, because four javadoc
	 * sentences in the plugin promise that the click is not consumed and the
	 * word has to stay sayable in the place where the promise is made. A real
	 * swallow is a call on the event and reads as the call.
	 */
	private static final List<String> MENU = Arrays.asList(
		"setMenuEntries",
		"createMenuEntry",
		"MenuEntry",
		".consume()");

	/**
	 * Things a hub plugin may not do, named here so that no file in this tree
	 * contains the words, whether it is calling them or explaining that it does
	 * not call them.
	 *
	 * <p>The second half is the point. A reviewer greps the tree, and a grep
	 * does not know a javadoc from a call. A submitter on plugin-hub 15361 was
	 * flagged twice for a banned API their code did not use, because a comment
	 * explaining why they had avoided it named it, and the grep kept matching.
	 * Explaining what you did not do, by naming it, reads exactly like doing
	 * it.
	 *
	 * <p>So the rule for this codebase is that a comment describes what the
	 * code does rather than what it declines to do, and where declining is the
	 * interesting part it is said without the forbidden name in it. This test
	 * is what keeps that true, since the alternative is remembering.
	 */
	private static final List<String> NEVER_NAMED = Arrays.asList(
		"Desktop.",
		"Thread.interrupt",
		"System.exit",
		"Runtime.getRuntime",
		"KeyboardFocusManager",
		"printStackTrace",
		"System.out",
		"System.err");

	@Test
	public void noMainSourceFileEvenNamesAForbiddenApi() throws IOException
	{
		final List<String> offences = scanFor(NEVER_NAMED);

		assertTrue("These are things a hub plugin may not do, and this tree does not contain the"
				+ " words at all, in code or in a comment. A reviewer greps, and a grep cannot tell"
				+ " a javadoc from a call, so a comment explaining why we avoided one of these reads"
				+ " as evidence that we did not. If a comment needs to make that point, make it"
				+ " without the name. Offending files, " + offences,
			offences.isEmpty());
	}

	@Test
	public void noMainSourceFileReachesForTheClientWindow() throws IOException
	{
		final List<String> offences = scanFor(WINDOW);

		assertTrue("RuneLite rejects plugins that manipulate the client's window, minimizing it or"
				+ " changing which window has focus included. A hub plugin was removed at Jagex's"
				+ " request for exactly that. Clockwork is a timer and has no reason to touch the"
				+ " window at all. See the comment at the top of this file before deciding that a"
				+ " new one does. Offending files, " + offences,
			offences.isEmpty());
	}

	/**
	 * The other half of the README's claim, that Clockwork starts a timer and
	 * changes no menu entry, adds none, and swallows none.
	 *
	 * <p>{@code MenuOptionClicked} is read and nothing else. The plugin takes
	 * the option and the target off it and hands them to the trigger rules, and
	 * the client does with the click exactly what it would have done had the
	 * plugin not been installed. Nothing here writes to the menu, so nothing
	 * here can send an action to the server on the player's behalf.
	 */
	@Test
	public void noMainSourceFileWritesToTheMenuOrSwallowsAClick() throws IOException
	{
		final List<String> offences = scanFor(MENU);

		assertTrue("RuneLite rejects plugins that add menu entries which send actions to the server,"
				+ " and the README promises that Clockwork changes no menu entry, adds none, and"
				+ " swallows none. Reading MenuOptionClicked is what the trigger needs and is all it"
				+ " is allowed. Anything that builds, replaces, or consumes an entry breaks the"
				+ " promise and has to be argued for here first. Offending files, " + offences,
			offences.isEmpty());
	}

	/**
	 * Reads every shipped source file and reports each token any of them
	 * mentions, having first proved there was something to read.
	 */
	private static List<String> scanFor(List<String> tokens) throws IOException
	{
		final List<Path> sources = mainSources();

		assertFalse("no main source files were found under " + new File(MAIN_SOURCE).getAbsolutePath()
				+ ", so this test would pass by scanning nothing. It expects to run with the plugin"
				+ " directory as the working directory.",
			sources.isEmpty());
		assertTrue("only " + sources.size() + " main source files were found, which is too few to be"
				+ " the whole plugin, so this test is not scanning what it thinks it is",
			sources.size() >= 20);

		final List<String> offences = new ArrayList<>();
		for (Path source : sources)
		{
			final String text = new String(Files.readAllBytes(source), StandardCharsets.UTF_8);
			for (String token : tokens)
			{
				if (text.contains(token))
				{
					offences.add(source + " mentions " + token);
				}
			}
		}
		return offences;
	}

	private static List<Path> mainSources() throws IOException
	{
		final File root = new File(MAIN_SOURCE);
		assertTrue("expected to run with the plugin directory as the working directory, looked for "
			+ root.getAbsolutePath(), root.isDirectory());

		try (Stream<Path> walk = Files.walk(root.toPath()))
		{
			final List<Path> sources = new ArrayList<>();
			walk.filter(Files::isRegularFile)
				.filter(path -> path.toString().endsWith(".java"))
				.forEach(sources::add);
			return sources;
		}
	}
}

package com.clockwork;

import com.clockwork.core.AlertOverride;
import com.clockwork.core.AlertStyle;
import com.clockwork.core.Mode;
import com.clockwork.core.OverlayMode;
import com.clockwork.core.OverlayOverride;
import com.clockwork.core.Routine;
import com.clockwork.core.RoutineController;
import com.clockwork.core.Toggle;
import com.clockwork.overlay.OverlaySnapshot;
import com.clockwork.overlay.RoutineOverlay;
import java.awt.Component;
import java.awt.Container;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.BooleanSupplier;
import javax.swing.JButton;
import javax.swing.JLabel;
import net.runelite.client.config.Notification;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.input.KeyListener;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.Overlay;
import static org.hamcrest.CoreMatchers.containsString;
import org.junit.After;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertThat;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.contains;
import static org.mockito.Mockito.atLeast;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;

/**
 * The wiring, tested. See {@link ClockworkHarness} for how it is stood up and
 * for what is a mock and what is hand written.
 *
 * <p>These are the paths that had no coverage at all while the pure core had
 * hundreds of tests, and they are the paths every bug this plugin has shipped
 * lived in. Two of them are here. The profile switch, which used to write one
 * profile's clocks over another's. And the registration lifecycle, which
 * RuneLite does not clean up for a plugin that forgets.
 *
 * <p>Adding another is a matter of a {@code @Test} and no new plumbing, which
 * was the point of the harness.
 */
public class ClockworkWiringTest
{
	private static final String HERB = "herb";
	private static final String WINES = "wines";

	private ClockworkHarness harness;

	@Before
	public void setUp()
	{
		harness = new ClockworkHarness();
	}

	@After
	public void tearDown()
	{
		harness.shutDown();
	}

	/**
	 * The bug this was written for. Every RuneLite config profile keeps its own
	 * settings file, so the clock list is per profile, and the plugin used to
	 * read it once at start up and never again. After a switch it still held
	 * the previous profile's clocks and the next save wrote them over the newly
	 * selected profile's.
	 *
	 * <p>The decision inside the switch is pure and already tested in
	 * {@code ProfileSwitchTest}. What is tested here is that the event reaches
	 * it, that the reload really replaces what the plugin holds, and that the
	 * run in progress is cancelled rather than carried into a profile it does
	 * not belong to.
	 */
	@Test
	public void aProfileChangeReplacesTheClocksAndDropsTheRunInProgress()
	{
		harness.storage.setStored(ClockworkHarness.routine(HERB, "Herb run"));
		harness.startUp();

		harness.onEdt(() -> harness.controller().start(HERB));
		assertTrue("the setup did not get a run under way, so the rest of this proves nothing",
			harness.controller().isRunning(HERB));

		// The user switched profile. The config manager has already moved by
		// the time the event arrives, so what storage answers now is the new
		// profile's clocks.
		harness.storage.setStored(ClockworkHarness.routine(WINES, "Wine run"));
		harness.plugin.onProfileChanged(new ProfileChanged());
		harness.flushEdt();

		final RoutineController after = harness.controller();
		assertNotNull("the clocks from the profile that was entered were never loaded",
			after.get(WINES));
		assertNull("the plugin is still holding a clock from the profile that was left, which is how"
				+ " one profile's clocks used to get written over another's",
			after.get(HERB));
		assertTrue("a run survived the switch, so it is still ticking against a profile it cannot be"
				+ " written to. It should have been cancelled. Running, " + after.runningIds(),
			after.runningIds().isEmpty());

		// The save that follows the reload goes to the profile just entered, so
		// what it writes has to be that profile's clocks and nothing else.
		assertTrue("the first save after the switch wrote a clock from the old profile into the new"
				+ " profile. Stored, " + harness.storage.storedIds(),
			harness.storage.storedIds().contains(WINES)
				&& !harness.storage.storedIds().contains(HERB));

		// The log is where the plugin says out loud what the switch cost. It is
		// the only evidence from outside that the run was dropped on purpose
		// rather than quietly lost.
		harness.shutDown();
		assertThat("the plugin did not record dropping the run, so a user looking at the log would"
				+ " have no idea where their run went",
			harness.newDiagnosticsText(), containsString("dropping 1 run in progress"));
	}

	/**
	 * Teardown mirrors startup, checked rather than read.
	 *
	 * <p>Stopping a plugin does not undo its registrations for it.
	 * {@code PluginManager} unschedules it and unregisters it from the event
	 * bus and then calls {@code shutDown}, and it never touches the toolbar. A
	 * navigation button left behind still opens a panel nothing is refreshing,
	 * which is the kind of thing only a user ever finds.
	 */
	@Test
	public void everythingRegisteredAtStartUpComesBackOffAtShutDown()
	{
		harness.storage.setStored(
			ClockworkHarness.routine(HERB, "Herb run"),
			ClockworkHarness.routine(WINES, "Wine run"));
		harness.startUp();

		// Both clocks are put under way first, because a timer box only exists
		// while its clock is running. Shutting down with nothing running would
		// leave the overlay half of this test checking an empty set against an
		// empty set and passing for the wrong reason.
		harness.onEdt(() ->
		{
			harness.controller().start(HERB);
			harness.controller().start(WINES);
		});
		waitFor("neither running clock ever got a timer box, so there is nothing here to give back",
			() -> harness.addedTimerBoxes().size() >= 2);

		final List<NavigationButton> buttons = harness.addedNavigation();
		assertFalse("the side panel button was never added, so there is nothing to prove here",
			buttons.isEmpty());

		// Every overlay rather than the timer boxes alone, because the screen
		// flash goes on at start up too and is exactly the sort of thing that
		// gets registered once and forgotten about at teardown.
		final List<Overlay> boxes = harness.addedOverlays();
		assertTrue("the screen flash was never registered, so this test is not covering it. Added "
				+ names(boxes),
			names(boxes).contains("clockwork_screenflash"));

		final List<KeyListener> keys = harness.registeredKeyListeners();
		assertEquals("the plugin registered a different number of key listeners than the three"
				+ " hotkeys it has, so this test is not covering what it thinks it is",
			3, keys.size());

		harness.shutDown();

		assertEquals("a navigation button was added and never taken off, so it still opens a panel"
				+ " nothing is refreshing. Added " + buttons
				+ ", removed " + harness.removedNavigation(),
			new HashSet<>(buttons), new HashSet<>(harness.removedNavigation()));

		assertEquals("an overlay was added and never taken off. Stopping a plugin never touches the"
				+ " overlay manager, so one left behind keeps drawing over the game forever with the"
				+ " plugin showing as off. Added " + names(boxes)
				+ ", removed " + names(harness.removedOverlays()),
			new HashSet<>(boxes), new HashSet<>(harness.removedOverlays()));

		assertEquals("a key listener was registered and never given back. Stopping a plugin never"
				+ " touches the key manager, so one left behind goes on acting on key presses with"
				+ " the plugin switched off, against a controller that has already been dropped."
				+ " Registered " + keys.size()
				+ ", unregistered " + harness.unregisteredKeyListeners().size(),
			new HashSet<>(keys), new HashSet<>(harness.unregisteredKeyListeners()));
	}

	/**
	 * The timer box, which is the whole reason the plugin draws anything
	 * outside the side panel.
	 *
	 * <p>A herb run is exactly the situation where the side panel is shut and
	 * the player is moving around the game world, so a box appears when a clock
	 * starts and goes away when it stops. Nothing here can test what the box
	 * looks like, because Swing rendering needs a frame, so what is tested is
	 * the pairing that decides whether one is on screen at all.
	 *
	 * <p>Stopping no longer takes the box away that instant. The run that just
	 * finished flashes its box, and the box is held open for the length of that
	 * alert so the flash can be seen, which the test next door is about. The
	 * alert is shortened here so this one is waiting on the pairing rather than
	 * on five seconds of blinking.
	 */
	@Test
	public void aTimerBoxAppearsWhileAClockRunsAndGoesAwayWhenItStops()
	{
		harness.config.setAlertSeconds(1);
		harness.storage.setStored(ClockworkHarness.routine(HERB, "Herb run"));
		harness.startUp();

		assertTrue("a timer box was put on screen with nothing running at all, so an idle client"
				+ " carries a box it was never asked for. Added " + names(harness.addedTimerBoxes()),
			harness.addedTimerBoxes().isEmpty());

		harness.onEdt(() -> harness.controller().start(HERB));
		waitFor("a clock started and no timer box appeared, so a run cannot be read without opening"
			+ " the side panel", () -> harness.addedTimerBoxes().size() == 1);

		harness.onEdt(() -> harness.controller().stop(HERB));
		waitFor("the run finished, its alert is long over, and its timer box is still on the overlay"
				+ " manager, so a box that nothing updates sits over the game until the plugin is"
				+ " switched off",
			() -> harness.removedTimerBoxes().size() == 1);
	}

	/**
	 * The setting that turns the boxes off, which is the only reason it exists.
	 *
	 * <p>Turning it off has to take away the boxes that are already on screen,
	 * not merely stop new ones appearing, because the clock a user wants the
	 * box off is the clock that is running while they change the setting.
	 */
	@Test
	public void turningTheTimerBoxSettingToNeverTakesEveryBoxAway()
	{
