			ClockworkHarness.routine(HERB, "Herb run"),
			ClockworkHarness.routine(WINES, "Wine run"));
		harness.startUp();

		harness.onEdt(() ->
		{
			harness.controller().start(HERB);
			harness.controller().start(WINES);
		});
		waitFor("the setup never got two timer boxes on screen, so turning the setting off proves"
			+ " nothing", () -> harness.addedTimerBoxes().size() >= 2);

		final List<Overlay> boxes = harness.addedTimerBoxes();

		harness.config.setOverlayVisibility(OverlayMode.NEVER);
		harness.plugin.onConfigChanged(visibilityChanged());

		waitFor("the timer boxes were turned off and the ones already on screen stayed there, so the"
				+ " setting only works for clocks that have not started yet. Added " + names(boxes)
				+ ", removed " + names(harness.removedTimerBoxes()),
			() -> harness.removedTimerBoxes().containsAll(boxes));
	}

	/**
	 * Always show, which is the answer the boxes never had before. Every other
	 * mode gives a box to a clock that is running, and this one gives a box to
	 * a clock that is not, so the whole add path runs on a client where nothing
	 * has been started at all.
	 */
	@Test
	public void alwaysShowGivesAnIdleClockABoxWithNothingRunning()
	{
		harness.config.setOverlayVisibility(OverlayMode.ALWAYS);
		harness.storage.setStored(ClockworkHarness.routine(HERB, "Herb run"));
		harness.startUp();

		waitFor("the timer boxes are set to always show and an idle clock never got one, so the"
				+ " setting does nothing until a run is under way, which is the one thing it is"
				+ " for", () -> harness.addedTimerBoxes().size() >= 1);
	}

	/**
	 * A clock's own setting beating the plugin wide one, in the direction that
	 * costs the user a box and in the direction that gives them one.
	 *
	 * <p>Both directions matter. An override that only ever adds a box would
	 * pass a test that resolved nothing at all, since the global default gives
	 * a running clock a box on its own.
	 */
	@Test
	public void aClockSettingOfItsOwnBeatsThePluginWideOne()
	{
		final Routine always = ClockworkHarness.routine(HERB, "Herb run");
		always.setOverlay(OverlayOverride.ALWAYS);
		final Routine never = ClockworkHarness.routine(WINES, "Wine run");
		never.setOverlay(OverlayOverride.NEVER);

		harness.config.setOverlayVisibility(OverlayMode.NEVER);
		harness.storage.setStored(always, never);
		harness.startUp();

		waitFor("a clock set to always show got no box while the plugin wide setting said never, so"
				+ " the per clock setting never wins. Added " + names(harness.addedTimerBoxes()),
			() -> names(harness.addedTimerBoxes()).contains("clockwork_" + HERB));

		// And the other way. This one is running, which under any global
		// setting but never would have earned it a box, and its own setting
		// says no.
		harness.onEdt(() -> harness.controller().start(WINES));
		harness.flushEdt();

		assertFalse("a clock set to never show got a box anyway while it was running, so its own"
				+ " setting is ignored the moment a run starts. Added "
				+ names(harness.addedTimerBoxes()),
			names(harness.addedTimerBoxes()).contains("clockwork_" + WINES));
	}

	/**
	 * The teardown, under the setting that changes what teardown has to cover.
	 *
	 * <p>The pairing test above starts two clocks first, because a box used to
	 * exist only while its clock ran. Always show breaks that assumption, so
	 * the leak it opens is a box on an idle client, which is a client that has
	 * been sitting there doing nothing and is the least likely state for
	 * anybody to notice a box that outlives the plugin.
	 */
	@Test
	public void anIdleAlwaysShowBoxComesBackOffAtShutDown()
	{
		harness.config.setOverlayVisibility(OverlayMode.ALWAYS);
		harness.storage.setStored(ClockworkHarness.routine(HERB, "Herb run"));
		harness.startUp();

		waitFor("no idle box was ever added, so the teardown below would pass by giving nothing"
			+ " back", () -> harness.addedTimerBoxes().size() >= 1);
		final List<Overlay> boxes = harness.addedTimerBoxes();

		harness.shutDown();

		// Flushed after the shutdown as well, because the leak this guards is a
		// refresh tick that was already queued when the plugin stopped and adds
		// a box that nothing will ever remove.
		harness.flushEdt();

		assertEquals("an idle timer box was added and never taken off. Stopping a plugin never"
				+ " touches the overlay manager, so one left behind keeps drawing over the game"
				+ " forever with the plugin showing as off. Added " + names(boxes)
				+ ", removed " + names(harness.removedTimerBoxes()),
			new HashSet<>(boxes), new HashSet<>(harness.removedTimerBoxes()));
		assertTrue("a box was added after the teardown ran, so a queued refresh tick can still"
				+ " reach the overlay manager once the plugin is off. Added "
				+ names(harness.addedTimerBoxes()),
			harness.addedTimerBoxes().size() == boxes.size());
	}

	/**
	 * The end of a run, which is the whole reason the alerts exist.
	 *
	 * <p>A fresh install flashes the timer box that clock already has and asks
	 * RuneLite to notify. It does not chime, because the chime is off until the
	 * user turns it on. A published plugin that started playing a sound on every
	 * finished run after an automatic update would be the sort of change nobody
	 * notices in a diff.
	 *
	 * <p>The notification going out on a fresh install is deliberate and is the
	 * one part of this that changed. It used to be shipped switched off, and
	 * {@code Notifier} returns straight back out on a notification that is not
	 * enabled, so the whole path was inert for everybody who never opened the
	 * item. Shipping it on costs a focused player nothing, since RuneLite holds
	 * a notification back while the client has focus unless the item itself says
	 * otherwise, and it is what makes the setting mean something for the alt
	 * tabbed player it is for.
	 *
	 * <p>This test used to assert that no notification went out at all, first
	 * because the item was off and then because the notification had been folded
	 * into the alert style. It is neither of those now, so the assertion is the
	 * other way round rather than loosened.
	 * {@link #aClockThatSaysNoIsNotAnnouncedEvenThoughTheGlobalSaysYes} is the
	 * other direction.
	 */
	@Test
	public void finishingARunFlashesAndNotifiesAndLeavesTheChimeAlone()
	{
		harness.storage.setStored(ClockworkHarness.routine(HERB, "Herb run"));
		harness.startUp();

		harness.onEdt(() -> harness.controller().start(HERB));
		verify(harness.notifier, never()).notify(any(Notification.class), anyString());

		harness.onEdt(() -> harness.controller().stop(HERB));

		verify(harness.notifier, times(1).description("a finished run did not reach RuneLite on a"
			+ " fresh install, so the notification is inert for every user who never opens the"
			+ " item")).notify(any(Notification.class), contains("Herb run finished in "));
		assertEquals("the chime played even though the sound setting is off",
			0, harness.audioPlayer.playCount());
	}

	/**
	 * The notification path, end to end, for a clock that asked for one while
	 * the plugin wide item is switched off.
	 *
	 * <p>Two things at once, and both of them are the awkward direction. The
	 * per clock setting has to beat a global that says no, and what goes out has
	 * to be a notification {@code Notifier} will act on, which a copy of a
	 * switched off item is not. A test that only counted the call would pass
	 * with a notification that RuneLite drops on the floor.
	 *
	 * <p>The notifier reads whether the client has focus, so the plugin hands it
	 * over on the client thread rather than from Swing. The harness runs client
	 * thread work inline, so a call that skipped the hop and one that took it
	 * both land here, and what this catches is the call going missing rather
	 * than the thread it went out on. It is still the only test that walks the
	 * whole way from a finished run to {@code Notifier}.
	 */
	@Test
	public void aClockThatSaysYesReachesRuneLiteEvenWhileTheGlobalSaysNo()
	{
		harness.config.setNotification(Notification.OFF);

		final Routine announced = ClockworkHarness.routine(HERB, "Herb run");
		announced.setNotify(Toggle.ON);
		harness.storage.setStored(announced);
		harness.startUp();

		harness.onEdt(() -> harness.controller().start(HERB));
		verify(harness.notifier, never()).notify(any(Notification.class), anyString());

		harness.onEdt(() -> harness.controller().stop(HERB));

		final ArgumentCaptor<Notification> sent = ArgumentCaptor.forClass(Notification.class);
		verify(harness.notifier, times(1)).notify(sent.capture(), contains("Herb run finished in "));
		assertTrue("the clock that said yes was handed a notification that is switched off, which"
				+ " Notifier drops without doing anything, so it asked for something and got"
				+ " nothing",
			sent.getValue().isEnabled());
	}

	/**
	 * And the other direction, which the plugin wide item cannot express on its
	 * own. One clock says no while the shipped default says yes, and that clock
	 * is not announced while the one beside it still is.
	 */
	@Test
	public void aClockThatSaysNoIsNotAnnouncedEvenThoughTheGlobalSaysYes()
	{
		final Routine quiet = ClockworkHarness.routine(HERB, "Herb run");
		quiet.setNotify(Toggle.OFF);
		harness.storage.setStored(quiet, ClockworkHarness.routine(WINES, "Wine run"));
		harness.startUp();

		harness.onEdt(() ->
		{
			harness.controller().start(HERB);
			harness.controller().stop(HERB);
		});

		verify(harness.notifier, never()).notify(any(Notification.class), anyString());

		harness.onEdt(() ->
		{
			harness.controller().start(WINES);
			harness.controller().stop(WINES);
		});

		verify(harness.notifier, times(1).description("the clock left alone stopped being announced"
			+ " too, so one clock saying no silenced the rest"))
			.notify(any(Notification.class), contains("Wine run finished in "));
	}

	/**
	 * A finished run writes that clock's runs and nothing else.
	 *
	 * <p>The saved state used to be rewritten whole every time a run ended, and
	 * every clock's runs went with it, all under one key. A config value is
	 * written whole and every key that has changed is uploaded whole, so a user
	 * with ten clocks at the fifty run cap put a quarter of a megabyte on a
	 * volunteer project's servers for one finished herb run.
	 *
	 * <p>Splitting the keys is what fixes the upload. Which write the finished
	 * run goes through is what fixes the rest of it, and that is what this pins,
	 * at the level where the controller, the listener and the storage are wired
	 * together rather than at any one of them.
	 */
	@Test
	public void finishingARunWritesOneClocksRunsRatherThanTheWholeSavedState()
	{
		harness.storage.setStored(ClockworkHarness.routine(HERB, "Herb run"),
			ClockworkHarness.routine(WINES, "Wines"));
		harness.startUp();

		harness.onEdt(() -> harness.controller().start(HERB));
		final int wideSaves = harness.storage.saveCount();

		harness.onEdt(() -> harness.controller().stop(HERB));

		assertEquals("the run went through the narrow write, aimed at the clock that gained it",
			Collections.singletonList(HERB), harness.storage.historySaves());
		assertEquals("and nothing rewrote the clock list, which a finished run does not change",
			wideSaves, harness.storage.saveCount());
	}

	/**
	 * Clearing one clock is the same narrow change seen from the other side, so
	 * it takes the same narrow write. The runs of the clock beside it are not
	 * rewritten to say that they did not change.
	 */
	@Test
	public void clearingOneClocksRunsIsAlsoOneWrite()
	{
		harness.storage.setStored(ClockworkHarness.routine(HERB, "Herb run"),
			ClockworkHarness.routine(WINES, "Wines"));
		harness.startUp();

		harness.onEdt(() ->
		{
			harness.controller().start(HERB);
			harness.controller().stop(HERB);
		});
		final int wideSaves = harness.storage.saveCount();

		harness.onEdt(() -> harness.controller().reset(HERB));

		assertEquals(Arrays.asList(HERB, HERB), harness.storage.historySaves());
		assertEquals(wideSaves, harness.storage.saveCount());
		assertTrue("the runs really did go",
			harness.controller().get(HERB).historyOrEmpty().isEmpty());
	}

	/**
	 * A countdown that carries on into overtime, which is the other moment
	 * worth alerting on and the one with a latch behind it.
	 *
	 * <p>{@code StopAtZeroTest} covers the latch itself against a fake clock.
	 * What is covered here is that the callback is wired to an alert at all,
	 * which it was not while the alerts were out of the plugin, and that many
	 * refresh ticks past the deadline still produce one alert rather than one
	 * per tick.
	 */
	@Test
	public void aCountdownThatRunsPastZeroAlertsOnceRatherThanOncePerTick()
	{
		// The notification is what this counts, and it goes out beside whatever
		// the alert style draws rather than instead of it, so the shipped
		// settings are enough for there to be something to count.
		final Routine overtime = ClockworkHarness.routine(HERB, "Herb run");
		overtime.setMode(Mode.COUNT_DOWN);
		overtime.setTargetMillis(0);
		overtime.setStopAtZero(false);
		harness.storage.setStored(overtime);
		harness.startUp();

		harness.onEdt(() -> harness.controller().start(HERB));

		// The refresh timer is what drives the expiry, and it is running for
		// real here, so this waits for the alert rather than forcing a tick.
		waitFor("a countdown ran past zero and nothing announced it, so the expiry callback reaches"
				+ " no alert at all",
			() -> notifications().size() >= 1);

		assertTrue("the run ended itself even though it was told to carry on into overtime",
			harness.controller().isRunning(HERB));

		// Long enough for many more ticks at the fast period, none of which may
		// alert again.
		settle(500);
		assertEquals("the countdown alerted again on a later tick, so the latch in the controller is"
				+ " not holding and a clock left in overtime would announce itself forever. Sent, "
				+ notifications(),
			1, notifications().size());
	}

	/**
	 * The count in, end to end and in real time. A countdown of a second and a
	 * fifth is counted in once, at one second left, and then chimes at zero.
	 *
	 * <p>{@code CountInTest} covers which seconds are announced against a fake
	 * clock. What is covered here is that the announcement reaches a clip at
	 * all, that the clip is the short one rather than the chime, and that the
	 * two arrive in that order off the real refresh timer.
	 *
	 * <p>A short countdown on purpose, since this waits in real time and one
	 * beat proves the path as well as three do.
	 */
	@Test
	public void aCountdownIsCountedInAndThenChimes()
	{
		final Routine countdown = ClockworkHarness.routine(HERB, "Herb run");
		countdown.setMode(Mode.COUNT_DOWN);
		countdown.setTargetMillis(1_200);
		countdown.setStopAtZero(true);
		countdown.setSound(Toggle.ON);
		harness.storage.setStored(countdown);
		harness.startUp();

		harness.onEdt(() -> harness.controller().start(HERB));

		waitFor("a countdown ran to zero and played nothing, so the count in reaches no clip."
				+ " Played, " + harness.audioPlayer.played(),
			() -> harness.audioPlayer.played().size() >= 2);

		// Long enough for many more ticks, none of which may add anything.
		settle(300);

		assertEquals("a countdown of a second and a fifth was counted in with the wrong clips or"
				+ " the wrong number of them",
			Arrays.asList("beep.wav", "complete.wav"), harness.audioPlayer.played());
	}

	/**
	 * The setting, turned off. The run still chimes at zero, because that is
	 * the alert and it is a separate answer, and nothing is heard on the way
	 * there.
	 */
	@Test
	public void turningTheCountInOffLeavesTheChimeAtZeroAlone()
	{
		harness.config.setCountIn(false);

