		harness.onEdt(() -> harness.controller().start(HERB));

		waitFor("the chime at zero went with the count in", () -> !harness.audioPlayer.played().isEmpty());
		settle(300);

		assertEquals("the count in was turned off and was heard anyway",
			Collections.singletonList("complete.wav"), harness.audioPlayer.played());
	}

	/**
	 * The alert every user gets without changing a setting, which is the flash
	 * on the clock's own timer box.
	 *
	 * <p>The trap it is built over is that the ordinary timer box setting gives
	 * a clock a box only while it runs, and the moment worth flashing is the
	 * moment the run ends. Without something holding the box open, the tick
	 * that starts the alert is the same tick that takes its box away and the
	 * flash is never seen. Nothing here can read a colour, since that needs a
	 * frame to draw in, so what is checked is the box still being on the
	 * overlay manager after the run it belongs to has finished.
	 */
	@Test
	public void theBoxOfAClockThatJustFinishedIsHeldOpenLongEnoughToFlash()
	{
