		harness.startUp();

		harness.onEdt(() -> harness.controller().start(HERB));
		waitFor("the setup never got a timer box, so there is nothing to hold open",
			() -> harness.addedTimerBoxes().size() == 1);

		harness.onEdt(() -> harness.controller().stop(HERB));

		// Several ticks' worth, well inside the five second default.
		settle(300);

		assertTrue("the timer box of the clock that just finished was taken away while its alert was"
				+ " still running, so the flash a new user gets is never on screen. Removed "
				+ names(harness.removedTimerBoxes()),
			harness.removedTimerBoxes().isEmpty());
	}

	/**
	 * What a running box actually says, which nothing could read until the
	 * snapshot could be read without a frame to draw it in.
	 *
	 * <p>The bug it is written for is the one a user hits first. Splits were
	 * recorded correctly and shown in a finished run's history, and while the
	 * run was going the screen did not change when Lap was pressed, so the
	 * button read as broken.
	 */
	@Test
