	/**
	 * The two averages, on the idle box and on the card at the same moment,
	 * read from the same derivation so the two surfaces cannot disagree about
	 * the same runs.
	 *
	 * <p>Three runs, one of them slow, so the recent average and the all time
	 * average are the same number here and the point is that both surfaces
	 * carry both of them rather than one surface being left behind.
	 */
	@Test
	public void anIdleBoxAndItsCardSayTheSameTwoAverages()
	{
		harness.config.setOverlayVisibility(OverlayMode.ALWAYS);
		harness.storage.setStored(ClockworkHarness.routine(HERB, "Herb run"));
		harness.startUp();

		harness.onEdt(() ->
		{
			for (int i = 0; i < 3; i++)
			{
				harness.controller().start(HERB);
				harness.controller().stop(HERB);
			}
		});

		waitFor("an idle box never carried an average, so a user who set the boxes to always show"
				+ " has to open the side panel to read one",
			() -> box(HERB) != null && box(HERB).getAverageText() != null);

		assertNotNull("the box says how the clock has run recently and says nothing at all about"
				+ " how it has run all along",
			box(HERB).getAllTimeText());
		assertEquals("last 3", box(HERB).getAverageLabel());

		final List<String> labels = new ArrayList<>();
		collectLabels(panelRoot(), labels);
		final List<String> allTime = new ArrayList<>();
		for (String text : labels)
		{
			if (text != null && text.contains("All time "))
			{
				allTime.add(text);
			}
		}

		assertFalse("no card on the panel carries an all time average, so the card and the timer"
				+ " box next to it answer different questions about the same clock. Labels found, "
				+ labels,
			allTime.isEmpty());
		assertThat("the card says the all time average is over every run the clock has recorded",
			allTime.toString(), containsString("over 3"));
	}

	/**
	 * The split in progress on the card, which no version of this plugin has
	 * ever shown. It reads the same derivation the box does, so what is checked
	 * here is that the card really is on that path and that the line is not
	 * held open on a card with nothing to put in it.
	 */
	@Test
	public void aCardOnAClockWithSplitsSaysWhichSplitTheRunIsOn()
