		herb.setLapsEnabled(true);
		harness.storage.setStored(herb);
		harness.startUp();

		assertTrue("a card with nothing running already carries a split line, so every card down the"
				+ " panel holds a line open for a run that is not happening. Found " + splitLines(),
			splitLines().isEmpty());

		harness.onEdt(() -> harness.controller().start(HERB));
		waitFor("a clock with its splits on has been running and its card says nothing about the"
				+ " split in progress, so the panel and the timer box describe the same run"
				+ " differently",
			() -> !splitLines().isEmpty() && splitLines().get(0).startsWith("Lap 1"));

		harness.onEdt(() -> harness.controller().lap(HERB));
		waitFor("a split was taken and the card still says lap one",
			() -> !splitLines().isEmpty() && splitLines().get(0).startsWith("Lap 2"));
	}

	/**
	 * A clock's own alert setting beating the plugin wide one, in the direction
	 * that costs it an alert.
	 *
	 * <p>There is no colour to read without a frame, so what is read is the
	 * consequence. Under the ordinary timer box setting the box of a clock that
	 * just finished is held on screen for exactly as long as its flash lasts,
	 * so a clock that draws nothing gives its box straight back and a clock
	 * that flashes keeps it.
	 */
	@Test
	public void aClockThatSaysItWantsNoAlertGivesItsBoxStraightBack()
