		final Routine quiet = ClockworkHarness.routine(HERB, "Herb run");
		quiet.setAlert(AlertOverride.NONE);
		harness.storage.setStored(quiet);
		harness.startUp();

		harness.onEdt(() -> harness.controller().start(HERB));
		waitFor("the setup never got a timer box", () -> harness.addedTimerBoxes().size() == 1);

		harness.onEdt(() -> harness.controller().stop(HERB));
		settle(300);

		assertFalse("a clock told to draw no alert flashed anyway, because its box was held open the"
				+ " way a flashing one is, so the per clock setting is ignored and every clock still"
				+ " alerts together",
			harness.removedTimerBoxes().isEmpty());
	}

	/**
	 * And the other way. A clock that asks to flash gets one while the plugin
	 * wide setting draws nothing at all.
	 */
	@Test
	public void aClockThatAsksToFlashDoesSoWhileTheRestDrawNothing()
	{
		harness.config.setAlertStyle(AlertStyle.NONE);
		harness.config.setAlertSeconds(3);

		final Routine loud = ClockworkHarness.routine(HERB, "Herb run");
		loud.setAlert(AlertOverride.TIMER_BOX);
		harness.storage.setStored(loud);
		harness.startUp();

		harness.onEdt(() -> harness.controller().start(HERB));
		waitFor("the setup never got a timer box", () -> harness.addedTimerBoxes().size() == 1);

		harness.onEdt(() -> harness.controller().stop(HERB));
		settle(300);

		assertTrue("a clock that asked for a flash had its box taken away on the tick the run ended,"
