	}

	/**
	 * A hotkey, end to end, from the keybind in config to the run that starts.
	 *
	 * <p>{@code HotkeyTargetTest} covers the rule itself. This covers the parts
	 * around it that the rule cannot see. That the listeners really get
	 * registered with the key manager, that the keybind from config is what
	 * they match on, that the designation read out of storage at start up is
	 * the one they resolve to, and that the work lands on the controller after
	 * the hop to the event dispatch thread.
	 */
	@Test
	public void theStartHotkeyStartsTheDesignatedClockRatherThanTheBuiltInOne()
	{
		harness.storage.setStored(ClockworkHarness.routine(HERB, "Herb run"));
		harness.storage.setHotkeyTargetId(HERB);
		harness.startUp();

		assertEquals("the plugin registered a different number of key listeners than the three"
				+ " hotkeys it has, so this test is pressing the wrong things",
			3, harness.registeredKeyListeners().size());

		harness.pressHotkey(FakeClockworkConfig.START);

		assertTrue("the start hotkey did not reach the designated clock",
			harness.controller().isRunning(HERB));
		assertFalse("the start hotkey fell through to the built in clock even though a clock was"
				+ " designated, which is the bug that made the keys useless with the sidebar shut",
			harness.controller().isRunning(Routine.QUICK_ID));

		harness.pressHotkey(FakeClockworkConfig.STOP);
		assertFalse("the stop hotkey did not reach the designated clock",
			harness.controller().isRunning(HERB));
	}

	/**
	 * The same path with a designation that has gone stale, which is what a
	 * deleted clock leaves behind.
	 *
	 * <p>A dead designation must fall through to the next rule rather than
	 * stopping the key from doing anything, and it must be unset rather than
	 * left in config pointing at nothing.
	 */
	@Test
	public void aDesignationPointingAtNothingIsClearedAndTheKeyFallsThroughToTheBuiltInClock()
	{
		harness.storage.setStored(ClockworkHarness.routine(HERB, "Herb run"));
		harness.storage.setHotkeyTargetId("a-clock-this-profile-does-not-have");
		harness.startUp();

		harness.pressHotkey(FakeClockworkConfig.START);

		assertTrue("the key did nothing at all, when it should have fallen through to the built in"
				+ " clock", harness.controller().isRunning(Routine.QUICK_ID));
		assertFalse("the key started an unrelated clock", harness.controller().isRunning(HERB));
		assertNull("the dead designation is still in storage, pointing at a clock that is not there",
			harness.storage.hotkeyTargetId());
		assertTrue("the designation was dropped in memory but never unset in storage, so it comes"
				+ " back on the next restart. Writes, " + harness.storage.hotkeyTargetWrites(),
			harness.storage.hotkeyTargetWrites().contains(null));
	}

	/**
	 * The designation across a config profile switch, in both directions.
	 *
	 * <p>The designation is a config key, so it belongs to the profile it was
	 * read from. A profile that has the clock keeps it pointed there, and a
	 * profile that does not has it cleared rather than left naming a clock that
	 * is not in the list. The pure half of that is
	 * {@code HotkeyTarget.surviving}, which is tested on its own. What is
	 * covered here is that the reload calls it and writes the answer.
	 */
	@Test
	public void aDesignationTheProfileBeingEnteredDoesNotHaveIsCleared()
	{
		harness.storage.setStored(ClockworkHarness.routine(HERB, "Herb run"));
		harness.storage.setHotkeyTargetId(HERB);
		harness.startUp();

		// A profile that also has the designated clock keeps it, so the key
		// still lands where the user put it.
		harness.storage.setStored(ClockworkHarness.routine(HERB, "Herb run"),
			ClockworkHarness.routine(WINES, "Wine run"));
		harness.plugin.onProfileChanged(new ProfileChanged());
		harness.flushEdt();

		harness.pressHotkey(FakeClockworkConfig.START);
		assertTrue("a designation the profile being entered also has was thrown away, so the keys"
				+ " stopped acting on the clock the user chose",
			harness.controller().isRunning(HERB));
		harness.onEdt(() -> harness.controller().cancel(HERB));

		// And a profile that does not have it at all.
		harness.storage.setStored(ClockworkHarness.routine(WINES, "Wine run"));
		harness.plugin.onProfileChanged(new ProfileChanged());
		harness.flushEdt();

		assertNull("the designation still names a clock the profile being entered does not have, so"
				+ " the keys point at nothing and it comes back on the next restart",
			harness.storage.hotkeyTargetId());

		harness.pressHotkey(FakeClockworkConfig.START);
		assertTrue("with the designation cleared the key should fall through to the built in clock",
			harness.controller().isRunning(Routine.QUICK_ID));

		harness.shutDown();
		assertThat("the plugin cleared the designation and never said so, so a user whose keys have"
				+ " quietly moved has nothing in the log to explain it",
			harness.newDiagnosticsText(), containsString("clearing the designated hotkey clock"));
	}

	/**
	 * Every notification message the plugin has sent, in order.
	 */
	private List<String> notifications()
	{
		final ArgumentCaptor<String> captor = ArgumentCaptor.forClass(String.class);
		verify(harness.notifier, atLeast(0)).notify(any(Notification.class), captor.capture());
		return captor.getAllValues();
	}

	/**
	 * The event the plugin gets when the timer box setting moves. The key is
	 * named because the plugin filters on the group and reads the settings
	 * fresh, so the name is what a reader needs rather than what the code does.
	 */
	private static ConfigChanged visibilityChanged()
	{
		final ConfigChanged changed = new ConfigChanged();
		changed.setGroup(ClockworkConfig.GROUP);
		changed.setKey("overlayVisibility");
		return changed;
	}

	/**
	 * The trap this feature is built on top of.
	 *
	 * <p>RuneLite keys a saved overlay position on {@code getName()}, and the
	 * default answer is the simple class name. Two boxes answering the same
	 * name share one stored position, which reads to a user as two timer boxes
	 * stacked on each other that will not stay where they are put. It fails
	 * silently, nothing throws and nothing is logged, so the only place to
	 * catch it is here.
	 */
	@Test
	public void eachTimerBoxKeepsItsOwnSavedPosition()
	{
		harness.storage.setStored(
			ClockworkHarness.routine(HERB, "Herb run"),
			ClockworkHarness.routine(WINES, "Wine run"));
		harness.startUp();

		harness.onEdt(() ->
		{
			harness.controller().start(HERB);
			harness.controller().start(WINES);
		});
		waitFor("the setup never got two timer boxes on screen, so there is no pair to compare",
			() -> harness.addedTimerBoxes().size() >= 2);

		final List<Overlay> boxes = harness.addedTimerBoxes();
		final Set<String> distinct = new HashSet<>(names(boxes));

		assertEquals("two timer boxes answered the same name, so RuneLite files both of their"
				+ " positions under one key and neither box stays where it is dragged. Names, "
				+ names(boxes),
			boxes.size(), distinct.size());
	}

	/**
	 * What RuneLite files an overlay's saved position under, which is the only
	 * part of a box readable without a frame to draw in.
	 */
	private static List<String> names(List<Overlay> boxes)
	{
		final List<String> found = new ArrayList<>();
		for (Overlay box : boxes)
		{
			found.add(box.getName());
		}
		return found;
	}

	/**
	 * The refresh, which now has two speeds.
	 *
	 * <p>With no clock running and the side panel shut, there is nothing that
	 * changes between one tick and the next, so the timer
	 * drops to a slow period. The bug that costs is the other half. Every path
	 * that starts something moving has to put it back on the fast one, and a
	 * path that forgets shows up as a clock that starts and then does not
	 * visibly move for half a second.
	 *
	 * <p>The drop is waited for rather than forced, because the real Swing
	 * timer is what decides it and a test that reached in and called the tick
	 * would be testing something else. The wake up is not waited for at all,
	 * which is the point of it.
	 */
	@Test
	public void theRefreshSlowsDownWhenNothingMovesAndWakesWhenAClockStarts()
	{
		harness.storage.setStored(ClockworkHarness.routine(HERB, "Herb run"));
		harness.startUp();

		waitFor("the refresh never slowed down with nothing running and the panel shut, so it is doing"
			+ " a tick's work twenty times a second forever",
			() -> harness.plugin.refreshDelayMillis() > 100);

		harness.onEdt(() -> harness.controller().start(HERB));

		assertTrue("a clock started and the refresh was left on its slow period, so the timer on screen"
				+ " will not move until the next slow tick. Delay is "
				+ harness.plugin.refreshDelayMillis() + "ms",
			harness.plugin.refreshDelayMillis() <= 50);

		// And the same going the other way. A cancelled run leaves nothing
		// moving, so it settles back down on its own.
		harness.onEdt(() -> harness.controller().cancel(HERB));
		waitFor("the refresh stayed fast after the last run was cancelled",
			() -> harness.plugin.refreshDelayMillis() > 100);
	}

	/**
	 * A display setting moved, and the numbers it is drawn with follow.
	 *
	 * <p>The bug this was written for. {@code onConfigChanged} used to call
	 * {@code wake()} and nothing else, which puts the refresh back on its fast
	 * period and so redraws the running clock. Everything else on a card, the
	 * Best line, the Average line, the Last line, and any open history rows, is
	 * only ever written by a panel rebuild, and no rebuild was asked for. So a
	 * user who changed a display setting saw the live clock change and the
	 * derived numbers underneath it stay in the format or the window they were
	 * last drawn in, until something unrelated rebuilt the panel. Nothing threw
	 * and nothing was logged.
	 *
	 * <p>Average over is the setting used here because it is the one whose
	 * effect is visible without a stopwatch. The Average line names the number
	 * of runs it was taken over, so moving the window from two runs to one
	 * changes the text, and the text is read straight off the label the user
	 * would be looking at.
	 */
	@Test
	public void aDisplaySettingChangeRedrawsTheDerivedNumbers()
	{
		harness.storage.setStored(ClockworkHarness.routine(HERB, "Herb run"));
		harness.startUp();

		// Two finished runs, so the average has a window wide enough to narrow.
		harness.onEdt(() ->
		{
			harness.controller().start(HERB);
			harness.controller().stop(HERB);
			harness.controller().start(HERB);
			harness.controller().stop(HERB);
		});

		final String before = averageLines();
		assertThat("the setup did not produce an average to look at, so the rest of this proves"
				+ " nothing. Card read as, " + before,
			before, containsString("over 2"));

		harness.config.setAverageWindow(1);
		harness.plugin.onConfigChanged(new ConfigChanged());
		harness.flushEdt();
		assertEquals("a config change from another plugin's group must not redraw anything here",
			before, averageLines());

		final ConfigChanged ours = new ConfigChanged();
		ours.setGroup(ClockworkConfig.GROUP);
		ours.setKey("averageWindow");
		harness.plugin.onConfigChanged(ours);
		harness.flushEdt();

		assertThat("the setting moved and the card still shows the old average window, so every"
				+ " derived number on screen is stale until something else rebuilds the panel."
				+ " Card reads, " + averageLines(),
			averageLines(), containsString("over 1"));
	}

	/**
	 * What one clock's timer box will draw next frame, or null while it has not
	 * got a box or has not been given anything to draw.
	 *
	 * <p>This is the only way to read what a box says without a frame to render
	 * one in, which is why the tests above could only ever count boxes before.
	 */
	private OverlaySnapshot box(String routineId)
	{
		final String wanted = "clockwork_" + routineId;
		for (Overlay overlay : harness.addedTimerBoxes())
		{
			if (overlay instanceof RoutineOverlay && wanted.equals(overlay.getName()))
			{
				return ((RoutineOverlay) overlay).getSnapshot();
			}
		}
		return null;
	}

	/**
	 * Every split line on the panel, which is the line a running clock with its
	 * splits on puts under its time.
	 *
	 * <p>Read from the labels rather than from the card, the same way the
	 * average lines are, so it says what a user would see. A card with nothing
	 * to say leaves the text empty rather than hidden with something stale in
	 * it, so an empty answer here really is an empty line.
	 */
	private List<String> splitLines()
	{
		final List<String> found = new ArrayList<>();
		collectLabels(panelRoot(), found);

		final List<String> splits = new ArrayList<>();
		for (String text : found)
		{
			if (text != null && text.startsWith("Lap "))
			{
				splits.add(text);
			}
		}
		return splits;
	}

	/**
	 * The side panel the plugin really put on the toolbar.
	 */
	private Container panelRoot()
	{
		final List<NavigationButton> buttons = harness.addedNavigation();
		assertFalse("the side panel was never put on the toolbar, so there is nothing to read",
			buttons.isEmpty());
		return buttons.get(buttons.size() - 1).getPanel();
	}

	/**
	 * Every Average line on the panel, read the way a user reads them, by
	 * looking at what is drawn.
	 *
	 * <p>All of them rather than one, because the built in Quick clock is
	 * always pinned above the clock a test made and has an Average line of its
	 * own. Only a clock with finished runs behind it names a window, so a
	 * caller can look for that without caring which card it came from.
	 */
	private String averageLines()
	{
		final List<String> found = new ArrayList<>();
		collectLabels(panelRoot(), found);

		final List<String> averages = new ArrayList<>();
		for (String text : found)
		{
			if (text != null && text.contains("Average "))
			{
				averages.add(text);
			}
		}

		assertFalse("no label on the panel mentions an average, so this is not reading the cards."
				+ " Labels found, " + found,
			averages.isEmpty());
		return averages.toString();
	}

	/**
	 * The expanded history, which is now two labelled lists rather than one.
	 *
	 * <p>A clock keeps its newest ten and its fastest ten, so a single
	 * undifferentiated list would be a mix of the two with nothing to say which
	 * run was there for which reason, and an old record sitting among recent
	 * runs would look like a run that happened yesterday.
	 */
	@Test
	public void theExpandedHistoryReadsAsRecentAndBest()
	{
		harness.startUp();

		// The built in clock, because it is pinned to the top of the panel and
		// so its card is the first one every helper below reaches.
		harness.onEdt(() ->
		{
			for (int i = 0; i < 3; i++)
			{
				harness.controller().start(Routine.QUICK_ID);
				harness.controller().stop(Routine.QUICK_ID);
			}
		});

		waitFor("the setup never produced a history button with runs behind it",
			() -> button("History (") != null && button("History (").isEnabled());

		harness.onEdt(() -> button("History (").doClick());
		harness.flushEdt();

		final List<String> labels = new ArrayList<>();
		collectLabels(panelRoot(), labels);

		assertTrue("the expanded history has no Recent heading, so a user cannot tell which runs"
				+ " are there because they just happened. Labels found, " + labels,
			labels.contains("Recent"));
		assertTrue("and no Best heading, so the runs kept for being records read as recent ones",
			labels.contains("Best"));
	}

	/**
	 * The first button on the panel whose text starts with the given text, or
	 * null when there is not one yet.
	 */
	private JButton button(String startsWith)
	{
		return findButton(panelRoot(), startsWith);
	}

	private static JButton findButton(Container root, String startsWith)
	{
		for (Component child : root.getComponents())
		{
			if (child instanceof JButton
				&& ((JButton) child).getText() != null
				&& ((JButton) child).getText().startsWith(startsWith))
			{
				return (JButton) child;
			}
			if (child instanceof Container)
			{
				final JButton found = findButton((Container) child, startsWith);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	private static void collectLabels(Container root, List<String> into)
	{
		for (Component child : root.getComponents())
		{
			if (child instanceof JLabel)
			{
				into.add(((JLabel) child).getText());
			}
			if (child instanceof Container)
			{
				collectLabels((Container) child, into);
			}
		}
	}

	/**
	 * Lets the running plugin tick for a while and asserts nothing.
	 *
	 * <p>The opposite of {@link #waitFor}, and used where the thing being
	 * checked is that something does not happen again. There is no state to
	 * poll for an event that must not arrive, so the only honest test is to
	 * give the refresh room to make the mistake.
	 */
	private void settle(long millis)
	{
		final long deadline = System.currentTimeMillis() + millis;
		while (System.currentTimeMillis() < deadline)
		{
			harness.flushEdt();
		}
	}

	/**
	 * Waits for something the running plugin will do on its own, and fails
	 * saying what it was still waiting for rather than hanging.
	 */
	private void waitFor(String message, BooleanSupplier condition)
	{
		final long deadline = System.currentTimeMillis() + 5_000;
		while (System.currentTimeMillis() < deadline)
		{
			harness.flushEdt();
			if (condition.getAsBoolean())
			{
				return;
			}
		}
		throw new AssertionError(message);
	}
}

package com.clockwork;

import com.clockwork.core.OverlayMode;
import com.clockwork.core.Run;
import com.clockwork.core.RunHistory;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.List;
import net.runelite.client.config.ConfigManager;
import static org.junit.Assert.assertEquals;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Moving what a user has stored from one config key to another without costing
 * them any of it.
 *
 * <p>Two moves live here. The timer box setting went from a boolean to a three
 * way choice, and the recorded runs went from one key holding every clock's runs
 * to a key per clock. They have nothing to do with each other except the shape
 * of the problem, which is the reason they share a file.
 *
 * <p>A config key is not the versioned blob. It carries no stamp, nothing reads
 * a version off it, and there is no salvage path underneath it. Rename one with
 * nothing to carry the old value across and every user silently goes back to
 * the default, which for the timer boxes means a user who deliberately turned
 * them off finds them switched back on after an automatic update they never
 * asked for.
 *
 * <p>{@link ClockworkStorageTest} pins what the old value means under the new
 * setting, which is pure and needs nothing behind it. This pins the three
 * branches around that mapping, which do need a config manager, so it is a file
 * of its own rather than a mock dropped into a class that deliberately has
 * none.
 *
 * <p>{@code ConfigManager} is mocked for the same reason the wiring harness
 * mocks three other collaborators. It is a concrete class with a wide
 * constructor, there is no interface behind it, and the plugin injects it as a
 * class. Mockito lives in the test source set alone and never reaches the hub.
 */
public class ConfigKeyMigrationTest
{
	private static final String GROUP = ClockworkConfig.GROUP;

	/**
	 * Where the setting lives now, and where it lived in the first published
	 * build. Spelled out here rather than read off the storage class, because a
	 * test that asked the code under test what the keys were could not catch a
	 * key being renamed.
	 */
	private static final String NEW_KEY = "overlayVisibility";
	private static final String OLD_KEY = "showTimerBox";

	/**
	 * Where the recorded runs live now, one key per clock, and the one key they
	 * all shared up to and including the fifth published build.
	 */
	private static final String HISTORY_PREFIX = "history_";

	/**
	 * Where the average window setting lives, spelled out for the same
	 * reason.
	 */
	private static final String AVERAGE_WINDOW_KEY = "averageWindow";
	private static final String OLD_HISTORY_KEY = "history";

	private static final Gson GSON = new Gson();

	private ConfigManager configManager;
	private ClockworkStorage storage;

	@Before
	public void setUp()
	{
		configManager = mock(ConfigManager.class);
		storage = new ClockworkStorage(configManager, GSON);
	}

	/**
	 * The user this whole method exists for.
	 */
	@Test
	public void aUserWhoTurnedTheBoxesOffKeepsThemOff()
	{
		when(configManager.getConfiguration(GROUP, OLD_KEY)).thenReturn("false");

		storage.migrateOverlayVisibility();

		verify(configManager).setConfiguration(GROUP, NEW_KEY, OverlayMode.NEVER);
		verify(configManager).unsetConfiguration(GROUP, OLD_KEY);
	}

	/**
	 * And the user who had them on, who has to end up looking at exactly what
	 * they were looking at before the update rather than at an idle box on
	 * every clock they own.
	 */
	@Test
	public void aUserWhoHadTheBoxesOnGetsTheSettingThatDrawsWhatTheyAlreadySaw()
	{
		when(configManager.getConfiguration(GROUP, OLD_KEY)).thenReturn("true");

		storage.migrateOverlayVisibility();

		verify(configManager).setConfiguration(GROUP, NEW_KEY, OverlayMode.WHILE_RUNNING);
		verify(configManager).unsetConfiguration(GROUP, OLD_KEY);
	}

	/**
	 * A user who never touched the old setting has nothing to carry across, and
	 * writing one for them would pin them to today's default forever instead of
	 * letting the default move.
	 */
	@Test
	public void aUserWhoNeverTouchedTheOldSettingIsLeftAlone()
	{
		storage.migrateOverlayVisibility();

		verify(configManager, never()).setConfiguration(anyString(), anyString(), any());
		verify(configManager, never()).unsetConfiguration(GROUP, OLD_KEY);
	}

	/**
	 * The second run, and every run after it. This is called on every start up,
	 * so a body that did its work twice would overwrite whatever the user had
	 * chosen since with whatever a long dead boolean used to say.
	 */
	@Test
	public void aUserWhoHasAlreadyChosenUnderTheNewSettingIsNotMovedAgain()
	{
		when(configManager.getConfiguration(GROUP, NEW_KEY)).thenReturn("ALWAYS");
		when(configManager.getConfiguration(GROUP, OLD_KEY)).thenReturn("false");

		storage.migrateOverlayVisibility();

		verify(configManager, never()).setConfiguration(anyString(), anyString(), any());
		verify(configManager, never()).unsetConfiguration(GROUP, OLD_KEY);
	}

	/**
	 * A key that has been unset reads back as an empty string on some paths and
	 * as null on others, and neither is a choice the user made.
	 */
	@Test
	public void aBlankIsTheSameAsAbsentInBothDirections()
	{
		when(configManager.getConfiguration(GROUP, NEW_KEY)).thenReturn("  ");
		when(configManager.getConfiguration(GROUP, OLD_KEY)).thenReturn("false");

		storage.migrateOverlayVisibility();

		verify(configManager).setConfiguration(GROUP, NEW_KEY, OverlayMode.NEVER);
	}

	/**
	 * The plugin swallows on purpose, everywhere, so that no entry point can
	 * take the client down with it. A config manager that throws must not stop
	 * a plugin starting.
	 */
	@Test
	public void aConfigManagerThatThrowsDoesNotStopThePluginStarting()
	{
		when(configManager.getConfiguration(GROUP, NEW_KEY))
			.thenThrow(new IllegalStateException("no profile"));

		storage.migrateOverlayVisibility();
	}

	// The average window, brought into a range that is now shorter

	/**
	 * The user this third move exists for. The window used to go up to fifty,
	 * because a clock used to keep its newest fifty runs, and it keeps its
	 * newest ten now.
	 *
	 * <p>Leaving thirty stored would have meant a config panel reading thirty
	 * and an average taken over ten, with nothing on screen to say so. A
	 * setting that says one thing and does another is worse than a setting that
	 * changed, so it is changed and it is visible.
	 */
	@Test
	public void aWindowSetPastWhatAClockNowKeepsIsBroughtDown()
	{
		when(configManager.getConfiguration(GROUP, AVERAGE_WINDOW_KEY)).thenReturn("30");

		storage.clampAverageWindow();

		verify(configManager).setConfiguration(GROUP, AVERAGE_WINDOW_KEY,
			String.valueOf(RunHistory.RECENT_KEPT));
	}

	/**
	 * Everybody else, which is everybody who never touched it and everybody who
	 * had it at ten or below. They see nothing at all, and nothing is written,
	 * so a user who never opened the setting is not pinned to today's default.
	 */
	@Test
	public void aWindowThatIsAlreadyInRangeIsLeftExactlyWhereItIs()
	{
		storage.clampAverageWindow();
		verify(configManager, never()).setConfiguration(anyString(), anyString(), any());

		when(configManager.getConfiguration(GROUP, AVERAGE_WINDOW_KEY)).thenReturn("4");
		storage.clampAverageWindow();
		verify(configManager, never()).setConfiguration(anyString(), anyString(), any());

		when(configManager.getConfiguration(GROUP, AVERAGE_WINDOW_KEY))
			.thenReturn(String.valueOf(RunHistory.RECENT_KEPT));
		storage.clampAverageWindow();
		verify(configManager, never()).setConfiguration(anyString(), anyString(), any());
	}

	/**
	 * Called on every start up, so the second run has to be a no operation.
	 * After the first one the stored value is in range and there is nothing
	 * left to do.
	 */
	@Test
	public void bringingTheWindowDownHappensOnceAndStays()
	{
		when(configManager.getConfiguration(GROUP, AVERAGE_WINDOW_KEY)).thenReturn("50");
		storage.clampAverageWindow();

		when(configManager.getConfiguration(GROUP, AVERAGE_WINDOW_KEY))
			.thenReturn(String.valueOf(RunHistory.RECENT_KEPT));
		storage.clampAverageWindow();

		verify(configManager, times(1)).setConfiguration(GROUP, AVERAGE_WINDOW_KEY,
			String.valueOf(RunHistory.RECENT_KEPT));
	}

	/**
	 * A stored value that is not a number is left alone. RuneLite answers the
	 * default for one of those, so it is already being read as ten, and writing
	 * over it would be this method inventing a setting rather than carrying
	 * one. A blank is the same as absent, as everywhere else here.
	 */
	@Test
	public void aWindowThatIsNotANumberIsLeftAlone()
	{
		when(configManager.getConfiguration(GROUP, AVERAGE_WINDOW_KEY)).thenReturn("lots");
		storage.clampAverageWindow();

		when(configManager.getConfiguration(GROUP, AVERAGE_WINDOW_KEY)).thenReturn("   ");
		storage.clampAverageWindow();

		verify(configManager, never()).setConfiguration(anyString(), anyString(), any());
	}

	@Test
	public void aConfigManagerThatThrowsDoesNotStopTheWindowBeingRead()
	{
		when(configManager.getConfiguration(GROUP, AVERAGE_WINDOW_KEY))
			.thenThrow(new IllegalStateException("no profile"));

		storage.clampAverageWindow();
	}

	// The recorded runs, off one shared key and onto a key per clock

	/**
	 * The user this second move exists for. Every clock's runs came out of the
	 * one key they shared, went onto a key of their own, and the shared key was
	 * let go.
	 */
	@Test
	public void everyClocksRunsAreMovedOntoAKeyOfTheirOwn()
	{
		when(configManager.getConfiguration(GROUP, OLD_HISTORY_KEY)).thenReturn(
			"{\"herb-id\":[{\"durationMillis\":1200},{\"durationMillis\":1300}],"
				+ "\"tree-id\":[{\"durationMillis\":300}]}");

		storage.migrateHistory();

		final ArgumentCaptor<String> keys = ArgumentCaptor.forClass(String.class);
		final ArgumentCaptor<String> values = ArgumentCaptor.forClass(String.class);
		verify(configManager, times(2)).setConfiguration(eq(GROUP), keys.capture(), values.capture());

		assertEquals(Arrays.asList(HISTORY_PREFIX + "herb-id", HISTORY_PREFIX + "tree-id"),
			keys.getAllValues());

		// Decoded rather than compared as text, because what has to survive the
		// move is the runs and not one particular spelling of them.
		assertEquals(2, ClockworkStorage.decodeRuns(GSON, values.getAllValues().get(0)).size());
		assertEquals(1200L, ClockworkStorage.decodeRuns(GSON, values.getAllValues().get(0))
			.get(0).getDurationMillis());
		assertEquals(1300L, ClockworkStorage.decodeRuns(GSON, values.getAllValues().get(0))
			.get(1).getDurationMillis());
		assertEquals(300L, ClockworkStorage.decodeRuns(GSON, values.getAllValues().get(1))
			.get(0).getDurationMillis());

		verify(configManager).unsetConfiguration(GROUP, OLD_HISTORY_KEY);
	}

	/**
	 * A clock named in the old key with nothing recorded against it. It needs no
	 * key, because a clock with no runs has none, and writing one would leave an
	 * empty list in the config for every clock a user ever made.
	 */
	@Test
	public void aClockWithNothingRecordedGetsNoKey()
	{
		when(configManager.getConfiguration(GROUP, OLD_HISTORY_KEY))
			.thenReturn("{\"fresh-id\":[],\"herb-id\":[{\"durationMillis\":1200}]}");

		storage.migrateHistory();

		verify(configManager, times(1)).setConfiguration(eq(GROUP), anyString(), anyString());
		verify(configManager).setConfiguration(eq(GROUP), eq(HISTORY_PREFIX + "herb-id"), anyString());
		verify(configManager).unsetConfiguration(GROUP, OLD_HISTORY_KEY);
	}

	/**
	 * The second start up, and every one after it. This runs on every load, so a
	 * run already on the clock's own key must not be written a second time and
	 * the user's history must not grow by a copy of itself each time they start
	 * the client.
	 *
	 * <p>Nothing is written at all here, rather than the same value being
	 * written back. A config value is uploaded whole when it changes, so a load
	 * that rewrote every clock's runs would put all of them in the next sync for
	 * no gain.
	 */
	@Test
	public void aRunUnderBothKeysIsKeptOnceAndWritesNothing()
	{
		final String sameRun = "{\"startedAtEpochMillis\":100,\"finishedAtEpochMillis\":1300,"
			+ "\"durationMillis\":1200}";
		when(configManager.getConfiguration(GROUP, OLD_HISTORY_KEY))
			.thenReturn("{\"herb-id\":[" + sameRun + "]}");
		when(configManager.getConfiguration(GROUP, HISTORY_PREFIX + "herb-id"))
			.thenReturn("[" + sameRun + "]");

		storage.migrateHistory();

		verify(configManager, never()).setConfiguration(anyString(), anyString(), anyString());

		// And the old key still goes, because everything under it is accounted
		// for. Leaving it would mean reading it again on every load forever.
		verify(configManager).unsetConfiguration(GROUP, OLD_HISTORY_KEY);
	}

	/**
	 * The state this method was rewritten for, off a real profile. One clock has
	 * runs under both layouts at once and the old key holds the newer of them.
	 *
	 * <p>The old code stopped as soon as any clock had a key of its own, so this
	 * user's newest run was read by nothing, drawn by nothing, and sat in their
	 * config where they could see it while the panel said the clock had no runs
	 * at all. There is no other copy of it anywhere.
	 */
	@Test
	public void runsUnderBothKeysAtOnceAreBroughtTogetherRatherThanSkipped()
	{
		when(configManager.getConfiguration(GROUP, OLD_HISTORY_KEY)).thenReturn(
			"{\"herb-id\":[{\"startedAtEpochMillis\":3000,\"finishedAtEpochMillis\":3900,"
				+ "\"durationMillis\":900}]}");
		when(configManager.getConfiguration(GROUP, HISTORY_PREFIX + "herb-id")).thenReturn(
			"[{\"startedAtEpochMillis\":1000,\"finishedAtEpochMillis\":2000,\"durationMillis\":1000}]");

		storage.migrateHistory();

		final ArgumentCaptor<String> value = ArgumentCaptor.forClass(String.class);
		verify(configManager).setConfiguration(eq(GROUP), eq(HISTORY_PREFIX + "herb-id"),
			value.capture());

		final List<Run> written = ClockworkStorage.decodeRuns(GSON, value.getValue());
		assertEquals("a clock with runs under both keys lost one set of them", 2, written.size());
		assertEquals("the runs came back in an order that is not oldest first, so the newest run is"
				+ " not the one at the end and every reader of the list is wrong about it",
			1000L, written.get(0).getStartedAtEpochMillis());
		assertEquals(3000L, written.get(1).getStartedAtEpochMillis());

		verify(configManager).unsetConfiguration(GROUP, OLD_HISTORY_KEY);
	}

	/**
	 * A fresh install, and a user who has never recorded a run. Nothing to carry
	 * across and nothing to take away.
	 */
	@Test
	public void aUserWithNoRecordedRunsIsLeftAlone()
	{
		storage.migrateHistory();

		verify(configManager, never()).setConfiguration(anyString(), anyString(), anyString());
		verify(configManager, never()).unsetConfiguration(GROUP, OLD_HISTORY_KEY);
	}

	/**
	 * A move where one clock could not be written, which is what an id nothing
	 * can spell as a config key looks like. The clocks that could be written are
	 * written, and the old key stays exactly where it is, because letting it go
	 * would be losing the runs of the clock that failed.
	 */
	@Test
	public void aMoveThatWasPartlyRefusedKeepsTheOldKey()
	{
		when(configManager.getConfiguration(GROUP, OLD_HISTORY_KEY)).thenReturn(
			"{\"bad:id\":[{\"durationMillis\":1}],\"herb-id\":[{\"durationMillis\":1200}]}");
		doThrow(new IllegalArgumentException("a config key cannot hold that"))
			.when(configManager).setConfiguration(eq(GROUP), eq(HISTORY_PREFIX + "bad:id"), anyString());

		storage.migrateHistory();

		verify(configManager).setConfiguration(eq(GROUP), eq(HISTORY_PREFIX + "herb-id"), anyString());
		verify(configManager, never()).unsetConfiguration(GROUP, OLD_HISTORY_KEY);
	}

	/**
	 * The same rule as the setting above. A config manager that throws must not
	 * stop a plugin starting, and this one runs on the way into every load.
	 */
	@Test
	public void aConfigManagerThatThrowsDoesNotStopTheRunsBeingRead()
	{
		when(configManager.getConfiguration(GROUP, OLD_HISTORY_KEY))
			.thenThrow(new IllegalStateException("no profile"));

		storage.migrateHistory();
	}

	/**
	 * A clock whose own key cannot be read at the moment the old key is being
	 * brought in. The clocks that could be read are written, and the old key
	 * stays, so the clock that failed is tried again on the next load rather
	 * than being left with the old key gone from under it.
	 */
	@Test
	public void aClockWhoseOwnKeyCannotBeReadKeepsTheOldKeyForTheNextLoad()
	{
		when(configManager.getConfiguration(GROUP, OLD_HISTORY_KEY)).thenReturn(
			"{\"unreadable-id\":[{\"durationMillis\":1}],\"herb-id\":[{\"durationMillis\":1200}]}");
		when(configManager.getConfiguration(GROUP, HISTORY_PREFIX + "unreadable-id"))
			.thenThrow(new IllegalStateException("no profile"));

		storage.migrateHistory();

		verify(configManager).setConfiguration(eq(GROUP), eq(HISTORY_PREFIX + "herb-id"), anyString());
		verify(configManager, never()).unsetConfiguration(GROUP, OLD_HISTORY_KEY);
	}
}

package com.clockwork;

import com.clockwork.core.Routine;
import com.clockwork.core.TriggerLibrary;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The register of damaged documents, and what each kind of damage actually
 * costs.
 *
 * <p>This is the only part of the plugin that takes text a person pasted in
 * from somewhere else. Everything else reacts to the game or to a button, so
 * this is where input arrives that nothing in this codebase wrote and nothing
 * in this codebase can vouch for. A reader of untrusted text has exactly two
 * ways to be wrong. It can refuse something it could have read, which costs
 * somebody the document they were handed, and it can accept something it should
 * not have, which costs them a clock that looks configured and never fires.
 *
 * <p>So every case below asserts what the code does rather than what it ought
 * to do. Where a kind of damage costs one clock, that is written down as the
 * behaviour, so a later change cannot quietly make the loss wider or narrower
 * without a test going red. Two of them are pinned as known leniencies rather
 * than as good outcomes, and they say so.
 *
 * <p>{@link DocumentProblemTest} covers the wording and the locations. This
 * file covers the verdicts.
 */
public class DamagedDocumentTest
{
	private static final Gson GSON = new Gson();

	private final TriggerLibrary library = TriggerLibrary.empty();

	private ClockworkDocument.Imported read(String json)
	{
		return ClockworkDocument.read(GSON, json, library);
	}

	private String said(String json)
	{
		return DocumentProblem.lines(read(json).getProblems());
	}

	/**
	 * Everything the read produced, as one line each, plus how many clocks
	 * arrived and how many did not.
	 */
	private String register(String json)
	{
		final ClockworkDocument.Imported imported = read(json);
		return (imported.isOk() ? "read" : "refused")
			+ ", " + imported.getAdded().size() + " added"
			+ ", " + DocumentProblem.skippedCount(imported.getProblems()) + " skipped";
	}

	// Nothing to read at all

	@Test
	public void anEmptyBoxIsRefusedAsAnEmptyBox()
	{
		for (String nothing : Arrays.asList(null, "", "   ", "\n\t "))
		{
			assertEquals("refused, 0 added, 0 skipped", register(nothing));
			assertEquals("There is nothing to read. Paste a Clockwork document first.", said(nothing));
		}
	}

	/**
	 * Three different shapes of "this is not a document", worded the same way
	 * on purpose. Somebody who pasted the wrong thing entirely does not need a
	 * parser's opinion, they need to know what should have been there.
	 */
	@Test
	public void somethingThatIsNotADocumentSaysWhatADocumentIs()
	{
		for (String wrong : Arrays.asList("null", "not json at all", "[1,2,3]", "\"a string\"", "7"))
		{
			assertEquals("refused for " + wrong, "refused, 0 added, 0 skipped", register(wrong));
			assertTrue(said(wrong), said(wrong).startsWith("That is not a Clockwork document."));
		}
	}

	// Damage the parser finds before anything binds

	@Test
	public void aTruncatedDocumentIsRefusedAndSaysWhereItStopped()
	{
		final String cut = "{\"version\":1,\"routines\":[{\"name\":\"Herb run\"}]";

		assertEquals("refused, 0 added, 0 skipped", register(cut));
		assertEquals("Line 1, column 46: the document stops here, which usually means a bracket"
			+ " or a brace is missing", said(cut));
	}

	/**
	 * Text after the closing brace, which is what pasting a document twice
	 * looks like.
	 *
	 * <p>The wording is the generic one, because Gson's own complaint about
	 * this names a class and a method and nothing out of a library is ever put
	 * in front of somebody. The location is the part that matters and the
	 * location is right, so it points at the first character that should not be
	 * there.
	 */
	@Test
	public void trailingGarbageIsRefusedAndPointsAtIt()
	{
		final String extra = "{\"version\":1,\"routines\":[{\"name\":\"Herb run\"}]} and then some";

		assertEquals("refused, 0 added, 0 skipped", register(extra));
		assertEquals("Line 1, column 49: the reader could not make sense of this", said(extra));
	}

	// Damage in the shape of the document

	@Test
	public void aDocumentWithNoClockListIsRefusedWhetherTheKeyIsMissingOrWrong()
	{
		for (String wrong : Arrays.asList("{\"version\":1}", "{\"version\":1,\"routines\":{}}",
			"{\"version\":1,\"routines\":\"none\"}", "{\"version\":1,\"routines\":null}"))
		{
			assertEquals("refused for " + wrong, "refused, 0 added, 0 skipped", register(wrong));
			assertEquals("That is not a Clockwork document. There is no list of clocks in it.", said(wrong));
		}
	}

	/**
	 * An empty clock list is a document rather than damage. It is what somebody
	 * who deleted every clock in the editor is trying to say, and the editor's
	 * confirm is what makes sure they mean it.
	 */
	@Test
	public void anEmptyDocumentIsReadRatherThanRefused()
	{
		assertEquals("read, 0 added, 0 skipped", register("{\"version\":1,\"routines\":[]}"));
		assertEquals("", said("{\"version\":1,\"routines\":[]}"));
	}

	/**
	 * A stamp above the one this build writes is the one thing that is refused
	 * outright rather than read as far as it goes, because it is the only case
	 * where the document can hold a shape this build has never seen.
	 */
	@Test
	public void aDocumentFromANewerBuildThatDoesNotSayIsRefused()
	{
		// No minVersion, so the version stands in for it and the strict answer
		// is the one given. A document that says nothing about who can read it
		// is treated as though only its own build can.
		final String newer = "{\"version\":2,\"routines\":[{\"name\":\"Herb run\"}]}";

		assertEquals("refused, 0 added, 0 skipped", register(newer));
		assertEquals("This document was written for a newer Clockwork than this one. It needs"
			+ " version 2 and this build is version 1. Update the plugin and try again.", said(newer));
	}

	@Test
	public void aDocumentFromANewerBuildThatSaysWeCanReadItIsRead()
	{
		// The reason the second number exists. Version 9 is far ahead of this
		// build, and that build says a version 1 reader gets it right, so the
		// clock arrives instead of the user being told to update for nothing.
		final String newer = "{\"version\":9,\"minVersion\":1,\"routines\":[{\"name\":\"Herb run\"}]}";

		assertEquals("read, 1 added, 0 skipped", register(newer));
	}

	@Test
	public void aDocumentFromANewerBuildThatSaysWeCannotIsRefused()
	{
		final String newer = "{\"version\":9,\"minVersion\":9,\"routines\":[{\"name\":\"Herb run\"}]}";

		assertEquals("refused, 0 added, 0 skipped", register(newer));
		assertEquals("This document was written for a newer Clockwork than this one. It needs"
			+ " version 9 and this build is version 1. Update the plugin and try again.", said(newer));
	}

	/**
	 * A stamp that is not a number reads as no stamp, which reads as older
	 * rather than newer, so the document is read. Being wrong in that direction
	 * costs nothing, and being wrong in the other one would cost somebody a
	 * document over a typo in a field they never look at.
	 */
	@Test
	public void aVersionThatIsNotANumberIsReadAsNoVersionAtAll()
	{
		for (String odd : Arrays.asList("{\"version\":\"one\",\"routines\":[{\"name\":\"Herb run\"}]}",
			"{\"version\":{},\"routines\":[{\"name\":\"Herb run\"}]}",
			"{\"routines\":[{\"name\":\"Herb run\"}]}"))
		{
			assertEquals("read for " + odd, "read, 1 added, 0 skipped", register(odd));
			assertEquals("", said(odd));
		}
	}

	// Damage inside one clock

	@Test
	public void anEntryThatIsNotAClockCostsThatClockAndNothingElse()
	{
		final String json = "{\"version\":1,\"routines\":[{\"name\":\"Herb run\"},[1,2],7,\"text\"]}";

		assertEquals("read, 1 added, 3 skipped", register(json));
		assertEquals("Clock 2: this is not a clock, it is a list, so it was skipped\n"
			+ "Clock 3: this is not a clock, it is 7, so it was skipped\n"
			+ "Clock 4: this is not a clock, it is \"text\", so it was skipped", said(json));
	}

	/**
	 * A literal null where a clock should be. It binds perfectly happily to a
	 * Java null, so nothing throws and nothing is wrong with the document as
	 * far as the parser is concerned, and everything downstream copies a clock
	 * rather than checking whether it is there.
	 */
	@Test
	public void aNullWhereAClockShouldBeIsCountedAsAClockThatDidNotArrive()
	{
		final String json = "{\"version\":1,\"routines\":[null]}";

		assertEquals("read, 0 added, 1 skipped", register(json));
		assertEquals("Clock 1: this is not a clock, it is nothing, so it was skipped", said(json));
	}

	/**
	 * And the clocks after it keep the numbers the user can count to in the
	 * text, whichever way the document was read.
	 */
	@Test
	public void aSkippedEntryDoesNotShiftTheNumbersOfTheOnesAfterIt()
	{
		assertEquals("Clock 1: this is not a clock, it is nothing, so it was skipped\n"
				+ "Clock 3 \"Wine run\", field targetMillis: expected a number, found \"soon\","
				+ " so this clock was skipped",
			said("{\"version\":1,\"routines\":[null,{\"name\":\"Herb run\"},"
				+ "{\"name\":\"Wine run\",\"targetMillis\":\"soon\"}]}"));
	}

	/**
	 * A number field holding text is the ordinary hand editing mistake. It
	 * costs that one clock, and the message names the field and quotes what is
	 * actually in it.
	 */
	@Test
	public void aFieldOfTheWrongTypeCostsThatClockAndNamesTheField()
	{
		final String json = "{\"version\":1,\"routines\":[{\"name\":\"Herb run\",\"targetMillis\":\"soon\"},"
			+ "{\"name\":\"Wine run\",\"abandonAfterMillis\":true},{\"name\":\"Tree run\"}]}";

		assertEquals("read, 1 added, 2 skipped", register(json));
		assertEquals("Clock 1 \"Herb run\", field targetMillis: expected a number, found \"soon\","
			+ " so this clock was skipped\n"
			+ "Clock 2 \"Wine run\", field abandonAfterMillis: expected a number, found true,"
			+ " so this clock was skipped", said(json));
	}

	/**
	 * A trigger of the wrong type costs the trigger rather than the clock. A
	 * clock that comes back waiting for nothing still has its name, its
	 * direction, and its target, which is a far smaller loss than the clock
	 * itself, and the user is told which end of it went.
	 */
	@Test
	public void aTriggerOfTheWrongTypeCostsTheTriggerAndNotTheClock()
	{
		final String json = "{\"version\":1,\"routines\":[{\"name\":\"Herb run\","
			+ "\"stopTrigger\":\"bankchest\"}]}";

		assertEquals("read, 1 added, 0 skipped", register(json));
		assertEquals("Clock 1 \"Herb run\", field stopTrigger: expected an object, found \"bankchest\","
			+ " so this clock arrives without the trigger it stopped on", said(json));
	}

	/**
	 * A known leniency, pinned so that it is a decision rather than a surprise.
	 *
	 * <p>Gson reads a boolean field holding a string by asking
	 * {@code Boolean.parseBoolean}, which answers false for anything that is
	 * not the word true. Nothing throws, so there is nothing for the reading to
	 * catch, and the value is not an enum so there is nothing for the review to
	 * check either. The clock arrives with the setting off.
	 *
	 * <p>It is the safe direction to be wrong in. Splits off is what the clock
	 * would have had if the key were absent, and the alternative is refusing a
	 * document over a field that has a sensible default.
	 */
	@Test
	public void aBooleanFieldHoldingTextIsReadAsFalseAndNothingIsSaid()
	{
		final String json = "{\"version\":1,\"routines\":[{\"name\":\"Herb run\",\"lapsEnabled\":\"yes\"}]}";

		assertEquals("read, 1 added, 0 skipped", register(json));
		assertEquals("", said(json));
		assertFalse(read(json).getAdded().get(0).isLapsEnabled());
	}

	// Damage across clocks

	/**
	 * Two clocks with one name is legal and is still worth saying, because
	 * clocks are matched by name when a document is applied as an edit, so the
	 * second one is what the user will find themselves editing.
	 */
	@Test
	public void twoClocksWithOneNameBothArriveAndTheSecondIsReported()
	{
		final String json = "{\"version\":1,\"routines\":[{\"name\":\"Herb run\"},{\"name\":\"herb run\"}]}";

		assertEquals("read, 2 added, 0 skipped", register(json));
		assertEquals("Clock 2 \"herb run\": another clock in this document is called this too,"
			+ " and clocks are matched by name", said(json));
	}

	/**
	 * The same document applied as an edit rather than imported. The first one
	 * takes the existing clock's id and its runs, the rest arrive as new
	 * clocks, and the user is told rather than left to work out why one of them
	 * has no history.
	 */
	@Test
	public void twoClocksWithOneNameOnAnAppliedEditKeepTheRunsOnTheFirst()
	{
		final Routine mine = new Routine("a", "Herb run");
		final ClockworkDocument.Applied applied = ClockworkDocument.readEdited(GSON,
			"{\"version\":1,\"routines\":[{\"name\":\"Herb run\"},{\"name\":\"Herb run\"}]}",
			Collections.singletonList(mine), library);

		assertTrue(applied.getProblem(), applied.isOk());
		assertEquals(2, applied.getRoutines().size());
		assertEquals("a", applied.getRoutines().get(0).getId());
		assertEquals(Collections.singletonList("Herb run"), applied.getAdded());
		assertTrue(applied.getNotes().get(0), applied.getNotes().get(0).contains("more than one clock"));
	}

	// Damage in the trigger library

	/**
	 * A library that is there but is not a list reads as no library at all, and
	 * nothing is said, because a document with no custom triggers in it is an
	 * ordinary document.
	 */
	@Test
	public void aTriggerLibraryThatIsNotAListReadsAsNoLibrary()
	{
		final String json = "{\"version\":1,\"triggers\":{},\"routines\":[{\"name\":\"Herb run\"}]}";

		assertEquals("read, 1 added, 0 skipped", register(json));
		assertEquals("", said(json));
	}

	/**
	 * A library that is a list of the wrong things is said out loud, because
	 * the clocks that pointed into it are about to be refused for pointing at
	 * nothing and the reason should not be a mystery.
	 */
	@Test
	public void aTriggerLibraryThatWillNotBindIsSaidOutLoud()
	{
		final String json = "{\"version\":1,\"triggers\":[3],\"routines\":[{\"name\":\"Herb run\"}]}";

		assertEquals("read, 1 added, 0 skipped", register(json));
		assertEquals("The custom triggers in this document could not be read, so none of them arrived"
			+ " and the clocks that waited for one now wait for nothing.", said(json));
	}

	/**
	 * The refusal that matters most, because it is the one that stops a clock
	 * arriving in a state where it looks configured and never starts.
	 */
	@Test
	public void aClockPointingAtATriggerTheDocumentDoesNotDefineIsRefused()
	{
		final String json = "{\"version\":1,\"triggers\":[3],\"routines\":[{\"name\":\"Herb run\","
			+ "\"startTrigger\":{\"type\":\"custom\",\"ref\":\"Note herbs\"}}]}";

		assertEquals("refused, 0 added, 0 skipped", register(json));
		assertEquals("The custom triggers in this document could not be read, so none of them arrived"
			+ " and the clocks that waited for one now wait for nothing.\n"
			+ "Clock 1 \"Herb run\": starts on a custom trigger called Note herbs,"
			+ " which this document does not define", said(json));
	}

	// Nothing out of a library is ever put in front of anybody

	@Test
	public void noRefusalEverQuotesTheParserAtTheUser()
	{
		final List<String> damaged = Arrays.asList("", "   ", "not json at all", "{\"version\":1,",
			"[1,2,3]", "null", "{\"version\":1,\"routines\":{}}", "{\"version\":9,\"routines\":[]}",
			"{\"version\":1,\"routines\":[{\"name\":\"Herb run\"}]} and then some");

		for (String json : damaged)
		{
			final ClockworkDocument.Imported imported = read(json);
			final String problem = imported.getProblem();

			assertFalse("expected a refusal for " + json, imported.isOk());
			assertFalse(problem, problem.contains("com.google"));
			assertFalse(problem, problem.contains("java."));
			assertFalse(problem, problem.contains("JsonReader"));
			assertFalse(problem, problem.contains("setLenient"));
			assertTrue("a refusal is still a sentence", problem.length() > 10);
		}
	}
}

package com.clockwork;

import com.clockwork.core.Routine;
import com.clockwork.core.TriggerLibrary;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * What a document says about itself when it is wrong.
 *
 * <p>The rule these tests exist to hold is the one sentence the whole change
 * was for. A document is read once, every problem in it is collected, and all
 * of them come back together. Somebody editing a page of JSON by hand should
 * never have to press Apply five times to be told about five mistakes, and the
 * test that matters most in this file is the one that pastes several different
 * mistakes into one document and counts what comes back.
 *
 * <p>The other half is that a location is attached to each one. What kind of
 * location is available depends entirely on how the failure happened, so the
 * tests are grouped by that rather than by which button is pressed. A parser
 * failure knows a line and a column. A binding failure knows a JSON path, which
 * is turned into a clock number and a field. Everything else is worked out here
 * and can say whatever it likes.
 */
public class DocumentProblemTest
{
	private static final Gson GSON = new Gson();

	private final TriggerLibrary library = TriggerLibrary.empty();

	private ClockworkDocument.Imported read(String json)
	{
		return ClockworkDocument.read(GSON, json, library);
	}

	/**
	 * Every problem as one string, which is what a test wants to search and
	 * what the user is shown.
	 */
	private String linesOf(String json)
	{
		return DocumentProblem.lines(read(json).getProblems());
	}

	// Syntax, which is the only kind that knows a line

	@Test
	public void aStraySeparatorSaysWhichLineAndColumn()
	{
		final ClockworkDocument.Imported imported = read("{\n"
			+ "  \"version\": 1,\n"
			+ "  \"routines\": [\n"
			+ "    {\"name\": \"Herb run\",,}\n"
			+ "  ]\n"
			+ "}");

		assertFalse("a document that will not parse is still refused", imported.isOk());
		assertEquals(1, imported.getProblems().size());

		final DocumentProblem problem = imported.getProblems().get(0);
		assertEquals("the line the stray comma is on", 4, problem.getLine());
		assertTrue("and a column to go with it", problem.getColumn() > 0);
		assertTrue(problem.describe(), problem.describe().startsWith("Line 4, column "));
		assertTrue(problem.describe(), problem.getDetail().contains("stray comma"));
	}

	@Test
	public void aDocumentThatStopsHalfWaySaysWhereItStopped()
	{
		final ClockworkDocument.Imported imported = read("{\n"
			+ "  \"version\": 1,\n"
			+ "  \"routines\": [\n"
			+ "    {\"name\": \"Herb run\"}");

		assertFalse(imported.isOk());
		assertEquals(4, DocumentProblem.firstLine(imported.getProblems()));
		assertTrue(DocumentProblem.lines(imported.getProblems()).contains("bracket or a brace"));
	}

	/**
	 * The line number is the whole reason the editor can put the caret on the
	 * trouble, so it is asked for the same way the editor asks for it.
	 */
	@Test
	public void theFirstLineIsWhatTheEditorJumpsTo()
	{
		assertEquals(0, DocumentProblem.firstLine(null));
		assertEquals(0, DocumentProblem.firstLine(Collections.emptyList()));
		assertEquals(0, DocumentProblem.firstLine(
			Collections.singletonList(DocumentProblem.inClock(2, "Herb run", "something"))));
		assertEquals(7, DocumentProblem.firstLine(Arrays.asList(
			DocumentProblem.inDocument("nowhere in particular"),
			DocumentProblem.at(7, 2, "here"),
			DocumentProblem.at(9, 1, "and here"))));
	}

	// Binding, which knows a clock and a field

	@Test
	public void aBadEnumValueNamesTheClockAndTheField()
	{
		final String said = linesOf("{\"version\":1,\"routines\":["
			+ "{\"name\":\"Zulrah trips\",\"mode\":\"countup!\"}]}");

		assertEquals("Clock 1 \"Zulrah trips\", field mode: expected countdown or countup,"
			+ " found \"countup!\"", said);
	}

	/**
	 * A value Gson quietly binds to null is the worst of the three kinds,
	 * because nothing throws and the clock looks configured. This is the one
	 * the plugin has to find for itself.
	 */
	@Test
	public void aBadEnumValueStillImportsTheClockAndSaysSo()
	{
		final ClockworkDocument.Imported imported = read("{\"version\":1,\"routines\":["
			+ "{\"name\":\"Zulrah trips\",\"mode\":\"countup!\"}]}");

		assertTrue("nothing about this stops the document being read", imported.isOk());
		assertEquals(1, imported.getAdded().size());
		assertEquals(1, imported.getProblems().size());
		assertFalse("a spelling nobody can act on is not a clock lost",
			imported.getProblems().get(0).isSkipped());
	}

	@Test
	public void aBadTriggerTypeNamesThePathToIt()
	{
		final String said = linesOf("{\"version\":1,\"routines\":[{\"name\":\"Herb run\","
			+ "\"startTrigger\":{\"type\":\"teleporting\"}}]}");

		assertTrue(said, said.startsWith("Clock 1 \"Herb run\", field startTrigger.type: expected "));
		assertTrue(said, said.contains("found \"teleporting\""));
		assertTrue("every value it would have taken is named", said.contains("teleport"));
	}

	/**
	 * A value of the wrong JSON type is what Gson does throw about, and the
	 * field it names comes back with the value the user actually typed rather
	 * than the name of a parser token.
	 */
	@Test
	public void aValueOfTheWrongShapeNamesTheFieldAndWhatIsInIt()
	{
		final String said = linesOf("{\"version\":1,\"routines\":["
			+ "{\"name\":\"Herb run\",\"targetMillis\":\"soon\"},{\"name\":\"Wine run\"}]}");

		assertEquals("Clock 1 \"Herb run\", field targetMillis: expected a number, found \"soon\","
			+ " so this clock was skipped", said);
	}

	@Test
	public void aClockThatCannotBeReadIsSkippedAndItsNeighboursStillArrive()
	{
		final ClockworkDocument.Imported imported = read("{\"version\":1,\"routines\":["
			+ "{\"name\":\"Herb run\"},{\"name\":\"Wine run\",\"targetMillis\":{}},"
			+ "{\"name\":\"Zulrah trips\"}]}");

		assertTrue(imported.isOk());
		assertEquals("losing one clock never costs the others", 2, imported.getAdded().size());
		assertEquals(1, DocumentProblem.skippedCount(imported.getProblems()));
		assertTrue(DocumentProblem.lines(imported.getProblems()),
			DocumentProblem.lines(imported.getProblems()).contains("Clock 2 \"Wine run\""));
		assertTrue(DocumentProblem.lines(imported.getProblems()).contains("found an object"));
	}

	/**
	 * A clock that loses only a trigger keeps everything else, which is
	 * deliberate and was silent until now.
	 */
	@Test
	public void aClockThatLosesOnlyATriggerArrivesAndSaysWhatItLost()
	{
		final ClockworkDocument.Imported imported = read("{\"version\":1,\"routines\":["
			+ "{\"name\":\"Herb run\",\"startTrigger\":[1,2]},{\"name\":\"Wine run\"}]}");

		assertTrue(imported.isOk());
		assertEquals(2, imported.getAdded().size());
		assertEquals("the clock arrived, so nothing was skipped", 0,
			DocumentProblem.skippedCount(imported.getProblems()));

		final String said = DocumentProblem.lines(imported.getProblems());
		assertTrue(said, said.contains("field startTrigger"));
		assertTrue(said, said.contains("expected an object, found a list"));
		assertTrue(said, said.contains("without the trigger it started on"));
	}

	@Test
	public void anEntryThatIsNotAClockAtAllIsCountedAndReported()
	{
		final ClockworkDocument.Imported imported =
			read("{\"version\":1,\"routines\":[{\"name\":\"Herb run\"},7]}");

		assertTrue(imported.isOk());
		assertEquals(1, imported.getAdded().size());
		assertEquals("Clock 2: this is not a clock, it is 7, so it was skipped",
			DocumentProblem.lines(imported.getProblems()));
	}

	// What the plugin works out for itself

	@Test
	public void aDanglingTriggerNamesTheClockAndTheTrigger()
	{
		final ClockworkDocument.Imported imported = read("{\"version\":1,\"routines\":["
			+ "{\"name\":\"Herb run\",\"startTrigger\":{\"type\":\"custom\",\"ref\":\"Note herbs\"}}]}");

		assertFalse("a clock waiting for something nothing defines is still a refusal", imported.isOk());
		assertEquals("Clock 1 \"Herb run\": starts on a custom trigger called Note herbs,"
			+ " which this document does not define", DocumentProblem.lines(imported.getProblems()));
	}

	@Test
	public void everyDanglingTriggerIsReportedRatherThanTheFirst()
	{
		final ClockworkDocument.Imported imported = read("{\"version\":1,\"routines\":["
			+ "{\"name\":\"Herb run\",\"startTrigger\":{\"type\":\"custom\",\"ref\":\"Note herbs\"},"
			+ "\"stopTrigger\":{\"type\":\"custom\",\"ref\":\"Bank it\"}},"
			+ "{\"name\":\"Wine run\",\"lapsEnabled\":true,"
			+ "\"lapTrigger\":{\"type\":\"custom\",\"ref\":\"Grapes\"}}]}");

		assertFalse(imported.isOk());
		assertEquals(3, imported.getProblems().size());

		final String said = DocumentProblem.lines(imported.getProblems());
		assertTrue(said, said.contains("Note herbs"));
		assertTrue(said, said.contains("Bank it"));
		assertTrue(said, said.contains("Grapes"));
		assertTrue("the three ends of a clock read differently", said.contains("takes a split"));
	}

	@Test
	public void aDocumentFromANewerBuildIsRefusedByVersion()
	{
		final ClockworkDocument.Imported imported =
			read("{\"version\":99,\"routines\":[{\"name\":\"Herb run\"}]}");

		assertFalse(imported.isOk());
		assertTrue(imported.getProblem(), imported.getProblem().contains("99"));
		assertTrue(imported.getProblem(), imported.getProblem().contains("newer"));
	}

	// Which clock is it

	@Test
	public void aClockIsIdentifiedByItsNameWhenTheDocumentGivesOne()
	{
		final String said = linesOf("{\"version\":1,\"routines\":[{\"name\":\"Herb run\"},"
			+ "{\"name\":\"Zulrah trips\",\"mode\":\"sideways\"}]}");

		assertTrue(said, said.startsWith("Clock 2 \"Zulrah trips\", field mode:"));
	}

	@Test
	public void aClockWithNoNameIsIdentifiedByWhereItIs()
	{
		final String said = linesOf("{\"version\":1,\"routines\":[{\"name\":\"Herb run\"},"
			+ "{\"mode\":\"sideways\"}]}");

		assertTrue(said, said.contains("Clock 2, field mode: expected"));
		assertFalse("there is no name to quote, so nothing is quoted at it", said.contains("Clock 2 \""));
	}

	@Test
	public void aClockWithNoNameIsSaidToHaveNone()
	{
		final String said = linesOf("{\"version\":1,\"routines\":[{\"targetMillis\":500}]}");

		assertEquals("Clock 1: this clock has no name, so it arrives called Clock", said);
	}

	@Test
	public void twoClocksWithOneNameAreWorthSayingOutLoud()
	{
		final String said = linesOf("{\"version\":1,\"routines\":[{\"name\":\"Herb run\"},"
			+ "{\"name\":\"herb run\"}]}");

		assertTrue(said, said.startsWith("Clock 2 \"herb run\": another clock in this document"));
		assertTrue(said, said.contains("matched by name"));
	}

	// The point of the whole change

	/**
	 * Six clocks, five different things wrong, one pass. Every one of them
	 * comes back, in the order somebody reads the document, and the document
	 * still imports what can be imported.
	 *
	 * <p>This is the test the change exists for. If it ever goes back to
	 * reporting one problem, this is what fails.
	 */
	@Test
	public void severalDifferentProblemsInOneDocumentAreAllReported()
	{
		final ClockworkDocument.Imported imported = read("{\n"
			+ "  \"version\": 1,\n"
			+ "  \"routines\": [\n"
			+ "    {\"name\": \"Herb run\"},\n"
			+ "    {\"name\": \"Wine run\", \"mode\": \"countup!\"},\n"
			+ "    {\"name\": \"Zulrah trips\", \"targetMillis\": \"soon\"},\n"
			+ "    {\"name\": \"Vorkath\", \"startTrigger\": [1, 2]},\n"
			+ "    {\"targetMillis\": 500},\n"
			+ "    {\"name\": \"Herb run\"}\n"
			+ "  ]\n"
			+ "}");

		assertTrue("one unreadable clock does not refuse the document", imported.isOk());
		assertEquals("the one that could not be read is the only one missing", 5,
			imported.getAdded().size());

		final List<DocumentProblem> problems = imported.getProblems();
		assertEquals("five things are wrong and five things are said", 5, problems.size());

		assertEquals("they arrive in the order the document reads",
			Arrays.asList(2, 3, 4, 5, 6), numbers(problems));

		final String said = DocumentProblem.lines(problems);
		assertTrue(said, said.contains("Clock 2 \"Wine run\", field mode: expected countdown or countup"));
		assertTrue(said, said.contains("Clock 3 \"Zulrah trips\", field targetMillis"));
		assertTrue(said, said.contains("Clock 4 \"Vorkath\", field startTrigger"));
		assertTrue(said, said.contains("Clock 5: this clock has no name"));
		assertTrue(said, said.contains("Clock 6 \"Herb run\": another clock"));

		assertEquals("only one of the five costs a clock", 1, DocumentProblem.skippedCount(problems));
	}

	private static List<Integer> numbers(List<DocumentProblem> problems)
	{
		final List<Integer> found = new ArrayList<>();
		for (DocumentProblem problem : problems)
		{
			found.add(problem.getNumber());
		}
		return found;
	}

	/**
	 * A skipped clock is still in the document, so the clocks after it keep the
	 * positions the user can count to. Numbering the survivors instead would
	 * point at the wrong line of somebody's file.
	 */
	@Test
	public void aSkippedClockDoesNotShiftTheNumbersOfTheOnesAfterIt()
	{
		final ClockworkDocument.Imported imported = read("{\"version\":1,\"routines\":["
			+ "{\"name\":\"Herb run\",\"targetMillis\":{}},"
			+ "{\"name\":\"Wine run\",\"startTrigger\":{\"type\":\"custom\",\"ref\":\"Grapes\"}}]}");

		assertFalse(imported.isOk());

		final String said = DocumentProblem.lines(imported.getProblems());
		assertTrue(said, said.contains("Clock 1 \"Herb run\""));
		assertTrue("the second clock is still the second clock", said.contains("Clock 2 \"Wine run\""));
	}

	@Test
	public void aTriggerLibraryThatCannotBeReadIsSaidOutLoud()
	{
		final ClockworkDocument.Imported imported =
			read("{\"version\":1,\"triggers\":[3],\"routines\":[{\"name\":\"Herb run\"}]}");

		final String said = DocumentProblem.lines(imported.getProblems());
		assertTrue(said, said.contains("The custom triggers in this document could not be read"));
	}

	// The quiet case, which matters as much

	@Test
	public void aGoodDocumentHasNothingToSay()
	{
		final ClockworkDocument.Imported imported = read("{\"version\":1,"
			+ "\"triggers\":[{\"name\":\"Note herbs\",\"option\":\"Use\",\"target\":\"Leprechaun\"}],"
			+ "\"routines\":[{\"name\":\"Herb run\",\"mode\":\"countdown\",\"targetMillis\":360000,"
			+ "\"startTrigger\":{\"type\":\"custom\",\"ref\":\"Note herbs\"}},"
			+ "{\"name\":\"Wine run\",\"clock\":\"loggedinonly\",\"overlay\":\"whilerunning\","
			+ "\"showDelta\":\"on\"}]}");

		assertTrue(imported.getProblem(), imported.isOk());
		assertEquals(2, imported.getAdded().size());
		assertTrue("a document with nothing wrong says nothing", imported.getProblems().isEmpty());
		assertEquals(0, DocumentProblem.skippedCount(imported.getProblems()));
	}

	/**
	 * The spelling an enum was stored under before this plugin was ever
	 * published is not a spelling this build binds, so it is reported rather
	 * than quietly accepted.
	 *
	 * <p>There used to be a table of historical names here, consulted before a
	 * value was judged, because the format had been through five shapes and an
	 * old document was a document rather than a mistake. The format restarted at
	 * one at first publish and no user has ever saved anything older, so the
	 * table went and the only spellings that count are the ones Gson writes now.
	 */
	@Test
	public void aConstantNameFromBeforeTheFirstPublishIsReported()
	{
		final String said = linesOf("{\"version\":1,\"routines\":["
			+ "{\"name\":\"Herb run\",\"mode\":\"COUNT_DOWN\"}]}");

		assertEquals("Clock 1 \"Herb run\", field mode: expected countdown or countup,"
			+ " found \"COUNT_DOWN\"", said);
	}

	/**
	 * The list of acceptable spellings is derived from the enums rather than
	 * written down, so it says what this build actually reads. Every persisted
	 * enum that can appear in a document is checked here, because a constant
	 * added to one of them and missing from a message is a message that reads
	 * as a rule the plugin does not have.
	 */
	@Test
	public void everyEnumValuedKeySaysTheSpellingsItActuallyBinds()
	{
		assertEquals("Clock 1 \"Herb run\", field mode: expected countdown or countup, found \"x\"",
			linesOf(one("mode")));
		assertEquals("Clock 1 \"Herb run\", field clock: expected loggedinonly or wallclock, found \"x\"",
			linesOf(one("clock")));
		assertEquals("Clock 1 \"Herb run\", field overlay: expected always, never, useglobal"
			+ " or whilerunning, found \"x\"", linesOf(one("overlay")));
		assertEquals("Clock 1 \"Herb run\", field showDelta: expected off, on or useglobal, found \"x\"",
			linesOf(one("showDelta")));
		assertEquals("Clock 1 \"Herb run\", field alert: expected none, screen, timerbox"
			+ " or useglobal, found \"x\"", linesOf(one("alert")));
		assertEquals("Clock 1 \"Herb run\", field sound: expected off, on or useglobal, found \"x\"",
			linesOf(one("sound")));
		assertEquals("Clock 1 \"Herb run\", field notify: expected off, on or useglobal, found \"x\"",
			linesOf(one("notify")));
		assertEquals("Clock 1 \"Herb run\", field startTrigger.type: expected bankchest, custom,"
			+ " mineiron, none or teleport, found \"x\"",
			linesOf("{\"version\":1,\"routines\":[{\"name\":\"Herb run\","
				+ "\"startTrigger\":{\"type\":\"x\"}}]}"));
	}

	/**
	 * A document holding exactly what this build writes for every one of those
	 * keys has nothing said about it, which is the other half of the same rule
	 * and the half that would break first if the derivation went wrong.
	 */
	@Test
	public void everySpellingThisBuildWritesIsAccepted()
	{
		for (String mode : new String[]{"countup", "countdown"})
		{
			assertEquals("", linesOf(one("mode", mode)));
		}
		for (String clock : new String[]{"wallclock", "loggedinonly"})
		{
			assertEquals("", linesOf(one("clock", clock)));
		}
		for (String overlay : new String[]{"useglobal", "always", "whilerunning", "never"})
		{
			assertEquals("", linesOf(one("overlay", overlay)));
		}
		for (String delta : new String[]{"useglobal", "on", "off"})
		{
			assertEquals("", linesOf(one("showDelta", delta)));
		}
		for (String alert : new String[]{"useglobal", "none", "timerbox", "screen"})
		{
			assertEquals("", linesOf(one("alert", alert)));
		}
		for (String sound : new String[]{"useglobal", "on", "off"})
		{
			assertEquals("", linesOf(one("sound", sound)));
		}
		for (String notify : new String[]{"useglobal", "on", "off"})
		{
			assertEquals("", linesOf(one("notify", notify)));
		}
		for (String type : new String[]{"none", "teleport", "bankchest", "mineiron"})
		{
			assertEquals("", linesOf("{\"version\":1,\"routines\":[{\"name\":\"Herb run\","
				+ "\"startTrigger\":{\"type\":\"" + type + "\"}}]}"));
		}
	}

	/**
	 * A one clock document with one key set to the given value, so the only
	 * thing there can be anything to say about is that key.
	 */
	private static String one(String field)
	{
		return one(field, "x");
	}

	private static String one(String field, String value)
	{
		return "{\"version\":1,\"routines\":[{\"name\":\"Herb run\",\"" + field
			+ "\":\"" + value + "\"}]}";
	}

	// The editor is told the same things

	@Test
	public void theEditorIsToldEverythingTheImportIsTold()
	{
		final List<Routine> mine = Collections.singletonList(new Routine("a", "Herb run"));
		final ClockworkDocument.Applied applied = ClockworkDocument.readEdited(GSON,
			"{\"version\":1,\"routines\":[{\"name\":\"Herb run\",\"mode\":\"countup!\"},"
				+ "{\"name\":\"Wine run\",\"targetMillis\":\"soon\"}]}",
			mine, library);

		assertTrue(applied.getProblem(), applied.isOk());
		assertEquals(2, applied.getProblems().size());
		assertEquals(1, DocumentProblem.skippedCount(applied.getProblems()));
		assertTrue(DocumentProblem.lines(applied.getProblems()).contains("Clock 2 \"Wine run\""));
	}

	@Test
	public void aRefusedEditSaysEveryReasonAtOnce()
	{
		final ClockworkDocument.Applied applied = ClockworkDocument.readEdited(GSON,
			"{\"version\":1,\"routines\":["
				+ "{\"name\":\"Herb run\",\"startTrigger\":{\"type\":\"custom\",\"ref\":\"Note herbs\"}},"
				+ "{\"name\":\"Wine run\",\"stopTrigger\":{\"type\":\"custom\",\"ref\":\"Bank it\"}}]}",
			Collections.emptyList(), library);

		assertFalse(applied.isOk());
		assertNotNull(applied.getProblem());
		assertEquals("a refusal reads as every line of it", 2,
			applied.getProblem().split("\n").length);
		assertTrue("and nothing is applied", applied.getRoutines().isEmpty());
	}

	// The value type itself

	@Test
	public void aProblemReadsAsWhereItIsThenWhatIsWrong()
	{
		assertEquals("Line 3, column 9: something", DocumentProblem.at(3, 9, "something").describe());
		assertEquals("Line 3: something", DocumentProblem.at(3, 0, "something").describe());
		assertEquals("Clock 2 \"Herb run\": something",
			DocumentProblem.inClock(2, "Herb run", "something").describe());
		assertEquals("Clock 2: something", DocumentProblem.inClock(2, null, "something").describe());
		assertEquals("Clock 2 \"Herb run\", field mode: something",
			DocumentProblem.inField(2, "Herb run", "mode", "something").describe());
		assertEquals("a document wide problem is the whole line", "something",
			DocumentProblem.inDocument("something").describe());
	}

	@Test
	public void aValueIsDescribedAsSomethingAPersonWouldSay()
	{
		final Gson gson = new Gson();
		assertEquals("an object", DocumentProblem.found(gson.toJsonTree(Collections.emptyMap())));
		assertEquals("a list", DocumentProblem.found(gson.toJsonTree(Collections.emptyList())));
		assertEquals("\"soon\"", DocumentProblem.found(gson.toJsonTree("soon")));
		assertEquals("7", DocumentProblem.found(gson.toJsonTree(7)));
		assertEquals("true", DocumentProblem.found(gson.toJsonTree(true)));
		assertEquals("nothing", DocumentProblem.found(null));
	}

	@Test
	public void nothingOutOfALibraryIsEverPutInFrontOfSomebody()
	{
		for (String bad : Arrays.asList("", "   ", "not json at all", "{\"version\":1,",
			"[1,2,3]", "null", "{\"version\":1,\"routines\":{}}"))
		{
			final ClockworkDocument.Imported imported = read(bad);

			assertFalse("expected a refusal for " + bad, imported.isOk());
			assertFalse(imported.getProblem(), imported.getProblem().contains("com.google"));
			assertFalse(imported.getProblem(), imported.getProblem().contains("java."));
			assertFalse(imported.getProblem(), imported.getProblem().contains("JsonReader"));
			assertTrue("a refusal is still a sentence", imported.getProblem().length() > 10);
		}
	}
}

package com.clockwork;

import com.clockwork.core.RoutineMigration;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The two numbers stamped on everything this build writes, and what a reader
 * does with them.
 *
 * <p>The pair exists because one number cannot answer two questions. The
 * version says which rewrites a newer reader runs over older data. The minimum
 * says whether an older reader is safe to go ahead at all. Refusing on the
 * version alone breaks sharing between two users every time an update rolls
 * out. Refusing on neither lets a field that changed its meaning arrive
 * looking fine.
 */
public class DocumentVersionStampTest
{
	private static final Gson GSON = new Gson();

	private static JsonObject stamped(String json)
	{
		return GSON.fromJson(json, JsonObject.class);
	}

	/**
	 * The one that has to hold forever. A build may not ask readers to be
	 * newer than it is itself, because it would be refusing its own documents.
	 */
	@Test
	public void thisBuildNeverAsksForAReaderNewerThanItself()
	{
		assertTrue("MINIMUM_READER_VERSION must never exceed CURRENT_VERSION, or this build"
				+ " writes documents it would refuse to read back",
			RoutineMigration.MINIMUM_READER_VERSION <= RoutineMigration.CURRENT_VERSION);
	}

	@Test
	public void everythingWrittenCarriesBothNumbers()
	{
		final JsonObject root = stamped(ClockworkStorage.encodeRoutines(GSON, null, null));

		assertEquals(RoutineMigration.CURRENT_VERSION, ClockworkStorage.version(root));
		assertEquals(RoutineMigration.MINIMUM_READER_VERSION, ClockworkStorage.minimumReader(root));
	}

	@Test
	public void aDocumentThatDoesNotSayIsJudgedByItsVersionInstead()
	{
		// The conservative way round. A document from before the second stamp
		// existed, or one with the key taken out, is read exactly as strictly
		// as it would have been before the stamp was invented.
		assertEquals(7, ClockworkStorage.minimumReader(stamped("{\"version\":7}")));
		assertEquals(7, ClockworkStorage.minimumReader(stamped("{\"version\":7,\"minVersion\":\"x\"}")));
		assertEquals(0, ClockworkStorage.minimumReader(stamped("{}")));
	}

	@Test
	public void aNewerDocumentThatSaysWeCanReadItIsNotRefused()
	{
		// The whole point of the second number. Version 9 was written by a
		// build far ahead of this one, and that build says a version 1 reader
		// gets it right, so it is read.
		final JsonObject root = stamped("{\"version\":9,\"minVersion\":1}");

		assertFalse("a newer document that says an older reader is safe must not be refused",
			ClockworkStorage.minimumReader(root) > RoutineMigration.CURRENT_VERSION);
	}

	@Test
	public void aNewerDocumentThatSaysWeCannotIsRefused()
	{
		final JsonObject root = stamped("{\"version\":9,\"minVersion\":9}");

		assertTrue("a document whose writer says an older reader would get it wrong must be refused",
			ClockworkStorage.minimumReader(root) > RoutineMigration.CURRENT_VERSION);
	}
}

package com.clockwork;

import com.clockwork.core.AlertStyle;
import com.clockwork.core.OverlayMode;
import java.awt.event.KeyEvent;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Notification;

/**
 * The config panel, as the plugin sees it, with none of RuneLite behind it.
 *
 * <p>Every method on {@link ClockworkConfig} carries a {@code default} body,
 * which {@code ClockworkConfigTest} already guarantees for a different reason,
 * so implementing the interface and overriding nothing gives the real defaults
 * rather than a set of guesses. A test that cares about one setting overrides
 * that one setting and leaves the rest alone.
 *
 * <p>Only the settings a test moves are overridable here, and each starts on
 * the real default. The defaults are what a user who has never opened the
 * config panel gets, so they are what the wiring tests run against.
 *
 * <p>The three hotkeys are the exception and are pinned rather than left on the
 * shipped defaults. Those carry ctrl and alt, and a {@code KeyEvent} built in a
 * test has to answer for its own modifiers as well as its key code for
 * {@code Keybind.matches} to say yes. F1, F2, and F3 are three keys that are
 * distinct, carry no modifiers, and produce no character, so a test can press
 * one without hand building a modifier mask that would only be testing itself.
 */
class FakeClockworkConfig implements ClockworkConfig
{
	static final Keybind START = new Keybind(KeyEvent.VK_F1, 0);
	static final Keybind STOP = new Keybind(KeyEvent.VK_F2, 0);
	static final Keybind LAP = new Keybind(KeyEvent.VK_F3, 0);

	/**
	 * How many recent runs the average is taken from, or null while no test has
	 * moved it. Null falls through to the interface's own default rather than
	 * to a number written out here, so moving the default moves this too.
	 */
	private Integer averageWindow;

	/**
	 * When a clock gets a timer box in the game window, or null while no test
	 * has moved it, for the same reason as above.
	 */
	private OverlayMode overlayVisibility;

	/**
	 * How long an alert stays on screen, or null while no test has moved it.
	 *
	 * <p>Worth moving in a test about the timer boxes, because a box whose
	 * clock has just finished is held open for exactly this long so that its
	 * flash can be seen. The shipped default is five seconds, which is longer
	 * than a test wants to sit waiting for a box to be given back.
	 */
	private Integer alertSeconds;

	/**
	 * What a finished clock draws, or null while no test has moved it.
	 *
	 * <p>Worth moving in a test about the per clock alert setting, because the
	 * override has to be shown winning in both directions and one of those
	 * needs the plugin wide answer to be something other than the shipped
	 * default.
	 */
	private AlertStyle alertStyle;

	/**
	 * Whether a finished clock chimes, or null while no test has moved it.
	 *
	 * <p>Worth moving for the same reason {@link #alertStyle} is. The chime is
	 * off on a fresh install, so a test that wants to watch a clock turn it off
	 * for itself needs the plugin wide answer to be on first.
	 */
	private Boolean playSound;

	/**
	 * How the RuneLite notification behaves, or null while no test has moved
	 * it.
	 *
	 * <p>Worth moving for the same reason {@link #playSound} is, and for one
	 * more. This is the global the per clock notification setting falls back
	 * to, and the half of it that means yes or no is the enabled tick, so a
	 * test that wants to watch a clock beat that tick has to be able to turn it
	 * off. It is also the only global here that is an object rather than a
	 * value, so a test can hand over one the user has already been at and watch
	 * what survives the trip.
	 */
	private Notification notification;

	/**
	 * Whether the last seconds of a countdown are counted in, or null while no
	 * test has moved it. On by default, so the test that has to move it is the
	 * one about turning it off.
	 */
	private Boolean countIn;

	/**
	 * How loud the clips are, or null while no test has moved it. Worth moving
	 * for the one case where the volume is the whole question, which is a user
	 * who has dragged it to zero and has asked for silence everywhere.
	 */
	private Integer soundVolume;

	@Override
	public int averageWindow()
	{
		return averageWindow == null ? ClockworkConfig.super.averageWindow() : averageWindow;
	}

	void setAverageWindow(int value)
	{
		averageWindow = value;
	}

	@Override
	public OverlayMode overlayVisibility()
	{
		return overlayVisibility == null ? ClockworkConfig.super.overlayVisibility() : overlayVisibility;
	}

	void setOverlayVisibility(OverlayMode value)
	{
		overlayVisibility = value;
	}

	@Override
	public int alertSeconds()
	{
		return alertSeconds == null ? ClockworkConfig.super.alertSeconds() : alertSeconds;
	}

	void setAlertSeconds(int value)
	{
		alertSeconds = value;
	}

	@Override
	public AlertStyle alertStyle()
	{
		return alertStyle == null ? ClockworkConfig.super.alertStyle() : alertStyle;
	}

	void setAlertStyle(AlertStyle value)
	{
		alertStyle = value;
	}

	@Override
	public boolean playSound()
	{
		return playSound == null ? ClockworkConfig.super.playSound() : playSound;
	}

	void setPlaySound(boolean value)
	{
		playSound = value;
	}

	@Override
	public Notification notification()
	{
		return notification == null ? ClockworkConfig.super.notification() : notification;
	}

	void setNotification(Notification value)
	{
		notification = value;
	}

	@Override
	public boolean countIn()
	{
		return countIn == null ? ClockworkConfig.super.countIn() : countIn;
	}

	void setCountIn(boolean value)
	{
		countIn = value;
	}

	@Override
	public int soundVolume()
	{
		return soundVolume == null ? ClockworkConfig.super.soundVolume() : soundVolume;
	}

	void setSoundVolume(int value)
	{
		soundVolume = value;
	}

	@Override
	public Keybind startHotkey()
	{
		return START;
	}

	@Override
	public Keybind stopHotkey()
	{
		return STOP;
	}

	@Override
	public Keybind lapHotkey()
	{
		return LAP;
	}
}

package com.clockwork;

import com.clockwork.core.Routine;
import com.clockwork.core.TriggerLibrary;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * The saved state, held in memory instead of in a RuneLite config profile.
 *
 * <p>This is a subclass rather than an interface implementation because
 * {@link ClockworkStorage} is a class and the plugin injects it as one. The
 * superclass constructor is handed two nulls, which is safe because every
 * method the plugin calls is overridden below and none of the ones left alone
 * touch the config manager or the Gson it was given.
 *
 * <p>It doubles as the main observation point for a wiring test. The plugin
 * saves through here on every change to the clock list, so {@link #stored()}
 * answers "what does the plugin believe the clocks are right now" without
 * reaching inside it, and {@link #hotkeyTargetWrites()} records every write of
 * the designation including the clearing ones, which are the interesting half.
 *
 * <p>One deliberate difference from the real thing. The real storage encodes to
 * JSON and decodes back, so what comes out of a load is never the object that
 * went into a save. This hands the same objects back, so a clock the controller
 * mutates is mutated here too. That is simpler to read and has not mattered
 * yet, but it is the first thing to suspect if a test about persistence passes
 * for the wrong reason.
 */
class FakeClockworkStorage extends ClockworkStorage
{
	private List<Routine> stored = new ArrayList<>();
	private TriggerLibrary library = TriggerLibrary.empty();
	private String hotkeyTargetId;

	private final List<String> hotkeyTargetWrites = new ArrayList<>();
	private final List<String> historySaves = new ArrayList<>();
	private int saves;

	FakeClockworkStorage()
	{
		super(null, null);
	}

	// What a test sets up before the plugin starts

	void setStored(Routine... routines)
	{
		stored = new ArrayList<>(Arrays.asList(routines));
	}

	void setHotkeyTargetId(String routineId)
	{
		hotkeyTargetId = routineId;
	}

	// What a test reads back afterwards

	List<Routine> stored()
	{
		return Collections.unmodifiableList(stored);
	}

	List<String> storedIds()
	{
		final List<String> ids = new ArrayList<>();
		for (Routine routine : stored)
		{
			ids.add(routine.getId());
		}
		return ids;
	}

	String hotkeyTargetId()
	{
		return hotkeyTargetId;
	}

	/**
	 * Every designation the plugin wrote, in order, nulls included. A null is
	 * the plugin clearing a designation that pointed at a clock which is not
	 * there any more, which is the behaviour worth asserting on.
	 */
	List<String> hotkeyTargetWrites()
	{
		return Collections.unmodifiableList(hotkeyTargetWrites);
	}

	int saveCount()
	{
		return saves;
	}

	/**
	 * Every narrow write of one clock's runs, in order, by clock id. The real
	 * storage aims those at one config key, so this is where a test says that a
	 * finished run wrote one clock's runs rather than everybody's.
	 */
	List<String> historySaves()
	{
		return Collections.unmodifiableList(historySaves);
	}

	// The surface the plugin actually uses

	/**
	 * Nothing to carry across. The real one reads and rewrites config keys
	 * through a config manager, and this stands in for a plugin that has none,
	 * so the real body would only ever record a failure for every test in the
	 * suite.
	 */
	@Override
	public void migrateOverlayVisibility()
	{
	}

	/**
	 * Nothing to bring into range, for the same reason.
	 */
	@Override
	public void clampAverageWindow()
	{
	}

	@Override
	public Saved load()
	{
		return new Saved(new ArrayList<>(stored), library);
	}

	@Override
	public void save(List<Routine> routines, TriggerLibrary savedLibrary)
	{
		saves++;
		stored = routines == null ? new ArrayList<>() : new ArrayList<>(routines);
		library = savedLibrary == null ? TriggerLibrary.empty() : savedLibrary;
	}

	/**
	 * The narrow write. Nothing to carry across, because this holds the very
	 * objects the controller mutates, so the stored list is already up to date.
	 * The call is recorded, since which write a change went through is the
	 * interesting part.
	 */
	@Override
	public void saveHistory(Routine routine)
	{
		historySaves.add(routine == null ? null : routine.getId());
	}

	@Override
	public String loadHotkeyTarget()
	{
		return hotkeyTargetId;
	}

	@Override
	public void saveHotkeyTarget(String routineId)
	{
		hotkeyTargetId = routineId;
		hotkeyTargetWrites.add(routineId);
	}
}

package com.clockwork;

import com.clockwork.core.DurationFormat;
import com.clockwork.core.SubSecond;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import org.junit.Test;

/**
 * The helper that replaced the default method on the config interface.
 */
public class FormatsTest
{
	/**
	 * Stands in for the config proxy. Only the four values the format is built
	 * from are given anything to say.
	 */
	private static ClockworkConfig config(boolean hours, boolean minutes, boolean seconds, SubSecond precision)
	{
		return new ClockworkConfig()
		{
			@Override
			public boolean showHours()
			{
				return hours;
			}

			@Override
			public boolean showMinutes()
			{
				return minutes;
			}

			@Override
			public boolean showSeconds()
			{
				return seconds;
			}

			@Override
			public SubSecond precision()
			{
				return precision;
			}
		};
	}

	@Test
	public void theFormatIsBuiltFromTheFourDisplaySettings()
	{
		assertEquals(new DurationFormat(true, true, true, SubSecond.HUNDREDTHS),
			Formats.of(config(true, true, true, SubSecond.HUNDREDTHS)));

		assertEquals(new DurationFormat(false, true, true, SubSecond.NONE),
			Formats.of(config(false, true, true, SubSecond.NONE)));
	}

	/**
	 * The crash this whole change came from was a null format reaching the
	 * refresh path, so the helper is not allowed to produce one.
	 */
	@Test
	public void aMissingConfigStillGivesAUsableFormat()
	{
		DurationFormat format = Formats.of(null);
		assertNotNull(format);
		assertNotNull(format.withoutSubSecond());
	}
}

package com.clockwork;

import com.clockwork.core.SavedTrigger;
import com.clockwork.core.Trigger;
import com.clockwork.core.TriggerEvent;
import com.clockwork.core.TriggerLibrary;
import com.clockwork.core.TriggerType;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.api.ChatMessageType;
import org.junit.Test;

/**
 * The client side half of a trigger.
 *
 * <p>The rules themselves are tested in core against plain values. What is
 * tested here is the translation that has to happen first, because a raw menu
 * target arrives wrapped in colour tags and comparing that against a plain
 * string silently never matches. A bug here looks exactly like a trigger that
 * does not work, with nothing in any log to say why.
 */
public class GameTriggersTest
{
	/**
	 * A "use X on Y" menu target exactly as the client sends it. Each half
	 * carries its own colour and the arrow between them carries none, so the
	 * tags fall in the middle of the phrase rather than around it.
	 */
	private static final String USE_ON_LEPRECHAUN =
		"<col=ff9040>Huasca<col=ffffff> -> <col=ffff00>Tool Leprechaun";

	/**
	 * The shape a menu target really arrives in.
	 */
	@Test
	public void aColourWrappedBankChestStillReachesTheRuleAsABankChest()
	{
		TriggerEvent event = GameTriggers.menuClick("Use", "<col=ff9040>Bank chest</col>");

		assertEquals("Bank chest", event.getMenuTarget());
		assertTrue(TriggerType.BANK_CHEST.matches(event));
	}

	/**
	 * The case the stripping actually earns its keep on. A name broken up by a
	 * second colour tag does not contain the words it reads as, so an
	 * unstripped compare fails even though a contains would otherwise be
	 * forgiving.
	 */
	@Test
	public void aTargetBrokenUpByASecondTagIsPutBackTogether()
	{
		String raw = "<col=ff9040>Bank<col=ffffff> chest</col>";

		assertFalse("the raw target is not the words it reads as",
			TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick("Use", raw)));
		assertTrue("stripped, it is", TriggerType.BANK_CHEST.matches(GameTriggers.menuClick("Use", raw)));
	}

	/**
	 * The whole entry gets stripped, not only the target, so the option half
	 * is judged as the plain word it reads as. Examine on a bank chest is the
	 * case that matters, because the rule used to look at the target alone and
	 * a clock would start or stop just from reading a description.
	 */
	@Test
	public void examiningAColourWrappedBankChestDoesNotFireTheTrigger()
	{
		TriggerEvent event = GameTriggers.menuClick("Examine", "<col=ff9040>Bank chest</col>");

		assertEquals("Examine", event.getMenuOption());
		assertEquals("Bank chest", event.getMenuTarget());
		assertFalse("examine is not using the chest", TriggerType.BANK_CHEST.matches(event));
	}

	@Test
	public void aMissingHalfOfAMenuEntryIsAnEmptyStringAndNotANull()
	{
		TriggerEvent event = GameTriggers.menuClick(null, null);

		assertEquals("", event.getMenuOption());
		assertEquals("", event.getMenuTarget());
		assertFalse(TriggerType.BANK_CHEST.matches(event));
	}

	/**
	 * The same stripping is what makes a click trigger usable at all. The user
	 * types the words they read on screen, and the words they read on screen are
	 * not the string the client sent.
	 */
	@Test
	public void aColourWrappedTargetOnlyMatchesAUserWrittenTriggerAfterStripping()
	{
		final Trigger cloak = Trigger.click("Rub", "Ardougne cloak");

		// Broken up by a second tag, which is the shape that actually defeats a
		// substring match. A name wrapped in one tag still contains its own
		// words, so it would match by accident rather than by design.
		final String raw = "<col=ff9040>Ardougne<col=ffffff> cloak 4</col>";

		assertFalse("the raw target is not the words it reads as",
			cloak.matches(TriggerEvent.menuClick("Rub", raw)));

		TriggerEvent event = GameTriggers.menuClick("Rub", raw);
		assertEquals("Ardougne cloak 4", event.getMenuTarget());
		assertTrue("stripped, it is", cloak.matches(event));
	}

	/**
	 * The option half gets stripped too, so a trigger written as the plain word
	 * still matches an entry the client wrapped.
	 */
	@Test
	public void aColourWrappedOptionAlsoReachesAUserWrittenTriggerAsPlainText()
	{
		TriggerEvent event = GameTriggers.menuClick("<col=ff9040>Rub</col>", "Ardougne cloak 4");

		assertEquals("Rub", event.getMenuOption());
		assertTrue(Trigger.click("Rub", null).matches(event));
	}

	/**
	 * The setup aid in the plugin config prints exactly these two strings, so
	 * what the user copies out of the chat box is what the rule is given.
	 */
	@Test
	public void whatIsPrintedToTheChatBoxIsWhatTheRuleIsGiven()
	{
		TriggerEvent event = GameTriggers.menuClick("Rub", "<col=ff9040>Ardougne cloak 4</col>");

		assertTrue(Trigger.click(event.getMenuOption(), event.getMenuTarget()).matches(event));
	}

	@Test
	public void aTaggedChatLineStillReachesTheRuleAsPlainText()
	{
		TriggerEvent event = GameTriggers.chatMessage("<col=000000>You manage to mine some iron.</col>");

		assertEquals("You manage to mine some iron.", event.getMessage());
		assertTrue(TriggerType.MINE_IRON.matches(event));
	}

	@Test
	public void aMissingChatLineIsAnEmptyStringAndNotANull()
	{
		assertEquals("", GameTriggers.chatMessage(null).getMessage());
	}

	/**
	 * Only the game's own messages to this player are read. Everything a
	 * person typed is dropped before any rule sees it, which is both the
	 * cheaper thing to do and the only defensible one.
	 */
	@Test
	public void onlyTheGamesOwnMessagesAreLookedAt()
	{
		assertTrue(GameTriggers.isTriggerChat(ChatMessageType.GAMEMESSAGE));
		assertTrue(GameTriggers.isTriggerChat(ChatMessageType.SPAM));

		assertFalse(GameTriggers.isTriggerChat(ChatMessageType.PUBLICCHAT));
		assertFalse(GameTriggers.isTriggerChat(ChatMessageType.PRIVATECHAT));
		assertFalse(GameTriggers.isTriggerChat(ChatMessageType.FRIENDSCHAT));
		assertFalse(GameTriggers.isTriggerChat(ChatMessageType.CLAN_CHAT));
		assertFalse(GameTriggers.isTriggerChat(null));
	}

	// Use X on Y, which arrives as an arrow

	/**
	 * The shape a "use X on Y" entry really arrives in.
	 *
	 * <p>Both halves are separately colour tagged and the arrow between them is
	 * outside either tag, so the whole thing reads as
	 * {@code Huasca -> Tool Leprechaun} only once the tags are off. This is the
	 * commonest thing a herb runner would want a clock to start on, and until
	 * now there was no test for it at all.
	 */
	@Test
	public void aUseXOnYTargetReachesTheRuleAsBothHalvesAndAnArrow()
	{
		TriggerEvent event = GameTriggers.menuClick("Use", USE_ON_LEPRECHAUN);

		assertEquals("Huasca -> Tool Leprechaun", event.getMenuTarget());
	}

	/**
	 * The half a user would type. A target is matched as a substring, so naming
	 * the thing being used on is enough and the herb does not have to be listed.
	 */
	@Test
	public void aSavedTriggerNamingTheSecondHalfMatchesTheWholeArrow()
	{
		TriggerLibrary library = TriggerLibrary.empty();
		SavedTrigger leprechaun = library.add("Note herbs", "Use", "Tool Leprechaun");
		Trigger onAClock = Trigger.saved(leprechaun.getName());

		assertTrue(library.matches(onAClock, GameTriggers.menuClick("Use", USE_ON_LEPRECHAUN)));
	}

	/**
	 * And the other half, for the same reason. Somebody timing one herb rather
	 * than one destination would write the herb.
	 */
	@Test
	public void aSavedTriggerNamingTheFirstHalfMatchesItToo()
	{
		TriggerLibrary library = TriggerLibrary.empty();
		SavedTrigger huasca = library.add("Huasca", "Use", "Huasca");
		Trigger onAClock = Trigger.saved(huasca.getName());

		assertTrue(library.matches(onAClock, GameTriggers.menuClick("Use", USE_ON_LEPRECHAUN)));
	}

	/**
	 * The option is not a substring, it is the whole word, and the option on
	 * this entry is Use. A clock set to Pick must not start when the player uses
	 * a herb on the leprechaun, or the herb run would be timed from the wrong
	 * moment.
	 */
	@Test
	public void anotherOptionOnTheSameTargetDoesNotMatch()
	{
		TriggerLibrary library = TriggerLibrary.empty();
		SavedTrigger picking = library.add("Pick herbs", "Pick", "Tool Leprechaun");

		assertFalse(library.matches(Trigger.saved(picking.getName()),
			GameTriggers.menuClick("Use", USE_ON_LEPRECHAUN)));
	}

	/**
	 * The stripping actually earning its keep on this shape.
	 *
	 * <p>Worth being careful about. A colour wrapped string usually still
	 * contains the plain words it reads as, so an "unstripped fails" assertion
	 * can pass for the wrong reason and prove nothing. The target used here is
	 * broken by a second tag in the middle, which is the shape that really does
	 * defeat a substring compare, and in the arrow form that tag sits between
	 * the first half and the arrow.
	 */
	@Test
	public void aTargetSpanningTheArrowOnlyMatchesAfterStripping()
	{
		TriggerLibrary library = TriggerLibrary.empty();
		SavedTrigger spanning = library.add("Huasca on something", "Use", "Huasca ->");
		Trigger onAClock = Trigger.saved(spanning.getName());

		assertFalse("the raw target is not the words it reads as",
			library.matches(onAClock, TriggerEvent.menuClick("Use", USE_ON_LEPRECHAUN)));
		assertTrue("stripped, it is",
			library.matches(onAClock, GameTriggers.menuClick("Use", USE_ON_LEPRECHAUN)));
	}
}

package com.clockwork;

import com.clockwork.core.TeleportAnimations;
import static org.junit.Assert.assertEquals;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.gameval.AnimationID;
import org.junit.Test;

/**
 * Pins the teleport animation ids to the client's own constants.
 *
 * <p>{@link TeleportAnimations} lives in core, which is not allowed to import
 * anything from RuneLite, so the ids are written out there as plain integers
 * named after the gameval constants they copy. That is a duplicate, and a
 * duplicate nobody checks is a duplicate that drifts.
 *
 * <p>This test is the check. It lives in the test source set, where the client
 * is on the classpath, and it fails the build the moment the two disagree. If
 * one of these constants is ever renumbered, the failure lands here rather than
 * as a trigger that silently stops firing.
 */
public class GamevalAnimationTest
{
	@Test
	public void theMirroredIdsStillAgreeWithTheClient()
	{
		assertEquals("the standard spellbook and jewellery teleport",
			AnimationID.HUMAN_CASTTELEPORT, TeleportAnimations.HUMAN_CASTTELEPORT);
		assertEquals("breaking a teleport tablet",
			AnimationID.POH_SMASH_MAGIC_TABLET, TeleportAnimations.POH_SMASH_MAGIC_TABLET);
		assertEquals("the Arceuus spellbook teleports",
			AnimationID.HUMAN_SPELLCAST_ARCEUUS_TELEPORT, TeleportAnimations.HUMAN_SPELLCAST_ARCEUUS_TELEPORT);
	}

	/**
	 * And that the set is exactly those three, so an id added to one place and
	 * not the other cannot pass unnoticed.
	 */
	@Test
	public void theSetIsExactlyTheMirroredIds()
	{
		Set<Integer> expected = new HashSet<>(Arrays.asList(
			AnimationID.HUMAN_CASTTELEPORT,
			AnimationID.POH_SMASH_MAGIC_TABLET,
			AnimationID.HUMAN_SPELLCAST_ARCEUUS_TELEPORT));

		assertEquals(expected, TeleportAnimations.ids());
	}
}

package com.clockwork;

import com.clockwork.core.Lap;
import com.clockwork.core.Routine;
import com.clockwork.core.RoutineController;
import com.clockwork.core.RoutineStats;
import com.clockwork.core.Run;
import com.clockwork.core.RunHistory;
import com.clockwork.core.Status;
import com.clockwork.core.Totals;
import com.clockwork.core.TriggerLibrary;
import com.google.gson.Gson;
import java.io.File;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.runelite.client.config.ConfigManager;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Which config keys a save touches, which one a finished run touches, and which
 * ones a load reads.
 *
 * <p>This is the file the storage layout is pinned in. Every clock's runs used
 * to share one key, and a config value is written whole and every key that has
 * changed is uploaded whole, so recording a single run rewrote every clock's
 * entire history and put all of it in the next sync. At the fifty run cap with
 * ten clocks that was a quarter of a megabyte on a volunteer project's servers
 * for one finished herb run. Splitting the key is what fixes the upload.
 * Aiming the write at one key is what fixes the rest of it, and both halves are
 * what these tests hold.
 *
 * <p>{@link ClockworkHistoryStorageTest} is the other side, covering what is
 * inside one key and what a damaged one costs.
 *
 * <p>The config manager is mocked over a map, so a test can say what the config
 * held before and read what it holds after, and so the prefix scan is answered
 * the way the real one answers it, with the group and the key joined by a dot.
 */
public class HistoryKeysTest
{
	private static final String GROUP = ClockworkConfig.GROUP;

	/**
	 * Spelled out rather than read off the storage class, because a test that
	 * asked the code under test what the prefix was could not catch it moving.
	 */
	private static final String PREFIX = "history_";

	/**
	 * Where a clock's lifetime totals sit, spelled out for the same reason.
	 */
	private static final String TOTALS_PREFIX = "totals_";

	private final Map<String, String> config = new LinkedHashMap<>();
	private final List<String> writes = new ArrayList<>();
	private final List<String> unsets = new ArrayList<>();

	private ClockworkStorage storage;

	@Before
	public void setUp()
	{
		final ConfigManager configManager = mock(ConfigManager.class);

		when(configManager.getConfiguration(eq(GROUP), anyString()))
			.thenAnswer(call -> config.get(whole(call.getArgument(1))));

		when(configManager.getConfigurationKeys(anyString())).thenAnswer(call ->
			config.keySet().stream()
				.filter(key -> key.startsWith(call.getArgument(0, String.class)))
				.collect(Collectors.toList()));

		doAnswer(call ->
		{
			final String key = call.getArgument(1);
			writes.add(key);
			config.put(whole(key), call.getArgument(2));
			return null;
		}).when(configManager).setConfiguration(eq(GROUP), anyString(), anyString());

		doAnswer(call ->
		{
			final String key = call.getArgument(1);
			unsets.add(key);
			config.remove(whole(key));
			return null;
		}).when(configManager).unsetConfiguration(eq(GROUP), anyString());

		storage = new ClockworkStorage(configManager, new Gson());
	}

	/**
	 * The one this whole change exists for. Three clocks with runs behind them,
	 * one of them gains a run, and the only keys written belong to that clock.
	 *
	 * <p>Two keys rather than one, because a finished run is a run added to the
	 * list and a run added to the lifetime count, and there is no event that is
	 * one without the other. What matters is that no other clock is touched.
	 */
	@Test
	public void aFinishedRunWritesOneClocksKeysAndLeavesTheRestAlone()
	{
		final List<Routine> routines = threeClocksWithRuns();
		storage.save(routines, TriggerLibrary.empty());

		final String before = config.get(whole(PREFIX + "tree-id"));
		final String totalsBefore = config.get(whole(TOTALS_PREFIX + "tree-id"));
		writes.clear();
		unsets.clear();

		// What the controller does when a run ends, then what the plugin does
		// when it hears about it.
		routines.get(0).getHistory().add(run(500L, 900L, 400L));
		routines.get(0).getTotals().record(400L);
		storage.saveHistory(routines.get(0));

		assertEquals("a finished run writes the runs and the totals of the clock that gained it,"
				+ " and nothing else",
			Arrays.asList(PREFIX + "herb-id", TOTALS_PREFIX + "herb-id"), writes);
		assertTrue("and takes nothing away", unsets.isEmpty());
		assertEquals("the other clocks' keys are untouched, byte for byte",
			before, config.get(whole(PREFIX + "tree-id")));
		assertEquals(totalsBefore, config.get(whole(TOTALS_PREFIX + "tree-id")));
	}

	/**
	 * The other half of the reconcile, and the one that would leak. A deleted
	 * clock's runs were already taken away, and its lifetime totals have to go
	 * the same way or every clock a user ever deletes leaves a key behind
	 * forever with nothing that will ever come back for it.
	 */
	@Test
	public void aClockThatHasLeftTheListLosesItsTotalsAsWellAsItsRuns()
	{
		final List<Routine> routines = threeClocksWithRuns();
		storage.save(routines, TriggerLibrary.empty());
		assertTrue(config.containsKey(whole(TOTALS_PREFIX + "tree-id")));

		final List<Routine> left = new ArrayList<>(routines);
		left.remove(1);
		storage.save(left, TriggerLibrary.empty());

		assertFalse("the runs of a clock that is gone", config.containsKey(whole(PREFIX + "tree-id")));
		assertFalse("and its lifetime totals with them",
			config.containsKey(whole(TOTALS_PREFIX + "tree-id")));
		assertTrue(config.containsKey(whole(TOTALS_PREFIX + "herb-id")));
	}

	/**
	 * The totals go out and come back as the same two numbers, which is the
	 * whole of what an all time average is read from once the runs behind it
	 * have been let go.
	 */
	@Test
	public void lifetimeTotalsComeBackOffTheirOwnKey()
	{
		final List<Routine> routines = threeClocksWithRuns();
		routines.get(0).setTotals(new Totals(214, 214L * 300_000L));
		storage.save(routines, TriggerLibrary.empty());

		final Routine loaded = storage.load().getRoutines().get(0);

		assertEquals("herb-id", loaded.getId());
		assertEquals(214, loaded.totalsOrZero().getCompletedRuns());
		assertEquals(214L * 300_000L, loaded.totalsOrZero().getCompletedMillis());
		assertEquals(Long.valueOf(300_000L), loaded.totalsOrZero().average());
	}

	/**
	 * The wide save, which is what a clock arriving or being reconfigured goes
	 * through. Every clock gets a key of its own, and the clocks blob holds
	 * none of the runs.
	 */
	@Test
	public void theWideSaveWritesAKeyPerClock()
	{
		storage.save(threeClocksWithRuns(), TriggerLibrary.empty());

		assertTrue(config.containsKey(whole(PREFIX + "herb-id")));
		assertTrue(config.containsKey(whole(PREFIX + "tree-id")));
		assertTrue(config.containsKey(whole(PREFIX + "clockwork-quick")));
		assertFalse("nothing writes the old shared key any more",
			config.containsKey(whole("history")));

		assertTrue("a clock's runs are an array, since the key is that clock's alone",
			config.get(whole(PREFIX + "herb-id")).startsWith("["));
		assertFalse("the settings blob carries no runs", config.get(whole("routines")).contains("durationMillis"));
	}

	/**
	 * Deleting a clock has to take its runs with it, or every clock a user ever
	 * deletes leaves a key behind forever.
	 */
	@Test
	public void aClockThatHasLeftTheListHasItsRunsTakenAway()
	{
		final List<Routine> routines = threeClocksWithRuns();
		storage.save(routines, TriggerLibrary.empty());

		final List<Routine> left = new ArrayList<>(routines);
		left.remove(1);
		storage.save(left, TriggerLibrary.empty());

		assertFalse(config.containsKey(whole(PREFIX + "tree-id")));
		assertTrue(config.containsKey(whole(PREFIX + "herb-id")));
		assertTrue(unsets.contains(PREFIX + "tree-id"));
	}

	/**
	 * A clock with nothing recorded has no key rather than a key holding an
	 * empty list, so clearing a clock leaves nothing behind and a clock nobody
	 * has run costs nothing at all.
	 */
	@Test
	public void aClockWithNoRunsHasNoKeyRatherThanAnEmptyOne()
	{
		final List<Routine> routines = threeClocksWithRuns();
		storage.save(routines, TriggerLibrary.empty());
		assertTrue(config.containsKey(whole(PREFIX + "herb-id")));

		routines.get(0).getHistory().clear();
		storage.saveHistory(routines.get(0));

		assertFalse(config.containsKey(whole(PREFIX + "herb-id")));
		assertTrue(config.containsKey(whole(PREFIX + "tree-id")));
	}

	/**
	 * A save and a load with a restart in between, which is the round trip that
	 * matters. The runs come back off their own keys and onto the clocks they
	 * belong to.
	 */
	@Test
	public void runsComeBackOffTheirOwnKeys()
	{
		final List<Routine> routines = threeClocksWithRuns();
		storage.save(routines, TriggerLibrary.empty());

		final List<Routine> loaded = storage.load().getRoutines();

		assertEquals(3, loaded.size());
		assertEquals("herb-id", loaded.get(0).getId());
		assertEquals(2, loaded.get(0).historyOrEmpty().size());
		assertEquals(1200L, loaded.get(0).historyOrEmpty().get(0).getDurationMillis());
		assertEquals(2, loaded.get(0).historyOrEmpty().get(0).lapsOrEmpty().size());
		assertEquals("Ardougne", loaded.get(0).historyOrEmpty().get(0).lapsOrEmpty().get(0).getLabel());
		assertEquals(1, loaded.get(1).historyOrEmpty().size());
		assertEquals(1, loaded.get(2).historyOrEmpty().size());
	}

	/**
	 * Runs stored against a clock that is not on the list. A load leaves them
	 * exactly where they are, because a load is not the place to destroy the
	 * only copy of anything, and the wide save that every load is followed by is
	 * what reconciles the keys with the clock list.
	 */
	@Test
	public void runsWithNoClockAreLeftAloneByALoadAndReconciledByTheNextSave()
	{
		final List<Routine> routines = threeClocksWithRuns();
		storage.save(routines, TriggerLibrary.empty());
		config.put(whole(PREFIX + "ghost-id"), "[{\"durationMillis\":7}]");

		final List<Routine> loaded = storage.load().getRoutines();

		assertEquals("the clock list is what it was", 3, loaded.size());
		assertTrue("and the stray runs are still there after the load",
			config.containsKey(whole(PREFIX + "ghost-id")));

		storage.save(loaded, TriggerLibrary.empty());

		assertFalse("the next wide save is what takes them away",
			config.containsKey(whole(PREFIX + "ghost-id")));
	}

	/**
	 * A clock with no id has nowhere to put its runs. It must cost that clock
	 * its runs and nothing else, and above all it must not write a key called
	 * {@code history_} with nothing after it, which the scan would then read
	 * back as a clock whose id is empty.
	 */
	@Test
	public void aClockWithNoUsableIdIsNeverWritten()
	{
		final Routine nameless = new Routine(null, "No id");
		nameless.setHistory(new ArrayList<>(Collections.singletonList(run(0L, 200L, 200L))));

		final Routine blank = new Routine("   ", "Blank id");
		blank.setHistory(new ArrayList<>(Collections.singletonList(run(0L, 300L, 300L))));

		final Routine herb = new Routine("herb-id", "Herb run");
		herb.setHistory(new ArrayList<>(Collections.singletonList(run(0L, 400L, 400L))));

		storage.save(Arrays.asList(nameless, blank, herb), TriggerLibrary.empty());

		assertEquals(Arrays.asList("routines", PREFIX + "herb-id"), writes);
		assertFalse(config.containsKey(whole(PREFIX)));
		assertFalse(config.containsKey(whole(PREFIX + "   ")));
	}

	/**
	 * A null clock in the list is stepped over rather than ending the save, and
	 * the clocks either side of it are still written.
	 */
	@Test
	public void aNullClockInTheListIsSteppedOver()
	{
		final List<Routine> routines = new ArrayList<>(threeClocksWithRuns());
		routines.add(1, null);

		storage.save(routines, TriggerLibrary.empty());

		assertTrue(config.containsKey(whole(PREFIX + "herb-id")));
		assertTrue(config.containsKey(whole(PREFIX + "tree-id")));
	}

	/**
	 * The old shared key is {@code history} with nothing after it, and the
	 * prefix ends in an underscore, so a user who still has one cannot have it
	 * read back as a clock.
	 *
	 * <p>Two things are held here. The reconcile that takes away the runs of
	 * clocks which have left the list does not touch it, since it is not a
	 * clock's key, and the load reads it as the map from clock id to runs that
	 * it is, so what is under it reaches the clock it names rather than a clock
	 * whose id is empty.
	 */
	@Test
	public void theOldSharedKeyIsNotMistakenForAClocksKey()
	{
		final List<Routine> routines = threeClocksWithRuns();
		storage.save(routines, TriggerLibrary.empty());
		config.put(whole("history"), "{\"herb-id\":[{\"durationMillis\":9}]}");

		storage.save(routines, TriggerLibrary.empty());

		assertTrue("it is not a clock's key, so the reconcile does not touch it",
			config.containsKey(whole("history")));

		final List<Routine> loaded = storage.load().getRoutines();

		assertEquals("the run under the old key reached the clock that key names", 3,
			loaded.get(0).historyOrEmpty().size());
		assertEquals(9L, loaded.get(0).historyOrEmpty().get(1).getDurationMillis());
		assertEquals("a clock the old key says nothing about gained a run from it", 1,
			loaded.get(1).historyOrEmpty().size());
		assertEquals(1, loaded.get(2).historyOrEmpty().size());
	}

	/**
	 * The run log's file path key survives the wide save that reconciles the run
	 * keys against the clock list.
	 *
	 * <p>This is a landmine guard. The reconcile scans every key under the
	 * {@code history_} and {@code totals_} prefixes and unsets each one whose
	 * suffix is not a live clock id. The file path key is named so that neither
	 * prefix matches it, so a wide save leaves it alone. Rename the key to
	 * anything starting with {@code history_} or {@code totals_} and this goes
	 * red, because the reconcile would then read it as a clock whose id is the
	 * rest of the key and sweep it, losing the user's chosen log location.
	 */
	@Test
	public void theRunLogPathSurvivesAWideSave()
	{
		final File chosen = new File("/some/where/log.csv");
		storage.saveHistoryFile(chosen);

		// The wide save, which runs forgetRunsExcept over a non empty clock list.
		storage.save(threeClocksWithRuns(), TriggerLibrary.empty());

		assertEquals("the chosen log location must not be swept by the run key reconcile",
			chosen, storage.loadHistoryFile());
	}

	/**
	 * A real profile, off the author's own client, with the same clock holding
	 * runs under both layouts at once and the old key holding the newer of
	 * them.
	 *
	 * <p>How a profile gets into this state does not matter to the fix, and
	 * there is more than one way in. A config profile is synced, so a key unset
	 * on this machine comes back from the server at the next login. A build
	 * that predates the split writes the old key while a build that follows it
	 * writes the new ones, which is what a second client on the same profile
	 * does and what any downgrade followed by an upgrade does. What matters is
	 * that "some of it happened" is a state a one to many move has to be able
	 * to finish from.
	 *
	 * <p>What the user saw was a clock reading Best none yet and History (0)
	 * with seven runs sitting in their config under the key the panel reads,
	 * because the move gave up the moment it found any clock already carrying a
	 * key of its own and never looked at the old one again.
	 *
	 * <p>The ids are the profile's, with the tail of each shortened. The times
	 * are exactly as they were found.
	 */
	@Test
	public void aProfileHoldingRunsUnderBothLayoutsKeepsEveryOneOfThem()
	{
		final String herb = "c9542141-0e6a-4a3f-9f1c-2b7d5c4e8a10";
		final String tree = "954be02a-7b3d-4c19-8e02-6f1a9d3c5b44";

		config.put(whole("routines"), "{\"version\":1,\"routines\":["
			+ "{\"id\":\"" + herb + "\",\"name\":\"Herb run\"},"
			+ "{\"id\":\"" + tree + "\",\"name\":\"Tree run\"},"
			+ "{\"id\":\"" + Routine.QUICK_ID + "\",\"name\":\"" + Routine.QUICK_NAME + "\"}]}");

		// Seven runs on the clock's own key, oldest first, which is what the
		// panel reads and what it was reading as nothing.
		final List<Run> onItsOwnKey = new ArrayList<>();
		final long[] started = {
			1_787_666_385_180L, 1_787_680_000_000L, 1_787_694_100_000L, 1_787_708_250_000L,
			1_787_722_400_000L, 1_787_736_500_000L, 1_787_750_565_428L};
		for (long startedAt : started)
		{
			onItsOwnKey.add(run(startedAt, startedAt + 600_000L, 600_000L));
		}
		config.put(whole(PREFIX + herb), new Gson().toJson(onItsOwnKey));

		// And the old key, holding one run of that same clock which is newer
		// than all seven, and holding two clocks that have recorded nothing.
		config.put(whole("history"), "{\"" + Routine.QUICK_ID + "\":[],"
			+ "\"" + herb + "\":[{\"startedAtEpochMillis\":1787758396539,"
			+ "\"finishedAtEpochMillis\":1787758817539,\"durationMillis\":421000,"
			+ "\"status\":\"COMPLETED\"}],"
			+ "\"" + tree + "\":[]}");

		final List<Run> loaded = storage.load().getRoutines().get(0).historyOrEmpty();

		assertEquals("a run that was under the old key alone was not carried across, which is the"
				+ " user watching a run they can see in their config never reach the panel",
			8, loaded.size());
		assertEquals("the run that was under the old key is newer than all seven and did not come"
				+ " back last, so the clock's newest run is not the newest run it has",
			1_787_758_396_539L, loaded.get(7).getStartedAtEpochMillis());
		assertEquals(1_787_666_385_180L, loaded.get(0).getStartedAtEpochMillis());
		assertEquals("and it is the personal best, which is what a merge that appended in the wrong"
				+ " order would still have got right, so this is the order and not the pick",
			421_000L, RoutineStats.personalBest(herbOf(loaded)).getDurationMillis());

		assertFalse("the old key was read and its runs landed, so it has nothing left to say and"
				+ " must go, otherwise it is read again on every load forever",
			config.containsKey(whole("history")));

		// The second load, and every load after it. A merge that is not
		// idempotent grows a user's history by a copy of itself each time.
		assertEquals("loading again added the same runs a second time",
			8, storage.load().getRoutines().get(0).historyOrEmpty().size());

		// And with the old key put back, which is what a sync does.
		config.put(whole("history"), "{\"" + herb + "\":[{\"startedAtEpochMillis\":1787758396539,"
			+ "\"finishedAtEpochMillis\":1787758817539,\"durationMillis\":421000,"
			+ "\"status\":\"COMPLETED\"}]}");
		assertEquals("the old key came back from a sync and its run was added a second time",
			8, storage.load().getRoutines().get(0).historyOrEmpty().size());
	}

	/**
	 * The runs of the clock the fixture above is about, as a list a statistic
	 * can be taken off.
	 */
	private static Routine herbOf(List<Run> runs)
	{
		final Routine routine = new Routine("herb-id", "Herb run");
		routine.setHistory(new ArrayList<>(runs));
		return routine;
	}

	/**
	 * A config manager that throws must not stop a save, and must not stop the
	 * other clocks being written. One clock nobody can write costs the user that
	 * clock rather than all of them.
	 */
	@Test
	public void oneClockThatCannotBeWrittenDoesNotCostTheOthers()
	{
		final ConfigManager throwing = mock(ConfigManager.class);
		doAnswer(call ->
		{
			final String key = call.getArgument(1, String.class);
			if (key.contains("tree-id"))
			{
				throw new IllegalArgumentException("no");
			}
			writes.add(key);
			return null;
		}).when(throwing).setConfiguration(eq(GROUP), anyString(), anyString());
		when(throwing.getConfigurationKeys(anyString())).thenReturn(Collections.emptyList());

		new ClockworkStorage(throwing, new Gson()).save(threeClocksWithRuns(), TriggerLibrary.empty());

		assertTrue(writes.contains(PREFIX + "herb-id"));
		assertTrue(writes.contains(PREFIX + "clockwork-quick"));
		assertFalse(writes.contains(PREFIX + "tree-id"));
	}

	/**
	 * What an existing user's first start under this build actually does, from
	 * the config keys through the real storage and into the real controller.
	 *
	 * <p>Fifty stored runs, no totals key, and the record set months ago sitting
	 * at position four where a trim that took the newest ten first would already
	 * have destroyed it. There is no backup and no export, so that trim would be
	 * the end of it.
	 */
	@Test
	public void anExistingUserKeepsTheirOldRecordAndGetsCountedFromWhatIsStored()
	{
		final List<Run> stored = new ArrayList<>();
		for (int i = 0; i < 50; i++)
		{
			stored.add(run(i, i + 600_000L, 600_000L));
		}
		final Run recordFromMonthsAgo = run(999L, 999L + 421_000L, 421_000L);
		stored.set(3, recordFromMonthsAgo);

		config.put(whole("routines"),
			"{\"version\":1,\"routines\":[{\"id\":\"herb-id\",\"name\":\"Herb run\"}]}");
		config.put(whole(PREFIX + "herb-id"), new Gson().toJson(stored));

		final ClockworkStorage.Saved saved = storage.load();
		assertEquals("the load hands over everything that is stored, untrimmed",
			50, saved.getRoutines().get(0).historyOrEmpty().size());
		assertTrue("and nothing has been counted for this clock yet",
			saved.getRoutines().get(0).totalsOrZero().isEmpty());

		final RoutineController controller = new RoutineController(() -> 0L);
		controller.load(saved.getRoutines(), TriggerLibrary.empty());
		final Routine loaded = controller.get("herb-id");

		assertEquals("counted from all fifty stored runs", 50, loaded.totalsOrZero().getCompletedRuns());
		assertEquals(RunHistory.MAX_KEPT, loaded.historyOrEmpty().size());
		assertEquals("the record set long ago is still the record",
			421_000L, RoutineStats.personalBest(loaded).getDurationMillis());
		assertEquals(Long.valueOf(596_420L), RoutineStats.allTimeAverage(loaded));
	}

	/**
	 * The author's own profile, from the config keys through the real storage
	 * and into the real controller, which is the whole of what went wrong.
	 *
	 * <p>Seven runs on the clock's own key, a totals key counting those seven,
	 * and an eighth run still sitting under the one key every clock used to
	 * share. The load brings the eighth run across, exactly as it is meant to,
	 * and the totals were counted before it arrived and knew nothing about it.
	 * What the user saw was "Average 16:00 over 8" beside "All time 16:01 over
	 * 7", a lifetime count smaller than the runs in front of them.
	 *
	 * <p>Both halves are asserted here rather than the repair alone, because
	 * the merge landing and the totals being reconciled are one story and a
	 * test of either on its own would have passed before the fix.
	 */
	@Test
	public void aRunRecoveredByTheMergeIsCountedRatherThanLeftOutOfTheLifetimeFigure()
	{
		final List<Run> onItsOwnKey = new ArrayList<>();
		for (int i = 0; i < 7; i++)
		{
			onItsOwnKey.add(run(i * 1_000_000L, i * 1_000_000L + 961_000L, 961_000L));
		}
		final Run recovered = run(7_000_000L, 7_953_000L, 953_000L);

		config.put(whole("routines"),
			"{\"version\":1,\"routines\":[{\"id\":\"herb-id\",\"name\":\"Herb run\"}]}");
		config.put(whole(PREFIX + "herb-id"), new Gson().toJson(onItsOwnKey));
		config.put(whole(TOTALS_PREFIX + "herb-id"), "{\"completedRuns\":7,\"completedMillis\":6727000}");
		config.put(whole("history"),
			"{\"herb-id\":" + new Gson().toJson(Collections.singletonList(recovered)) + "}");

		final ClockworkStorage.Saved saved = storage.load();

		assertEquals("the run under the old key was not brought across, so this is no longer the"
				+ " state the repair is for",
			8, saved.getRoutines().get(0).historyOrEmpty().size());
		assertEquals("and the totals came back exactly as they were stored, knowing nothing about it",
			7, saved.getRoutines().get(0).totalsOrZero().getCompletedRuns());

		final RoutineController controller = new RoutineController(() -> 0L);
		controller.load(saved.getRoutines(), TriggerLibrary.empty());
		final Routine loaded = controller.get("herb-id");

		assertEquals("the lifetime count is still under the runs the clock is holding",
			8, loaded.totalsOrZero().getCompletedRuns());
		assertEquals(Long.valueOf(960_000L), RoutineStats.allTimeAverage(loaded));
		assertEquals("the two averages still disagree about how many runs there have been",
			RoutineStats.completedInLast(loaded, RunHistory.RECENT_KEPT),
			RoutineStats.completedAllTime(loaded));
	}

	/**
	 * A totals value nobody can read costs the user an exact lifetime count and
	 * gives them one taken from the runs still stored, which is the safe
	 * direction to be wrong in. It must never throw, because the only copy of
	 * their runs is being read on the same pass.
	 */
	@Test
	public void aDamagedTotalsValueReadsAsNothingCountedRatherThanThrowing()
	{
		final List<Routine> routines = threeClocksWithRuns();
		storage.save(routines, TriggerLibrary.empty());
		config.put(whole(TOTALS_PREFIX + "herb-id"), "{\"completedRuns\":");

		final Routine loaded = storage.load().getRoutines().get(0);

		assertEquals("herb-id", loaded.getId());
		assertTrue(loaded.totalsOrZero().isEmpty());
		assertEquals("and the runs beside it are untouched", 2, loaded.historyOrEmpty().size());
	}

	private static String whole(String key)
	{
		return GROUP + "." + key;
	}

	private static List<Routine> threeClocksWithRuns()
	{
		final Routine herb = new Routine("herb-id", "Herb run");
		herb.setHistory(new ArrayList<>(Arrays.asList(
			run(0L, 1200L, 1200L, new Lap("Ardougne", 600L, 600L), new Lap("Catherby", 1200L, 600L)),
			run(2000L, 3400L, 1400L))));

		final Routine tree = new Routine("tree-id", "Tree run");
		tree.setHistory(new ArrayList<>(Collections.singletonList(run(0L, 300L, 300L))));

		final Routine quick = new Routine(Routine.QUICK_ID, Routine.QUICK_NAME);
		quick.setHistory(new ArrayList<>(Collections.singletonList(run(0L, 40L, 40L))));

		final List<Routine> routines = new ArrayList<>(Arrays.asList(herb, tree, quick));
		for (Routine routine : routines)
		{
			counted(routine);
		}
		return routines;
	}

	/**
	 * Gives a clock the lifetime totals its runs imply, which is the state a
	 * clock is in by the time the plugin is holding it. A fixture that skipped
	 * this would have every clock writing an empty totals key and would be
	 * testing a state the plugin never produces.
	 */
	private static void counted(Routine routine)
	{
		for (Run recorded : routine.historyOrEmpty())
		{
			if (recorded.isCompleted())
			{
				routine.getTotals().record(recorded.getDurationMillis());
			}
		}
	}

	private static Run run(long startedAt, long finishedAt, long duration, Lap... laps)
	{
		return new Run(startedAt, finishedAt, duration, new ArrayList<>(Arrays.asList(laps)),
			Status.COMPLETED);
	}
}

package com.clockwork;

import ch.qos.logback.classic.Level;
import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.AppenderBase;
import java.util.ArrayList;
import java.util.List;
import org.slf4j.LoggerFactory;

/**
 * Everything the plugin logs, held where a test can read it.
 *
 * <p>The plugin swallows on purpose. Every entry point is wrapped in
 * {@code Diagnostics.guard}, which catches and writes a line rather than
 * throwing, so a wiring bug shows up as a test failing for a reason that makes
 * no sense until you read what was logged. It is also where a profile switch
 * says what the switch cost, which is the only outside evidence that a run in
 * progress was dropped rather than carried across.
 *
 * <p>Two things follow from being able to read the level as well as the text.
 * A test can assert that a message was made at all, and a test can assert that
 * a message on a hot path was not made too loudly. The second is a plugin hub
 * rejection reason in its own right.
 *
 * <p>Test only. Nothing here is packaged, and logback is on the test classpath
 * because the client brings it.
 */
public class LogCapture implements AutoCloseable
{
	/**
	 * The logger every class in the plugin sits under, so one attachment
	 * catches all of them.
	 */
	private static final String ROOT = "com.clockwork";

	private final List<ILoggingEvent> events = new ArrayList<>();

	private final Logger logger;
	private final Level restore;
	private final AppenderBase<ILoggingEvent> appender;

	public LogCapture()
	{
		logger = (Logger) LoggerFactory.getLogger(ROOT);
		restore = logger.getLevel();

		// Turned down to debug because that is where the guard writes, and a
		// test that could not see debug could not tell a swallowed failure
		// from a clean run.
		logger.setLevel(Level.DEBUG);

		appender = new AppenderBase<ILoggingEvent>()
		{
			@Override
			protected void append(ILoggingEvent event)
			{
				synchronized (events)
				{
					events.add(event);
				}
			}
		};
		appender.setName("clockwork-test-capture");
		appender.start();
		logger.addAppender(appender);
	}

	/**
	 * Every event so far, oldest first.
	 */
	public List<ILoggingEvent> events()
	{
		synchronized (events)
		{
			return new ArrayList<>(events);
		}
	}

	/**
	 * The formatted text of everything logged so far, one entry per line.
	 */
	public String text()
	{
		final StringBuilder out = new StringBuilder();
		for (ILoggingEvent event : events())
		{
			out.append(event.getLevel())
				.append(' ')
				.append(event.getFormattedMessage())
				.append(System.lineSeparator());
		}
		return out.toString();
	}

	/**
	 * The loudest level anything was logged at, or null when nothing was.
	 */
	public Level loudest()
	{
		Level loudest = null;
		for (ILoggingEvent event : events())
		{
			if (loudest == null || event.getLevel().isGreaterOrEqual(loudest))
			{
				loudest = event.getLevel();
			}
		}
		return loudest;
	}

	/**
	 * Detaches. What was already captured stays readable, so a test can shut
	 * the plugin down and then read what the shutdown wrote.
	 */
	@Override
	public void close()
	{
		logger.detachAppender(appender);
		appender.stop();
		logger.setLevel(restore);
	}
}

package com.clockwork;

import com.clockwork.core.AlertOverride;
import com.clockwork.core.ClockMode;
import com.clockwork.core.Mode;
import com.clockwork.core.OverlayOverride;
import com.clockwork.core.Routine;
import com.clockwork.core.Run;
import com.clockwork.core.Status;
import com.clockwork.core.Toggle;
import com.clockwork.core.Trigger;
import com.clockwork.core.TriggerType;
import com.google.gson.Gson;
import java.util.ArrayList;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * {@link Routine#copy()} has to list every persisted field by hand, because
 * reflection is not allowed in a plugin. A field added to the class and not
 * added to the copy would go missing from every export and from every applied
 * edit, quietly, and only for that one field.
 *
 * <p>So rather than list the fields again here and have two lists to keep in
 * step, this compares what Gson writes for the copy against what Gson writes
 * for the original. Gson does walk the fields, so anything the copy forgot
 * shows up as a difference. The runs are not in that comparison because they
 * are transient, which is exactly why they are also not in an export.
 */
public class RoutineCopyTest
{
	private static final Gson GSON = new Gson();

	private static Routine filledIn()
	{
		Routine routine = new Routine("a", "Herb run");
		routine.setMode(Mode.COUNT_DOWN);
		routine.setTargetMillis(360_000);
		routine.setStopAtZero(true);
		routine.setClock(ClockMode.LOGGED_IN_ONLY);
		routine.setLapsEnabled(true);
		routine.setAbandonAfterMillis(2_700_000L);
		routine.setRestartOnStart(true);
		routine.setOverlay(OverlayOverride.WHILE_RUNNING);
		routine.setShowDelta(Toggle.ON);
		routine.setAlert(AlertOverride.SCREEN);
		routine.setSound(Toggle.OFF);
		routine.setNotify(Toggle.ON);
		routine.setStartTrigger(Trigger.saved("Note herbs"));
		routine.setLapTrigger(Trigger.saved("Leprechaun"));
		routine.setStopTrigger(Trigger.of(TriggerType.BANK_CHEST));
		routine.getHistory().add(new Run(1, 2, 1, new ArrayList<>(), Status.COMPLETED));
		return routine;
	}

	@Test
	public void aCopyCarriesEveryPersistedField()
	{
		Routine original = filledIn();

		assertEquals("a field was added to Routine and not to copy()",
			GSON.toJson(original), GSON.toJson(original.copy()));
	}

	@Test
	public void aCopyIsADifferentObjectWithItsOwnEmptyHistory()
	{
		Routine original = filledIn();
		Routine copy = original.copy();

		assertNotSame(original, copy);
		assertTrue("a copy starts with no runs", copy.historyOrEmpty().isEmpty());

		copy.setName("Something else");
		copy.getHistory().add(new Run(3, 4, 1, new ArrayList<>(), Status.COMPLETED));

		assertEquals("Herb run", original.getName());
		assertEquals("and changing one does not reach the other", 1, original.historyOrEmpty().size());
	}

	/**
	 * A copy is what an export and an import are made of, so it carries no
	 * lifetime count either. Somebody else's all time average is not part of a
	 * clock's settings any more than their personal best is, and the count is
	 * the one derived figure that is stored rather than worked out, so it is
	 * the one that could have travelled.
	 */
	@Test
	public void aCopyCarriesNoLifetimeTotals()
	{
		Routine original = filledIn();
		original.getTotals().record(300_000L);
		assertFalse(original.totalsOrZero().isEmpty());

		Routine copy = original.copy();

		assertTrue("an exported clock carried the owner's lifetime figures with it",
			copy.totalsOrZero().isEmpty());

		copy.getTotals().record(1_000L);
		assertEquals("and the two do not share one set of totals",
			1, original.totalsOrZero().getCompletedRuns());
	}

	@Test
	public void anEmptyRoutineCopiesToAnEmptyRoutine()
	{
		Routine blank = new Routine();
		Routine copy = blank.copy();

		assertNull(copy.getId());
		assertEquals(GSON.toJson(blank), GSON.toJson(copy));
	}
}

package com.clockwork;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.client.audio.AudioPlayer;

/**
 * Counts the chime instead of playing it.
 *
 * <p>The build runs headless with no sound card, so the real player would throw
 * a {@code LineUnavailableException} that the plugin catches and logs at debug,
 * and the test would see nothing either way. Counting turns a silent success
 * and a silent failure into two different answers.
 *
 * <p>Subclassing works because {@code AudioPlayer} has a public no argument
 * constructor and {@code play} is not final. Only the overload the plugin uses
 * is overridden. The other two are left alone deliberately, so a change to
 * which one the plugin calls shows up as a test that tries to open a sound card
 * rather than as one that quietly stops counting.
 */
class SilentAudioPlayer extends AudioPlayer
{
	private final List<String> played = new ArrayList<>();

	@Override
	public void play(Class<?> owner, String resource, float gain)
	{
		played.add(resource);
	}

	int playCount()
	{
		return played.size();
	}

	/**
	 * Which clips were played, in order. There is more than one now, and a
	 * count on its own cannot tell a countdown counted in from one that played
	 * its chime three times over.
	 */
	List<String> played()
	{
		return Collections.unmodifiableList(played);
	}
}

package com.clockwork;

import com.clockwork.core.AlertOverride;
import com.clockwork.core.AlertStyle;
import com.clockwork.core.ClockMode;
import com.clockwork.core.Mode;
import com.clockwork.core.OverlayMode;
import com.clockwork.core.OverlayOverride;
import com.clockwork.core.Status;
import com.clockwork.core.SubSecond;
import com.clockwork.core.Toggle;
import com.clockwork.core.TriggerType;
import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The name every persisted enum constant is stored under, written down once so
 * that changing one is a decision rather than an accident.
 *
 * <p>This guards the quietest failure the plugin has. A persisted constant
 * carries a {@code SerializedName}, and that annotation replaces the name based
 * binding rather than adding to it. Rename it, or drop it, and a value stored
 * under the old name binds as null. Nothing throws, nothing is logged, and the
 * user finds out weeks later that a clock counts the wrong way or a run has no
 * status.
 *
 * <p>So every constant is asked what Gson actually writes for it, and the full
 * set is compared against a golden list checked in here. A constant added,
 * removed, or respelled fails here rather than in somebody's config, and anyone
 * who means to do it has to say so by editing the list.
 *
 * <p>The list is written in the order the constants are declared, because that
 * is the order a reader will find them in, and a missing annotation is caught
 * separately from a wrong one so the failure says which of the two happened.
 */
public class StoredEnumNamesTest
{
	private static final Gson GSON = new Gson();

	/**
	 * What Gson writes for one constant, with the quotes off.
	 */
	private static String written(Enum<?> value)
	{
		final String json = GSON.toJson(value);
		assertTrue(json, json.startsWith("\"") && json.endsWith("\""));
		return json.substring(1, json.length() - 1);
	}

	/**
	 * Holds one enum to its golden list, annotation by annotation.
	 *
	 * <p>The annotation is looked for on the field itself rather than inferred
	 * from what Gson writes, because Gson falls back to the constant's own name
	 * when there is no annotation, and that fallback is exactly the accident
	 * this test exists to catch.
	 */
	private static void check(Class<? extends Enum<?>> type, String... golden)
	{
		final Enum<?>[] values = type.getEnumConstants();
		assertEquals(type.getSimpleName() + " has a constant the golden list does not name",
			golden.length, values.length);

		final List<String> stored = new ArrayList<>();
		for (Enum<?> value : values)
		{
			final SerializedName annotation;
			try
			{
				annotation = type.getDeclaredField(value.name()).getAnnotation(SerializedName.class);
			}
			catch (NoSuchFieldException ex)
			{
				throw new AssertionError(type.getSimpleName() + "." + value.name() + " has no field", ex);
			}

			assertNotNull(type.getSimpleName() + "." + value.name()
				+ " is persisted and carries no SerializedName, so it is stored under its own"
				+ " constant name and renaming the constant would silently orphan every stored value",
				annotation);
			assertEquals("the annotation on " + type.getSimpleName() + "." + value.name()
				+ " is not what Gson writes for it", annotation.value(), written(value));
			stored.add(written(value));
		}

		assertEquals("the stored names of " + type.getSimpleName() + " have moved away from the golden"
			+ " list, which is a one way door once anybody has saved a clock",
			Arrays.asList(golden), stored);
	}

	@Test
	public void modeIsStoredUnderTheNamesItAlwaysWas()
	{
		check(Mode.class, "countup", "countdown");
	}

	@Test
	public void clockModeIsStoredUnderTheNamesItAlwaysWas()
	{
		check(ClockMode.class, "wallclock", "loggedinonly");
	}

	@Test
	public void statusIsStoredUnderTheNamesItAlwaysWas()
	{
		check(Status.class, "completed", "abandoned");
	}

	@Test
	public void subSecondIsStoredUnderTheNamesItAlwaysWas()
	{
		check(SubSecond.class, "none", "tenths", "hundredths");
	}

	@Test
	public void toggleIsStoredUnderTheNamesItAlwaysWas()
	{
		check(Toggle.class, "useglobal", "on", "off");
	}

	/**
	 * A clock's own timer box setting, which rides in the routines blob on
	 * {@code Routine.overlay} and so is bound by Gson through the annotation.
	 */
	@Test
	public void overlayOverrideIsStoredUnderTheNamesItAlwaysWas()
	{
		check(OverlayOverride.class, "useglobal", "always", "whilerunning", "never");
	}

	/**
	 * A clock's own answer to what it draws when it finishes, which rides in
	 * the routines blob on {@code Routine.alert} and so is bound by Gson
	 * through the annotation.
	 */
	@Test
	public void alertOverrideIsStoredUnderTheNamesItAlwaysWas()
	{
		check(AlertOverride.class, "useglobal", "none", "timerbox", "screen");
	}

	@Test
	public void triggerTypeIsStoredUnderTheNamesItAlwaysWas()
	{
		check(TriggerType.class, "none", "teleport", "bankchest", "mineiron", "custom");
	}

	/**
	 * The plugin wide timer box setting, which is stored a different way and
	 * therefore guarded a different way.
	 *
	 * <p>{@link OverlayMode} never reaches the routines blob. It is a config
	 * item, and RuneLite's config manager writes an enum with {@code name()}
	 * and reads it back with {@code Enum.valueOf}, so what sits in the settings
	 * file is {@code WHILE_RUNNING} and the annotation is not consulted at all.
	 * Renaming the constant is what would orphan a saved choice, and it would
	 * do it exactly as quietly as a respelled annotation does everywhere else
	 * in this file, so the constant names are pinned here.
	 *
	 * <p>There is a live reason this is not hypothetical. The update that
	 * introduced this setting writes one of these names into the settings file
	 * for every user who had turned the timer boxes off, so the name has been
	 * committed to a stranger's disk.
	 */
	@Test
	public void overlayModeIsWrittenToConfigUnderTheConstantNamesItAlwaysWas()
	{
		checkConstantNames(OverlayMode.class, "ALWAYS", "WHILE_RUNNING", "NEVER");
	}

	/**
	 * What a finished clock does on screen, which is a config item and nothing
	 * else.
	 *
	 * <p>It belongs on this side of the file rather than the other for the same
	 * reason {@link OverlayMode} does. Nothing persists it through Gson, so the
	 * name that has been committed to a stranger's disk is the constant name,
	 * and renaming a constant is what would quietly put an alert style the user
	 * chose back to the default.
	 *
	 * <p>It carries no {@code SerializedName} at all. There is a per clock
	 * version of this setting, but it is {@link AlertOverride} rather than this
	 * enum, and that one carries annotations of its own and is checked above.
	 * Nothing puts an {@code AlertStyle} in the blob, so an annotation here
	 * would say it is persisted when it is not, and moving this test to
	 * {@link #check} would then fail saying exactly that.
	 */
	@Test
	public void alertStyleIsWrittenToConfigUnderTheConstantNamesItAlwaysWas()
	{
		checkConstantNames(AlertStyle.class, "NONE", "TIMER_BOX", "SCREEN");
	}

	/**
	 * Holds one config enum to the constant names the config manager stores it
	 * under, which is a different contract from the one {@link #check} guards
	 * and is checked separately because a config enum is allowed to have no
	 * annotation at all.
	 */
	private static void checkConstantNames(Class<? extends Enum<?>> type, String... golden)
	{
		final Enum<?>[] values = type.getEnumConstants();
		final List<String> names = new ArrayList<>();
		for (Enum<?> value : values)
		{
			names.add(value.name());
		}

		assertEquals("the constant names of " + type.getSimpleName() + " have moved away from the"
			+ " golden list. RuneLite stores a config enum by its constant name, so a rename binds"
			+ " every saved value to null without saying anything",
			Arrays.asList(golden), names);
	}
}

package com.clockwork.core;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

/**
 * The last three seconds of a countdown, announced one at a time.
 *
 * <p>Every test here collects the seconds the controller announced and compares
 * the whole list, because the thing worth protecting is not that a beat happens
 * but that each of the three happens exactly once. The refresh that drives this
 * runs twenty times a second while a clock is moving, so a rule written as
 * "less than three seconds left" would announce sixty beats instead of three,
 * and a count of them is what says so.
 *
 * <p>The alerts are somewhere else entirely. What is decided here is when a
 * beat is due, which is a question about a run and belongs beside the deadline
 * it is measured from. {@code AlertMatrixTest} covers whether a clock that is
 * silent stays silent, and {@code ClockworkWiringTest} covers the two ends
 * being joined.
 */
public class CountInTest
{
	private static final long T0 = 1_700_000_000_000L;

	/**
	 * What the refresh does while a clock is moving, so the ticks a count in
	 * really sees are this far apart.
	 */
	private static final long REFRESH = 50;

	private FakeClock clock;
	private RoutineController controller;

	private final List<Integer> counted = new ArrayList<>();
	private final List<String> countedFor = new ArrayList<>();
	private final List<String> ended = new ArrayList<>();

	@Before
	public void setUp()
	{
		clock = new FakeClock(T0);
		controller = new RoutineController(clock);
		counted.clear();
		countedFor.clear();
		ended.clear();

		controller.addListener(new RoutineListener()
		{
			@Override
			public void onCountInSecond(Routine routine, int secondsLeft)
			{
				counted.add(secondsLeft);
				countedFor.add(routine.getId());
			}

			@Override
			public void onRunFinished(Routine routine, Run run)
			{
				ended.add("finished");
			}

			@Override
			public void onCountdownExpired(Routine routine)
			{
				ended.add("expired");
			}
		});
	}

	private Routine countdown(long targetMillis)
	{
		return countdown(targetMillis, true);
	}

	private Routine countdown(long targetMillis, boolean stopAtZero)
	{
		Routine r = controller.create("Countdown");
		controller.update(r.getId(), x ->
		{
			x.setMode(Mode.COUNT_DOWN);
			x.setTargetMillis(targetMillis);
			x.setStopAtZero(stopAtZero);
		});
		return r;
	}

	/**
	 * Ticks the way the refresh ticks, which is every fiftieth of a second.
	 */
	private void run(long millis)
	{
		for (long elapsed = 0; elapsed < millis; elapsed += REFRESH)
		{
			clock.advance(REFRESH);
			controller.tick(clock.getAsLong());
		}
	}

	/**
	 * The whole of it, at the tick rate it really runs at. Three beats, in
	 * order, and one each.
	 */
	@Test
	public void threeSecondsAreCountedInOnceEachAtTheRealTickRate()
	{
		Routine r = countdown(10_000);
		controller.start(r.getId());

		run(6_900);
		assertTrue("something was counted in while there were still three seconds to go",
			counted.isEmpty());

		run(3_100);

		assertEquals(Arrays.asList(3, 2, 1), counted);
		assertEquals("the countdown did not end at zero", 1, ended.size());
	}

	/**
	 * The beat lands on the boundary rather than a tick early or a tick late,
	 * so a user hearing three, two, one is hearing the seconds they have left.
	 */
	@Test
	public void eachBeatLandsOnItsOwnSecond()
	{
		Routine r = countdown(10_000);
		controller.start(r.getId());

		clock.advance(6_999);
		controller.tick(clock.getAsLong());
		assertTrue("a beat with 3001ms left is a beat too early", counted.isEmpty());

		clock.advance(1);
		controller.tick(clock.getAsLong());
		assertEquals(Collections.singletonList(3), counted);

		clock.advance(999);
		controller.tick(clock.getAsLong());
		assertEquals(Collections.singletonList(3), counted);

		clock.advance(1);
		controller.tick(clock.getAsLong());
		assertEquals(Arrays.asList(3, 2), counted);
	}

	/**
	 * A clock counting up has no known end, so there is nothing to count in to
	 * and nothing is announced however long it runs.
	 */
	@Test
	public void aClockCountingUpIsNeverCountedIn()
	{
		Routine r = controller.create("Herb run");
		controller.start(r.getId());

		run(600_000);

		assertTrue("a clock with no end announced the last seconds of it", counted.isEmpty());
	}

	/**
	 * A countdown pauses when the player logs out, and a paused run has its
	 * remaining time held still, so it crosses nothing. What it was owed when
	 * it stopped is what it is owed when it comes back.
	 */
	@Test
	public void aPausedCountdownIsNotCountedInAndKeepsWhatItIsOwed()
	{
		Routine r = countdown(10_000);
		controller.update(r.getId(), x -> x.setClock(ClockMode.LOGGED_IN_ONLY));
		controller.start(r.getId());

		run(7_400);
		assertEquals("the three landed before the player logged out",
			Collections.singletonList(3), counted);

		controller.setLoggedIn(false);
		run(600_000);

		assertEquals("a paused countdown was counted in, so a player at the login screen hears a"
				+ " count in for a run that is not moving",
			Collections.singletonList(3), counted);
		assertTrue("and it must not have reached zero either", ended.isEmpty());

		controller.setLoggedIn(true);
		run(2_600);

		assertEquals("the beats it was still owed did not arrive after it came back",
			Arrays.asList(3, 2, 1), counted);
		assertEquals(1, ended.size());
	}

	/**
	 * A countdown with less than three seconds on it gets the beats that fit
	 * and no more, so nothing is ever announced for a moment that had already
	 * passed when the run began.
	 */
	@Test
	public void aShortCountdownGetsTheBeatsThatFitInIt()
	{
		assertEquals("exactly three seconds is three beats", Arrays.asList(3, 2, 1),
			beatsOf(3_000));
		assertEquals("two and a half seconds has no three in it", Arrays.asList(2, 1),
			beatsOf(2_500));
		assertEquals(Arrays.asList(2, 1), beatsOf(2_000));
		assertEquals(Collections.singletonList(1), beatsOf(1_200));
		assertEquals("under a second has no whole second left to count in",
			Collections.emptyList(), beatsOf(900));
		assertEquals("and a countdown of nothing at all simply ends", Collections.emptyList(),
			beatsOf(0));
	}

	private List<Integer> beatsOf(long targetMillis)
	{
		counted.clear();
		Routine r = countdown(targetMillis);
		controller.start(r.getId());
		run(targetMillis + 1_000);
		return new ArrayList<>(counted);
	}

	/**
	 * A tick that arrives late has crossed more than one boundary. It announces
	 * one beat, for the second the countdown is actually in, rather than
	 * emptying the whole count in at once.
	 */
	@Test
	public void aLateTickAnnouncesTheSecondItIsInRatherThanAllOfThem()
	{
		Routine r = countdown(10_000, false);
		controller.start(r.getId());

		// A client that stalls from three and a half seconds left to four
		// tenths of a second left, which is one tick either side of the gap.
		clock.advance(6_500);
		controller.tick(clock.getAsLong());
		clock.advance(3_100);
		controller.tick(clock.getAsLong());

		assertEquals("a stall emptied the count in in one moment",
			Collections.singletonList(1), counted);

		run(2_000);
		assertEquals("and nothing was announced past zero", Collections.singletonList(1), counted);
	}

	/**
	 * Nothing is counted in past zero, whichever way the clock is set. A
	 * countdown left to run into overtime has already been counted in and is
	 * not counted in again on the way out.
	 */
	@Test
	public void aCountdownInOvertimeIsCountedInOnTheWayToZeroAndNotAfterIt()
	{
		Routine r = countdown(5_000, false);
		controller.start(r.getId());

		run(5_000);
		assertEquals(Arrays.asList(3, 2, 1), counted);
		assertEquals(Collections.singletonList("expired"), ended);

		run(600_000);

		assertEquals("a clock in overtime kept counting itself in", Arrays.asList(3, 2, 1), counted);
		assertTrue("and it is still running, which is what overtime is",
			controller.isRunning(r.getId()));
	}

	/**
	 * A run that is thrown away mid count in takes the count in with it, and a
	 * new run gets a new one. The latch lives on the run, so there is nothing
	 * to reset by hand and nothing that can be left behind.
	 */
	@Test
	public void aCancelledRunStartedAgainIsCountedInAgain()
	{
		Routine r = countdown(10_000);
		controller.start(r.getId());

		run(8_000);
		assertEquals(Arrays.asList(3, 2), counted);

		controller.cancel(r.getId());
		assertFalse(controller.isRunning(r.getId()));

		counted.clear();
		controller.start(r.getId());
		run(10_000);

		assertEquals("the new run was counted in from where the cancelled one left off",
			Arrays.asList(3, 2, 1), counted);
	}

	/**
	 * The same for a restart, which is a clock set to start over when its
	 * trigger fires again. The run in progress is discarded mid count in and
	 * the one replacing it is counted in from three.
	 */
	@Test
	public void aRestartMidCountInIsCountedInFromThreeAgain()
	{
		Routine r = countdown(10_000);
		controller.update(r.getId(), x -> x.setRestartOnStart(true));
		controller.start(r.getId());

		run(8_000);
		assertEquals(Arrays.asList(3, 2), counted);

		counted.clear();
		controller.start(r.getId());
		run(10_000);

		assertEquals(Arrays.asList(3, 2, 1), counted);
	}

	/**
	 * A run stopped by hand during the count in is over, so the beats it had
	 * not reached yet never arrive.
	 */
	@Test
	public void aRunStoppedMidCountInIsCountedInNoFurther()
	{
		Routine r = countdown(10_000);
		controller.start(r.getId());

		run(7_500);
		assertEquals(Collections.singletonList(3), counted);

		controller.stop(r.getId());
		run(10_000);

		assertEquals("a run that had already been stopped went on counting itself in",
			Collections.singletonList(3), counted);
	}

	/**
	 * A clock that abandons a run it has been left in wins over the count in,
	 * the same way it wins over the automatic stop at zero.
	 */
	@Test
	public void anAbandonedRunIsCountedInNoFurther()
	{
		Routine r = countdown(10_000);
		controller.update(r.getId(), x -> x.setAbandonAfterMillis(7_500L));
		controller.start(r.getId());

		run(10_000);

		assertEquals("a run that was abandoned mid count in kept counting",
			Collections.singletonList(3), counted);
		assertFalse(controller.isRunning(r.getId()));
	}

	/**
	 * Two countdowns at once are counted in separately, since the latch is on
	 * the run rather than on the plugin. They overlap, so the beats interleave,
	 * and each clock still gets its own three.
	 */
	@Test
	public void twoCountdownsAtOnceAreCountedInSeparately()
	{
		Routine first = countdown(10_000);
		Routine second = countdown(12_000);
		controller.start(first.getId());
		controller.start(second.getId());

		run(12_000);

		assertEquals("one clock's count in was cut short by the other's",
			Arrays.asList(3, 2, 1), beatsFor(first.getId()));
		assertEquals(Arrays.asList(3, 2, 1), beatsFor(second.getId()));
	}

	/**
	 * The beats announced for one clock, in order, out of the beats announced
	 * for every clock.
	 */
	private List<Integer> beatsFor(String routineId)
	{
		final List<Integer> beats = new ArrayList<>();
		for (int i = 0; i < counted.size(); i++)
		{
			if (routineId.equals(countedFor.get(i)))
			{
				beats.add(counted.get(i));
			}
		}
		return beats;
	}
}

package com.clockwork.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import org.junit.Test;

public class DurationFormatterTest
{
	private static final long HOUR = 3_600_000L;

	private static String fmt(long millis, boolean h, boolean m, boolean s, SubSecond sub)
	{
		return DurationFormatter.format(millis, new DurationFormat(h, m, s, sub));
	}

	@Test
	public void zero()
	{
		assertEquals("0:00", fmt(0, true, true, true, SubSecond.NONE));
		assertEquals("0:00.0", fmt(0, true, true, true, SubSecond.TENTHS));
		assertEquals("0:00.00", fmt(0, true, true, true, SubSecond.HUNDREDTHS));
	}

	@Test
	public void subSecondPrecision()
	{
		assertEquals("0:01", fmt(1234, true, true, true, SubSecond.NONE));
		assertEquals("0:01.2", fmt(1234, true, true, true, SubSecond.TENTHS));
		assertEquals("0:01.23", fmt(1234, true, true, true, SubSecond.HUNDREDTHS));
		assertEquals("0:00.9", fmt(999, true, true, true, SubSecond.TENTHS));
		assertEquals("0:00.99", fmt(999, true, true, true, SubSecond.HUNDREDTHS));
	}

	@Test
	public void justUnderOneHourKeepsHoursHidden()
	{
		assertEquals("59:59.99", fmt(HOUR - 10, true, true, true, SubSecond.HUNDREDTHS));
		assertEquals("59:59", fmt(HOUR - 10, true, true, true, SubSecond.NONE));
	}

	@Test
	public void exactlyOneHourShowsHours()
	{
		assertEquals("1:00:00.00", fmt(HOUR, true, true, true, SubSecond.HUNDREDTHS));
		assertEquals("1:00:00", fmt(HOUR, true, true, true, SubSecond.NONE));
	}

	@Test
	public void pastOneHour()
	{
		assertEquals("1:01:01.23", fmt(HOUR + 61_234, true, true, true, SubSecond.HUNDREDTHS));
	}

	@Test
	public void multiHourDoesNotWrap()
	{
		assertEquals("2:00:00", fmt(2 * HOUR, true, true, true, SubSecond.NONE));
		assertEquals("13:37:00", fmt(13 * HOUR + 37 * 60_000L, true, true, true, SubSecond.NONE));
		assertEquals("100:00:00", fmt(100 * HOUR, true, true, true, SubSecond.NONE));
	}

	@Test
	public void minutesCarryTheHoursWhenHoursAreOff()
	{
		// Sixty one minutes must never be mistakable for one minute.
		String oneMinute = fmt(60_000, false, true, true, SubSecond.NONE);
		String sixtyOne = fmt(61 * 60_000L, false, true, true, SubSecond.NONE);
		assertEquals("1:00", oneMinute);
		assertEquals("61:00", sixtyOne);
		assertNotEquals(oneMinute, sixtyOne);
	}

	@Test
	public void secondsCarryEverythingWhenMinutesAreOff()
	{
		assertEquals("3723", fmt(3_723_456L, false, false, true, SubSecond.NONE));
		assertNotEquals(fmt(3_000L, false, false, true, SubSecond.NONE),
			fmt(63_000L, false, false, true, SubSecond.NONE));
	}

	@Test
	public void everyFieldCombination()
	{
		// One hour, two minutes, three seconds, four hundred and fifty six millis.
		long v = HOUR + 2 * 60_000L + 3_000L + 456L;

		assertEquals("1:02:03", fmt(v, true, true, true, SubSecond.NONE));
		assertEquals("1:02", fmt(v, true, true, false, SubSecond.NONE));
		assertEquals("1:123", fmt(v, true, false, true, SubSecond.NONE));
		assertEquals("1", fmt(v, true, false, false, SubSecond.NONE));
		assertEquals("62:03", fmt(v, false, true, true, SubSecond.NONE));
		assertEquals("62", fmt(v, false, true, false, SubSecond.NONE));
		assertEquals("3723", fmt(v, false, false, true, SubSecond.NONE));
		assertEquals("", fmt(v, false, false, false, SubSecond.NONE));

		assertEquals("1:02:03.4", fmt(v, true, true, true, SubSecond.TENTHS));
		assertEquals("1:02.4", fmt(v, true, true, false, SubSecond.TENTHS));
		assertEquals("1:123.4", fmt(v, true, false, true, SubSecond.TENTHS));
		assertEquals("1.4", fmt(v, true, false, false, SubSecond.TENTHS));
		assertEquals("62:03.4", fmt(v, false, true, true, SubSecond.TENTHS));
		assertEquals("62.4", fmt(v, false, true, false, SubSecond.TENTHS));
		assertEquals("3723.4", fmt(v, false, false, true, SubSecond.TENTHS));
		assertEquals("4", fmt(v, false, false, false, SubSecond.TENTHS));

		assertEquals("1:02:03.45", fmt(v, true, true, true, SubSecond.HUNDREDTHS));
		assertEquals("45", fmt(v, false, false, false, SubSecond.HUNDREDTHS));
	}

	@Test
	public void disabledFieldsAreAbsentNotMasked()
	{
		long v = HOUR + 2 * 60_000L + 3_000L + 456L;

		// Hours off must remove the hours entirely, not blank them out.
		String noHours = fmt(v, false, true, true, SubSecond.HUNDREDTHS);
		assertEquals("62:03.45", noHours);
		assertFalse(noHours.contains("x"));
		assertFalse(noHours.contains("X"));
		assertFalse(noHours.contains("-"));
		assertEquals(1, noHours.chars().filter(c -> c == ':').count());

		// Sub-second off must remove the separator with it.
		String noFraction = fmt(v, true, true, true, SubSecond.NONE);
		assertFalse(noFraction.contains("."));

		// Seconds off must remove the trailing group entirely.
		String noSeconds = fmt(v, true, true, false, SubSecond.NONE);
		assertEquals("1:02", noSeconds);
		assertEquals(1, noSeconds.chars().filter(c -> c == ':').count());
	}

	@Test
	public void negativeValuesCarryASign()
	{
		assertEquals("-0:05.0", fmt(-5000, true, true, true, SubSecond.TENTHS));
		assertEquals("-1:00:00", fmt(-HOUR, true, true, true, SubSecond.NONE));
	}

	@Test
	public void signedDeltas()
	{
		assertEquals("+0:04.2", DurationFormatter.formatSigned(4200, DurationFormat.CLOCK_TENTHS));
		assertEquals("-0:04.2", DurationFormatter.formatSigned(-4200, DurationFormat.CLOCK_TENTHS));
		assertEquals("+0:00.0", DurationFormatter.formatSigned(0, DurationFormat.CLOCK_TENTHS));
	}
}

package com.clockwork.core;

import java.util.function.LongSupplier;

/**
 * A clock the tests drive by hand, so timing behaviour is checked without
 * waiting for real time to pass.
 */
public class FakeClock implements LongSupplier
{
	private long now;

	public FakeClock(long start)
	{
		this.now = start;
	}

	public long advance(long millis)
	{
		now += millis;
		return now;
	}

	public void set(long millis)
	{
		now = millis;
	}

	@Override
	public long getAsLong()
	{
		return now;
	}
}

package com.clockwork.core;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

/**
 * Which clock a hotkey acts on.
 *
 * <p>Two things matter most here.
 *
 * <p>The first is that an explicit choice wins. The rule used to be led by the
 * panel's selection, which is transient, so playing with the sidebar shut the
 * keys could only ever reach the built in clock however many clocks were
 * pinned on screen. A designation is persistent and deliberate, so it beats
 * everything, including a single running clock.
 *
 * <p>The second is the ambiguous case. A stop key that picks the wrong clock
 * out of several running ones ends a run that cannot be got back, so the
 * answer there has to be nothing at all.
 */
public class HotkeyTargetTest
{
	private static final String QUICK = "clockwork-quick";

	private static final List<String> ALL = Arrays.asList(QUICK, "herb", "birds", "wines");

	// The designation, which beats everything

	@Test
	public void theDesignatedClockWinsOverASingleRunningClock()
	{
		assertEquals("wines",
			HotkeyTarget.resolve(Collections.singletonList("herb"), "wines", null, QUICK));
	}

	/**
	 * The reverse of the surprise the old rule had. Designate a clock, leave
	 * the built in one running, and the start key still has to land on the
	 * clock the user picked.
	 */
	@Test
	public void theDesignatedClockWinsWhileQuickIsRunning()
	{
		assertEquals("herb",
			HotkeyTarget.resolve(Collections.singletonList(QUICK), "herb", null, QUICK));
	}

	@Test
	public void theDesignatedClockWinsOverASelection()
	{
		assertEquals("herb", HotkeyTarget.resolve(Collections.emptyList(), "herb", "wines", QUICK));
	}

	@Test
	public void theDesignatedClockWinsOverSeveralRunningClocks()
	{
		assertEquals("wines",
			HotkeyTarget.resolve(Arrays.asList("herb", "birds"), "wines", null, QUICK));
	}

	/**
	 * The designation reaches a clock nobody has started. That is the whole
	 * point of it, since the start key has to have somewhere to land.
	 */
	@Test
	public void theDesignatedClockWinsWithNothingRunningAtAll()
	{
		assertEquals("herb", HotkeyTarget.resolve(Collections.emptyList(), "herb", null, QUICK));
		assertEquals("herb", HotkeyTarget.resolve(null, "herb", null, QUICK));
	}

	@Test
	public void anEmptyDesignationIsNoDesignation()
	{
		assertEquals(QUICK, HotkeyTarget.resolve(Collections.emptyList(), "", null, QUICK));
	}

	// Whether a designation is still real

	@Test
	public void aDesignationOnALiveClockSurvives()
	{
		assertEquals("herb", HotkeyTarget.surviving("herb", ALL));
	}

	/**
	 * A deleted clock, or a config profile that never had it. The stored id
	 * has to stop counting, and the caller unsets it.
	 */
	@Test
	public void aDesignationOnAClockThatIsGoneDoesNot()
	{
		assertNull(HotkeyTarget.surviving("gone", ALL));
		assertNull(HotkeyTarget.surviving("herb", Collections.singletonList(QUICK)));
		assertNull(HotkeyTarget.surviving("herb", Collections.emptyList()));
	}

	@Test
	public void nothingDesignatedSurvivesAsNothing()
	{
		assertNull(HotkeyTarget.surviving(null, ALL));
		assertNull(HotkeyTarget.surviving("", ALL));
		assertNull(HotkeyTarget.surviving("herb", null));
	}

	/**
	 * A stale designation falls through to the next rule rather than stopping
	 * the key from doing anything. Composed the way the plugin composes them.
	 */
	@Test
	public void aStaleDesignationFallsThroughToTheRunningClock()
	{
		final String designated = HotkeyTarget.surviving("deleted", ALL);
		assertNull(designated);
		assertEquals("herb",
			HotkeyTarget.resolve(Collections.singletonList("herb"), designated, null, QUICK));
	}

	// Everything below the designation, unchanged

	@Test
	public void theOneRunningClockWins()
	{
		assertEquals("herb", HotkeyTarget.resolve(Collections.singletonList("herb"), null, null, QUICK));
	}

	@Test
	public void theOneRunningClockWinsEvenOverASelection()
	{
		assertEquals("herb", HotkeyTarget.resolve(Collections.singletonList("herb"), null, "wines", QUICK));
	}

	@Test
	public void withNothingRunningTheSelectionWins()
	{
		assertEquals("wines", HotkeyTarget.resolve(Collections.emptyList(), null, "wines", QUICK));
	}

	@Test
	public void withNothingRunningAndNoSelectionTheQuickClockWins()
	{
		assertEquals(QUICK, HotkeyTarget.resolve(Collections.emptyList(), null, null, QUICK));
		assertEquals(QUICK, HotkeyTarget.resolve(null, null, null, QUICK));
		assertEquals(QUICK, HotkeyTarget.resolve(Collections.emptyList(), null, "", QUICK));
	}

	@Test
	public void severalRunningWithASelectionUsesTheSelection()
	{
		assertEquals("wines", HotkeyTarget.resolve(Arrays.asList("herb", "birds"), null, "wines", QUICK));
	}

	/**
	 * Several clocks running, nothing designated and nothing selected, so
	 * there is no defensible answer and none is given. The quick clock is not
	 * a fallback here, because acting on it would be just as wrong as acting
	 * on one of the running ones.
	 */
	@Test
	public void severalRunningWithNoDesignationAndNoSelectionDoesNothing()
	{
		assertNull(HotkeyTarget.resolve(Arrays.asList("herb", "birds"), null, null, QUICK));
		assertNull(HotkeyTarget.resolve(Arrays.asList("herb", "birds", "wines"), null, null, QUICK));
	}
}

package com.clockwork.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

/**
 * The per-clock override rule, which three settings use and more will.
 *
 * <p>Every combination is here on purpose. The rule is three lines long and
 * exactly the sort of thing that gets quietly inverted by a later edit, and an
 * inverted one shows up as a clock reading the wrong setting rather than as
 * anything that throws.
 */
public class OverridableTest
{
	@Test
	public void useGlobalTakesTheGlobalValue()
	{
		assertEquals(Boolean.TRUE, Overridable.resolve(Toggle.USE_GLOBAL, true));
		assertEquals(Boolean.FALSE, Overridable.resolve(Toggle.USE_GLOBAL, false));
	}

	@Test
	public void onAndOffWinOverEitherGlobal()
	{
		assertEquals(Boolean.TRUE, Overridable.resolve(Toggle.ON, true));
		assertEquals(Boolean.TRUE, Overridable.resolve(Toggle.ON, false));
		assertEquals(Boolean.FALSE, Overridable.resolve(Toggle.OFF, true));
		assertEquals(Boolean.FALSE, Overridable.resolve(Toggle.OFF, false));
	}

	/**
	 * A decode of older or damaged data can leave the setting null, and that
	 * has to read as "use global" rather than throw on the refresh path.
	 */
	@Test
	public void aMissingSettingReadsAsUseGlobal()
	{
		assertEquals(Boolean.FALSE, Overridable.<Boolean>resolve(null, false));
		assertEquals(Boolean.TRUE, Overridable.<Boolean>resolve(null, true));
	}

	/**
	 * The one thing resolve cannot invent. A null global with a deferring
	 * clock has no answer, and the callers all pass a real config value.
	 */
	@Test
	public void aNullGlobalUnderUseGlobalStaysNull()
	{
		assertNull(Overridable.resolve(Toggle.USE_GLOBAL, null));
	}

	@Test
	public void everyMemberCarriesTheValueItsNameClaims()
	{
		assertNull(Toggle.USE_GLOBAL.override());
		assertEquals(Boolean.TRUE, Toggle.ON.override());
		assertEquals(Boolean.FALSE, Toggle.OFF.override());
	}

	/**
	 * The second setting to take this shape, which is what the interface was
	 * written for. The members are checked against the styles they name rather
	 * than assumed, because a member wired to the wrong style would show up as
	 * a clock flashing the screen when it was asked to flash its timer, and
	 * nothing about that throws.
	 */
	@Test
	public void everyAlertMemberCarriesTheStyleItsNameClaims()
	{
		assertNull(AlertOverride.USE_GLOBAL.override());
		assertEquals(AlertStyle.NONE, AlertOverride.NONE.override());
		assertEquals(AlertStyle.TIMER_BOX, AlertOverride.TIMER_BOX.override());
		assertEquals(AlertStyle.SCREEN, AlertOverride.SCREEN.override());
	}

	@Test
	public void anAlertLeftOnUseGlobalTakesWhateverTheConfigSays()
	{
		assertEquals(AlertStyle.SCREEN, Overridable.resolve(AlertOverride.USE_GLOBAL, AlertStyle.SCREEN));
		assertEquals(AlertStyle.NONE, Overridable.resolve(AlertOverride.USE_GLOBAL, AlertStyle.NONE));
		assertEquals(AlertStyle.NONE, Overridable.resolve(AlertOverride.NONE, AlertStyle.TIMER_BOX));
		assertEquals(AlertStyle.TIMER_BOX, Overridable.resolve(AlertOverride.TIMER_BOX, AlertStyle.NONE));
		assertEquals("a clock that asked for a flash took the plugin wide answer instead, so the"
				+ " per clock answer cannot win a flash back once the global draws nothing",
			AlertStyle.SCREEN, Overridable.resolve(AlertOverride.SCREEN, AlertStyle.NONE));
	}
}

package com.clockwork.core;

import java.util.Arrays;
import java.util.Collections;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * What a config profile switch costs.
 *
 * <p>The bug behind this was silent. Clockwork read the clock list once at
 * start up, so after a switch it still held the previous profile's clocks and
 * the next save wrote them over the newly selected profile's. Clocks vanished
 * and nothing said so.
 *
 * <p>The reload itself is plumbing. The part with a decision in it is here,
 * which clocks lose a run when the profile they belong to is left behind.
 */
public class ProfileSwitchTest
{
	@Test
	public void aSwitchWithNothingRunningCostsNothing()
	{
		assertTrue(ProfileSwitch.droppedRuns(Collections.emptyList()).isEmpty());
	}

	/**
	 * A run in progress belongs to the profile being left and cannot be
	 * written there any more, so it is dropped. That is the accepted cost of
	 * the switch, and the point of naming it here is that the plugin can say
	 * so in the log rather than losing it quietly.
	 */
	@Test
	public void everyRunInProgressIsDropped()
	{
		assertEquals(Arrays.asList("herb", "birds"),
			ProfileSwitch.droppedRuns(Arrays.asList("herb", "birds")));
	}

	/**
	 * Including a run on a clock the profile being entered happens to have as
	 * well. The run was timed against the old profile and there is nowhere to
	 * file it.
	 */
	@Test
	public void aRunIsDroppedEvenWhenTheClockExistsInBothProfiles()
	{
		assertEquals(Collections.singletonList("herb"),
			ProfileSwitch.droppedRuns(Collections.singletonList("herb")));
	}

	/**
	 * An id that is null or empty is not a run, so it is not something being
	 * dropped and the plugin has no reason to write a diagnostics line about
	 * it.
	 */
	@Test
	public void anEmptyIdIsNotARun()
	{
		assertEquals(Collections.singletonList("herb"),
			ProfileSwitch.droppedRuns(Arrays.asList(null, "", "herb")));
	}

	@Test
	public void nullsAreTreatedAsNothing()
	{
		assertTrue(ProfileSwitch.droppedRuns(null).isEmpty());
	}
}

package com.clockwork.core;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

/**
 * The built in clock.
 *
 * <p>It is always there, it is always first, and there is never a second one.
 * The last of those is the one worth guarding, since a start up that created
 * one every time would fill a user's panel with identical clocks over a week
 * of playing.
 */
public class QuickClockTest
{
	private static final long T0 = 1_700_000_000_000L;

	private FakeClock clock;
	private RoutineController controller;

	@Before
	public void setUp()
	{
		clock = new FakeClock(T0);
		controller = new RoutineController(clock);
	}

	@Test
	public void itIsCreatedOnFirstUse()
	{
		controller.load(new ArrayList<>(), TriggerLibrary.empty());
		assertTrue(controller.getRoutines().isEmpty());

		Routine quick = controller.ensureQuick();

		assertNotNull(quick);
		assertEquals(Routine.QUICK_ID, quick.getId());
		assertEquals(Routine.QUICK_NAME, quick.getName());
		assertTrue(quick.isBuiltIn());
		assertEquals(1, controller.getRoutines().size());
	}

	@Test
	public void makingItAgainInTheSameSessionChangesNothing()
	{
		Routine first = controller.ensureQuick();
		Routine second = controller.ensureQuick();
		Routine third = controller.ensureQuick();

		assertSame(first, second);
		assertSame(first, third);
		assertEquals(1, controller.getRoutines().size());
	}

	/**
	 * The restart case. What comes back from storage already has the built in
	 * clock in it, so the second start up must adopt that one rather than make
	 * another beside it.
	 */
	@Test
	public void itSurvivesAReloadWithoutBeingDuplicated()
	{
		controller.ensureQuick();
		controller.start(Routine.QUICK_ID);
		clock.advance(4_000);
		controller.stop(Routine.QUICK_ID);

		final List<Routine> saved = new ArrayList<>(controller.getRoutines());

		RoutineController restarted = new RoutineController(clock);
		restarted.load(saved, TriggerLibrary.empty());
		restarted.ensureQuick();
		restarted.ensureQuick();

		assertEquals(1, restarted.getRoutines().size());
		Routine quick = restarted.get(Routine.QUICK_ID);
		assertNotNull(quick);
		assertEquals("its runs come back with it", 1, quick.historyOrEmpty().size());
		assertEquals(4_000, quick.historyOrEmpty().get(0).getDurationMillis());
	}

	@Test
	public void itIsPinnedToTheTopWhateverElseExists()
	{
		Routine herb = controller.create("Herb run");
		Routine wines = controller.create("Wines");

		controller.ensureQuick();

		List<Routine> routines = controller.getRoutines();
		assertEquals(3, routines.size());
		assertEquals(Routine.QUICK_ID, routines.get(0).getId());
		assertEquals("the user's clocks keep their own order underneath it",
			herb.getId(), routines.get(1).getId());
		assertEquals(wines.getId(), routines.get(2).getId());
	}

	@Test
	public void itCannotBeDeleted()
	{
		controller.ensureQuick();
		Routine herb = controller.create("Herb run");

		controller.delete(Routine.QUICK_ID);

		assertNotNull("the built in clock is always there", controller.get(Routine.QUICK_ID));
		assertEquals(2, controller.getRoutines().size());

		controller.delete(herb.getId());
		assertEquals("an ordinary clock still deletes", 1, controller.getRoutines().size());
	}

	@Test
	public void itCannotBeRenamed()
	{
		controller.ensureQuick();

		controller.update(Routine.QUICK_ID, r -> r.setName("Herb run"));

		assertEquals(Routine.QUICK_NAME, controller.get(Routine.QUICK_ID).getName());
	}

	/**
	 * Renaming is the only thing an edit cannot do to it. Everything else is
	 * the user's, because it is an ordinary clock in every other way.
	 */
	@Test
	public void everyOtherSettingOnItIsStillEditable()
	{
		controller.ensureQuick();

		controller.update(Routine.QUICK_ID, r ->
		{
			r.setMode(Mode.COUNT_DOWN);
			r.setTargetMillis(300_000);
			r.setShowDelta(Toggle.OFF);
		});

		Routine quick = controller.get(Routine.QUICK_ID);
		assertSame(Mode.COUNT_DOWN, quick.getMode());
		assertEquals(300_000, quick.getTargetMillis());
		assertSame(Toggle.OFF, quick.getShowDelta());
	}

	/**
	 * A scratch timer is started again because the user wants to time
	 * something else, which is the one case where the ignore that suits a
	 * repeating trigger is wrong.
	 */
	@Test
	public void aSecondStartOnItStartsOver()
	{
		Routine quick = controller.ensureQuick();
		assertTrue(quick.isRestartOnStart());
		assertTrue("splits are on, so a split can be taken on it", quick.isLapsEnabled());

		controller.start(Routine.QUICK_ID);
		clock.advance(9_000);
		controller.start(Routine.QUICK_ID);

		assertEquals(0, controller.elapsedMillis(Routine.QUICK_ID));
		assertFalse("a discarded run records nothing", controller.get(Routine.QUICK_ID).historyOrEmpty().size() > 0);
	}

	@Test
	public void itRecordsRunsAndPersonalBestsLikeAnyOtherClock()
	{
		controller.ensureQuick();

		controller.start(Routine.QUICK_ID);
		clock.advance(30_000);
		controller.stop(Routine.QUICK_ID);

		controller.start(Routine.QUICK_ID);
		clock.advance(20_000);
		controller.stop(Routine.QUICK_ID);

		Routine quick = controller.get(Routine.QUICK_ID);
		assertEquals(2, quick.historyOrEmpty().size());
		assertEquals(20_000, RoutineStats.personalBest(quick).getDurationMillis());
	}

	/**
	 * Counts the rebuild announcements, so a test can say how many arrived
	 * rather than infer it from what the list looks like afterwards.
	 */
	private static final class Fires implements RoutineListener
	{
		private int changed;

		@Override
		public void onRoutinesChanged()
		{
			changed++;
		}
	}

	private static List<String> idsOf(RoutineController from)
	{
		final List<String> ids = new ArrayList<>();
		for (Routine routine : from.getRoutines())
		{
			ids.add(routine.getId());
		}
		return ids;
	}

	/**
	 * The saved order is the drawn order, so a move has to be announced or
	 * both the panel and the saved state sit stale until something unrelated
	 * happens to fire.
	 */
	@Test
	public void movingItBackToTheFrontIsAnnounced()
	{
		final List<Routine> saved = new ArrayList<>();
		saved.add(new Routine("herb", "Herb run"));
		saved.add(new Routine(Routine.QUICK_ID, Routine.QUICK_NAME));
		saved.add(new Routine("wines", "Wines"));
		controller.load(saved, TriggerLibrary.empty());

		final Fires fires = new Fires();
		controller.addListener(fires);

		controller.ensureQuick();

		assertEquals("a move is a change and has to be announced", 1, fires.changed);
		assertEquals(Arrays.asList(Routine.QUICK_ID, "herb", "wines"), idsOf(controller));
	}

	@Test
	public void leavingItWhereItIsAnnouncesNothing()
	{
		controller.ensureQuick();
		controller.create("Herb run");

		final Fires fires = new Fires();
		controller.addListener(fires);
		final List<String> before = idsOf(controller);

		controller.ensureQuick();

		assertEquals("nothing moved, so there was nothing to say", 0, fires.changed);
		assertEquals(before, idsOf(controller));
	}

	@Test
	public void creatingItIsAnnouncedOnce()
	{
		controller.load(new ArrayList<>(), TriggerLibrary.empty());
		final Routine herb = controller.create("Herb run");

		final Fires fires = new Fires();
		controller.addListener(fires);

		controller.ensureQuick();

		assertEquals(1, fires.changed);
		assertEquals("the built in clock arrives pinned to the top",
			Arrays.asList(Routine.QUICK_ID, herb.getId()), idsOf(controller));
	}
}

package com.clockwork.core;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class RoutineControllerTest
{
	private static final long T0 = 1_700_000_000_000L;

	private FakeClock clock;
	private RoutineController controller;

	@Before
	public void setUp()
	{
		clock = new FakeClock(T0);
		controller = new RoutineController(clock);
	}

	private Routine routine(String name)
	{
		return controller.create(name);
	}

	// Timing

	@Test
	public void elapsedFollowsTheClockExactly()
	{
		Routine r = routine("Herb run");
		controller.start(r.getId());

		assertEquals(0, controller.elapsedMillis(r.getId()));
		clock.advance(1);
		assertEquals(1, controller.elapsedMillis(r.getId()));
		clock.advance(999);
		assertEquals(1000, controller.elapsedMillis(r.getId()));
	}

	/**
	 * Drift regression. The clock is advanced in ragged steps that no fixed
	 * per-tick increment could reproduce, and elapsed time has to agree with
	 * the clock at every single step. An implementation that added a constant
	 * per tick would fail on the first uneven jump and never catch up.
	 */
	@Test
	public void elapsedNeverDriftsUnderIrregularAdvances()
	{
		Routine r = routine("Herb run");
		controller.start(r.getId());

		long[] steps = {7, 13, 1, 600, 3, 4_999, 17, 250, 1, 1, 120_000, 33, 8, 3_600_001, 5};
		long expected = 0;
		for (long step : steps)
		{
			clock.advance(step);
			expected += step;
			assertEquals("elapsed must equal the clock delta", expected, controller.elapsedMillis(r.getId()));
		}

		controller.stop(r.getId());
		Run run = r.getHistory().get(0);
		assertEquals(expected, run.getDurationMillis());
		assertEquals(T0, run.getStartedAtEpochMillis());
		assertEquals(T0 + expected, run.getFinishedAtEpochMillis());
	}

	@Test
	public void countdownReachesZeroExactlyThenGoesNegative()
	{
		Routine r = routine("Six minute herbs");
		controller.update(r.getId(), x ->
		{
			x.setMode(Mode.COUNT_DOWN);
			x.setTargetMillis(5_000);

			// Overtime is what this test is about, and stopping at zero is the
			// default now, so it has to be asked for rather than assumed.
			x.setStopAtZero(false);
		});

		controller.start(r.getId());
		assertEquals(Long.valueOf(5_000), controller.remainingMillis(r.getId(), clock.getAsLong()));

		clock.advance(4_999);
		controller.tick(clock.getAsLong());
		assertEquals(Long.valueOf(1), controller.remainingMillis(r.getId(), clock.getAsLong()));
		assertTrue("a countdown that has not reached zero must still be running",
			controller.isRunning(r.getId()));

		clock.advance(1);
		controller.tick(clock.getAsLong());
		assertEquals(Long.valueOf(0), controller.remainingMillis(r.getId(), clock.getAsLong()));
		assertTrue("with the stop at zero toggle off, zero is not the end of the run",
			controller.isRunning(r.getId()));
		assertTrue("nothing may be recorded until the run is stopped", r.getHistory().isEmpty());

		// Overshoot. The run keeps going and reports overtime.
		clock.advance(2_500);
		controller.tick(clock.getAsLong());
		assertEquals(Long.valueOf(-2_500), controller.remainingMillis(r.getId(), clock.getAsLong()));
		assertEquals(7_500, controller.elapsedMillis(r.getId()));
		assertTrue("overtime must not end the run", controller.isRunning(r.getId()));
		assertTrue(r.getHistory().isEmpty());
	}

	@Test
	public void loggedInOnlyClockPausesWhileOutOfTheGame()
	{
		Routine r = routine("Logged in run");
		controller.update(r.getId(), x ->
		{
			x.setClock(ClockMode.LOGGED_IN_ONLY);
			x.setMode(Mode.COUNT_DOWN);
			x.setTargetMillis(10_000);
		});

		controller.start(r.getId());
		clock.advance(3_000);
		assertEquals(3_000, controller.elapsedMillis(r.getId()));

		controller.setLoggedIn(false);
		clock.advance(60_000);
		assertEquals("logged out time must not count", 3_000, controller.elapsedMillis(r.getId()));
		assertEquals(Long.valueOf(7_000), controller.remainingMillis(r.getId(), clock.getAsLong()));

		controller.setLoggedIn(true);
		clock.advance(2_000);
		assertEquals(5_000, controller.elapsedMillis(r.getId()));
		assertEquals(Long.valueOf(5_000), controller.remainingMillis(r.getId(), clock.getAsLong()));

		controller.stop(r.getId());
		assertEquals(5_000, r.getHistory().get(0).getDurationMillis());
	}

	@Test
	public void wallClockRoutineIgnoresLogout()
	{
		Routine r = routine("Wall clock run");
		controller.start(r.getId());
		controller.setLoggedIn(false);
		clock.advance(45_000);
		assertEquals(45_000, controller.elapsedMillis(r.getId()));
	}

	// Arm semantics

	@Test
	public void startOnARunningRoutineIsIgnoredByDefault()
	{
		Routine r = routine("Herb run");
		final int[] starts = {0};
		controller.addListener(new RoutineListener()
		{
			@Override
			public void onRunStarted(Routine routine)
			{
				starts[0]++;
			}
		});

		controller.start(r.getId());
		clock.advance(4_000);
		controller.start(r.getId());
		controller.start(r.getId());

		assertEquals("the extra starts must not restart the clock", 4_000, controller.elapsedMillis(r.getId()));
		assertEquals(1, starts[0]);
	}

	@Test
	public void restartOnStartDiscardsTheRunInProgress()
	{
		Routine r = routine("Herb run");
		controller.update(r.getId(), x -> x.setRestartOnStart(true));

		final int[] starts = {0};
		final int[] cancels = {0};
		controller.addListener(new RoutineListener()
		{
			@Override
			public void onRunStarted(Routine routine)
			{
				starts[0]++;
			}

			@Override
			public void onRunCancelled(Routine routine)
			{
				cancels[0]++;
			}
		});

		controller.start(r.getId());
		clock.advance(4_000);
		controller.start(r.getId());

		assertEquals(0, controller.elapsedMillis(r.getId()));
		assertEquals(2, starts[0]);
		assertEquals(1, cancels[0]);
		assertTrue("a restart records nothing", r.getHistory().isEmpty());
	}

	// Laps

	@Test
	public void lapMath()
	{
		Routine r = routine("Herb run");
		controller.update(r.getId(), x -> x.setLapsEnabled(true));
		controller.start(r.getId());

		clock.advance(1_000);
		controller.lap(r.getId(), "Ardougne");
		clock.advance(2_500);
		controller.lap(r.getId(), "Catherby");
		clock.advance(500);
		controller.stop(r.getId());

		List<Lap> laps = r.getHistory().get(0).getLaps();
		assertEquals(3, laps.size());

		assertEquals("Ardougne", laps.get(0).getLabel());
		assertEquals(1_000, laps.get(0).getSplitMillis());
		assertEquals("the first lap's split and lap time are the same", 1_000, laps.get(0).getLapMillis());

		assertEquals("Catherby", laps.get(1).getLabel());
		assertEquals(3_500, laps.get(1).getSplitMillis());
		assertEquals(2_500, laps.get(1).getLapMillis());

		// Stopping closes the segment the user was in.
		assertNull(laps.get(2).getLabel());
		assertEquals(4_000, laps.get(2).getSplitMillis());
		assertEquals(500, laps.get(2).getLapMillis());
		assertEquals(4_000, r.getHistory().get(0).getDurationMillis());
	}

	@Test
	public void lapsAreIgnoredWhenTheRoutineDoesNotUseThem()
	{
		Routine r = routine("Plain stopwatch");
		controller.start(r.getId());
		clock.advance(1_000);
		controller.lap(r.getId());
		clock.advance(1_000);
		controller.stop(r.getId());

		assertTrue(r.getHistory().get(0).getLaps().isEmpty());
	}

	// Lifecycle

	@Test
	public void cancelRecordsNothing()
	{
		Routine r = routine("Herb run");
		controller.start(r.getId());
		clock.advance(9_000);
		controller.cancel(r.getId());

		assertFalse(controller.isRunning(r.getId()));
		assertTrue(r.getHistory().isEmpty());
	}

	@Test
	public void resetDropsTheRunAndTheHistory()
	{
		Routine r = routine("Herb run");
		controller.start(r.getId());
		clock.advance(1_000);
		controller.stop(r.getId());
		controller.start(r.getId());

		controller.reset(r.getId());

		assertFalse(controller.isRunning(r.getId()));
		assertTrue(r.getHistory().isEmpty());
		assertNull(RoutineStats.personalBest(r));
	}

	@Test
	public void stopOnARoutineThatIsNotRunningDoesNothing()
	{
		Routine r = routine("Herb run");
		controller.stop(r.getId());
		controller.lap(r.getId());
		controller.cancel(r.getId());
		assertTrue(r.getHistory().isEmpty());
	}

	// Auto-abandon

	@Test
	public void runsPastTheThresholdAreAbandonedAndIgnoredByStats()
	{
		Routine r = routine("Herb run");
		controller.update(r.getId(), x -> x.setAbandonAfterMillis(10_000L));

		// A good run first, so there is a personal best to protect.
		controller.start(r.getId());
		clock.advance(4_000);
		controller.stop(r.getId());

		// Then one that runs away.
		controller.start(r.getId());
		clock.advance(9_999);
		controller.tick(clock.getAsLong());
		assertTrue("still inside the threshold", controller.isRunning(r.getId()));

		clock.advance(1);
		controller.tick(clock.getAsLong());

		assertFalse(controller.isRunning(r.getId()));
		assertEquals(2, r.getHistory().size());

		Run abandoned = r.getHistory().get(1);
		assertEquals(Status.ABANDONED, abandoned.getStatus());
		assertEquals(10_000, abandoned.getDurationMillis());

		assertEquals(4_000, RoutineStats.personalBest(r).getDurationMillis());
		assertEquals(Long.valueOf(4_000), RoutineStats.averageOfLast(r, 10));
		assertEquals(4_000, RoutineStats.lastCompleted(r).getDurationMillis());
	}

	@Test
	public void abandonThresholdDoesNotCountLoggedOutTime()
	{
		Routine r = routine("Herb run");
		controller.update(r.getId(), x ->
		{
			x.setClock(ClockMode.LOGGED_IN_ONLY);
			x.setAbandonAfterMillis(10_000L);
		});

		controller.start(r.getId());
		clock.advance(5_000);
		controller.setLoggedIn(false);
		clock.advance(600_000);
		controller.tick(clock.getAsLong());

		assertTrue("an overnight logout must not abandon a paused run", controller.isRunning(r.getId()));
	}

	// History cap

	/**
	 * A user getting steadily slower, which is the case the old flat cap got
	 * wrong. Fifty five runs, each one slower than the last, so the best runs
	 * this clock will ever see are the oldest ones in it.
	 *
	 * <p>Under the newest fifty rule the first five fell off the front and the
	 * record went with them, silently, and the Best line then meant best of
	 * what is left. Here the fastest are chosen before anything is dropped, so
	 * run one is still there and still holds the record.
	 */
	@Test
	public void theFastestRunsSurviveEvenWhenTheyAreTheOldest()
	{
		Routine r = routine("Herb run");
		int total = 55;

		for (int i = 1; i <= total; i++)
		{
			controller.start(r.getId());
			clock.advance(i * 1_000L);
			controller.stop(r.getId());
			clock.advance(10);
		}

		assertEquals("the newest ten and the fastest ten, and here they do not overlap at all",
			RunHistory.MAX_KEPT, r.getHistory().size());
		assertEquals("the very first run was the fastest one and it is still stored",
			1_000, r.getHistory().get(0).getDurationMillis());
		assertEquals("and it is what the personal best reads",
			1_000, RoutineStats.personalBest(r).getDurationMillis());
		assertEquals(total * 1_000L, r.getHistory().get(r.getHistory().size() - 1).getDurationMillis());

		// The fastest ten are runs one through ten and the newest ten are runs
		// forty six through fifty five, with nothing in between.
		assertEquals(10_000, r.getHistory().get(9).getDurationMillis());
		assertEquals(46_000, r.getHistory().get(10).getDurationMillis());
	}

	/**
	 * The mirror image, a user getting steadily quicker, where the newest runs
	 * are also the fastest. The two sets are then the same ten runs and the
	 * clock keeps ten rather than twenty, because a run that qualifies on both
	 * counts is stored once.
	 */
	@Test
	public void theTwoSetsOverlapWhenTheNewestRunsAreAlsoTheFastest()
	{
		Routine r = routine("Herb run");

		for (int i = 55; i >= 1; i--)
		{
			controller.start(r.getId());
			clock.advance(i * 1_000L);
			controller.stop(r.getId());
			clock.advance(10);
		}

		assertEquals("the newest ten are the fastest ten, so there are ten distinct runs",
			RunHistory.RECENT_KEPT, r.getHistory().size());
		assertEquals(10_000, r.getHistory().get(0).getDurationMillis());
		assertEquals(1_000, r.getHistory().get(9).getDurationMillis());
	}

	@Test
	public void loadRepairsIdsAndTrimsOversizedHistory()
	{
		Routine broken = new Routine();
		broken.setName("Imported");
		broken.setHistory(new ArrayList<>());
		for (int i = 0; i < 60; i++)
		{
			broken.getHistory().add(new Run(0, i, i, new ArrayList<>(), Status.COMPLETED));
		}

		List<Routine> loaded = new ArrayList<>();
		loaded.add(broken);
		loaded.add(null);
		controller.load(loaded, TriggerLibrary.empty());

		assertEquals(1, controller.getRoutines().size());
		Routine kept = controller.getRoutines().get(0);
		assertNotNull(kept.getId());
		assertEquals(RunHistory.MAX_KEPT, kept.getHistory().size());
	}

	// Lifetime totals

	/**
	 * Every completed run is counted, including the ones the trim goes on to
	 * drop, because the lifetime figure is about what the user did rather than
	 * about what there was room to keep.
	 */
	@Test
	public void everyCompletedRunIsCountedEvenTheOnesTheTrimDrops()
	{
		Routine r = routine("Herb run");

		for (int i = 1; i <= 40; i++)
		{
			controller.start(r.getId());
			clock.advance(60_000);
			controller.stop(r.getId());
			clock.advance(10);
		}

		assertEquals("forty runs happened and twenty are stored", 40, r.getTotals().getCompletedRuns());
		assertEquals(RunHistory.MAX_KEPT, r.getHistory().size());
		assertEquals(Long.valueOf(60_000), RoutineStats.allTimeAverage(r));
	}

	/**
	 * An abandoned run never reaches the lifetime figure, on the same rule that
	 * keeps it out of every other statistic.
	 */
	@Test
	public void anAbandonedRunIsNotCounted()
	{
		Routine r = routine("Herb run");
		controller.update(r.getId(), x -> x.setAbandonAfterMillis(10_000L));

		controller.start(r.getId());
		clock.advance(4_000);
		controller.stop(r.getId());

		controller.start(r.getId());
		clock.advance(10_000);
		controller.tick(clock.getAsLong());

		assertEquals(2, r.getHistory().size());
		assertEquals("the run that ran away is in the history and not in the count",
			1, r.getTotals().getCompletedRuns());
		assertEquals(Long.valueOf(4_000), RoutineStats.allTimeAverage(r));
	}

	/**
	 * Clearing one clock takes its lifetime figure with it. A clock that kept
	 * its all time average would be answering from runs the user has just
	 * thrown away, and there would be no way to get back to the runs to check.
	 */
	@Test
	public void resettingAClockClearsWhatItHadCounted()
	{
		Routine r = routine("Herb run");
		controller.start(r.getId());
		clock.advance(4_000);
		controller.stop(r.getId());
		assertEquals(1, r.getTotals().getCompletedRuns());

		controller.reset(r.getId());

		assertTrue(r.getHistory().isEmpty());
		assertTrue("personal bests go and so does the lifetime count", r.getTotals().isEmpty());
		assertNull(RoutineStats.allTimeAverage(r));
	}

	@Test
	public void clearingEveryClockClearsWhatTheyHadCounted()
	{
		Routine one = routine("Herb run");
		Routine two = routine("Tree run");
		for (Routine each : new Routine[]{one, two})
		{
			controller.start(each.getId());
			clock.advance(4_000);
			controller.stop(each.getId());
		}

		controller.clearAllHistory();

		assertTrue(one.getTotals().isEmpty());
		assertTrue(two.getTotals().isEmpty());
	}

	/**
	 * What a user upgrading goes through, end to end through the controller.
	 *
	 * <p>Fifty stored runs arrive with no lifetime totals against them, which
	 * is what every existing user looks like on the first start of a build that
	 * has them. The count is taken from all fifty, before the trim, and the
	 * record set months ago and sitting deep in the middle of the list is one
	 * of the runs that survives.
	 *
	 * <p>Fifty is also the honest ceiling. A user who has really run this clock
	 * two hundred times had fifty stored, because that was the cap, so fifty is
	 * what there is to count and fifty is what they are credited with.
	 */
	@Test
	public void anExistingUsersStoredRunsAreCountedBeforeAnyAreDropped()
	{
		Routine arriving = new Routine("herb-id", "Herb run");
		for (int i = 0; i < 50; i++)
		{
			arriving.getHistory().add(new Run(i, i + 600_000L, 600_000L, new ArrayList<>(), Status.COMPLETED));
		}
		final Run recordFromMonthsAgo =
			new Run(999, 999 + 421_000L, 421_000L, new ArrayList<>(), Status.COMPLETED);
		arriving.getHistory().set(3, recordFromMonthsAgo);

		controller.load(Collections.singletonList(arriving), TriggerLibrary.empty());
		Routine loaded = controller.get("herb-id");

		assertEquals("counted from all fifty stored runs, not from what survived the trim",
			50, loaded.getTotals().getCompletedRuns());
		assertEquals(RunHistory.MAX_KEPT, loaded.getHistory().size());
		assertTrue("a record set long ago is the whole reason this rule changed",
			loaded.getHistory().contains(recordFromMonthsAgo));
		assertSame(recordFromMonthsAgo, RoutineStats.personalBest(loaded));
	}

	/**
	 * The seed happens once. A clock that already has a lifetime count keeps
	 * it, or every restart would add the surviving runs on top of a figure that
	 * already included them.
	 */
	@Test
	public void aClockThatAlreadyHasACountIsNotCountedAgain()
	{
		Routine arriving = new Routine("herb-id", "Herb run");
		arriving.setTotals(new Totals(200, 200L * 600_000L));
		for (int i = 0; i < 12; i++)
		{
			arriving.getHistory().add(new Run(i, i + 600_000L, 600_000L, new ArrayList<>(), Status.COMPLETED));
		}

		controller.load(Collections.singletonList(arriving), TriggerLibrary.empty());

		assertEquals(200, controller.get("herb-id").getTotals().getCompletedRuns());
		assertEquals(200L * 600_000L, controller.get("herb-id").getTotals().getCompletedMillis());
	}

	/**
	 * The profile this repair was written from, with the author's own numbers.
	 *
	 * <p>Their card read "Average 16:00 over 8" beside "All time 16:01 over 7".
	 * The lifetime count was under the number of completed runs sitting in the
	 * clock's own history, which cannot be true of anything, and it happened
	 * because the totals were counted first and a run was recovered onto the
	 * history afterwards by the move off the one key every clock used to share.
	 * The seed only ever fired for a clock that had counted nothing, so nothing
	 * ever went back for the recovered run.
	 *
	 * <p>The eight stored runs here are seven of 16:01 and one of 15:53, which
	 * is 16:00 on average, and the totals are the seven of 16:01 alone. That is
	 * the screen exactly, and it is internally consistent, since the run the
	 * totals never counted is the one the merge brought back.
	 */
	@Test
	public void aLifetimeCountUnderTheStoredRunsIsRaisedToMeetThem()
	{
		final Routine arriving = new Routine("herb-id", "Herb run");
		for (int i = 0; i < 7; i++)
		{
			arriving.getHistory().add(
				new Run(i, i + 961_000L, 961_000L, new ArrayList<>(), Status.COMPLETED));
		}
		arriving.getHistory().add(new Run(7, 7 + 953_000L, 953_000L, new ArrayList<>(), Status.COMPLETED));
		arriving.setTotals(new Totals(7, 7L * 961_000L));

		controller.load(Collections.singletonList(arriving), TriggerLibrary.empty());
		final Routine loaded = controller.get("herb-id");

		assertEquals("the lifetime count is still under the runs the clock is holding, which is the"
				+ " thing that cannot be true",
			8, loaded.getTotals().getCompletedRuns());
		assertEquals("the count moved and the sum did not, so the all time average is now a real"
				+ " sum divided by a count that does not belong to it",
			7_680_000L, loaded.getTotals().getCompletedMillis());

		// What the card reads afterwards, in the words it reads them in.
		assertEquals("All time 16:00 over 8", "All time "
			+ DurationFormatter.format(RoutineStats.allTimeAverage(loaded), DurationFormat.CLOCK)
			+ " over " + RoutineStats.completedAllTime(loaded));
		assertEquals("and the line above it, which is what disagreed", "Average 16:00 over 8",
			"Average " + DurationFormatter.format(
				RoutineStats.averageOfLast(loaded, RunHistory.RECENT_KEPT), DurationFormat.CLOCK)
			+ " over " + RoutineStats.completedInLast(loaded, RunHistory.RECENT_KEPT));
	}

	/**
	 * The direction the repair may never go. A clock with two hundred runs
	 * behind it and twenty stored is the ordinary shape rather than a fault,
	 * because the runs are capped and the totals are not, and recounting it
	 * from the twenty would destroy a hundred and eighty runs the user really
	 * did with no backup to get them back from.
	 */
	@Test
	public void aLifetimeCountAboveTheStoredRunsIsNeverBroughtDown()
	{
		final Routine arriving = new Routine("herb-id", "Herb run");
		for (int i = 0; i < 20; i++)
		{
			arriving.getHistory().add(
				new Run(i, i + 60_000L, 60_000L, new ArrayList<>(), Status.COMPLETED));
		}
		arriving.setTotals(new Totals(200, 200L * 600_000L));

		controller.load(Collections.singletonList(arriving), TriggerLibrary.empty());
		final Routine loaded = controller.get("herb-id");

		assertEquals(200, loaded.getTotals().getCompletedRuns());
		assertEquals("the sum was recounted from the stored runs, so a hundred and eighty runs the"
				+ " user did are gone and there is nowhere to read them back from",
			200L * 600_000L, loaded.getTotals().getCompletedMillis());
	}

	/**
	 * Each figure is held to its own floor, because each is evidence on its
	 * own. A clock short on the count whose sum already covers the runs it is
	 * short of keeps that sum, which is what a counted run that has since aged
	 * out of the history looks like, and a wholesale recount would have thrown
	 * it away.
	 */
	@Test
	public void theSumIsNotDraggedDownByARaisedCount()
	{
		final Routine arriving = new Routine("herb-id", "Herb run");
		for (int i = 0; i < 3; i++)
		{
			arriving.getHistory().add(
				new Run(i, i + 60_000L, 60_000L, new ArrayList<>(), Status.COMPLETED));
		}
		arriving.setTotals(new Totals(2, 3_600_000L));

		controller.load(Collections.singletonList(arriving), TriggerLibrary.empty());
		final Routine loaded = controller.get("herb-id");

		assertEquals(3, loaded.getTotals().getCompletedRuns());
		assertEquals("a sum well above what the stored runs account for was replaced by them",
			3_600_000L, loaded.getTotals().getCompletedMillis());
	}

	/**
	 * An abandoned run sets no floor, on the same rule that keeps it out of
	 * every other statistic. A clock with two completed runs and eight
	 * abandoned ones is not owed a lifetime count of ten.
	 */
	@Test
	public void anAbandonedRunDoesNotRaiseTheLifetimeCount()
	{
		final Routine arriving = new Routine("herb-id", "Herb run");
		arriving.getHistory().add(new Run(0, 60_000L, 60_000L, new ArrayList<>(), Status.COMPLETED));
		for (int i = 1; i < 9; i++)
		{
			arriving.getHistory().add(
				new Run(i, i + 900_000L, 900_000L, new ArrayList<>(), Status.ABANDONED));
		}
		arriving.setTotals(new Totals(1, 60_000L));

		controller.load(Collections.singletonList(arriving), TriggerLibrary.empty());
		final Routine loaded = controller.get("herb-id");

		assertEquals(1, loaded.getTotals().getCompletedRuns());
		assertEquals(60_000L, loaded.getTotals().getCompletedMillis());
	}

	/**
	 * The repair runs on every load, so it has to be idempotent, and it is
	 * idempotent by construction rather than by a guard. A floor that is
	 * already met moves nothing however many times it is asked.
	 */
	@Test
	public void aSecondLoadOfTheSameClockChangesNothing()
	{
		final Routine arriving = new Routine("herb-id", "Herb run");
		for (int i = 0; i < 8; i++)
		{
			arriving.getHistory().add(
				new Run(i, i + 961_000L, 961_000L, new ArrayList<>(), Status.COMPLETED));
		}
		arriving.setTotals(new Totals(7, 7L * 961_000L));

		controller.load(Collections.singletonList(arriving), TriggerLibrary.empty());
		final Totals afterOne = new Totals(controller.get("herb-id").getTotals().getCompletedRuns(),
			controller.get("herb-id").getTotals().getCompletedMillis());

		controller.load(Collections.singletonList(controller.get("herb-id")), TriggerLibrary.empty());

		assertEquals("a restart added the surviving runs on top of a count that already had them",
			afterOne, controller.get("herb-id").getTotals());
	}

	/**
	 * A clock whose runs the user cleared stays cleared. There are no runs to
	 * count, so the seed finds nothing and does not resurrect anything.
	 */
	@Test
	public void aClearedClockIsNotSeededBackToLife()
	{
		Routine arriving = new Routine("herb-id", "Herb run");

		controller.load(Collections.singletonList(arriving), TriggerLibrary.empty());

		assertTrue(controller.get("herb-id").getTotals().isEmpty());
		assertNull(RoutineStats.allTimeAverage(controller.get("herb-id")));
	}

	@Test
	public void deleteRemovesTheRoutineAndItsRun()
	{
		Routine r = routine("Herb run");
		controller.start(r.getId());
		controller.delete(r.getId());

		assertTrue(controller.getRoutines().isEmpty());
		assertFalse(controller.isRunning(r.getId()));
	}

	/**
	 * The rename cascade, driven through the controller, which is the only
	 * place that holds both the library and the clocks.
	 */
	@Test
	public void editingATriggersNameFollowsThroughOntoEveryClock()
	{
		controller.editLibrary(library -> library.add("Note herbs", "Use", "Tool Leprechaun"));

		Routine herb = routine("Herb run");
		controller.update(herb.getId(), r -> r.setStartTrigger(Trigger.saved("Note herbs")));

		Routine flax = routine("Flax run");
		controller.update(flax.getId(), r -> r.setStopTrigger(Trigger.saved("Note herbs")));

		assertNotNull(controller.editTrigger("Note herbs", "Leprechaun", "Use", "Tool Leprechaun"));

		assertEquals(Trigger.saved("Leprechaun"), controller.get(herb.getId()).getStartTrigger());
		assertEquals(Trigger.saved("Leprechaun"), controller.get(flax.getId()).getStopTrigger());
		assertTrue("and both still fire on the click they always fired on",
			controller.getLibrary().matches(controller.get(herb.getId()).getStartTrigger(),
				TriggerEvent.menuClick("Use", "Tool Leprechaun")));

		assertNull("editing something that is not there changes nothing",
			controller.editTrigger("gone", "Whatever", "Use", "Thing"));
	}

	// Arriving from outside

	/**
	 * What an import applies. Adding somebody else's clocks must not throw away
	 * the run the user is timing right now, which is the one thing
	 * {@link RoutineController#load} would do.
	 */
	@Test
	public void addAllAddsWithoutDisturbingWhatIsAlreadyThere()
	{
		Routine mine = routine("Herb run");
		controller.start(mine.getId());

		Routine incoming = new Routine();
		incoming.setName("Birdhouse run");

		TriggerLibrary library = TriggerLibrary.empty();
		library.add("Note herbs", "Use", "Tool Leprechaun");

		controller.addAll(Arrays.asList(incoming, null), library);

		assertEquals(2, controller.getRoutines().size());
		assertTrue("the run in progress survived", controller.isRunning(mine.getId()));
		assertNotNull("a clock with no id gets one", incoming.getId());
		assertNotNull(controller.get(incoming.getId()));
		assertEquals(1, controller.getLibrary().all().size());
	}

	@Test
	public void addAllWithNothingToAddIsNotAnError()
	{
		Routine mine = routine("Herb run");

		controller.addAll(null, null);

		assertEquals(1, controller.getRoutines().size());
		assertEquals("Herb run", controller.get(mine.getId()).getName());
	}

	/**
	 * What it takes for a plain object to become a live clock, on the load
	 * path.
	 *
	 * <p>There are two ways clocks arrive from outside and the terms are the
	 * same either way, so the same damaged pair is put through each of them and
	 * held to the same outcome. Written twice inside the controller, this was a
	 * rule that could be changed on one path and not the other with nothing to
	 * notice, which is exactly what these two tests are for.
	 */
	@Test
	public void loadAppliesTheTermsOfArrival()
	{
		Routine noId = withNoId();
		Routine overFull = withTooMuchHistory();

		controller.load(Arrays.asList(noId, null, overFull), TriggerLibrary.empty());

		assertArrived(noId, overFull);
	}

	/**
	 * And on the add path, which an import uses. Same rule, same outcome.
	 */
	@Test
	public void addAllAppliesTheSameTermsOfArrival()
	{
		Routine noId = withNoId();
		Routine overFull = withTooMuchHistory();

		controller.addAll(Arrays.asList(noId, null, overFull), null);

		assertArrived(noId, overFull);
	}

	/**
	 * A clock as a document that left its ids out hands it over, with a null
	 * history on top of that. The id is empty rather than null because both
	 * have always counted as no id, and only one of them is obvious.
	 */
	private static Routine withNoId()
	{
		Routine routine = new Routine();
		routine.setName("Imported");
		routine.setId("");
		routine.setHistory(null);
		return routine;
	}

	/**
	 * A clock carrying more runs than one is allowed to keep, which a hand
	 * edited or an older store can produce.
	 */
	private static Routine withTooMuchHistory()
	{
		Routine routine = new Routine("full", "Wine run");
		for (int i = 0; i < 60; i++)
		{
			routine.getHistory().add(new Run(0, i, i, new ArrayList<>(), Status.COMPLETED));
		}
		return routine;
	}

	private void assertArrived(Routine noId, Routine overFull)
	{
		assertEquals("the null in the list was dropped rather than kept or thrown",
			2, controller.getRoutines().size());

		assertNotNull("an empty id is no id, so one is minted", noId.getId());
		assertFalse(noId.getId().isEmpty());
		assertSame("and the clock is reachable by it", noId, controller.get(noId.getId()));
		assertNotNull("a null history becomes an empty one, so nothing downstream checks",
			noId.getHistory());
		assertTrue(noId.getHistory().isEmpty());

		assertEquals("an over long history is trimmed on the way in, not on the way out",
			RunHistory.MAX_KEPT, overFull.getHistory().size());
		assertSame("an id that was already there is kept", overFull, controller.get("full"));
	}
}

package com.clockwork.core;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class RoutineStatsTest
{
	private Routine routine;

	@Before
	public void setUp()
	{
		routine = new Routine("id", "Herb run");
	}

	private void addRun(long duration, Status status)
	{
		routine.getHistory().add(new Run(0, duration, duration, new ArrayList<>(), status));
	}

	private static Lap lap(long split, long delta)
	{
		return new Lap(null, split, delta);
	}

	@Test
	public void emptyHistoryHasNoStats()
	{
		assertNull(RoutineStats.personalBest(routine));
		assertNull(RoutineStats.lastCompleted(routine));
		assertNull(RoutineStats.averageOfLast(routine, 10));
		assertTrue(RoutineStats.completed(routine).isEmpty());
	}

	@Test
	public void personalBestIsTheFastestCompletedRun()
	{
		addRun(9_000, Status.COMPLETED);
		addRun(6_000, Status.COMPLETED);
		addRun(7_500, Status.COMPLETED);

		assertEquals(6_000, RoutineStats.personalBest(routine).getDurationMillis());
		assertEquals(7_500, RoutineStats.lastCompleted(routine).getDurationMillis());
	}

	@Test
	public void abandonedRunsAreExcludedFromEveryStat()
	{
		addRun(9_000, Status.COMPLETED);
		addRun(1_000, Status.ABANDONED);
		addRun(7_000, Status.COMPLETED);
		addRun(999_000, Status.ABANDONED);

		assertEquals("an abandoned run must never take the record",
			7_000, RoutineStats.personalBest(routine).getDurationMillis());
		assertEquals("the last stat means the last completed run",
			7_000, RoutineStats.lastCompleted(routine).getDurationMillis());
		assertEquals(Long.valueOf(8_000), RoutineStats.averageOfLast(routine, 10));
		assertEquals(2, RoutineStats.completed(routine).size());
	}

	@Test
	public void averageUsesOnlyTheLastWindowOfRuns()
	{
		addRun(10_000, Status.COMPLETED);
		addRun(20_000, Status.COMPLETED);
		addRun(30_000, Status.COMPLETED);
		addRun(40_000, Status.COMPLETED);

		assertEquals(Long.valueOf(35_000), RoutineStats.averageOfLast(routine, 2));
		assertEquals(Long.valueOf(30_000), RoutineStats.averageOfLast(routine, 3));
		assertEquals(Long.valueOf(25_000), RoutineStats.averageOfLast(routine, 4));
	}

	@Test
	public void averageWithFewerRunsThanTheWindowAveragesWhatIsThere()
	{
		addRun(10_000, Status.COMPLETED);
		addRun(20_000, Status.COMPLETED);

		assertEquals(Long.valueOf(15_000), RoutineStats.averageOfLast(routine, 10));
		assertNull(RoutineStats.averageOfLast(routine, 0));
	}

	@Test
	public void liveDeltaWithoutAPersonalBestIsNull()
	{
		assertNull(RoutineStats.liveDelta(routine, 5_000, Collections.emptyList()));
	}

	@Test
	public void liveDeltaWithoutLapsTracksTheBestTotal()
	{
		addRun(10_000, Status.COMPLETED);

		assertEquals(Long.valueOf(-6_000), RoutineStats.liveDelta(routine, 4_000, Collections.emptyList()));
		assertEquals(Long.valueOf(0), RoutineStats.liveDelta(routine, 10_000, Collections.emptyList()));
		assertEquals(Long.valueOf(2_000), RoutineStats.liveDelta(routine, 12_000, Collections.emptyList()));
	}

	@Test
	public void liveDeltaComparesAgainstTheBestRunSplits()
	{
		routine.setLapsEnabled(true);
		List<Lap> bestLaps = Arrays.asList(lap(3_000, 3_000), lap(7_000, 4_000), lap(10_000, 3_000));
		routine.getHistory().add(new Run(0, 10_000, 10_000, bestLaps, Status.COMPLETED));
		// A slower run that must not become the reference.
		routine.getHistory().add(new Run(0, 20_000, 20_000,
			Arrays.asList(lap(9_000, 9_000), lap(15_000, 6_000), lap(20_000, 5_000)), Status.COMPLETED));

		// Before the first split, the delta tracks the best run's first split.
		assertEquals(Long.valueOf(-1_000), RoutineStats.liveDelta(routine, 2_000, Collections.emptyList()));
		assertEquals(Long.valueOf(500), RoutineStats.liveDelta(routine, 3_500, Collections.emptyList()));

		// One split taken, two hundred millis ahead of the record. The delta
		// holds that value while the run is still inside the next segment.
		List<Lap> mine = new ArrayList<>();
		mine.add(lap(2_800, 2_800));
		assertEquals(Long.valueOf(-200), RoutineStats.liveDelta(routine, 4_000, mine));
		assertEquals(Long.valueOf(-200), RoutineStats.liveDelta(routine, 6_999, mine));

		// Past the record's second split, the delta goes live again.
		assertEquals(Long.valueOf(500), RoutineStats.liveDelta(routine, 7_500, mine));

		// After the last recorded split the comparison falls back to the total.
		mine.add(lap(6_500, 3_700));
		mine.add(lap(9_500, 3_000));
		assertEquals(Long.valueOf(-500), RoutineStats.liveDelta(routine, 9_500, mine));
	}

	@Test
	public void liveDeltaIgnoresSplitsWhenTheRoutineHasLapsOff()
	{
		routine.setLapsEnabled(false);
		routine.getHistory().add(new Run(0, 10_000, 10_000,
			Arrays.asList(lap(3_000, 3_000), lap(10_000, 7_000)), Status.COMPLETED));

		assertEquals(Long.valueOf(-6_000), RoutineStats.liveDelta(routine, 4_000, Collections.emptyList()));
	}

	/**
	 * The memo, checked for the failure it could have. Statistics are derived
	 * once per routine and kept until the history they came from changes, so
	 * the thing that could go wrong is an answer that outlives the runs behind
	 * it. Every test below reads first, so there is something remembered to be
	 * wrong, and then reads again after a change.
	 */
	@Test
	public void clearingTheHistoryChangesThePersonalBest()
	{
		addRun(9_000, Status.COMPLETED);
		addRun(6_000, Status.COMPLETED);

		assertEquals("the setup did not produce a personal best, so the rest of this proves nothing",
			6_000, RoutineStats.personalBest(routine).getDurationMillis());
		assertEquals(2, RoutineStats.completed(routine).size());

		routine.getHistory().clear();

		assertNull("the personal best survived the history being cleared, which means it was answered"
			+ " from something remembered rather than from the runs", RoutineStats.personalBest(routine));
		assertNull(RoutineStats.lastCompleted(routine));
		assertTrue(RoutineStats.completed(routine).isEmpty());
		assertNull(RoutineStats.averageOfLast(routine, 10));
	}

	@Test
	public void aFasterRunReplacesTheRememberedPersonalBest()
	{
		addRun(9_000, Status.COMPLETED);
		assertEquals(9_000, RoutineStats.personalBest(routine).getDurationMillis());

		addRun(4_000, Status.COMPLETED);

		assertEquals("a faster run was recorded and the personal best did not move",
			4_000, RoutineStats.personalBest(routine).getDurationMillis());
		assertEquals(4_000, RoutineStats.lastCompleted(routine).getDurationMillis());
	}

	@Test
	public void replacingTheWholeHistoryListChangesTheAnswer()
	{
		addRun(9_000, Status.COMPLETED);
		assertEquals(9_000, RoutineStats.personalBest(routine).getDurationMillis());

		final List<Run> replacement = new ArrayList<>();
		replacement.add(new Run(0, 2_000, 2_000, new ArrayList<>(), Status.COMPLETED));
		routine.setHistory(replacement);

		assertEquals("the history list was swapped for a different one and the old numbers were still"
			+ " being answered", 2_000, RoutineStats.personalBest(routine).getDurationMillis());
	}

	@Test
	public void twoClocksThatShareAnIdDoNotShareStatistics()
	{
		addRun(9_000, Status.COMPLETED);
		assertEquals(9_000, RoutineStats.personalBest(routine).getDurationMillis());

		// The same id, which is what the memo is keyed on, and a different
		// clock. A profile switch produces exactly this.
		final Routine other = new Routine("id", "Wine run");
		other.getHistory().add(new Run(0, 1_000, 1_000, new ArrayList<>(), Status.COMPLETED));

		assertEquals(1_000, RoutineStats.personalBest(other).getDurationMillis());
		assertEquals(9_000, RoutineStats.personalBest(routine).getDurationMillis());
	}

	@Test
	public void invalidatingChangesNothingAboutTheAnswers()
	{
		addRun(9_000, Status.COMPLETED);
		addRun(4_000, Status.COMPLETED);
		assertEquals(4_000, RoutineStats.personalBest(routine).getDurationMillis());

		RoutineStats.invalidate(routine);
		assertEquals(4_000, RoutineStats.personalBest(routine).getDurationMillis());

		RoutineStats.invalidateAll();
		assertEquals(4_000, RoutineStats.personalBest(routine).getDurationMillis());
		assertEquals(2, RoutineStats.completed(routine).size());

		RoutineStats.invalidate(null);
	}

	/**
	 * The split in progress, which the timer box and the side panel both read
	 * from here so that the two of them cannot disagree about one run.
	 */
	@Test
	public void aRunWithNoSplitsTakenIsOnLapOneAndHasBeenAllRun()
	{
		assertEquals("Lap 1", RoutineStats.currentLapLabel(Collections.emptyList()));
		assertEquals(4_000, RoutineStats.currentLapMillis(Collections.emptyList(), 4_000));
	}

	@Test
	public void theSplitInProgressIsMeasuredFromTheLastOneTaken()
	{
		final List<Lap> taken = Arrays.asList(
			new Lap(null, 3_000, 3_000),
			new Lap(null, 8_000, 5_000));

		assertEquals("Lap 3", RoutineStats.currentLapLabel(taken));
		assertEquals(2_500, RoutineStats.currentLapMillis(taken, 10_500));
	}

	/**
	 * A controller that has no run for this clock answers with an empty list,
	 * and a decode of damaged data can leave one null. Neither may throw on the
	 * refresh path, which runs twenty times a second for every card on screen.
	 */
	@Test
	public void noLapsAtAllReadsAsLapOneRatherThanThrowing()
	{
		assertEquals("Lap 1", RoutineStats.currentLapLabel(null));
		assertEquals(7_000, RoutineStats.currentLapMillis(null, 7_000));
	}

	// The two sets, the record, and the two averages

	/**
	 * The record is the first of the fastest set and is held nowhere else, so
	 * there is one copy of it and the card cannot disagree with the list.
	 */
	@Test
	public void thePersonalBestIsTheFirstOfTheFastestSet()
	{
		addRun(9_000, Status.COMPLETED);
		addRun(6_000, Status.COMPLETED);
		addRun(7_500, Status.COMPLETED);

		assertSame(RoutineStats.fastest(routine).get(0), RoutineStats.personalBest(routine));
		assertEquals(6_000, RoutineStats.personalBest(routine).getDurationMillis());
	}

	/**
	 * Two runs at exactly the same time. The older one holds the record, which
	 * is what this has always answered and is the same way the trim breaks the
	 * tie, so the run named as Best is a run that is still stored.
	 */
	@Test
	public void matchingTheRecordDoesNotTakeIt()
	{
		addRun(6_000, Status.COMPLETED);
		addRun(6_000, Status.COMPLETED);

		assertSame("the first run to reach the time keeps it",
			routine.getHistory().get(0), RoutineStats.personalBest(routine));
	}

	/**
	 * The two lists the panel draws are the two sets the store keeps, from the
	 * same rule, so nothing is listed that has already been let go.
	 */
	@Test
	public void theTwoListsAreTheTwoSetsTheStoreKeeps()
	{
		for (int i = 1; i <= 12; i++)
		{
			addRun(i * 1_000L, Status.COMPLETED);
		}

		assertEquals(RunHistory.recent(routine.getHistory()), RoutineStats.recent(routine));
		assertEquals(RunHistory.fastest(routine.getHistory()), RoutineStats.fastest(routine));
		assertEquals("newest first", 12_000, RoutineStats.recent(routine).get(0).getDurationMillis());
		assertEquals("fastest first", 1_000, RoutineStats.fastest(routine).get(0).getDurationMillis());
	}

	/**
	 * The window is over runs recorded, not over completed runs, and this is
	 * the case where the difference bites.
	 *
	 * <p>The stored runs are the newest ten and the fastest ten, so a window
	 * that reached past the newest ten to make itself up to length would reach
	 * straight into the user's record runs and quietly pull their recent
	 * average down towards their best ever form. Here the last three runs are
	 * abandoned, so the average is over the seven completed ones among the last
	 * ten and says so, rather than being topped up with three runs from months
	 * ago.
	 */
	@Test
	public void anAbandonedRunInTheWindowIsLeftOutRatherThanReplaced()
	{
		// An old record, the sort the fastest set exists to hold on to.
		addRun(100_000, Status.COMPLETED);
		for (int i = 0; i < 7; i++)
		{
			addRun(400_000, Status.COMPLETED);
		}
		for (int i = 0; i < 3; i++)
		{
			addRun(999_000, Status.ABANDONED);
		}

		assertEquals("the seven completed runs among the last ten, and nothing older",
			Long.valueOf(400_000), RoutineStats.averageOfLast(routine, 10));
		assertEquals(7, RoutineStats.completedInLast(routine, 10));
	}

	/**
	 * A window longer than the recent set has nothing behind it, so it is
	 * brought down here as well as in the config item that offers it. Without
	 * this a stored setting that got past the range would silently average a
	 * user's record runs into their recent form.
	 */
	@Test
	public void aWindowLongerThanTheRecentSetIsBroughtDownToIt()
	{
		addRun(100_000, Status.COMPLETED);
		for (int i = 0; i < 10; i++)
		{
			addRun(400_000, Status.COMPLETED);
		}

		assertEquals(Long.valueOf(400_000), RoutineStats.averageOfLast(routine, RunHistory.RECENT_KEPT));
		assertEquals("a window of fifty is the old maximum and must not reach any further than ten",
			Long.valueOf(400_000), RoutineStats.averageOfLast(routine, 50));
		assertEquals(RunHistory.RECENT_KEPT, RoutineStats.completedInLast(routine, 50));
	}

	@Test
	public void anAllTimeAverageIsTheQuotientOfTheStoredTotals()
	{
		assertNull("nothing counted yet", RoutineStats.allTimeAverage(routine));
		assertEquals(0, RoutineStats.completedAllTime(routine));

		routine.setTotals(new Totals(214, 214L * 300_000L));

		assertEquals(Long.valueOf(300_000L), RoutineStats.allTimeAverage(routine));
		assertEquals(214, RoutineStats.completedAllTime(routine));
	}

	/**
	 * The one repair the two numbers have, stated on its own.
	 *
	 * <p>{@code RoutineController} decides when to ask and what the floor is.
	 * What is asserted here is the rule itself, that a figure below the floor
	 * is raised to it and a figure above the floor is left exactly where it is,
	 * in both directions and on each number separately. Getting either
	 * comparison the wrong way round would quietly rewrite a lifetime record
	 * from the handful of runs that happen to still be stored.
	 */
	@Test
	public void raisingTheStoredTotalsNeverLowersEither()
	{
		final Totals totals = new Totals(7, 6_727_000L);

		totals.raiseTo(8, 7_680_000L);
		assertEquals(8, totals.getCompletedRuns());
		assertEquals(7_680_000L, totals.getCompletedMillis());

		totals.raiseTo(3, 1_000L);
		assertEquals("a lifetime count was brought down to the runs still stored", 8,
			totals.getCompletedRuns());
		assertEquals("and so was the time behind it, which is where the average comes from",
			7_680_000L, totals.getCompletedMillis());

		totals.raiseTo(9, 1_000L);
		assertEquals("each number is judged on its own, so a raised count is not a reason to touch"
				+ " a sum that is already above its own floor",
			9, totals.getCompletedRuns());
		assertEquals(7_680_000L, totals.getCompletedMillis());

		totals.raiseTo(0, 0);
		assertEquals(9, totals.getCompletedRuns());
		assertEquals(7_680_000L, totals.getCompletedMillis());
	}

	/**
	 * The reason the totals are stored at all. The runs behind an all time
	 * average are dropped as the cap does its work, and the answer has to
	 * survive that, because there is nowhere else it could be read from.
	 */
	@Test
	public void theAllTimeAverageOutlivesTheRunsItCameFrom()
	{
		routine.setTotals(new Totals(200, 200L * 360_000L));
		addRun(300_000, Status.COMPLETED);

		routine.getHistory().clear();

		assertEquals("dropping runs must not move the lifetime figure",
			Long.valueOf(360_000L), RoutineStats.allTimeAverage(routine));
		assertNull("while everything read off the runs goes with them",
			RoutineStats.personalBest(routine));
	}

	@Test
	public void nothingDerivedThrowsOnANullRoutine()
	{
		assertNull(RoutineStats.allTimeAverage(null));
		assertEquals(0, RoutineStats.completedAllTime(null));
		assertNull(RoutineStats.averageOfLast(null, 10));
		assertEquals(0, RoutineStats.completedInLast(null, 10));
		assertTrue(RoutineStats.recent(null).isEmpty());
		assertTrue(RoutineStats.fastest(null).isEmpty());
	}
}

package com.clockwork.core;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Which runs a clock keeps.
 *
 * <p>This is the file that decides whether a user's best ever run still exists,
 * so it is worth saying what is at stake. The plugin writes no file, keeps no
 * backup, and offers no export of runs. A config key is the only copy there is.
 * A rule that drops the wrong run does not archive it or summarise it, it
 * deletes it, and the user finds out when a number on a card is quietly worse
 * than the one they remember.
 *
 * <p>The rule used to be the newest fifty and nothing else, which meant exactly
 * that. It is now the newest ten and the fastest ten, and the tests below pin
 * both halves, the two decisions where a tie could go either way, and the order
 * of operations that a user upgrading depends on.
 */
public class RunHistoryTest
{
	/**
	 * A completed run of the given duration, with the start time carrying the
	 * position so a test can say which run came back.
	 */
	private static Run run(long startedAt, long duration)
	{
		return new Run(startedAt, startedAt + duration, duration, new ArrayList<>(), Status.COMPLETED);
	}

	private static Run abandoned(long startedAt, long duration)
	{
		return new Run(startedAt, startedAt + duration, duration, new ArrayList<>(), Status.ABANDONED);
	}

	private static List<Long> durationsOf(List<Run> runs)
	{
		final List<Long> durations = new ArrayList<>();
		for (Run each : runs)
		{
			durations.add(each.getDurationMillis());
		}
		return durations;
	}

	@Test
	public void aHistoryShorterThanEitherCapIsKeptWhole()
	{
		final List<Run> history = new ArrayList<>();
		for (int i = 0; i < 6; i++)
		{
			history.add(run(i, 1_000 + i));
		}

		assertEquals(6, RunHistory.kept(history).size());
		assertEquals(history, RunHistory.kept(history));
	}

	/**
	 * The whole point. A user getting slower, so their record is the oldest run
	 * they have, and it survives.
	 */
	@Test
	public void theFastestAreChosenBeforeAnythingIsDropped()
	{
		final List<Run> history = new ArrayList<>();
		for (int i = 1; i <= 50; i++)
		{
			history.add(run(i, i * 1_000L));
		}

		final List<Run> kept = RunHistory.kept(history);

		assertEquals("ten newest and ten fastest, and here they share nothing",
			RunHistory.MAX_KEPT, kept.size());
		assertSame("the fastest run ever recorded is the oldest one stored, and it is still here",
			history.get(0), kept.get(0));
		assertSame("as is the newest", history.get(49), kept.get(kept.size() - 1));

		// Runs one through ten for being the fastest, then forty one through
		// fifty for being the newest, in the order they were recorded.
		assertEquals(Arrays.asList(1_000L, 2_000L, 3_000L, 4_000L, 5_000L,
				6_000L, 7_000L, 8_000L, 9_000L, 10_000L,
				41_000L, 42_000L, 43_000L, 44_000L, 45_000L,
				46_000L, 47_000L, 48_000L, 49_000L, 50_000L),
			durationsOf(kept));
	}

	/**
	 * The case the user upgrading is in, and the one worth writing down on its
	 * own. Fifty stored runs where the best sits deep in the middle, nowhere
	 * near the newest ten, which is where a trim that took the newest first
	 * would already have thrown it away.
	 */
	@Test
	public void aRecordSetLongAgoSurvivesTheTrim()
	{
		final List<Run> history = new ArrayList<>();
		for (int i = 0; i < 50; i++)
		{
			history.add(run(i, 600_000L + i));
		}

		final Run recordFromMonthsAgo = run(999, 421_000L);
		history.set(3, recordFromMonthsAgo);

		final List<Run> kept = RunHistory.kept(history);

		assertTrue("the best run a user ever had was at position four of fifty and the trim"
				+ " destroyed it, which is the only copy of it that existed",
			kept.contains(recordFromMonthsAgo));
		assertSame("and it is still what the fastest set answers first",
			recordFromMonthsAgo, RunHistory.fastest(history).get(0));
	}

	/**
	 * An abandoned run is a run that ran away rather than an achievement, so it
	 * can never be one of the fastest however short it was. It can still be one
	 * of the newest, because the recent list is a record of what happened.
	 */
	@Test
	public void anAbandonedRunIsNeverOneOfTheFastest()
	{
		final List<Run> history = new ArrayList<>();
		for (int i = 0; i < 30; i++)
		{
			history.add(run(i, 500_000L + i));
		}
		final Run cutShort = abandoned(900, 1_000L);
		history.set(2, cutShort);

		assertFalse("the shortest run in the list was abandoned and it took the record",
			RunHistory.fastest(history).contains(cutShort));
		assertFalse("so nothing keeps it once it is not one of the newest either",
			RunHistory.kept(history).contains(cutShort));

		final Run cutShortRecently = abandoned(901, 1L);
		history.set(29, cutShortRecently);
		assertTrue("but an abandoned run among the newest is still part of what happened",
			RunHistory.kept(history).contains(cutShortRecently));
		assertFalse(RunHistory.fastest(history).contains(cutShortRecently));
	}

	/**
	 * Two runs of exactly equal duration. The older one is the faster of the
	 * two for every purpose, which means it is the one shown as the record.
	 *
	 * <p>That is deliberately the same answer the statistics have always given,
	 * since a new best was only taken on a strictly faster run, and it means the
	 * run named as Best does not change identity the moment somebody matches it.
	 */
	@Test
	public void aTieGoesToTheOlderRun()
	{
		final Run first = run(1, 300_000L);
		final Run matched = run(2, 300_000L);
		final Run slower = run(3, 400_000L);

		final List<Run> history = new ArrayList<>(Arrays.asList(first, matched, slower));
		final List<Run> fastest = RunHistory.fastest(history);

		assertSame("the earliest run to reach the time is the one that holds it",
			first, fastest.get(0));
		assertSame(matched, fastest.get(1));
		assertSame(slower, fastest.get(2));
	}

	/**
	 * A run that is both one of the newest and one of the fastest is stored
	 * once, so the two sets overlap rather than doubling up, and a clock holds
	 * somewhere between ten and twenty runs rather than always twenty.
	 */
	@Test
	public void aRunThatQualifiesOnBothCountsIsKeptOnce()
	{
		final List<Run> history = new ArrayList<>();
		for (int i = 30; i >= 1; i--)
		{
			history.add(run(31 - i, i * 1_000L));
		}

		final List<Run> kept = RunHistory.kept(history);

		assertEquals("every one of the newest ten is also one of the fastest ten",
			RunHistory.RECENT_KEPT, kept.size());
		assertEquals(Arrays.asList(10_000L, 9_000L, 8_000L, 7_000L, 6_000L,
				5_000L, 4_000L, 3_000L, 2_000L, 1_000L),
			durationsOf(kept));
	}

	/**
	 * Halfway between the two, which is the shape a real clock settles into.
	 * Some of the best runs are recent and some are not, so the kept count sits
	 * between the two bounds.
	 */
	@Test
	public void thePartlyOverlappingCaseKeepsSomethingInBetween()
	{
		final List<Run> history = new ArrayList<>();
		// Fifteen ordinary runs, then five very fast ones, then ten ordinary
		// again. The five fast ones are neither the newest nor forgettable.
		for (int i = 0; i < 15; i++)
		{
			history.add(run(i, 500_000L + i));
		}
		for (int i = 0; i < 5; i++)
		{
			history.add(run(100 + i, 300_000L + i));
		}
		for (int i = 0; i < 10; i++)
		{
			history.add(run(200 + i, 400_000L + i));
		}

		final List<Run> kept = RunHistory.kept(history);

		assertTrue("more than the recent set alone", kept.size() > RunHistory.RECENT_KEPT);
		assertTrue("and fewer than the two sets with no overlap at all",
			kept.size() < RunHistory.MAX_KEPT);
		// The five fast ones, plus five of the newest that are also among the
		// fastest ten, plus the newest ten.
		assertEquals(15, kept.size());
	}

	/**
	 * The kept list is in the order the runs were recorded, which every reader
	 * of the stored list depends on. The last completed run is read off the end
	 * of it, and the panel lists it backwards.
	 */
	@Test
	public void whatIsKeptStaysInRecordedOrder()
	{
		final List<Run> history = new ArrayList<>();
		for (int i = 1; i <= 40; i++)
		{
			history.add(run(i, (41 - i) * 1_000L));
		}

		final List<Run> kept = RunHistory.kept(history);

		long previous = -1;
		for (Run each : kept)
		{
			assertTrue("the kept runs came back out of order", each.getStartedAtEpochMillis() > previous);
			previous = each.getStartedAtEpochMillis();
		}
	}

	/**
	 * The recent list is the newest first, which is the order the panel draws
	 * it in, and it is the reverse of the stored order.
	 */
	@Test
	public void theRecentListReadsNewestFirst()
	{
		final List<Run> history = new ArrayList<>();
		for (int i = 1; i <= 14; i++)
		{
			history.add(run(i, i * 1_000L));
		}

		final List<Run> recent = RunHistory.recent(history);

		assertEquals(RunHistory.RECENT_KEPT, recent.size());
		assertEquals(14_000L, recent.get(0).getDurationMillis());
		assertEquals(5_000L, recent.get(recent.size() - 1).getDurationMillis());
	}

	@Test
	public void nothingReadableIsAskedOfNothing()
	{
		assertTrue(RunHistory.kept(null).isEmpty());
		assertTrue(RunHistory.recent(null).isEmpty());
		assertTrue(RunHistory.fastest(null).isEmpty());
		assertTrue(RunHistory.kept(Collections.emptyList()).isEmpty());
		assertTrue(RunHistory.fastest(Collections.emptyList()).isEmpty());
	}

	/**
	 * A null in a stored list carries nothing, so it is dropped rather than
	 * taking up one of the ten places a real run could have had.
	 */
	@Test
	public void nullsAreDroppedAndDoNotUseUpAPlace()
	{
		final List<Run> history = new ArrayList<>();
		for (int i = 1; i <= 12; i++)
		{
			history.add(run(i, i * 1_000L));
			history.add(null);
		}

		final List<Run> kept = RunHistory.kept(history);

		assertFalse(kept.contains(null));
		assertEquals("twelve real runs, all of them kept, and the nulls are not among them",
			12, kept.size());
	}

	@Test
	public void theRuleAboutWhichRunsCountIsSaidOnce()
	{
		assertFalse(RunHistory.counts(null));
		assertFalse(RunHistory.counts(abandoned(0, 1_000)));
		assertTrue(RunHistory.counts(run(0, 1_000)));
	}
}

package com.clockwork.core;

import java.util.ArrayList;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

/**
 * The per-routine choice about what a countdown does when it reaches zero.
 *
 * <p>Every test here counts the run finished callbacks, because the thing
 * worth protecting is that a countdown told to stop at zero raises exactly one
 * of them however many ticks arrive after the deadline, and that a countdown
 * told to carry on into overtime raises none until it is stopped by hand.
 */
public class StopAtZeroTest
{
	private static final long T0 = 1_700_000_000_000L;

	private FakeClock clock;
	private RoutineController controller;

	private final List<String> endings = new ArrayList<>();

	@Before
	public void setUp()
	{
		clock = new FakeClock(T0);
		controller = new RoutineController(clock);
		endings.clear();

		controller.addListener(new RoutineListener()
		{
			@Override
			public void onRunFinished(Routine routine, Run run)
			{
				if (run.getStatus() == Status.COMPLETED)
				{
					endings.add("finished");
				}
			}
		});
	}

	private Routine countdown(long targetMillis, boolean stopAtZero)
	{
		Routine r = controller.create("Five second countdown");
		controller.update(r.getId(), x ->
		{
			x.setMode(Mode.COUNT_DOWN);
			x.setTargetMillis(targetMillis);
			x.setStopAtZero(stopAtZero);
		});
		return r;
	}

	/**
	 * The default changed. A countdown that reaches zero has done what it was
	 * asked to do, so ending there is the ordinary case and carrying on into
	 * overtime is the one you ask for.
	 *
	 * <p>Only a clock made after this changed picks it up. The field is a
	 * primitive boolean, which Gson writes whether it is true or false, so
	 * every clock already saved carries its own answer and keeps it.
	 */
	@Test
	public void onByDefault()
	{
		assertTrue("a countdown should end at zero unless overtime is asked for",
			new Routine().isStopAtZero());
	}

	@Test
	public void stopsAndRecordsExactlyAtZero()
	{
		Routine r = countdown(5_000, true);
		controller.start(r.getId());

		clock.advance(4_999);
		controller.tick(clock.getAsLong());
		assertTrue("still inside the countdown", controller.isRunning(r.getId()));
		assertTrue(endings.isEmpty());

		clock.advance(1);
		controller.tick(clock.getAsLong());

		assertFalse(controller.isRunning(r.getId()));
		assertEquals(1, r.getHistory().size());

		Run run = r.getHistory().get(0);
		assertEquals("recorded the same way a stop records", Status.COMPLETED, run.getStatus());
		assertEquals(5_000, run.getDurationMillis());
		assertEquals(T0, run.getStartedAtEpochMillis());
		assertEquals(T0 + 5_000, run.getFinishedAtEpochMillis());

		// The run counts toward the statistics, because it really did complete.
		assertEquals(5_000, RoutineStats.personalBest(r).getDurationMillis());
		assertEquals(1, endings.size());
		assertEquals("finished", endings.get(0));
	}

	/**
	 * A tick that arrives long after the deadline. The recorded duration is the
	 * time that actually passed, not the target, because a history full of
	 * exactly-on-target runs would be a history of runs nobody did. The refresh
	 * timer ticks every fifty milliseconds, so the real overshoot is small, but
	 * a stalled client can make it anything at all and the record still has to
	 * be honest about it.
	 */
	@Test
	public void aLateTickRecordsTheTimeThatReallyPassed()
	{
		Routine r = countdown(5_000, true);
		controller.start(r.getId());

		clock.advance(8_000);
		controller.tick(clock.getAsLong());

		assertFalse(controller.isRunning(r.getId()));
		Run run = r.getHistory().get(0);
		assertEquals("the measured elapsed time, not the target", 8_000, run.getDurationMillis());
		assertEquals(T0 + 8_000, run.getFinishedAtEpochMillis());
		assertEquals(1, endings.size());
	}

	@Test
	public void withTheToggleOffTheRunCarriesOnIntoOvertime()
	{
		Routine r = countdown(5_000, false);
		controller.start(r.getId());

		clock.advance(5_000);
		controller.tick(clock.getAsLong());
		assertTrue("the run must survive zero", controller.isRunning(r.getId()));
		assertTrue("reaching zero must not end an overtime run", endings.isEmpty());
		assertTrue(r.getHistory().isEmpty());

		clock.advance(2_500);
		controller.tick(clock.getAsLong());
		assertTrue(controller.isRunning(r.getId()));
		assertEquals(Long.valueOf(-2_500), controller.remainingMillis(r.getId(), clock.getAsLong()));
		assertTrue("a tick past the deadline must not end an overtime run either",
			endings.isEmpty());
		assertTrue(r.getHistory().isEmpty());

		controller.stop(r.getId());
		assertEquals(7_500, r.getHistory().get(0).getDurationMillis());
		assertEquals("stopping by hand is what ends an overtime run", 1, endings.size());
		assertEquals("finished", endings.get(0));
	}

	/**
	 * Many ticks after the deadline must still leave one record and one
	 * callback, which is what the latch in the controller is for.
	 */
	@Test
	public void repeatedTicksPastZeroStopTheRunOnlyOnce()
	{
		Routine r = countdown(1_000, true);
		controller.start(r.getId());

		for (int i = 0; i < 20; i++)
		{
			clock.advance(500);
			controller.tick(clock.getAsLong());
		}

		assertEquals(1, r.getHistory().size());
		assertEquals(1, endings.size());
	}

	@Test
	public void aPausedCountdownDoesNotStopAndPicksUpTheShiftedDeadline()
	{
		Routine r = countdown(10_000, true);
		controller.update(r.getId(), x -> x.setClock(ClockMode.LOGGED_IN_ONLY));

		controller.start(r.getId());
		clock.advance(3_000);

		controller.setLoggedIn(false);
		clock.advance(600_000);
		controller.tick(clock.getAsLong());

		assertTrue("a logged out run must not hit its deadline", controller.isRunning(r.getId()));
		assertTrue(endings.isEmpty());
		assertEquals(Long.valueOf(7_000), controller.remainingMillis(r.getId(), clock.getAsLong()));

		controller.setLoggedIn(true);
		clock.advance(6_999);
		controller.tick(clock.getAsLong());
		assertTrue("still seven seconds of played time to go", controller.isRunning(r.getId()));

		clock.advance(1);
		controller.tick(clock.getAsLong());

		assertFalse(controller.isRunning(r.getId()));
		Run run = r.getHistory().get(0);
		assertEquals("logged out time is not part of the run", 10_000, run.getDurationMillis());
		assertEquals("the wall clock span is much longer than the run", T0 + 609_999 + 1,
			run.getFinishedAtEpochMillis());
		assertEquals(1, endings.size());
	}

	@Test
	public void theAutomaticStopClosesTheLastLap()
	{
		Routine r = countdown(5_000, true);
		controller.update(r.getId(), x -> x.setLapsEnabled(true));
		controller.start(r.getId());

		clock.advance(1_000);
		controller.lap(r.getId(), "Ardougne");
		clock.advance(2_500);
		controller.lap(r.getId(), "Catherby");

		clock.advance(1_500);
		controller.tick(clock.getAsLong());

		assertFalse(controller.isRunning(r.getId()));
		Run run = r.getHistory().get(0);
		List<Lap> laps = run.getLaps();

		assertEquals(3, laps.size());
		assertNull("the closing lap is the one the user did not label", laps.get(2).getLabel());
		assertEquals(5_000, laps.get(2).getSplitMillis());
		assertEquals(1_500, laps.get(2).getLapMillis());
		assertEquals("the last split must equal the run", run.getDurationMillis(),
			laps.get(laps.size() - 1).getSplitMillis());
	}

	@Test
	public void theToggleDoesNothingToACountUpRoutine()
	{
		Routine r = controller.create("Herb run");
		controller.update(r.getId(), x -> x.setStopAtZero(true));

		controller.start(r.getId());
		clock.advance(60_000);
		controller.tick(clock.getAsLong());

		assertTrue("a count up routine has no zero to stop at", controller.isRunning(r.getId()));
		assertTrue(endings.isEmpty());
	}

	@Test
	public void abandonStillWinsOverTheAutomaticStop()
	{
		Routine r = countdown(10_000, true);
		controller.update(r.getId(), x -> x.setAbandonAfterMillis(4_000L));

		controller.start(r.getId());
		clock.advance(4_000);
		controller.tick(clock.getAsLong());

		assertFalse(controller.isRunning(r.getId()));
		assertEquals(Status.ABANDONED, r.getHistory().get(0).getStatus());
		assertTrue("an abandoned run does not count as a completed one", endings.isEmpty());
	}

	@Test
	public void clearAllHistoryEmptiesEveryRoutineAndLeavesRunsAlone()
	{
		Routine a = controller.create("Herb run");
		Routine b = controller.create("Birdhouse run");

		controller.start(a.getId());
		clock.advance(1_000);
		controller.stop(a.getId());

		controller.start(b.getId());
		clock.advance(2_000);
		controller.stop(b.getId());

		controller.start(b.getId());
		clock.advance(500);

		controller.clearAllHistory();

		assertTrue(a.getHistory().isEmpty());
		assertTrue(b.getHistory().isEmpty());
		assertNull(RoutineStats.personalBest(a));
		assertTrue("a run in progress is not a stored run", controller.isRunning(b.getId()));
		assertEquals(500, controller.elapsedMillis(b.getId()));
	}
}

package com.clockwork.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

/**
 * Dispatch, against a real controller and a clock the test drives by hand.
 *
 * <p>Triggers go through the same {@code start} and {@code stop} the buttons
 * use, so what is checked here is not just that the right method was called but
 * that the arm semantics behind it still hold. A herb run is ten teleports and
 * has to stay one run.
 */
public class TriggerEngineTest
{
	private static final long T0 = 1_700_000_000_000L;

	private FakeClock clock;
	private RoutineController controller;

	@Before
	public void setUp()
	{
		clock = new FakeClock(T0);
		controller = new RoutineController(clock);
	}

	/**
	 * The two questions with no saved triggers in play, which is what most of
	 * the clocks below are set to. The engine takes the library either way, so
	 * the convenience sits here rather than as an overload nothing in the
	 * plugin calls.
	 */
	private static TriggerEngine.Action decide(Routine routine, boolean running, TriggerEvent event)
	{
		return decide(routine, TriggerLibrary.empty(), running, event);
	}

	private static TriggerEngine.Action decide(Routine routine, TriggerLibrary library,
		boolean running, TriggerEvent event)
	{
		return TriggerEngine.decide(routine, library, running, event);
	}

	private static boolean wants(List<Routine> routines, TriggerEvent.Kind kind)
	{
		return wants(routines, TriggerLibrary.empty(), kind);
	}

	private static boolean wants(List<Routine> routines, TriggerLibrary library, TriggerEvent.Kind kind)
	{
		return TriggerEngine.wants(routines, library, kind);
	}

	private static TriggerEvent teleport()
	{
		return TriggerEvent.animation(TeleportAnimations.HUMAN_CASTTELEPORT);
	}

	private static TriggerEvent bankChest()
	{
		return TriggerEvent.menuClick("Use", "Bank chest");
	}

	private static TriggerEvent iron()
	{
		return TriggerEvent.chatMessage("You manage to mine some iron.");
	}

	private static TriggerEvent click(String option, String target)
	{
		return TriggerEvent.menuClick(option, target);
	}

	private Routine clockWith(String name, TriggerType start, TriggerType stop)
	{
		return clockWith(name, Trigger.of(start), Trigger.of(stop));
	}

	private Routine clockWith(String name, Trigger start, Trigger stop)
	{
		Routine routine = controller.create(name);
		routine.setStartTrigger(start);
		routine.setStopTrigger(stop);
		return routine;
	}

	// Starting

	@Test
	public void aStartTriggerStartsAnIdleClock()
	{
		Routine herb = clockWith("Herb run", TriggerType.TELEPORT, null);

		assertFalse(controller.isRunning(herb.getId()));
		TriggerEngine.dispatch(controller, teleport());
		assertTrue(controller.isRunning(herb.getId()));
	}

	/**
	 * The reason the whole plugin has arm semantics. A herb run is ten
	 * teleports, and only the first of them may begin the run.
	 */
	@Test
	public void aStartTriggerOnARunningClockLeavesTheRunAlone()
	{
		Routine herb = clockWith("Herb run", TriggerType.TELEPORT, null);

		TriggerEngine.dispatch(controller, teleport());
		long startedAt = clock.getAsLong();

		for (int hop = 0; hop < 9; hop++)
		{
			clock.advance(30_000);
			TriggerEngine.dispatch(controller, teleport());
		}

		assertTrue(controller.isRunning(herb.getId()));
		assertEquals("the run should still be measuring from the first teleport",
			clock.getAsLong() - startedAt, controller.elapsedMillis(herb.getId()));
		assertTrue("nothing has ended, so nothing is recorded", herb.historyOrEmpty().isEmpty());
	}

	@Test
	public void aStartTriggerRestartsARunningClockThatAsksToBeRestarted()
	{
		Routine scratch = clockWith("Scratch", TriggerType.TELEPORT, null);
		scratch.setRestartOnStart(true);

		TriggerEngine.dispatch(controller, teleport());
		clock.advance(45_000);
		assertEquals(45_000, controller.elapsedMillis(scratch.getId()));

		TriggerEngine.dispatch(controller, teleport());

		assertTrue(controller.isRunning(scratch.getId()));
		assertEquals("the second teleport started it over", 0, controller.elapsedMillis(scratch.getId()));
		assertTrue("a discarded run is not recorded", scratch.historyOrEmpty().isEmpty());
	}

	// Stopping

	@Test
	public void aStopTriggerEndsARunningClockAndRecordsIt()
	{
		Routine herb = clockWith("Herb run", TriggerType.TELEPORT, TriggerType.BANK_CHEST);

		TriggerEngine.dispatch(controller, teleport());
		clock.advance(600_000);
		TriggerEngine.dispatch(controller, bankChest());

		assertFalse(controller.isRunning(herb.getId()));
		assertEquals(1, herb.historyOrEmpty().size());
		assertEquals(600_000, herb.historyOrEmpty().get(0).getDurationMillis());
		assertSame(Status.COMPLETED, herb.historyOrEmpty().get(0).getStatus());
	}

	/**
	 * A stop on an idle clock has nothing to end. It must not start one, and it
	 * must not file a run of no length, which is what a naive stop would leave
	 * behind every time somebody walked past a bank chest.
	 */
	@Test
	public void aStopTriggerOnAnIdleClockDoesNothingAndRecordsNothing()
	{
		Routine herb = clockWith("Herb run", TriggerType.TELEPORT, TriggerType.BANK_CHEST);

		for (int visit = 0; visit < 5; visit++)
		{
			TriggerEngine.dispatch(controller, bankChest());
		}

		assertFalse(controller.isRunning(herb.getId()));
		assertTrue("an idle stop must never write a run", herb.historyOrEmpty().isEmpty());
	}

	// The toggle

	/**
	 * One trigger on both ends means one event toggles the clock. Start wins
	 * while it is idle, stop wins while it is running.
	 */
	@Test
	public void oneTriggerOnBothEndsTogglesTheClock()
	{
		Routine laps = clockWith("Agility lap", TriggerType.BANK_CHEST, TriggerType.BANK_CHEST);

		TriggerEngine.dispatch(controller, bankChest());
		assertTrue("idle, so start won", controller.isRunning(laps.getId()));

		clock.advance(120_000);
		TriggerEngine.dispatch(controller, bankChest());
		assertFalse("running, so stop won", controller.isRunning(laps.getId()));
		assertEquals(1, laps.historyOrEmpty().size());
		assertEquals(120_000, laps.historyOrEmpty().get(0).getDurationMillis());

		clock.advance(5_000);
		TriggerEngine.dispatch(controller, bankChest());
		assertTrue("idle again, so start won again", controller.isRunning(laps.getId()));
		assertEquals("and only the one finished run has been recorded", 1, laps.historyOrEmpty().size());
	}

	/**
	 * The toggle is decided per event rather than per clock, so one event can
	 * never both stop and restart the same clock.
	 */
	@Test
	public void aToggleIsOneDecisionPerEvent()
	{
		Routine laps = clockWith("Agility lap", TriggerType.BANK_CHEST, TriggerType.BANK_CHEST);
		laps.setRestartOnStart(true);

		TriggerEngine.dispatch(controller, bankChest());
		clock.advance(60_000);
		TriggerEngine.dispatch(controller, bankChest());

		assertFalse("stop wins while it is running, even with start over ticked",
			controller.isRunning(laps.getId()));
		assertEquals(1, laps.historyOrEmpty().size());
	}

	// Scope

	@Test
	public void twoClocksWithTheSameStartTriggerEachStartThemselves()
	{
		Routine herb = clockWith("Herb run", TriggerType.TELEPORT, null);
		Routine tree = clockWith("Tree run", TriggerType.TELEPORT, null);

		TriggerEngine.dispatch(controller, teleport());

		assertTrue(controller.isRunning(herb.getId()));
		assertTrue(controller.isRunning(tree.getId()));
	}

	@Test
	public void oneClocksTriggerLeavesTheOthersAlone()
	{
		Routine herb = clockWith("Herb run", TriggerType.TELEPORT, null);
		Routine mining = clockWith("Iron", TriggerType.MINE_IRON, null);

		TriggerEngine.dispatch(controller, iron());

		assertFalse(controller.isRunning(herb.getId()));
		assertTrue(controller.isRunning(mining.getId()));
	}

	@Test
	public void aClockWithNoTriggersIsUntouchedByEverything()
	{
		Routine manual = controller.create("Manual");

		for (TriggerEvent event : Arrays.asList(teleport(), bankChest(), iron()))
		{
			TriggerEngine.dispatch(controller, event);
		}
		assertFalse(controller.isRunning(manual.getId()));

		controller.start(manual.getId());
		clock.advance(10_000);
		for (TriggerEvent event : Arrays.asList(teleport(), bankChest(), iron()))
		{
			TriggerEngine.dispatch(controller, event);
		}

		assertTrue("a hand started run is not stopped by anything either",
			controller.isRunning(manual.getId()));
		assertTrue(manual.historyOrEmpty().isEmpty());
	}

	/**
	 * A clock saved before triggers existed has neither field, and null has to
	 * behave exactly as "nothing" does.
	 */
	@Test
	public void aClockWithNullTriggersBehavesAsIfItHadNone()
	{
		Routine old = controller.create("Older clock");
		old.setStartTrigger(null);
		old.setStopTrigger(null);

		// A clock saved before the lap trigger existed decodes with this one
		// null and the other two filled in, which is the only thing an upgrade
		// costs it.
		old.setLapsEnabled(true);
		old.setLapTrigger(null);

		TriggerEngine.dispatch(controller, teleport());
		TriggerEngine.dispatch(controller, bankChest());

		assertFalse(controller.isRunning(old.getId()));
		assertTrue(old.historyOrEmpty().isEmpty());
	}

	// The decision on its own

	@Test
	public void theDecisionItselfReadsTheWayItIsDocumented()
	{
		Routine both = new Routine("x", "Both");
		both.setStartTrigger(Trigger.of(TriggerType.BANK_CHEST));
		both.setStopTrigger(Trigger.of(TriggerType.BANK_CHEST));

		assertSame(TriggerEngine.Action.START, decide(both, false, bankChest()));
		assertSame(TriggerEngine.Action.STOP, decide(both, true, bankChest()));
		assertSame(TriggerEngine.Action.NONE, decide(both, false, teleport()));
		assertSame(TriggerEngine.Action.NONE, decide(both, true, teleport()));

		Routine stopOnly = new Routine("y", "Stop only");
		stopOnly.setStopTrigger(Trigger.of(TriggerType.BANK_CHEST));
		assertSame(TriggerEngine.Action.NONE, decide(stopOnly, false, bankChest()));
		assertSame(TriggerEngine.Action.STOP, decide(stopOnly, true, bankChest()));

		assertSame(TriggerEngine.Action.NONE, decide(null, false, bankChest()));
		assertSame(TriggerEngine.Action.NONE, decide(stopOnly, true, null));
	}

	// What the handlers ask before they do any work

	@Test
	public void nobodyIsWatchedForWhenNoClockHasATrigger()
	{
		controller.create("Manual");

		for (TriggerEvent.Kind kind : TriggerEvent.Kind.values())
		{
			assertFalse(kind.name(), wants(controller.getRoutines(), kind));
		}
	}

	@Test
	public void onlyTheKindsSomeClockAsksForAreWatchedFor()
	{
		clockWith("Herb run", TriggerType.TELEPORT, TriggerType.BANK_CHEST);

		assertTrue(wants(controller.getRoutines(), TriggerEvent.Kind.ANIMATION));
		assertTrue(wants(controller.getRoutines(), TriggerEvent.Kind.MENU_CLICK));
		assertFalse(wants(controller.getRoutines(), TriggerEvent.Kind.CHAT_MESSAGE));

		assertFalse(wants(null, TriggerEvent.Kind.ANIMATION));
		assertFalse(wants(Collections.singletonList(null), TriggerEvent.Kind.ANIMATION));
		assertFalse(wants(controller.getRoutines(), null));
	}

	/**
	 * A click trigger with nothing filled in can match no click, so no handler
	 * should be switched on for it either. A user who picks the trigger and
	 * then cancels out of the boxes must not cost every click in the game a
	 * dispatch.
	 */
	@Test
	public void anEmptyClickTriggerIsNotWatchedForAtAll()
	{
		clockWith("Half set up", Trigger.click("", "  "), Trigger.nothing());

		for (TriggerEvent.Kind kind : TriggerEvent.Kind.values())
		{
			assertFalse(kind.name(), wants(controller.getRoutines(), kind));
		}
	}

	@Test
	public void aFilledInClickTriggerIsWatchedFor()
	{
		clockWith("Cloak", Trigger.click("Rub", "Ardougne cloak"), Trigger.nothing());

		assertTrue(wants(controller.getRoutines(), TriggerEvent.Kind.MENU_CLICK));
		assertFalse(wants(controller.getRoutines(), TriggerEvent.Kind.ANIMATION));
		assertFalse(wants(controller.getRoutines(), TriggerEvent.Kind.CHAT_MESSAGE));
	}

	// The click trigger, through the same dispatch as everything else

	@Test
	public void aClickTriggerStartsAnIdleClock()
	{
		Routine cloak = clockWith("Ardougne run", Trigger.click("Rub", "Ardougne cloak 4"), Trigger.nothing());

		TriggerEngine.dispatch(controller, click("Rub", "Ardougne cloak 4"));

		assertTrue(controller.isRunning(cloak.getId()));
	}

	/**
	 * The same arm semantics every other trigger gets. Rubbing the cloak again
	 * partway through a run must not restart the run.
	 */
	@Test
	public void aClickTriggerOnARunningClockLeavesTheRunAlone()
	{
		Routine cloak = clockWith("Ardougne run", Trigger.click("Rub", "Ardougne cloak"), Trigger.nothing());

		TriggerEngine.dispatch(controller, click("Rub", "Ardougne cloak 4"));
		long startedAt = clock.getAsLong();

		clock.advance(60_000);
		TriggerEngine.dispatch(controller, click("Rub", "Ardougne cloak 4"));

		assertTrue(controller.isRunning(cloak.getId()));
		assertEquals("still measuring from the first rub",
			clock.getAsLong() - startedAt, controller.elapsedMillis(cloak.getId()));
		assertTrue(cloak.historyOrEmpty().isEmpty());
	}

	@Test
	public void aClickStopTriggerOnAnIdleClockDoesNothingAndRecordsNothing()
	{
		Routine cloak = clockWith("Ardougne run", Trigger.of(TriggerType.TELEPORT),
			Trigger.click("Bank", "Bank chest"));

		for (int visit = 0; visit < 5; visit++)
		{
			TriggerEngine.dispatch(controller, click("Bank", "Bank chest"));
		}

		assertFalse(controller.isRunning(cloak.getId()));
		assertTrue("an idle stop must never write a run", cloak.historyOrEmpty().isEmpty());
	}

	@Test
	public void oneClickTriggerOnBothEndsTogglesTheClock()
	{
		Trigger mine = Trigger.click("Mine", "Iron rocks");
		Routine ore = clockWith("Iron", mine, mine);

		TriggerEngine.dispatch(controller, click("Mine", "Iron rocks"));
		assertTrue("idle, so start won", controller.isRunning(ore.getId()));

		clock.advance(90_000);
		TriggerEngine.dispatch(controller, click("Mine", "Iron rocks"));
		assertFalse("running, so stop won", controller.isRunning(ore.getId()));
		assertEquals(1, ore.historyOrEmpty().size());
		assertEquals(90_000, ore.historyOrEmpty().get(0).getDurationMillis());

		clock.advance(1_000);
		TriggerEngine.dispatch(controller, click("Mine", "Iron rocks"));
		assertTrue("idle again, so start won again", controller.isRunning(ore.getId()));
		assertEquals(1, ore.historyOrEmpty().size());
	}

	/**
	 * The case that would be a disaster in game. A click trigger nobody filled
	 * in matches no click, so a clock carrying one is driven by hand exactly as
	 * it was before.
	 */
	@Test
	public void anEmptyClickTriggerNeverFires()
	{
		Routine idle = clockWith("Half set up", Trigger.click(null, null), Trigger.click("", ""));

		for (String option : Arrays.asList("Use", "Walk here", "Examine", ""))
		{
			TriggerEngine.dispatch(controller, click(option, "Anything at all"));
		}

		assertFalse(controller.isRunning(idle.getId()));
		assertTrue(idle.historyOrEmpty().isEmpty());
	}

	/**
	 * A click trigger is still one clock's setting. It does not reach across to
	 * a clock that asked for something else.
	 */
	@Test
	public void aClickTriggerLeavesTheOtherClocksAlone()
	{
		Routine cloak = clockWith("Ardougne run", Trigger.click("Rub", "Ardougne cloak"), Trigger.nothing());
		Routine herb = clockWith("Herb run", Trigger.of(TriggerType.TELEPORT), Trigger.nothing());

		TriggerEngine.dispatch(controller, click("Rub", "Ardougne cloak 4"));

		assertTrue(controller.isRunning(cloak.getId()));
		assertFalse(controller.isRunning(herb.getId()));
	}

	// Saved triggers

	/**
	 * A clock does not hold the two strings of a custom trigger, it holds the
	 * id of a library entry. Dispatch has to resolve that before it can decide,
	 * and this is the test that says it does.
	 */
	@Test
	public void aClockPointingAtASavedTriggerFiresOnTheClickItNames()
	{
		final SavedTrigger herbs = save("Note herbs", "Use", "Tool Leprechaun");
		Routine herb = clockWith("Herb run", Trigger.saved(herbs.getName()), null);

		TriggerEngine.dispatch(controller, click("Use", "Gardener"));
		assertFalse("a different click is not this clock's click", controller.isRunning(herb.getId()));

		TriggerEngine.dispatch(controller, click("Talk-to", "Tool Leprechaun"));
		assertFalse("nor is the same target under another option", controller.isRunning(herb.getId()));

		TriggerEngine.dispatch(controller, click("Use", "Tool Leprechaun"));
		assertTrue(controller.isRunning(herb.getId()));
	}

	/**
	 * The point of a library. One correction reaches every clock waiting on it,
	 * because they all point at the same entry rather than holding copies.
	 */
	@Test
	public void editingASavedTriggerReachesEveryClockThatWaitsForIt()
	{
		final SavedTrigger herbs = save("Note herbs", "Use", "Tool Lepprechaun");
		Routine herb = clockWith("Herb run", Trigger.saved(herbs.getName()), null);
		Routine flax = clockWith("Flax run", Trigger.saved(herbs.getName()), null);

		TriggerEngine.dispatch(controller, click("Use", "Tool Leprechaun"));
		assertFalse("the typo means neither clock fires", controller.isRunning(herb.getId()));
		assertFalse(controller.isRunning(flax.getId()));

		controller.editLibrary(library -> library.edit(herbs.getName(), "Note herbs", "Use", "Tool Leprechaun"));

		TriggerEngine.dispatch(controller, click("Use", "Tool Leprechaun"));
		assertTrue(controller.isRunning(herb.getId()));
		assertTrue("both of them, from one edit", controller.isRunning(flax.getId()));
	}

	/**
	 * The dangling reference. A hand edited config can leave a clock pointing
	 * at an entry that is not there, and such a clock is manual rather than
	 * broken.
	 */
	@Test
	public void aClockPointingAtATriggerThatIsGoneIsSimplyManual()
	{
		Routine herb = clockWith("Herb run", Trigger.saved("gone"), null);

		TriggerEngine.dispatch(controller, click("Use", "Tool Leprechaun"));
		TriggerEngine.dispatch(controller, click("", ""));
		TriggerEngine.dispatch(controller, bankChest());
		assertFalse(controller.isRunning(herb.getId()));

		controller.start(herb.getId());
		assertTrue("and the buttons still work on it", controller.isRunning(herb.getId()));
	}

	/**
	 * The handler switch. A clock waiting on a saved trigger needs the menu
	 * handler on, and one waiting on an entry that is gone does not.
	 */
	@Test
	public void aSavedTriggerIsWhatDecidesWhetherTheMenuHandlerIsNeeded()
	{
		final SavedTrigger herbs = save("Note herbs", "Use", "Tool Leprechaun");
		Routine herb = clockWith("Herb run", Trigger.saved(herbs.getName()), null);

		assertTrue(wants(controller.getRoutines(), controller.getLibrary(),
			TriggerEvent.Kind.MENU_CLICK));
		assertFalse(wants(controller.getRoutines(), controller.getLibrary(),
			TriggerEvent.Kind.ANIMATION));

		controller.update(herb.getId(), r -> r.setStartTrigger(Trigger.saved("gone")));

		assertFalse("nothing can act on a click for a clock pointing at nothing",
			wants(controller.getRoutines(), controller.getLibrary(),
				TriggerEvent.Kind.MENU_CLICK));
	}


	// Lapping

	/**
	 * A clock that takes splits, with all three triggers set. The splits are
	 * switched on, because a lap trigger on a clock that does not take them is
	 * not a setting that can do anything.
	 */
	private Routine lapClock(String name, Trigger start, Trigger lap, Trigger stop)
	{
		Routine routine = clockWith(name, start, stop);
		routine.setLapTrigger(lap);
		routine.setLapsEnabled(true);
		return routine;
	}

	/**
	 * The case the lap trigger was added for. A herb run that starts on the
	 * teleport and ends at the bank used to give one number for ten patches,
	 * and now gives one per patch.
	 */
	@Test
	public void aLapTriggerSplitsARunningClockWithoutEndingIt()
	{
		Routine herb = lapClock("Herb run", Trigger.of(TriggerType.TELEPORT),
			Trigger.click("Use", "Tool Leprechaun"), Trigger.of(TriggerType.BANK_CHEST));

		TriggerEngine.dispatch(controller, teleport());

		clock.advance(60_000);
		TriggerEngine.dispatch(controller, click("Use", "Tool Leprechaun"));

		clock.advance(45_000);
		TriggerEngine.dispatch(controller, click("Use", "Tool Leprechaun"));

		assertTrue("a lap must never end the run", controller.isRunning(herb.getId()));
		assertTrue("and must never record one", herb.historyOrEmpty().isEmpty());

		List<Lap> laps = controller.currentLaps(herb.getId());
		assertEquals(2, laps.size());
		assertEquals(60_000, laps.get(0).getSplitMillis());
		assertEquals(60_000, laps.get(0).getLapMillis());
		assertEquals(105_000, laps.get(1).getSplitMillis());
		assertEquals("the second patch took 45 seconds", 45_000, laps.get(1).getLapMillis());
	}

	/**
	 * A lap on an idle clock has no run to split, exactly as a stop on one has
	 * no run to end. It must not open a run to put the split in.
	 */
	@Test
	public void aLapTriggerOnAnIdleClockDoesNothing()
	{
		Routine herb = lapClock("Herb run", Trigger.of(TriggerType.TELEPORT),
			Trigger.click("Use", "Tool Leprechaun"), Trigger.of(TriggerType.BANK_CHEST));

		for (int patch = 0; patch < 5; patch++)
		{
			TriggerEngine.dispatch(controller, click("Use", "Tool Leprechaun"));
		}

		assertFalse(controller.isRunning(herb.getId()));
		assertTrue(herb.historyOrEmpty().isEmpty());
		assertTrue(controller.currentLaps(herb.getId()).isEmpty());
		assertSame(TriggerEngine.Action.NONE,
			decide(herb, false, click("Use", "Tool Leprechaun")));
	}

	/**
	 * Splits switched off is a clock with nowhere to put a lap, so its lap
	 * trigger is read as though it were not there rather than turning the
	 * splits back on behind the user.
	 */
	@Test
	public void aLapTriggerDoesNothingWhenSplitsAreSwitchedOff()
	{
		Routine herb = lapClock("Herb run", Trigger.of(TriggerType.TELEPORT),
			Trigger.click("Use", "Tool Leprechaun"), Trigger.of(TriggerType.BANK_CHEST));
		herb.setLapsEnabled(false);

		TriggerEngine.dispatch(controller, teleport());
		clock.advance(60_000);
		TriggerEngine.dispatch(controller, click("Use", "Tool Leprechaun"));

		assertTrue("the run carries on", controller.isRunning(herb.getId()));
		assertTrue("but nothing was split", controller.currentLaps(herb.getId()).isEmpty());
		assertSame(TriggerEngine.Action.NONE,
			decide(herb, true, click("Use", "Tool Leprechaun")));
	}

	/**
	 * The first precedence rule. Ending the run is the more final intent, and
	 * the closing lap the controller writes covers the stretch a lap on the way
	 * out would have covered, so nothing is lost by the stop winning.
	 */
	@Test
	public void aStopBeatsALapWhenOneEventIsBoth()
	{
		Trigger bank = Trigger.of(TriggerType.BANK_CHEST);
		Routine herb = lapClock("Herb run", Trigger.of(TriggerType.TELEPORT), bank, bank);

		assertSame(TriggerEngine.Action.STOP, decide(herb, true, bankChest()));

		TriggerEngine.dispatch(controller, teleport());
		clock.advance(300_000);
		TriggerEngine.dispatch(controller, bankChest());

		assertFalse("stop won", controller.isRunning(herb.getId()));
		assertEquals(1, herb.historyOrEmpty().size());
		assertEquals(300_000, herb.historyOrEmpty().get(0).getDurationMillis());
		assertEquals("the closing lap is the only one, and it is the whole run",
			1, herb.historyOrEmpty().get(0).lapsOrEmpty().size());
		assertEquals(300_000, herb.historyOrEmpty().get(0).lapsOrEmpty().get(0).getSplitMillis());
	}

	/**
	 * The second precedence rule, on an idle clock. A lap has no run to split,
	 * so the start is the only one of the two that can mean anything.
	 */
	@Test
	public void aStartBeatsALapOnAnIdleClock()
	{
		Trigger tele = Trigger.of(TriggerType.TELEPORT);
		Routine herb = lapClock("Herb run", tele, tele, Trigger.of(TriggerType.BANK_CHEST));

		assertSame(TriggerEngine.Action.START, decide(herb, false, teleport()));

		TriggerEngine.dispatch(controller, teleport());

		assertTrue(controller.isRunning(herb.getId()));
		assertTrue("starting is not splitting", controller.currentLaps(herb.getId()).isEmpty());
	}

	/**
	 * The second precedence rule, on a running clock. The arm semantics already
	 * ignore a start against a running clock, so the lap is what the event
	 * means and the lap is what it does.
	 */
	@Test
	public void aLapBeatsAStartOnARunningClock()
	{
		Trigger tele = Trigger.of(TriggerType.TELEPORT);
		Routine herb = lapClock("Herb run", tele, tele, Trigger.of(TriggerType.BANK_CHEST));

		TriggerEngine.dispatch(controller, teleport());
		long startedAt = clock.getAsLong();

		assertSame(TriggerEngine.Action.LAP, decide(herb, true, teleport()));

		clock.advance(60_000);
		TriggerEngine.dispatch(controller, teleport());

		assertTrue(controller.isRunning(herb.getId()));
		assertEquals("still measuring from the first teleport",
			clock.getAsLong() - startedAt, controller.elapsedMillis(herb.getId()));
		assertEquals(1, controller.currentLaps(herb.getId()).size());
		assertEquals(60_000, controller.currentLaps(herb.getId()).get(0).getSplitMillis());
	}

	/**
	 * The exception to that. A clock that asks to be started over is one where
	 * the start is not ignored, so the premise the lap wins on does not hold
	 * and starting over is the more final of the two.
	 */
	@Test
	public void startingOverBeatsALapOnAClockThatAsksForIt()
	{
		Trigger tele = Trigger.of(TriggerType.TELEPORT);
		Routine scratch = lapClock("Scratch", tele, tele, Trigger.of(TriggerType.BANK_CHEST));
		scratch.setRestartOnStart(true);

		TriggerEngine.dispatch(controller, teleport());
		clock.advance(45_000);

		assertSame(TriggerEngine.Action.START, decide(scratch, true, teleport()));

		TriggerEngine.dispatch(controller, teleport());

		assertTrue(controller.isRunning(scratch.getId()));
		assertEquals("the second teleport started it over", 0, controller.elapsedMillis(scratch.getId()));
		assertTrue("and the run it started over has no splits in it",
			controller.currentLaps(scratch.getId()).isEmpty());
		assertTrue("a discarded run is not recorded", scratch.historyOrEmpty().isEmpty());
	}

	/**
	 * Every combination of the three, read off the decision itself rather than
	 * through a run, so the table is in one place and is legible.
	 */
	@Test
	public void theLapDecisionReadsTheWayItIsDocumented()
	{
		Routine lapOnly = new Routine("x", "Lap only");
		lapOnly.setLapsEnabled(true);
		lapOnly.setLapTrigger(Trigger.of(TriggerType.BANK_CHEST));

		assertSame("idle, so there is nothing to split",
			TriggerEngine.Action.NONE, decide(lapOnly, false, bankChest()));
		assertSame(TriggerEngine.Action.LAP, decide(lapOnly, true, bankChest()));
		assertSame(TriggerEngine.Action.NONE, decide(lapOnly, true, teleport()));

		lapOnly.setLapsEnabled(false);
		assertSame("splits off, so the lap trigger is not a setting",
			TriggerEngine.Action.NONE, decide(lapOnly, true, bankChest()));

		Routine lapAndStop = new Routine("y", "Lap and stop");
		lapAndStop.setLapsEnabled(true);
		lapAndStop.setLapTrigger(Trigger.of(TriggerType.BANK_CHEST));
		lapAndStop.setStopTrigger(Trigger.of(TriggerType.BANK_CHEST));

		assertSame("stop wins", TriggerEngine.Action.STOP,
			decide(lapAndStop, true, bankChest()));
		assertSame(TriggerEngine.Action.NONE, decide(lapAndStop, false, bankChest()));

		Routine startAndLap = new Routine("z", "Start and lap");
		startAndLap.setLapsEnabled(true);
		startAndLap.setStartTrigger(Trigger.of(TriggerType.TELEPORT));
		startAndLap.setLapTrigger(Trigger.of(TriggerType.TELEPORT));

		assertSame("idle, so start wins", TriggerEngine.Action.START,
			decide(startAndLap, false, teleport()));
		assertSame("running, so the start is ignored and the lap is what it means",
			TriggerEngine.Action.LAP, decide(startAndLap, true, teleport()));

		startAndLap.setRestartOnStart(true);
		assertSame("unless the start is not ignored, and then it wins",
			TriggerEngine.Action.START, decide(startAndLap, true, teleport()));

		Routine none = new Routine("w", "Nothing set");
		none.setLapsEnabled(true);
		assertSame(TriggerEngine.Action.NONE, decide(none, true, bankChest()));
	}

	/**
	 * The handler switch. A clock whose only trigger is a lap is still a clock
	 * waiting for an event, so the handler for that event has to be on. Without
	 * this the whole feature is silently dead for the clock that has only it.
	 */
	@Test
	public void aClockWhoseOnlyTriggerIsALapIsStillWatchedFor()
	{
		Routine herb = controller.create("Herb run");
		herb.setLapsEnabled(true);
		herb.setLapTrigger(Trigger.click("Use", "Tool Leprechaun"));

		assertTrue(wants(controller.getRoutines(), TriggerEvent.Kind.MENU_CLICK));
		assertFalse(wants(controller.getRoutines(), TriggerEvent.Kind.ANIMATION));
		assertFalse(wants(controller.getRoutines(), TriggerEvent.Kind.CHAT_MESSAGE));

		herb.setLapTrigger(Trigger.of(TriggerType.TELEPORT));
		assertTrue(wants(controller.getRoutines(), TriggerEvent.Kind.ANIMATION));
		assertFalse(wants(controller.getRoutines(), TriggerEvent.Kind.MENU_CLICK));
	}

	/**
	 * The same switch for a lap trigger that names a library entry, which is
	 * what the editor actually stores when the user picks a custom trigger.
	 */
	@Test
	public void aSavedLapTriggerSwitchesTheMenuHandlerOn()
	{
		final SavedTrigger herbs = save("Note herbs", "Use", "Tool Leprechaun");
		Routine herb = controller.create("Herb run");
		herb.setLapsEnabled(true);
		herb.setLapTrigger(Trigger.saved(herbs.getName()));

		assertTrue(wants(controller.getRoutines(), controller.getLibrary(),
			TriggerEvent.Kind.MENU_CLICK));

		controller.update(herb.getId(), r -> r.setLapTrigger(Trigger.saved("gone")));

		assertFalse("nothing can act on a click for a clock pointing at nothing",
			wants(controller.getRoutines(), controller.getLibrary(),
				TriggerEvent.Kind.MENU_CLICK));
	}

	/**
	 * Adds an entry to the controller's library and hands it back. The one
	 * element array is how a lambda gives something to the caller.
	 */
	private SavedTrigger save(String name, String option, String target)
	{
		final SavedTrigger[] saved = new SavedTrigger[1];
		controller.editLibrary(library -> saved[0] = library.add(name, option, target));
		return saved[0];
	}
}

package com.clockwork.core;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import org.junit.Before;
import org.junit.Test;

/**
 * The named custom triggers, and the rules for keeping them.
 *
 * <p>Every rule here is a pure function of a value, so the awkward cases can be
 * written down rather than found in game months later. The two that matter most
 * are at the bottom. A trigger a clock is still waiting for must not be
 * deletable, and a reference to a trigger that is gone must read as Nothing
 * rather than throw or, far worse, fire on everything.
 */
public class TriggerLibraryTest
{
	private TriggerLibrary library;

	@Before
	public void setUp()
	{
		library = TriggerLibrary.empty();
	}

	private static TriggerEvent click(String option, String target)
	{
		return TriggerEvent.menuClick(option, target);
	}

	// Adding

	@Test
	public void anAddedTriggerIsThereUnderItsName()
	{
		SavedTrigger herbs = library.add("Note herbs", "Use", "Tool Leprechaun");

		assertEquals(1, library.all().size());
		assertSame(herbs, library.byName(herbs.getName()));
		assertSame(herbs, library.byName("Note herbs"));
		assertEquals("Note herbs", herbs.getName());
		assertEquals("Use: Tool Leprechaun", herbs.describe());
	}

	@Test
	public void aNameIsTrimmedAndSoAreTheStrings()
	{
		SavedTrigger herbs = library.add("  Note herbs  ", "  Use  ", "  Tool Leprechaun  ");

		assertEquals("Note herbs", herbs.getName());
		assertEquals("Use", herbs.getOption());
		assertEquals("Tool Leprechaun", herbs.getTarget());
	}

	@Test
	public void theListReadsAlphabeticallyWhateverOrderTheyWereAddedIn()
	{
		library.add("Rub the cloak", "Rub", "Ardougne cloak");
		library.add("note herbs", "Use", "Tool Leprechaun");
		library.add("Bank it", "Bank", "Bank chest");

		List<SavedTrigger> all = library.all();
		assertEquals("Bank it", all.get(0).getName());
		assertEquals("case does not sort a name away from its neighbours",
			"note herbs", all.get(1).getName());
		assertEquals("Rub the cloak", all.get(2).getName());
	}

	// Names

	@Test
	public void aNameCannotBeTakenTwice()
	{
		library.add("Note herbs", "Use", "Tool Leprechaun");

		final String problem = library.problemWith("Note herbs", "Rub", "Cloak", null);
		assertNotNull("a second Note herbs is refused rather than saved quietly", problem);
		assertTrue(problem, problem.contains("Note herbs"));

		assertNotNull("and case is not a way around it",
			library.problemWith("NOTE HERBS", "Rub", "Cloak", null));
		assertNotNull("nor is space",
			library.problemWith("  Note herbs  ", "Rub", "Cloak", null));

		try
		{
			library.add("Note herbs", "Rub", "Cloak");
			fail("a library that can be talked into holding a name twice is not a library");
		}
		catch (IllegalArgumentException expected)
		{
			assertEquals("nothing was added", 1, library.all().size());
		}
	}

	@Test
	public void aNameCannotBeEmpty()
	{
		assertNotNull(library.problemWith("", "Use", "Tool Leprechaun", null));
		assertNotNull(library.problemWith("   ", "Use", "Tool Leprechaun", null));
		assertNotNull(library.problemWith(null, "Use", "Tool Leprechaun", null));
		assertTrue(library.all().isEmpty());
	}

	/**
	 * The rule that has always been there, kept in the one place a custom
	 * trigger is now defined. Both halves empty would match every click in the
	 * game.
	 */
	@Test
	public void neitherHalfFilledInIsRefused()
	{
		assertNotNull(library.problemWith("Everything", "", "", null));
		assertNotNull(library.problemWith("Everything", null, null, null));
		assertNotNull(library.problemWith("Everything", "   ", "\t", null));

		assertNull("one half is enough", library.problemWith("Any use", "Use", "", null));
		assertNull("either half", library.problemWith("Any chest", "", "Bank chest", null));
	}

	// Editing

	/**
	 * This used to be the test that a rename kept the entry's generated id, on
	 * the grounds that the id was what a clock held and so nothing had to
	 * follow. A clock holds the name now, so there is no id to keep and the
	 * rename is exactly the edit that has to be followed through. Same
	 * guarantee, which is that a rename never costs a clock its trigger, and a
	 * different mechanism, so the test says the new thing rather than the old
	 * one.
	 */
	@Test
	public void renamingCascadesOntoEveryClockThatWasWaitingForIt()
	{
		SavedTrigger herbs = library.add("Note herbs", "Use", "Tool Leprechaun");

		Routine herbRun = new Routine("a", "Herb run");
		herbRun.setStartTrigger(Trigger.saved(herbs.getName()));

		Routine flaxRun = new Routine("b", "Flax run");
		flaxRun.setStopTrigger(Trigger.saved(herbs.getName()));

		Routine wineRun = new Routine("c", "Wine run");
		wineRun.setStartTrigger(Trigger.of(TriggerType.TELEPORT));

		List<Routine> clocks = Arrays.asList(herbRun, flaxRun, wineRun);

		SavedTrigger renamed = library.edit("Note herbs", "Leprechaun", "Use", "Tool Leprechaun");
		assertEquals(2, TriggerLibrary.repoint(clocks, "Note herbs", renamed.getName()));

		assertEquals(1, library.all().size());
		assertEquals("Leprechaun", renamed.getName());
		assertNull("the old name is free again", library.byName("Note herbs"));

		assertEquals("a start trigger followed", Trigger.saved("Leprechaun"), herbRun.getStartTrigger());
		assertEquals("and so did a stop trigger", Trigger.saved("Leprechaun"), flaxRun.getStopTrigger());
		assertEquals("a clock waiting for something else is untouched",
			Trigger.of(TriggerType.TELEPORT), wineRun.getStartTrigger());

		assertTrue("and the clocks still fire on the click they always fired on",
			library.matches(herbRun.getStartTrigger(), click("Use", "Tool Leprechaun")));
	}

	/**
	 * The cascade is the thing that has to not happen when nothing was renamed,
	 * and the thing that has to not happen to a clock nobody asked about.
	 */
	@Test
	public void repointingLeavesEverythingElseAlone()
	{
		Routine herbRun = new Routine("a", "Herb run");
		herbRun.setStartTrigger(Trigger.saved("Note herbs"));

		List<Routine> clocks = Collections.singletonList(herbRun);

		assertEquals("the same name is not a rename", 0,
			TriggerLibrary.repoint(clocks, "Note herbs", "note herbs"));
		assertEquals(0, TriggerLibrary.repoint(clocks, "Something else", "Leprechaun"));
		assertEquals(0, TriggerLibrary.repoint(null, "Note herbs", "Leprechaun"));
		assertEquals(0, TriggerLibrary.repoint(clocks, null, "Leprechaun"));
		assertEquals(0, TriggerLibrary.repoint(clocks, "Note herbs", null));

		assertEquals(Trigger.saved("Note herbs"), herbRun.getStartTrigger());
	}

	@Test
	public void editingTheClickChangesWhatEveryClockPointingAtItWaitsFor()
	{
		SavedTrigger herbs = library.add("Note herbs", "Use", "Tool Lepprechaun");
		Trigger onAClock = Trigger.saved(herbs.getName());

		assertFalse("the typo means it never fires",
			library.matches(onAClock, click("Use", "Tool Leprechaun")));

		library.edit(herbs.getName(), "Note herbs", "Use", "Tool Leprechaun");

		assertTrue("corrected once, and the clock that was pointing at it is corrected too",
			library.matches(onAClock, click("Use", "Tool Leprechaun")));
	}

	@Test
	public void anEntryIsAllowedToKeepItsOwnNameWhileBeingEdited()
	{
		SavedTrigger herbs = library.add("Note herbs", "Use", "Tool Leprechaun");

		assertNull("its own name is not a clash with itself",
			library.problemWith("Note herbs", "Use", "Gardener", herbs.getName()));

		SavedTrigger edited = library.edit(herbs.getName(), "Note herbs", "Use", "Gardener");
		assertEquals("Gardener", edited.getTarget());
	}

	@Test
	public void anEditCannotTakeAnotherEntrysName()
	{
		library.add("Note herbs", "Use", "Tool Leprechaun");
		SavedTrigger cloak = library.add("Rub the cloak", "Rub", "Ardougne cloak");

		assertNotNull(library.problemWith("Note herbs", "Rub", "Ardougne cloak", cloak.getName()));
		try
		{
			library.edit(cloak.getName(), "Note herbs", "Rub", "Ardougne cloak");
			fail("two entries called Note herbs is exactly what the library exists to prevent");
		}
		catch (IllegalArgumentException expected)
		{
			assertEquals("Rub the cloak", library.byName(cloak.getName()).getName());
		}
	}

	@Test
	public void editingSomethingThatIsNotThereChangesNothing()
	{
		assertNull(library.edit("gone", "Note herbs", "Use", "Tool Leprechaun"));
		assertTrue(library.all().isEmpty());
	}

	// Deleting

	@Test
	public void anUnusedTriggerCanBeDeleted()
	{
		SavedTrigger herbs = library.add("Note herbs", "Use", "Tool Leprechaun");

		assertTrue(library.remove(herbs.getName()));
		assertTrue(library.all().isEmpty());
		assertNull(library.byName(herbs.getName()));
		assertFalse("and removing it twice is not a second deletion", library.remove(herbs.getName()));
	}

	@Test
	public void deletingSomethingThatIsNotThereIsNotAnError()
	{
		assertFalse(library.remove("gone"));
		assertFalse(library.remove(null));
	}

	/**
	 * The refusal, and the reason it names the clocks. Detaching them silently
	 * would change what they do without being asked, and cascading the delete
	 * would leave clocks pointing at nothing.
	 */
	@Test
	public void aTriggerAClockIsWaitingForNamesTheClocksThatWantIt()
	{
		SavedTrigger herbs = library.add("Note herbs", "Use", "Tool Leprechaun");

		Routine herbRun = new Routine("a", "Herb run");
		herbRun.setStartTrigger(Trigger.saved(herbs.getName()));

		Routine flaxRun = new Routine("b", "Flax run");
		flaxRun.setStopTrigger(Trigger.saved(herbs.getName()));

		Routine wineRun = new Routine("c", "Wine run");
		wineRun.setStartTrigger(Trigger.of(TriggerType.TELEPORT));

		List<Routine> clocks = Arrays.asList(herbRun, flaxRun, wineRun);
		List<String> users = TriggerLibrary.usedBy(clocks, herbs.getName());

		assertEquals("a start trigger and a stop trigger both count", 2, users.size());
		assertTrue(users.contains("Herb run"));
		assertTrue(users.contains("Flax run"));
		assertFalse("a clock that waits for something else is not named", users.contains("Wine run"));
	}

	/**
	 * A lap trigger is a use like any other. Missing it here would let the user
	 * delete an entry a clock is still splitting on, and that clock would go on
	 * looking configured while quietly never splitting again.
	 */
	@Test
	public void aTriggerAClockSplitsOnCountsAsAUseAndBlocksTheDelete()
	{
		SavedTrigger herbs = library.add("Note herbs", "Use", "Tool Leprechaun");

		Routine herbRun = new Routine("a", "Herb run");
		herbRun.setLapsEnabled(true);
		herbRun.setLapTrigger(Trigger.saved(herbs.getName()));

		Routine wineRun = new Routine("b", "Wine run");
		wineRun.setStartTrigger(Trigger.of(TriggerType.TELEPORT));

		List<String> users = TriggerLibrary.usedBy(Arrays.asList(herbRun, wineRun), herbs.getName());

		assertEquals(1, users.size());
		assertEquals("the clock is named, because an id would tell the user nothing",
			"Herb run", users.get(0));
	}

	/**
	 * A clock that starts, splits, and stops on one entry is named once rather
	 * than three times, because the message reads out clock names.
	 */
	@Test
	public void aClockUsingOneTriggerThreeTimesIsNamedOnce()
	{
		SavedTrigger herbs = library.add("Note herbs", "Use", "Tool Leprechaun");

		Routine herbRun = new Routine("a", "Herb run");
		herbRun.setLapsEnabled(true);
		herbRun.setStartTrigger(Trigger.saved(herbs.getName()));
		herbRun.setLapTrigger(Trigger.saved(herbs.getName()));
		herbRun.setStopTrigger(Trigger.saved(herbs.getName()));

		assertEquals(1, TriggerLibrary.usedBy(Collections.singletonList(herbRun), herbs.getName()).size());
	}

	/**
	 * A rename has to reach a lap trigger too, or renaming an entry leaves
	 * every clock splitting on it pointed at a name that names nothing.
	 */
	@Test
	public void renamingCascadesOntoALapTriggerAsWell()
	{
		SavedTrigger herbs = library.add("Note herbs", "Use", "Tool Leprechaun");

		Routine herbRun = new Routine("a", "Herb run");
		herbRun.setLapsEnabled(true);
		herbRun.setLapTrigger(Trigger.saved(herbs.getName()));

		List<Routine> clocks = Collections.singletonList(herbRun);
		SavedTrigger renamed = library.edit("Note herbs", "Leprechaun", "Use", "Tool Leprechaun");

		assertEquals(1, TriggerLibrary.repoint(clocks, "Note herbs", renamed.getName()));
		assertEquals(Trigger.saved("Leprechaun"), herbRun.getLapTrigger());
		assertTrue("and it still splits on the click it always split on",
			library.matches(herbRun.getLapTrigger(), click("Use", "Tool Leprechaun")));
	}

	/**
	 * One clock changed once, however many of its triggers point at the entry.
	 * The count is clocks rather than triggers, and a lap trigger must not
	 * quietly turn one clock into two.
	 */
	@Test
	public void repointingCountsAClockOnceHoweverManyOfItsTriggersFollow()
	{
		Routine herbRun = new Routine("a", "Herb run");
		herbRun.setLapsEnabled(true);
		herbRun.setStartTrigger(Trigger.saved("Note herbs"));
		herbRun.setLapTrigger(Trigger.saved("Note herbs"));
		herbRun.setStopTrigger(Trigger.saved("Note herbs"));

		assertEquals(1, TriggerLibrary.repoint(Collections.singletonList(herbRun),
			"Note herbs", "Leprechaun"));
		assertEquals(Trigger.saved("Leprechaun"), herbRun.getStartTrigger());
		assertEquals(Trigger.saved("Leprechaun"), herbRun.getLapTrigger());
		assertEquals(Trigger.saved("Leprechaun"), herbRun.getStopTrigger());
	}

	@Test
	public void aTriggerNobodyWantsIsUsedByNothing()
	{
		SavedTrigger herbs = library.add("Note herbs", "Use", "Tool Leprechaun");
		SavedTrigger cloak = library.add("Rub the cloak", "Rub", "Ardougne cloak");

		Routine herbRun = new Routine("a", "Herb run");
		herbRun.setStartTrigger(Trigger.saved(herbs.getName()));

		assertTrue(TriggerLibrary.usedBy(Collections.singletonList(herbRun), cloak.getName()).isEmpty());
		assertTrue(TriggerLibrary.usedBy(null, herbs.getName()).isEmpty());
		assertTrue(TriggerLibrary.usedBy(Collections.singletonList(herbRun), null).isEmpty());
	}

	// Resolving

	@Test
	public void aReferenceResolvesToTheClickItNames()
	{
		SavedTrigger herbs = library.add("Note herbs", "Use", "Tool Leprechaun");
		Trigger onAClock = Trigger.saved(herbs.getName());

		assertEquals(Trigger.click("Use", "Tool Leprechaun"), library.resolve(onAClock));
		assertSame(TriggerEvent.Kind.MENU_CLICK, library.kind(onAClock));
		assertEquals("click, Note herbs", library.hint(onAClock));

		assertTrue(library.matches(onAClock, click("Use", "Tool Leprechaun")));
		assertFalse("and not on a click it was not written for",
			library.matches(onAClock, click("Use", "Gardener")));
		assertFalse(library.matches(onAClock, click("Talk-to", "Tool Leprechaun")));
	}

	/**
	 * The dangling case, which a hand edited config or a clock copied between
	 * profiles can produce. It has to be Nothing, because the alternatives are
	 * a crash or a clock that fires on something nobody asked for.
	 */
	@Test
	public void aReferenceToSomethingThatIsGoneIsNothing()
	{
		Trigger onAClock = Trigger.saved("gone");

		assertSame(Trigger.nothing(), library.resolve(onAClock));
		assertNull(library.kind(onAClock));
		assertEquals("nothing", library.hint(onAClock));
		assertFalse(library.matches(onAClock, click("Use", "Tool Leprechaun")));
		assertFalse(library.matches(onAClock, click("", "")));
	}

	@Test
	public void aTriggerThatIsNotAReferenceIsHandedBackAsItStands()
	{
		assertSame(Trigger.nothing(), library.resolve(null));
		assertEquals(Trigger.of(TriggerType.TELEPORT), library.resolve(Trigger.of(TriggerType.TELEPORT)));
		assertEquals(Trigger.click("Rub", "Cloak"), library.resolve(Trigger.click("Rub", "Cloak")));
		assertEquals("teleporting", library.hint(Trigger.of(TriggerType.TELEPORT)));
		assertTrue(library.matches(Trigger.of(TriggerType.BANK_CHEST), click("Use", "Bank chest")));
	}

	// Reading what came out of storage

	@Test
	public void aDamagedLibraryLoadsAsMuchOfItselfAsMakesSense()
	{
		SavedTrigger good = SavedTrigger.of("Note herbs", "Use", "Tool Leprechaun");
		SavedTrigger sameName = SavedTrigger.of("note herbs", "Rub", "Cloak");
		SavedTrigger other = SavedTrigger.of("Rub the cloak", "Rub", "Cloak");

		TriggerLibrary loaded = TriggerLibrary.of(Arrays.asList(good, null, sameName, other));

		assertEquals("a name twice is one entry, and the first one wins", 2, loaded.all().size());
		assertEquals("Use", loaded.byName("Note herbs").getOption());
		assertEquals("Rub the cloak", loaded.byName("Rub the cloak").getName());
		assertTrue(TriggerLibrary.of(null).all().isEmpty());
	}

	// Absorbing, which is what an import does

	@Test
	public void absorbingAnEntryThatIsAlreadyThereReusesIt()
	{
		SavedTrigger mine = library.add("Note herbs", "Use", "Tool Leprechaun");

		assertSame("the same name asking for the same click is the same idea",
			mine, library.absorb("Note herbs", "Use", "Tool Leprechaun"));
		assertSame("and case is not a second entry",
			mine, library.absorb("NOTE HERBS", "Use", "Tool Leprechaun"));
		assertEquals(1, library.all().size());
	}

	@Test
	public void absorbingADifferentClickUnderATakenNameNumbersIt()
	{
		library.add("Note herbs", "Use", "Tool Leprechaun");

		SavedTrigger landed = library.absorb("Note herbs", "Rub", "Ardougne cloak");

		assertEquals("neither was dropped and neither was overwritten", 2, library.all().size());
		assertEquals("Note herbs (2)", landed.getName());
		assertEquals("what the user already had is untouched",
			"Use", library.byName("Note herbs").getOption());
	}

	@Test
	public void absorbingAnEntryNobodyHasKeepsItsName()
	{
		SavedTrigger landed = library.absorb("Note herbs", "Use", "Tool Leprechaun");

		assertEquals("Note herbs", landed.getName());
		assertEquals(1, library.all().size());
	}

	/**
	 * An entry with neither string filled in cannot fire, which is what
	 * {@link Trigger#matches} already says about it. It is still absorbed,
	 * because dropping it would leave the clocks that named it pointing at
	 * nothing at all, which is a worse answer than a trigger that never comes
	 * up.
	 */
	@Test
	public void absorbingAnEntryWithNeitherStringIsNotRefused()
	{
		SavedTrigger landed = library.absorb("Nothing at all", null, null);

		assertEquals("Nothing at all", landed.getName());
		assertEquals(1, library.all().size());
	}

	/**
	 * A name that is already taken a thousand times over still lands, because
	 * an import that silently dropped a trigger would leave the clock that
	 * named it looking configured and never firing.
	 */
	@Test
	public void absorbingAnEntryWithNoNameStillLands()
	{
		SavedTrigger landed = library.absorb("   ", "Use", "Tool Leprechaun");

		assertEquals("Custom trigger", landed.getName());
	}
}

package com.clockwork.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The click trigger the user writes themselves.
 *
 * <p>Every rule below is a pure function of a value, so the near misses can be
 * written down and asserted against rather than found in game months later. The
 * dangerous one is the last group. A trigger with nothing filled in has to match
 * nothing, because the alternative is a clock that starts on every click in the
 * game.
 */
public class TriggerTest
{
	private static TriggerEvent click(String option, String target)
	{
		return TriggerEvent.menuClick(option, target);
	}

	// The option half

	@Test
	public void anOptionMatchesExactly()
	{
		Trigger rub = Trigger.click("Rub", null);

		assertTrue(rub.matches(click("Rub", "Ardougne cloak 4")));
		assertTrue("no target asked for, so any target will do",
			rub.matches(click("Rub", "Anything at all")));
	}

	@Test
	public void anOptionIsNotMatchedAsASubstring()
	{
		Trigger rub = Trigger.click("Rub", null);

		assertFalse("the option is the whole word or nothing", rub.matches(click("Rubbing", "Cloak")));
		assertFalse(rub.matches(click("Scrub", "Cloak")));
		assertFalse(rub.matches(click("Use", "Cloak")));
		assertFalse(rub.matches(click("", "Cloak")));
	}

	@Test
	public void aBlankOptionMatchesAnyOption()
	{
		Trigger anyOption = Trigger.click("", "Bank chest");

		assertTrue(anyOption.matches(click("Use", "Bank chest")));
		assertTrue(anyOption.matches(click("Deposit", "Bank chest")));
		assertTrue("examine included, since the user asked for any option",
			anyOption.matches(click("Examine", "Bank chest")));
		assertTrue(anyOption.matches(click("", "Bank chest")));
	}

	@Test
	public void aBlankOptionIsTheSameThingAsAMissingOne()
	{
		assertEquals(Trigger.click(null, "Bank chest"), Trigger.click("", "Bank chest"));
		assertEquals(Trigger.click(null, "Bank chest"), Trigger.click("   ", "Bank chest"));
		assertNull(Trigger.click("   ", "Bank chest").getOption());
	}

	// The target half

	@Test
	public void aTargetMatchesAsASubstring()
	{
		Trigger cloak = Trigger.click("Rub", "Ardougne cloak");

		assertTrue("the diary tier is on the end of the name and should not have to be typed",
			cloak.matches(click("Rub", "Ardougne cloak 4")));
		assertTrue(cloak.matches(click("Rub", "Ardougne cloak 2")));
		assertFalse(cloak.matches(click("Rub", "Karamja gloves 3")));
	}

	@Test
	public void aBlankTargetMatchesAnyTarget()
	{
		Trigger anyTarget = Trigger.click("Mine", "");

		assertTrue(anyTarget.matches(click("Mine", "Iron rocks")));
		assertTrue(anyTarget.matches(click("Mine", "Copper rocks")));
		assertTrue(anyTarget.matches(click("Mine", "")));
		assertFalse("the option still has to match", anyTarget.matches(click("Prospect", "Iron rocks")));
	}

	// Both halves left empty

	@Test
	public void neitherHalfFilledInMatchesNothingAtAll()
	{
		for (Trigger empty : new Trigger[]{
			Trigger.click(null, null),
			Trigger.click("", ""),
			Trigger.click("   ", "\t"),
			Trigger.of(TriggerType.CUSTOM_CLICK)})
		{
			assertFalse("an empty click trigger must not fire on a click",
				empty.matches(click("Use", "Bank chest")));
			assertFalse(empty.matches(click("", "")));
			assertFalse(empty.matches(click("Walk here", "")));
			assertFalse(empty.matches(null));
		}
	}

	/**
	 * The plugin only switches its menu handler on for a kind some clock is
	 * waiting for, so an empty click trigger reports no kind rather than
	 * costing every click in the game a dispatch.
	 */
	@Test
	public void anEmptyClickTriggerWaitsForNoKindOfEvent()
	{
		assertNull(Trigger.click(null, null).kind());
		assertNull(Trigger.click("  ", "  ").kind());
		assertNull(Trigger.nothing().kind());

		assertSame(TriggerEvent.Kind.MENU_CLICK, Trigger.click("Rub", null).kind());
		assertSame(TriggerEvent.Kind.MENU_CLICK, Trigger.click(null, "Bank chest").kind());
		assertSame(TriggerEvent.Kind.ANIMATION, Trigger.of(TriggerType.TELEPORT).kind());
		assertSame(TriggerEvent.Kind.CHAT_MESSAGE, Trigger.of(TriggerType.MINE_IRON).kind());
	}

	// Case and space

	@Test
	public void caseIsIgnoredOnBothHalves()
	{
		Trigger cloak = Trigger.click("rub", "ARDOUGNE CLOAK");

		assertTrue(cloak.matches(click("Rub", "Ardougne cloak 4")));
		assertTrue(cloak.matches(click("RUB", "ardougne cloak 4")));
		assertTrue(Trigger.click("RUB", "ardougne").matches(click("rub", "Ardougne cloak 4")));
	}

	@Test
	public void spaceAroundWhatTheUserTypedIsIgnored()
	{
		assertTrue(Trigger.click("  Rub  ", "  Ardougne cloak  ").matches(click("Rub", "Ardougne cloak 4")));
		assertTrue("and space around what the game sent too",
			Trigger.click("Rub", null).matches(click("  Rub ", "Ardougne cloak 4")));
	}

	// The other kinds of event

	@Test
	public void aClickTriggerIgnoresAnimationsAndChatLines()
	{
		Trigger cloak = Trigger.click("Rub", "Ardougne cloak");

		assertFalse(cloak.matches(TriggerEvent.animation(TeleportAnimations.HUMAN_CASTTELEPORT)));
		assertFalse(cloak.matches(TriggerEvent.chatMessage("Rub Ardougne cloak 4")));
		assertFalse(cloak.matches(null));
	}

	/**
	 * The rule needs the two strings, and the enum member has nowhere to keep
	 * them, so asking it directly has to answer no rather than yes.
	 */
	@Test
	public void theBareEnumMemberCannotDecideAndSaysNo()
	{
		assertFalse(TriggerType.CUSTOM_CLICK.matches(click("Rub", "Ardougne cloak 4")));
		assertFalse(TriggerType.CUSTOM_CLICK.matches(click("", "")));
	}

	// Missing values

	@Test
	public void aMissingTriggerReadsAsNothing()
	{
		assertSame(Trigger.nothing(), Trigger.orNothing(null));
		assertSame(Trigger.nothing(), Trigger.orNothing(Trigger.of(TriggerType.NONE)));
		assertSame(Trigger.nothing(), Trigger.orNothing(Trigger.of(null)));
		assertSame(TriggerType.NONE, Trigger.nothing().getType());
		assertFalse(Trigger.nothing().matches(click("Use", "Bank chest")));
	}

	@Test
	public void aTriggerThatNeedsNothingFilledInStillWorksTheWayItAlwaysDid()
	{
		assertTrue(Trigger.of(TriggerType.BANK_CHEST).matches(click("Use", "Bank chest")));
		assertFalse(Trigger.of(TriggerType.BANK_CHEST).matches(click("Examine", "Bank chest")));
		assertTrue(Trigger.of(TriggerType.TELEPORT)
			.matches(TriggerEvent.animation(TeleportAnimations.HUMAN_CASTTELEPORT)));
		assertTrue(Trigger.of(TriggerType.MINE_IRON)
			.matches(TriggerEvent.chatMessage("You manage to mine some iron.")));
	}

	// What the card reads

	@Test
	public void theCardPhraseSaysWhatWasAskedFor()
	{
		assertEquals("click, Rub: Ardougne cloak 4", Trigger.click("Rub", "Ardougne cloak 4").hint());
		assertEquals("click, Rub", Trigger.click("Rub", "").hint());
		assertEquals("click, anything: Bank chest", Trigger.click("", "Bank chest").hint());
		assertEquals("click, nothing filled in yet", Trigger.click("", "").hint());

		assertEquals("teleporting", Trigger.of(TriggerType.TELEPORT).hint());
		assertEquals("using a bank chest", Trigger.of(TriggerType.BANK_CHEST).hint());
		assertEquals("nothing", Trigger.nothing().hint());
	}

	@Test
	public void twoTriggersAskingForTheSameThingAreTheSameTrigger()
	{
		assertEquals(Trigger.click("Rub", "Ardougne cloak"), Trigger.click(" Rub ", "Ardougne cloak "));
		assertEquals(Trigger.click("Rub", "Ardougne cloak").hashCode(),
			Trigger.click(" Rub ", "Ardougne cloak ").hashCode());

		assertFalse(Trigger.click("Rub", "Ardougne cloak").equals(Trigger.click("Rub", "Karamja gloves")));
		assertFalse(Trigger.click("Rub", null).equals(Trigger.of(TriggerType.TELEPORT)));
		assertFalse(Trigger.nothing().equals(null));
		assertFalse(Trigger.nothing().equals("nothing"));
	}
}

package com.clockwork.core;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The trigger rules, checked without a client.
 *
 * <p>This is the point of putting the matching in core. Every rule below is a
 * pure function of a value, so a near miss can be written down and asserted
 * against rather than discovered in game months later.
 */
public class TriggerTypeTest
{
	private static TriggerEvent bankChest()
	{
		return TriggerEvent.menuClick("Use", "Bank chest");
	}

	private static TriggerEvent minedIron()
	{
		return TriggerEvent.chatMessage("You manage to mine some iron.");
	}

	private static TriggerEvent teleported()
	{
		return TriggerEvent.animation(TeleportAnimations.HUMAN_CASTTELEPORT);
	}

	// Nothing

	@Test
	public void nothingMatchesNothingAtAll()
	{
		assertFalse(TriggerType.NONE.matches(teleported()));
		assertFalse(TriggerType.NONE.matches(bankChest()));
		assertFalse(TriggerType.NONE.matches(minedIron()));
		assertFalse(TriggerType.NONE.matches(TriggerEvent.animation(0)));
		assertFalse(TriggerType.NONE.matches(null));
	}

	@Test
	public void aMissingTriggerReadsAsNothing()
	{
		assertFalse(TriggerType.orNone(null).matches(teleported()));
		assertTrue(TriggerType.NONE == TriggerType.orNone(null));
		assertTrue(TriggerType.TELEPORT == TriggerType.orNone(TriggerType.TELEPORT));
	}

	// Teleporting

	@Test
	public void teleportingMatchesEveryTeleportAnimation()
	{
		for (int id : TeleportAnimations.ids())
		{
			assertTrue("animation " + id + " should read as a teleport",
				TriggerType.TELEPORT.matches(TriggerEvent.animation(id)));
		}
	}

	@Test
	public void teleportingCoversTheSpellbookAndTheTabletAndArceuus()
	{
		assertTrue(TriggerType.TELEPORT.matches(
			TriggerEvent.animation(TeleportAnimations.HUMAN_CASTTELEPORT)));
		assertTrue(TriggerType.TELEPORT.matches(
			TriggerEvent.animation(TeleportAnimations.POH_SMASH_MAGIC_TABLET)));
		assertTrue(TriggerType.TELEPORT.matches(
			TriggerEvent.animation(TeleportAnimations.HUMAN_SPELLCAST_ARCEUUS_TELEPORT)));
	}

	/**
	 * The animation right beside the teleport one is a different spell, and a
	 * rule that matched a range rather than a set would start clocks on it.
	 */
	@Test
	public void teleportingRejectsANeighbouringAnimation()
	{
		assertFalse(TriggerType.TELEPORT.matches(
			TriggerEvent.animation(TeleportAnimations.HUMAN_CASTTELEPORT - 1)));
		assertFalse(TriggerType.TELEPORT.matches(
			TriggerEvent.animation(TeleportAnimations.HUMAN_CASTTELEPORT + 1)));
		assertFalse(TriggerType.TELEPORT.matches(TriggerEvent.animation(-1)));
	}

	@Test
	public void teleportingIgnoresEventsThatAreNotAnimations()
	{
		assertFalse(TriggerType.TELEPORT.matches(bankChest()));
		assertFalse(TriggerType.TELEPORT.matches(minedIron()));
	}

	// Bank chest

	@Test
	public void aBankChestClickMatchesWhateverTheCaseIs()
	{
		assertTrue(TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick("Use", "Bank chest")));
		assertTrue(TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick("Use", "BANK CHEST")));
		assertTrue(TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick("Use", "bank chest")));
	}

	/**
	 * Targets often carry more than the name, such as a level or a place, so
	 * the rule is a contains rather than an equals.
	 */
	@Test
	public void aBankChestClickMatchesInsideALongerTarget()
	{
		assertTrue(TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick("Use", "Bank chest (Castle Wars)")));
	}

	/**
	 * The tags are the plugin's job, and this records what happens if they are
	 * ever left on. A target whose name is broken up by a second colour tag
	 * stops looking like the name at all, which is the failure the stripping in
	 * {@code GameTriggers} exists to prevent.
	 */
	@Test
	public void aTargetLeftWrappedInColourTagsDoesNotMatch()
	{
		assertFalse("stripping the tags is the plugin's job, not the rule's",
			TriggerType.BANK_CHEST.matches(
				TriggerEvent.menuClick("Use", "<col=ff9040>Bank<col=ffffff> chest</col>")));
	}

	@Test
	public void aBankBoothIsNotABankChest()
	{
		assertFalse(TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick("Bank", "Bank booth")));
		assertFalse(TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick("Open", "Chest")));
		assertFalse(TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick("Talk-to", "Banker")));
	}

	/**
	 * The rule used to look at the target alone, so every entry on a bank
	 * chest fired it. Reading the description of a chest is not banking at it,
	 * and a clock that starts or stops because somebody looked at something is
	 * a clock the user cannot trust.
	 */
	@Test
	public void examiningABankChestDoesNotMatch()
	{
		assertFalse("examine is not using the chest",
			TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick("Examine", "Bank chest")));
		assertFalse(TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick("examine", "Bank chest")));
		assertFalse(TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick("EXAMINE", "Bank chest")));
	}

	/**
	 * Chests differ, so the rule accepts a small set rather than one exact
	 * string. Most read Use, some read Bank, the deposit ones read Deposit,
	 * and a few are opened rather than used.
	 */
	@Test
	public void everyWayOfActuallyUsingAChestMatches()
	{
		assertTrue(TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick("Use", "Bank chest")));
		assertTrue(TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick("Bank", "Bank chest")));
		assertTrue(TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick("Open", "Bank chest")));
		assertTrue(TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick("Deposit", "Bank chest")));
	}

	@Test
	public void theOptionIsMatchedWhateverTheCaseAndSpacing()
	{
		assertTrue(TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick("USE", "Bank chest")));
		assertTrue(TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick(" use ", "Bank chest")));
	}

	/**
	 * Anything outside the set, whether it is walking, cancelling, a missing
	 * option, or something the game gains later, does not count as using the
	 * chest.
	 */
	@Test
	public void anythingThatIsNotUsingTheChestDoesNotMatch()
	{
		assertFalse(TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick("Walk here", "Bank chest")));
		assertFalse(TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick("Cancel", "Bank chest")));
		assertFalse(TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick("Look at", "Bank chest")));
		assertFalse(TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick("", "Bank chest")));
		assertFalse(TriggerType.BANK_CHEST.matches(TriggerEvent.menuClick(null, "Bank chest")));
	}

	@Test
	public void aBankChestRuleIgnoresEventsThatAreNotClicks()
	{
		assertFalse(TriggerType.BANK_CHEST.matches(teleported()));
		assertFalse(TriggerType.BANK_CHEST.matches(TriggerEvent.chatMessage("Bank chest")));
	}

	// Mining iron

	@Test
	public void miningIronMatchesTheSuccessMessage()
	{
		assertTrue(TriggerType.MINE_IRON.matches(TriggerEvent.chatMessage("You manage to mine some iron.")));
	}

	/**
	 * Matched as a substring after the opening, so the rule holds whether the
	 * game names the ore "iron" or "iron ore".
	 */
	@Test
	public void miningIronMatchesEitherWordingOfTheOre()
	{
		assertTrue(TriggerType.MINE_IRON.matches(TriggerEvent.chatMessage("You manage to mine some iron ore.")));
		assertTrue(TriggerType.MINE_IRON.matches(TriggerEvent.chatMessage("you manage to mine some IRON.")));
		assertTrue(TriggerType.MINE_IRON.matches(TriggerEvent.chatMessage("  You manage to mine some iron.  ")));
	}

	/**
	 * The near misses. Another ore out of the same sentence, the swing that
	 * comes before the ore, and a sentence that mentions iron without being
	 * the mining message at all.
	 */
	@Test
	public void miningIronRejectsTheMessagesBesideIt()
	{
		assertFalse(TriggerType.MINE_IRON.matches(TriggerEvent.chatMessage("You manage to mine some coal.")));
		assertFalse(TriggerType.MINE_IRON.matches(TriggerEvent.chatMessage("You manage to mine some clay.")));
		assertFalse(TriggerType.MINE_IRON.matches(TriggerEvent.chatMessage("You swing your pickaxe at the rock.")));
		assertFalse(TriggerType.MINE_IRON.matches(TriggerEvent.chatMessage("There is no ore currently available in this rock.")));
		assertFalse(TriggerType.MINE_IRON.matches(TriggerEvent.chatMessage("Iron: you manage to mine some coal.")));
	}

	@Test
	public void miningIronIgnoresEventsThatAreNotMessages()
	{
		assertFalse(TriggerType.MINE_IRON.matches(teleported()));
		assertFalse(TriggerType.MINE_IRON.matches(
			TriggerEvent.menuClick("Mine", "You manage to mine some iron.")));
	}

	// The vocabulary itself

	/**
	 * Every trigger that can fire names the one kind of event it reads, and
	 * nothing else does. That mapping is what lets the plugin switch a whole
	 * handler off, so it is worth pinning.
	 */
	@Test
	public void everyTriggerNamesExactlyOneKindOfEvent()
	{
		assertTrue(TriggerType.NONE.kind() == null);
		assertTrue(TriggerType.TELEPORT.kind() == TriggerEvent.Kind.ANIMATION);
		assertTrue(TriggerType.BANK_CHEST.kind() == TriggerEvent.Kind.MENU_CLICK);
		assertTrue(TriggerType.MINE_IRON.kind() == TriggerEvent.Kind.CHAT_MESSAGE);
		assertTrue(TriggerType.CUSTOM_CLICK.kind() == TriggerEvent.Kind.MENU_CLICK);
	}

	/**
	 * The list is deliberately short. A new member is a decision about what
	 * this plugin is allowed to watch, so it should not be possible to add one
	 * without a test going red and sending the author to read why.
	 *
	 * <p>It has gone from four to five once, on purpose.
	 * {@link TriggerType#CUSTOM_CLICK} lets the user describe the click rather
	 * than pick one this plugin already knows about, which is a wider setting
	 * but not a wider event surface. It reads the same menu clicks the bank
	 * chest trigger already read, and reading the player's own clicks is
	 * precedented. A hub plugin ran the same matcher for two years and was
	 * eventually removed for what it did with the click rather than for reading
	 * it. Nothing here reads another actor, and nothing may.
	 */
	@Test
	public void theVocabularyIsStillTheFiveItWasMeantToBe()
	{
		assertTrue("read the class comment on TriggerType before changing this",
			TriggerType.values().length == 5);
	}

	/**
	 * The other direction, and the one that matters. Every member still reads
	 * one of the three kinds, all of which are the player's own action reported
	 * back to the player. A member built on anything else would be a member
	 * built on another actor.
	 */
	@Test
	public void everyMemberStillReadsOneOfTheThreeAllowedKinds()
	{
		for (TriggerType type : TriggerType.values())
		{
			assertTrue(type + " reads a kind of event that is not one of the three allowed ones",
				type.kind() == null
					|| type.kind() == TriggerEvent.Kind.ANIMATION
					|| type.kind() == TriggerEvent.Kind.MENU_CLICK
					|| type.kind() == TriggerEvent.Kind.CHAT_MESSAGE);
		}
	}
}

package com.clockwork.diag;

import ch.qos.logback.classic.Level;
import com.clockwork.LogCapture;
import java.util.concurrent.atomic.AtomicBoolean;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * The guard the whole plugin is wrapped in.
 *
 * <p>Two things are being held down here. That a failure inside a guarded body
 * does not escape, which is the entire reason the class exists, and that the
 * guard does not shout, because it sits on the refresh tick and anything above
 * debug on a hot path is a plugin hub rejection reason.
 */
public class DiagnosticsTest
{
	private LogCapture logs;

	@Before
	public void setUp()
	{
		logs = new LogCapture();
	}

	@After
	public void tearDown()
	{
		logs.close();
	}

	@Test
	public void aGuardedBodyThatThrowsIsRecordedAndNotRethrown()
	{
		new Diagnostics().guard("panel.rebuild", () ->
		{
			throw new IllegalStateException("the button was pressed");
		});

		assertTrue("the failure was swallowed and then never mentioned, which is the worst of both",
			logs.text().contains("panel.rebuild"));
	}

	@Test
	public void aGuardedBodyThatWorksRunsAndSaysNothing()
	{
		AtomicBoolean ran = new AtomicBoolean();
		new Diagnostics().guard("panel.rebuild", () -> ran.set(true));

		assertTrue(ran.get());
		assertEquals("nothing has gone wrong, so there is nothing to report", "", logs.text());
	}

	@Test
	public void anErrorIsCaughtAsWellAsAnException()
	{
		new Diagnostics().guard("refresh.tick", () ->
		{
			throw new StackOverflowError();
		});

		assertTrue(logs.text().contains("refresh.tick"));
	}

	@Test
	public void aNullBodyIsNotAFailure()
	{
		new Diagnostics().guard("panel.rebuild", null);

		assertEquals("", logs.text());
	}

	/**
	 * The refresh tick runs twenty times a second, so a failure that repeats is
	 * a failure that repeats every frame. Nothing on a hot path may log above
	 * debug.
	 */
	@Test
	public void aGuardedFailureIsWrittenAtDebugAndNoLouder()
	{
		Diagnostics diagnostics = new Diagnostics();
		diagnostics.guard("refresh.tick", () ->
		{
			throw new IllegalStateException("every frame");
		});
		diagnostics.record("refresh.render", new IllegalStateException("every frame"));

		assertEquals("the guard and the throwable form of record both sit on hot paths. Above debug"
				+ " they fill a real user's log twenty times a second",
			Level.DEBUG, logs.loudest());
	}

	/**
	 * The message form is not reached from any repeating path. It is used
	 * where the plugin deliberately drops something the user would expect to
	 * keep, and that is worth saying out loud.
	 */
	@Test
	public void aDeliberateNoticeIsWrittenAtWarn()
	{
		new Diagnostics().record("plugin.profileChanged", "dropping 1 run in progress");

		assertEquals(Level.WARN, logs.loudest());
		assertTrue(logs.text().contains("dropping 1 run in progress"));
	}

	@Test
	public void aNullThrowableAndANullContextAreRecordedRatherThanThrownAt()
	{
		Diagnostics diagnostics = new Diagnostics();
		diagnostics.record(null, (Throwable) null);
		diagnostics.record(null, (String) null);

		assertTrue("a null should still leave a line rather than taking the caller down",
			logs.text().contains("clockwork"));
	}

	/**
	 * The null object. It still swallows, because the guard's job does not
	 * depend on there being anywhere to write.
	 */
	@Test
	public void theEmptyInstanceWritesNothingAndStillSwallowsEverything()
	{
		Diagnostics diagnostics = Diagnostics.none();
		diagnostics.record("refresh.tick", new IllegalStateException("nothing doing"));
		diagnostics.record("refresh.tick", "nothing doing");
		diagnostics.guard("refresh.tick", () ->
		{
			throw new IllegalStateException("nothing doing");
		});

		assertNull(logs.loudest());
	}
}

package com.clockwork.history;

import com.clockwork.core.Lap;
import com.clockwork.core.Run;
import com.clockwork.core.Status;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The shape of one line in the history file.
 *
 * <p>Timestamps are rendered in UTC here rather than in whatever zone the
 * machine running the tests happens to be in, so the expected strings are
 * stable everywhere.
 */
public class HistoryCsvTest
{
	private static final long T0 = 1_700_000_000_000L;
	private static final ZoneId UTC = ZoneOffset.UTC;

	private static Run run(long durationMillis, List<Lap> laps, Status status)
	{
		return new Run(T0, T0 + durationMillis, durationMillis,
			laps == null ? new ArrayList<>() : laps, status);
	}

	@Test
	public void header()
	{
		assertEquals("routine,started_at,finished_at,duration_ms,duration,status,laps", HistoryCsv.HEADER);
	}

	@Test
	public void plainRun()
	{
		String row = HistoryCsv.row("Herb run", run(5_000, null, Status.COMPLETED), UTC);
		assertEquals("Herb run,2023-11-14T22:13:20,2023-11-14T22:13:25,5000,0:05.00,COMPLETED,", row);
		assertEquals("one row is one line", 7, row.split(",", -1).length);
	}

	@Test
	public void lappedRunListsEverySplit()
	{
		List<Lap> laps = Arrays.asList(
			new Lap("Ardougne", 1_000, 1_000),
			new Lap("Catherby", 3_500, 2_500),
			new Lap(null, 4_000, 500));

		String row = HistoryCsv.row("Herb run", run(4_000, laps, Status.COMPLETED), UTC);
		assertEquals("Herb run,2023-11-14T22:13:20,2023-11-14T22:13:24,4000,0:04.00,COMPLETED,1000|3500|4000", row);
	}

	@Test
	public void abandonedRunIsLoggedToo()
	{
		String row = HistoryCsv.row("Herb run", run(3_661_000, null, Status.ABANDONED), UTC);
		assertEquals("Herb run,2023-11-14T22:13:20,2023-11-14T23:14:21,3661000,1:01:01.00,ABANDONED,", row);
	}

	@Test
	public void aNullStatusReadsAsCompletedRatherThanBreakingTheRow()
	{
		String row = HistoryCsv.row("Herb run", run(1_000, null, null), UTC);
		assertTrue(row.endsWith(",COMPLETED,"));
	}

	// Escaping. Routine names are typed by the user, so all of this is reachable.

	@Test
	public void anOrdinaryNameIsNotQuoted()
	{
		assertEquals("Herb run", HistoryCsv.escape("Herb run"));
		assertEquals("", HistoryCsv.escape(null));
		assertEquals("", HistoryCsv.escape(""));
	}

	@Test
	public void aCommaInTheNameIsQuoted()
	{
		assertEquals("\"Herbs, then birdhouses\"", HistoryCsv.escape("Herbs, then birdhouses"));

		String row = HistoryCsv.row("Herbs, then birdhouses", run(5_000, null, Status.COMPLETED), UTC);
		assertEquals("\"Herbs, then birdhouses\",2023-11-14T22:13:20,2023-11-14T22:13:25,5000,0:05.00,COMPLETED,",
			row);
	}

	@Test
	public void aQuoteInTheNameIsDoubledAndQuoted()
	{
		assertEquals("\"The \"\"quick\"\" run\"", HistoryCsv.escape("The \"quick\" run"));
	}

	@Test
	public void aNewlineInTheNameIsQuoted()
	{
		assertEquals("\"two\nlines\"", HistoryCsv.escape("two\nlines"));
		assertEquals("\"two\r\nlines\"", HistoryCsv.escape("two\r\nlines"));
	}

	@Test
	public void aNameWithAllThreeSurvivesTogether()
	{
		String name = "Herbs, \"fast\"\nrun";
		assertEquals("\"Herbs, \"\"fast\"\"\nrun\"", HistoryCsv.escape(name));

		String row = HistoryCsv.row(name, run(5_000, null, Status.COMPLETED), UTC);
		assertTrue(row.startsWith("\"Herbs, \"\"fast\"\"\nrun\","));
		assertTrue(row.endsWith(",5000,0:05.00,COMPLETED,"));
	}
}

package com.clockwork.history;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/**
 * Appending to the log, and what happens when the disk will not have it.
 */
public class HistoryFileTest
{
	@Rule
	public final TemporaryFolder folder = new TemporaryFolder();

	private static List<String> lines(File file) throws IOException
	{
		return Files.readAllLines(file.toPath(), StandardCharsets.UTF_8);
	}

	@Test
	public void theHeaderIsWrittenWhenTheFileIsCreated() throws IOException
	{
		File target = new File(folder.getRoot(), "history.csv");
		HistoryFile file = new HistoryFile(target);

		assertFalse(file.exists());
		assertTrue(file.append("Herb run,a,b,1,2,COMPLETED,"));
		assertTrue(file.exists());

		List<String> lines = lines(target);
		assertEquals(2, lines.size());
		assertEquals(HistoryCsv.HEADER, lines.get(0));
		assertEquals("Herb run,a,b,1,2,COMPLETED,", lines.get(1));
	}

	@Test
	public void theHeaderIsNotWrittenAgainOnAppend() throws IOException
	{
		File target = new File(folder.getRoot(), "history.csv");
		HistoryFile file = new HistoryFile(target);

		file.append("one");
		file.append("two");
		file.append("three");

		List<String> lines = lines(target);
		assertEquals(4, lines.size());
		assertEquals(HistoryCsv.HEADER, lines.get(0));
		assertEquals("one", lines.get(1));
		assertEquals("two", lines.get(2));
		assertEquals("three", lines.get(3));
	}

	/**
	 * A fresh instance pointed at a file somebody already has must add to it
	 * rather than start it over, because the file is the permanent record.
	 */
	@Test
	public void aSecondSessionAddsToTheFileItFinds() throws IOException
	{
		File target = new File(folder.getRoot(), "history.csv");
		new HistoryFile(target).append("first session");
		new HistoryFile(target).append("second session");

		List<String> lines = lines(target);
		assertEquals(3, lines.size());
		assertEquals(HistoryCsv.HEADER, lines.get(0));
		assertEquals("second session", lines.get(2));
	}

	@Test
	public void theFolderIsCreatedIfItIsNotThere() throws IOException
	{
		File target = new File(new File(folder.getRoot(), "clockwork"), "history.csv");
		assertFalse(target.getParentFile().exists());

		assertTrue(new HistoryFile(target).append("Herb run,a,b,1,2,COMPLETED,"));
		assertTrue(target.getParentFile().isDirectory());
		assertEquals(2, lines(target).size());
	}

	@Test
	public void deletingLeavesNoFileAndTheNextRunStartsANewOne() throws IOException
	{
		File target = new File(folder.getRoot(), "history.csv");
		HistoryFile file = new HistoryFile(target);
		file.append("one");

		assertTrue(file.delete());
		assertFalse(target.exists());
		assertFalse(file.exists());

		file.append("two");
		List<String> lines = lines(target);
		assertEquals(2, lines.size());
		assertEquals(HistoryCsv.HEADER, lines.get(0));
		assertEquals("two", lines.get(1));
	}

	@Test
	public void deletingWhenThereIsNoFileIsNotAFailure()
	{
		HistoryFile file = new HistoryFile(new File(folder.getRoot(), "never-written.csv"));
		assertTrue(file.delete());
		assertNull(file.getNotice());
	}

	/**
	 * The target is put inside something that is a file rather than a folder,
	 * so the write cannot possibly succeed. A run ending is not the moment to
	 * throw, so the caller gets a false and a notice instead.
	 */
	@Test
	public void anUnwritableTargetDoesNotThrowAtTheCaller() throws IOException
	{
		File blocker = folder.newFile("not-a-folder");
		File target = new File(blocker, "history.csv");

		HistoryFile file = new HistoryFile(target);
		assertFalse(file.append("Herb run,a,b,1,2,COMPLETED,"));

		assertNotNull("the panel needs something to show", file.getNotice());
		assertTrue(file.getNotice().contains("history.csv"));
		assertFalse(target.exists());

		// And it still does not throw the second time, or on a delete.
		assertFalse(file.append("another"));
		file.delete();
	}

	@Test
	public void aGoodWriteAfterABadOneClearsTheNotice() throws IOException
	{
		File blocker = folder.newFile("blocker");
		HistoryFile file = new HistoryFile(new File(blocker, "history.csv"));
		assertFalse(file.append("one"));
		assertNotNull(file.getNotice());

		file.setTarget(new File(folder.getRoot(), "history.csv"));
		assertNull("moving the file is a fresh start", file.getNotice());

		assertTrue(file.append("two"));
		assertNull(file.getNotice());
		assertEquals(2, lines(file.getTarget()).size());
	}

	@Test
	public void aNullRowIsIgnored()
	{
		HistoryFile file = new HistoryFile(new File(folder.getRoot(), "history.csv"));
		assertFalse(file.append(null));
		assertFalse(file.exists());
	}

	@Test
	public void aNullTargetIsIgnored()
	{
		HistoryFile file = new HistoryFile(null);
		assertFalse(file.append("one"));
		assertFalse(file.delete());
		assertFalse(file.exists());
	}
}

package com.clockwork.ui;

import com.clockwork.DocumentProblem;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The wording the panel shows back to the user, and the decisions behind it.
 *
 * <p>The widgets themselves are not tested and cannot usefully be. What can be
 * tested is what they say and when they stop to ask, which is the part that
 * costs somebody their run history when it is wrong. So both live in
 * {@link PanelMessages}, which holds no Swing and no state, and both are checked
 * here.
 *
 * <p>No reflection anywhere in this file, and none in the class under test.
 */
public class PanelMessagesTest
{
	private static final List<String> NONE = Collections.emptyList();

	private static final List<DocumentProblem> NO_PROBLEMS = Collections.emptyList();

	// Counting

	@Test
	public void oneClockIsSingular()
	{
		assertEquals("1 clock", PanelMessages.clocks(1));
	}

	@Test
	public void anythingElseIsPlural()
	{
		assertEquals("0 clocks", PanelMessages.clocks(0));
		assertEquals("2 clocks", PanelMessages.clocks(2));
		assertEquals("11 clocks", PanelMessages.clocks(11));
	}

	@Test
	public void oneProblemIsSingular()
	{
		assertEquals("1 problem", PanelMessages.problems(1));
		assertEquals("0 problems", PanelMessages.problems(0));
		assertEquals("4 problems", PanelMessages.problems(4));
	}

	// Saying what is wrong with a document

	private static final DocumentProblem BAD_MODE =
		DocumentProblem.inField(3, "Zulrah trips", "mode", "expected countdown or countup, found \"countup!\"");

	private static final DocumentProblem SKIPPED =
		DocumentProblem.skippedClock(5, "Wine run", "targetMillis",
			"expected a number, found \"soon\", so this clock was skipped");

	private static final DocumentProblem SYNTAX =
		DocumentProblem.at(14, 3, "a value was expected here");

	@Test
	public void aProblemListIsOneProblemToALine()
	{
		assertEquals("Clock 3 \"Zulrah trips\", field mode: expected countdown or countup, found \"countup!\"\n"
				+ "Clock 5 \"Wine run\", field targetMillis: expected a number, found \"soon\","
				+ " so this clock was skipped",
			PanelMessages.problemLines(Arrays.asList(BAD_MODE, SKIPPED)));
	}

	@Test
	public void anEmptyProblemListSaysNothingAtAll()
	{
		assertEquals("", PanelMessages.problemLines(null));
		assertEquals("", PanelMessages.problemLines(Collections.emptyList()));
		assertEquals("", PanelMessages.problemHtml(Collections.emptyList()));
	}

	/**
	 * A document pasted from the wrong place can have a problem on every line
	 * of it, and the box under the editor is three rows tall. The count above
	 * the list is never capped, so nothing is hidden.
	 */
	@Test
	public void aVeryLongProblemListSaysHowManyMoreThereAre()
	{
		final List<DocumentProblem> many = new ArrayList<>();
		for (int number = 1; number <= 10; number++)
		{
			many.add(DocumentProblem.inClock(number, "Clock " + number, "something"));
		}

		final String said = PanelMessages.problemLines(many);
		assertEquals(7, said.split("\n").length);
		assertTrue(said, said.endsWith("and 4 more."));
		assertTrue("the count is of all of them", PanelMessages.refusal(many).contains("10 problems"));
	}

	@Test
	public void aProblemInADialogIsEscapedLikeEverythingElse()
	{
		final String html = PanelMessages.problemHtml(Collections.singletonList(
			DocumentProblem.inClock(1, "<b>Herb</b>", "something")));

		assertFalse(html, html.contains("<b>"));
		assertTrue(html, html.contains("&lt;b&gt;Herb&lt;/b&gt;"));
	}

	/**
	 * One problem about the whole document is already a whole sentence, so it
	 * is left to speak for itself rather than wrapped in a count of one.
	 */
	@Test
	public void oneWholeDocumentProblemIsTheWholeMessage()
	{
		final String only = "There is nothing to read. Paste a Clockwork document first.";
		assertEquals(only, PanelMessages.refusal(
			Collections.singletonList(DocumentProblem.inDocument(only))));
	}

	@Test
	public void aRefusalCountsWhatItFoundAndGetsThePluralRight()
	{
		assertTrue(PanelMessages.refusal(Collections.singletonList(SYNTAX))
			.startsWith("That document could not be read. 1 problem was found."));
		assertTrue(PanelMessages.refusal(Arrays.asList(SYNTAX, BAD_MODE))
			.startsWith("That document could not be read. 2 problems were found."));
		assertEquals(PanelMessages.REFUSED, PanelMessages.refusal(Collections.emptyList()));
	}

	@Test
	public void aRefusalInTheSidePanelIsOneLine()
	{
		assertEquals("the sidebar has room for one line, and one problem fits in it",
			SYNTAX.describe(), PanelMessages.refusalLine(Collections.singletonList(SYNTAX)));
		assertEquals("That document could not be read. 2 problems were found.",
			PanelMessages.refusalLine(Arrays.asList(SYNTAX, BAD_MODE)));
	}

	/**
	 * The headline is the answer to the only question the user has, which is
	 * how much of their document is going to arrive. A clock that will not
	 * arrive and a field spelled wrong are different news and are counted
	 * differently.
	 */
	@Test
	public void aHeadlineSaysWhatArrivesAndWhatDoesNot()
	{
		assertEquals("Add 3 clocks from the clipboard.",
			PanelMessages.importHeadline(3, NO_PROBLEMS));
		assertEquals("Add 3 clocks from the clipboard. 1 problem was found.",
			PanelMessages.importHeadline(3, Collections.singletonList(BAD_MODE)));
		assertEquals("Add 3 clocks from the clipboard. 1 was skipped.",
			PanelMessages.importHeadline(3, Arrays.asList(BAD_MODE, SKIPPED)));
		assertEquals("Add 1 clock from the clipboard. 2 were skipped.",
			PanelMessages.importHeadline(1, Arrays.asList(SKIPPED, SKIPPED)));
		assertEquals("No clocks will be added. 1 was skipped.",
			PanelMessages.importHeadline(0, Collections.singletonList(SKIPPED)));
	}

	@Test
	public void anEditHeadlineCountsTheListAsItWouldStand()
	{
		assertEquals("4 clocks will be applied. 1 was skipped.",
			PanelMessages.editHeadline(4, Collections.singletonList(SKIPPED)));
		assertEquals("1 clock will be applied.", PanelMessages.editHeadline(1, NO_PROBLEMS));
	}

	/**
	 * A document with something wrong in it is worth stopping for even when
	 * nothing would be removed, because the alternative is a button that
	 * quietly drops a clock and mentions it afterwards.
	 */
	@Test
	public void problemsAreWorthStoppingForOnTheirOwn()
	{
		final PanelMessages.Confirm confirm = PanelMessages.importConfirm(
			2, Collections.singletonList(SKIPPED));

		assertTrue(confirm.isNeeded());
		assertTrue(confirm.getMessage(), confirm.getMessage().contains("1 was skipped"));
		assertTrue(confirm.getMessage(), confirm.getMessage().contains("field targetMillis"));

		final PanelMessages.Confirm edit = PanelMessages.editConfirm(NONE, NONE, NONE,
			Collections.singletonList(SKIPPED), 4);
		assertTrue("nothing is removed and it still asks", edit.isNeeded());
		assertTrue(edit.getMessage(), edit.getMessage().contains("4 clocks will be applied"));
		assertTrue(edit.getMessage(), edit.getMessage().contains("Nothing has happened to your clocks yet"));

		assertFalse("a document with nothing wrong and nothing removed still goes straight through",
			PanelMessages.editConfirm(NONE, NONE, NONE, NO_PROBLEMS, 4).isNeeded());
	}

	@Test
	public void aRemovalConfirmStillCarriesTheProblems()
	{
		final PanelMessages.Confirm confirm = PanelMessages.editConfirm(
			Collections.singletonList("Zulrah"), NONE, NONE,
			Collections.singletonList(BAD_MODE), 3);

		assertTrue(confirm.getMessage(), confirm.getMessage().contains("1 clock will be removed"));
		assertTrue(confirm.getMessage(), confirm.getMessage().contains("field mode"));
	}

	@Test
	public void aSummarySaysWhatWasSkipped()
	{
		assertEquals("3 clocks added. 1 was skipped.",
			PanelMessages.summariseImport(3, NONE, Collections.singletonList(SKIPPED)));
		assertEquals("3 clocks added. 2 were skipped.",
			PanelMessages.summariseImport(3, NONE, Arrays.asList(SKIPPED, SKIPPED)));
		assertEquals("a spelling nobody can act on does not belong on a status line",
			"3 clocks added.", PanelMessages.summariseImport(3, NONE, Collections.singletonList(BAD_MODE)));
		assertEquals("Applied. 4 clocks, nothing added or removed. 1 was skipped.",
			PanelMessages.summariseEdit(4, 0, 0, NONE, Collections.singletonList(SKIPPED)));
	}

