	@Test
	public void anEditThatRemovesClocksNamesEveryOneOfThem()
	{
		final PanelMessages.Confirm confirm =
			PanelMessages.editConfirm(Arrays.asList("Zulrah", "Vorkath"), NONE, NONE);

		assertTrue(confirm.isNeeded());
