	@Test
	public void anEditThatRemovesClocksSaysTheHistoryGoesWithThem()
	{
		final String message =
			PanelMessages.editConfirm(Collections.singletonList("Zulrah"), NONE, NONE).getMessage();

		assertTrue("a generic are you sure would not tell anybody what they are about to lose",
			message.contains("run history with it"));
