	@Test
	public void aRemovalBesideAnAdditionExplainsTheRenameTrap()
	{
		final PanelMessages.Confirm confirm = PanelMessages.editConfirm(
			Collections.singletonList("Zulrah"), Collections.singletonList("Zulrah trips"), NONE);

		final String message = confirm.getMessage();
		assertTrue(message.contains("Zulrah trips"));
		assertTrue("a rename reads as one removal and one addition, and that has to be legible",
			message.contains("renamed"));
		assertTrue("the way out of the trap is the panel's own rename",
			message.contains("... menu"));
	}

