	{
		assertNull(PanelMessages.keptCustomTriggers(null));
		assertNull(PanelMessages.keptCustomTriggers(Collections.emptyList()));
		assertNull("a blank name is not something saved",
			PanelMessages.keptCustomTriggers(Arrays.asList("", "   ")));
	}

	@Test
	public void cancellingAfterSavingOneNamesItAndSaysWhereItWent()
	{
		final String said = PanelMessages.keptCustomTriggers(Collections.singletonList("Note herbs"));

		assertTrue(said, said.contains("Note herbs was saved."));
		assertTrue("the clock is the thing that was cancelled, and that should be plain",
			said.contains("Cancelling left the clock alone"));
		assertTrue("and it has to say where to find it",
			said.contains("under Custom triggers in the side panel"));
	}

	@Test
	public void cancellingAfterSavingSeveralReadsAsASentence()
	{
		final String said = PanelMessages.keptCustomTriggers(
			Arrays.asList("Note herbs", "Bank it", "Rub the cloak"));

		assertTrue(said, said.contains("Note herbs, Bank it and Rub the cloak were saved."));
		assertTrue(said, said.contains("triggers you defined are kept"));
		assertTrue(said, said.contains("point any clock at them."));
	}

	/**
	 * The names come out of a box the user typed into, and they land inside
	 * html, so anything in one that looks like a tag has to stop looking like
	 * one first.
	 */
	@Test
	public void aSavedNameIsEscapedLikeEveryOtherNameShownBack()
	{
		final String said = PanelMessages.keptCustomTriggers(
			Collections.singletonList("<b>Note herbs</b>"));

		assertTrue(said, said.contains("&lt;b&gt;Note herbs&lt;/b&gt;"));
	}

